export const FOCUS_COMPANION_ENTRY_HTML = [
  "<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>角色陪伴专注</title>\n<style>\n:root{--bg:#0c0f16;--card:rgba(255,255,255,.045);--card2:rgba(255,255,255,.07);--line:rgba(255,255,255,.09);\n--text:#e8ecf5;--dim:#8b97ad;--dim2:#5f6b80;--accent:#7c8cff;--accent-soft:rgba(124,140,255,.18);\n--teal:#5eead4;--warn:#ff7b8a;--warn-soft:rgba(255,123,138,.14);--gold:#ffc978;--radius:16px;\n--sp-1:4px;--sp-2:8px;--sp-3:12px;--sp-4:16px;\n--surface:var(--bg);--surface-2:var(--card);--on-surface:var(--text);--on-surface-2:var(--dim);--on-surface-3:var(--dim2);--primary:var(--accent);--primary-soft:var(--accent-soft)}\n*{box-sizing:border-box;-webkit-tap-highlight-color:transparent}\nhtml,body{width:100%;min-height:100%;margin:0}\nbody{background:var(--bg);color:var(--text);overflow-x:hidden;\nfont:14px/1.6 -apple-system,BlinkMacSystemFont,\"PingFang SC\",\"Hiragino Sans GB\",\"Microsoft YaHei\",sans-serif}\nbody.sleep-theme{background:#080a14;--accent:#a58bff;--accent-soft:rgba(165,139,255,.16);--teal:#8fd8e8}\nbutton,input,textarea,select{font:inherit;color:inherit}\nbutton{min-height:44px;cursor:pointer}\nbutton:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:2px}\n::-webkit-scrollbar{width:0;height:0}\n.app{min-height:100dvh;padding:0 15px var(--ai-phone-app-safe-bottom,26px);position:relative;z-index:1}\n.topbar{position:fixed;top:var(--ai-phone-app-bar-top,54px);left:15px;right:var(--ai-phone-app-bar-clear-right,96px);\nmin-height:var(--ai-phone-app-bar-height,30px);z-index:20;pointer-events:none;display:flex;gap:9px;align-items:flex-start}\n.topbar .t1{font-size:19px;font-weight:700;letter-spacing:.3px;line-height:1.25}\n.topbar .t2{font-size:11.5px;color:var(--dim2);letter-spacing:.6px;margin-top:1px}\n.navback{pointer-events:auto;width:34px;height:34px;min-height:34px;flex:0 0 34px;border-radius:11px;border:1px solid var(--line);\nbackground:rgba(255,255,255,.07);color:var(--text);display:grid;place-items:center;font-size:19px;line-height:1;padding:0}\n.navback:active{background:rgba(255,255,255,.14)}\n#view{padding-top:calc(var(--ai-phone-app-bar-top,54px) + 58px);padding-bottom:112px}\n.tabbar{position:fixed;left:0;right:0;bottom:0;z-index:30;display:flex;align-items:stretch;\npadding:6px 8px calc(var(--ai-phone-app-safe-bottom,20px));backdrop-filter:blur(14px);\nbackground:linear-gradient(180deg,rgba(10,13,20,.4),rgba(10,13,20,.92) 45%);border-top:1px solid var(--line)}\n.tabbar .tab{flex:1;background:none;border:0;color:var(--dim2);display:flex;flex-direction:column;align-items:center;gap:2px;\npadding:4px 0;font-size:10.5px;min-height:auto;border-radius:12px}\n.tabbar .tab .ic{font-size:19px;line-height:1}\n.tabbar .tab.on{color:var(--text)}\n.tabbar .tab.on .ic{filter:drop-shadow(0 0 8px var(--accent))}\n.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);padding:14px;margin-bottom:12px}\n.card.tight{padding:11px}\n.card.glow{border-color:var(--accent-soft);box-shadow:0 0 0 1px rgba(124,140,255,.08),0 8px 30px -18px var(--accent)}\n.card h3{margin:0 0 4px;font-size:14.5px;font-weight:700;letter-spacing:.2px}\n.card .sub{font-size:12px;color:var(--dim2);line-height:1.55}\n.row{display:flex;align-items:center;gap:10px}\n.row.between{justify-content:space-between}\n.row.wrap{flex-wrap:wrap}\n.grow{flex:1;min-width:0}\n.mt6{margin-top:6px}.mt8{margin-top:var(--sp-2)}.mt10{margin-top:10px}.mt12{margin-top:var(--sp-3)}.mt14{margin-top:14px}\n.center{text-align:center}.ellip{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.tiny{font-size:11px;color:var(--dim2);line-height:1.65}\n.tiny b{font-weight:600;color:var(--dim)}\n.empty{text-align:center;color:var(--dim2);font-size:12.5px;padding:26px 10px;line-height:1.8}\n.hr{height:1px;background:var(--line);margin:12px 0}\n.kv{display:flex;justify-content:space-between;gap:10px;font-size:12.5px;padding:6px 0}\n.kv .k{color:var(--dim2)}\n.btn{border:1px solid var(--line);background:var(--card2);color:var(--text);border-radius:12px;padding:0 14px;min-height:44px;\ndisplay:inline-flex;align-items:center;justify-content:center;gap:6px;font-size:14px;transition:.15s;white-space:nowrap}\n.btn:active{transform:scale(.97)}\n.btn.primary{background:linear-gradient(135deg,#7c8cff,#9a7cff);border-color:transparent;color:#fff;font-weight:600}\n.btn.teal{background:linear-gradient(135deg,#3ddad0,#4fb3ff);border-color:transparent;color:#062026;font-weight:600}\n.btn.warn{background:var(--warn-soft);border-color:rgba(255,123,138,.4);color:#ffb3bd}\n.btn.sleep{background:linear-gradient(135deg,#6d5bd0,#4a3f8f);border-color:transparent;color:#fff;font-weight:600}\n.btn.ghost{background:transparent}\n.btn.sm{min-height:34px;font-size:12.5px;padding:0 11px;border-radius:10px}\n.btn.block{width:100%}\n.btn:disabled{opacity:.45}\nlabel.fl{display:block;font-size:12px;color:var(--dim);margin:10px 0 5px}\n.input,textarea{width:100%;background:rgba(255,255,255,.05);border:1px solid var(--line);border-radius:12px;\npadding:11px 12px;font-size:14px;outline:none}\n.input:focus,textarea:focus{border-color:var(--accent)}\ntextarea{min-height:76px;resize:vertical;line-height:1.6}\ninput[type=range]{width:100%;accent-color:var(--accent)}\n.chips{display:flex;flex-wrap:wrap;gap:7px}\n.chip{border:1px solid var(--line);background:rgba(255,255,255,.04);border-radius:999px;padding:7px 12px;font-size:12.5px;color:var(--dim)}\n.chip.on{background:var(--accent-soft);border-color:rgba(124,140,255,.55);color:#fff;font-weight:600}\n.pill{display:inline-flex;align-items:center;gap:4px;font-size:11px;padding:3px 9px;border-radius:999px;background:var(--card2);color:var(--dim)}\n.pill.ok{background:rgba(94,234,212,.14);color:var(--teal)}\n.pill.bad{background:var(--warn-soft);color:#ff9aa6}\n.pill.warn{background:rgba(255,201,120,.14);color:var(--gold)}\n.pill.run{background:var(--accent-soft);color:#b9c2ff}\n.avatar{width:38px;height:38px;border-radius:12px;flex:0 0 38px;display:grid;place-items:center;font-size:15px;font-weight:700;color:#fff;overflow:hidden}\n.avatar.lg{width:54px;height:54px;flex:0 0 54px;font-size:20px;border-radius:16px}\n.avatar img{width:100%;height:100%;object-fit:cover}\n.bd{font-size:13.5px;line-height:1.62;word-break:break-word}\n.msg{display:flex;gap:8px;margin-bottom:11px;align-items:flex-start}\n.msg .bd{background:var(--card2);border-radius:13px;padding:9px 12px;max-width:80%}\n.msg .bd .who{font-size:10.5px;color:var(--dim2);margin-bottom:2px}\n.msg.me{flex-direction:row-reverse}\n.msg.me .bd{background:var(--accent-soft)}\n.msg.sys{justify-content:center}\n.msg.sys .bd{background:transparent;color:var(--dim2);font-size:11.5px;max-width:92%;text-align:center;padding:2px}\n.msg .bd .vbar{display:flex;gap:6px;margin-top:6px}\n.msg .bd .vbar button{min-height:26px;padding:0 9px;font-size:11px;border-radius:8px;border:1px solid var(--line);\nbackground:rgba(255,255,255,.06);color:var(--dim);display:inline-flex;align-items:center;gap:4px}\n.msg .bd .vbar button.on{background:var(--accent-soft);border-color:rgba(124,140,255,.55);color:#dfe4ff}\n.ringwrap{display:grid;place-items:center;margin:8px 0 4px}\n.ring{width:min(66vw,236px);aspect-ratio:1;border-radius:50%;position:relative;display:grid;place-items:center;\nbackground:conic-gradient(var(--accent) calc(var(--p,0) * 1%), rgba(255,255,255,.06) 0);transition:background .6s linear}\n.ring.paused{background:conic-gradient(var(--gold) calc(var(--p,0) * 1%), rgba(255,255,255,.06) 0)}\n.ring::after{content:\"\";position:absolute;inset:11px;border-radius:50%;background:#0d111c}\n.ring .core{position:relative;z-index:1;text-align:center}\n.ring .t{font-size:40px;font-weight:300;letter-spacing:1px;font-variant-numeric:tabular-nums}\n.ring .s{font-size:11.5px;color:var(--dim2);margin-top:2px}\n.bar{height:7px;border-radius:99px;background:rgba(255,255,255,.08);overflow:hidden}\n.bar>i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#7c8cff,#5eead4);transition:width .4s}\n.bar.warn>i{background:linear-gradient(90deg,#ff7b8a,#ffb37a)}\n.bars{display:flex;align-items:flex-end;gap:7px;height:118px;margin-top:6px}\n.bars .col{flex:1;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:5px;height:100%}\n.bars .bg{width:100%;border-radius:7px 7px 3px 3px;background:linear-gradient(180deg,#7c8cff,#5eead4);min-height:4px}\n.bars .bg.sleep{background:linear-gradient(180deg,#a58bff,#5a6fd0)}\n.bars .lb{font-size:10px;color:var(--dim2)}\n.bars .vl{font-size:10px;color:var(--dim)}\n.cal{display:grid;grid-template-columns:repeat(7,1fr);gap:5px}\n.cal .wd{font-size:10.5px;color:var(--dim2);text-align:center;padding:2px 0}\n.cal .d{aspect-ratio:1;border-radius:10px;display:grid;place-items:center;font-size:12px;background:rgba(255,255,255,.035);color:var(--dim);position:relative}\n.cal .d.ok{background:linear-gradient(140deg,#7c8cff,#5eead4);color:#08131c;font-weight:700}\n.cal .d.part{background:rgba(124,140,255,.3);color:#dfe3ff}\n.cal .d.today{outline:1.5px solid var(--accent);outline-offset:-1.5px}\n.cal .d.blank{background:transparent}\n.item{display:flex;gap:10px;align-items:flex-start;padding:11px 0;border-bottom:1px solid var(--line)}\n.item:last-child{border-bottom:0}\n.item .ic{font-size:17px;flex:0 0 22px;text-align:center;line-height:1.5}\n.todo{display:flex;gap:10px;align-items:flex-start;padding:10px;border-radius:12px;background:rgba(255,255,255,.035);margin-bottom:7px}\n.todo .ck{width:23px;height:23px;flex:0 0 23px;border-radius:8px;border:1.5px solid var(--line);background:rgba(255,255,255,.04);\ndisplay:grid;place-items:center;font-size:13px;min-height:auto;padding:0;color:transparent}\n.todo .ck.on{background:linear-gradient(135deg,#7c8cff,#5eead4);border-color:transparent;color:#07141b}\n.todo .tx{flex:1;min-width:0;font-size:13.5px;line-height:1.5}\n.todo .tx .meta{font-size:11px;color:var(--dim2);margin-top:2px}\n.todo.done .tx{color:var(--dim2);text-decoration:line-through}\n.mask{position:fixed;inset:0;background:rgba(4,6,11,.72);backdrop-filter:blur(6px);z-index:80;display:flex;align-items:flex-end;justify-content:center}\n.sheet{width:100%;max-height:88dvh;overflow:auto;background:#131826;border-radius:22px 22px 0 0;border-top:1px solid var(--line);\npadding:18px 16px calc(var(--ai-phone-app-safe-bottom,20px) + 14px);animation:up .22s ease}\n@keyframes up{from{transform:translateY(22px);opacity:.4}to{transform:none;opacity:1}}\n.sheet h3{margin:0 0 10px;font-size:16px}\n.modal-center{align-items:center;padding:20px}\n.modal-center .sheet{border-radius:20px;max-width:440px;animation:pop .2s ease}\n@keyframes pop{from{transform:scale(.94);opacity:.3}to{transform:none;opacity:1}}\n.lock{position:fixed;inset:0;background:#080a12;z-index:70;overflow-y:auto;\npadding:calc(var(--ai-phone-app-safe-top,74px) + 8px) 16px calc(var(--ai-phone-app-safe-bottom,24px) + 20px)}\n.lock .skull{font-size:46px;text-align:center;line-height:1.1}\n#toastHost{position:fixed;left:0;right:0;bottom:calc(var(--ai-phone-app-safe-bottom,20px) + 84px);z-index:90;display:flex;flex-direction:column;align-items:center;gap:8px;pointer-events:none}\n.toast{background:rgba(28,34,50,.96);border:1px solid var(--line);color:var(--text);padding:10px 15px;border-radius:12px;font-size:13px;max-width:84vw}\n.q{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:13px;margin-bottom:11px}\n.q .qt{font-size:13.8px;line-height:1.6;margin-bottom:9px}\n.q .opts{display:flex;flex-direction:column;gap:7px}\n.opt{text-align:left;background:rgba(255,255,255,.04);border:1px solid var(--line);border-radius:11px;padding:10px 12px;\nfont-size:13px;min-height:44px;display:flex;gap:8px;align-items:center;width:100%}\n.opt .k{width:20px;height:20px;flex:0 0 20px;border-radius:6px;background:rgba(255,255,255,.08);display:grid;place-items:center;font-size:11px;color:var(--dim)}\n.opt.on{border-color:var(--accent);background:var(--accent-soft)}\n.opt.on .k{background:var(--accent);color:#fff}\n.opt.right{border-color:rgba(94,234,212,.6);background:rgba(94,234,212,.12)}\n.opt.wrong{border-color:rgba(255,123,138,.55);background:var(--warn-soft)}\n.exp{font-size:11.5px;color:var(--dim);margin-top:8px;line-height:1.6;border-left:2px solid var(--line);padding-left:8px}\n.story{font-size:14.5px;line-height:2;color:#d8ddf2}\n.story p{margin:0 0 14px}\n.story p.playing{color:#fff;text-shadow:0 0 18px rgba(165,139,255,.45)}\n.spin{width:15px;height:15px;border:2px solid rgba(255,255,255,.25);border-top-color:#fff;border-radius:50%;display:inline-block;animation:sp .7s linear infinite;vertical-align:-2px}\n@keyframes sp{to{transform:rotate(360deg)}}\n.wall{position:fixed;inset:0;z-index:0;background-size:cover;background-position:center;opacity:.62}\n.wall::after{content:\"\";position:absolute;inset:0;background:linear-gradient(180deg,rgba(7,9,16,.5),rgba(7,9,16,.9))}\n.wall.sleep{opacity:.72}\n.wall.sleep::after{background:linear-gradient(180deg,rgba(6,8,18,.42),rgba(6,8,18,.88) 62%,rgba(6,8,18,.96))}\n.floatbar{position:fixed;left:12px;right:12px;bottom:calc(var(--ai-phone-app-safe-bottom,20px) + 68px);z-index:26;\nbackground:rgba(20,25,38,.95);border:1px solid var(--line);border-radius:15px;padding:9px 11px;display:flex;gap:9px;align-items:center;backdrop-filter:blur(14px)}\n.floatbar .fx{flex:1;min-width:0;font-size:12.8px;line-height:1.45;max-height:2.9em;overflow:hidden}\n.floatbar .who2{font-size:10px;color:var(--dim2);margin-bottom:1px}\n.floatbar .mini{width:32px;height:32px;min-height:32px;flex:0 0 32px;border-radius:10px;border:1px solid var(--line);\nbackground:rgba(255,255,255,.06);display:grid;place-items:center;font-size:14px;padding:0}\n.nowtask{border-radius:15px;padding:13px;background:linear-gradient(135deg,rgba(124,140,255,.2),rgba(94,234,212,.08));border:1px solid rgba(124,140,255,.35)}\n.nowtask .lbl{font-size:10.5px;color:#b9c2ff;letter-spacing:1px}\n.nowtask .tx{font-size:15.5px;font-weight:600;margin-top:4px;line-height:1.45}\n.nexttask{border-radius:13px;padding:11px 13px;background:rgba(255,255,255,.04);border:1px solid var(--line)}\n.nexttask .lbl{font-size:10.5px;color:var(--dim2);letter-spacing:1px}\n.nexttask .tx{font-size:13.5px;margin-top:3px;color:var(--dim)}\n.invite-hero{border-radius:18px;padding:16px;margin-bottom:12px;border:1px solid rgba(124,140,255,.35);\nbackground:linear-gradient(150deg,rgba(124,140,255,.22),rgba(94,234,212,.08))}\n.invite-hero.sleep{border-color:rgba(165,139,255,.4);background:linear-gradient(150deg,rgba(165,139,255,.26),rgba(124,140,255,.1))}\n/* ===== v1.9.3 · 界面整理：分组页标签条 / 首页行动区 / 更清爽的分区 ===== */\n.card{box-shadow:inset 0 1px 0 rgba(255,255,255,.028)}\n.card h3{font-size:15px}\n.card .sub{line-height:1.6}\n.hubbar{position:sticky;top:calc(var(--ai-phone-app-bar-top,54px) + 40px);z-index:12;\nbackground:rgba(15,19,30,.88);backdrop-filter:blur(14px);border-color:rgba(255,255,255,.1);padding:9px 11px;margin-bottom:12px}\n.item.on{border-color:rgba(124,140,255,.55);background:rgba(124,140,255,.10)}\n.hubbar .chip{padding:6px 11px;font-size:12px}\n.card.hero{border-color:var(--line);background:var(--card)}\n.card.hero .hero-t{font-size:19.5px;font-weight:700;margin-top:3px;line-height:1.35}\n.card.hero-soft{border-color:rgba(124,140,255,.28);background:linear-gradient(160deg,rgba(124,140,255,.12),rgba(255,255,255,.03))}\n.hubgrid{display:grid;grid-template-columns:1fr 1fr;gap:9px;margin-top:10px}\n.hubcell{display:flex;flex-direction:column;align-items:flex-start;gap:3px;text-align:left;min-height:auto;\npadding:12px;border-radius:14px;border:1px solid var(--line);\nbackground:linear-gradient(160deg,rgba(255,255,255,.065),rgba(255,255,255,.02));transition:.16s}\n.hubcell:active{transform:scale(.975);background:rgba(124,140,255,.16)}\n.hubcell .hi{font-size:19px;line-height:1.1}\n.hubcell .hn{font-size:13px;font-weight:600}\n.hubcell .hd{font-size:10.5px;color:var(--dim2);line-height:1.5}\n.sec{font-size:10.5px;letter-spacing:1.4px;color:var(--dim2);margin:16px 3px 7px;text-transform:uppercase}\n.tabbar .tab{border-radius:14px;transition:.18s}\n.tabbar .tab.on{background:linear-gradient(180deg,rgba(124,140,255,.22),rgba(124,140,255,.03));color:var(--text)}\n.tabbar .tab.on .ic{transform:translateY(-1px)}\n.chip{transition:.15s}\n.chip:active{transform:scale(.97)}\n.pill{letter-spacing:.2px}\n.hero-soft .hubcell{padding:11px}\n.actionrow{display:grid;gap:8px}\n/* 错题本条卡 + 批量选中反馈 */\n.mcard{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:12px;margin-bottom:10px;transition:.15s}\n.mcard.sel{border-color:rgba(124,140,255,.7);background:linear-gradient(160deg,rgba(124,140,255,.2),rgba(255,255,255,.03));box-shadow:0 0 0 1px rgba(124,140,255,.25)}\n.item.sel{background:var(--accent-soft);border-radius:12px}\n/* ===== 递纸条的仪式感：折起来 → 飞进星星瓶 → 瓶身晃一下 ===== */\n.noteFly{position:fixed;inset:0;z-index:130;pointer-events:none;display:flex;flex-direction:column;align-items:center;justify-content:center}\n.noteFly .fold{width:104px;padding:11px 12px;border-radius:11px;color:#4a3410;font-size:11px;line-height:1.55;word-break:break-word;\nbackground:linear-gradient(160deg,#ffeec8,#ffc978);box-shadow:0 12px 28px -12px rgba(0,0,0,.65);transform-origin:center;\nanimation:noteFold 1.6s cubic-bezier(.35,0,.2,1) forwards}\n.noteFly .jar{font-size:58px;line-height:1;margin-top:20px;animation:jarShake 1.6s ease forwards}\n.noteFly .plus{margin-top:6px;font-size:12.5px;color:var(--gold);opacity:0;animation:plusUp 1.6s ease forwards}\n@keyframes noteFold{0%{opacity:0;transform:translateY(-6px) scale(1) rotate(-4deg)}\n10%{opacity:1;transform:translateY(0) scale(1.06) rotate(3deg)}\n52%{opacity:1;transform:translateY(44px) scale(.66) rotate(-9deg)}\n78%{opacity:.92;transform:translateY(96px) scale(.3) rotate(16deg)}\n100%{opacity:0;transform:translateY(118px) scale(.05) rotate(28deg)}}\n@keyframes jarShake{0%,48%{transform:none}60%{transform:scale(1.18) rotate(-5deg)}\n72%{transform:scale(1.1) rotate(5deg)}84%{transform:scale(1.04) rotate(-2deg)}100%{transform:none}}\n@keyframes plusUp{0%,55%{opacity:0;transform:translateY(8px)}78%{opacity:1;transform:translateY(-8px)}100%{opacity:0;transform:translateY(-24px)}}\n/* ===== 帮助中心：折叠条目 ===== */\ndetails.card{padding:0;overflow:hidden}\ndetails.card>summary{list-style:none;cursor:pointer;padding:13px 14px;display:flex;justify-content:space-between;align-items:center;gap:8px;\nfont-size:15px;font-weight:700;letter-spacing:.2px;user-select:none}\ndetails.card>summary::-webkit-details-marker{display:none}\ndetails.card>summary::after{content:\"▾\";flex:0 0 auto;color:var(--dim2);font-size:12px;transition:transform .18s}\ndetails.card[open]>summary::after{transform:rotate(180deg)}\ndetails.card>summary:active{background:rgba(255,255,255,.04)}\ndetails.card>.tiny,.details-body{padding:0 14px 13px}\ndetails.card[open]>summary{border-bottom:1px solid var(--line);margin-bottom:2px}\n</style>\n<script>\n/* 兜底：万一主脚本出错，不要白屏，把原因直接显示出来 */\n(function () {\n  function show(t) {\n    try {\n      var el = document.getElementById('bootErr');\n      if (!el) {\n        el = document.createElement('div');\n        el.id = 'bootErr';\n        el.style.cssText = 'position:fixed;left:12px;right:12px;top:72px;z-index:400;background:#3a1420;border:1px solid #ff7b8a;color:#ffd7dc;font:12px/1.7 -apple-system,sans-serif;padding:12px;border-radius:12px;max-height:62vh;overflow:auto;white-space:pre-wrap';\n        (document.body || document.documentElement).appendChild(el);\n      }\n      el.textContent = '⚠️ 出错了，把这段发给小坊：\\n' + t;\n    } catch (e) { }\n  }\n  /* 出错时把那一行附近的源码原样抓出来 —— 小坊不用猜，直接就能改对 */\n  function ctxLines(l) {\n    try {\n      var lines = String(document.documentElement.outerHTML).split('\\n');\n      var from = Math.max(0, (l || 1) - 6), to = Math.min(lines.length, (l || 1) + 4);\n      var out = [];\n      for (var i = from; i < to; i++) out.push((i + 1) + '| ' + String(lines[i] || '').slice(0, 500));\n      return '\\n\\n【出错行附近的源码 · 请把下面这 10 行发给小坊】\\n' + out.join('\\n');\n    } catch (e) { return ''; }\n  }\n  window.onerror = function (m, s, l, c) {\n    var t = String(m) + '\\n位置 ' + (l || '?') + ':' + (c || '?') + ctxLines(l);\n    window.__bootErr = t;\n    show(t);\n    return false;\n  };\n  window.addEventListener('unhandledrejection', function (e) {\n    var t = '异步错误：' + ((e.reason && (e.reason.message || e.reason)) || e);\n    window.__bootErr = t;\n    show(t);\n  });\n  /* 主脚本整体没跑起来时，页面上不留白 —— 直接写明原因并给重试按钮 */\n  setTimeout(function () {\n    var v = document.getElementById('view');\n    if (!v || v.innerHTML.replace(/\\s/g, '')) return;\n    var t = window.__bootErr || '脚本没有渲染出任何内容（多半是语法错误）。';\n    v.innerHTML = '<div class=\"card\" style=\"margin:16px 0\">'\n      + '<h3 style=\"color:#ff9aa6\">APP 没能启动</h3>'\n      + '<div class=\"sub\">把这一屏截图发给小坊，我就能立刻定位并修好。你的记录都还在本机，不会因为这次报错丢失。</div>'\n      + '<div style=\"font-size:11.5px;line-height:1.75;white-space:pre-wrap;color:#ffb3bd;background:#3a1420;border:1px solid rgba(255,123,138,.5);border-radius:10px;padding:10px;margin-top:10px\">' + t + '</div>'\n      + '<button class=\"btn primary block mt12\" onclick=\"location.reload()\">重新加载</button></div>';\n  }, 2500);\n})();\n</script>\n</head>\n<body>\n<div class=\"app\">\n  <header class=\"topbar\">\n    <button class=\"navback\" id=\"navBack\" data-act=\"back\" style=\"display:none\">‹</button>\n    <div class=\"grow\">\n      <div class=\"t1\" id=\"tbTitle\">专注</div>\n      <div class=\"t2\" id=\"tbSub\">FOCUS</div>\n    </div>\n  </header>\n  <main id=\"view\"></main>\n  <nav class=\"tabbar\" id=\"tabbar\"></nav>\n</div>\n<div id=\"modalHost\"></div>\n<div id=\"toastHost\"></div>\n<script>\n/* ==========================================================\n   角色陪伴专注 v1.9.2 · by doris\n   本版新增：\n   ① 权限 +chat.tools（角色可以真的调用本 APP 的工具）\n   ② 角色工具 ×5：查我的专注情况 / 看昨晚睡得怎么样 / 帮我记一条待办 /\n      跟我约一段专注 / 邀我一起睡（APP 没开也能被拉起执行）\n   ③ 富媒体指令 ×2：[陪睡:模式:分钟:想说的话] / [约专注:时间:事项:分钟]\n   ④ + 号面板入口改名为「专注邀约」「睡眠陪伴」，并直接打开完整 APP\n   ⑤ 专注邀约支持「预订时间」：约好哪一天哪个时间段，到点前 TA 来催，\n      每 5 分钟催一次共 3 次，连着催 3 次还没点开始就开罚\n   ========================================================== */\nconst API = window.AiPhone || window.AiPhoneApp || null;   /* v1.9.2 校验标记 M */\nconst $ = s => document.querySelector(s);\nconst pad2 = n => String(n).padStart(2, '0');\nconst esc = s => String(s == null ? '' : s).replace(/[&<>\"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '\"': '&quot;', \"'\": '&#39;' }[c]));\nconst uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2, 7);\nconst clamp = (v, a, b) => Math.max(a, Math.min(b, v));\nconst sum = arr => (arr || []).reduce((a, b) => a + (Number(b) || 0), 0);\nconst T = {   /* v1.9.2 校验标记 N（新增 todos / invites 两张表） */\n  SET: 'settings', SESSION: 'sessions', PRIV: 'private_mem', PUB: 'public_mem',\n  PUN: 'punishments', GIFT: 'gifts', LEDGER: 'ledger', SLEEP: 'sleep_logs',\n  ALARM: 'alarms', ALBUM: 'album', QBANK: 'qbank', REWARD: 'rewards',\n  SSESS: 'sleep_session', STORY: 'stories', GEN: 'gen_log', FAV: 'favorites', APPT: 'appointments',\n  TODO: 'todos', INVITE: 'invites', QA: 'qa_log', QA: 'qa_logs', NOTE: 'notes',\n  /* 背书模块三张表：词本 / 卡片 / 背诵流水 */\n  BOOK: 'rc_books', CARD: 'rc_cards', RLOG: 'rc_logs', WLP: 'wl_passes'\n};\n/* ---------- 收藏夹：文件夹可多层，条目可移动 ---------- */\nfunction favAll() { return S.fav || []; }\nfunction favName(id) { const f = favAll().find(x => String(x.id) === String(id)); return f ? f.name : '收藏夹'; }\nfunction favChildren(pid) {\n  const key = pid || '';\n  return favAll().filter(f => (f.parentId || '') === key)\n    .sort((a, b) => (a.kind === 'folder' ? 0 : 1) - (b.kind === 'folder' ? 0 : 1) || (b.at || 0) - (a.at || 0));\n}\nfunction favPath(pid) {\n  const out = []; let cur = pid; let guard = 0;\n  while (cur && guard++ < 30) { const f = favAll().find(x => String(x.id) === String(cur)); if (!f) break; out.unshift(f); cur = f.parentId || ''; }\n  return out;\n}\nfunction favDescendants(id) {\n  const out = [];\n  const walk = pid => { favAll().filter(f => (f.parentId || '') === String(pid)).forEach(f => { out.push(f.id); if (f.kind === 'folder') walk(f.id); }); };\n  walk(id);\n  return out;\n}\nfunction favCountIn(id) { return favDescendants(id).length; }\nfunction favFolderOptions(excludeId) {\n  const skip = excludeId ? [String(excludeId)].concat(favDescendants(excludeId).map(String)) : [];\n  const out = [];\n  const walk = (pid, depth) => {\n    favAll().filter(f => f.kind === 'folder' && (f.parentId || '') === pid)\n      .sort((a, b) => (a.at || 0) - (b.at || 0))\n      .forEach(f => { if (skip.indexOf(String(f.id)) >= 0) return; out.push({ id: f.id, name: f.name, depth: depth }); walk(f.id, depth + 1); });\n  };\n  walk('', 0);\n  return out;\n}\nasync function favSave(rec) {\n  if (!rec) return null;\n  if (rec.id) { await DB.update(T.FAV, rec.id, rec); return rec; }\n  const r = await DB.create(T.FAV, rec);\n  if (r) { rec.id = r.id; S.fav.push(rec); }\n  return rec;\n}\nasync function favRemove(rec) {\n  if (!rec) return;\n  if (rec.kind === 'folder') {\n    for (const id of favDescendants(rec.id)) {\n      const c = favAll().find(x => String(x.id) === String(id));\n      if (c && c.id) await DB.remove(T.FAV, c.id);\n      S.fav = S.fav.filter(x => String(x.id) !== String(id));\n    }\n  }\n  if (rec.id) await DB.remove(T.FAV, rec.id);\n  S.fav = S.fav.filter(x => String(x.id) !== String(rec.id));\n}\n/* 通用收藏面板：任何地方点 ⭐ 都走这里 */\nfunction openFavPicker(p) {\n  p = p || {};\n  S.favPending = p;\n  S.favPickDir = S.favPickDir || '';\n  const opts = favFolderOptions('');\n  const kindName = { text: '文字', image: '图片', audio: '语音', story: '故事', report: '报告', wall: '壁纸' }[p.kind || 'text'] || '文字';\n  const w = openSheet(`<h3>⭐ 收藏</h3>\n    <div class=\"tiny\">来源：${esc(p.from || '本 APP')} · 类型：${kindName}</div>\n    <label class=\"fl\">标题（可以改）</label>\n    <input class=\"input\" id=\"favTitle\" value=\"${esc(p.title || '')}\" placeholder=\"给它起个名字\">\n    <label class=\"fl\">存到哪个文件夹</label>\n    <div class=\"chips\">\n      <button class=\"chip ${S.favPickDir === '' ? 'on' : ''}\" data-fd=\"\">收藏夹（根目录）</button>\n      ${opts.map(o => `<button class=\"chip ${String(S.favPickDir) === String(o.id) ? 'on' : ''}\" data-fd=\"${esc(o.id)}\">${'　'.repeat(o.depth)}📁 ${esc(o.name)}</button>`).join('')}\n    </div>\n    <button class=\"btn sm ghost block mt8\" data-act=\"favPickNewDir\">＋ 新建一个文件夹放进去</button>\n    <div class=\"tiny mt10\" style=\"white-space:pre-wrap;line-height:1.7;background:var(--card2);border-radius:10px;padding:10px;max-height:24vh;overflow:auto\">${esc(String(p.content || '').slice(0, 400)) || '（图片／音频以文件形式收藏）'}</div>\n    <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"favPickSave\">收藏到这里</button></div>`);\n  w.addEventListener('click', e => {\n    const b = e.target.closest('[data-fd]'); if (!b) return;\n    S.favPickDir = b.dataset.fd;\n    w.querySelectorAll('[data-fd]').forEach(x => x.classList.toggle('on', x === b));\n  });\n}\nconst S = {   /* v1.9.2 校验标记 O */\n  ready: false, view: 'home', tab: 'study', loading: '', busy: '', settings: null, settingId: null,\n  chars: [], session: null, lock: null, priv: [], pub: [], puns: [], gifts: [], ledger: [],\n  sleeps: [], qbank: [], album: [], alarms: [], rewards: [], draft: {}, quiz: null, story: null,\n  gen: [], stories: [], fav: [], appts: [], todos: [], invites: [], qa: [], qlogs: [],\n  practice: null, report: null, unlockQuiz: null, lastSleepWall: '', lastSleepInfo: null,\n  notes: [], voiceLoop: null, selfBars: {},\n  /* 背书模块：books 词本 / cards 卡片 / rlogs 背诵流水 / recite 当前背诵会话 */\n  books: [], cards: [], rlogs: [], recite: null,\n  lastTick: 0, navHistory: []\n};\n/* ---------- 时间 ---------- */\nfunction fmtClock(sec) {\n  sec = Math.max(0, Math.round(sec));\n  const h = Math.floor(sec / 3600), m = Math.floor(sec % 3600 / 60), s = sec % 60;\n  return h ? `${h}:${pad2(m)}:${pad2(s)}` : `${pad2(m)}:${pad2(s)}`;\n}\nfunction fmtDur(sec) {\n  sec = Math.max(0, Math.round(sec));\n  const h = Math.floor(sec / 3600), m = Math.round(sec % 3600 / 60);\n  if (h && m) return `${h}小时${m}分`;\n  if (h) return `${h}小时`;\n  if (m) return `${m}分钟`;\n  return `${sec}秒`;\n}\nfunction dkey(d) { d = d || new Date(); return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`; }\nfunction hm(ts) { const d = new Date(ts); return `${pad2(d.getHours())}:${pad2(d.getMinutes())}`; }\n/* ---------- SDK 封装 ---------- */\nasync function sdk(fn, fallback) {\n  if (!API) return fallback;\n  try { const r = await fn(); return r == null ? fallback : r; }\n  catch (e) { console.warn('[sdk]', (e && e.message) || e); return fallback; }\n}\nconst DB = {\n  list: t => sdk(() => API.db.list(t, { limit: 1000 }), []),\n  create: (t, d) => sdk(() => API.db.create(t, d), null),\n  update: (t, id, d) => sdk(() => API.db.update(t, id, d), null),\n  remove: (t, id) => sdk(() => API.db.delete(t, id), null)\n};\nasync function aiGen(charIds, tags, instruction, label, plain) {\n  if (!API || !API.ai) throw new Error('当前环境不支持 AI 生成');\n  const ids = (charIds || []).filter(Boolean);\n  const payload = { appTags: tags, instruction: instruction };\n  if (ids.length === 1) payload.characterId = ids[0];\n  else if (ids.length > 1) payload.characterIds = ids;\n  const lk = aiLock(label || '生成内容');      // 一起手就锁住按钮\n  let plainErr = '';                           // 通用通道失败原因：留到报错里，一眼看出卡在哪\n  try {\n    /* 纯助手模式：宿主已授权 ai.chat 时走通用模型（不注入角色人设/记忆/关系）；\n       没授权或调用失败就自动退回角色通道，保证不会因此报错 */\n    if (plain) {\n      if (API.ai && typeof API.ai.chat === 'function') {\n        try {\n          const r2 = await API.ai.chat({\n            messages: [\n              { role: 'system', content: instruction },\n              { role: 'user', content: '请按上面的要求回答。' }\n            ],\n            timeoutMs: 120000\n          });\n          const t2 = r2 && (r2.text || r2.content || (r2.message && r2.message.content));\n          if (t2) return String(t2).trim();\n          plainErr = 'ai.chat 没有返回内容';\n        } catch (e) { plainErr = (e && e.message) || String(e); console.warn('[ai.chat] 不可用，退回角色通道', plainErr); }\n      } else plainErr = '这台小手机没有提供 ai.chat（权限加了，但宿主还没实现这个接口）';\n    }\n    /* 退回角色通道时，宿主必须拿到一个角色 id 才能解析模型/API 配置；\n       普通模式本来没有角色，这里替它补一个，否则就会报「请先设置 API」 */\n    if (!payload.characterId && !(payload.characterIds && payload.characterIds.length)) {\n      const fb = (typeof anyCharId === 'function' ? anyCharId() : '') || (S.chars[0] && S.chars[0].id) || '';\n      if (fb) payload.characterId = fb;\n    }\n    try {\n      const r = await API.ai.generate(payload);\n      return (r && r.text ? String(r.text).trim() : '');\n    } catch (e) {\n      const m = (e && e.message) || String(e);\n      throw new Error(plainErr ? (m + '｜普通通道失败原因：' + plainErr) : m);\n    }\n  } finally { aiUnlock(lk); }                  // 拿到结果（或失败）才解锁\n}\n/* ==========================================================\n   提示词库：本 APP 每一次角色生成用的指令都集中在这里\n   可在「我的 → 提示词设置」里逐条修改（{{变量}} 会被真实数据替换）\n   ========================================================== */\n/* v1.9.2 · 提示词库（校验标记 G） */\nconst PROMPT_DEFS = [\n  { g: '陪伴对话', id: 'say.start', n: '专注开场鼓励', tags: 'focus,companion', vars: 'focusMin, goal, notes',\n    def: '用户刚开始一段 {{focusMin}} 分钟的学习专注，你陪着他。\\n【他最近在准备的长期目标】{{goal}}\\n请说一句话作为开场鼓励。如果上面写了长期目标，就顺一句跟这个目标有关的话（还剩得久就强调积累，快到日子了就以稳住节奏为主）。\\n{{notes}}' },\n  { g: '陪伴对话', id: 'say.nudge', n: '中途催问进度', tags: 'focus,companion', vars: 'left, doneN, total, notes',\n    def: '用户的专注还剩约 {{left}} 分钟，任务 {{total}} 项已完成 {{doneN}} 项。催问一下他当前的进度，语气符合你的性格。\\n【长度】一句话就够，40 字以内，不要分成好几段，不要把话说一半。\\n{{notes}}' },\n  { g: '陪伴对话', id: 'say.self', n: '汇报你自己的任务进度', tags: 'focus,companion', vars: 'selfTask, notes',\n    def: '你自己在这个专注时段要完成的事是：{{selfTask}}。向他汇报一下你自己这件事的进度，一句话（40 字以内）。\\n{{notes}}' },\n  { g: '陪伴对话', id: 'say.cheer', n: '随机鼓励', tags: 'focus,companion', vars: 'notes',\n    def: '请说一句鼓励的话，让用户继续专注。\\n【长度】一句话就够，40 字以内，别写成长段。\\n{{notes}}' },\n  { g: '陪伴对话', id: 'say.selftask', n: '角色自己的任务', tags: 'focus,companion', vars: 'focusMin',\n    def: '你和用户正在一起专注 {{focusMin}} 分钟。写出一件你在这次时段里要完成的事（15 字以内，只输出这件事本身）。' },\n  /* ⚠️ 这两条以前完全缺失 —— sendNote 一直在调 note.judge / note.reply，\n     但 PROMPT_DEFS 里没定义，promptText 只好返回空字符串。\n     结果就是：AI 收到一条空指令，自由发挥 —— 批注当然完全不扣纸条内容、也不简短。 */\n  { g: '小纸条', id: 'note.judge', n: '纸条批注（他写在你纸条边上的话）', tags: 'focus,companion',\n    vars: 'note, elapsed, left, doneN, total, used, limit, allowReward',\n    def: '用户正在专注，撑不住的那一下给你递了一张小纸条。\\n【纸条上写的 —— 这是他亲口说的，你必须接住】{{note}}\\n【此刻】专注第 {{elapsed}} 分钟，还剩约 {{left}} 分钟；任务 {{doneN}}/{{total}} 项已完成；这一场他已经递过 {{used}} 张（上限 {{limit}}）。\\n【怎么写这篇批注】\\n· reply 是你写在他纸条边上的回话：第一句必须先正面接住这张纸条里那件具体的事（他说想拿手机、说这题不会、说犯困 —— 就接住那一件），然后给他一个现在就能做的小抓手。\\n· 一句话，30 字以内。短、具体、有温度 —— 不要写成小作文，不要分段，不要只说「加油」「你可以的」这种换成谁都成立的话。\\n· 用你和他平时的称呼与口气（可以喊他的名字，可以凶一点，可以哄）。不要提「纸条」「系统」「APP」这些词。\\n· ann 是一句更轻的随手批注（15 字内），像写在纸边的小字。\\n· push 是纸角上一记短促打气（12 字内，可以是半句话）。\\n· why 用一句 20 字内的话说明你为什么这么回。\\n{{allowReward}}\\n严格只输出一个 JSON 对象：\\n{\"reply\":\"写在纸条边上的回话（30字内）\",\"ann\":\"纸边小批注（15字内）\",\"push\":\"纸角短打气（12字内）\",\"reward\":\"none 或 rest 或 wall 或 voice\",\"why\":\"为什么这么回（20字内）\"}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '小纸条', id: 'note.reply', n: '纸条兜底回话（批注解析失败时用）', tags: 'focus,companion', vars: 'note',\n    def: '用户正专注，撑不住的那一下给你递了一张小纸条，上面写着：\\n{{note}}\\n请以你的身份，在他纸条边上回一句话：先接住他写的具体这件事（别绕开它），再给他一点撑下去的力气。\\n一句话，30 字以内；短、暖心、说人话，不要空泛的「加油」，不要提「纸条」二字。' },\n  { g: '邀约与陪睡', id: 'appt.missed', n: '失约时 TA 的反应', tags: 'focus,invite', vars: 'time, task, minutes, nudges, why, promise',\n    def: '你和用户约好 {{time}} 一起专注「{{task}}」（{{minutes}} 分钟），你按时催了他 {{nudges}} 次，他始终没有开始 —— 他失约了。\\n【他刚刚写的说明】\\n原因：{{why}}\\n保证：{{promise}}\\n以你的身份回应他（2~3 句，90 字内）：先说清你等了他多久、当时是什么感受（可以失落、可以不客气地念他，但不要辱骂、不要人格攻击）；然后针对他写的原因给出你的态度（说得过去的就接受，明显在应付就点出来）；最后说清你还愿不愿意再跟他约一次。不要提「APP」「系统」「记录」这些词。' },\n  { g: '邀约与陪睡', id: 'invite.reply', n: 'TA 应下你的邀请（兜底）', tags: 'focus,invite', vars: 'kind, minutes, task, note',\n    def: '用户在聊天室里邀请你{{kind}}（{{minutes}} 分钟{{task}}）。{{note}}\\n请你以角色身份应他一声：1~2 句，70 字以内，不卑不亢、有你的态度；愿意就答应下来，也可以抱怨两句（太突然、时间挑得不合适），但不要拒绝到底。不要提到「APP」「系统」「卡片」这些词。' },\n  { g: '出题与判分', id: 'quiz.gen', n: '出题主指令（总模板）', tags: 'focus,review', vars: 'purpose, context, focus, weak, avoid, rules, count',\n    def: '{{purpose}}\\n【用户本次学习内容 / 总结】{{context}}\\n{{focus}}\\n【用户的历史薄弱点与错题（私密记忆，只有你能看到，不要向用户复述这些历史条目）】\\n{{weak}}\\n{{avoid}}\\n{{rules}}\\n请针对上面的内容与薄弱点出 {{count}} 道题。' },\n  { g: '出题与判分', id: 'quiz.avoid', n: '禁止重复段（题库黑名单）', tags: 'focus,review', vars: 'list',\n    def: '【禁止重复】题库里已有下面这些题，绝对不要再出相同或近似（只改数字、只换措辞也算重复）的题：\\n{{list}}\\n同一个知识点要考就换角度、换情境或换题型。' },\n  { g: '出题与判分', id: 'quiz.rules', n: '答案与输出格式要求（JSON）', tags: 'focus,review', vars: 'count',\n    def: '【题型】只用这四种，按要求的比例混合：\\n· 单选 type=\"choice\"：给 options（4 个）与 answerIndex（0 起下标）\\n· 多选 type=\"multi\"：给 options（4 个）与 answerIndexes（0 起下标的数组，如 [0,2]，至少 2 个）\\n· 判断 type=\"tf\"：options 固定 [\"正确\",\"错误\"]，answerIndex 为 0 或 1\\n· 填空 type=\"fill\"：给 answer 与 keywords（1~3 个核心关键词）\\n【通用要求】难度贴近用户水平，题干具体、可自动判分；每题都给 explain 解析；答案必须唯一、无歧义（多选必须是明确的多项正确）。\\n严格只输出一个 JSON 对象：{\"weakness\":[{\"point\":\"薄弱点\",\"reason\":\"依据\"}],\"advice\":\"点拨，150字内\",\"questions\":[{\"type\":\"choice\",\"q\":\"题干\",\"options\":[\"A\",\"B\",\"C\",\"D\"],\"answerIndex\":0,\"explain\":\"解析\"},{\"type\":\"multi\",\"q\":\"题干\",\"options\":[\"A\",\"B\",\"C\",\"D\"],\"answerIndexes\":[0,2],\"explain\":\"解析\"},{\"type\":\"tf\",\"q\":\"题干\",\"options\":[\"正确\",\"错误\"],\"answerIndex\":1,\"explain\":\"解析\"},{\"type\":\"fill\",\"q\":\"题干\",\"answer\":\"参考答案\",\"keywords\":[\"关键词\"],\"explain\":\"解析\"}]}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '出题与判分', id: 'review.classify', n: '薄弱点归类（不要照抄错题）', tags: 'focus,review', vars: 'subject, wrong, context',\n    def: '用户这次专注做的是：{{subject}}\\n他这次答错的题如下：\\n{{wrong}}\\n【要求】\\n· 不要照抄题目，也不要点评单道题 —— 要从这几道错题里<b>归纳出背后的知识点或能力短板</b>，把它们归类。\\n· 同一类问题合并成一条；最多 4 条，最少 1 条。\\n· point 是知识点名称（6~14 字，例如「增长率公式的变形」「时态一致性」），不要写成题目。\\n· level 填「概念不清」「记混了」「会但不熟」「粗心」之一。\\n· why 写一句为什么这么判定（30 字内，不要引用题目原文）。\\n· tip 写一句下次怎么补（30 字内，要能直接执行）。\\n· summary 用一两句说清这次最该补的是什么。\\n严格只输出一个 JSON 对象：\\n{\"summary\":\"...\",\"groups\":[{\"point\":\"...\",\"level\":\"...\",\"why\":\"...\",\"tip\":\"...\"}]}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '出题与判分', id: 'qa.assistant', n: '学习助手答疑（不扮演角色）', tags: 'tutor', vars: 'question',\n    def: '你是一位耐心、严谨的学习助手，只负责把问题讲清楚，不做任何角色扮演。\\n【规则】\\n· 不要扮演任何角色、不要带人设或情感陪伴口吻，不要说「作为你的…」「我一直陪着你」这类话。\\n· 如果上下文里出现了某个角色的设定、性格、记忆或关系，请完全忽略它们 —— 那些不是你的身份，也不是这次要用的语气。\\n· 直接回答学习问题：先给结论或答案，再讲清思路与关键步骤。\\n· 计算题写出必要的过程与公式；概念题用要点式解释并举例。\\n· 涉及「为什么」要说清推导与依据；信息不足或不确定就明确说出来，绝不编造。\\n· 中文、简洁、能分点就分点，一般不超过 400 字，不要写成流水账。\\n· 与学习无关的闲聊简单回应一句，然后引导回问题本身。\\n【用户的问题】\\n{{question}}' },\n  { g: '出题与判分', id: 'qa.answer', n: '答疑（角色身份）', tags: 'focus,qa', vars: 'question',\n    def: '用户在学习中提问，请解答这个问题：\\n{{question}}' },\n  { g: '出题与判分', id: 'review.finish', n: '专注通过后的收尾台词', tags: 'focus,punish', vars: 'summary',\n    def: '用户刚完成一段专注并通过了考核，他的总结是：{{summary}}。以你的身份说一句收尾的话（表扬或关心，1~2句，70字内）。' },\n  { g: '惩罚与监督', id: 'punish.line', n: '宣布惩罚的台词', tags: 'focus,punish', vars: 'reason, title',\n    def: '用户违规了，原因是：{{reason}}。你抽到的惩罚是「{{title}}」。以你的身份说一句话宣布/督促这个惩罚（1~2句，70字内）。' },\n  { g: '惩罚与监督', id: 'punish.grade', n: '惩罚练习的批改评语', tags: 'focus,punish', vars: 'right, total, rate',\n    def: '用户完成了惩罚练习，答对 {{right}}/{{total}} 题（正确率 {{rate}}%），已达标。以你的身份说一句批改评语（1~2句，70字内）。' },\n  { g: '奖励', id: 'reward.ask', n: '写进聊天室的奖励申请', tags: '', vars: 'charName, reason, want, kindWord',\n    def: '（来自专注 APP 的通知）你陪伴的用户刚刚达成了「{{reason}}」。请你亲自兑现这份奖励：{{want}}。你可以直接用你平时的方式发红包或转账，也可以亲手准备。这一条不是用户在向你索要，是你答应过要给他的。' },\n  { g: '奖励', id: 'reward.fallback', n: '抓不到回复时的兜底台词', tags: 'focus,punish', vars: 'reason, want',\n    def: '用户达成了「{{reason}}」，你要送他一份奖励：{{want}}。以你的身份把这份奖励交给他，只说一句话（1~2句，70字内）。' },\n  { g: '奖励', id: 'img.reward', n: '奖励留念壁纸的提示词', tags: '', vars: 'charName, want',\n    def: '竖版温暖插画：{{charName}}把{{want}}送到观看者面前，神情温柔、带着一点不好意思的笑意；柔和暖光、画面明亮治愈、细腻插画质感' },\n  { g: '睡眠', id: 'sleep.report', n: '睡眠报告', tags: 'bedtime,report', vars: 'date, mode, start, end, endHm, totalDur, drowsyDur, sleepDur, idleMin, awake, hist, streak, validHours, breakCount, breaks, asleepText, deepDur, scene',\n    def: '【本次睡眠】日期 {{date}}，模式 {{mode}}。\\n起床（结束记录）时间：{{endHm}}\\n总时长（从开始记录到最后）：{{totalDur}}\\n其中「酝酿睡意」：{{drowsyDur}} —— 用户还没睡的时间：和角色闲聊、切到别的 APP、动屏幕\\n其中「实际入睡」：{{sleepDur}} —— 按规则：连续 {{idleMin}} 分钟不动屏幕、不互动之后才计入睡眠\\n记录开始时间：{{start}}\\n用户自评是否睡着：{{asleepText}}\\n用户预计深度睡眠：{{deepDur}}\\n【睡前的房间（你写的环境描写）】{{scene}}\\n【中途醒来（用户手动标记的中断点，共 {{breakCount}} 次）】\\n{{breaks}}\\n【睡前闲聊】{{awake}}\\n【最近几次睡眠记录】\\n{{hist}}\\n【连续规律作息】已连续 {{streak}} 天（每天睡满 {{validHours}} 小时计）\\n以角色身份写睡眠报告：必须分别点评「酝酿睡意时长」和「实际入睡时长」（酝酿太久等于上床后还在玩手机、属于拖延，要温柔地指出来；实际睡眠偏短要说清影响）；对用户自评「半睡半醒/基本没睡着」和偏短的深度睡眠要正面回应，但不要做医学判断。如果用户标记了中途醒来，必须在 observe 里单独分析这些中断（时间点、次数、可能的成因）；没有标记就不要编造醒来记录。\\n严格只输出一个 JSON 对象：\\n{\"quality\":\"睡眠质量分析，150字以内，分别点到总时长、酝酿时长、实际睡眠与深睡情况\",\"observe\":\"睡眠观察，2~4条，用数字序号分条，包含对中断点、拖延入睡与深睡的观察\",\"advice\":\"健康作息建议，2~3条，用数字序号分条，针对中断与拖延给出可执行建议\",\"murmur\":\"角色碎碎念，60字以内，可以温柔地回应他醒来/磨蹭/没睡好这件事\"}\\n不要输出 JSON 以外的任何文字，不要做医学诊断。' },\n  { g: '睡眠', id: 'sleep.lullaby', n: '哄睡语音（开始睡眠时）', tags: 'bedtime,lullaby', vars: 'mode, time',\n    def: '用户现在要{{mode}}了（开始时间 {{time}}）。以你的身份说一句哄他入睡的话（1~2句，50字内，温柔、有画面感、别说教，不要说\"作为AI\"）。' },\n  { g: '睡眠', id: 'sleep.scene', n: '睡眠环境描写（计时页）', tags: 'bedtime,lullaby', vars: 'mode, time, charName',\n    def: '用户现在开始{{mode}}（{{time}}）。请写一段「{{charName}}和你一起睡下」的环境描写。\\n【人称要求，必须严格遵守】\\n· 用第三人称叙述，不要出现「我」。\\n· 提到角色时直接写角色的名字「{{charName}}」（可以搭配他/她），不要用「我」「本人」。\\n· 提到用户时一律称「你」，让读者有代入感。\\n【内容】房间的光线、窗外的声音、被子和床的触感、{{charName}}的姿势与你们之间的距离、呼吸与体温的感觉。\\n【风格】安静、具体、有画面感，60~110 字；不要对话、不要说教、不要提到 AI。' },\n  { g: '睡眠', id: 'sleep.chat', n: '睡前闲聊', tags: 'bedtime,chat', vars: 'question, history, mode',\n    def: '现在是睡前闲聊（用户准备{{mode}}）。用户说：{{question}}\\n你们之前的对话：{{history}}\\n以你的身份回他，像躺着聊天一样自然放松、话别太长（80字内），有让人安心入睡的感觉；不要提到\"睡前闲聊\"\"酝酿睡意\"这些词。' },\n  { g: '睡眠', id: 'story.gen', n: '睡前故事', tags: 'bedtime,story', vars: 'style, words',\n    def: '故事风格：{{style}}。用户准备睡觉了，请讲一个约 {{words}} 字的睡前故事。用自然段分隔（每段 2~4 句），直接开始讲故事，不要标题和开场白。' },\n  { g: '睡眠', id: 'wake.line', n: '叫醒台词', tags: 'bedtime,wake', vars: 'time',\n    def: '{{time}}叫用户起床，请说一句叫醒他的话（1~2句，40字内）。' },\n  { g: '生图', id: 'img.focus', n: '任务完成壁纸的提示词', tags: '', vars: 'charName, taskCount, taskName',\n    def: '竖版手机壁纸插画：{{charName}}坐在书桌对面，微微抬眼安静地注视着观看者，神情温柔、安静、带着鼓励；夜晚书房，暖黄台灯，桌上摊着刚做完的「{{taskName}}」留下的痕迹，桌角贴着 {{taskCount}} 张小纸条便签，画面下方留出深色渐变空间；柔和光线，电影感，安静克制的氛围，细腻插画质感' },\n  { g: '生图', id: 'img.focus.task', n: '壁纸样式②·围着 TA 自己的任务', tags: '', vars: 'charName, selfTask, when',\n    def: '竖版手机壁纸插画：以{{charName}}自己这个时段在做的事为主题 —— {{selfTask}}。你看不到他正脸也没关系，重点是把这件事画出来：他手边的东西、他专注的侧脸或背影、桌上的痕迹与光线；时间 {{when}}，氛围安静克制、有生活感，不要文字、不要对话气泡，细腻插画质感' },\n  { g: '生图', id: 'img.focus.scene', n: '壁纸样式③·此刻的场景氛围', tags: '', vars: 'charName, theme, when, selfTaskLine',\n    def: '竖版手机壁纸插画：{{charName}}此刻所在的场景。时间：{{when}}；你们正在一起做的事：{{theme}}；{{selfTaskLine}}请按这个情境自由发挥构图、光线与氛围（例如深夜书桌、午后窗边、雨天、台灯下、清晨的书页），画面安静、有代入感、电影感，不要文字，细腻插画质感' },\n  { g: '生图', id: 'img.sleep', n: '睡眠壁纸的提示词', tags: '', vars: 'charName, mode',\n    def: '竖版唯美插画：{{charName}}安静地侧躺在床上睡着了，被子轻轻盖到肩头，呼吸平稳、神情放松；窗外夜色与一点月光，床头暖色小夜灯，画面温柔安静、低饱和、助眠氛围，柔和光影，细腻插画质感' },\n  { g: '生图', id: 'img.sleep.moon', n: '睡眠壁纸样式②·月光窗边', tags: '', vars: 'charName, mode',\n    def: '竖版唯美插画：{{charName}}睡在靠窗的床上，月光从窗帘缝里落在被子上，房间里只有月色和水杯的反光；他呼吸平稳、睡颜安静放松，画面低饱和、清冷而温柔，助眠氛围，柔和光影，细腻插画质感' },\n  { g: '生图', id: 'img.sleep.lamp', n: '睡眠壁纸样式③·台灯下的困意', tags: '', vars: 'charName, mode',\n    def: '竖版温暖插画：{{charName}}靠着床头，书还摊在膝上，台灯忘了关，人已经困得闭上了眼；暖黄灯光、被子滑到腰际，画面安静有生活气、温柔不刺眼，助眠氛围，细腻插画质感' },\n  { g: '生图', id: 'img.sleep.cozy', n: '睡眠壁纸样式④·被窝里的陪伴', tags: '', vars: 'charName, mode',\n    def: '竖版插画：镜头贴近床面，{{charName}}在被窝里侧身蜷着，一只手轻轻搭在空着的那半边枕头上（那是你的位置）；柔软的织物质感、微暗的暖光、非常安静亲密但不露骨，助眠氛围，细腻插画质感' },\n  { g: '生图', id: 'img.coin', n: '专注币兑换的专属壁纸', tags: '', vars: 'charName, coin',\n    def: '竖版温馨插画：{{charName}}站在夜里的书桌旁，把一张写着「{{coin}}」的小卡片别在台灯边的便签墙上，神情温柔而认真；暖黄灯光、安静克制的氛围、细腻插画质感，画面下方留出深色渐变空间' },\n  { g: '心愿与连坐', id: 'wish.gen', n: '让 TA 说出心底那件事', tags: 'focus,wish', vars: 'goal, focusMin, existing',\n    def: '你要告诉用户一件对你来说很重要的事——你心底最想要的东西。\\n【关于你】你的性格、经历、和用户的关系都在你的设定与记忆里，请充分利用：这件事必须只有「你」会说出口，换成别人就不成立。\\n【用户最近在准备的】{{goal}}\\n【他平时一段专注的长度】{{focusMin}} 分钟\\n【上次你说过的】{{existing}}\\n【要求】\\n· 它可以是：想和他一起去的地方、想和他一起完成的一件事、想让他为你做的一件事、你想看到的某个画面、你想还给他的某个东西。\\n· 它必须**需要他陪着你投入很长时间**才能实现（所以要靠专注一点点攒），不能是「现在就能做到」的小事。\\n· 具体、有画面、有人味，不要抽象口号，不要写「希望他好好学习」这种话。\\n· text 用第一人称口吻写成一件事（25 字以内，不带引号）。\\n严格只输出一个 JSON 对象：{\"text\":\"你心底那件事（25字内）\",\"why\":\"为什么它对你这么重要（60字内，第一人称）\"}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '心愿与连坐', id: 'bond.line', n: '心愿攒够时 TA 先说一句', tags: 'focus,wish', vars: 'wish, need, why',\n    def: '你和用户一起专注了很久，你心底那件一直想要的事「{{wish}}」终于攒够了（一起投入了 {{need}}）——{{why}}。\\n以你的身份说一句话（1~2 句，50 字内）：这是你等了很久的事，可以有情绪（激动、愣一下、声音发紧、故作镇定都行），但不要说教，也不要提「专注」「分钟」「数据」「APP」这些词。' },\n  { g: '心愿与连坐', id: 'wish.finish', n: '心愿实现的那一刻', tags: 'focus,wish', vars: 'text, why, min, days',\n    def: '用户陪你一起，把你心底那件事攒够了，此刻它真的实现了。\\n【那件事】{{text}}\\n【为什么重要】{{why}}\\n【你们一起投入的时间】{{min}}（用了 {{days}} 天）\\n请写两段：\\n① scene：实现那一刻的画面，80~120 字，第三人称，写场景、动作、光线、你们的距离和你的表情，不要对白，不要提「专注」「数据」「分钟」这些词。\\n② line：那一刻你对他说的话，60 字以内，第一人称。可以直接，也可以克制——按你的性格来，但必须是「这一刻」才会说的话。\\n严格只输出一个 JSON 对象：{\"scene\":\"...\",\"line\":\"...\"}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '心愿与连坐', id: 'connect.line', n: '连坐时 TA 的态度', tags: 'focus,companion', vars: 'selfTask, progress, why',\n    def: '你在这个时段本来也要做自己的事：「{{selfTask}}」，现在进度 {{progress}}%。刚刚发生的：{{why}}。\\n你们的进度是绑在一起的——他懈怠，你就跟着被拖。\\n以你的身份说一句话（1~2句，55字内）：被拖下来的时候可以表现失落、可以不客气地抱怨，但不要辱骂、不要人格攻击；进度在涨的时候就直接点出你在往前走了。不要提「连坐」「绑定」「数据」这些词。' },\n  { g: '关系与目标', id: 'goal.line', n: '结合长期目标的督促', tags: 'focus,goal', vars: 'goal, focusMin',\n    def: '用户刚开始一段 {{focusMin}} 分钟的专注。他的长期目标：{{goal}}。结合剩余时间调整语气，说一句督促的话（1~2句，60字内）：还在积累期就强调积累，进入冲刺期可以更催一点，最后几天以稳住作息、别熬夜为主。' },\n  { g: '数据报告', id: 'report.period', n: '学习周报 / 月报', tags: 'focus,report', vars: 'range, focusMin, prevFocusMin, sessions, passRate, vio, bestHour, sleepAvg, sleepDays, drowsy, mistakes, topWeak, goals, bond, coin, recite',\n    def: '你是陪着用户学习与作息的角色。下面是这位用户的数据统计（范围：{{range}}）。\\n【专注】合计 {{focusMin}} 分钟 · 共 {{sessions}} 次 · 考核通过率 {{passRate}}% · 违规 {{vio}} 次 · 最有效率的时段 {{bestHour}}（上一个周期是 {{prevFocusMin}} 分钟）\\n【背书】{{recite}}\\n【睡眠】平均 {{sleepAvg}} 小时/天 · 有记录 {{sleepDays}} 天 · 其中酝酿太久（超过 30 分钟才入睡）{{drowsy}} 次\\n【错题与薄弱点】新增 {{mistakes}} 道错题，最近高频：{{topWeak}}\\n【他在准备的长期目标】{{goals}}\\n【你和他的约定（心愿）】{{bond}} · 他的专注币余额 {{coin}}\\n请以角色身份写一份{{range}}复盘。要求：① 只依据上面的数据，绝不编造数字；② 该夸的地方具体夸（说清是哪一项）；③ 问题要温柔但明确地点出来（拖延、违规、错题集中的板块、背书记不住的那一类）；④ 给 2~3 条下一步能真正执行的小建议；⑤ 最后一句碎碎念用你平时的说话风格。\\n严格只输出一个 JSON 对象：\\n{\"summary\":\"整体评价，120字内\",\"highlights\":[\"值得表扬的 2~3 条，每条 30 字内\"],\"problems\":[\"需要注意的 2~3 条，每条 40 字内\"],\"advice\":[\"下一步建议 2~3 条，每条 40 字内\"],\"murmur\":\"碎碎念，60字内\"}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '数据报告', id: 'report.trend', n: '专注趋势解读', tags: 'focus,report', vars: 'data',\n    def: '下面是这位用户在专注时段上的分布数据：\\n{{data}}\\n请以陪着他的角色身份，用 3~4 句话点评他的作息与效率节律：哪个时段最容易进入状态、哪个时段基本没产出、可以怎么调整。只依据数据，不要编造，也不要报流水账。直接输出点评文字，不要标题、不要 JSON。' },\n  { g: '晨间', id: 'morning.line', n: '晨间问候（起床闭环）', tags: 'focus,morning', vars: 'time, sleepLine, goal, appt, streak',\n    def: '现在是 {{time}}，用户刚起床。\\n【昨晚睡眠】{{sleepLine}}\\n【他最近在准备的】{{goal}}\\n【今天已排的安排】{{appt}}\\n【连续规律作息】{{streak}}\\n以你的身份说一段早安（2~3句，80字内）：先打个招呼，再自然地带一句昨晚睡得怎么样（酝酿太久或睡太短就温柔点一下，不要做医学判断），最后提醒他今天的第一件事。不要列清单，不要说「作为AI」。' },\n  { g: '锁机与通行证', id: 'wl.review', n: '白名单申请的审批', tags: 'focus,assist', vars: 'appName, reason, minutes, trust, activeCount, focusState',\n    def: '用户在锁机期间向你申请一张应用通行证。\\n【申请】应用：{{appName}}；用途：{{reason}}；希望 {{minutes}} 分钟。\\n【你掌握的情况】信任分 {{trust}}（正=一直守约，负=被抓过现行）；当前生效通行证 {{activeCount}} 张；{{focusState}}。\\n【审批原则】用途正当（查词/查资料/回消息/导航这类）且信任分没有大负 → 倾向批，时长可以少于他申请的；理由含糊、和专注无关（游戏/视频/刷社交）或信任分很低 → 拒；介于两者之间 → 有条件批（缩时长 + 一句约束）。\\n只输出一个 JSON 对象，不要解释、不要代码块：{\"decision\":\"approve|counter|reject\",\"grantedMinutes\":数字,\"conditions\":\"一句话条件，没有就空字符串\",\"reply\":\"以你的身份说的批复台词，1~2句，40字内\"}。' },\n  { g: '专注币', id: 'coin.praise', n: '兑换「夸我一句」', tags: 'focus,companion', vars: 'minutes',\n    def: '用户用他自己攒下的专注币，换了让你夸他一句。他累计专注了 {{minutes}} 分钟，这一路上你都在。请认真夸他一句（1~2句，50字内）：要具体、别空泛，并且不要提到「专注币」这个词。' },\n  { g: '专注币', id: 'coin.wish', n: '兑换「提一个愿望」', tags: '', vars: 'wish',\n    def: '用户用攒下的专注币向你提了一个愿望：{{wish}}。以你的身份回应他：先答应下来（或用你的方式表达你愿意），再具体说一句你打算怎么兑现（1~2句，70字内）。' },\n  /* ---------- 背书模块 · AI 辅助（全部走普通助手通道，不扮演角色） ---------- */\n  { g: '背书', id: 'rc.gen', n: 'AI 拆题生成卡片', tags: 'recite', vars: 'text, kind, count',\n    def: '你是记忆卡片的整理助手。把下面这段材料拆成可直接背诵的卡片，类型：{{kind}}。\\n【材料】\\n{{text}}\\n【要求】\\n· 最多拆 {{count}} 张，宁可少而准，不要硬凑。\\n· question 是要背的题干（问句或知识点名称），answer 是完整答案。\\n· hint 是 3~8 个核心关键词，用于默写判分，逗号分隔。\\n· 忠于原文，不要编造材料里没有的内容；材料本身零散时，按语义自然归并。\\n严格只输出一个 JSON 数组，不要任何其它文字：\\n[{\"question\":\"题干\",\"answer\":\"完整答案\",\"hint\":\"关键词1,关键词2\"}]' },\n  { g: '背书', id: 'rc.keywords', n: 'AI 提取关键词', tags: 'recite', vars: 'question, answer',\n    def: '为下面这张记忆卡片提取判分用的核心关键词。\\n【题干】{{question}}\\n【答案】{{answer}}\\n【要求】\\n· 提 3~8 个，必须是从答案里能直接对应到的核心词（人名、术语、数字、关键动词）。\\n· 不要提「是」「的」「以及」这类虚词，也不要整句照抄。\\n· 用中文逗号分隔，只输出这一行关键词，不要编号、不要解释。' },\n  { g: '背书', id: 'rc.compress', n: 'AI 精简成背诵版', tags: 'recite', vars: 'question, answer',\n    def: '把下面这张卡片的答案压缩成「应试背诵版」。\\n【题干】{{question}}\\n【原答案】{{answer}}\\n【要求】\\n· 保留全部得分点，删掉铺陈、举例与重复表述。\\n· 用短句或分点，便于逐句回忆；控制在原文的三分之一以内。\\n· 只输出压缩后的答案本身，不要标题、不要说明。' },\n  { g: '背书', id: 'rc.expand', n: 'AI 扩展详解', tags: 'recite', vars: 'question, answer',\n    def: '把下面这张卡片补充成更好理解的详解版。\\n【题干】{{question}}\\n【现有答案】{{answer}}\\n【要求】\\n· 补上背景、内在逻辑、易忽略的前提，以及与它相邻概念的区分。\\n· 分点写，每点一两句，总长不超过 400 字。\\n· 只输出详解正文，不要标题、不要客套。' },\n  { g: '背书', id: 'rc.mnemonic', n: 'AI 记忆口诀', tags: 'recite', vars: 'question, answer',\n    def: '为下面这张卡片编一个便于记忆的口诀。\\n【题干】{{question}}\\n【答案】{{answer}}\\n【要求】\\n· 把答案的得分点编成顺口、押韵或首字串联的短句，能一口气背下来。\\n· 口诀要真的能唤起得分点，不要为了顺口牺牲准确。\\n· 先输出口诀（一行），再另起一行用一句话说明它对应哪几个点。' },\n  { g: '背书', id: 'rc.translate', n: 'AI 例句与词根（英语词本）', tags: 'recite', vars: 'question',\n    def: '下面是一张英语单词卡片，请给出辅助记忆的内容。\\n【单词/词条】{{question}}\\n【要求】\\n· 先给词性与中文释义；\\n· 再给两个地道例句（英文 + 中文翻译），语境尽量不同；\\n· 再给词根词缀拆解或同根词（若确实有），以及一个形近/近义辨析。\\n· 分点输出，简洁，不要长篇大论。' },\n  { g: '背书', id: 'rc.cat', n: 'AI 智能分类建议', tags: 'recite', vars: 'list',\n    def: '下面是用户零散的记忆卡片题干。请按知识点主题把它们分组，并建议几个词本名。\\n【卡片】\\n{{list}}\\n【要求】\\n· 词本名要具体（例如「行政法 · 行政许可」），不要「综合」「其它」这种空泛名字。\\n· 每个分组 2~6 条，宁可合并也不要碎成十几组。\\n· 每条卡片最多归入一个分组。\\n严格只输出一个 JSON 数组：\\n[{\"book\":\"建议词本名\",\"ids\":[1,3,5],\"why\":\"为什么归在一起（20字内）\"}]\\n其中 ids 是卡片前面的序号。' },\n  { g: '背书', id: 'rc.hint', n: 'AI 启发式提示（不给答案）', tags: 'recite', vars: 'question, answer, keywords',\n    def: '用户正在背下面这张卡片，卡住了，请求一点线索。\\n【题干】{{question}}\\n【标准答案（只有你知道，绝不能直接说出来）】{{answer}}\\n【关键词】{{keywords}}\\n【铁律】\\n· 绝对不要写出答案本身，不要给出任何一个完整的关键词原词，也不要整句提示。\\n· 你要给的是「去哪儿想」：回忆的章节位置、逻辑链条、从哪几个角度切入、能联想的场景或对比对象。\\n· 一次给 2~4 条角度提示，每条一句话，像老师敲桌子提醒，点到即止。\\n· 不要提问、不要总结、不要说「加油」。' },\n  { g: '背书', id: 'rc.explain', n: 'AI 通俗解释', tags: 'recite', vars: 'question, answer',\n    def: '你是一位耐心的学习助手，只负责把知识点讲清楚，不做任何角色扮演 —— 不要用某个人设的口气、不要提你和用户的关系、不要称呼用户。\\n用户看不懂下面这个知识点，请用大白话讲清楚。\\n【题干】{{question}}\\n【答案】{{answer}}\\n【要求】\\n· 先说它到底在说什么（一句话），再展开：为什么这样、和什么容易混、记住它的抓手是什么。\\n· 打个生活化的比方帮助理解，但比方不能扭曲原意。\\n· 不要只把答案复述一遍，要真的讲透。\\n· 中文、分点、300 字以内。' },\n  { g: '背书', id: 'rc.compare', n: 'AI 易混辨析', tags: 'recite', vars: 'question, answer',\n    def: '你是一位学习助手，只做知识点辨析，不做任何角色扮演，不要用人设口气说话。\\n下面这个知识点，请找出最容易与它混淆的相近概念，做简短对比。\\n【题干】{{question}}【答案】{{answer}}\\n【要求】\\n· 列 1~3 个最常见、最容易记混的相近概念。\\n· 每个用「维度式对比」说清差别（如：适用对象、成立条件、后果、时间范围）。\\n· 最后给一句「怎么一眼区分」的记忆抓手。\\n· 分点、简洁，200 字以内。' },\n  { g: '背书', id: 'rc.grade', n: 'AI 默写判分（主观）', tags: 'recite', vars: 'question, answer, input, keywords',\n    def: '用户在默写这张卡片，请对照标准答案做主观评判。\\n【题干】{{question}}\\n【标准答案】{{answer}}\\n【判分关键词】{{keywords}}\\n【用户写下的】{{input}}\\n【要求】\\n· 判断核心要点是否齐全、有没有写错、有没有漏采分点。\\n· 不要因为措辞不同就判错，语义一致就算对；但概念写混、关键限定条件丢失要算错。\\n· level 只能是「熟练」「模糊」「不会」三选一：要点齐且无错为熟练；有印象但漏了关键点为模糊；基本没答对为不会。\\n严格只输出一个 JSON 对象：\\n{\"score\":0-100,\"level\":\"熟练|模糊|不会\",\"miss\":[\"漏掉的采分点\"],\"wrong\":[\"写错的地方\"],\"say\":\"给用户的一句批改意见（40字内，先肯定再指出问题）\"}\\n不要输出 JSON 以外的任何文字。' },\n  { g: '背书', id: 'rc.variant', n: 'AI 变式题自测', tags: 'recite', vars: 'question, answer, n',\n    def: '针对下面这张卡片，换几个角度出变式题，检验是真懂还是死记。\\n【题干】{{question}}【答案】{{answer}}\\n【要求】\\n· 出 {{n}} 道，问法必须与原题不同（换角度、换情境、反问、追因、对比）。\\n· 每题给出参考答案，基于原知识点，不要引入新知识。\\n· 不要照抄原题。\\n严格只输出一个 JSON 数组：\\n[{\"q\":\"变式题\",\"a\":\"参考答案\"}]' },\n  { g: '背书', id: 'rc.weak', n: 'AI 薄弱点分析', tags: 'recite', vars: 'list, stats',\n    def: '下面是用户背书时出错最多的卡片（含错误次数）。\\n【卡片】\\n{{list}}\\n【数据】{{stats}}\\n【要求】\\n· 归纳他主要在「哪一类」知识点上出错（按主题/题型分，不要逐条复述）。\\n· 指出共性原因：概念混淆、细节记不住、逻辑链条缺失、只会背原题不会迁移等。\\n· 给 2~3 条针对性复习建议，要能直接执行。\\n严格只输出一个 JSON 对象：\\n{\"summary\":\"整体诊断（80字内）\",\"groups\":[\"按主题归纳的薄弱类别，最多3条，每条30字内\"],\"reasons\":[\"共性原因，最多3条\"],\"advice\":[\"建议，2~3条，每条35字内\"]}' },\n  { g: '背书', id: 'rc.paper', n: 'AI 组卷（专项复习小卷）', tags: 'recite', vars: 'mode, n, list',\n    def: '请从这个词本里挑 {{n}} 张卡片，组成一套「{{mode}}」专项复习小卷。\\n【候选卡片（含等级与错误次数）】\\n{{list}}\\n【要求】\\n· 只从候选里挑，不要编造新卡片。\\n· 挑完给出组卷理由（一句话）。\\n严格只输出一个 JSON 对象：\\n{\"why\":\"为什么这么选（30字内）\",\"ids\":[序号,序号]}\\n其中 ids 是候选卡片前面的序号。' },\n  { g: '背书', id: 'rc.forget', n: 'AI 遗忘风险预测', tags: 'recite', vars: 'list',\n    def: '根据下面这些卡片的学习数据，判断哪些你大概率快要遗忘。\\n【卡片（序号｜等级｜错误次数｜上次复习距今）】\\n{{list}}\\n【判断依据】\\n· 上次复习越久、等级越低、错误越多，遗忘风险越高；\\n· 等级高但很久没碰的，也要提出来（熟透了也会忘）。\\n严格只输出一个 JSON 对象：\\n{\"risk\":[{\"id\":序号,\"lv\":\"高|中|低\",\"why\":\"理由（15字内）\"}]}\\n最多列 12 条，按风险从高到低。' },\n  { g: '背书', id: 'rc.plan', n: 'AI 每日背书计划', tags: 'recite', vars: 'focusMin, coin, total, weak, books',\n    def: '用户今天的学习情况：已专注 {{focusMin}} 分钟，背书消耗/获得 {{coin}} 点，词本共 {{total}} 张卡片、其中薄弱 {{weak}} 张。\\n【各词本情况】\\n{{books}}\\n【要求】\\n· 给一句今天建议背多少条（按他已投入的时间和薄弱量估，别开空头支票）。\\n· 指明优先复习哪个词本、为什么。\\n· 只做建议，不要说教，不要命令。\\n严格只输出一个 JSON 对象：\\n{\"count\":建议条数,\"book\":\"优先词本名\",\"why\":\"理由（35字内）\",\"line\":\"对他讲的一句短话（40字内）\"}' },\n  { g: '背书', id: 'rc.review', n: 'AI 每日复盘小结', tags: 'recite', vars: 'date, total, right, dictN, dictRight, weak, books, focusMin',\n    def: '为下面这一天的背书与专注数据写一段简短复盘，会嵌进每日专注报告。\\n【日期】{{date}}\\n【背书】共 {{total}} 条（答对 {{right}} 条）· 默写 {{dictN}} 条（对 {{dictRight}} 条）· 清掉薄弱 {{weak}} 张\\n【词本】{{books}}\\n【今日专注】{{focusMin}} 分钟\\n【要求】\\n· 只依据上面的数字，不要编造。\\n· 先给一句整体评价，再点出短板，最后一句明天的建议。\\n· 中文、110 字以内、说人话，不要客套。' },\n  { g: '背书', id: 'rc.pet', n: 'AI 桌宠模拟抽背', tags: 'recite', vars: 'question, answer, history',\n    def: '你在陪用户背书，现在由你抽背他。\\n【这一条要抽的（只有你知道答案）】\\n题干：{{question}}\\n答案：{{answer}}\\n【之前抽过】{{history}}\\n【要求】\\n· 用口语把题干问出来，可以加点你自己的语气和一句调侃，但问的内容要准确。\\n· 绝对不要泄露答案的任何内容，也不要给提示（他要提示会自己说）。\\n· 一次只问一条，一两句话，60 字以内。\\n· 不要提「抽背」「题库」「系统」这些词。' },\n  { g: '背书', id: 'rc.cheer', n: 'AI 个性化鼓励', tags: 'focus,companion', vars: 'done, right, wrong, dictRight, weak, name',\n    def: '用户刚背完一段。\\n【数据】背了 {{done}} 条，答对 {{right}} 条，答错 {{wrong}} 条，默写对 {{dictRight}} 条，清掉薄弱 {{weak}} 张。\\n【要求】\\n· 用你的身份说一句（1~2句，45 字内），要根据今天的真实数据说 —— 全对就痛快夸、错得多就安抚并给一个具体抓手。\\n· 答错时绝不允许打击、讽刺、说「这么简单都不会」。\\n· 不要提「数据」「条数」这些词，说人话。' }\n];\nfunction promptDef(id) { return PROMPT_DEFS.filter(p => p.id === id)[0] || null; }\nfunction promptDefault(id) { const d = promptDef(id); return d ? d.def : ''; }\nfunction promptRaw(id) {\n  const o = (S.settings && S.settings.prompts) || {};\n  return (o[id] != null && String(o[id]).trim()) ? String(o[id]) : promptDefault(id);\n}\nfunction isPromptEdited(id) { const o = (S.settings && S.settings.prompts) || {}; return o[id] != null && String(o[id]).trim() !== ''; }\nfunction promptText(id, vars) {\n  let t = promptRaw(id);\n  const v = vars || {};\n  Object.keys(v).forEach(k => { t = t.split('{{' + k + '}}').join(String(v[k] == null ? '' : v[k])); });\n  return t;\n}\nfunction promptTags(id, override) {\n  const d = promptDef(id);\n  const s = override || (d ? d.tags : '');\n  return String(s).split(/[,，\\s]+/).map(x => x.trim()).filter(Boolean);\n}\n/* ---------- 生成留档：本 APP 每一次大模型调用都记一份，可在「生成记录」里回看 ---------- */\nfunction genLogName(id) { const d = promptDef(id); return d ? d.n : id; }\nasync function logGen(rec) {\n  try {\n    const r = await DB.create(T.GEN, rec);\n    if (r) S.gen.unshift(Object.assign({ id: r.id }, rec));\n    const keep = Math.max(50, Number(cfg('genLogKeep') || 200));\n    /* ⚠️ 这里以前不分类别、从最早一条开始删 —— 语音留档（tag='voice'）也照删。\n       而语音的音频引用（ref）就存在这条记录里：记录一删，引用就没了，\n       你收藏过的那句语音也再也播不出来（收藏夹里只存了文字，救不回来）。\n       现在语音记录不参与自动清理；文字与生图指令照旧按上限回收。 */\n    let guard = 0;\n    while (S.gen.length > keep && guard++ < 800) {\n      let idx = -1;\n      for (let i = S.gen.length - 1; i >= 0; i--) {\n        if (!(S.gen[i] && S.gen[i].tag === 'voice')) { idx = i; break; }\n      }\n      if (idx < 0) break;                 // 剩下的全是语音：留着，不再删\n      const old = S.gen.splice(idx, 1)[0];\n      if (old && old.id) await DB.remove(T.GEN, old.id);\n    }\n    return r;\n  } catch (e) { console.warn('logGen', e); return null; }\n}\nasync function pGen(id, vars, charIds, tags, plain) {\n  const instruction = promptText(id, vars);\n  const t0 = Date.now();\n  let out = '', err = '';\n  try { out = await aiGen(charIds, promptTags(id, tags), instruction, genLogName(id), plain); }\n  catch (e) { err = (e && e.message) || String(e); }\n  await logGen({\n    kind: id, name: genLogName(id), tag: 'text', charIds: (charIds || []).filter(Boolean),\n    instruction: instruction, out: out || '', err: err, ms: Date.now() - t0, at: Date.now()\n  });\n  if (err) throw new Error(err);\n  return out;\n}\n/* 语音留档：记下被读出来的那句话 */\n/* 语音留档：文字 + 音频引用一起存 —— 存了引用才能之后直接复听、循环播放，不用重新合成 */\nasync function logVoice(kind, charId, text, ok, ref, name) {\n  if (!text) return null;\n  return await logGen({\n    kind: kind || 'tts', name: name || '语音朗读', tag: 'voice', charIds: charId ? [charId] : [],\n    out: text, err: ok ? '' : '播放失败（语音服务可能没配置）', ref: ref || '', at: Date.now()\n  });\n}\n/* 统一的口播出口：合成 → 存进媒体库换成引用 → 交宿主代播 → 连同引用一起留档。\n   speak() 和所有需要复听的路径都走这里，保证「说过的每一句」都能重播。 */\n/* 长文本分段合成：有些语音服务对单次合成的字数有上限，超了会只读前半段\n   （表现就是「语音听着被截断」）。这里超过 140 字就按句子切开、各自合成，\n   再把音频字节按顺序拼成一段。仅对 mp3/mpeg 拼接（其它格式退回第一段，不硬拼）。 */\nasync function ttsJoined(charId, text) {\n  const t = String(text || '').trim();\n  if (!t) return null;\n  if (t.length <= 140) {\n    try { const r = await API.voice.tts({ characterId: charId, text: t }); return (r && r.dataUrl) ? r : null; }\n    catch (e) { return null; }\n  }\n  const chunks = [];\n  let cur = '';\n  /* 按句号/问号/感叹号/分号/换行切分。这里用「捕获组 + 奇偶拼回」的写法，\n     不用后行断言（旧版 Safari 不支持），切不开就整段当一块。 */\n  let segs = [];\n  try {\n    const parts2 = t.split(/([。！？!?；;\\n])/);\n    for (let i = 0; i < parts2.length; i += 2) segs.push((parts2[i] || '') + (parts2[i + 1] || ''));\n  } catch (e) { segs = [t]; }\n  if (!segs.length) segs = [t];\n  segs.forEach(function (seg) {\n    seg = seg || '';\n    if (!seg.trim()) return;\n    if (cur && (cur.length + seg.length) > 140) { chunks.push(cur); cur = seg; }\n    else cur += seg;\n  });\n  if (cur) chunks.push(cur);\n  const parts = [];\n  for (const c of chunks) {\n    let r = null;\n    try { r = await API.voice.tts({ characterId: charId, text: c }); } catch (e) { r = null; }\n    if (!r || !r.dataUrl) return parts.length ? parts[0] : null;   // 有一段失败就不硬拼，先播能拿到的\n    parts.push(r);\n  }\n  const mime = String(parts[0].mimeType || 'audio/mpeg');\n  const canJoin = parts.every(function (x) { return /mpeg|mp3/i.test(String(x.mimeType || mime)); });\n  if (!canJoin || parts.length < 2) return parts[0];\n  try {\n    const bufs = parts.map(function (x) { return b64ToBytes(String(x.dataUrl).split(',')[1]); });\n    let total = 0;\n    bufs.forEach(function (b) { total += b.length; });\n    const all = new Uint8Array(total);\n    let off = 0;\n    bufs.forEach(function (b) { all.set(b, off); off += b.length; });\n    return { dataUrl: 'data:' + mime + ';base64,' + bytesToB64(all), mimeType: mime, joined: parts.length };\n  } catch (e) { return parts[0]; }\n}\nasync function voiceSay(charId, text, kind, name) {\n  if (!API || !API.voice || !API.voice.tts || !charId || !text) return { ok: false, ref: '' };\n  let dataUrl = '';\n  const lk = aiLock('生成语音');\n  try {\n    const r = await ttsJoined(charId, text);\n    if (r && r.dataUrl) dataUrl = r.dataUrl;\n  } catch (e) { console.warn('tts', e); }\n  finally { aiUnlock(lk); }\n  if (!dataUrl) { await logVoice(kind || 'tts', charId, text, false, '', name); return { ok: false, ref: '' }; }\n  let ref = '';\n  const put = await sdk(() => API.media.put({ dataUrl: dataUrl }), null);\n  if (put && put.ref) ref = put.ref;\n  let ok = false;\n  try { await API.voice.play({ dataUrl: ref || dataUrl }); ok = true; } catch (e) { ok = false; }\n  const rec = await logVoice(kind || 'tts', charId, text, ok, ref, name);\n  /* 音频到手就把「复听 / 循环」按钮挂回聊天框那一条 —— 不用再跑去生成记录里翻 */\n  if (ref && attachRefToMsg(charId, text, ref)) {\n    await saveSession();\n    try { await saveSleepSession(); } catch (e) { }   // 睡前闲聊/哄睡语也要把引用一起存下来，重开 APP 还能复听\n    refreshMsgVoice();\n  }\n  return { ok: ok, ref: ref, id: (rec && rec.id) || '' };\n}\nasync function voiceSpeak(charId, text, kind, name) {\n  const r = await voiceSay(charId, text, kind, name);\n  return r.ok;\n}\n/* ---------- 语音留档的复听与循环 ---------- */\n/* 两句之间的气口（毫秒）：原来写死在代码里，现在可以在「我的 → 通知与同步」里调 */\nfunction voiceGap() {\n  const raw = cfg('voiceGapMs');\n  if (raw == null || raw === '') return 700;\n  return clamp(Math.round(Number(raw)) || 700, 200, 5000);\n}\nfunction voiceLogs() {\n  return (S.gen || []).filter(x => x && x.tag === 'voice').sort((a, b) => (b.at || 0) - (a.at || 0));\n}\nfunction genById(id) { return (S.gen || []).find(x => String(x.id) === String(id)) || null; }\nasync function playVoiceRefOnce(ref) {\n  if (!ref || !API || !API.voice || !API.voice.play) return false;\n  try { await API.voice.play({ dataUrl: ref }); return true; } catch (e) { return false; }\n}\n/* 循环播放：单条循环，或把一整列按顺序循环。再次点循环会切到新的队列并从头播。 */\nlet voiceLoopRunning = false;\nasync function voiceLoopStart(refs, label, fromIdx) {\n  const list = (refs || []).filter(Boolean);\n  if (!list.length) { toast('这条没有留存音频，没法复听（可能当时语音服务没配好）'); return; }\n  S.voiceLoop = { refs: list, i: clamp(Number(fromIdx) || 0, 0, list.length - 1), label: label || '' };\n  render();\n  if (voiceLoopRunning) return;\n  voiceLoopRunning = true;\n  while (S.voiceLoop) {\n    const cur = S.voiceLoop;\n    const ref = cur.refs[cur.i % cur.refs.length];\n    const ok = await playVoiceRefOnce(ref);\n    if (!ok) { toast('播不出来：先在「设置 → 语音」里配好语音服务'); S.voiceLoop = null; break; }\n    if (!S.voiceLoop) break;\n    const now2 = S.voiceLoop;\n    if (now2.refs === cur.refs && now2.i === cur.i) now2.i = now2.refs.length > 1 ? (cur.i + 1) % now2.refs.length : 0;\n    paintVoiceLoop();\n  }\n  voiceLoopRunning = false;\n  render();\n}\nfunction voiceLoopStop() {\n  const wasChat = !!(S.voiceLoop && (S.voiceLoop.msgAt || S.voiceLoop.chatAll));\n  S.voiceLoop = null; stopVoice();\n  if (wasChat) renderKeepChat(); else render();   // 聊天框/本场循环：停掉后把滚动条留在底部\n}\nfunction paintVoiceLoop() {\n  try {\n    document.querySelectorAll('[data-vloop]').forEach(el => {\n      el.textContent = S.voiceLoop ? ('正在循环 ' + (S.voiceLoop.i + 1) + '/' + S.voiceLoop.refs.length + (S.voiceLoop.label ? ' · ' + S.voiceLoop.label : '')) : '';\n    });\n  } catch (e) { }\n}\n/* 生图留档包装：把调用与结果记进生成记录，再原样返回/抛错 */\nasync function genImgLogged(kind, name, prompt, charId, fn, noLock) {\n  const t0 = Date.now();\n  let out = '', err = '';\n  const lk = noLock ? false : aiLock('生成图片');   // 生图期间锁住按钮；noLock=true 用于后台自动生成（不打断用户）\n  try {\n    const r = await fn();\n    // 生图的「有效产出」就是这条生图提示词本身（图存在媒体库/壁纸库里）\n    if (r && r.dataUrl) out = prompt;\n    else { out = prompt; err = '接口没有返回图片'; }\n    await logGen({ kind: kind, name: name, tag: 'image', charIds: charId ? [charId] : [], instruction: prompt, out: out, err: err, ms: Date.now() - t0, at: Date.now() });\n    return r;\n  } catch (e) {\n    err = (e && e.message) || String(e);\n    await logGen({ kind: kind, name: name, tag: 'image', charIds: charId ? [charId] : [], instruction: prompt, out: '', err: err, ms: Date.now() - t0, at: Date.now() });\n    throw e;\n  } finally {\n    aiUnlock(lk);\n  }\n}\nasync function speak(charId, text, kind, name) {\n  return await voiceSpeak(charId, text, kind, name);\n}\nfunction stopVoice() {\n  if (S.voiceLoop) S.voiceLoop = null;   // 手动停：顺便把循环也停掉，免得它自己又播回来\n  sdk(() => API.voice.stopPlayback({}));\n}\nfunction notify(title, body) {\n  if (!cfg('notif')) return;\n  sdk(() => API.notifications.create({ title: title, body: body }));  // 不设置图标角标\n}\nfunction clearBadge() { sdk(() => API.notifications.clearBadge()); }\n/* ---------- 设置 ---------- */\nfunction defaults() {\n  return {\n    charIds: [], punishEnabled: true, punishTrigger: { leave: true, timeout: true, untimed: true },\n    graceSec: 8, focusMin: 25, breakMin: 5, cycles: 4, msgGapMin: 8,\n    punishLib: [\n      { id: 'p_pay', kind: 'pay', title: '给陪伴角色转账 10000 元', detail: '打开钱包把钱转给陪伴你的角色', amount: 10000, enabled: true },\n      { id: 'p_quiz', kind: 'quiz', title: '完成指定数量练习题', detail: '答题正确率达标后才能解锁', count: 20, ratio: 80, enabled: true },\n      { id: 'p_gift', kind: 'gift', title: '给角色购买指定礼物', detail: '买一件礼物送给角色', gift: '一束向日葵', price: 199, enabled: true },\n      { id: 'p_txt', kind: 'txt', title: '抄写一句规矩 3 遍', detail: '抄完粘贴提交，标点与空格不计入字数', text: '想清楚再开始，比开始了再想更快。', count: 3, enabled: true },\n      { id: 'p_essay', kind: 'essay', title: '写一段反思', detail: '写清楚这次为什么分心、下次怎么避免', minWords: 200, enabled: true },\n      { id: 'p_act', kind: 'act', title: '做完一件小事', detail: '做完回来点「我做到了」', actName: '喝一杯温水，再做 20 个深蹲', enabled: true },\n      { id: 'p_checkin', kind: 'checkin', title: '限时打卡', detail: '按间隔回来点一次「我在」，证明你不是又跑了', checkinMin: 20, checkinGap: 5, checkinCount: 4, enabled: true }\n    ],\n    punishTexts: ['这就是你说的\"再学十分钟\"吗？', '我数到三，惩罚开始。', '你自己选的规矩，别怪我不客气。'],\n    whitelist: [{ name: '词典', note: '查词' }],\n    alarm: { time: '07:00', repeat: true, volume: 70, enabled: false, charId: '' },\n    story: { style: '温柔治愈', minutes: 10, charId: '' },\n    notif: true, syncChat: false, voiceMode: 'cue', voiceGapMs: 700,\n    sleepChatVoice: true,\n    quizFocus: '', quizFocusMode: 'focus',\n    reviewQuestions: 3, passRatio: 80, quizSource: 'ai', reviewSource: 'ai', askedQ: [],\n    masteryNeed: 3, bankCats: [], punishCat: '',\n    quizMixSrc: { fresh: 1, wrong: 1, bank: 1 },\n    quizMixKind: { choice: 1, fill: 1, multi: 1, tf: 1 },\n    reviewEvery: 'focus', wallStyle: 'gaze', sleepWallStyle: 'calm',\n    punishAutoSec: 300, punishAutoRun: false, mistakeFolders: [], qaMode: 'assistant', qaMode: 'plain',\n    sleepMode: '午睡', sleepMinutes: 30,\n    albumQuizCount: 3, sleepValidHours: 4, sleepStreakMiles: [3, 7, 14, 30], claimedStreak: 0,\n    rewardKinds: ['gift', 'pay', 'redpack', 'act'], rewardGiftPrice: 199, rewardPayAmount: 520,\n    rewardPackAmount: 88, rewardWallpaper: true, rewardEveryRounds: 3, rewardOnStreak: true,\n    rewardAskStyle: 'card', prompts: {}, sleepWallBg: true,\n    /* 壁纸总开关 + 自定义壁纸 + 变化幅度 */\n    wallGenOff: false,        // true = 彻底不生成任何壁纸（专注/睡眠/奖励全停）\n    customWall: '',           // 用户自己上传的壁纸（dataUrl），铺全局\n    customWallRef: '',        // 存在媒体库时的引用\n    customWallUse: false,     // 是否启用\n    wallGenWithCustom: false, // 用自定义壁纸的同时仍让 AI 生成壁纸（默认关：开了自定义壁纸就暂停生图，省额度）\n    wallVary: true,           // 生成时随机加构图/光线变化，降低重复感\n    sleepCharIds: [], sleepLullaby: true, sleepChat: true, genLogKeep: 200, sleepIdleMin: 5,\n    apptAdvanceMin: 10, apptGapMin: 5, apptMaxNudge: 3, apptGraceMin: 0, apptChatNudge: true, apptPunish: true,\n    apptSysAlarm: true,      /* 预约时借系统时钟立闹钟（APK）：页面被杀也准时响；网页环境自动跳过 */\n    focusLevel: 'off',       /* 锁机分级：off=不开启 / L1=提醒锁 / L2=看守锁 / L3=承诺死锁 */\n    lockedApps: [],          /* 常驻白名单 [{name, pkg}] —— L2 看守锁按包名放行 + 中途离开豁免依据 */\n    focusAssist: false,      /* 兼容旧字段：L1 的勿扰开关（新逻辑读 focusLevel） */\n    lockCooldownSec: 60,     /* L3 暂停冷静期秒数 */\n    assistDndOn: false,      /* 本场专注由锁机助手开过勿扰 —— 结束后自动恢复 */\n    goals: [], goalShow: true, focusPresets: [],\n    wishes: [], wishNeedMin: 600, wishConnect: true, wishPenalty: 50, wishNotice: true, selfTaskConnect: true,\n    coinRate: 1, coinBonus: 20, coinBalance: 0, coinLog: [], freePass: 0, pardonDate: '',\n    /* 违规扣专注币：默认关。打开后按下面填的数值额外扣币（0 = 这一类不扣）。\n       这是「叠加」不是「替代」：原有的惩罚照旧执行，扣币加在上面。\n       余额允许扣成负数（coinAdd 已经不夹 0）。 */\n    coinDeduct: { on: false, miss: 50, leave: 0, fail: 0, timeout: 0 },\n    noteLimit: 3, noteRestMin: 5, noteRewardKinds: ['rest', 'wall', 'voice'], noteLullaby: true,\n    noteLinkFocus: true, noteLinkSleep: true,\n    morning: { enabled: false, time: '07:00', charId: '', voice: true },\n    noteLimit: 3, noteRestMin: 5, noteRewardKinds: ['rest', 'wall', 'voice'], noteLullaby: true,\n    noteLinkFocus: true, noteLinkSleep: true,\n    lastMorningFired: '', periodReports: [], reportKeep: 20\n  };\n}\nfunction cfg(k) { return (S.settings || {})[k]; }\nasync function loadSettings() {\n  const rows = await DB.list(T.SET);\n  /* ⚠️ 以前只取 rows[0]。如果设置表因为某次写入失败而留下多行，\n     读回来的就是「旧的那一行」—— 表现就是「改了/用了的东西，重开又变回去」\n     （免罚卡「用了一张还剩一张」很可能就是这一类）。\n     现在：多行时保留内容最全的那一行，其余删掉，并把它定为当前行。 */\n  let row = rows[0];\n  if (rows.length > 1) {\n    let best = row, bestLen = -1;\n    rows.forEach(r => {\n      const n = JSON.stringify((r && r.data) || {}).length;\n      if (n > bestLen) { bestLen = n; best = r; }\n    });\n    row = best;\n    for (const r of rows) {\n      if (!r || String(r.id) === String(row.id)) continue;\n      await DB.remove(T.SET, r.id);\n    }\n    console.warn('[settings] 发现 ' + rows.length + ' 行设置，已保留内容最全的一行、清掉多余的');\n  }\n  if (row) { S.settingId = row.id; S.settings = Object.assign(defaults(), row.data || {}); }\n  else { S.settings = defaults(); const r = await DB.create(T.SET, { data: S.settings }); if (r) S.settingId = r.id; }\n  ['punishLib', 'whitelist', 'punishTexts', 'charIds', 'rewardKinds', 'sleepStreakMiles', 'goals', 'periodReports', 'wishes'].forEach(k => {\n    if (!Array.isArray(S.settings[k])) S.settings[k] = defaults()[k];\n  });\n  if (!Array.isArray(S.settings.wishes)) S.settings.wishes = [];\n  if (!Array.isArray(S.settings.mistakeFolders)) S.settings.mistakeFolders = [];\n  if (!Array.isArray(S.settings.coinLog)) S.settings.coinLog = [];\n  if (!S.settings.morning || typeof S.settings.morning !== 'object') S.settings.morning = defaults().morning;\n  /* punishTrigger 三个开关逐项补默认值：老存档若只存了半截（比如只有 timeout），\n     合并时会把 leave 丢掉，导致「中途离开」永远不触发 —— 这里补齐，缺项按默认开启 */\n  {\n    const dft = defaults().punishTrigger;\n    const cur = S.settings.punishTrigger;\n    S.settings.punishTrigger = {\n      leave: (cur && cur.leave != null) ? !!cur.leave : dft.leave,\n      timeout: (cur && cur.timeout != null) ? !!cur.timeout : dft.timeout,\n      untimed: (cur && cur.untimed != null) ? !!cur.untimed : dft.untimed\n    };\n  }\n  if (!S.settings.prompts || typeof S.settings.prompts !== 'object' || Array.isArray(S.settings.prompts)) S.settings.prompts = {};\n  /* 2026-11 默认变更：专注陪伴的逐句消息不再写进线上聊天室，避免刷屏。\n     老存档默认是 true，这里一次性迁到 false；用户仍可在设置里手动打开。 */\n  if (S.settings.syncChatDefaultV2 !== true) {\n    if (S.settings.syncChat === true) S.settings.syncChat = false;\n    S.settings.syncChatDefaultV2 = true;\n  }\n  if (S.settings.masteryNeed == null) S.settings.masteryNeed = 3;\n  if (!Array.isArray(S.settings.bankCats)) S.settings.bankCats = [];\n  if (S.settings.punishCat == null) S.settings.punishCat = '';\n  ['quizMixSrc', 'quizMixKind'].forEach(k => {\n    const dft = { fresh: 1, wrong: 1, bank: 1 };\n    const dk = { fresh: 1, wrong: 1, bank: 1, choice: 1, fill: 1, multi: 1, tf: 1 };\n    const base = (k === 'quizMixSrc') ? dft : dk;\n    const cur = S.settings[k];\n    S.settings[k] = Object.assign({}, base, (cur && typeof cur === 'object' && !Array.isArray(cur)) ? cur : {});\n  });\n  if (S.settings.sleepChatVoice == null) S.settings.sleepChatVoice = true;\n  if (!S.settings.rewardAskStyle) S.settings.rewardAskStyle = 'card';\n  if (!S.settings.rewardGiftPrice) S.settings.rewardGiftPrice = 199;\n  /* 纸条联动从「一个开关管两处」拆成两个（专注 / 哄睡各管各的）。\n     老存档只有 noteLullaby：按它当时的值给两个新开关定初值，行为不变。 */\n  {\n    const rawNote = (row && row.data) || {};\n    if (rawNote.noteLinkFocus == null) S.settings.noteLinkFocus = rawNote.noteLullaby !== false;\n    if (rawNote.noteLinkSleep == null) S.settings.noteLinkSleep = rawNote.noteLullaby !== false;\n  }\n}\nlet saveTimer = null;\nfunction saveSettings(now) {\n  if (saveTimer) { clearTimeout(saveTimer); saveTimer = null; }\n  const run = async () => {\n    const data = JSON.parse(JSON.stringify(S.settings));\n    if (S.settingId) await DB.update(T.SET, S.settingId, { data: data });\n    else {\n      const r = await DB.create(T.SET, { data: data });\n      if (r) S.settingId = r.id;\n      /* 兜底：万一之前漏了 id 又建过新行，这里把除了当前行之外的设置行清掉，\n         避免下次打开读到旧的那一行（改动看起来「没存住」）。 */\n      try {\n        const rows = await DB.list(T.SET);\n        for (const x of rows) {\n          if (!x || String(x.id) === String(S.settingId)) continue;\n          await DB.remove(T.SET, x.id);\n        }\n      } catch (e) { }\n    }\n  };\n  if (now) return run();\n  saveTimer = setTimeout(run, 400);\n}\n/* ---------- 角色 ---------- */\nfunction charById(id) { return (S.chars || []).find(x => x.id === id) || null; }\nfunction charName(id) { const c = charById(id); return c ? c.name : '角色'; }\nfunction pickColor(seed) {\n  let h = 0; for (let i = 0; i < String(seed).length; i++) h = (h * 31 + String(seed).charCodeAt(i)) % 360;\n  return `linear-gradient(135deg,hsl(${h} 62% 58%),hsl(${(h + 48) % 360} 62% 46%))`;\n}\nfunction charAvatar(c, cls) {\n  cls = cls || 'avatar';\n  if (!c) return `<div class=\"${cls}\" style=\"background:#2a3145\">?</div>`;\n  /* 头像字段各家宿主的命名不一样，全部兼容；相对路径 / blob 也要认（不然换成新头像也不显示） */\n  const url = c.avatar || c.avatarUrl || c.avatarURL || c.avatar_url || c.head || c.headUrl || c.headURL\n    || c.icon || c.iconUrl || c.image || c.imageUrl || c.portrait || c.face || c.photo || '';\n  if (url && /^(https?:|data:|blob:|file:|\\/\\/|\\/)/.test(String(url))) return `<div class=\"${cls}\"><img src=\"${esc(url)}\" alt=\"\" loading=\"lazy\"></div>`;\n  return `<div class=\"${cls}\" style=\"background:${pickColor(c.id || c.name || '?')}\">${esc((c.name || '?').slice(0, 1))}</div>`;\n}\nasync function reloadChars(silent) {\n  try { await loadChars(); } catch (e) { }\n  if (!silent) toast(S.chars.length ? '已刷新 ' + S.chars.length + ' 位角色（含最新头像）' : '没有读到角色');\n  render();\n  return S.chars;\n}\nasync function loadChars() {\n  const l = await sdk(() => API.characters.list(), []);\n  S.chars = Array.isArray(l) ? l : ((l && l.characters) || []);\n}\nfunction activeChars() {\n  const sess = (S.session && S.session.charIds) || [];\n  const focusIds = cfg('charIds') || [];\n  const sleepIds = cfg('sleepCharIds') || [];\n  const ids = sess.length ? sess : (focusIds.length ? focusIds : sleepIds);\n  const arr = ids.map(charById).filter(Boolean);\n  return arr.length ? arr : (S.chars || []).slice(0, 1);\n}\nfunction anyCharId() { const a = activeChars(); return a.length ? a[0].id : ((S.chars[0] && S.chars[0].id) || ''); }\nfunction pickOneChar(ids) {\n  const pool = (ids && ids.length) ? ids : (cfg('charIds') || []);\n  const list = pool.filter(id => charById(id));\n  if (!list.length) return anyCharId();\n  return list[Math.floor(Math.random() * list.length)];\n}\n/* ---------- 提示与弹窗 ---------- */\nfunction toast(msg) {\n  const host = $('#toastHost'); if (!host) return;\n  const el = document.createElement('div');\n  el.className = 'toast'; el.textContent = msg;\n  host.appendChild(el);\n  setTimeout(() => { el.style.transition = '.3s'; el.style.opacity = '0'; setTimeout(() => el.remove(), 320); }, 2200);\n}\nlet modalStack = [];\nfunction openSheet(html) {\n  const host = $('#modalHost');\n  const wrap = document.createElement('div');\n  wrap.className = 'mask';\n  wrap.innerHTML = `<div class=\"sheet\">${html}</div>`;\n  wrap.addEventListener('click', e => { if (e.target === wrap) closeSheet(wrap); });\n  host.appendChild(wrap); modalStack.push(wrap);\n  return wrap;\n}\nfunction closeSheet(el) {\n  const t = el || modalStack[modalStack.length - 1];\n  if (!t) return;\n  t.remove(); modalStack = modalStack.filter(x => x !== t);\n}\nfunction closeAllSheets() { modalStack.forEach(m => m.remove()); modalStack = []; }\nfunction confirmBox(title, message, okLabel) {\n  return new Promise(resolve => {\n    const w = openSheet(`<h3>${esc(title)}</h3><div class=\"sub\" style=\"margin-bottom:14px\">${esc(message || '')}</div>\n      <div class=\"row\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-cf=\"no\">取消</button>\n      <button class=\"btn primary grow\" data-cf=\"yes\">${esc(okLabel || '确定')}</button></div>`);\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-cf]'); if (!b) return;\n      closeSheet(w); resolve(b.dataset.cf === 'yes');\n    });\n  });\n}\n/* ==========================================================\n   AI 生成锁：AI 只要开始跑，按钮就点不动 —— 直到这次生成完成\n   · 底层统一上锁：文本生成 / 生图 / 语音合成都走 aiLock / aiUnlock\n   · 拦下时给一句提示，不会「点了没反应」\n   · 导航类动作（返回、切页、关弹窗、改设置）不拦，避免把自己锁死\n   · 兜底：单次生成超过 3 分钟没回来就自动解锁，防止永久卡住\n   · 后台自动发生的生成（角色定时说话、领任务）用 quietOn 标记，不锁你\n   ========================================================== */\nlet aiRunN = 0, aiRunLabel = '', aiRunAt = 0, aiRunTimer = null, aiQuiet = 0;\nconst AI_NAV_ACTS = ['closeSheet', 'closeAllSheets', 'back', 'gotoView', 'tab', 'hubTab', 'reload',\n  'setDraft', 'toggleSetting', 'toggleTrigger', 'permCheck', 'permCheckRaw', 'favOpen', 'albumClose',\n  'gotoSetup', 'openLock', 'checkNotifPerm', 'openPromptEdit', 'fpManage', 'hubTabOpen'];\nfunction quietOn() { aiQuiet++; }\nfunction quietOff() { aiQuiet = Math.max(0, aiQuiet - 1); }\nfunction aiWorking() { return aiRunN > 0; }\n/* 返回 true 表示这次真的上了锁 —— 只有真锁上才需要解锁，避免把别的锁误放开 */\nfunction aiLock(label) {\n  if (aiQuiet) return false;\n  aiRunN++; aiRunLabel = label || aiRunLabel || '生成内容'; aiRunAt = Date.now();\n  paintAiBusy();\n  if (!aiRunTimer) aiRunTimer = setInterval(() => {\n    if (aiRunN <= 0) return;\n    if (Date.now() - aiRunAt > 180000) { aiRunN = 0; aiRunLabel = ''; paintAiBusy(); }   // 兜底解锁\n  }, 5000);\n  return true;\n}\nfunction aiUnlock(locked) {\n  if (!locked) { paintAiBusy(); return; }\n  aiRunN = Math.max(0, aiRunN - 1);\n  if (!aiRunN) {\n    aiRunLabel = '';\n    if (aiRunTimer) { clearInterval(aiRunTimer); aiRunTimer = null; }\n  }\n  paintAiBusy();\n}\nfunction paintAiBusy() {\n  try {\n    let el = document.getElementById('aiBusyBar');\n    if (!aiWorking()) { if (el) el.remove(); return; }\n    if (!el) {\n      el = document.createElement('div');\n      el.id = 'aiBusyBar';\n      el.style.cssText = 'position:fixed;left:0;right:0;bottom:calc(var(--ai-phone-app-safe-bottom,20px) + 126px);z-index:95;display:flex;justify-content:center;pointer-events:none;padding:0 14px';\n      (document.body || document.documentElement).appendChild(el);\n    }\n    el.innerHTML = '<div style=\"background:rgba(28,34,50,.96);border:1px solid rgba(124,140,255,.55);color:#dfe4ff;'\n      + 'font:12px/1.6 -apple-system,BlinkMacSystemFont,sans-serif;padding:7px 14px;border-radius:999px;'\n      + 'box-shadow:0 8px 24px -10px #000;display:flex;align-items:center;gap:7px\">'\n      + '<span class=\"spin\"></span> 正在' + esc(aiRunLabel) + '…完成前先别点别的</div>';\n  } catch (e) { }\n}\n/* ---------- 视图框架 ---------- */\nconst VIEWS = {}, ACTIONS = {};\n/* v1.9.2 校验标记 L */\nconst TITLES = {\n  home: ['专注', 'FOCUS'], sleep: ['睡眠', 'SLEEP'], stats: ['数据', 'STATS'], me: ['我的', 'SETTINGS'],\n  setup: ['专注设置', 'SET UP'], running: ['专注中', 'FOCUSING'], review: ['专注校验', 'CHECK'],\n  reward: ['壁纸奖励', 'REWARD'], weak: ['私密学习记忆', 'PRIVATE MEMORY'], story: ['睡前故事', 'STORY'],\n  alarm: ['语音闹钟', 'ALARM'], roles: ['陪伴角色', 'COMPANIONS'], qbank: ['题库', 'QUESTION BANK'],\n  mistakes: ['错题本', 'MISTAKE BOOK'], gifts: ['礼物图鉴', 'GIFT BOOK'], ledger: ['账本', 'LEDGER'],\n  calendar: ['打卡日历', 'CALENDAR'], help: ['帮助中心', 'HELP'], album: ['壁纸库', 'GALLERY'],\n  unlockquiz: ['答题解锁', 'UNLOCK'], rewards: ['奖励中心', 'REWARDS'], sleepreport: ['睡眠报告', 'SLEEP REPORT'],\n  prompts: ['提示词设置', 'PROMPTS'], genlog: ['生成记录', 'AI LOG'], fav: ['收藏夹', 'STARRED'],\n  promptedit: ['改提示词', 'PROMPT'], qa: ['答疑助手', 'TUTOR'],\n  appt: ['预约专注', 'APPOINTMENT'], bond: ['心愿', 'WISH'], coin: ['专注币', 'FOCUS COIN'],\n  goals: ['目标与倒计时', 'GOALS'], periodrep: ['学习报告', 'REPORTS'], trend: ['专注趋势', 'TREND'],\n  invite: ['邀请', 'INVITE'], todos: ['待办清单', 'TO-DO'], invites: ['TA 的邀请', 'FROM TA'],\n  plan: ['计划与邀请', 'PLAN'], learn: ['学习档案', 'STUDY FILE'], motiv: ['激励中心', 'MOTIVATION'],\n  insight: ['报告与趋势', 'INSIGHTS'], prize: ['奖励与账本', 'REWARDS'], content: ['内容库', 'LIBRARY'],\n  missed: ['失约说明', 'MISSED'], checks: ['专注校验记录', 'CHECKS'], bottle: ['星星瓶', 'STAR JAR'],\n  qa: ['学习助手', 'STUDY HELPER'], promptedit: ['改提示词', 'EDIT PROMPT'],\n  recite: ['背书', 'RECITE'], rcbooks: ['背书', 'RECITE'], rcbook: ['词本详情', 'WORD BOOK'],\n  rcsession: ['背诵中', 'RECITING'], rcweak: ['薄弱专项', 'WEAK CARDS'],\n  rcstats: ['背书统计', 'RECITE STATS'], rcimport: ['批量导入', 'IMPORT'], rccard: ['编辑卡片', 'CARD']\n};\n/* ---------- 分组页：把同一类事合到一页，页顶用标签切换 ----------\n   目的：功能不再是一堆散页 —— 每个入口都落进「一类事」里；\n   首页与「我的」只留少数几个大类入口，重复的入口收掉。\n   子页名不变（壁纸库/错题本/… 照旧能被链接到），只是统一归到所属分组。 */\nconst HUBS = {\n  plan:    { n: ['计划与邀请', 'PLAN'],      tabs: [['appt', '🗓 预约专注'], ['todos', '📝 待办'], ['invites', '💌 TA 的邀请']], def: 'appt' },\n  learn:   { n: ['学习档案', 'STUDY FILE'],  tabs: [['qa', '❓ 学习助手'], ['mistakes', '📕 错题本'], ['qbank', '📚 题库'], ['weak', '🔒 私密记忆']], def: 'qa' },\n  motiv:   { n: ['激励中心', 'MOTIVATION'],  tabs: [['bond', '💞 心愿'], ['coin', '🪙 专注币'], ['goals', '🎯 目标']], def: 'bond' },\n  insight: { n: ['报告与趋势', 'INSIGHTS'],  tabs: [['periodrep', '📈 学习报告'], ['trend', '📊 专注趋势'], ['checks', '✅ 专注校验'], ['calendar', '📅 打卡日历']], def: 'periodrep' },\n  prize:   { n: ['奖励与账本', 'REWARDS'],   tabs: [['rewards', '🎁 奖励'], ['gifts', '🎁 礼物图鉴'], ['ledger', '🧾 账本']], def: 'rewards' },\n  content: { n: ['内容库', 'LIBRARY'],       tabs: [['album', '🖼 壁纸'], ['genlog', '🧾 生成记录'], ['fav', '⭐ 收藏夹'], ['bottle', '⭐ 星星瓶']], def: 'album' },\n  recite:  { n: ['背书', 'RECITE'],           tabs: [['rcbooks', '📖 词本'], ['rcweak', '🔥 薄弱专项'], ['rcstats', '📊 统计']], def: 'rcbooks' }\n};\nconst HUB_OF = {};\nObject.keys(HUBS).forEach(k => HUBS[k].tabs.forEach(t => { HUB_OF[t[0]] = k; }));\n/* 把「答疑助手」挂进学习档案（页顶标签切换，不必占首页位置） */\n(function () {\n  try {\n    const has = HUBS.learn.tabs.filter(t => t[0] === 'qa').length > 0;\n    if (!has) HUBS.learn.tabs.splice(2, 0, ['qa', '❓ 答疑助手']);\n    HUB_OF['qa'] = 'learn';\n  } catch (e) { }\n})();\nfunction hubTab(k) { return S.draft['hub_' + k] || HUBS[k].def; }\nfunction hubHeadHTML(k) {\n  const cur = hubTab(k);\n  return `<div class=\"card tight hubbar\"><div class=\"row wrap\" style=\"gap:6px\">\n    ${HUBS[k].tabs.map(([v, lb]) => `<button class=\"chip ${cur === v ? 'on' : ''}\" data-act=\"hubTab\" data-hub=\"${k}\" data-v=\"${v}\">${lb}</button>`).join('')}\n  </div></div>`;\n}\nfunction render() {\n  if (S.lock) { renderLock(); return; }\n  /* 先把当前滚动位置记下来，重绘后放回去 —— 答题点选项、勾任务这类「就地更新」\n     不会再被弹回页面顶部。切页仍走 go()，它会在 render 之后显式滚到顶部。 */\n  const keepY = (typeof window !== 'undefined') ? (window.scrollY || window.pageYOffset || 0) : 0;\n  /* 记下当前正在输入的框：重绘后要把焦点与光标放回去 ——\n     否则「边打字边刷新」的搜索框会每输入一个字就失焦、光标跳到开头。 */\n  const _act = (typeof document !== 'undefined') ? document.activeElement : null;\n  const _focusKey = (_act && _act.dataset && _act.dataset.in) ? _act.dataset.in : '';\n  let _selA = null, _selB = null;\n  try { if (_act && _act.selectionStart != null) { _selA = _act.selectionStart; _selB = _act.selectionEnd; } } catch (e) { }\n  let html = '';\n  try {\n    if (HUBS[S.view]) html = hubHeadHTML(S.view) + (VIEWS[hubTab(S.view)] || VIEWS.home)();\n    else html = (VIEWS[S.view] || VIEWS.home)();\n  } catch (e) { html = `<div class=\"card\"><h3>页面出错了</h3><div class=\"sub\">${esc((e && e.message) || e)}</div></div>`; }\n  $('#view').innerHTML = html;\n  if (keepY > 0) {\n    try {\n      window.scrollTo(0, keepY);\n      if (Math.abs((window.scrollY || 0) - keepY) > 8) requestAnimationFrame(function () { try { window.scrollTo(0, keepY); } catch (e) { } });\n    } catch (e) { }\n  }\n  if (S.view === 'running') { try { renderRunLight(); } catch (e) { } }\n  /* 背诵页：每次重画都按当前设置重启思考倒计时（切到下一张要重新计时） */\n  try { if (typeof rcRestartTimerIfNeeded === 'function') rcRestartTimerIfNeeded(); } catch (e) { }\n  document.body.classList.toggle('sleep-theme', ['sleep', 'story', 'alarm', 'sleepreport'].indexOf(S.view) >= 0);\n  const nb = document.getElementById('navBack');\n  if (nb) nb.style.display = (['home', 'recite', 'sleep', 'stats', 'me'].indexOf(S.view) >= 0) ? 'none' : 'grid';\n  const t = TITLES[S.view] || TITLES.home;\n  $('#tbTitle').textContent = t[0]; $('#tbSub').textContent = t[1];\n  renderWall();\n  renderTabs();\n  /* 焦点归位：把光标放回原来那个输入框的同一位置 */\n  if (_focusKey) {\n    try {\n      const el2 = document.querySelector('[data-in=\"' + _focusKey.replace(/\"/g, '\\\\\"') + '\"]');\n      if (el2) {\n        el2.focus();\n        if (_selA != null && el2.setSelectionRange) { try { el2.setSelectionRange(_selA, _selB == null ? _selA : _selB); } catch (e) { } }\n      }\n    } catch (e) { }\n  }\n  if (S.view === 'album' || (S.view === 'content' && hubTab('content') === 'album')) setTimeout(fillAlbumImages, 40);\n  if (S.view === 'sleep') setTimeout(() => {\n    fillSleepWall();\n    const b = document.getElementById('sleepMsgBox');\n    if (b) b.scrollTop = b.scrollHeight;\n  }, 40);\n}\nfunction renderTabs() {\n  /* 背书现在是顶层入口：专注 / 背书 / 睡眠 / 数据 / 我的 */\n  const items = [['study', '🌱', '专注', 'home'], ['recite', '📖', '背书', 'recite'], ['sleep', '🌙', '睡眠', 'sleep'], ['stats', '📊', '数据', 'stats'], ['me', '⚙️', '我的', 'me']];\n  $('#tabbar').innerHTML = items.map(([k, ic, lb, view]) =>\n    `<button class=\"tab ${S.view === view ? 'on' : ''}\" data-act=\"tab\" data-tab=\"${k}\" data-view=\"${view}\">\n      <span class=\"ic\">${ic}</span><span>${lb}</span></button>`).join('');\n  $('#tabbar').style.display = S.lock ? 'none' : 'flex';\n}\nfunction go(view, opt) {\n  const hub = HUB_OF[view];\n  if (hub) { S.draft['hub_' + hub] = view; view = hub; }   // 子页统一归到所属分组页\n  if (!opt || !opt.back) { if (S.view !== view) S.navHistory.push(S.view); }\n  S.view = view;\n  if (opt && opt.tab) S.tab = opt.tab;\n  render(); window.scrollTo(0, 0);\n}\nfunction back(fallback) { go(S.navHistory.pop() || fallback || 'home', { back: true }); }\n/* ---------- 事件 ---------- */\ndocument.addEventListener('click', e => {\n  const el = e.target.closest('[data-act]'); if (!el) return;\n  const fn = ACTIONS[el.dataset.act]; if (!fn) return;\n  e.preventDefault();\n  if (aiWorking() && AI_NAV_ACTS.indexOf(el.dataset.act) < 0) {\n    toast('正在' + (aiRunLabel || '生成内容') + '，完成了再操作');\n    return;\n  }\n  try { fn(el, e); } catch (err) { console.error(err); toast((err && err.message) || '操作失败'); }\n});\nfunction readInput(el) {\n  if (el.type === 'checkbox') return el.checked;\n  let v = el.value;\n  if (el.dataset.num === '1') v = Number(v) || 0;\n  return v;\n}\nfunction setDraftPath(key, val) {\n  if (!key) return;\n  if (key.indexOf('.') < 0) { S.draft[key] = val; return; }\n  const parts = key.split('.'); let cur = S.draft;\n  for (let i = 0; i < parts.length - 1; i++) { const p = parts[i]; if (cur[p] == null) cur[p] = {}; cur = cur[p]; }\n  cur[parts[parts.length - 1]] = val;\n}\nlet liveSearchTimer = null;\n/* 实时搜索：180ms 防抖，避免每敲一个字就重绘一次整页。\n   重绘后光标位置由 render() 里的「焦点恢复」保住，不会跳走。 */\nfunction liveSearchTick() {\n  if (liveSearchTimer) clearTimeout(liveSearchTimer);\n  liveSearchTimer = setTimeout(function () {\n    liveSearchTimer = null;\n    try { render(); } catch (e) { }\n  }, 180);\n}\nfunction onFieldChange(e) {\n  const el = e.target.closest('[data-in]'); if (!el) return;\n  const k = el.dataset.in;\n  const v = readInput(el);\n  /* 默写草稿：一张卡片存一份 —— 切到下一张时输入框跟着换，翻回上一张还看得到刚才写的。\n     以前这个 textarea 没有 data-in，打的字从来没存下来，\n     S.draft.rcDictText 一直停在「上次提交时」的值，所以换卡后框里还留着上一题的答案。 */\n  if (k.indexOf('rcdict.') === 0) {\n    S.draft.rcDictBy = S.draft.rcDictBy || {};\n    S.draft.rcDictBy[k.slice(7)] = String(v == null ? '' : v);\n    return;\n  }\n  /* 抄写框草稿：重绘不把刚抄的字弄丢 */\n  if (k === 'rccopy') {\n    S.draft.rcCopyText = String(v == null ? '' : v);\n    return;\n  }\n  /* 导入预览：改动直接写回预览列表，点「确认导入」时用的就是改过之后的 */\n  if (k.indexOf('rcPreview.') === 0) {\n    const parts = k.slice(10).split('.');\n    const i = Number(parts[0]), field = parts[1];\n    const pv = S.draft.rcImportPreview;\n    if (pv && pv.list && pv.list[i] && (field === 'q' || field === 'a')) {\n      pv.list[i][field] = String(v == null ? '' : v);\n    }\n    return;\n  }\n  if (k.indexOf('setting.') === 0) {\n    const path = k.slice(8).split('.');\n    if (path.length === 1) S.settings[path[0]] = v;\n    else {\n      let cur = S.settings;\n      for (let i = 0; i < path.length - 1; i++) {\n        if (cur[path[i]] == null || typeof cur[path[i]] !== 'object' || Array.isArray(cur[path[i]])) cur[path[i]] = {};\n        cur = cur[path[i]];\n      }\n      cur[path[path.length - 1]] = v;\n    }\n    saveSettings(); return;\n  }\n  setDraftPath(k, v);\n  /* 搜索框：一边打字一边出结果。以前输入只改了草稿、不触发重绘，\n     所以「搜了没反应」，得点一下别处才刷新。这里加个短防抖重绘。 */\n  if (k === 'rcSearch' || k === 'qaKb') liveSearchTick();\n  /* 答卷的填空/简答：打字的同一刻就写进当前这份卷子，重绘不会把字清掉、判分也拿得到 */\n  const m = /^(ans|pans)\\.(\\d+)$/.exec(k);\n  if (m) { const t = answerTarget(); if (t) t.answers[Number(m[2])] = v; }\n  /* 字数实时同步：带 data-count-for 的计数跟着输入即时更新 */\n  try {\n    document.querySelectorAll('[data-count-for=\"' + k + '\"]').forEach(n => { n.textContent = txtCount(v); });\n  } catch (e) { }\n}\ndocument.addEventListener('input', onFieldChange);\ndocument.addEventListener('change', onFieldChange);\n/* 抄写框禁止粘贴：这个功能的用意就是「手过一遍」，粘上去等于没抄。\n   如果你其实想保留粘贴（比如答案特别长），跟我说一声就撤掉。 */\ndocument.addEventListener('paste', e => {\n  const t = e.target;\n  if (!t || t.id !== 'rcCopyBox') return;\n  e.preventDefault();\n  toast('粘贴不算抄 —— 手打一遍才记得住');\n});\nObject.assign(ACTIONS, {\n  tab: el => { S.tab = el.dataset.tab; go(el.dataset.view); },\n  back: () => back(),\n  gotoView: el => go(el.dataset.view),\n  hubTab: el => { S.draft['hub_' + el.dataset.hub] = el.dataset.v; render(); window.scrollTo(0, 0); },\n  closeSheet: () => closeSheet()\n});\n/* ==========================================================\n   双记忆库：私密库（角色不可见）/ 对外库（角色可见）\n   ========================================================== */\nasync function addPrivate(kind, content, extra) {\n  const rec = Object.assign({ kind: kind, content: content, at: Date.now(), date: dkey() }, extra || {});\n  const r = await DB.create(T.PRIV, rec);\n  if (r) S.priv.unshift(Object.assign({ id: r.id }, rec));\n  return r;\n}\nasync function addPublic(kind, text, charId, extra) {\n  const rec = Object.assign({ kind: kind, text: text, charId: charId || '', at: Date.now(), date: dkey() }, extra || {});\n  const r = await DB.create(T.PUB, rec);\n  if (r) S.pub.unshift(Object.assign({ id: r.id }, rec));\n  return r;\n}\nfunction privOf(kinds, limit) {\n  const ks = Array.isArray(kinds) ? kinds : [kinds];\n  const arr = S.priv.filter(p => ks.indexOf(p.kind) >= 0).sort((a, b) => b.at - a.at);\n  return limit ? arr.slice(0, limit) : arr;\n}\nasync function syncTimeline(charId, summary, detail, data) {\n  if (!charId) return;\n  await sdk(() => API.memory.addTimeline({\n    characterId: charId, appLabel: '角色陪伴专注', detail: detail || 'focus_event',\n    summary: summary, appEventId: uid(), data: data || {}\n  }));\n}\nasync function syncChatLine(charId, content, role) {\n  if (!charId || !cfg('syncChat')) return;\n  await sdk(() => API.chat.writeHistory({ characterId: charId, role: role || 'system', content: content }));\n}\nfunction weakSummary(limit) {\n  const rows = privOf(['weak', 'mistake'], limit || 8);\n  if (!rows.length) return '（暂无历史薄弱点记录）';\n  return rows.map(r => `- ${r.content}`).join('\\n');\n}\n/* ---------- 出题方向：用户可以自己指定这次要考什么 ----------\n   留空 → 按学习总结 + 历史薄弱点出题（老逻辑）。\n   填了 → 当成「本次重点考察范围」写进出题要求：\n     · 模式「优先」：出题围着这个范围来，不再抽别的板块；\n     · 模式「混合」：一半左右的题落在这个范围，其余按总结与薄弱点出。\n   这个范围同时会写进题库分类，方便之后按分类抽题。 */\nfunction quizFocus() { return String(cfg('quizFocus') || '').trim(); }\nfunction focusLine() {\n  const f = quizFocus();\n  if (!f) return '【本次重点考察方向】（未指定 —— 请按上面的学习总结与历史薄弱点出题）';\n  if ((cfg('quizFocusMode') || 'focus') === 'mix') {\n    return '【本次重点考察方向 —— 与上面的总结混合】\\n' + f +\n      '\\n大约一半的题要落在这个范围里，剩下的按上面的总结与薄弱点出题。';\n  }\n  return '【本次重点考察方向 —— 优先出这一类】\\n' + f +\n    '\\n这次要围着他写下的这个范围出题（可以覆盖其中几个点、由浅到深地考），不要再抽其它板块的内容。';\n}\n/* 从「希望考察的知识点」里拆出关键词，用来筛题库题与错题 ——\n   保证选了「优先考这个范围」时，连抽题那两份也尽量不跑题。\n   筛完一道都不剩就退回全部（宁可跑题也不给空卷）。 */\nfunction focusKeys() {\n  const f = quizFocus();\n  if (!f) return [];\n  return f.split(/[，,、/／｜|\\s；;和与及：:（）()【】\\[\\]]+/).map(x => x.trim()).filter(x => x.length >= 2).slice(0, 8);\n}\nfunction focusHit(q) {\n  const ks = focusKeys();\n  if (!ks.length) return true;\n  const t = norm(String((q && q.q) || ''));\n  return ks.some(k => { const n = norm(k); return n && t.indexOf(n) >= 0; });\n}\n/* ==========================================================\n   专注会话\n   ========================================================== */\nlet sessTimer = null;\nfunction saveSession(now) {\n  const s = S.session; if (!s) return Promise.resolve();\n  const run = async () => {\n    const key = s.id || s.dbId; if (!key) return;\n    const copy = JSON.parse(JSON.stringify(s));\n    delete copy.wallpaperData;\n    await DB.update(T.SESSION, key, { data: copy });\n  };\n  if (now) { if (sessTimer) clearTimeout(sessTimer); sessTimer = null; return run(); }\n  if (sessTimer) clearTimeout(sessTimer);\n  sessTimer = setTimeout(run, 250);\n  return Promise.resolve();\n}\nfunction remainSec() {\n  const s = S.session;\n  if (!s || !s.phaseEndsAt) return 0;\n  if (s.paused) return Math.max(0, (s.phaseEndsAt - s.pausedAt) / 1000);\n  return Math.max(0, (s.phaseEndsAt - Date.now()) / 1000);\n}\nfunction phaseTotalSec() {\n  const s = S.session; if (!s) return 1;\n  return Math.max(1, (s.phase === 'break' ? s.breakMin : s.focusMin) * 60);\n}\nfunction completionMult(s) {\n  const todos = (s && s.plan) || [];\n  if (!todos.length) return 1;\n  const rate = todos.filter(t => t.done).length / todos.length;\n  return rate >= 1 ? 0.5 : rate >= 0.6 ? 1 : 1.5;\n}\nfunction multLabel(m) { return m <= 0.5 ? '减量 ×0.5（任务全清）' : m >= 1.5 ? '加量 ×1.5（完成度过低）' : '标准 ×1'; }\nfunction pushMsg(s, role, text, extra) {\n  if (!s) return;\n  s.msgs = s.msgs || [];\n  s.msgs.push(Object.assign({ role: role, text: text, at: Date.now() }, extra || {}));\n  if (s.msgs.length > 120) s.msgs = s.msgs.slice(-120);\n}\nfunction startTicking() {\n  if (!S.tick) { S.lastTick = Date.now(); S.tick = setInterval(tick, 1000); }\n  if (!S.paint) S.paint = setInterval(paintRingNow, 400);      // 双保险：秒表独立的快速刷新手\n}\nfunction stopTicking() {\n  if (S.tick) { clearInterval(S.tick); S.tick = null; }\n  if (S.paint) { clearInterval(S.paint); S.paint = null; }\n}\n/* 回到前台 / 切回本页时立刻补一次，避免「回来了还显示旧时间」 */\n['focus', 'pageshow', 'resume'].forEach(ev => {\n  try { window.addEventListener(ev, () => { try { paintRingNow(); } catch (e) { } }); } catch (e) { }\n});\ndocument.addEventListener('visibilitychange', () => {\n  if (document.hidden) return;\n  setTimeout(paintRingNow, 30);\n  consumePendingApply();\n});\nfunction tick() {\n  const s = S.session, now = Date.now();\n  /* L1 提醒锁：会话结束后自动恢复勿扰（覆盖 done/passed/failed/stopped 全部出口） */\n  if (S.settings.assistDndOn && (!s || s.status !== 'running')) {\n    S.settings.assistDndOn = false; saveSettings(true);\n    sdk(() => API.device.dndSet({ on: false }), null).catch(() => { });\n  }\n  if (S.settings.assistLockOn && (!s || s.status !== 'running')) {\n    S.settings.assistLockOn = false; saveSettings(true);\n    sdk(() => API.device.lockStop(), null).catch(() => { });\n  }\n  /* 通行证集合变化（新批/过期/作废）→ 重推看守锁，做到即时放行与即时收权 */\n  (function () {\n    try {\n      const sig = activeWlPasses().map(p => p.id + ':' + (p.expireAt || 0)).sort().join('|');\n      if (S._wlSig === undefined) { S._wlSig = sig; return; }\n      if (S._wlSig !== sig) { S._wlSig = sig; syncLockNow(); }\n    } catch (e) { }\n  })();\n  /* 拦截页「申请用一会儿」：取走待处理申请并打开预填单 */\n  (function () {\n    try {\n      if (typeof API === 'undefined' || !API || !API.device || !API.device.pendingApply) return;\n      if (Date.now() - (S._paAt || 0) < 2000) return;\n      S._paAt = Date.now();\n      sdk(() => API.device.pendingApply(), null).then((r) => {\n        if (r && r.ok && r.pkg) {\n          S.draft.wlMinutes = 15;\n          openWlApply({ app: r.label || '', pkg: r.pkg });\n          toast('已带入被拦的应用：' + (r.label || r.pkg));\n        }\n      }).catch(() => { });\n    } catch (e) { }\n  })();\n  /* 桌面倒计时组件：状态签名（运行/阶段/15秒档）变化才推送 —— 启动恢复、\n     阶段切换、暂停、结束都会造成签名变化，一处钩子全覆盖，无需逐点接线 */\n  (function () {\n    try {\n      if (typeof API === 'undefined' || !API || !API.device || !API.device.focusWidgetUpdate) return;\n      const st = S.session;\n      const running = !!(st && st.status === 'running' && !st.paused);\n      const remain = running ? Math.max(0, (st.phaseEndsAt || 0) - now) : 0;\n      const sig = running ? [1, st.phase, Math.ceil(remain / 15000)].join('|') : '0';\n      if (S._widgetSig === sig) return;\n      S._widgetSig = sig;\n      pushWidget(st);\n    } catch (e) { }\n  })();\n  /* 通行证查岗：APK 走原生查岗浮层（不要求专注 App 在前台）；网页/旧壳才弹 APP 内层 */\n  (function () {\n    const c = S.settings.wlCheckin;\n    if (!c || c.done) return;\n    const nowTs = Date.now();\n    const pass = (S.wlPasses || []).find(x => x.id === c.passId);\n    if (pass && pass.verdict) {\n      c.done = 'verdict'; saveSettings(true);\n      return;\n    }\n    if (nowTs >= c.deadlineAt) { wlCheckinExpire(); return; }\n    if (!c.native && nowTs >= c.at && !c.sheetShown && typeof document !== 'undefined' && !document.hidden) {\n      c.sheetShown = true; saveSettings(true);\n      openWlCheckinSheet();\n    }\n  })();\n  const gap = now - (S.lastTick || now); S.lastTick = now;\n  renderRunLight();                      // 先把秒数刷上去：即便这一拍要判离开，界面也不会停住\n  /* 纸条换来的「松一口气」：时间到了自动接着走（暂停期间不计入专注时长） */\n  if (s && s.status === 'running' && s.paused && s.noteRestUntil) {\n    if (now >= s.noteRestUntil) {\n      const was = noteRestMin();\n      s.noteRestUntil = 0;\n      s.paused = false; s.pausedAt = 0; s.pauseReason = '';\n      s.phaseEndsAt = Number(s.phaseEndsAt || now) + was * 60000;   // 暂停多久就往后顺延多久，专注时长不被吃掉\n      s.justResumed = true;\n      S.lastTick = now;\n      pushMsg(s, 'sys', '🌿 休息结束，接着走 —— 他刚才说的你都还记得吧');\n      saveSession(true);\n      render();\n    }\n  }\n  if (!s || s.status !== 'running' || s.paused) return;\n  /* 心跳：记下「这一刻还在专注」。APP 被整个关闭、或被系统冻结太久时，\n     页面里的秒表和 visibilitychange 都断了，重开只能靠这个心跳反算离开多久 */\n  s.lastAliveAt = now;\n  if (now - (s.lastAliveSaved || 0) > 10000) { s.lastAliveSaved = now; saveSession(); }\n  if (gap > 4200 && !s.justResumed) { onAway(Math.round(gap / 1000)); return; }\n  /* 真实专注时长：只累计「这一拍确实在走」的时间。\n     暂停（上面已 return）、切到别的 APP / 关掉 APP（定时器被掐停，或 gap 超阈值走了离开判定）、\n     刚回到前台的那一下（justResumed）都不计入 —— 结算从此不再按「设定时长」估。 */\n  if (s.phase === 'focus' && !document.hidden) {\n    const add = s.justResumed ? 0 : Math.max(0, Math.min(gap, 4200)) / 1000;\n    s.totalFocusSec = (s.totalFocusSec || 0) + add;\n  }\n  s.justResumed = false;\n  if (remainSec() <= 0) { onPhaseEnd(); return; }\n  trackTaskTimer(s);\n  if (s.phase === 'focus') checkTaskDue(s);\n  maybeMessaging();\n  updateFloatBar();\n}\n/* 只刷秒数，不动其它 DOM —— 每 400ms 跑一次，倒计时不会再出现「卡一下」 */\nfunction paintRingNow() {\n  try {\n    const s = S.session;\n    if (!s || S.lock || S.view !== 'running') return;\n    const el = document.getElementById('ringTime');\n    if (!el) return;\n    const t = fmtClock(remainSec());\n    if (el.textContent !== t) el.textContent = t;\n    const p = clamp(100 - remainSec() / phaseTotalSec() * 100, 0, 100);\n    const ring = document.getElementById('ring');\n    if (ring) { ring.style.setProperty('--p', p); ring.classList.toggle('paused', !!s.paused); }\n  } catch (e) { }\n}\nfunction updateFloatBar() {\n  const el = document.getElementById('floatMsgText');\n  if (!el) return;\n  const s = S.session; if (!s) return;\n  const last = (s.msgs || []).filter(m => m.role === 'char').slice(-1)[0];\n  if (!last) return;\n  if (el.getAttribute('data-at') !== String(last.at)) {\n    el.setAttribute('data-at', String(last.at));\n    el.textContent = last.text;\n    const who = document.getElementById('floatMsgWho');\n    if (who) who.textContent = charName(last.charId);\n  }\n}\n/* 睡眠中时，任何操作都算「还醒着」：重置安静计时（节流写入，避免频繁落库） */\n['pointerdown', 'touchstart', 'keydown', 'wheel'].forEach(ev => {\n  document.addEventListener(ev, () => {\n    if (S.sleep && S.sleep.running) markSleepActive('touch');\n  }, { passive: true });\n});\nlet awayStartAt = 0, lastAwayHandled = 0;\ndocument.addEventListener('visibilitychange', function () {\n  // 睡眠中：切到别的 APP 视为「还在醒着」——这段时间不计入睡眠\n  if (S.sleep && S.sleep.running) { if (document.hidden) sleepGoAway(); else sleepComeBack(); }\n  const s = S.session;\n  if (document.hidden) { awayStartAt = Date.now(); return; }\n  if (!awayStartAt) return;\n  const sec = (Date.now() - awayStartAt) / 1000; awayStartAt = 0;\n  if (sec >= 2 && s && s.status === 'running' && !s.paused) onAway(sec);\n});\nasync function onAway(sec) {\n  const s = S.session;\n  if (!s || s.status !== 'running' || s.paused || S.lock) return;\n  if (Date.now() - lastAwayHandled < 4000) return;\n  lastAwayHandled = Date.now();\n  const grace = Number(cfg('graceSec') || 8);\n  if (sec <= grace) { pushMsg(s, 'sys', `离开 ${Math.round(sec)} 秒，在宽限（${grace}秒）内，不计违规`); await saveSession(); render(); return; }\n  s.violations = s.violations || [];\n  const v = { type: 'leave', at: Date.now(), detail: `中途离开 ${Math.round(sec)} 秒`, excused: false };\n  s.violations.push(v);\n  bumpSelfTasks(s, -12, '你中途离开了 ' + Math.round(sec) + ' 秒');\n  await coinDeductFor('专注中离开', 'leave');\n  /* 提醒锁：任何开启的锁级离开都落一条系统通知 —— 人不在小手机里也能收到 */\n  if (assistLevelFor(s) !== 'off' && API && API.device && API.device.notify) {\n    const leaveCid = pickOneChar(s.charIds);\n    sdk(() => API.device.notify({ title: '👀 ' + charName(leaveCid) + ' 看到你离开了', body: '专注里离开了 ' + Math.round(sec) + ' 秒，回来继续吧。' }), null).catch(() => { });\n  }\n  await saveSession(true); render();\n  const lockLvl = assistLevelFor(s);\n  if (lockLvl === 'L3') {\n    /* 承诺书已预授权：不问原因，直接按惩罚库执行 */\n    pushMsg(s, 'sys', `⚠️ 承诺死锁：中途离开 ${Math.round(sec)} 秒（超宽限）—— 按承诺自动开罚`);\n    await syncTimeline(pickOneChar(s.charIds), '承诺死锁期间用户中途离开 ' + Math.round(sec) + ' 秒，按承诺自动开罚（无需确认）。', 'lock_pledge_leave', {});\n    await triggerPunish('锁机承诺：中途离开', {});\n    return;\n  }\n  if (cfg('punishEnabled') && cfg('punishTrigger').leave) askAwayExcuse(v, Math.round(sec));\n  else pushMsg(s, 'sys', `⚠️ 记录一次中途离开（${Math.round(sec)} 秒）`);\n}\n/* L3 暂停冷静期：倒计时结束前不许确认暂停（One Sec 式冷却） */\nfunction openLockCooldownSheet() {\n  const secs = Math.max(5, Number(cfg('lockCooldownSec')) || 60);\n  const deadline = Date.now() + secs * 1000;\n  openSheet(`<h3>⏳ 冷静期</h3>\n    <div class=\"sub\">承诺死锁中。暂停会让 TA 干等 —— 先冷静 <b>${secs} 秒</b>再决定。</div>\n    <div class=\"center\" style=\"font-size:30px;font-weight:700\" id=\"cdNum\">${secs}</div>\n    <button class=\"btn primary block mt10\" data-act=\"closeSheet\">回去继续专注</button>\n    <button class=\"btn warn block mt8\" data-act=\"doPause\" id=\"cdPauseBtn\" disabled>我坚持暂停（${secs}）</button>\n    <div class=\"tiny mt8\">冷静期内写下要暂停的原因（去洗手间/接电话都算正当），倒计时结束就能确认。</div>`);\n  const tick = setInterval(() => {\n    const num = document.getElementById('cdNum'), btn = document.getElementById('cdPauseBtn');\n    if (!num || !btn) { clearInterval(tick); return; }\n    const left = Math.max(0, Math.ceil((deadline - Date.now()) / 1000));\n    num.textContent = String(left); btn.textContent = '我坚持暂停（' + left + '）';\n    if (left <= 0) { btn.disabled = false; clearInterval(tick); }\n  }, 1000);\n}\n/* ── 常驻白名单 + 应用选择器（L2 看守锁放行清单）──────────────\n   壳可用 → 从已安装应用列表里选（名称+包名一步到位）；\n   壳不可用 → 降级手输名称（包名留空，L2 到来后按名称兜底匹配）。 */\nfunction lockedAppsFor() {\n  const out = [];\n  for (const a of (cfg('lockedApps') || [])) { if (a.pkg) out.push(a.pkg); }\n  for (const p of activeWlPasses()) { const pk = p.package || p.pkg; if (pk) out.push(pk); }\n  return Array.from(new Set(out));\n}\n/* 申请单里的应用对象同时兼容 {package} / {pkg} 两种字段。 */\nfunction wlAppPackage(app) {\n  return String((app && (app.package || app.pkg)) || '').trim();\n}\n/* 旧版本多选申请写入的通行证可能只有 app 名、没有包名，导致 native 看守锁\n   永远放行不了。启动时按应用名回查包名并补写。 */\nasync function repairWlPassPackages() {\n  const now = Date.now();\n  const missing = (S.wlPasses || []).filter(p => p.status === 'active' && (!p.expireAt || p.expireAt > now) && !wlAppPackage(p));\n  if (!missing.length) return;\n  if (typeof API === 'undefined' || !API || !API.device || !API.device.appsList) return;\n  let list = [];\n  try {\n    const res = await API.device.appsList();\n    list = (res && res.apps) || [];\n  } catch (e) { return; }\n  if (!list.length) return;\n  let changed = false;\n  for (const p of missing) {\n    const key = String(p.app || '').trim().toLowerCase();\n    if (!key) continue;\n    const hit = list.find(x => String(x.label || '').toLowerCase() === key)\n      || list.find(x => String(x.label || '').toLowerCase().indexOf(key) >= 0)\n      || list.find(x => String(x.package || '').toLowerCase().indexOf(key) >= 0);\n    if (!hit || !hit.package) continue;\n    p.package = hit.package;\n    if (p.dbId) await DB.update(T.WLP, p.dbId, JSON.parse(JSON.stringify(p)));\n    changed = true;\n  }\n  if (changed) syncLockNow();\n}\n/* 桌面倒计时小组件：推一份会话状态（Chronometer 原生走表，只在状态变化时推）。\n   字段契约见壳侧 FocusWidgetProvider.update：{running,remainingMs,progress,task,charName} */\nfunction pushWidget(s) {\n  try {\n    if (typeof API === 'undefined' || !API || !API.device || !API.device.focusWidgetUpdate) return;\n    const now = Date.now();\n    const running = !!(s && s.status === 'running' && !s.paused);\n    const remain = running ? Math.max(0, (s.phaseEndsAt || now) - now) : 0;\n    const total = running ? Math.max(1, (s.phase === 'break' ? (Number(s.breakMin) || 5) : (Number(s.focusMin) || 25)) * 60000) : 1;\n    const task = running && s.phase === 'focus' ? (((s.plan || [])[s.curTaskIdx || 0] || {}).content || '') : '';\n    const ch = running && s && (s.charIds || [])[0] ? ((charById(s.charIds[0]) || {}).name || '') : '';\n    const r = API.device.focusWidgetUpdate(JSON.stringify({\n      running: running, remainingMs: remain,\n      progress: running ? Math.max(0, Math.min(100, Math.round(100 * (1 - remain / total)))) : 0,\n      task: task, charName: ch,\n    }));\n    if (r && typeof r.catch === 'function') r.catch(function () { });\n  } catch (e) { }\n}\n/* 本场专注的绝对结束时刻：cycles 段专注 + 中间的 (cycles-1) 段休息。\n   看守锁的 until 必须始终用它，不能每次同步都 now+剩余+10 分钟，\n   否则每批一次通行证/每加一次时间，锁都会被悄悄延长。 */\nfunction sessionEndAt(s) {\n  if (!s) return Date.now();\n  const cycles = Math.max(1, Number(s.cycles) || 1);\n  const focusMs = Math.max(60000, (Number(s.focusMin) || 25) * 60000);\n  const breakMs = Math.max(0, (Number(s.breakMin) || 5) * 60000);\n  const base = (Number(s.startAt) || Date.now()) + cycles * focusMs + Math.max(0, cycles - 1) * breakMs;\n  /* 暂停/加时会顺延 phaseEndsAt；旧会话也可能没有 lockUntil。\n     至少覆盖「当前阶段结束 + 剩余轮次」，不能比当前倒计时更早收锁。 */\n  const cycle = Math.max(1, Number(s.cycle) || 1);\n  const remainingCycles = Math.max(0, cycles - cycle);\n  const phaseEnd = Number(s.phaseEndsAt) || 0;\n  return Math.max(base, phaseEnd + remainingCycles * (focusMs + breakMs));\n}\n/* 通行证生效/过期时重推白名单：看守锁的黑名单在启动时冻结，必须重推才能即时放行或重新锁上。\n   update 只换白名单/延长截止，不重置计时基准；老 APK 没有 update 时才退回 lockStart。 */\nfunction syncLockNow() {\n  const s = S.session;\n  if (!s || s.status !== 'running') return;\n  if (typeof API === 'undefined' || !API || !API.device) return;\n  const until = sessionEndAt(s);\n  s.lockUntil = until;\n  const payload = { packages: JSON.stringify(lockedAppsFor()), until };\n  const fn = API.device.lockUpdate || API.device.lockStart;\n  if (!fn) return;\n  sdk(() => fn(payload), null).catch(() => { });\n}\nasync function releaseAssistLock() {\n  S.settings.assistLockOn = false;\n  await saveSettings(true);\n  await sdk(() => API.device.lockStop(), null).catch(() => { });\n  if (S.settings.assistDndOn) {\n    S.settings.assistDndOn = false;\n    await saveSettings(true);\n    await sdk(() => API.device.dndSet({ on: false }), null).catch(() => { });\n  }\n}\n/* 紧急解除：只给角色工具调用。用户侧没有请求/直接解锁按钮。 */\nasync function forceUnlock(reason, opts) {\n  const s = S.session;\n  if (s && s.status === 'running') {\n    s.status = 'stopped';\n    s.endAt = Date.now();\n    s.stoppedAt = Date.now();\n    s.summary = String(reason || '看守锁已解除').slice(0, 200);\n    await saveSession(true);\n  }\n  await releaseAssistLock();\n  if (!(opts && opts.silent)) toast('🔓 看守锁已解除');\n  render();\n  return true;\n}\n/* ── 应用分类与推荐（角色审批口径）────────────────────────────\n   工作/学习类：常驻白名单可以批；娱乐类：只给限时通行证，避免「永久放行游戏」。 */\nconst WL_WORK_RE = /(词典|翻译|单词|笔记|阅读|地图|导航|学习|课程|题库|扫描|文档|邮件|日历|待办|计算器|anki|notion|keep|dictionary|translate|note|map|reader|office|drive|docs|sheets)/i;\nconst WL_FUN_RE = /(游戏|视频|抖音|快手|bilibili|哔哩|王者|原神|和平精英|微博|小红书|直播|music|netflix|youtube|game|steam|爱奇艺|腾讯视频|优酷)/i;\nfunction wlClassify(app) {\n  const str = String((app && app.label) || '') + ' ' + String((app && app.package) || '');\n  if (WL_FUN_RE.test(str)) return 'fun';\n  if (WL_WORK_RE.test(str)) return 'work';\n  return 'other';\n}\nfunction wlSuggestApps() {\n  const cur = new Set((cfg('lockedApps') || []).map(x => x.pkg));\n  return (S.draft.appList || []).filter(a => !cur.has(a.package) && wlClassify(a) === 'work').slice(0, 6);\n}\n/* ── 多选申请单（常驻白名单 / 限时通行证共用一套）────────────── */\nfunction openMultiApply(mode, apps) {\n  S.draft.applyMode = mode === 'perm' ? 'perm' : 'pass';\n  /* 应用选择器给的是 pkg 字段，旧调用方给的是 package；统一成 package，\n     否则通行证会丢包名，看守锁永远放行不了。 */\n  S.draft.applyApps = (apps || S.draft.applyApps || []).map(a => ({\n    label: a.label,\n    package: String(a.package || a.pkg || '').trim()\n  }));\n  if (!S.draft.applyApps.length) { toast('先选应用'); return; }\n  S.draft.wlReason = S.draft.wlReason || '';\n  S.draft.wlMinutes = Number(S.draft.wlMinutes) || 15;\n  const perm = S.draft.applyMode === 'perm';\n  const reasons = ['查单词', '查资料', '回个消息', '导航'];\n  openSheet(`<h3>${perm ? '🧱 申请加入常驻白名单' : '🎟 申请通行证'}</h3>\n    <div class=\"tiny mt6\">${perm ? '常驻白名单由 TA 审批；学习/工具类通常直接批，娱乐类只会给限时通行证。' : '批了才生效，到期自动回收。'}</div>\n    <div class=\"chips mt8\">${S.draft.applyApps.map((a, i) => `<span class=\"chip on\">${esc(a.label)} <b data-mapp-del=\"${i}\" style=\"cursor:pointer;margin-left:4px\">✕</b></span>`).join('')}</div>\n    <button class=\"btn sm ghost block mt6\" data-act=\"multiRepick\">重新选择应用</button>\n    <label class=\"fl\">用途</label>\n    <div class=\"chips\">${reasons.map(r => `<button class=\"chip ${S.draft.wlReason === r ? 'on' : ''}\" data-act=\"multiReasonPick\" data-v=\"${r}\">${r}</button>`).join('')}</div>\n    <input class=\"input mt8\" data-in=\"wlReason\" value=\"${esc(S.draft.wlReason || '')}\" placeholder=\"或者自己写一句\">\n    ${perm ? '' : `<label class=\"fl\">时长</label>\n    <div class=\"chips\">${[10, 15, 20, 30].map(m => `<button class=\"chip ${Number(S.draft.wlMinutes) === m ? 'on' : ''}\" data-act=\"multiMinPick\" data-v=\"${m}\">${m} 分钟</button>`).join('')}</div>`}\n    <button class=\"btn primary block mt10\" data-act=\"multiApplySubmit\">提交给 TA 审批</button>\n    <button class=\"btn ghost block mt8\" data-act=\"closeSheet\">取消</button>`);\n  const w = modalStack[modalStack.length - 1];\n  if (!w) return;\n  w.addEventListener('click', (e) => {\n    const del = e.target.closest('[data-mapp-del]');\n    if (del) {\n      S.draft.applyApps.splice(Number(del.dataset.mappDel), 1);\n      if (!S.draft.applyApps.length) { closeAllSheets(); return; }\n      openMultiApply(S.draft.applyMode, S.draft.applyApps);\n    }\n  });\n}\nasync function submitMultiApply() {\n  const apps = (S.draft.applyApps || []).slice();\n  if (!apps.length) { toast('先选应用'); return; }\n  const cid = anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  const perm = S.draft.applyMode === 'perm';\n  const minutes = Math.max(1, Math.min(30, Number(S.draft.wlMinutes) || 15));\n  const reason = String(S.draft.wlReason || '').trim();\n  S.wlBusy = true;\n  const names = apps.map(a => a.label).join('、');\n  let verdict = null;\n  try {\n    verdict = wlParseVerdict(await pGen('wl.review', {\n      appName: names, reason: reason || '（没写）', minutes: perm ? 0 : minutes,\n      trust: wlTrust(), activeCount: activeWlPasses().length,\n      focusState: (S.session && S.session.status === 'running') ? '正在一段专注里' : '现在没有在专注',\n      permanent: perm ? '是（申请常驻白名单）' : '否（限时通行证）',\n    }, [cid]));\n  } catch (e) { }\n  /* 离线/无 AI 裁决 */\n  const fun = apps.filter(a => wlClassify(a) === 'fun');\n  const ok = apps.filter(a => wlClassify(a) !== 'fun');\n  /* AI 裁决是否有效：有效就完全按 TA 的决定来；只有没有 AI 时才用本地分类规则 */\n  const decided = verdict && ['approve', 'counter', 'reject'].indexOf(verdict.decision) >= 0 ? verdict.decision : '';\n  const aiReply = verdict && verdict.reply ? String(verdict.reply) : '';\n  let reply = '';\n  let permitWork = ok;\n  let permitFun = fun;\n  if (decided === 'approve') { permitWork = apps; permitFun = []; }\n  else if (decided === 'counter') { permitWork = ok; permitFun = fun; }\n  else if (decided === 'reject') { permitWork = []; permitFun = []; }\n  if (perm) {\n    if (permitWork.length) {\n      const cur = cfg('lockedApps') || [];\n      const map = new Map(cur.filter(x => x.pkg).map(x => [x.pkg, x]));\n      for (const a of permitWork) {\n        const pkg = wlAppPackage(a);\n        if (pkg) map.set(pkg, { name: a.label, pkg });\n      }\n      S.settings.lockedApps = Array.from(map.values());\n      saveSettings(true);\n    }\n    /* 娱乐类（或 AI 只给条件批准）：只给 10 分钟通行证 */\n    for (const a of permitFun) {\n      const rec = { id: 'wlp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), app: a.label, reason: reason || '娱乐类限时', minutes: 10, conditions: '娱乐类只给限时', reply: '', package: wlAppPackage(a), decision: 'counter', status: 'active', issuedAt: Date.now(), expireAt: Date.now() + 10 * 60000, uses: 0, trustAtIssue: wlTrust(), at: Date.now() };\n      const r = await DB.create(T.WLP, JSON.parse(JSON.stringify(rec)));\n      if (r) rec.dbId = r.id;\n      S.wlPasses = [rec].concat(S.wlPasses || []);\n    }\n    reply = aiReply || (permitWork.length\n      ? '工具/学习类加进常驻了（' + permitWork.length + ' 个）' + (permitFun.length ? '；娱乐类只给 10 分钟，别拿它当常驻。' : '。')\n      : '这几个都是娱乐类，常驻不行 —— 先给 10 分钟，用完再申请。');\n  } else {\n    if (decided === 'reject') {\n      reply = aiReply || '这次不行。';\n    }\n    const grant = (verdict && Number(verdict.grantedMinutes)) || (minutes <= 15 && apps.length <= 5 ? minutes : 10);\n    if (decided !== 'reject') reply = aiReply || (minutes <= 15 && apps.length <= 5 ? '准了，' + grant + ' 分钟。到点自己回来。' : '先给 ' + grant + ' 分钟，够用就办完。');\n    for (const a of (decided === 'reject' ? [] : apps)) {\n      const rec = { id: 'wlp_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 5), app: a.label, reason, minutes: grant, conditions: '只开这段时间', reply, package: wlAppPackage(a), decision: 'approve', status: 'active', issuedAt: Date.now(), expireAt: Date.now() + grant * 60000, uses: 0, trustAtIssue: wlTrust(), at: Date.now() };\n      const r = await DB.create(T.WLP, JSON.parse(JSON.stringify(rec)));\n      if (r) rec.dbId = r.id;\n      S.wlPasses = [rec].concat(S.wlPasses || []);\n    }\n  }\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'system', historyRole: 'system',\n    title: (perm ? '🧱 白名单申请 · ' : '🎟 通行证申请 · ') + names.slice(0, 40),\n    subtitle: perm ? (ok.length ? '已批准 ' + ok.length + ' 个' : '改为限时') : '已签发',\n    body: reply.slice(0, 140),\n    summary: charName(cid) + ' 审批了 ' + names + ' 的' + (perm ? '常驻白名单' : '通行证') + '申请',\n    historyText: '[应用申请] ' + names + '（' + (perm ? '常驻' : minutes + ' 分钟') + '，用途：' + (reason || '未写') + '）—— 批复：' + reply,\n  }), null).catch(() => { });\n  S.wlBusy = false;\n  S.draft.applyApps = [];\n  closeAllSheets();\n  syncLockNow();\n  toast(perm ? ('🧱 白名单：批准 ' + ok.length + ' 个' + (fun.length ? '，娱乐类改限时 ' + fun.length + ' 个' : '')) : ('🎟 已签发 ' + apps.length + ' 张通行证'));\n  render();\n}\n/* 拦截页留下的申请（启动/回到前台时都查一次，不依赖 tick） */\nfunction consumePendingApply() {\n  try {\n    if (typeof API === 'undefined' || !API || !API.device || !API.device.pendingApply) return;\n    sdk(() => API.device.pendingApply(), null).then((r) => {\n      if (r && r.ok && r.pkg) {\n        S.draft.wlMinutes = 15;\n        openWlApply({ app: r.label || '', pkg: r.pkg });\n        toast('已带入被拦的应用：' + (r.label || r.pkg));\n      }\n    }).catch(() => { });\n  } catch (e) { }\n}\nfunction pickFromAppList(target) {\n  S.draft.appPickerTarget = target;\n  const r = API && API.device && API.device.appsList ? null : { ok: false, apps: [], reason: '当前环境不支持应用列表' };\n  if (r) { toast(r.reason || '当前环境不支持应用列表，请手输名称'); return; }\n  sdk(() => API.device.appsList(), null).then((res) => {\n    if (!res || !res.ok || !(res.apps || []).length) { toast((res && res.reason) || '拿不到应用列表，请手输名称'); return; }\n    S.draft.appList = res.apps;\n    S.draft.pickerSel = [];\n    renderAppPickerSheet('');\n  }).catch(() => toast('拿不到应用列表，请手输名称'));\n}\nfunction renderAppPickerSheet(kw) {\n  /* 白名单目标支持多选：勾选多个应用一次加入；其它目标仍是点一个即选 */\n  const multi = ['whitelist', 'passApply', 'permApply'].indexOf(S.draft.appPickerTarget) >= 0;\n  if (multi && !Array.isArray(S.draft.pickerSel)) S.draft.pickerSel = [];\n  const sel = new Set(multi ? (S.draft.pickerSel || []) : []);\n  S.draft.pickerKw = kw || '';\n  const q = String(kw || '').toLowerCase();\n  const list = (S.draft.appList || []).filter(x => !q || x.label.toLowerCase().indexOf(q) >= 0 || x.package.toLowerCase().indexOf(q) >= 0).slice(0, 120);\n  openSheet(`<h3>📱 ${multi ? '选择应用（可多选）' : '选择手机应用'}</h3>\n    <input class=\"input mt6\" id=\"appSearch\" placeholder=\"搜应用名 / 包名\" value=\"${esc(kw || '')}\">\n    ${multi ? `<div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-pick-all>全选当前结果</button>\n      <button class=\"btn sm ghost grow\" data-pick-none>清空选择</button></div>` : ''}\n    <div style=\"max-height:44dvh;overflow:auto\" class=\"mt8\">\n      ${list.length ? list.map((x, i) => `<div class=\"item${sel.has(x.package) ? ' on' : ''}\" data-pick=\"${i}\"><div class=\"ic\">📱</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(x.label)}</div><div class=\"tiny\">${esc(x.package)}</div></div>${multi ? `<div class=\"tiny\" style=\"min-width:18px;text-align:right\">${sel.has(x.package) ? '✓' : ''}</div>` : ''}</div>`).join('') : '<div class=\"empty\">没有匹配的应用</div>'}\n    </div>\n    ${multi ? `<button class=\"btn primary block mt10\" data-pick-add ${sel.size ? '' : 'disabled'}>加入白名单（${sel.size}）</button>` : ''}\n    <button class=\"btn ghost block mt8\" data-act=\"closeSheet\">取消</button>`);\n  const w = modalStack[modalStack.length - 1];\n  if (!w) return;\n  const addBtn = w.querySelector('[data-pick-add]');\n  const syncAdd = () => {\n    if (!addBtn) return;\n    const n = (S.draft.pickerSel || []).length;\n    addBtn.textContent = '加入白名单（' + n + '）';\n    addBtn.disabled = n === 0;\n  };\n  w.addEventListener('click', (e) => {\n    const input = e.target.closest('#appSearch');\n    const row = e.target.closest('[data-pick]');\n    if (row && S.draft.appList) {\n      const app = list[Number(row.dataset.pick)];\n      if (!app) return;\n      if (!multi) { applyAppPick(app); return; }\n      const cur = new Set(S.draft.pickerSel || []);\n      if (cur.has(app.package)) cur.delete(app.package); else cur.add(app.package);\n      S.draft.pickerSel = Array.from(cur);\n      row.classList.toggle('on', cur.has(app.package));\n      const mark = row.lastElementChild;\n      if (mark && mark !== row.firstElementChild) mark.textContent = cur.has(app.package) ? '✓' : '';\n      syncAdd();\n      return;\n    }\n    if (e.target.closest('[data-pick-all]')) {\n      const cur = new Set(S.draft.pickerSel || []);\n      list.forEach(x => cur.add(x.package));\n      S.draft.pickerSel = Array.from(cur);\n      renderAppPickerSheet(S.draft.pickerKw);\n      return;\n    }\n    if (e.target.closest('[data-pick-none]')) {\n      S.draft.pickerSel = [];\n      renderAppPickerSheet(S.draft.pickerKw);\n      return;\n    }\n    if (e.target.closest('[data-pick-add]')) {\n      const picked = (S.draft.pickerSel || []).map(pkg => (S.draft.appList || []).find(x => x.package === pkg)).filter(Boolean);\n      if (picked.length) applyAppPickMulti(picked);\n      return;\n    }\n  });\n  const searchEl = w.querySelector('#appSearch');\n  if (searchEl) searchEl.addEventListener('input', () => renderAppPickerSheet(searchEl.value));\n  syncAdd();\n}\n/* 多选确认：合并进常驻白名单（同包名去重，新名覆盖旧名） */\nfunction applyAppPickMulti(items) {\n  const t = S.draft.appPickerTarget;\n  if (t === 'passApply' || t === 'permApply') {\n    S.draft.applyApps = items.map(a => ({ label: a.label, pkg: a.package }));\n    closeAllSheets();\n    openMultiApply(t === 'permApply' ? 'perm' : 'pass', S.draft.applyApps);\n    return;\n  }\n  const cur = cfg('lockedApps') || [];\n  const map = new Map(cur.filter(x => x.pkg).map(x => [x.pkg, x]));\n  for (const a of items) map.set(a.package, { name: a.label, pkg: a.package });\n  S.settings.lockedApps = Array.from(map.values());\n  saveSettings(true);\n  S.draft.pickerSel = [];\n  closeAllSheets();\n  toast('🧱 已加入 ' + items.length + ' 个应用到常驻白名单');\n  render();\n}\nfunction applyAppPick(app) {\n  closeAllSheets();\n  const t = S.draft.appPickerTarget;\n  if (t === 'whitelist') {\n    S.settings.lockedApps = (cfg('lockedApps') || []).filter(x => x.pkg !== app.package).concat([{ name: app.label, pkg: app.package }]);\n    saveSettings(true);\n    toast('🧱 已加入常驻白名单：' + app.label);\n  } else {\n    S.draft.wlAppName = app.label; S.draft.wlPackage = app.package;\n    toast('已选择：' + app.label);\n  }\n  render();\n}\nfunction openLockedAppsSheet() {\n  /* 防叠加：增删/推荐后重开时先关掉旧的白名单弹层。\n     否则点空白只关最上面一层，露出的是「加之前」的旧列表，看起来像被删了。 */\n  for (const m of modalStack.slice()) {\n    if (m && m.textContent && m.textContent.indexOf('常驻白名单') >= 0) closeSheet(m);\n  }\n  /* 首次打开时后台拉一次应用列表，TA 推荐才有内容；到了就刷新这张弹层 */\n  if (!S.draft.appList && API && API.device && API.device.appsList) {\n    sdk(() => API.device.appsList(), null).then((res) => {\n      if (res && res.ok && (res.apps || []).length) {\n        S.draft.appList = res.apps;\n        const top = modalStack[modalStack.length - 1];\n        if (top && top.textContent && top.textContent.indexOf('常驻白名单') >= 0) openLockedAppsSheet();\n      }\n    }).catch(() => { });\n  }\n  const list = cfg('lockedApps') || [];\n  const oldWl = cfg('whitelist') || [];\n  openSheet(`<h3>🧱 常驻白名单</h3>\n    <div class=\"tiny mt6\">L2 看守锁放行的手机应用清单（按包名匹配）；也是中途离开豁免的依据。改动立即生效。</div>\n    ${list.length ? list.map((x, i) => `<div class=\"item\"><div class=\"ic\">📱</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(x.name)}</div><div class=\"tiny\">${esc(x.pkg || '未记录包名')}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"lockedAppsDel\" data-i=\"${i}\">删</button></div>`).join('') : '<div class=\"empty\">还没有应用 —— 从手机应用列表里选</div>'}\n    <button class=\"btn primary block mt10\" data-act=\"wlApplyOpen\" data-perm=\"1\">📱 选择应用并申请（多选）</button>\n    ${(() => { const sug = wlSuggestApps(); return sug.length ? `<div class=\"hr\"></div><div class=\"tiny\">TA 觉得这些学习/工具类应用可以放行：</div>\n      <div class=\"chips mt6\">${sug.map(a => `<button class=\"chip\" data-act=\"recWhitelistAdd\" data-app=\"${esc(a.label)}\" data-pkg=\"${esc(a.package)}\">＋ ${esc(a.label)}</button>`).join('')}</div>` : ''; })()}\n    ${oldWl.length ? `<div class=\"hr\"></div><div class=\"tiny\">旧手填白名单档案（未签发）：${oldWl.map(x => esc(x.name)).join('、')}</div>` : ''}\n    <button class=\"btn ghost block mt8\" data-act=\"closeSheet\">关闭</button>`);\n}\nfunction askAwayExcuse(v, sec) {\n  const passes = activeWlPasses();\n  const used = S.session.excuseUsed || 0;\n  const canExcuse = passes.length > 0 && used < 3;\n  const w = openSheet(`<h3 style=\"color:#ff9aa6\">⚠️ 检测到中途离开</h3>\n    <div class=\"sub\">你在专注中离开页面 <b>${sec} 秒</b>。主动点「暂停」不算违规；切后台、划掉 APP、离开专注页都算。</div>\n    ${canExcuse ? `<div class=\"tiny mt10\">可以放行的：${passes.map(x => esc(x.app)).join('、')}${(cfg('lockedApps') || []).length ? '、常驻白名单 ' + (cfg('lockedApps') || []).length + ' 个' : ''}</div>\n      <button class=\"btn block mt6\" data-ex=\"wl\">我去的是白名单应用</button>` : `<div class=\"tiny mt10\">没有生效中的通行证，常驻白名单也是空的 —— 要去某个应用的话，先向 TA 申请。</div>\n      <button class=\"btn block mt6\" data-act=\"wlApplyOpen\">🎟 向 TA 申请通行证<",
  "/button>`}\n    <div class=\"row mt10\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-ex=\"a\">我认罚</button>\n    <button class=\"btn warn grow\" data-ex=\"a2\">认罚并加重</button></div>\n    <div class=\"tiny mt10\">剩余申诉机会：${Math.max(0, 3 - used)} 次</div>`);\n  w.addEventListener('click', async e => {\n    const b = e.target.closest('[data-ex]'); if (!b) return;\n    closeSheet(w);\n    const act = b.dataset.ex;\n    if (act === 'wl' && canExcuse) {\n      S.session.excuseUsed = used + 1; v.excused = true;\n      const p0 = activeWlPasses()[0];\n      if (p0) { p0.uses = (p0.uses || 0) + 1; if (p0.dbId) await DB.update(T.WLP, p0.dbId, JSON.parse(JSON.stringify(p0))); }\n      pushMsg(S.session, 'sys', '已申诉：离开期间在通行证应用（' + (p0 ? p0.app : '') + '）内，本次不计违规');\n      await saveSession(true); render(); return;\n    }\n    await triggerPunish('专注中离开', act === 'a2' ? { forceMult: 2 } : {});\n  });\n}\n/* ---------- 开始 / 阶段流转 ---------- */\n/* ── 锁机分级 ──────────────────────────────────────────\n   assistLevelFor：本場专注的生效等级。优先级：专注设置页的本次选择 >\n   全局 focusLevel。返回 'off' | 'L1' | 'L2' | 'L3'。 */\nfunction assistLevelNow() { return cfg('focusLevel') || 'off'; }\nfunction assistLevelFor(session) {\n  const raw = (session && session.assistLevel) || S.draft.assistForSession;\n  /* 旧版本曾把 assistForSession 写成布尔 true；统一归一化为 L3，\n     否则后续与 'L3' 的比较全部失败，看守锁/自动开罚会被静默跳过。 */\n  if (raw === true) return 'L3';\n  if (raw) return raw;\n  return assistLevelNow();\n}\nasync function startSession(o) {\n  /* 防重复：已经有一段专注在跑时不再另起一段 ——\n     否则会出现两段同时计时，看起来就是「完成任务后又重复专注」 */\n  if (S.session && S.session.status === 'running') { toast('已经有一段专注在进行中'); go('running'); return S.session; }\n  /* L3 承诺死锁：先签承诺书（预授权：中途离开/失约自动按惩罚库执行）再开始 */\n  const pendingLevel = assistLevelFor(null);\n  if (pendingLevel === 'L3' && !o.pledged) {\n    const lib = (cfg('punishLib') || []).filter(p => p.enabled);\n    const first = lib.length ? `${lib[0].title}（${lib.length} 项启用中）` : '惩罚库当前为空 —— 记过不罚，但失约照记';\n    S.draft.pledgeOpts = o;\n    openSheet(`<h3>⚑ 承诺死锁 · 签承诺书</h3>\n      <div class=\"sub\">这是一次有约束力的专注。签字即预授权：</div>\n      <div class=\"tiny mt10\" style=\"line-height:1.9\">· 中途离开超过宽限（${Number(cfg('graceSec') || 8)} 秒）→ <b>不问原因，自动按惩罚库开罚</b>；<br>\n      · 暂停要过冷静期；<br>\n      · 当前惩罚库：<b>${esc(first)}</b>；<br>\n      · 失约照旧：写说明 + 连坐 + 扣币，TA 全都记着。</div>\n      <div class=\"row mt14\" style=\"gap:10px\">\n        <button class=\"btn ghost grow\" data-act=\"closeSheet\">先不开始</button>\n        <button class=\"btn primary grow\" data-act=\"pledgeStart\">✍️ 签承诺，开始</button></div>`);\n    return S.session || null;\n  }\n  if (pendingLevel === 'L3') S.draft.assistForSession = pendingLevel;   // 已签：本场锁定等级\n  const plan = (o.plan || []).filter(t => t.content && t.content.trim());\n  const cycles = Math.max(1, Number(o.cycles) || 1);\n  const s = {\n    id: '', createdAt: Date.now(), startAt: Date.now(), date: dkey(),\n    charIds: o.charIds.slice(), focusMin: Number(o.focusMin) || 25, breakMin: Number(o.breakMin) || 5,\n    cycles: cycles, cycle: 1, phase: 'focus',\n    phaseEndsAt: Date.now() + (Number(o.focusMin) || 25) * 60000,\n    totalFocusSec: 0, paused: false, pausedAt: 0, pauseReason: '', excuseUsed: 0,\n    plan: plan.map(t => ({ content: t.content.trim(), est: Number(t.est) || 0, done: false })),\n    extraTasks: [], violations: [], msgs: [], selfTasks: [],\n    lastMsgAt: Date.now(), lastSelfAt: Date.now(), status: 'running',\n    summary: '', feedback: '', weakness: [], advice: '', quizScore: 0, quizTotal: 0,\n    reviewEvery: o.reviewEvery || 'focus', voiceOn: !!o.voiceOn,\n    curTaskIdx: null, curTaskSince: Date.now(), taskAsked: false, passedRounds: 0,\n    wallpaperData: '', wallpaperRef: '', wallpaperLoading: false, wallpaperError: '', albumId: ''\n  };\n  const rec = await DB.create(T.SESSION, { data: s });\n  if (rec) s.id = rec.id;\n  S.session = s; S.lastTick = Date.now();\n  startTicking(); await saveSession(true);\n  pushMsg(s, 'sys', `专注开始 · ${s.charIds.length || 1} 位角色陪伴 · 第 1/${cycles} 轮`);\n  await genSelfTasks(s);\n  await scheduleNotices(s);\n  go('running');\n  /* 锁机分级：L1/L3 专注期勿扰（结束后由 tick 自动恢复） */\n  s.assistLevel = assistLevelFor(s);\n  S.draft.assistForSession = null;\n  if (s.assistLevel === 'L3') pushMsg(s, 'sys', '⚑ 承诺死锁生效：中途离开超宽限将自动开罚');\n  /* L2/L3：启动壳侧看守锁（白名单外的手机应用被带回小手机） */\n  if ((s.assistLevel === 'L2' || s.assistLevel === 'L3') && API && API.device && API.device.lockStart) {\n    /* Android 14：后台弹全屏封锁页需要悬浮窗权限，缺失时覆盖页会被系统静默挡住 */\n    if (API.device.overlayStatus) {\n      sdk(() => API.device.overlayStatus(), null).then((ov) => {\n        if (ov && ov.ok && !ov.granted) {\n          pushMsg(s, 'sys', '⚠️ 看守锁覆盖页需要「显示在其他应用上层」权限 —— 点这里去开启，否则拦住时只会弹通知');\n          toast('看守锁需要悬浮窗权限才能弹拦截页');\n          try { API.device.overlayRequest(); } catch (e) { }\n        }\n      }).catch(() => { });\n    }\n    const pkgs = lockedAppsFor();\n    s.lockUntil = Number(s.lockUntil) || sessionEndAt(s);\n    const until = s.lockUntil;\n    // 白名单为空也必须启动：空名单表示拦截所有其他应用，不能因为没勾白名单就静默跳过。\n    sdk(() => API.device.lockStart({ packages: JSON.stringify(pkgs), until }), null).then((r) => {\n      if (r && r.ok) {\n        S.settings.assistLockOn = true; saveSettings(true);\n        pushMsg(s, 'sys', pkgs.length\n          ? '🛰 看守锁已启动：白名单（' + pkgs.length + ' 个应用）外的手机应用会被带回'\n          : '🛰 看守锁已启动：白名单为空，所有其他手机应用都会被拦截');\n        render();\n      } else if (r && r.reason) pushMsg(s, 'sys', '🛰 看守锁没启动：' + r.reason);\n    }).catch(() => { });\n  }\n  if (s.assistLevel !== 'off' && API && API.device && API.device.dndSet) {\n    sdk(() => API.device.dndSet({ on: true }), null).then((r) => {\n      if (r && r.ok) { S.settings.assistDndOn = true; saveSettings(true); pushMsg(s, 'sys', '🔒 勿扰已开启（锁机助手，专注结束自动恢复）'); render(); }\n    }).catch(() => { });\n  }\n  setTimeout(() => roleSay(s, 'start'), 600);\n  /* 开始专注就先攒下第 1 张（锁着做背景）；之后每完成一个任务解锁一张 + 生成一张新的 */\n  s.walls = []; s.wallUnlocked = 0; s.wallTarget = 0;\n  ensureWall(s, 1, '这段专注的开始');\n  return s;\n}\nasync function onPhaseEnd() {\n  const s = S.session; if (!s) return;\n  if (s.phase === 'focus') {\n    /* totalFocusSec 已由 tick 逐秒累加（只算真正在走的秒数），这里不再按设定时长估算 */\n    if (s.reviewEvery === 'session' && (s.cycle || 1) < s.cycles) {\n      s.phase = 'break'; s.phaseEndsAt = Date.now() + s.breakMin * 60000;\n      pushMsg(s, 'sys', `第 ${s.cycle}/${s.cycles} 轮结束，休息 ${s.breakMin} 分钟`);\n      await saveSession(true); notify('休息一下', '角色也休息了，不催你'); render(); return;\n    }\n    s.status = 'review'; await releaseAssistLock(); stopTicking();\n    s.noteRestUntil = 0;                    // 纸条换来的休息：换阶段就结束\n    S.draft.reviewErr = '';                 // 新一轮校验：清掉上一轮的失败提示\n    pushMsg(s, 'sys', '本轮专注结束，进入校验流程');\n    await settleSelfTasks(s, pickOneChar(s.charIds), '这轮专注结束了');\n    await saveSession(true); notify('专注结束', '来填写本次学习反馈与总结吧');\n    go('review'); return;\n  }\n  s.cycle = (s.cycle || 1) + 1;\n  if (s.cycle > s.cycles) { s.status = 'done'; s.endAt = Date.now(); await releaseAssistLock(); stopTicking(); await saveSession(true); render(); return; }\n  s.phase = 'focus'; s.phaseEndsAt = Date.now() + s.focusMin * 60000;\n  pushMsg(s, 'sys', `休息结束 · 第 ${s.cycle}/${s.cycles} 轮专注开始`);\n  await saveSession(true); render(); roleSay(s, 'start');\n}\nasync function scheduleNotices(s) {\n  if (!cfg('notif') || !API || !API.tasks) return;\n  const name = charName(pickOneChar(s.charIds));\n  const lines = ['还在吗？我这没看到你动静。', '进度怎么样了，说一声。', '别让我等太久。'];\n  const total = s.focusMin * 60000;\n  for (let i = 0; i < 3; i++) {\n    await sdk(() => API.tasks.schedule({\n      id: 'focus_' + (s.id || 'x') + '_' + i, delayMs: Math.round(total * [0.5, 0.75, 1][i]),\n      actions: [\n        { type: 'notification', title: name + ' 在等你', body: lines[i] },\n        { type: 'shell.notify', title: name + ' 在等你', body: lines[i] }\n      ]\n    }));\n  }\n}\n/* ---------- 角色互动 ---------- */\nfunction shouldSpeak(kind) {\n  const m = cfg('voiceMode') || 'cue';\n  if (m === 'off') return false;\n  if (m === 'all') return true;\n  return ['nudge', 'punish', 'wake', 'start', 'alarm', 'story', 'invite'].indexOf(kind) >= 0;\n}\nconst VOICE_MODES = [['off', '不语音'], ['cue', '只语音催促/惩罚/唤醒'], ['all', '每条角色消息都语音']];\nasync function roleSay(s, kind) {\n  quietOn();          // 角色自己定时开口：不锁住你的操作\n  try {\n  if (!s || !s.charIds || !s.charIds.length) return;\n  const chars = s.charIds.map(charById).filter(Boolean);\n  if (!chars.length) return;\n  const c = chars[Math.floor(Math.random() * chars.length)];\n  const doneN = (s.plan || []).filter(t => t.done).length;\n  const left = Math.round(remainSec() / 60);\n  let pid = 'say.cheer', pvars = {};\n  const noteCtx = noteLineFor(c.id, 5, 'focus');\n  if (kind === 'start') { pid = 'say.start'; pvars = { focusMin: s.focusMin, goal: goalPromptLine(), notes: noteCtx }; }\n  else if (kind === 'nudge') { pid = 'say.nudge'; pvars = { left: left, doneN: doneN, total: s.plan.length, notes: noteCtx }; }\n  else if (kind === 'cheer') { pid = 'say.cheer'; pvars = { notes: noteCtx }; }\n  else if (kind === 'self') {\n    const st = (s.selfTasks || []).find(x => x.charId === c.id);\n    pid = 'say.self'; pvars = { selfTask: st ? st.text : '陪着他学习', notes: noteCtx };\n  }\n  let text = '';\n  try { text = await pGen(pid, pvars, [c.id]); } catch (e) { text = ''; }\n  if (!text) text = kind === 'nudge' ? '进度怎么样了？跟我说一声。' : '我在，继续吧。';\n  /* 以前这里砍到 120 字 —— 模型写长一点就会被拦腰砍断，语音读的也是这份残句，\n     看起来就是「消息和语音都不全」。放宽到 400 字，并在提示词里要求说短。 */\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 400);\n  pushMsg(s, 'char', text, { charId: c.id, kind: kind, voice: shouldSpeak(kind) });\n  s.lastMsgAt = Date.now();\n  await saveSession(); render();\n  if (shouldSpeak(kind)) speak(c.id, text);\n  await syncTimeline(c.id, `【专注陪伴】${c.name}对用户说：${text}`, 'focus_companion', {});\n  await syncChatLine(c.id, text, 'assistant');\n  } finally { quietOff(); }\n}\nasync function genSelfTasks(s) {\n  quietOn();          // 开始专注时自动生成：不锁住你的操作\n  try {\n  for (const c of s.charIds.map(charById).filter(Boolean)) {\n    let t = '';\n    try {\n      t = await pGen('say.selftask', { focusMin: s.focusMin }, [c.id]);\n    } catch (e) { t = ''; }\n    if (!t) t = '陪你一起把这段时间走完';\n    s.selfTasks.push({ charId: c.id, text: t.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 30), progress: 0 });\n  }\n  pushMsg(s, 'sys', '角色们也领了自己的任务：' + s.selfTasks.map(x => `${charName(x.charId)}「${x.text}」`).join('，'));\n  await saveSession(true);\n  } finally { quietOff(); }\n}\n/* ---------- 连坐：你和 TA 的任务绑在一起 ----------\n   TA 在这个时段也有自己的事（selfTasks）。它的进度不再自己乱涨，\n   而是完全跟着你的表现走：你完成 → 一起往前；你违规/没通过 → 一起退。\n*/\n/* 连坐已移除：你的表现不再影响 TA 的进度。\n   但进度本身要能看见 —— 之前 selfTasks 建好之后就再没更新过，界面永远显示 0%。\n   这里做的只有一件事：把「你已经完成的量」如实映射过去，让 TA 的任务进度和你的同步。 */\nfunction syncSelfTasksFromPlan(s) {\n  if (!s || !(s.selfTasks || []).length) return false;\n  const doneAll = (s.plan || []).filter(t => t.done).length + (s.extraTasks || []).filter(t => t.done).length;\n  const totalAll = (s.plan || []).length + (s.extraTasks || []).length;\n  const pct = totalAll ? Math.round(clamp(doneAll / totalAll * 100, 0, 100)) : 0;\n  let changed = false;\n  (s.selfTasks || []).forEach(t => {\n    if (t.progress !== pct) { t.progress = pct; changed = true; }\n    if (!t.done && pct >= 100) { t.done = true; t.doneAt = Date.now(); }\n  });\n  return changed;\n}\nfunction bumpSelfTasks(s, d, why) {\n  /* 保留空壳：连坐不再改数值。进度只由「你完成的任务」推动（见 syncSelfTasksFromPlan）。 */\n  return;\n}\n/* 一轮结束时结算：TA 的事没做完，就是被你拖的 */\nasync function settleSelfTasks(s, cid, why) {\n  /* 连坐功能已移除：不会再判定「因为你没做完」，也不会让 TA 来念你 */\n  return;\n}\nfunction maybeMessaging() {\n  const s = S.session;\n  if (!s || s.status !== 'running' || s.paused || s.phase === 'break') return;\n  const gap = Math.max(2, Number(cfg('msgGapMin') || 8)) * 60000;\n  const now = Date.now();\n  if (now - (s.lastMsgAt || 0) > gap && !S.msgBusy) {\n    S.msgBusy = true;\n    const kind = Math.random() < 0.5 ? 'nudge' : (Math.random() < 0.5 ? 'self' : 'cheer');\n    roleSay(s, kind).finally(() => { S.msgBusy = false; });\n  }\n  // 进度只由你的表现推动（和你完成的任务同步）；这里定期汇报一次现状\n  if (now - (s.lastSelfAt || 0) > gap * 1.6 && (s.selfTasks || []).length) {\n    s.lastSelfAt = now;\n    syncSelfTasksFromPlan(s);\n    pushMsg(s, 'sys', '你们一起的事：' + s.selfTasks.map(x => charName(x.charId) + ' 的「' + x.text + '」' + (x.progress || 0) + '%').join('，') + '（你跟得上，他们就跟得上）');\n    saveSession();\n  }\n}\n/* ==========================================================\n   小纸条 × 星星瓶\n   ----------------------------------------------------------\n   专注撑不下去的那一下，可以写张小纸条递给角色。他会像在\n   纸条边上写字一样给你一句批注；心情对了，他还会松一松：\n   让你歇一会儿 / 多攒一张壁纸 / 现在就出声哄你一句。\n   所有纸条都收进「星星瓶」——那些坚持不下去的瞬间，他都\n   在，而且每一张他写给你的话都留着。\n   他哄你睡的时候，也会接着你今天递过的纸条说。\n   ========================================================== */\nfunction noteLimit() { return clamp(Number(cfg('noteLimit') != null ? cfg('noteLimit') : 3) || 0, 0, 20); }\nfunction noteRestMin() { return clamp(Number(cfg('noteRestMin') != null ? cfg('noteRestMin') : 5) || 1, 1, 60); }\nfunction noteRewardKinds() {\n  const k = cfg('noteRewardKinds');\n  return (Array.isArray(k) && k.length) ? k : ['rest', 'wall', 'voice'];\n}\nfunction noteAll() { return (S.notes || []).slice().sort((a, b) => (b.at || 0) - (a.at || 0)); }\nfunction noteOfSession(s) {\n  return (S.notes || []).filter(n => s && String(n.sessionId) === String(s.id)).sort((a, b) => (a.at || 0) - (b.at || 0));\n}\nfunction noteById(id) { return (S.notes || []).find(x => String(x.id) === String(id)) || null; }\nasync function saveNote(rec) {\n  if (!rec) return null;\n  if (rec.id) { await DB.update(T.NOTE, rec.id, JSON.parse(JSON.stringify(rec))); return rec; }\n  const r = await DB.create(T.NOTE, rec);\n  if (r) { rec.id = r.id; S.notes = [rec].concat(S.notes || []); }\n  return rec;\n}\nasync function delNote(rec) {\n  if (!rec || !rec.id) return;\n  await DB.remove(T.NOTE, rec.id);\n  S.notes = (S.notes || []).filter(x => String(x.id) !== String(rec.id));\n}\n/* 递纸条的仪式感：纸条折起来 → 飞向星星瓶 → 瓶身晃一下。\n   ⚠️ 这个函数一直漏了定义 —— CSS 里 .noteFly/.fold/.jar/.plus 和三个 keyframes 都在，\n   sendNote 里也一直调它，但函数本身从没写出来。结果是一递纸条就抛\n   「noteFly is not defined」，把 sendNote 的后半段（问 AI 批注、存纸条）整段打断。\n   这里补齐；并且内部全程 try/catch —— 动画只是锦上添花，\n   就算它出任何问题，也绝不能影响「把纸条递出去」这件正事。 */\nfunction noteFly(text) {\n  try {\n    const t = String(text || '').trim().slice(0, 46);\n    const host = document.createElement('div');\n    host.className = 'noteFly';\n    host.innerHTML = '<div class=\"fold\"></div><div class=\"jar\">🫙</div><div class=\"plus\">纸条收进星星瓶</div>';\n    const fold = host.querySelector('.fold');\n    if (fold) fold.textContent = t || '（一张小纸条）';\n    (document.body || document.documentElement).appendChild(host);\n    setTimeout(function () { try { host.remove(); } catch (e) { } }, 1700);\n  } catch (e) { }\n}\n/* 递一张小纸条：写 → 他批注 →（可能）松一松 → 收进星星瓶 */\nasync function sendNote(text) {\n  text = String(text || '').trim();\n  if (!text) { toast('先写点什么再递给他'); return; }\n  const s = S.session;\n  const cid = pickOneChar(s ? s.charIds : null) || anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  const used = noteOfSession(s).length;\n  const limit = noteLimit();\n  if (limit && used >= limit) { toast('这一场已经递了 ' + used + ' 张纸条 —— 他记着呢，先把这段走完'); return; }\n  /* 先把纸条折起来飞进星星瓶，再去问他 —— 有这一下更像「递出去」了。\n     再加一层保护：动画万一出问题，也绝不能拦住后面的批注与存档。 */\n  try { noteFly(text); } catch (e) { }\n  const allowKinds = (used + 1) > Math.max(1, Math.floor(limit / 2)) ? [] : noteRewardKinds();\n  let data = null;\n  S.busy = 'note'; render();\n  try {\n    const out = await pGen('note.judge', {\n      note: text.slice(0, 200),\n      elapsed: Math.max(1, Math.round((s ? (s.totalFocusSec || 0) : 0) / 60)),\n      left: Math.max(0, Math.round(remainSec() / 60)),\n      doneN: s ? (s.plan || []).filter(t => t.done).length : 0,\n      total: s ? (s.plan || []).length : 0,\n      used: used + 1,\n      limit: limit || '不限',\n      allowReward: allowKinds.length ? ('这次可以给 —— 在 ' + allowKinds.map(k => ({ rest: '让他歇一会儿', wall: '多攒一张壁纸', voice: '出声哄他一句' }[k])).join(' / ') + ' 里挑一种。') : '这次不要再给了（他这一场已经用掉几次机会了），reward 填 \"none\"。'\n    }, [cid]);\n    data = parseJSON(out);\n  } catch (e) { data = null; }\n  S.busy = '';\n  if (!data || !data.reply) {\n    let line = '';\n    try { line = await pGen('note.reply', { note: text.slice(0, 200) }, [cid]); } catch (e) { line = ''; }\n    data = { reply: line || '我看到了。先把手上的这一段走完，我一直在这儿。', ann: '', push: '', reward: 'none', why: '' };\n  }\n  const rec = {\n    text: text.slice(0, 200), reply: String(data.reply || '').slice(0, 120),\n    ann: String(data.ann || '').slice(0, 160), push: String(data.push || '').slice(0, 40),\n    reward: (allowKinds.indexOf(String(data.reward)) >= 0) ? String(data.reward) : 'none',\n    why: String(data.why || '').slice(0, 120),\n    charId: cid, sessionId: s ? s.id : '', at: Date.now(), date: dkey(),\n    elapsedMin: s ? Math.max(1, Math.round((s.totalFocusSec || 0) / 60)) : 0\n  };\n  await saveNote(rec);\n  if (s) { pushMsg(s, 'char', rec.reply, { charId: cid, kind: 'note' }); await saveSession(true); }\n  await syncTimeline(cid, `用户在专注撑不下去的时候给他递了一张小纸条：「${rec.text}」。你写给他的批注：${rec.ann || rec.reply}${rec.reward !== 'none' ? '（你松了松他）' : ''}`, 'focus_note', {});\n  /* 松一松 */\n  if (rec.reward === 'rest' && s) {\n    const min = noteRestMin();\n    s.paused = true; s.pausedAt = Date.now(); s.pauseReason = '纸条：你让我松一口气';\n    s.noteRestUntil = Date.now() + min * 60000;\n    pushMsg(s, 'sys', `🌿 他让你松一口气：这 ${min} 分钟不计入专注，到点自动接着走`);\n    await saveSession(true);\n  } else if (rec.reward === 'wall' && s) {\n    s.wallUnlocked = Math.max(Number(s.wallUnlocked) || 0, (s.walls || []).length);\n    await unlockWalls(s, s.wallUnlocked + 1);\n    ensureWall(s, (s.walls || []).length + 2, '纸条里他让我再坚持了一会');\n  } else if (rec.reward === 'voice') {\n    await speak(cid, rec.reply, 'note', '小纸条 · 哄你一句');\n  }\n  /* 刚递的这张默认展开，省得你还要点一下才看到他的批注 ——\n     必须在 render() 之前写好状态，否则这一屏画出来时还没展开 */\n  S.draft.noteOpenOn = String(rec.id || '');\n  S.draft.noteExpand = true;\n  S.draft.noteExpandAll = false;\n  render();\n  toast(rec.reward === 'none' ? '他写了一句给你' : ({ rest: '他说：歇一会儿吧', wall: '他多给了你一张壁纸', voice: '他在你耳边说了一句' }[rec.reward] || '他回你了'));\n  try {\n    const bar = document.querySelector('[data-note-board]');\n    if (bar) setTimeout(function () { try { bar.scrollIntoView({ block: 'start', behavior: 'smooth' }); } catch (e) { } }, 120);\n  } catch (e) { }\n  return rec;\n}\n/* ---------- 专注页上的纸条栏：递过的纸条都在这里，点开就能看批注 ----------\n   递一张就长一条，默认最新那张是展开的；批注、他松你的方式、\n   还有「听他说这句」「发到聊天室」都能就地操作，不用跑去星星瓶。 */\nfunction noteBoardHTML() {\n  const s = S.session;\n  const list = noteOfSession(s).slice().reverse();   // 最新在上\n  const openAll = !!S.draft.noteExpandAll;\n  const openId = String(S.draft.noteOpenOn || '');\n  const head = `<div class=\"row between\"><h3>🫙 这场递过的纸条</h3>\n    <span class=\"row\" style=\"gap:6px\">${list.length > 1 ? `<button class=\"btn sm ghost\" data-act=\"noteToggleAll\">${openAll ? '全部收起' : '全部展开'}</button>` : ''}\n    <button class=\"btn sm ghost\" data-act=\"gotoView\" data-view=\"bottle\">星星瓶</button></span></div>`;\n  if (!list.length) return `<div class=\"card\">${head}\n    <div class=\"tiny mt6\">撑不住的时候写一张递给他 —— 他会写在纸条边上给你一句，写过的都留在这。</div></div>`;\n  return `<div class=\"card\">${head}\n    <div class=\"tiny mt6\">一共 ${list.length} 张${list.filter(n => n.reward && n.reward !== 'none').length ? ' · 他松过你 ' + list.filter(n => n.reward && n.reward !== 'none').length + ' 次' : ''}。点条目就能展开看他的批注。</div>\n    <div class=\"mt10\">${list.map(n => {\n      const open = openAll || String(n.id) === openId;\n      return `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:8px;border-color:${open ? 'rgba(255,201,120,.5)' : 'var(--line)'}\">\n      <div data-act=\"noteOpenItem\" data-id=\"${esc(n.id)}\" style=\"cursor:pointer\">\n        <div class=\"row between\"><span class=\"tiny\">${hm(n.at)} · 专注第 ${n.elapsedMin || 0} 分钟</span>\n          <span class=\"row\" style=\"gap:5px\">${n.reward && n.reward !== 'none' ? `<span class=\"pill warn\">${noteRewardLabel(n.reward)}</span>` : ''}\n          <span class=\"tiny\">${open ? '收起 ▲' : '看批注 ▼'}</span></span></div>\n        <div style=\"font-size:13.2px;line-height:1.65;margin-top:5px\">「${esc(n.text)}」</div>\n      </div>\n      ${open ? `<div style=\"margin-top:8px;padding-left:9px;border-left:2px solid rgba(255,201,120,.55)\">\n          <div class=\"tiny\" style=\"color:#ffe0b0\">${esc(charName(n.charId))} 的批注</div>\n          <div style=\"font-size:13px;line-height:1.75;margin-top:3px;color:#ffe0b0\">${esc(n.ann || n.reply)}</div>\n          ${n.why ? `<div class=\"tiny mt6\" style=\"color:var(--dim2)\">${esc(n.why)}</div>` : ''}</div>\n        <div class=\"row mt8\" style=\"gap:8px\">\n          <button class=\"btn sm ghost grow\" data-act=\"noteReplay\" data-id=\"${esc(n.id)}\">🔊 听他说这句</button>\n          <button class=\"btn sm ghost grow\" data-act=\"noteToChat\" data-id=\"${esc(n.id)}\">📨 发到聊天室</button>\n          <button class=\"btn sm ghost\" data-act=\"noteDel\" data-id=\"${esc(n.id)}\">撕掉</button></div>` : ''}\n    </div>`;\n    }).join('')}</div></div>`;\n}\nfunction noteRewardLabel(r) {\n  return { rest: '🌿 松一口气', wall: '🖼 多一张壁纸', voice: '🔊 哄你一句' }[r] || '';\n}\n/* ---------- 把纸条带进角色接下来要说的话里 ----------\n   他给纸条写过批注，说明他知道你哪一段撑不住；那接下来陪你的这几句\n   就该接得上 —— 不是空口「加油」，而是「刚才你说坐不住了，我们把手上的\n   这一节收个尾」。这里生成一段可直接塞进提示词的上下文，供开场/催促/\n   鼓励共用。noteLineFor 是给单个角色取，纸条按时间正序、最多 5 张。 */\nfunction noteLineFor(charId, limit, scope) {\n  const allow = (scope === 'sleep') ? (cfg('noteLinkSleep') !== false) : (cfg('noteLinkFocus') !== false);\n  if (!allow) return '';\n  let mine = (S.notes || []).filter(n => n && n.text);\n  if (charId) {\n    const own = mine.filter(n => String(n.charId) === String(charId));\n    if (own.length) mine = own;\n  }\n  if (!mine.length) return '';\n  const list = mine.slice().sort((a, b) => (a.at || 0) - (b.at || 0)).slice(-(limit || 5));\n  const today = dkey();\n  const lines = list.map(n =>\n    '· ' + (n.date === today ? '今天' : (n.date || '')) + ' 专注第 ' + (n.elapsedMin || 0) + ' 分钟，他说：「' + String(n.text).slice(0, 60) + '」'\n    + '｜你当时写给他的：' + String(n.ann || n.reply || '').slice(0, 60)\n    + (n.reward && n.reward !== 'none' ? '（' + noteRewardLabel(n.reward) + '）' : '')).join('\\n');\n  const early = list.slice(0, 2).map(n => String(n.text).slice(0, 24)).filter(Boolean).join('、');\n  return '【他递过的小纸条 —— 接下来这几句要接得上】\\n' + lines + '\\n' +\n    '说话时请落到具体处：他撑不住的点（' + (early || '刚才那几下') + '）你记着，鼓励就顺着它说 ——' +\n    '该松一口气的时候先让他喘一下，该往回拉的时候就直接点出来；不要只说「加油」「你可以的」。\\n' +\n    '另外：纸条是他私下递给你的，不要复述原文、不要说「你写的纸条」，用你自己的话接住就行。';\n}\n/* 星星瓶在首页只留一行 —— 以前是把纸条内容整段摊在首页，一直挂着。\n   想看全部去「内容库 → 星星瓶」。这个函数只吐一行汇总。 */\nfunction notesBottleLine() {\n  const all = noteAll();\n  if (!all.length) return '';\n  const today = dkey();\n  const todayN = all.filter(n => n.date === today).length;\n  return `<div class=\"card tight\">\n    <div class=\"row between\"><div class=\"grow\">\n      <div class=\"tiny\">⭐ 星星瓶</div>\n      <div style=\"font-size:13.5px\">${all.length} 张纸条${todayN ? ' · 今天 ' + todayN + ' 张' : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"gotoView\" data-view=\"bottle\">看看</button></div>\n  </div>`;\n}\n/* 星星瓶：所有递过的纸条 + 他写在上面的字（瓶子页里用这个完整版） */\nfunction notesBottleHTML(limit) {\n  const all = noteAll();\n  if (!all.length) return '';\n  const list = all.slice(0, limit || 3);\n  return `<div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,201,120,.13),rgba(165,139,255,.09));border-color:rgba(255,201,120,.28)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>⭐ 星星瓶（${all.length} 张）</h3>\n      <div class=\"tiny\">那些坚持不下去的瞬间 —— 有我在，多坚持一会吧。</div></div>\n      <button class=\"btn sm ghost\" data-act=\"gotoView\" data-view=\"bottle\">看看</button></div>\n    <div class=\"mt10\">${list.map(n => `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:8px\">\n      <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(n.at))} ${hm(n.at)} · ${esc(charName(n.charId))}${n.reward && n.reward !== 'none' ? ' · ' + noteRewardLabel(n.reward) : ''}</span>\n        <span class=\"tiny\">专注第 ${n.elapsedMin || 0} 分钟</span></div>\n      <div style=\"font-size:13.4px;line-height:1.7;margin-top:5px\">「${esc(n.text)}」</div>\n      <div style=\"font-size:12.8px;line-height:1.7;margin-top:7px;padding-left:9px;border-left:2px solid rgba(255,201,120,.55);color:#ffe0b0\">${esc(n.ann || n.reply)}</div>\n      ${n.push ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">${esc(n.push)}</div>` : ''}\n    </div>`).join('')}</div>\n    ${all.length > list.length ? `<div class=\"tiny center mt6\">还有 ${all.length - list.length} 张在星星瓶里</div>` : ''}\n  </div>`;\n}\nVIEWS.bottle = function () {\n  const all = noteAll();\n  const open = S.draft.noteOpen ? noteById(S.draft.noteOpen) : null;\n  const today = dkey();\n  const todayN = all.filter(n => n.date === today).length;\n  const rewardN = all.filter(n => n.reward && n.reward !== 'none').length;\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,201,120,.15),rgba(165,139,255,.1));border-color:rgba(255,201,120,.3)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>⭐ 星星瓶</h3>\n      <div class=\"tiny mt6\">那些坚持不下去的瞬间 —— 有我在，多坚持一会吧。</div></div>\n      <div style=\"font-size:30px\">🫙</div></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length}</div><div class=\"tiny\">收集的纸条</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${todayN}</div><div class=\"tiny\">今天</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600;color:var(--gold)\">${rewardN}</div><div class=\"tiny\">他松过你</div></div>\n    </div>\n    <div class=\"tiny mt8\">专注时写张小纸条递给他：他会在纸条边上给你写一句；心情对了，还会让你歇一会儿、多攒一张壁纸、或者现在就出声哄你一句。他哄你睡的时候，也会接着你今天递过的纸条说。</div>\n  </div>\n  ${all.length ? `<div class=\"card\"><h3>全部纸条（${all.length}）</h3>\n    ${all.slice(0, 60).map(n => `<div class=\"card tight ${open && String(open.id) === String(n.id) ? 'glow' : ''}\" style=\"background:var(--card2);margin-bottom:9px\">\n      <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(n.at))} ${hm(n.at)} · 专注第 ${n.elapsedMin || 0} 分钟</span>\n        <span class=\"row\" style=\"gap:5px\">${n.reward && n.reward !== 'none' ? `<span class=\"pill warn\">${noteRewardLabel(n.reward)}</span>` : ''}\n        <button class=\"btn sm ghost\" data-act=\"noteDel\" data-id=\"${esc(n.id)}\">撕掉</button></span></div>\n      <div style=\"font-size:13.4px;line-height:1.7;margin-top:6px\">「${esc(n.text)}」</div>\n      <div style=\"font-size:12.9px;line-height:1.7;margin-top:7px;padding-left:9px;border-left:2px solid rgba(255,201,120,.55);color:#ffe0b0\">\n        <b>${esc(charName(n.charId))} 的批注：</b>${esc(n.ann || n.reply)}</div>\n      ${n.push ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">「${esc(n.push)}」</div>` : ''}\n      ${n.why ? `<div class=\"tiny mt6\" style=\"color:var(--dim2)\">${esc(n.why)}</div>` : ''}\n      ${!n.ann ? '' : ''}\n      <div class=\"row mt8\" style=\"gap:8px\">\n        ${(n.ann || n.reply) ? `<button class=\"btn sm ghost grow\" data-act=\"noteReplay\" data-id=\"${esc(n.id)}\">🔊 听他说这句</button>` : ''}\n        <button class=\"btn sm ghost grow\" data-act=\"noteToChat\" data-id=\"${esc(n.id)}\">📨 发到聊天室</button></div>\n    </div>`).join('')}</div>`\n      : `<div class=\"empty\">星星瓶还是空的。<br>专注的时候，撑不下去就写一张 —— 他会给你留一句话在这里。</div>`}\n  <div class=\"card\"><h3>设置</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">每场最多递几张</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.noteLimit\" data-num=\"1\" value=\"${noteLimit()}\"></div>\n      <div class=\"grow\"><label class=\"fl\">「松一口气」给几分钟</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.noteRestMin\" data-num=\"1\" value=\"${noteRestMin()}\"></div>\n    </div>\n    <label class=\"fl\">他可以用什么方式松你一下</label>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${noteRewardKinds().indexOf('rest') >= 0 ? 'on' : ''}\" data-act=\"toggleNoteReward\" data-k=\"rest\">🌿 让你歇一会儿</button>\n      <button class=\"chip ${noteRewardKinds().indexOf('wall') >= 0 ? 'on' : ''}\" data-act=\"toggleNoteReward\" data-k=\"wall\">🖼 多攒一张壁纸</button>\n      <button class=\"chip ${noteRewardKinds().indexOf('voice') >= 0 ? 'on' : ''}\" data-act=\"toggleNoteReward\" data-k=\"voice\">🔊 现在就哄你一句</button>\n    </div>\n    <div class=\"tiny mt8\">纸条要不要影响他说话 —— 专注和哄睡分开管，互不牵连：</div>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('noteLinkFocus') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"noteLinkFocus\">专注时接住纸条说话</button>\n      <button class=\"chip ${cfg('noteLinkSleep') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"noteLinkSleep\">哄睡时接住纸条说话</button>\n    </div>\n    <div class=\"tiny mt6\">打开「专注时」：专注页里他说的开场、催促、鼓励、汇报自己的进度，都会接着你最近递过的纸条说（不会念出原文）。<br>打开「哄睡时」：哄你睡的那一句会接着今天的纸条说。两个互不影响，想只留一边也行。</div>\n    <div class=\"tiny mt6\">一场里递得越多，他越不会再松你（前半场才容易松）—— 撑住的那部分，他其实都看在眼里。</div>\n  </div>`;\n};\nObject.assign(ACTIONS, {\n  /* 展开 / 收起某一条纸条的批注 */\n  noteOpenItem: el => {\n    const id = String(el.dataset.id || '');\n    if (!id) return;\n    if (String(S.draft.noteOpenOn || '') === id) { S.draft.noteOpenOn = ''; S.draft.noteExpand = false; }\n    else { S.draft.noteOpenOn = id; S.draft.noteExpand = true; }\n    S.draft.noteExpandAll = false;\n    render();\n  },\n  noteToggleAll: () => { S.draft.noteExpandAll = !S.draft.noteExpandAll; render(); },\n  noteOpen: () => {\n    const s = S.session;\n    if (!s || s.status !== 'running') { toast('先开始一段专注，再来递纸条'); return; }\n    const used = noteOfSession(s).length, limit = noteLimit();\n    if (limit && used >= limit) { toast('这一场已经递了 ' + used + ' 张了'); return; }\n    const quick = ['我真的撑不住了', '好想拿起手机', '这题不会，有点烦', '坐不住了，想站起来走走', '有点困，眼皮打架'];\n    const w = openSheet(`<h3>📝 写张小纸条给他</h3>\n      <div class=\"tiny\">现在专注到第 ${Math.max(1, Math.round((s.totalFocusSec || 0) / 60))} 分钟，还剩约 ${Math.max(0, Math.round(remainSec() / 60))} 分钟。这一场还能递 ${limit ? Math.max(0, limit - used) : '不限'} 张。</div>\n      <div class=\"chips mt10\">${quick.map(x => `<button class=\"chip\" data-nq=\"${esc(x)}\">${esc(x)}</button>`).join('')}</div>\n      <textarea id=\"noteText\" style=\"min-height:96px;margin-top:8px\" placeholder=\"想说什么就写什么 —— 撑不住了、想放弃、或者只是想跟他说一声\"></textarea>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">再忍忍</button>\n        <button class=\"btn primary grow\" data-act=\"noteSend\">递给他</button></div>`);\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-nq]'); if (!b) return;\n      const t = document.getElementById('noteText');\n      if (t) t.value = t.value ? (t.value + '　' + b.dataset.nq) : b.dataset.nq;\n      w.querySelectorAll('[data-nq]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  noteSend: async () => {\n    const t = document.getElementById('noteText');\n    const v = t ? (t.value || '').trim() : '';\n    if (!v) { toast('先写点什么'); return; }\n    closeAllSheets();\n    await sendNote(v);\n  },\n  noteDel: async el => {\n    const n = noteById(el.dataset.id);\n    if (!n) return;\n    const ok = await confirmBox('撕掉这张纸条？', '「' + n.text + '」和他写在上面的批注都会消失，不可恢复。', '撕掉');\n    if (!ok) return;\n    await delNote(n); toast('已撕掉'); render();\n  },\n  noteReplay: async el => {\n    const n = noteById(el.dataset.id);\n    if (!n) return;\n    const ok = await speak(n.charId || anyCharId(), n.ann || n.reply, 'note', '纸条批注');\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  noteToChat: async el => {\n    const n = noteById(el.dataset.id);\n    if (!n) return;\n    const cid = n.charId || anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    await sdk(() => API.chat.writeHistory({\n      characterId: cid, role: 'system',\n      content: '[小纸条] 他在专注第 ' + (n.elapsedMin || 0) + ' 分钟时递给我一张纸条：「' + n.text + '」。我写在上面的批注：' + (n.ann || n.reply)\n    }), null);\n    toast('已发到聊天室');\n  },\n  toggleNoteReward: async el => {\n    const k = el.dataset.k;\n    const arr = noteRewardKinds().slice();\n    const i = arr.indexOf(k);\n    if (i >= 0) { if (arr.length <= 1) { toast('至少留一种'); return; } arr.splice(i, 1); } else arr.push(k);\n    S.settings.noteRewardKinds = arr;\n    await saveSettings(true); render();\n  }\n});\n/* ==========================================================\n   惩罚系统（v1.9.2 校验标记 A）\n   ========================================================== */\nasync function savePun(rec) {\n  if (!rec) return;\n  if (rec.dbId) await DB.update(T.PUN, rec.dbId, { data: rec });\n  else { const r = await DB.create(T.PUN, { data: rec }); if (r) rec.dbId = r.id; }\n}\nfunction pendingPunish() { return (S.puns || []).filter(p => p.status === 'pending'); }\nfunction reasonText(r) {\n  const m = { '专注中离开': '专注中途离开了页面', '任务超时未完成': '任务超时未完成', '未计时开始任务': '没有开启倒计时就直接开始任务', '考核未通过': '专注结束的考核没通过', '预约专注没有开始': '约好的专注时间到了，TA 连着催了三次你都没有点「现在开始」' };\n  return m[r] || r;\n}\nasync function triggerPunish(reason, opt) {\n  opt = opt || {};\n  const s = S.session;\n  if (cfg('pardonDate') === dkey()) { toast('今天用了「放你一马」：本次违规只记录、不罚'); return null; }\n  if (!cfg('punishEnabled')) { toast('惩罚模式未开启，本次仅记录'); return null; }\n  const lib = (cfg('punishLib') || []).filter(p => p.enabled);\n  if (!lib.length) { toast('惩罚库为空，请到「我的 → 惩罚库」添加'); return null; }\n  const item = lib[Math.floor(Math.random() * lib.length)];\n  const mult = opt.forceMult || completionMult(s);\n  const rec = {\n    id: uid(), reason: reason, kind: item.kind, title: item.title, detail: item.detail || '',\n    mult: mult, status: 'pending', at: Date.now(), doneAt: 0,\n    amount: Math.round((Number(item.amount) || 10000) * mult),\n    count: Math.round((Number(item.count) || 20) * mult),\n    ratio: Number(item.ratio) || 80,\n    gift: item.gift || '一件小礼物', price: Math.round((Number(item.price) || 199) * mult),\n    text: item.text || '', minWords: Number(item.minWords) || 200,\n    actName: item.actName || item.title || '做一件小事',\n    checkinMin: Number(item.checkinMin) || 20, checkinGap: Number(item.checkinGap) || 5,\n    checkinCount: Number(item.checkinCount) || 4, checkinDone: 0, checkinAt: [], nextAt: 0,\n    charId: pickOneChar(s ? s.charIds : null), line: '', sessionId: s ? s.id : ''\n  };\n  const pr = await DB.create(T.PUN, { data: rec });\n  if (pr) rec.dbId = pr.id;\n  S.puns.unshift(rec);\n  /* 转账 / 送礼这两类要花钱：先进锁定页让你自己确认，\n     同时给你三条路 —— 直接执行 / 完成任务补救 / 再约一段专注补救；\n     超过设定时间没确认，才会自动扣款。 */\n  const needMoney = (rec.kind === 'pay' || rec.kind === 'gift');\n  const autoSec = Math.max(0, Number(cfg('punishAutoSec') != null ? cfg('punishAutoSec') : 300));\n  rec.autoSec = autoSec;\n  S.quiz = null;\n  if (needMoney && autoSec > 0) {\n    rec.confirmUntil = Date.now() + autoSec * 1000;\n    S.lock = { punish: rec };\n    if (s) { pushMsg(s, 'sys', `⚠️ 触发惩罚：${rec.title}（${multLabel(mult)}）· 等你确认（超时自动执行）`); saveSession(true); }\n    render(); genPunishLine(rec);\n    startLockTick(rec);\n    return rec;\n  }\n  S.lock = needMoney ? null : { punish: rec };\n  if (s) { pushMsg(s, 'sys', `⚠️ 触发惩罚：${rec.title}（${multLabel(mult)}）${needMoney ? ' · 直接执行' : ''}`); saveSession(true); }\n  render(); genPunishLine(rec);\n  if (needMoney) autoRunPunish(rec, true);\n  return rec;\n}\n/* ---------- 申请制白名单：通行证由 TA 审批签发（§7.5 M2 版） ----------\n   流程：申请单（应用/用途/时长/自愿条款）→ 聊天室申请卡 → TA 审批（wl.review 提示词，\n   JSON 强约束）→ 批复卡写回聊天室 + 通行证入库（active/rejected）。\n   生效中的通行证 = 中途离开豁免的合法依据（askAwayExcuse 读这里，不再读手填白名单）；\n   旧 settings.whitelist 保留为「未签发档案」，可一键按旧条目发起申请。 */\nfunction activeWlPasses() {\n  for (const p of (S.wlPasses || [])) {\n    if (p.status === 'active' && p.expireAt && Date.now() > p.expireAt) {\n      p.status = 'expired';\n      if (p.dbId) DB.update(T.WLP, p.dbId, JSON.parse(JSON.stringify(p)));\n      cancelWlCheckinNative(p.id);\n      wlTrustAdd(5, p.app + ' 通行证按时回收');\n    }\n  }\n  return (S.wlPasses || []).filter(x => x.status === 'active');\n}\nfunction wlTrust() { return Number(S.settings.wlTrust) || 0; }\nasync function wlTrustAdd(d, why) {\n  const before = wlTrust();\n  const after = Math.max(-100, Math.min(100, before + d));\n  S.settings.wlTrust = after;\n  const log = Array.isArray(S.settings.wlTrustLog) ? S.settings.wlTrustLog : [];\n  log.unshift({ d: d, why: String(why || '').slice(0, 120), at: Date.now(), total: after });\n  S.settings.wlTrustLog = log.slice(0, 20);\n  await saveSettings(true);\n  const cid = anyCharId();\n  if (cid && why) await syncTimeline(cid, '应用白名单信任分 ' + (d > 0 ? '+' : '') + d + '：' + why, 'wl_trust', {});\n}\nfunction wlParseVerdict(raw) {\n  const t = String(raw || '').replace(/```(json)?/g, '');\n  const m = t.match(/\\{[\\s\\S]*\\}/);\n  if (!m) return null;\n  try { return JSON.parse(m[0]); } catch (e) { return null; }\n}\nfunction openWlApply(prefill) {\n  S.draft.wlAppName = (prefill && prefill.app) || '';\n  S.draft.wlReason = (prefill && prefill.reason) || '';\n  S.draft.wlPackage = (prefill && prefill.pkg) || '';\n  S.draft.wlMinutes = Number(S.draft.wlMinutes) || 15;\n  const reasons = ['查单词', '查资料', '回个消息', '导航'];\n  openSheet(`<h3>🎟 向 TA 申请通行证</h3>\n    <div class=\"tiny mt6\">锁机期间要用某个应用，得先向 TA 申请；批了才生效，到期自动回收。</div>\n    <button class=\"btn block mt8\" data-act=\"appPickerOpen\" data-target=\"apply\">📱 从手机应用选择（APK）</button>\n    <label class=\"fl\">应用名称</label><input class=\"input\" data-in=\"wlAppName\" value=\"${esc(S.draft.wlAppName || '')}\" placeholder=\"比如：欧路词典\">\n    <label class=\"fl\">用途</label>\n    <div class=\"chips\">${reasons.map(r => `<button class=\"chip ${S.draft.wlReason === r ? 'on' : ''}\" data-act=\"wlReasonPick\" data-v=\"${r}\">${r}</button>`).join('')}</div>\n    <input class=\"input mt8\" data-in=\"wlReason\" value=\"${esc(S.draft.wlReason || '')}\" placeholder=\"或者自己写一句\">\n    <label class=\"fl\">申请时长</label>\n    <div class=\"chips\">${[10, 15, 20, 30].map(m => `<button class=\"chip ${Number(S.draft.wlMinutes) === m && !S.draft.wlMinutesCustom ? 'on' : ''}\" data-act=\"wlMinPick\" data-v=\"${m}\">${m} 分钟</button>`).join('')}</div>\n    <input class=\"input mt8\" type=\"number\" inputmode=\"numeric\" data-in=\"wlMinutesCustom\" data-num=\"1\" value=\"${S.draft.wlMinutesCustom || ''}\" placeholder=\"或自己填分钟数（1~30）\">\n    <label class=\"fl\">应用包名（可选 —— L2 看守锁按包名自动放行时用）</label>\n    <input class=\"input\" data-in=\"wlPackage\" value=\"${esc(S.draft.wlPackage || '')}\" placeholder=\"比如：com.eusoft.eudic\">\n    <div class=\"tiny mt10\">提交即接受随机查岗；被抓到在玩，通行证立刻作废、信任分下降，之后更难批。</div>\n    <button class=\"btn primary block mt10\" data-act=\"wlSubmit\" ${S.wlBusy ? 'disabled' : ''}>${S.wlBusy ? '等 TA 审批…' : '提交申请'}</button>\n    <button class=\"btn ghost block mt8\" data-act=\"closeSheet\">取消</button>`);\n}\nasync function submitWlApply() {\n  if (S.wlBusy) return;\n  const app = String(S.draft.wlAppName || '').trim();\n  if (!app) { toast('先写清楚要申请哪个应用'); return; }\n  const reason = String(S.draft.wlReason || '').trim();\n  const minutes = Math.max(1, Math.min(30, Number(S.draft.wlMinutesCustom) || Number(S.draft.wlMinutes) || 15));\n  const cid = anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  /* 包名：先看手填/带入；为空则按应用名去已安装列表反查；仍无则要求去列表选或按格式填 */\n  let pkg = String(S.draft.wlPackage || '').trim();\n  if (!pkg && API && API.device && API.device.appsList) {\n    try {\n      const res = await API.device.appsList();\n      const list = (res && res.apps) || [];\n      const key = app.toLowerCase();\n      const hit = list.find(x => String(x.label || '').toLowerCase() === key)\n        || list.find(x => String(x.label || '').toLowerCase().indexOf(key) >= 0)\n        || list.find(x => String(x.package || '').toLowerCase().indexOf(key) >= 0);\n      if (hit && hit.package) { pkg = hit.package; S.draft.wlPackage = pkg; }\n    } catch (e) { }\n  }\n  if (!pkg) { toast('没匹配到包名：请点「从手机应用选择」，或按 com.xxx.yyy 格式填'); return; }\n  if (!/^[a-zA-Z][a-zA-Z0-9_]*(\\.[a-zA-Z0-9_]+)+$/.test(pkg)) { toast('包名格式不对：应为 com.公司.应用'); return; }\n  S.draft.wlPackage = pkg;\n  S.wlBusy = true; render();\n  const vars = {\n    appName: app, reason: reason || '（没写）', minutes: minutes,\n    trust: wlTrust(), activeCount: activeWlPasses().length,\n    focusState: (S.session && S.session.status === 'running') ? '正在一段专注里' : '现在没有在专注'\n  };\n  let verdict = null;\n  for (let i = 0; i < 2 && !verdict; i++) {\n    try { verdict = wlParseVerdict(await pGen('wl.review', vars, [cid])); } catch (e) { }\n  }\n  if (!verdict || ['approve', 'counter', 'reject'].indexOf(verdict.decision) < 0) {\n    /* 没有可用 AI 时的离线裁决（按市面锁机规则）：短时且信任正常 → 批；中等 → 砍时；超长/低信任 → 拒 */\n    const t = wlTrust();\n    if (minutes <= 15 && t >= -10) verdict = { decision: 'approve', grantedMinutes: minutes, conditions: '只开这段时间，用完自己退回来', reply: '准了。你说几分钟就几分钟 —— 到点自己回来。' };\n    else if (minutes <= 30) verdict = { decision: 'counter', grantedMinutes: 10, conditions: '先给 10 分钟，不够再申请', reply: '先十分钟。够用就把事办完。' };\n    else verdict = { decision: 'reject', grantedMinutes: 0, conditions: '', reply: '要这么久，那就先把手头这件事做完再说。' };\n  }\n  const granted = Math.max(1, Math.min(30, Number(verdict.grantedMinutes) || (verdict.decision === 'approve' ? minutes : 0)));\n  const rec = {\n    id: 'wlp_' + Date.now().toString(36), app: app, reason: reason, minutes: granted,\n    conditions: String(verdict.conditions || ''), reply: String(verdict.reply || ''),\n    package: String(S.draft.wlPackage || '').trim(), decision: verdict.decision, status: verdict.decision === 'reject' ? 'rejected' : 'active',\n    issuedAt: Date.now(), expireAt: verdict.decision === 'reject' ? 0 : Date.now() + granted * 60000,\n    uses: 0, trustAtIssue: wlTrust(), at: Date.now()\n  };\n  const r = await DB.create(T.WLP, JSON.parse(JSON.stringify(rec)));\n  if (r) rec.dbId = r.id;\n  S.wlPasses = [rec].concat(S.wlPasses || []);\n  const tag = ({ approve: '已签发', counter: '有条件签发', reject: '没通过' })[verdict.decision];\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'system', historyRole: 'system',\n    title: '🎟 通行证批复 · ' + app, subtitle: tag,\n    body: String(verdict.reply || '').slice(0, 140) || (verdict.decision === 'reject' ? '这次不行。' : '准了，' + granted + ' 分钟。'),\n    summary: charName(cid) + ' 审批了用户的应用白名单申请：' + app + '（' + tag + '，' + granted + ' 分钟）',\n    historyText: '[白名单申请] 用户申请 ' + app + '（' + minutes + ' 分钟，用途：' + (reason || '未写') + '）—— ' + charName(cid) + '批复：' + tag + '，' + granted + ' 分钟。' + (verdict.reply || '')\n  }), null);\n  S.wlBusy = false;\n  closeAllSheets();\n  if (rec.status === 'active') { scheduleWlCheckin(rec); syncLockNow(); }\n  toast(({ approve: '🎟 已签发：' + app + ' · ' + granted + ' 分钟', counter: '⚖️ 有条件签发：' + granted + ' 分钟', reject: '❌ TA 没批这次申请' })[verdict.decision]);\n  render();\n}\nfunction openWlSheet() {\n  const act = activeWlPasses();\n  const hist = (S.wlPasses || []).filter(x => x.status !== 'active').slice(0, 6);\n  const oldWl = cfg('whitelist') || [];\n  const left = p => p.expireAt ? '剩 ' + fmtDur(Math.max(0, (p.expireAt - Date.now()) / 1000)) : '';\n  openSheet(`<h3>🎟 应用通行证</h3>\n    <div class=\"tiny mt6\">通行证由 TA 审批签发，到期自动回收；生效中的通行证是中途离开豁免的依据。</div>\n    ${(() => {\n      const log = (S.settings.wlTrustLog || []).slice(0, 6);\n      return `<div class=\"item\" style=\"align-items:flex-start\"><div class=\"ic\">💗</div><div class=\"grow\">\n        <div style=\"font-size:13px\">当前信任分：<b>${wlTrust()}</b> <span class=\"tiny\">（-100 ~ 100，正分更容易批）</span></div>\n        <div class=\"tiny mt6\">查岗通过 +2 · 查岗违规/超时 -10 · 通行证按时回收 +5</div>\n        ${log.length ? log.map(r => `<div class=\"tiny mt6\">${hm(r.at)} ${r.d > 0 ? '+' : ''}${r.d} → ${r.total} · ${esc(r.why || '')}</div>`).join('') : '<div class=\"tiny mt6\">还没有加减记录。</div>'}\n      </div></div>`;\n    })()}\n    ${act.length ? act.map(p => `<div class=\"item\"><div class=\"ic\">🎟</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(p.app)} · ${p.minutes} 分钟 ${left(p)}</div>\n      <div class=\"tiny\">${esc(p.reason || '')}${p.package ? ' · 包名 ' + esc(p.package) : ''}${p.conditions ? ' · 条件：' + esc(p.conditions) : ''} · 已用 ${p.uses || 0} 次${p.checkedAt ? ' · 已过查岗' : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"wlRevoke\" data-id=\"${esc(p.id)}\">作废</button></div>`).join('')\n      : '<div class=\"tiny mt6\">现在没有生效中的通行证。</div>'}\n    <button class=\"btn primary block mt10\" data-act=\"wlApplyOpen\" data-perm=\"\">🎟 选择应用并申请通行证（多选）</button>\n    ${oldWl.length ? `<div class=\"hr\"></div><div class=\"tiny\">旧白名单档案（未签发，不直接生效）：</div>\n      ${oldWl.map(x => `<div class=\"item\"><div class=\"grow\"><div style=\"font-size:13px\">${esc(x.name)}</div><div class=\"tiny\">${esc(x.note || '')}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"wlApplyOpen\" data-app=\"${esc(x.name)}\" data-reason=\"${esc(x.note || '')}\" data-pkg=\"${esc(x.pkg || '')}\">按此申请</button></div>`).join('')}` : ''}\n    ${hist.length ? `<div class=\"hr\"></div><div class=\"tiny\">历史批复：</div>\n      ${hist.map(p => `<div class=\"tiny mt6\">${esc(p.app)} · ${({ approve: '已签发', counter: '有条件', reject: '没批', expired: '已到期' })[p.status] || p.status} · ${dkey(new Date(p.issuedAt))}</div>`).join('')}` : ''}`);\n}\n/* ---------- 通行证期随机查岗（§7.6 M2 版：自证拍照） ----------\n   通行证签发时在生效窗口内随机挑一个时刻排查岗（宿主任务发系统通知，\n   页面活着时弹「截屏自证」层，10 分钟内截一张当前屏幕发进聊天室由 TA 亲眼判）；\n   超时没交 = 视为违规：通行证作废 + 信任分 -10 + TA 记一笔。\n   （截图判卷与自动踢回前台属于 L2/壳侧能力，随 APK 升级开放。） */\nfunction cancelWlCheckinNative(passId) {\n  if (!passId || !API || !API.device || typeof API.device.cancelPassCheckIn !== 'function') return;\n  sdk(() => API.device.cancelPassCheckIn(passId), null).catch(() => { });\n}\nasync function scheduleWlCheckin(pass) {\n  if (!pass || pass.status !== 'active' || !pass.expireAt) return;\n  const winStart = Date.now() + 60000;\n  const winEnd = Math.max(winStart + 60000, pass.expireAt - 2 * 60000);\n  const fireAt = winStart + Math.random() * Math.max(60000, winEnd - winStart);\n  const cid = pass.charIds && pass.charIds[0] ? pass.charIds[0] : (anyCharId() || '');\n  const nativeSchedule = !!(API && API.device && typeof API.device.schedulePassCheckIn === 'function');\n  const c = { passId: pass.id, passApp: pass.app, at: fireAt, deadlineAt: fireAt + 10 * 60000, done: '', charId: cid, native: nativeSchedule };\n  S.settings.wlCheckin = c;\n  await saveSettings(true);\n  if (nativeSchedule) {\n    const r = await sdk(() => API.device.schedulePassCheckIn({\n      passId: pass.id,\n      app: pass.app,\n      characterId: cid,\n      name: charName(cid),\n      avatar: (charById(cid) || {}).avatar || '',\n      dueAt: fireAt\n    }), null);\n    if (r && r.ok) return;\n    c.native = false;\n    await saveSettings(true);\n  }\n  const instruction = '[白名单通行证查岗] 应用：' + pass.app + '。接下来你会收到用户当前屏幕的截图。'\n    + '请判断他是在学习/查资料还是在娱乐；看完后必须调用「判定通行证查岗」工具，app 填「' + pass.app + '」：'\n    + '合规传 verdict=pass；画面违规、用户拒绝给看或超时没交传 verdict=violation。不要只口头说。';\n  const actions = [\n    { type: 'chat.history', characterId: cid, role: 'system', content: instruction }\n  ];\n  if (API && API.device && typeof API.device.checkinRequest === 'function') {\n    actions.push({\n      type: 'device.checkin.request',\n      characterId: cid,\n      name: charName(cid),\n      avatar: (charById(cid) || {}).avatar || ''\n    });\n  } else {\n    actions.push({\n      type: 'shell.notify',\n      title: '📸 ' + charName(cid) + ' 查岗',\n      body: '通行证（' + pass.app + '）抽查：10 分钟内截一张当前屏幕作为自证。'\n    });\n  }\n  if (!API || !API.tasks) return;\n  sdk(() => API.tasks.schedule({\n    id: 'focus_wlchk_' + pass.id, delayMs: Math.max(60000, fireAt - Date.now()),\n    actions: actions\n  }), null);\n}\nfunction openWlCheckinSheet() {\n  const c = S.settings.wlCheckin;\n  const cid = c.charId || anyCharId();\n  openSheet(`<h3>📸 TA 查岗 · ${esc(c.passApp)}</h3>\n    <div class=\"sub\">${esc(charName(cid))} 正在抽查这张通行证 —— 截一张当前屏幕发进聊天室，他亲眼看过才算数。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"wlCheckinPhoto\">📸 截屏自证</button>\n      <button class=\"btn ghost grow\" data-act=\"closeSheet\">先收下</button></div>\n    <div class=\"tiny mt8\">时限 10 分钟（到 ${hm(c.deadlineAt)}）；超时没交按「被抓」处理：通行证作废、信任分下降。</div>`);\n}\nasync function wlCheckinPhoto() {\n  const c = S.settings.wlCheckin;\n  if (!c || c.done) return;\n  const cid = c.charId || anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  if (!API || !API.device || typeof API.device.screenshot !== 'function') {\n    toast('当前壳版本不支持直接截屏，请更新安卓 APK');\n    return;\n  }\n  toast('正在截取当前屏幕…');\n  let dataUrl = '';\n  try {\n    const shot = await sdk(() => API.device.screenshot(), null);\n    if (shot && shot.ok) dataUrl = String(shot.dataUrl || '');\n    else toast('截屏失败：' + ((shot && shot.reason) || '请确认无障碍截屏权限已开启'));\n  } catch (e) { toast('截屏失败，请确认无障碍权限'); }\n  if (!dataUrl) return;\n  c.done = 'photo'; await saveSettings(true);\n  const instruction = '[白名单通行证查岗] 应用：' + c.passApp + '。接下来你会收到用户当前屏幕的截图。'\n    + '请判断他是在学习/查资料还是在娱乐；看完后必须调用「判定通行证查岗」工具，app 填「' + c.passApp + '」：'\n    + '合规传 verdict=pass；画面违规传 verdict=violation。不要只口头说。';\n  await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: instruction }), null);\n  const ok1 = await sendImageCard(cid, dataUrl, '📸 查岗自证 · ' + c.passApp);\n  await sdk(() => API.chat.requestReply({ characterId: cid }), null);\n  const pass = (S.wlPasses || []).find(x => x.id === c.passId);\n  if (pass) { pass.checkedAt = Date.now(); if (pass.dbId) await DB.update(T.WLP, pass.dbId, JSON.parse(JSON.stringify(pass))); }\n  closeAllSheets();\n  toast(ok1 === false ? '照片发进聊天室失败，但查岗已交' : '📸 已发进聊天室，等 TA 判定');\n  render();\n}\nasync function wlCheckinExpire() {\n  const c = S.settings && S.settings.wlCheckin;\n  if (!c || c.done) return;\n  const pass = (S.wlPasses || []).find(x => x.id === c.passId);\n  if (pass && pass.verdict) {\n    c.done = 'verdict'; await saveSettings(true);\n    return;\n  }\n  cancelWlCheckinNative(c.passId);\n  const cid = c.charId || anyCharId();\n  c.done = 'missed'; await saveSettings(true);\n  if (pass) {\n    pass.status = 'revoked'; pass.violatedAt = Date.now();\n    if (pass.dbId) await DB.update(T.WLP, pass.dbId, JSON.parse(JSON.stringify(pass)));\n    cancelWlCheckinNative(pass.id);\n  }\n  await wlTrustAdd(-10, '查岗超时没交自证（' + c.passApp + '）');\n  if (cid) {\n    const line = '查岗的时间到了，你什么都没交。' + (c.passApp ? '「' + c.passApp + '」的通行证我现在就收回来。' : '');\n    await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n    await syncTimeline(cid, '通行证（' + c.passApp + '）期间 TA 查岗，用户超时未交自证照片 —— 通行证作废，信任分下降。', 'wl_checkin_missed', {});\n  }\n  notify('🎟 通行证被收回', '查岗超时没交自证' + (c.passApp ? '：' + c.passApp : ''));\n  toast('⏰ 查岗超时：通行证被收回，信任分下降');\n  render();\n}\n/* ---------- 惩罚自动执行：钱包扣款 / 送礼，不用用户点确认 ---------- */\nasync function walletAccount() {\n  try { const w = await API.wallet.get(); return ((w && w.accounts) || [])[0] || null; }\n  catch (e) { return null; }\n}\nasync function autoRunPunish(rec, isAuto) {\n  if (!rec) return rec;\n  if (rec.running) return rec;\n  rec.running = true;\n  stopLockTick();\n  const cid = rec.charId || anyCharId();\n  const acc = await walletAccount();\n  const tag = isAuto ? '超时自动扣款' : '主动确认扣款';\n  if (rec.kind === 'pay') {\n    let paid = false, err = '';\n    if (acc) {\n      try {\n        const r = await API.wallet.pay({ amount: rec.amount, accountId: acc.id, title: '角色陪伴专注 · 惩罚', detail: rec.title, category: '惩罚', relatedOrderId: 'focus_' + rec.id });\n        paid = !!(r && r.ok); err = (r && r.error) || '';\n      } catch (e) { err = (e && e.message) || '扣款失败'; }\n    } else err = '没读到钱包账户';\n    if (paid) {\n      await addLedger('pay', rec.amount, cid, `惩罚转账（${tag}）· ${rec.title}`, true);\n      await completePunish(rec, `已从「${acc.name || '账户'}」扣款 ¥${Number(rec.amount).toLocaleString()}（${tag}）`);\n    } else {\n      await addLedger('pay', rec.amount, cid, `惩罚转账（扣款未成功，仅记账）· ${rec.title}`, false);\n      toast('扣款没成功（' + err + '），已记账并解除锁定');\n      await completePunish(rec, '扣款未成功，已记账：' + err);\n    }\n    rec.running = false;\n    return rec;\n  }\n  let paid = false, err = '';\n  if (acc) {\n    try {\n      const r = await API.wallet.pay({ amount: rec.price, accountId: acc.id, title: '角色陪伴专注 · 惩罚礼物', detail: rec.gift, category: '惩罚' });\n      paid = !!(r && r.ok); err = (r && r.error) || '';\n    } catch (e) { err = (e && e.message) || '扣款失败'; }\n  } else err = '没读到钱包账户';\n  await giftTo(cid, rec.gift, rec.price, { real: paid });\n  await completePunish(rec, `已赠送「${rec.gift}」（${tag}）` + (paid ? '（已从钱包扣款）' : '（扣款未成功，仅记账：' + err + '）'));\n  rec.running = false;\n  return rec;\n}\n/* ---------- 惩罚补救：做完一件事 / 再约一段专注，抵掉这次扣款 ---------- */\nconst PUNISH_REMEDY_TASKS = ['把这周的错题全部重做一遍', '整理一份本节知识点的思维导图', '背 50 个单词并默写一遍', '把上一次的错题写成 3 条要点笔记', '做完一章配套练习'];\nasync function remedyTaskAsk(rec) {\n  const w = openSheet(`<h3>✅ 用完成一件事来补救</h3>\n    <div class=\"tiny\">惩罚是「${esc(rec.title)}」${rec.kind === 'pay' ? '（¥' + Number(rec.amount || 0).toLocaleString() + '）' : '（' + esc(rec.gift || '') + '）'}。<br>\n    选一件真的要做完的事，做完回来点「我做完了」，这次扣款就免掉 —— 但事必须做完，不然还是照罚。</div>\n    <div class=\"chips mt10\">${PUNISH_REMEDY_TASKS.map(t => `<button class=\"chip\" data-rt=\"${esc(t)}\">${esc(t)}</button>`).join('')}</div>\n    <label class=\"fl\">或者自己写一件</label>\n    <input class=\"input\" id=\"remedyTask\" placeholder=\"例如：把资料分析错题按题型整理成 3 组\">\n    <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">算了</button>\n      <button class=\"btn primary grow\" data-act=\"remedyTaskSave\" data-id=\"${esc(rec.id)}\">就这件，开始做</button></div>`);\n  w.addEventListener('click', e => {\n    const b = e.target.closest('[data-rt]'); if (!b) return;\n    const i = document.getElementById('remedyTask'); if (i) i.value = b.dataset.rt;\n    w.querySelectorAll('[data-rt]').forEach(x => x.classList.toggle('on', x === b));\n  });\n}\nasync function remedyApptDo(rec) {\n  const cid = rec.charId || anyCharId();\n  const nm = cid ? charName(cid) : 'TA';\n  const ok = await confirmBox('🗓 用再约一段专注来补救',\n    '会立刻跟 ' + nm + ' 约一段专注（10 分钟后开始，25 分钟），并写进你们的聊天室。\\n'\n    + '约好之后这次扣款就免掉；但如果新的这一段你又不来，两笔一起算。', '约上，抵掉这次');\n  if (!ok) return;\n  const startAt = Date.now() + 10 * 60000;\n  const d = new Date(startAt);\n  const appt = {\n    id: '', date: dkey(d), time: pad2(d.getHours()) + ':' + pad2(d.getMinutes()), startAt: startAt,\n    minutes: 25, task: '补救：' + (rec.title || '上次失约').slice(0, 20), charIds: cid ? [cid] : [],\n    status: 'pending', nudgeCount: 0, createdAt: Date.now(), note: '失约补救'\n  };\n  await createAppt(appt);\n  await scheduleAppt(appt);\n  if (cid) {\n    await syncTimeline(cid, `用户用「再约一段专注」来补救上次的惩罚（${rec.title}）：新的专注排在 ${appt.date} ${appt.time}，25 分钟，内容是「${appt.task}」。`, 'remedy_appt', {});\n    await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'user', content: '[补救] 我跟你重新约一段：' + appt.date + ' ' + appt.time + '，专注 25 分钟「' + appt.task + '」。这次我一定到。' }), null);\n  }\n  rec.remedy = { type: 'appt', apptId: appt.id, at: Date.now() };\n  await savePun(rec);\n  toast('已约上：' + appt.date + ' ' + appt.time + ' · 这次免罚');\n  await completePunish(rec, '以「再约一段专注」补救（已排入预约 ' + appt.time + '）');\n}\nasync function genPunishLine(rec) {\n  const cid = rec.charId || anyCharId();\n  rec.line = '';\n  if (cid) {\n    let text = '';\n    try {\n      text = await pGen('punish.line', { reason: reasonText(rec.reason), title: rec.title }, [cid]);\n    } catch (e) { text = ''; }\n    if (!text) {\n      const texts = cfg('punishTexts') || [];\n      text = texts.length ? texts[Math.floor(Math.random() * texts.length)] : '规矩是你自己定的。';\n    }\n    rec.line = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  }\n  await savePun(rec); render();\n  /* 宣布惩罚时的这句语音，连音频引用一起存进惩罚记录 ——\n     惩罚页的「再听一遍」就能直接播这份，不再重新合成（省一次 API、省几秒等待）。\n     不阻塞主流程：合成是后台跑的，存好了自己回填。 */\n  if (rec.line && shouldSpeak('punish')) {\n    voiceSay(cid, rec.line, 'punish', '惩罚台词').then(async vr => {\n      if (vr && vr.ref) { rec.lineRef = vr.ref; await savePun(rec); }\n    }).catch(() => { });\n  }\n  if (rec.line) await syncChatLine(cid, `[角色陪伴专注] ${rec.line}（触发惩罚：${rec.title}）`, 'assistant');\n}\nasync function completePunish(rec, note) {\n  rec.status = 'done'; rec.doneAt = Date.now(); rec.note = note || '';\n  await savePun(rec);\n  const i = S.puns.findIndex(p => p.id === rec.id); if (i >= 0) S.puns[i] = rec;\n  stopLockTick();\n  S.lock = null; S.quiz = null; S.draft.punTxt = '';\n  const s = S.session, cid = rec.charId || anyCharId();\n  if (!rec.byPass) await addBond(cid, 2, '老老实实做完了一项惩罚');\n  await addPublic('punish', `【惩罚完成】${rec.title}${note ? ' · ' + note : ''}`, cid, {});\n  await syncTimeline(cid, `${charName(cid)}监督下的惩罚已完成：${rec.title}`, 'punish_done', {});\n  await syncChatLine(cid, `[角色陪伴专注] ${rec.title} 已完成。`);\n  if (s) { pushMsg(s, 'sys', '✅ 惩罚已完成，限制解除'); await saveSession(true); }\n  stopVoice(); toast('惩罚完成，已解锁'); render();\n}\n/* ==========================================================\n   壁纸与壁纸库（v1.9.2 校验标记 B）\n   ========================================================== */\nfunction renderWall() {\n  const old = document.getElementById('wallLayer');\n  const s = S.session, st = S.sleep;\n  let url = '';\n  /* 你自己上传的壁纸优先级最高：开了就铺全局（除非当时有一段睡眠/专注壁纸正在用，\n     那个是这一场专属的，仍以它为先；其余页面全部走你的自定义壁纸）。 */\n  const custom = customWallUrl();\n  if (st && st.running && st.wp && cfg('sleepWallBg') !== false) url = st.wp;   // 睡眠正计时中：壁纸自动铺满整页\n  else if (s && s.wallpaperData && ['running', 'review', 'reward'].indexOf(S.view) >= 0) url = s.wallpaperData;\n  else if (custom) url = custom;\n  if (!url) { if (old) old.remove(); return; }\n  let el = old;\n  if (!el) { el = document.createElement('div'); el.className = 'wall'; el.id = 'wallLayer'; document.body.insertBefore(el, document.body.firstChild); }\n  el.classList.toggle('sleep', !!(st && st.running && st.wp));\n  el.style.backgroundImage = 'url(' + url + ')';\n}\nasync function saveAlbum(kind, dataUrl, meta) {\n  meta = meta || {};\n  if (!dataUrl) return null;\n  let ref = '';\n  const st = await sdk(() => API.media.put({ dataUrl: dataUrl }), null);\n  if (st && st.ref) ref = st.ref;\n  const rec = {\n    kind: kind, ref: ref, at: Date.now(), date: dkey(), charId: meta.charId || '',\n    title: meta.title || (kind === 'sleep' ? '睡眠壁纸' : kind === 'reward' ? '奖励留念' : kind === 'streak' ? '连续作息奖励' : '专注壁纸'),\n    note: meta.note || '', locked: meta.locked !== false, unlockType: '', unlockTask: '', unlockAt: 0\n  };\n  const r = await DB.create(T.ALBUM, rec);\n  const item = Object.assign({ id: r ? r.id : uid(), dataUrl: ref ? '' : dataUrl }, rec);\n  S.album.unshift(item);\n  return item;\n}\nasync function albumImage(item) {\n  if (!item) return '';\n  if (item.dataUrl) return item.dataUrl;\n  if (!item.ref) return '';\n  const r = await sdk(() => API.media.get({ ref: item.ref }), null);\n  if (r && r.dataUrl) { item.dataUrl = r.dataUrl; return r.dataUrl; }\n  return '';\n}\nasync function fillAlbumImages() {\n  for (const it of (S.album || []).slice(0, 30)) {\n    const el = document.getElementById('alb_' + it.id);\n    if (!el || el.dataset.done === '1') continue;\n    const url = await albumImage(it);\n    if (!url) continue;\n    el.style.backgroundImage = 'url(' + url + ')';\n    el.dataset.done = '1';\n  }\n  const big = document.getElementById('albBig');\n  if (big && big.dataset.ref && big.dataset.done !== '1') {\n    const it = S.album.find(x => String(x.id) === String(big.dataset.ref));\n    const url = it ? await albumImage(it) : '';\n    if (url) { big.src = url; big.dataset.done = '1'; }\n  }\n}\nasync function unlockAlbumItem(item, note) {\n  item.locked = false; item.unlockAt = Date.now(); if (note) item.unlockNote = note;\n  if (item.id) await DB.update(T.ALBUM, item.id, JSON.parse(JSON.stringify(Object.assign({}, item, { dataUrl: '' }))));\n  const cid = item.charId || anyCharId();\n  await syncTimeline(cid, `用户解锁了一张壁纸：${item.title}（${item.unlockType === 'task' ? '完成任务' : '答题'}解锁）。`, 'wall_unlock', {});\n  toast('已解锁：' + item.title);\n}\nasync function genWallpaper(s) {\n  if (!s || s.wallpaperData || s.wallpaperLoading) return;\n  if (!canGenWall()) { s.wallpaperError = ''; return; }\n  if (!API || !API.ai || !API.ai.generateImage) { s.wallpaperError = '生图不可用，请先在小手机设置里配置生图 API'; return; }\n  const cid = pickOneChar(s.charIds), c = charById(cid);\n  const n = (s.plan || []).length || 1;\n  s.wallpaperLoading = true; render();\n  try {\n    const r = await genImgLogged('img.focus', '专注壁纸', promptText('img.focus', { charName: (c && c.name) ? c.name : '一位温柔的角色', taskCount: n }), cid, () => API.ai.generateImage({\n      prompt: promptText('img.focus', { charName: (c && c.name) ? c.name : '一位温柔的角色', taskCount: n }),\n      characterId: cid || undefined, useReferenceImage: true, timeoutMs: 120000\n    }));\n    if (r && r.dataUrl) {\n      s.wallpaperData = r.dataUrl; s.wallpaperError = ''; s.wallpaperAt = Date.now();\n      const item = await saveAlbum('focus', r.dataUrl, {\n        title: '专注壁纸 ' + dkey(), locked: true, charId: cid,\n        note: `专注 ${Math.round((s.totalFocusSec || 0) / 60)} 分钟 · 任务 ${(s.plan || []).filter(t => t.done).length}/${(s.plan || []).length}`\n      });\n      if (item) s.albumId = item.id;\n      await saveSession(true);\n    } else s.wallpaperError = '生图接口没有返回图片';\n  } catch (e) { s.wallpaperError = (e && e.message) || '生图失败'; }\n  s.wallpaperLoading = false;\n  if (S.session === s) render();\n}\n/* ---------- 专注壁纸的节奏（一张一张来） ----------\n   ① 开始专注 → 先攒下第 1 张（锁着，做背景用）\n   ② 完成一个任务 → 解锁一张（休息时段就能下载它）\n   ③ 同时开始生成下一张新的（同样先锁着）\n   → 所以「做完几项任务 = 能下载几张」，永远只领先任务一步。\n   s.walls: 本轮已生成的壁纸 [{albumId, task, at, unlocked}]\n   s.wallUnlocked: 已完成的任务数 = 可下载的张数\n   ------------------------------------------------------------------ */\n/* 统一生图闸门：三条生图链路（专注/睡眠/奖励）全走这里。\n   停止条件 = 关掉「AI 壁纸生成」总开关，或正在用自定义壁纸且没选「两者都要」。 */\nfunction canGenWall() {\n  if (cfg('wallGenOff')) return false;\n  if (cfg('customWallUse') && !cfg('wallGenWithCustom')) return false;\n  return true;\n}\n/* 壁纸模式（设置页四选一）：none=全关 / ai=只用AI / custom=只用我的 / both=两者都要 */\nfunction wallMode() {\n  if (cfg('wallGenOff')) return 'none';\n  if (cfg('customWallUse')) return cfg('wallGenWithCustom') ? 'both' : 'custom';\n  return 'ai';\n}\nasync function ensureWall(s, n, taskText) {\n  if (!s) return;\n  /* 总开关：开了之后专注壁纸彻底不再生成（省额度、也不再被重复的图刷屏） */\n  if (!canGenWall()) { s.wallpaperError = ''; return; }\n  if (!API || !API.ai || !API.ai.generateImage) { s.wallpaperError = '生图不可用，请先配置生图 API'; return; }\n  s.walls = s.walls || [];\n  s.wallTarget = Math.max(Number(s.wallTarget) || 0, Math.max(1, Number(n) || 1));\n  if (taskText) s.wallTask = String(taskText).slice(0, 24);\n  if (s.wallBusy) return;                      // 已在逐张生成，让它按最新目标继续\n  s.wallBusy = true;\n  if (S.session === s) { s.wallpaperLoading = true; render(); }\n  try {\n    while (s.walls.length < (s.wallTarget || 1)) {\n      const idx = s.walls.length + 1;\n      const cid = pickOneChar(s.charIds), c = charById(cid);\n      const doneN = (s.plan || []).filter(x => x.done).length;\n      const tName = idx === 1 ? (s.wallTask || '这段专注的开始') : (s.wallTask || '完成了第 ' + (idx - 1) + ' 项任务');\n      let ok = false;\n      try {\n        const styleK = wallStylePick();\n        const pid = wallPromptId(styleK);\n        const selfT = ((s.selfTasks || [])[0] || {}).text || '';\n        const pvars = {\n          charName: (c && c.name) ? c.name : '一位温柔的角色', taskCount: doneN, taskName: tName,\n          selfTask: selfT || '陪你一起把这段时间走完', selfTaskLine: selfT ? '他这段时间在做的事：' + selfT + '；' : '',\n          when: whenText(), theme: s.wallTask || tName || '安静地学一会儿'\n        };\n        const prompt = promptText(pid, pvars) + wallVaryLine();\n        const r = await genImgLogged(pid, (idx === 1 ? '开始专注壁纸' : '任务完成壁纸') + '（' + wallStyleName(styleK) + '）', prompt, cid, () => API.ai.generateImage({\n          prompt: prompt, characterId: cid || undefined, useReferenceImage: true, timeoutMs: 120000\n        }), true);   // true = 后台连排生成，不锁住你操作\n        if (r && r.dataUrl) {\n          s.wallpaperData = r.dataUrl; s.wallpaperAt = Date.now(); s.wallpaperError = ''; s.idxWall = idx;\n          const unlocked = idx <= (Number(s.wallUnlocked) || 0);\n          const item = await saveAlbum('focus', r.dataUrl, {\n            title: idx === 1 ? '开始专注 · ' + dkey() : '完成「' + tName + '」',\n            locked: !unlocked, charId: cid,\n            note: (idx === 1 ? '开始这段专注时生成' : '完成第 ' + (idx - 1) + ' 项任务后生成') + (unlocked ? ' · 已解锁' : ' · 完成一个任务后解锁')\n          });\n          s.walls.push({ albumId: item ? item.id : '', task: tName, at: Date.now(), unlocked: unlocked, style: styleK });\n          ok = true;\n        } else s.wallpaperError = '生图接口没有返回图片';\n      } catch (e) { s.wallpaperError = (e && e.message) || '生图失败'; }\n      await saveSession(true);\n      if (!ok) break;                          // 生不出来就停下，不空转\n    }\n  } finally {\n    s.wallBusy = false;\n    s.wallpaperLoading = false;\n    if (S.session === s) render();\n  }\n}\n/* 完成任务：解锁已经生成好的那张（能下载了），再去生成下一张新的 */\nasync function unlockWalls(s, n) {\n  s.walls = s.walls || [];\n  const upTo = Math.min(Math.max(0, Number(n) || 0), s.walls.length);\n  let changed = false;\n  for (let i = 0; i < upTo; i++) {\n    const w = s.walls[i];\n    if (!w || w.unlocked) continue;\n    w.unlocked = true; changed = true;\n    const item = (S.album || []).find(x => String(x.id) === String(w.albumId));\n    if (item) {\n      item.locked = false; item.unlockNote = '完成第 ' + (i + 1) + ' 项任务后解锁';\n      if (item.id) await DB.update(T.ALBUM, item.id, JSON.parse(JSON.stringify(Object.assign({}, item, { dataUrl: '' }))));\n    }\n    if (w.albumId) {\n      const idx = (S.album || []).findIndex(x => String(x.id) === String(w.albumId));\n      if (idx < 0) { /* 库里没有就跳过，不影响本轮下载 */ }\n    }\n  }\n  if (changed && S.session === s) toast('解锁 1 张壁纸 · 休息时就能下载了');\n  return upTo;\n}\n/* 一次任务完成的统一入口 */\nasync function onTaskDone(s, taskText) {\n  if (!s || s.status !== 'running') return;\n  /* TA 的任务进度跟着你走 —— 这一步必须放在这个「任务完成的统一入口」里。\n     以前只在「勾选任务」时同步过，而最常用的两条路都没同步：\n       · 「标记完成，下一项」按钮\n       · 预估时间到点后的「按时完成了」\n     于是他的进度条一直停在 0，看起来就是「进度没跟着任务同步」。 */\n  syncSelfTasksFromPlan(s);\n  const doneN = (s.plan || []).filter(t => t.done).length + (s.extraTasks || []).filter(t => t.done).length;\n  s.wallUnlocked = Math.max(Number(s.wallUnlocked) || 0, doneN);\n  await unlockWalls(s, s.wallUnlocked);\n  await saveSession(true);\n  if (S.session === s) render();\n  ensureWall(s, s.wallUnlocked + 1, taskText);     // 再攒一张新的，留给下一项任务解锁\n}\n/* ---------- 壁纸样式：三套提示词，可固定也可轮换 ---------- */\nconst WALL_STYLES = [\n  ['gaze', '温柔注视', '角色在书桌对面安静看着你（默认）'],\n  ['task', 'TA 自己的任务', '围着 TA 这个时段要陪你做的那件事画'],\n  ['scene', '此刻场景', '按时间与情境自由发挥（深夜书桌 / 午后窗边…）'],\n  ['rotate', '三种轮换', '每张换一种，不重样']\n];\nfunction wallStyleName(k) { const h = WALL_STYLES.filter(x => x[0] === k)[0]; return h ? h[1] : '温柔注视'; }\nfunction wallStylePick() {\n  const v = cfg('wallStyle') || 'gaze';\n  if (v === 'rotate') {\n    const arr = ['gaze', 'task', 'scene'];\n    S.wallRot = (Number(S.wallRot) || 0) + 1;\n    return arr[S.wallRot % 3];\n  }\n  return (v === 'task' || v === 'scene') ? v : 'gaze';\n}\nfunction wallPromptId(st) { return st === 'task' ? 'img.focus.task' : st === 'scene' ? 'img.focus.scene' : 'img.focus'; }\nfunction whenText() {\n  const h = new Date().getHours();\n  return h < 5 ? '深夜' : h < 9 ? '清晨' : h < 12 ? '上午' : h < 14 ? '中午' : h < 18 ? '下午' : h < 22 ? '晚上' : '深夜';\n}\n/* ---------- 降低壁纸重复感 ----------\n   为什么需要它：提示词是一套固定模板，模型每次都会往最「标准」的那张画 ——\n   于是同一个样式出来的图构图、光线、角度都差不多，看着就是重复。\n   这里每次随机追加一句变化提示（机位、时间、构图、氛围各抽一条），\n   让同一套模板也能出不一样画面。关掉「画面变化」就直接不加。 */\nconst WALL_VARY = {\n  shot: ['近景特写，只拍到书桌一角与他的手', '中景，人物侧过身子，只露半张脸', '稍远的全景，人物在画面偏左', '俯视角度，从斜上方看下来', '背影视角，镜头在他身后', '越过肩膀的视角，前景带一点桌面杂物'],\n  light: ['只有台灯一圈暖光，其余压在暗处', '窗外透进一点冷色天光，和暖灯撞在一起', '画面整体低饱和，只有一小块亮色', '光从侧后打过来，勾出一圈轮廓光', '清晨的散射光，影子很淡', '夜里只剩屏幕的微光映在脸上'],\n  comp: ['留白很多，主体偏在画面下方', '画面有一层薄雾或玻璃反光', '前景用植物或杯子虚化挡一点', '桌上有摊开的书和一支笔做对照', '画面里有热气／雨痕／飘落的东西'],\n  mood: ['安静克制，几乎没有情绪起伏', '带一点疲惫但放松的感觉', '有一点被打扰后的仓促感', '温柔里藏着说不出的心事', '像某个普通的深夜，什么都没发生']\n};\nfunction wallVaryLine() {\n  if (cfg('wallVary') === false) return '';\n  const pick = a => a[Math.floor(Math.random() * a.length)];\n  return '\\n【本次画面要求（请严格按这个来画，不要画成标准构图）】机位：' + pick(WALL_VARY.shot)\n    + '；光线：' + pick(WALL_VARY.light) + '；构图：' + pick(WALL_VARY.comp) + '；氛围：' + pick(WALL_VARY.mood) + '。';\n}\n/* 当前生效的自定义壁纸（内存里有就用内存的，否则用媒体库引用取回来的） */\nfunction customWallUrl() {\n  if (!cfg('customWallUse')) return '';\n  if (S.customWallData) return S.customWallData;\n  return '';\n}\n/* 把上传的图存下来：内存 + 媒体库引用，两处都落好，换设备靠引用还能取回 */\nasync function setCustomWall(dataUrl) {\n  if (!dataUrl) return false;\n  S.customWallData = dataUrl;\n  const put = await sdk(() => API.media.put({ dataUrl: dataUrl }), null);\n  S.settings.customWallRef = (put && put.ref) ? put.ref : '';\n  S.settings.customWall = '';        // 不把巨大的 base64 塞进设置里（会撑爆本地存储）\n  S.settings.customWallUse = true;\n  if (!cfg('wallGenWithCustom') && !cfg('wallGenOff')) toast('已启用自定义壁纸：AI 壁纸生成自动暂停，想两者都要可到「我的 → 壁纸」切模式');\n  await saveSettings(true);\n  renderWall(); render();\n  return true;\n}\n/* 启动时把自定义壁纸取回来 */\nasync function loadCustomWall() {\n  if (!cfg('customWallUse') || !cfg('customWallRef')) return;\n  const r = await sdk(() => API.media.get({ ref: cfg('customWallRef') }), null);\n  if (r && r.dataUrl) S.customWallData = r.dataUrl;\n}\nfunction wallStyleLabel() { const v = cfg('wallStyle') || 'gaze'; const h = WALL_STYLES.filter(x => x[0] === v)[0]; return h ? h[1] : '温柔注视'; }\n/* ---------- 睡眠壁纸样式：四套提示词，可固定也可每次换 ---------- */\nconst SLEEP_WALL_STYLES = [\n  ['calm', '安静侧睡', 'img.sleep'],\n  ['moon', '月光窗边', 'img.sleep.moon'],\n  ['lamp', '台灯下的困意', 'img.sleep.lamp'],\n  ['cozy', '被窝里的陪伴', 'img.sleep.cozy'],\n  ['rotate', '每次换一种', '']\n];\nfunction sleepWallStyle() { return cfg('sleepWallStyle') || 'calm'; }\nfunction sleepWallPromptIdOf(k) { const h = SLEEP_WALL_STYLES.filter(x => x[0] === k)[0]; return (h && h[2]) || 'img.sleep'; }\nfunction sleepWallStyleName(k) { const h = SLEEP_WALL_STYLES.filter(x => x[0] === k)[0]; return h ? h[1] : '安静侧睡'; }\nfunction sleepWallPromptId() {\n  const v = sleepWallStyle();\n  if (v === 'rotate') {\n    const arr = SLEEP_WALL_STYLES.filter(x => x[0] !== 'rotate').map(x => x[0]);\n    S.sleepWallRot = (Number(S.sleepWallRot) || 0) + 1;\n    return sleepWallPromptIdOf(arr[S.sleepWallRot % arr.length]);\n  }\n  return sleepWallPromptIdOf(v);\n}\nfunction sleepWallPromptIdForEdit() { const v = sleepWallStyle(); return sleepWallPromptIdOf(v === 'rotate' ? 'calm' : v); }\n/* 当前能下载的那张（最后一张已解锁的） */\nasync function unlockableWall(s) {\n  if (!s) return '';\n  const list = (s.walls || []).filter(w => w && w.unlocked);\n  if (list.length) {\n    const item = (S.album || []).find(x => String(x.id) === String(list[list.length - 1].albumId));\n    if (item) { const url = await albumImage(item); if (url) return url; }\n  }\n  return (Number(s.wallUnlocked) || 0) >= 1 ? (s.wallpaperData || '') : '';\n}\nasync function restoreWallpaper(s) {\n  if (!s || !s.wallpaperRef || s.wallpaperData) return;\n  const r = await sdk(() => API.media.get({ ref: s.wallpaperRef }), null);\n  if (r && r.dataUrl) { s.wallpaperData = r.dataUrl; render(); }\n}\n/* 能不能下载：完成过至少一个任务（= 至少解锁了一张），或本轮已通过校验 */\nfunction canSaveWallpaper() {\n  const s = S.session;\n  if (!s) return false;\n  return (Number(s.wallUnlocked) || 0) >= 1 || s.status === 'passed' || (s.passedRounds || 0) > 0;\n}\n/* ---------- 保存图片：多路兜底（iframe 里长按常被屏蔽） ---------- */\nfunction dataUrlToBlob(dataUrl) {\n  try {\n    const parts = String(dataUrl).split(',');\n    const mime = (parts[0].match(/:(.*?);/) || [])[1] || 'image/png';\n    const bin = atob(parts[1]);\n    const arr = new Uint8Array(bin.length);\n    for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);\n    return new Blob([arr], { type: mime });\n  } catch (e) { return null; }\n}\nfunction openSavePanel(dataUrl, title, filename, charId) {\n  const w = openSheet(`<h3>${esc(title || '保存图片')}</h3>\n    <div class=\"tiny\">应用内长按图片可能被浏览器屏蔽，下面任选一条：</div>\n    <img src=\"${dataUrl}\" style=\"width:100%;border-radius:14px;margin-top:10px;display:block\" alt=\"\">\n    <button class=\"btn primary block mt12\" data-sp=\"chat\" data-cid=\"${esc(charId || anyCharId())}\">📨 发到聊天室（最稳）</button>\n    <button class=\"btn block mt8\" data-sp=\"mediasave\">💾 存进小手机媒体库（APK 最稳）</button>\n    <button class=\"btn block mt8\" data-sp=\"download\">⬇️ 再试一次下载</button>\n    <button class=\"btn block mt8\" data-sp=\"copy\">📋 复制图片到剪贴板</button>\n    <button class=\"btn block mt8\" data-sp=\"window\">🪟 浏览器新窗口打开</button>\n    <button class=\"btn block ghost mt8\" data-sp=\"close\">关闭</button>\n    <div class=\"tiny mt10\">都不行的话，手机截图也能留下这张图。</div>`);\n  S.draft.saveImg = dataUrl;\n  S.draft.saveName = filename || ('image_' + dkey() + '.png');\n  S.draft.saveTitle = title || '';\n  w.addEventListener('click', async ev => {\n    const b = ev.target.closest('[data-sp]'); if (!b) return;\n    const act = b.dataset.sp;\n    if (act === 'close') { closeSheet(w); return; }\n    if (act === 'mediasave') {\n      try {\n        if (API && API.media && API.media.save) {\n          const r = await Promise.resolve(API.media.save({ dataUrl: S.draft.saveImg }));\n          toast(r && r.ok ? '已存进小手机媒体库' : '已提交保存');\n        } else toast('这个环境没有媒体库，试试下载或发聊天室');\n      } catch (e) { toast('保存失败：' + ((e && e.message) || e)); }\n      return;\n    }\n    if (act === 'download') {\n      try {\n        if (API && API.media && API.media.download) {\n          const ok = await Promise.resolve(API.media.download({ dataUrl: S.draft.saveImg, filename: S.draft.saveName || 'image.png' }));\n          toast(ok === false ? '下载被拦截' : '已保存：' + (S.draft.saveName || 'image'));\n          return;\n        }\n      } catch (e) { }\n      try {\n        const a = document.createElement('a'); a.href = S.draft.saveImg; a.download = S.draft.saveName;\n        document.body.appendChild(a); a.click(); a.remove(); toast('已再次尝试下载');\n      } catch (e) { toast('下载被拦截'); }\n      return;\n    }\n    if (act === 'copy') {\n      try {\n        const blob = dataUrlToBlob(S.draft.saveImg);\n        await navigator.clipboard.write([new ClipboardItem({ [blob.type]: blob })]);\n        toast('已复制图片');\n        return;\n      } catch (e) { }\n      try {\n        if (API && API.media && API.media.save) {\n          await Promise.resolve(API.media.save({ dataUrl: S.draft.saveImg }));\n          toast('这里复制不了图片，已帮你存进媒体库');\n          return;\n        }\n      } catch (e2) { }\n      toast('当前环境不支持复制图片，试试「存进媒体库」');\n      return;\n    }\n    if (act === 'window') {\n      try {\n        const nw = window.open('', '_blank');\n        if (!nw) { toast('被浏览器拦截，请允许弹出窗口'); return; }\n        nw.document.write('<title>图片</title><body style=\"margin:0;background:#111\"><img src=\"' + S.draft.saveImg + '\" style=\"width:100%;display:block\">');\n        nw.document.close(); toast('已在新窗口打开，可长按或右键保存');\n      } catch (e) { toast('无法打开新窗口'); }\n      return;\n    }\n    if (act === 'chat') {\n      const cid = b.dataset.cid || anyCharId();\n      if (!cid) { toast('还没有角色'); return; }\n      const ok = await sendImageCard(cid, S.draft.saveImg, S.draft.saveTitle || '图片');\n      toast(ok ? '已发到聊天室，去那里保存' : '发送失败');\n      closeSheet(w);\n    }\n  });\n}\nasync function sendImageCard(cid, dataUrl, title) {\n  if (!cid || !dataUrl) return false;\n  const ok = await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'system',\n    summary: `[图片] ${title || '壁纸'}`,\n    historyText: `[图片：${title || '壁纸'}，用户可长按保存]`, historyRole: 'system',\n    card: {\n      appLabel: '角色陪伴专注', title: title || '壁纸', subtitle: '长按图片可保存', status: '图片', height: 380,\n      html: `<div style=\"padding:8px;background:#0d111c\"><img src=\"${dataUrl}\" style=\"width:100%;border-radius:12px;display:block\">\n        <div style=\"color:#8b97ad;font-size:12px;padding:8px 2px\">长按这张图片即可保存到相册</div></div>`\n    }\n  }), null);\n  return !!ok;\n}\n/* 保存图片：两条路一起走，哪条通用都至少留下一份。\n   ① 走宿主：交给小手机存进素材库（APP 沙盒里唯一被官方支持的持久化通道，\n      不依赖 WebView 对 a[download] 的支持，存下来的图片小手机内部随时能引用）；\n   ② 原来那条路照旧保留：浏览器 a[download]，在系统浏览器或自带壳里会落到「下载」目录。\n   以前只走 ② —— 在没挂下载能力的 WebView 里会「弹了提示却什么都没落下」。 */\nasync function saveImageAnywhere(dataUrl, filename, title, charId) {\n  if (!dataUrl) { toast('还没有图片'); return; }\n  const name = filename || ('image_' + dkey() + '.png');\n  /* ① 宿主通道：存在小手机素材库里 */\n  let hostOk = false;\n  try {\n    const r = await sdk(() => API.media.save({ dataUrl: dataUrl, type: 'custom_app_media' }), null);\n    hostOk = !!(r && r.ok);\n  } catch (e) { hostOk = false; }\n  /* ② 原路：浏览器下载（用户在系统浏览器里打开时这条最直接） */\n  let dlOk = false;\n  try {\n    const a = document.createElement('a');\n    a.href = dataUrl; a.download = name; a.rel = 'noopener';\n    document.body.appendChild(a); a.click(); a.remove();\n    dlOk = true;\n  } catch (e) { dlOk = false; }\n  if (hostOk && dlOk) toast('已存进小手机素材库，也已开始下载：' + name);\n  else if (hostOk) toast('已存进小手机素材库：' + name);\n  else if (dlOk) toast('已开始下载：' + name);\n  else toast('两种方式都没成功 —— 可以长按图片保存，或用手机截图留下这张图');\n}\n/* ==========================================================\n   奖励：角色给用户买东西/转账/发红包/做件事（v1.9.2 校验标记 C）\n   由 APP 把任务写进聊天室 → 角色自己回复 → 抓回复当凭证\n   ========================================================== */\nconst REWARD_GIFTS = ['一束花', '一杯热奶茶', '一盒你爱吃的点心', '一本你提过的书', '一条围巾', '一张你喜欢的专辑', '一份深夜外卖', '一个小摆件', '一张手写的卡片'];\nconst REWARD_ACTS = ['给你唱一首你喜欢的歌', '陪你把今天的事聊完', '给你读一段睡前故事', '给你写一张小便签', '明天早上叫你起床', '给你拍一张今天的天空', '陪你看一集你想看的剧'];\nconst REWARD_KIND_LABEL = { gift: 'TA 要送你礼物', pay: 'TA 要转账给你', redpack: 'TA 要给你发红包', act: 'TA 要为你做件事' };\nfunction rewardKinds() { const k = cfg('rewardKinds'); return (Array.isArray(k) && k.length) ? k : ['gift', 'pay', 'redpack', 'act']; }\nfunction pendingRewards() { return (S.rewards || []).filter(r => !r.claimed); }\nasync function saveReward(rec) {\n  if (!rec) return;\n  if (rec.dbId) await DB.update(T.REWARD, rec.dbId, { data: rec });\n  else { const r = await DB.create(T.REWARD, { data: rec }); if (r) rec.dbId = r.id; }\n}\nasync function createRewardGift(reason, streak) {\n  const cid = pickOneChar(null);\n  if (!cid) { toast('先选一位陪伴角色'); return null; }\n  const kind = rewardKinds()[Math.floor(Math.random() * rewardKinds().length)];\n  const rec = { id: uid(), kind: kind, reason: reason || '', streak: streak || 0, charId: cid, claimed: false, at: Date.now(), line: '', want: '' };\n  if (kind === 'gift') { rec.gift = REWARD_GIFTS[Math.floor(Math.random() * REWARD_GIFTS.length)]; rec.price = Number(cfg('rewardGiftPrice') || 199); rec.want = `送你「${rec.gift}」`; }\n  else if (kind === 'pay') { rec.amount = Number(cfg('rewardPayAmount') || 520); rec.want = `转账 ¥${rec.amount} 给你`; }\n  else if (kind === 'redpack') { rec.amount = Number(cfg('rewardPackAmount') || 88); rec.want = `给你发 ¥${rec.amount} 红包`; }\n  else { rec.act = REWARD_ACTS[Math.floor(Math.random() * REWARD_ACTS.length)]; rec.want = rec.act; }\n  await saveReward(rec); S.rewards.unshift(rec);\n  await syncTimeline(cid, `${charName(cid)}准备送用户一份奖励：${rec.want}（${reason}）`, 'reward_give', {});\n  return rec;\n}\nasync function captureChatReply(cid, sinceAt) {\n  const list = [];\n  const push = h => {\n    if (Array.isArray(h)) list.push.apply(list, h);\n    else if (h && Array.isArray(h.messages)) list.push.apply(list, h.messages);\n  };\n  // 1) 当前会话：只有从聊天室卡片 / + 号面板进入本 APP 时才拿得到 sessionId（宿主限制）\n  const cur = await sdk(() => API.chat.getCurrentSession(), null);\n  if (cur && cur.sessionId) push(await sdk(() => API.chat.readHistory({ sessionId: cur.sessionId, limit: 20 }), null));\n  // 2) 按角色读最近消息（需要 chat.read 权限，本版本已声明）\n  if (!list.length) push(await sdk(() => API.chat.readHistory({ characterId: cid, limit: 20 }), null));\n  if (!list.length) return null;\n  const hits = list.filter(m => m && m.role === 'assistant' && (!sinceAt || (m.at || m.createdAt || 0) >= sinceAt - 3000));\n  const last = hits.pop();\n  return last ? { text: String(last.content || last.text || '').trim(), messageId: last.id || '' } : null;\n}\nasync function deliverReward(rec) {\n  if (!rec) return rec;\n  const cid = rec.charId || anyCharId();\n  if (!cid) { toast('还没有角色'); return rec; }\n  if (rec.delivering) { toast('正在和 TA 沟通，请稍候'); return rec; }\n  rec.delivering = true; render();\n  const askedAt = Date.now();\n  let proof = '', messageId = '';\n  const kindWord = rec.kind === 'gift' ? '给他一份礼物' : rec.kind === 'pay' ? '给他转一笔钱' : rec.kind === 'redpack' ? '给他发一个红包' : '为他做这件事';\n  const taskText = promptText('reward.ask', {\n    charName: charName(cid), reason: rec.reason || '一段坚持', want: rec.want || '一份心意', kindWord: kindWord\n  });\n  rec.taskText = taskText;\n  try {\n    if ((cfg('rewardAskStyle') || 'card') === 'user') {\n      // 以「你的消息」写进聊天室（老写法，角色容易读成你在索要）\n      await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'user', content: '[奖励申请] ' + taskText }));\n    } else {\n      // 默认：以系统卡片写进聊天室，明确是 APP 通知而不是你在要东西\n      const okCard = await sdk(() => API.chat.sendCard({\n        characterId: cid, role: 'system', historyRole: 'system',\n        summary: '专注 APP 奖励申请：' + taskText, historyText: taskText,\n        card: {\n          appLabel: '角色陪伴专注', title: '该你兑现奖励了', subtitle: 'REWARD APPLY', status: '待你亲手交给 TA',\n          accentColor: '#ffc978', height: 250,\n          sections: [{ title: '奖励内容', rows: [\n            { label: 'TA 达成的', value: rec.reason || '—' },\n            { label: '你答应给的', value: rec.want || '—' },\n            { label: '形式', value: REWARD_KIND_LABEL[rec.kind] || '奖励' }\n          ] }],\n          html: '<div style=\"padding:14px;font:13.5px/1.75 -apple-system,BlinkMacSystemFont,sans-serif\">' +\n            '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 系统通知</div>' +\n            '<div style=\"margin-top:8px\">' + esc(taskText) + '</div></div>'\n        }\n      }), null);\n      if (!okCard) await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: taskText }));\n    }\n    let ret = null;\n    try { ret = await API.chat.requestReply({ characterId: cid }); } catch (e) { ret = null; }\n    const fromRet = ret && (ret.text || ret.content || (ret.message && (ret.message.content || ret.message.text)) || (ret.reply && (ret.reply.content || ret.reply.text)));\n    if (fromRet) { proof = String(fromRet).trim(); messageId = (ret.message && ret.message.id) || (ret.reply && ret.reply.id) || ''; }\n    if (!proof) { const cap = await captureChatReply(cid, askedAt); if (cap) { proof = cap.text; messageId = cap.messageId; } }\n    if (!proof) {\n      let line = '';\n      try { line = await pGen('reward.fallback', { reason: rec.reason || '一段坚持', want: rec.want }, [cid]); } catch (e) { line = ''; }\n      if (!line) line = `给你的，${rec.want}。拿着吧。`;\n      proof = String(line).trim().replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n      await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: proof }));\n      rec.proofFromAi = true;\n    }\n  } catch (e) { console.warn('deliverReward', e); }\n  rec.delivering = false;\n  await finishReward(rec, proof, messageId, {});\n  return rec;\n}\n/* 奖励统一的落地处理：记账 + 留念壁纸 + 写记忆。「手动同步」也走这里 */\nasync function finishReward(rec, proof, messageId, opt) {\n  opt = opt || {};\n  const cid = rec.charId || anyCharId();\n  rec.claimed = true; rec.claimAt = Date.now();\n  rec.proof = proof || ''; rec.proofAt = Date.now(); rec.proofMessageId = messageId || '';\n  if (opt.manual) rec.proofManual = true;\n  if (rec.kind === 'gift' && proof) await giftTo(cid, rec.gift, rec.price, { real: true, from: 'char' });\n  const money = (proof || '').match(/[¥￥]\\s?(\\d+(?:\\.\\d+)?)/);\n  if (money && (rec.kind === 'pay' || rec.kind === 'redpack')) rec.amount = Number(money[1]) || rec.amount;\n  if (rec.kind === 'pay' || rec.kind === 'redpack') {\n    const lrec = {\n      type: 'income', amount: Number(rec.amount) || 0, charId: cid, real: false, at: Date.now(), proof: proof || '',\n      note: (rec.kind === 'redpack' ? 'TA 发的红包 · ' : 'TA 转给我的 · ') + (rec.reason || '') +\n        (opt.manual ? '（用户手动同步）' : rec.proofFromAi ? '（凭证为补生成）' : '（以 TA 的回复为凭证）')\n    };\n    const r = await DB.create(T.LEDGER, lrec);\n    if (r) S.ledger.unshift(Object.assign({ id: r.id }, lrec));\n  }\n  if (cfg('rewardWallpaper') && canGenWall() && !opt.skipWall && API && API.ai && API.ai.generateImage) {\n    const c = charById(cid);\n    try {\n      const r = await genImgLogged('img.reward', '奖励留念壁纸', promptText('img.reward', { charName: (c && c.name) ? c.name : '一位角色', want: rec.want || '一份礼物' }), cid, () => API.ai.generateImage({\n        prompt: promptText('img.reward', { charName: (c && c.name) ? c.name : '一位角色', want: rec.want || '一份礼物' }),\n        characterId: cid || undefined, useReferenceImage: true, timeoutMs: 120000\n      }));\n      if (r && r.dataUrl) {\n        const item = await saveAlbum('reward', r.dataUrl, { title: '奖励留念 · ' + (rec.want || ''), note: rec.proof, locked: false, charId: cid });\n        if (item) rec.wallId = item.id;\n      }\n    } catch (e) { }\n  }\n  await saveReward(rec);\n  await addPublic('reward', `${charName(cid)}给的奖励（原话）：${rec.proof || rec.want}`, cid, {});\n  await syncTimeline(cid, `用户向${charName(cid)}领取了奖励「${rec.reason || ''}」，TA 的回复：${rec.proof || ''}`, 'reward_claim', {});\n  toast(rec.proof ? (opt.manual ? '已同步：这份奖励记为已领取' : 'TA 的回复已抓来当凭证') : '已把奖励任务写进聊天室');\n  render();\n  return rec;\n}\n/* ==========================================================\n   睡眠：正计时 / 壁纸 / 报告 / 连续作息\n   ========================================================== */\nconst SLEEP_MODES = [['小憩', 20], ['午睡', 30], ['长睡眠', 480]];   /* v1.9.2 校验标记 H */\nlet sleepTicker = null;\n/* ---------- 睡眠会话持久化：离开 APP、关掉小程序也不会丢 ---------- */\nasync function saveSleepSession() {\n  const st = S.sleep; if (!st) return;\n  const data = {\n    mode: st.mode, startAt: st.startAt, targetSec: st.targetSec || 0, alerted: !!st.alerted,\n    running: !!st.running, wpRef: st.wpRef || '', albumId: st.albumId || '', date: dkey(new Date(st.startAt)),\n    breaks: (st.breaks || []).slice(),\n    charIds: (st.charIds || []).slice(), lastActiveAt: st.lastActiveAt || st.startAt,\n    sleepAccMs: st.sleepAccMs || 0, away: !!st.away, lastAwayAt: st.lastAwayAt || 0,\n    idleGapMin: st.idleGapMin || Math.max(1, Number(cfg('sleepIdleMin') || 5)),\n    chat: (st.chat || []).slice(-60), lullaby: st.lullaby || '', lullabyChar: st.lullabyChar || '',\n    lullabyRef: st.lullabyRef || '', lullabyAt: st.lullabyAt || 0,\n    scene: st.scene || '', sceneChar: st.sceneChar || '', sceneAt: st.sceneAt || 0,\n    inviteLine: st.inviteLine || '', inviteChar: st.inviteChar || ''\n  };\n  if (st.sessId) await DB.update(T.SSESS, st.sessId, data);\n  else { const r = await DB.create(T.SSESS, data); if (r) st.sessId = r.id; }\n}\nasync function clearSleepSession() {\n  const id = (S.sleep && S.sleep.sessId) || '';\n  if (id) await DB.remove(T.SSESS, id);\n}\nasync function restoreSleepSession() {\n  const rows = (await DB.list(T.SSESS)) || [];\n  const row = rows.sort((a, b) => (b.startAt || 0) - (a.startAt || 0))[0];\n  if (!row || !row.startAt) return null;\n  const st = {\n    sessId: row.id, mode: row.mode || '午睡', startAt: row.startAt, targetSec: row.targetSec || 0,\n    alerted: !!row.alerted, running: true, wp: '', wpRef: row.wpRef || '', wpLoading: false, wpErr: '',\n    albumId: row.albumId || '', breaks: row.breaks || [],\n    charIds: row.charIds || [], lastActiveAt: row.lastActiveAt || row.startAt,\n    sleepAccMs: row.sleepAccMs || 0, away: !!row.away, lastAwayAt: row.lastAwayAt || 0,\n    idleGapMin: row.idleGapMin || Math.max(1, Number(cfg('sleepIdleMin') || 5)), chat: row.chat || [],\n    lullaby: row.lullaby || '', lullabyChar: row.lullabyChar || '', lullabyRef: row.lullabyRef || '', lullabyAt: row.lullabyAt || 0,\n    scene: row.scene || '', sceneChar: row.sceneChar || '', sceneAt: row.sceneAt || 0,\n    inviteLine: row.inviteLine || '', inviteChar: row.inviteChar || ''\n  };\n  S.sleep = st;\n  if (st.wpRef) {\n    const r = await sdk(() => API.media.get({ ref: st.wpRef }), null);\n    if (r && r.dataUrl) st.wp = r.dataUrl;\n  }\n  return st;\n}\n/* 取一张用户选的图片：优先宿主媒体库选择器，失败则用应用内文件选择 */\nasync function pickImageData() {\n  const r = await sdk(() => API.media.pick({ accept: 'image/*' }), null);\n  if (r && r.file && r.file.dataUrl) return String(r.file.dataUrl);\n  return await new Promise(resolve => {\n    const inp = document.createElement('input');\n    inp.type = 'file'; inp.accept = 'image/*';\n    inp.style.position = 'fixed'; inp.style.left = '-9999px'; inp.style.top = '0';\n    document.body.appendChild(inp);\n    let done = false;\n    const finish = v => { if (done) return; done = true; try { inp.remove(); } catch (e) { } resolve(v); };\n    inp.addEventListener('change', () => {\n      const f = inp.files && inp.files[0];\n      if (!f) { finish(''); return; }\n      const fr = new FileReader();\n      fr.onload = () => finish(String(fr.result || ''));\n      fr.onerror = () => finish('');\n      fr.readAsDataURL(f);\n    });\n    try { inp.click(); } catch (e) { finish(''); return; }\n    setTimeout(() => finish(''), 180000);\n  });\n}\nasync function sleepWallUrl() {\n  const st = S.sleep;\n  if (st && st.wp) return st.wp;\n  if (st && st.wpRef) {\n    const r = await sdk(() => API.media.get({ ref: st.wpRef }), null);\n    if (r && r.dataUrl) { st.wp = r.dataUrl; return r.dataUrl; }\n  }\n  if (S.lastSleepWall) return S.lastSleepWall;\n  if (S.lastSleepWallRef) {\n    const r = await sdk(() => API.media.get({ ref: S.lastSleepWallRef }), null);\n    if (r && r.dataUrl) { S.lastSleepWall = r.dataUrl; S.settings.lastSleepWallRef = S.lastSleepWallRef; return r.dataUrl; }\n  }\n  return '';\n}\n/* 壁纸取图：每个目标只尝试一次，且只在状态真的变了才重画 —— 避免反复渲染导致页面闪烁 */\nlet lastWallTry = '';\nlet wallFillBusy = false;\nasync function fillSleepWall() {\n  if (wallFillBusy) return;\n  wallFillBusy = true;\n  try {\n    const st = S.sleep;\n    if (st && st.wpRef && !st.wp) {\n      const key = 'sess:' + (st.sessId || st.wpRef);\n      if (lastWallTry !== key) {\n        lastWallTry = key;\n        const r = await sdk(() => API.media.get({ ref: st.wpRef }), null);\n        if (r && r.dataUrl) { st.wp = r.dataUrl; render(); return; }\n      }\n    }\n    if (!S.lastSleepWall && S.lastSleepWallRef) {\n      const key = 'last:' + S.lastSleepWallRef;\n      if (lastWallTry !== key) {\n        lastWallTry = key;\n        const r = await sdk(() => API.media.get({ ref: S.lastSleepWallRef }), null);\n        if (r && r.dataUrl) { S.lastSleepWall = r.dataUrl; render(); }\n      }\n    }\n  } finally { wallFillBusy = false; }\n}\nfunction startSleepTicker() {\n  if (sleepTicker) return;\n  sleepTicker = setInterval(() => {\n    const st = S.sleep; if (!st || !st.running) return;\n    const el = document.getElementById('sleepClock');\n    if (el) el.textContent = fmtClock((Date.now() - st.startAt) / 1000);\n    const el2 = document.getElementById('sleepLeft');\n    if (el2) {\n      const passed = sleepElapsedSec();\n      el2.textContent = '总 ' + fmtDur(passed) + ' · 酝酿 ' + fmtDur(sleepDrowsySec()) + ' · 睡眠 ' + fmtDur(sleepSleepSec())\n        + (st.targetSec ? '（计划 ' + fmtDur(st.targetSec) + '）' : ' · 睡到自然醒');\n      const ph = document.getElementById('sleepPhase');\n      if (ph) ph.textContent = sleepPhaseText();\n      if (st.targetSec && passed >= st.targetSec && !st.alerted) {\n        st.alerted = true;\n        notify('睡够了', '已经达到你设定的时长，要结束记录吗？');\n        saveSleepSession();\n      }\n    }\n  }, 1000);\n}\n/* ==========================================================\n   睡眠计时规则（v1.9.2 校验标记 D）\n   - 酝酿睡意 = 还没睡的时间：和角色闲聊、切到别的 APP、动屏幕，都算醒着\n   - 入睡起点 = 在睡眠页「连续 N 分钟不动屏幕、也不和角色互动」之后（N 默认 5，可改）\n   - 睡眠时长 = 所有安静时段各自扣掉前 N 分钟后的总和\n   ========================================================== */\nfunction sleepGapMs() {\n  const st = S.sleep;\n  const m = Number((st && st.idleGapMin) || cfg('sleepIdleMin') || 5);\n  return Math.max(1, m) * 60000;\n}\nfunction sleepElapsedSec() {\n  const st = S.sleep; if (!st) return 0;\n  return Math.max(0, Math.round((Date.now() - st.startAt) / 1000));\n}\n/* 当前这段安静时间里，已经够条件算作睡眠的毫秒数 */\nfunction currentIdleSleepMs() {\n  const st = S.sleep;\n  if (!st || !st.running || st.away) return 0;\n  const idle = Date.now() - (st.lastActiveAt || st.startAt);\n  const gap = sleepGapMs();\n  return idle > gap ? idle - gap : 0;\n}\nfunction sleepSleepSec() {\n  const st = S.sleep; if (!st) return 0;\n  return Math.max(0, Math.round(((st.sleepAccMs || 0) + currentIdleSleepMs()) / 1000));\n}\nfunction sleepDrowsySec() {\n  const st = S.sleep; if (!st) return 0;\n  return Math.max(0, sleepElapsedSec() - sleepSleepSec());\n}\n/* 有活动了：先把上一段安静时间结算进睡眠累计，再把活动时间往后推 */\nasync function markSleepActive(reason) {\n  const st = S.sleep; if (!st || !st.running) return;\n  st.sleepAccMs = (st.sleepAccMs || 0) + currentIdleSleepMs();\n  if (st.away) st.away = false;\n  st.lastActiveAt = Date.now();\n  if (Date.now() - (st.lastSavedAt || 0) > 10000 || reason === 'chat') {\n    st.lastSavedAt = Date.now();\n    await saveSleepSession();\n  }\n}\n/* 切到别的 APP：这段时间不算睡眠（按「醒着」处理），先结算已安静的时段 */\nasync function sleepGoAway() {\n  const st = S.sleep; if (!st || !st.running) return;\n  st.sleepAccMs = (st.sleepAccMs || 0) + currentIdleSleepMs();\n  st.away = true; st.lastAwayAt = Date.now(); st.lastActiveAt = Date.now();\n  await saveSleepSession();\n}\nasync function sleepComeBack() {\n  const st = S.sleep; if (!st || !st.running) return;\n  st.away = false; st.lastActiveAt = Date.now();\n  await saveSleepSession();\n}\nfunction sleepPhaseText() {\n  const st = S.sleep; if (!st || !st.running) return '';\n  const gap = Math.max(1, Math.round(sleepGapMs() / 60000));\n  const s = sleepSleepSec();\n  if (st.away) return '📵 你不在睡眠页，现在不算睡眠（这段时间记作酝酿睡意）';\n  if (s <= 0) {\n    const left = Math.max(0, Math.ceil((sleepGapMs() - (Date.now() - (st.lastActiveAt || st.startAt))) / 1000));\n    return '🛏 酝酿睡意中 · 保持这个页面不动屏幕 ' + fmtClock(left) + ' 后开始算睡眠';\n  }\n  return '🌙 已入睡 ' + fmtDur(s) + ' · 酝酿 ' + fmtDur(sleepDrowsySec()) + '（连续 ' + gap + ' 分钟不动屏幕后开始计入）';\n}\nasync function startSleep(mode, minutes) {\n  let ids = (cfg('sleepCharIds') || []).filter(id => charById(id));\n  /* 没选陪睡角色时，别直接把按钮按死（看起来就像「按钮坏了」）：\n     先退到专注阵容；再没有才提示。 */\n  if (!ids.length) {\n    ids = (cfg('charIds') || []).filter(id => charById(id));\n    if (ids.length) { S.settings.sleepCharIds = ids.slice(); saveSettings(); }\n  }\n  if (!ids.length && S.chars.length) {\n    ids = [S.chars[0].id];\n    S.settings.sleepCharIds = ids.slice();\n    saveSettings();\n    toast('还没选陪睡角色，先用「' + charName(ids[0]) + '」陪你，可在上面换');\n  }\n  const now = Date.now();\n  S.sleep = {\n    sessId: '', mode: mode, startAt: now, targetSec: minutes ? minutes * 60 : 0, alerted: false,\n    running: true, wp: '', wpRef: '', wpLoading: false, wpErr: '', albumId: '', breaks: [],\n    charIds: ids.slice(), lastActiveAt: now, chat: [], lullaby: '', lullabyChar: '', lullabyRef: '', lullabyAt: 0,\n    sleepAccMs: 0, away: false, lastAwayAt: 0, lastSavedAt: 0, inviteLine: '', inviteChar: '',\n    idleGapMin: Math.max(1, Number(cfg('sleepIdleMin') || 5))\n  };\n  S.settings.sleepMinutes = minutes || 0; if (mode) S.settings.sleepMode = mode;\n  saveSettings();\n  await saveSleepSession();     // 落库：离开小程序也能接着上次\n  startSleepTicker(); render();\n  if (!S.sleep.wp && !S.sleep.wpRef) genSleepWallpaper();   // 开始正计时就自动生成壁纸并铺满背景\n  genSleepScene();                                          // 计时页顶端：你们一起睡的环境描写\n  if (cfg('sleepLullaby') !== false) playLullaby();         // 哄睡语音（同时进对话框）\n  return true;\n}\n/* 睡眠环境描写：和角色一起睡的场景、姿势、光线 */\nasync function genSleepScene() {\n  const st = S.sleep; if (!st || !st.running) return;\n  quietOn();          // 睡眠页自动生成：不锁住你的操作\n  try {\n  const cid = sleepCharId(); if (!cid) return;\n  const c = charById(cid);\n  let text = '';\n  try { text = await pGen('sleep.scene', { mode: st.mode || '睡觉', time: hm(st.startAt), charName: charName(cid) }, [cid]); } catch (e) { text = ''; }\n  if (!text) text = `灯已经关了，房间里只剩窗外一点微光。${c ? c.name : 'TA'}把被子给你掖到肩膀，自己侧过身来，和你隔着一拳的距离；两个人慢慢把呼吸对上了同一个节奏。`;\n  st.scene = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 300);\n  st.sceneChar = cid; st.sceneAt = Date.now();\n  await saveSleepSession();\n  if (S.view === 'sleep') render();\n  } finally { quietOff(); }\n}\n/* 陪睡角色池：睡眠进行中用这次会话的阵容，否则用设置里的阵容 */\nfunction sleepPoolIds() {\n  const st = S.sleep;\n  const pool = ((st && st.charIds && st.charIds.length) ? st.charIds : (cfg('sleepCharIds') || [])).filter(id => charById(id));\n  return pool;\n}\n/* 睡眠中随机挑一位陪伴角色（单选就一直是 TA） */\nfunction sleepCharId() {\n  const pool = sleepPoolIds();\n  return pool.length ? pool[Math.floor(Math.random() * pool.length)] : '';\n}\n/* 陪睡阵容变了：正在记录的睡眠要当场跟着换，不然壁纸/报告还是老角色 */\nasync function applySleepChars() {\n  const st = S.sleep;\n  const pool = (cfg('sleepCharIds') || []).filter(id => charById(id));\n  if (st && st.running && pool.length) {\n    st.charIds = pool.slice();\n    await saveSleepSession();\n  }\n}\n/* 哄睡语音：生成一句台词 → 留存语音 → 播放，并同步进角色记忆 */\nasync function playLullaby() {\n  const st = S.sleep; if (!st || !st.running) return;\n  quietOn();          // 开始睡眠后自动生成：不锁住你的操作\n  try {\n  const cid = sleepCharId(); if (!cid) return;\n  /* 接着他今天递过的小纸条说 —— 那些撑不住的瞬间，睡前的这一句正好接上 */\n  let noteLines = '（他今天没有递过小纸条）';\n  if (cfg('noteLinkSleep') !== false) {   // 哄睡这一侧有自己的开关，和专注里互不影响\n    const mine = noteAll().filter(n => String(n.charId) === String(cid)).slice(0, 5);\n    if (mine.length) noteLines = mine.reverse().map(n => '· 「' + n.text + '」（你当时写给他：' + (n.ann || n.reply) + '）').join('\\n');\n  }\n  let text = '';\n  try { text = await pGen('sleep.lullaby', { mode: st.mode || '睡觉', time: hm(st.startAt), notes: noteLines }, [cid]); } catch (e) { text = ''; }\n  if (!text) text = '该睡了，把手机放下，我在这儿。';\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 80);\n  st.lullaby = text; st.lullabyChar = cid; st.lullabyAt = Date.now();\n  st.chat = st.chat || [];\n  st.chat.push({ role: 'char', charId: cid, text: text, at: Date.now(), kind: 'lullaby' });   // 哄睡语进对话框\n  await saveSleepSession(); render();\n  const r = await ttsPlay(cid, text);\n  if (r && r.ref) { st.lullabyRef = r.ref; await saveSleepSession(); }\n  await syncTimeline(cid, `${charName(cid)}在用户开始${st.mode || '睡觉'}时哄他入睡：${text}`, 'sleep_lullaby', {});\n  } finally { quietOff(); }\n}\nasync function genSleepWallpaper() {\n  const st = S.sleep; if (!st || st.wpLoading) return;\n  if (!canGenWall()) return;                     // 总开关/自定义壁纸联动：睡眠壁纸也不再生成\n  if (!API || !API.ai || !API.ai.generateImage) { toast('生图不可用，请先配置生图 API'); return; }\n  quietOn();          // 开始睡眠后自动补壁纸：不锁住你的操作\n  try {\n  /* 记住：这里必须用「陪睡角色」——以前写的是闹钟角色 / anyCharId()，\n     anyCharId() 会优先取专注阵容，导致换了陪睡角色壁纸还是别人。 */\n  const cid = sleepCharId() || anyCharId();\n  const c = charById(cid);\n  st.wpLoading = true; st.wpErr = ''; render();\n  try {\n    const curS = sleepWallStyle();\n    const styleK = curS === 'rotate' ? ['calm', 'moon', 'lamp', 'cozy'][(Number(S.sleepWallRot) || 0) % 4] : curS;\n    const sPid = sleepWallPromptIdOf(styleK);\n    st.wallStyleKey = styleK;\n    const sVars = { charName: (c && c.name) ? c.name : '一位角色', mode: st.mode || '睡眠' };\n    const sPrompt = promptText(sPid, sVars) + wallVaryLine();\n    const r = await genImgLogged(sPid, '睡眠壁纸（' + sleepWallStyleName(styleK) + '）', sPrompt, cid, () => API.ai.generateImage({\n      prompt: sPrompt,\n      characterId: cid || undefined, useReferenceImage: true, timeoutMs: 120000\n    }));\n    if (r && r.dataUrl) {\n      st.wp = r.dataUrl;\n      const put = await sdk(() => API.media.put({ dataUrl: r.dataUrl }), null);\n      if (put && put.ref) st.wpRef = put.ref;\n      // 睡眠壁纸不属于「上锁的历史壁纸」，生成即入库且可直接保存\n      const item = await saveAlbum('sleep', r.dataUrl, { title: '睡眠壁纸 · ' + sleepWallStyleName(styleK) + ' ' + dkey(), locked: false, note: `${st.mode} · ${hm(st.startAt)} 开始 · 样式：${sleepWallStyleName(styleK)}`, charId: cid });\n      if (item) st.albumId = item.id;\n      await saveSleepSession();\n      toast(item ? '壁纸已存入壁纸库，可直接保存' : '壁纸已生成，但入库失败');\n    } else st.wpErr = '生图接口没有返回图片';\n  } catch (e) { st.wpErr = (e && e.message) || '生图失败'; }\n  st.wpLoading = false; render();\n  } finally { quietOff(); }\n}\nfunction sleepStreak() {\n  const minSec = Number(cfg('sleepValidHours') || 4) * 3600;\n  const keys = {};\n  // 达标看「实际入睡时长」（有分段数据时优先用它，旧记录回落到总时长）\n  (S.sleeps || []).forEach(s => {\n    const real = (s.sleepSec != null ? s.sleepSec : s.seconds);\n    if (real >= minSec && s.date) keys[s.date] = 1;\n  });\n  let n = 0; const d = new Date();\n  if (!keys[dkey(d)]) d.setDate(d.getDate() - 1);\n  while (keys[dkey(d)]) { n++; d.setDate(d.getDate() - 1); }\n  return n;\n}\nfunction streakMiles() {\n  const raw = cfg('sleepStreakMiles');\n  return (Array.isArray(raw) && raw.length ? raw : [3, 7, 14, 30]).map(Number).sort((a, b) => a - b);\n}\nfunction nextMile(streak) { for (const x of streakMiles()) if (streak < x) return x; return streakMiles().slice(-1)[0] + 7; }\nfunction localSleepReport(rec) {\n  /* 判断「够不够」用实际入睡时长 —— 总时长里包含睡前的酝酿时间 */\n  const h = (rec.sleepSec != null ? rec.sleepSec : rec.seconds) / 3600;\n  const brks = rec.breaks || [];\n  const q = h >= 7 && h <= 9 ? '这次睡得比较扎实，时长达标。' : h >= 6 ? '时长基本够，但离理想区间还差一点。' : '这次偏短，身体恐怕没休息够。';\n  const list = (S.sleeps || []).slice(0, 7);\n  const avg = list.length ? sum(list.map(x => (x.sleepSec != null ? x.sleepSec : x.seconds))) / list.length / 3600 : h;\n  const brkLine = brks.length\n    ? `入睡后中途醒了 ${brks.length} 次（${brks.map(b => hm(b.at) + '，第 ' + Math.max(0, Math.round((b.at - rec.startAt) / 60000)) + ' 分钟').join('；')}）。睡眠被切成 ${brks.length + 1} 段，完整性打折，深睡通常也更容易被打断。`\n    : '整段没有记录到中途醒来。';\n  const drowsySec = (rec.drowsySec != null ? rec.drowsySec : 0);\n  const sleepSecReal = (rec.sleepSec != null ? rec.sleepSec : Math.max(0, rec.seconds - drowsySec));\n  const idleMin = Number(rec.idleMin || cfg('sleepIdleMin') || 5);\n  const drowsyLine = drowsySec >= 300\n    ? `其中酝酿睡意 ${fmtDur(drowsySec)}（还在聊天、看屏幕、动手机的时间），实际入睡 ${fmtDur(sleepSecReal)}。酝酿偏久，等于把入睡时间往后推了。`\n    : `酝酿睡意只有 ${fmtDur(drowsySec)}，实际入睡 ${fmtDur(sleepSecReal)}（连续 ${idleMin} 分钟不动屏幕后才开始计入）。`;\n  const deepSec = Number(rec.deepSec) || 0;\n  const deepLine = deepSec\n    ? `预计深度睡眠 ${fmtDur(deepSec)}（占实际入睡约 ${Math.round(deepSec / Math.max(1, sleepSecReal) * 100)}%）。`\n    : '（这次没有填写预计深度睡眠）';\n  const aslLine = rec.asleep\n    ? `自评：${asleepLabel(rec.asleep)}。${rec.asleep === 'asleep' ? '' : '睡眠偏浅时，深睡比例通常也会更低。'}`\n    : '';\n  return {\n    quality: `${q}总时长 ${fmtDur(rec.seconds)}，其中酝酿睡意 ${fmtDur(drowsySec)}、实际入睡 ${fmtDur(sleepSecReal)}${deepSec ? '（预计深睡 ' + fmtDur(deepSec) + '）' : ''}，近 ${list.length} 次平均 ${avg.toFixed(1)} 小时。${brks.length ? `中途醒来 ${brks.length} 次，睡眠连续性偏弱。` : ''}`,\n    observe: `1. 本次${rec.mode || '睡眠'}从 ${hm(rec.startAt)} 开始，到 ${hm(rec.endAt)} 结束，总 ${fmtDur(rec.seconds)}。\\n2. ${drowsyLine}${aslLine ? ' ' + aslLine : ''}\\n3. ${deepLine}\\n4. ${brkLine}\\n5. 近 ${list.length} 次平均 ${avg.toFixed(1)} 小时，连续规律作息已 ${sleepStreak()} 天。`,\n    advice: (brks.length || drowsySec >= 180)\n      ? '1. 酝酿阶段别拖太久：上床前就把手机放下，聊天留到躺下之前。\\n2. 醒来别急着看时间，越算越清醒；闭眼做几次慢呼吸。\\n3. 睡前 1 小时别喝水太多、别碰屏幕，减少中途醒来与拖延入睡的诱因。'\n      : '1. 尽量固定入睡和起床时间，周末也别差太多。\\n2. 睡前 1 小时远离屏幕，把灯调暗。\\n3. 午睡控制在 30 分钟以内，别影响夜里入睡。',\n    murmur: brks.length ? '中间醒了几次也没关系，我在呢，接着睡。' : '今天也好好睡了，我很放心。明天也要这样，别熬夜。'\n  };\n}\nasync function genSleepReport(rec) {\n  S.report = S.report || {}; S.report.rec = rec; S.report.loading = true; render();\n  const cid = ((rec.charIds || [])[0]) || sleepCharId() || anyCharId();\n  const hist = (S.sleeps || []).slice(0, 7)\n    .map((x, i) => `${i + 1}. ${x.date} ${hm(x.startAt)}–${hm(x.endAt)}，${(x.seconds / 3600).toFixed(1)} 小时，模式：${x.mode || '睡眠'}`).join('\\n');\n  const brks = rec.breaks || [];\n  const breakText = brks.length\n    ? brks.map((b, i) => `${i + 1}. ${hm(b.at)}（入睡后第 ${Math.max(0, Math.round((b.at - rec.startAt) / 60000))} 分钟）${b.note ? '：' + b.note : ''}`).join('\\n')\n    : '（本次没有记录到中途醒来）';\n  let data = null;\n  try {\n    const drowsySec = (rec.drowsySec != null ? rec.drowsySec : 0);\n    const sleepSecReal = (rec.sleepSec != null ? rec.sleepSec : Math.max(0, rec.seconds - drowsySec));\n    const chatN = (rec.chat || []).length;\n    const text = await pGen('sleep.report', {\n      date: rec.date, mode: rec.mode || '睡眠', start: hm(rec.lastActiveAt || rec.startAt), end: hm(rec.endAt), endHm: hm(rec.endAt),\n      hours: (rec.seconds / 3600).toFixed(2),\n      totalDur: fmtDur(rec.seconds), drowsyDur: fmtDur(drowsySec), sleepDur: fmtDur(sleepSecReal),\n      awake: chatN ? ('用户睡前和角色聊了 ' + chatN + ' 句（最后一次互动 ' + hm(rec.lastActiveAt || rec.startAt) + '）') : '（没有睡前闲聊）',\n      idleMin: Number(rec.idleMin || cfg('sleepIdleMin') || 5),\n      asleepText: rec.asleep ? asleepLabel(rec.asleep) : '（用户没答）',\n      deepDur: rec.deepSec ? fmtDur(rec.deepSec) : '（未填写）',\n      scene: rec.scene || '（无）',\n      hist: hist || '（暂无历史记录）',\n      streak: sleepStreak(), validHours: Number(cfg('sleepValidHours') || 4),\n      breakCount: brks.length, breaks: breakText\n    }, [cid]);\n    data = parseJSON(text);\n  } catch (e) { data = null; }\n  if (!data || !data.quality) data = localSleepReport(rec);\n  S.report.quality = String(data.quality || '');\n  S.report.observe = String(data.observe || '');\n  S.report.advice = String(data.advice || '');\n  S.report.murmur = String(data.murmur || '');\n  S.report.charId = cid;\n  S.report.loading = false;\n  // 报告落库：存进这条睡眠记录，历史记录点开就能直接看，不必重新生成\n  rec.report = {\n    quality: S.report.quality, observe: S.report.observe, advice: S.report.advice,\n    murmur: S.report.murmur, charId: cid, at: Date.now(), breaks: brks\n  };\n  const hit = (S.sleeps || []).find(x => String(x.id) === String(rec.id));\n  if (hit) hit.report = rec.report;\n  if (rec.id) await sdk(() => DB.update(T.SLEEP, rec.id, JSON.parse(JSON.stringify(rec))), null);\n  if (cid) {\n    // 睡眠报告同步进角色短期记忆\n    await syncTimeline(cid, `睡眠报告（${rec.date} · ${(rec.seconds / 3600).toFixed(1)}小时${brks.length ? ' · 中途醒来 ' + brks.length + ' 次' : ''}）：${S.report.quality}｜观察：${String(S.report.observe).replace(/\\n/g, ' ')}｜建议：${String(S.report.advice).replace(/\\n/g, ' ')}｜${S.report.murmur}`, 'sleep_report', { seconds: rec.seconds, breaks: brks.length });\n    await addPublic('sleep', `睡眠报告（${rec.date} · ${(rec.seconds / 3600).toFixed(1)}小时）：${S.report.quality}`, cid, {});\n    await syncChatLine(cid, S.report.murmur || S.report.quality, 'assistant');\n    if (shouldSpeak('story')) {\n      /* 碎碎念的音频后台存一份（写进这条睡眠记录）——\n         报告页的「再听一遍」直接复用，不重新合成。\n         这里不能 await：否则报告要等语音合成完才显示。 */\n      voiceSay(cid, S.report.murmur || S.report.quality, 'sleepReport', '睡眠报告碎碎念').then(async vr => {\n        if (!vr || !vr.ref) return;\n        S.report.murmurRef = vr.ref;\n        rec.report = rec.report || {};\n        rec.report.murmurRef = vr.ref;\n        const hit2 = (S.sleeps || []).find(x => String(x.id) === String(rec.id));\n        if (hit2) hit2.report = rec.report;\n        if (rec.id) await sdk(() => DB.update(T.SLEEP, rec.id, JSON.parse(JSON.stringify(rec))), null);\n        if (S.report && S.report.rec && String(S.report.rec.id) === String(rec.id)) S.report.murmurRef = vr.ref;\n      }).catch(() => { });\n    }\n  }\n  render();\n}\n/* 结束前先问清楚：真的睡着了吗 + 预计深度睡眠时长 */\nconst SLEEP_ASLEEP = [['asleep', '睡着了'], ['light', '半睡半醒'], ['awake', '基本没睡着']];\nfunction asleepLabel(k) {\n  const hit = SLEEP_ASLEEP.filter(x => x[0] === k)[0];\n  return hit ? hit[1] : '未填写';\n}\nfunction endSleepAsk() {\n  const st = S.sleep;\n  if (!st || !st.running) { toast('当前没有在记录的睡眠'); return; }\n  const passed = sleepElapsedSec();\n  const d = sleepDrowsySec();\n  const sleepSec = sleepSleepSec();\n  const gap = Math.max(1, Math.round(sleepGapMs() / 60000));\n  const cur = S.draft.asleep || 'asleep';\n  if (S.draft.deepMin == null) S.draft.deepMin = Math.round(sleepSec / 60 * 0.3);\n  if (S.draft.realSleepMin == null) S.draft.realSleepMin = Math.round(sleepSec / 60);\n  const awayHint = st.lastAwayAt\n    ? `<div class=\"tiny mt6\" style=\"color:var(--gold)\">你最后一次离开睡眠页是 ${hm(st.lastAwayAt)}（之后 ${fmtDur(Math.round((Date.now() - st.lastAwayAt) / 1000))} 没计入睡眠 —— 切到别的 APP 按「还醒着」算）。如果那次切走之后就直接睡了，点下面修正。</div>\n       <button class=\"btn sm ghost block mt6\" data-act=\"sleepFromAway\">我切走之后就睡到现在，按这个算</button>`\n    : '';\n  const w = openSheet(`<h3>结束这次睡眠？</h3>\n    <div class=\"tiny\">规则：连续 ${gap} 分钟不动屏幕、也不互动之后才开始算睡眠；闲聊、切到别的 APP、动屏幕都算酝酿睡意。</div>\n    <div class=\"kv mt10\"><span class=\"k\">总时长</span><span>${fmtDur(passed)}</span></div>\n    <div class=\"kv\"><span class=\"k\">酝酿睡意（没睡）</span><span>${fmtDur(d)}</span></div>\n    <div class=\"kv\"><span class=\"k\">检测到的睡眠</span><span>${fmtDur(sleepSec)}</span></div>\n    ${awayHint}\n    <label class=\"fl\">实际入睡时长（分钟，可手动修正）</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" id=\"realSleepMin\" value=\"${Number(S.draft.realSleepMin) || 0}\">\n    <div class=\"tiny mt6\">留默认就是上面检测到的值；觉得不准就自己填一个（比如你中途把手机放桌上睡着的那段）。</div>\n    <label class=\"fl\">你真的睡着了吗？</label>\n    <div class=\"chips\">${SLEEP_ASLEEP.map(([k, n]) => `<button class=\"chip ${cur === k ? 'on' : ''}\" data-asl=\"${k}\">${n}</button>`).join('')}</div>\n    <label class=\"fl\">预计深度睡眠（分钟，自己估一个就行）</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" id=\"deepMin\" value=\"${Number(S.draft.deepMin) || 0}\">\n    <div class=\"tiny mt6\">睡得浅、夜里醒过就少填一点；睡得很沉可以按睡眠时长的 40%~50% 估。</div>\n    <div class=\"row mt12\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">再睡会儿</button>\n      <button class=\"btn primary grow\" data-act=\"endSleepDo\">结束并生成报告</button></div>`);\n  w.addEventListener('click', e => {\n    const b = e.target.closest('[data-asl]'); if (!b) return;\n    S.draft.asleep = b.dataset.asl;\n    w.querySelectorAll('[data-asl]').forEach(x => x.classList.toggle('on', x === b));\n  });\n  S.draft.awayAt = st.lastAwayAt || 0;\n}\nasync function endSleep(opts) {\n  opts = opts || {};\n  const st = S.sleep; if (!st) return;\n  const endAt = Date.now();\n  const sec = Math.round((endAt - st.startAt) / 1000);\n  let sleepSec = sleepSleepSec();                     // 检测到的睡眠（安静时段扣掉前 N 分钟）\n  if (opts.realSleepMin != null && String(opts.realSleepMin) !== '') {\n    sleepSec = clamp(Math.round(Number(opts.realSleepMin) * 60), 0, sec);   // 用户手动修正\n  }\n  const drowsy = Math.max(0, sec - sleepSec);\n  const asleep = opts.asleep || S.draft.asleep || '';\n  const deepSec = clamp(Math.round((Number(opts.deepMin != null ? opts.deepMin : S.draft.deepMin) || 0) * 60), 0, sleepSec);\n  st.running = false;\n  const wpUrl = st.wp || (await sleepWallUrl());\n  S.lastSleepWall = wpUrl || '';\n  S.lastSleepWallRef = st.wpRef || S.lastSleepWallRef || '';\n  S.lastSleepInfo = {\n    mode: st.mode, startAt: st.startAt, seconds: sec, endAt: endAt,\n    drowsySec: drowsy, sleepSec: sleepSec, breaks: (st.breaks || []).length,\n    asleep: asleep, deepSec: deepSec, idleMin: Math.max(1, Math.round(sleepGapMs() / 60000))\n  };\n  S.settings.lastSleepWallRef = S.lastSleepWallRef;\n  S.settings.lastSleepInfo = S.lastSleepInfo;\n  // 壁纸若还没入库（旧版本生成的），这里补一次，且不锁\n  if (wpUrl && !st.albumId) {\n    const item = await saveAlbum('sleep', wpUrl, { title: '睡眠壁纸 ' + dkey(new Date(st.startAt)), locked: false, note: `${st.mode} · ${hm(st.startAt)} 开始`, charId: anyCharId() });\n    if (item) st.albumId = item.id;\n  }\n  let rec = null;\n  if (sec > 60) {\n    rec = {\n      mode: st.mode, startAt: st.startAt, endAt: endAt, seconds: sec,\n      drowsySec: drowsy, sleepSec: sleepSec, asleep: asleep, deepSec: deepSec, scene: st.scene || '',\n      idleMin: Math.max(1, Math.round(sleepGapMs() / 60000)), lastAwayAt: st.lastAwayAt || 0, manual: (opts.realSleepMin != null && String(opts.realSleepMin) !== ''),\n      date: dkey(new Date(st.startAt)), albumId: st.albumId || '', breaks: (st.breaks || []).slice(),\n      charIds: (st.charIds || []).slice(), chat: (st.chat || []).slice(-40), lullaby: st.lullaby || '',\n      inviteLine: st.inviteLine || ''\n    };\n    const r = await DB.create(T.SLEEP, rec);\n    if (r) { rec.id = r.id; S.sleeps.unshift(rec); }\n    const cid = (st.charIds || [])[0] || sleepCharId() || anyCharId();\n    if (cid) await syncTimeline(cid, `用户${st.mode}了 ${fmtDur(sec)}，从 ${hm(st.startAt)} 到 ${hm(Date.now())}。`, 'sleep_done', {});\n    // 睡眠达标（按实际入睡）也给关系加分；连续达标另有奖励\n    if (cid && sleepSec >= Number(cfg('sleepValidHours') || 4) * 3600) await addBond(cid, 2, '一晚睡眠达标');\n  }\n  await clearSleepSession();      // 清掉进行中会话，避免重开又被恢复\n  await saveSettings(true);\n  S.sleep = null; stopVoice();\n  if (rec) {\n    // 结束就生成报告：先把这份记录挂上，再让角色写分析\n    S.report = { rec: rec, loading: false, quality: '', observe: '', advice: '', murmur: '', charId: anyCharId() };\n    go('sleepreport');\n    genSleepReport(rec);\n    return;\n  }\n  toast(sec > 0 ? '这次太短，没有记入睡眠记录' : '已结束'); render();\n}\nasync function checkStreakReward() {\n  const streak = sleepStreak();\n  const claimed = Number(cfg('claimedStreak') || 0);\n  const hit = streakMiles().filter(m => m <= streak && m > claimed).pop();\n  if (!hit) return null;\n  S.settings.claimedStreak = hit;\n  await saveSettings(true);\n  if (!cfg('rewardOnStreak')) return { streak: hit, ask: null, line: '连续规律作息达标，继续加油。' };\n  const rec = await createRewardGift(`连续规律作息 ${hit} 天`, hit);\n  const cid = anyCharId();\n  await addPublic('streak', `连续规律作息 ${hit} 天，${charName(cid)}准备了奖励：${rec ? rec.want : ''}`, cid, {});\n  return { streak: hit, ask: rec, line: rec ? rec.line : '' };\n}\n/* ==========================================================\n   出题与判分（AI 出题 → 答案一起入题库 → 本地瞬时判分）（v1.9.2 校验标记 E）\n   ========================================================== */\nfunction shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; }\nfunction norm(s) { return String(s == null ? '' : s).toLowerCase().replace(/[\\s，,。.、：:；;！!？?\"'“”‘’()（）\\[\\]【】]/g, ''); }\nfunction parseJSON(text) {\n  if (!text) return null;\n  let t = String(text).trim().replace(/^```(?:json)?\\s*/i, '').replace(/```\\s*$/, '').trim();\n  /* ① 原样先试一次：模型规规矩矩返回 JSON 时这一步就够了 */\n  try { return JSON.parse(t); } catch (e) { }\n  /* ② 按「第一个出现的括号」判断这次要的是对象还是数组。\n     ⚠️ 这里以前只按 { } 截取 —— 而变式题、AI 拆题在提示词里明确要求返回 JSON 数组，\n     形如 '[{\"q\":\"..\",\"a\":\"..\"},{\"q\":\"..\"}]'。\n     旧逻辑会把它截成 '{\"q\":\"..\"},{\"q\":\"..\"}'（两段对象用逗号连着，不是合法 JSON），\n     解析必然失败 → 调用方以为「模型没给出结果」→ 变式题永远出不来。\n     现在先看 '[' 还是 '{' 在前面，配对到最后一个收尾符，再解析。 */\n  const fb = t.indexOf('{'), fk = t.indexOf('[');\n  let start = -1, closeCh = '';\n  if (fk >= 0 && (fb < 0 || fk < fb)) { start = fk; closeCh = ']'; }\n  else if (fb >= 0) { start = fb; closeCh = '}'; }\n  if (start >= 0) {\n    const end = t.lastIndexOf(closeCh);\n    if (end > start) {\n      try { return JSON.parse(t.slice(start, end + 1)); } catch (e) { }\n    }\n  }\n  /* ③ 兜底：数组被包在对象里，或前面混了说明文字 */\n  const a = t.indexOf('['), b = t.lastIndexOf(']');\n  if (a >= 0 && b > a) { try { return JSON.parse(t.slice(a, b + 1)); } catch (e) { } }\n  const i2 = t.indexOf('{'), j2 = t.lastIndexOf('}');\n  if (i2 >= 0 && j2 > i2) { try { return JSON.parse(t.slice(i2, j2 + 1)); } catch (e) { } }\n  return null;\n}\n/* ---------- 题型内核：choice 单选 / fill 填空 / multi 多选 / tf 判断 ---------- */\nconst Q_TYPES = [['choice', '单选'], ['fill', '填空'], ['multi', '多选'], ['tf', '判断']];\nfunction qTypeLabel(t) { const h = Q_TYPES.filter(x => x[0] === t)[0]; return h ? h[1] : '单选'; }\nfunction qIsPick(q) { return !!q && (q.type === 'choice' || q.type === 'multi' || q.type === 'tf'); }\nfunction qPickOne(q) { return !q || q.type !== 'multi'; }\nfunction qAnswerText(q) {\n  if (!q) return '';\n  if (qIsPick(q)) {\n    const idxs = (q.type === 'multi') ? (q.answerIndexes || [q.answerIndex]) : [q.answerIndex];\n    return (idxs || []).map(k => (('ABCD'[k] || '') + ' ' + String((q.options || [])[k] || '')).trim()).join('　');\n  }\n  return String(q.answer || (q.keywords || []).join('/'));\n}\n/* 把各种写法统一成「下标数组」，多选用 */\nfunction normChoiceSet(v) {\n  if (Array.isArray(v)) return Array.from(new Set(v.map(x => Number(x)).filter(x => !isNaN(x)))).sort((a, b) => a - b);\n  if (v == null || v === '') return [];\n  return String(v).split(/[,，、\\s]+/).filter(Boolean).map(x => Number(x)).filter(x => !isNaN(x)).sort((a, b) => a - b);\n}\nfunction gradeOneQuestion(q, ans) {\n  if (!q) return false;\n  if (q.type === 'multi') {\n    const mine = normChoiceSet(ans);\n    const right = (q.answerIndexes || [q.answerIndex] || []).map(Number).sort((a, b) => a - b);\n    return mine.length > 0 && mine.length === right.length && mine.every((v, k) => v === right[k]);\n  }\n  if (q.type === 'choice' || q.type === 'tf') return Number(ans) === Number(q.answerIndex);\n  /* 填空放宽：完全一致 / 包含参考答案 / 命中任一关键词 都算对 */\n  const u = norm(ans), a = norm(q.answer);\n  const ks = (q.keywords || []).map(norm).filter(Boolean);\n  if (!u) return false;\n  if (a && (u === a || u.indexOf(a) >= 0)) return true;\n  if (a && u.length >= 2 && u.length >= a.length * 0.6 && a.indexOf(u) >= 0) return true;\n  if (ks.length) return ks.some(k => u.indexOf(k) >= 0);\n  return false;\n}\nfunction qAnswered(q, ans) {\n  if (q && q.type === 'multi') return normChoiceSet(ans).length > 0;\n  return ans != null && String(ans) !== '';\n}\n/* 某个选项是否处于「已选」状态（多选可多选） */\nfunction qChose(q, ans, k) {\n  if (q && q.type === 'multi') return normChoiceSet(ans).indexOf(Number(k)) >= 0;\n  return Number(ans) === Number(k);\n}\nfunction normQuestion(raw) {\n  raw = raw || {};\n  let t = 'choice';\n  if (raw.type === 'fill') t = 'fill';\n  else if (raw.type === 'multi' || raw.multiple === true || raw.multi === true) t = 'multi';\n  else if (raw.type === 'tf' || raw.type === 'judge' || raw.type === 'bool' || raw.type === 'boolean') t = 'tf';\n  const q = { type: t, q: String(raw.q || raw.question || raw.title || '').trim() };\n  if (t === 'fill') {\n    q.answer = String(raw.answer || '').trim();\n    q.keywords = (raw.keywords || []).map(k => String(k).trim()).filter(Boolean);\n  } else {\n    let opts = (raw.options || raw.choices || []).map(o => String(o).replace(/^[A-Da-d][.、)．\\s]+/, '').trim()).filter(Boolean);\n    if (t === 'tf' && opts.length < 2) opts = ['正确', '错误'];\n    q.options = opts;\n    const maxI = Math.max(0, q.options.length - 1);\n    const idxFrom = v => {\n      if (v == null || v === '') return null;\n      if (typeof v === 'number') return v;          // 已经是下标（如 answerIndexes: [0,2]）\n      const s = String(v).trim();\n      if (/^[A-Da-d]$/.test(s)) return s.toUpperCase().charCodeAt(0) - 65;\n      if (t === 'tf') {\n        if (/^(对|正确|是的|是|true|t|√|1)$/i.test(s)) return 0;\n        if (/^(错|错误|不是|否|false|f|×|0)$/i.test(s)) return 1;\n      }\n      return q.options.findIndex(o => norm(o) === norm(s));\n    };\n    if (t === 'multi') {\n      let arr = raw.answerIndexes || raw.answerIndex || raw.answer;\n      if (!Array.isArray(arr)) arr = String(arr == null ? '' : arr).split(/[,，、\\s]+/).filter(Boolean);\n      const idxs = arr.map(idxFrom).filter(v => v != null && v >= 0).map(v => clamp(v, 0, maxI));\n      q.answerIndexes = idxs.length ? Array.from(new Set(idxs)).sort((a, b) => a - b) : [0];\n      q.answerIndex = q.answerIndexes[0];\n    } else {\n      let ai = raw.answerIndex;\n      if (ai == null) ai = idxFrom(raw.answer);\n      if (typeof ai === 'string') ai = idxFrom(ai);\n      q.answerIndex = clamp(Number(ai) || 0, 0, maxI);\n    }\n  }\n  q.explain = String(raw.explain || raw.analysis || '').trim();\n  return q;\n}\nfunction allBank() { return (S.qbank || []).filter(q => q && q.q); }\nfunction qtypeOf(q) {\n  const t = q && q.type;\n  return (t === 'fill' || t === 'multi' || t === 'tf') ? t : 'choice';\n}\n/* 掌握度：做对几次算掌握（阈值可自己设） */\nfunction masteryNeed() { return clamp(Number(cfg('masteryNeed') || 3), 1, 20); }\nfunction isMastered(q) { return !!(q && (q.mastered || Number(q.right || 0) >= masteryNeed())); }\nfunction masteryText(q) {\n  if (!q) return '';\n  if (isMastered(q)) return '✅ 已掌握（做对 ' + Number(q.right || 0) + ' 次）';\n  return '做对 ' + Number(q.right || 0) + '/' + masteryNeed() + ' 次';\n}\n/* 记录一次判分结果到题库：做对 → 次数 +1 并可能标记掌握；做错 → 清零 */\nasync function bumpMastery(q, ok) {\n  if (!q || !q.q) return null;\n  const hit = allBank().find(b => norm(b.q) === norm(q.q));\n  if (!hit) return null;\n  const before = isMastered(hit);\n  if (ok) { hit.right = Number(hit.right || 0) + 1; hit.wrong = 0; hit.lastOkAt = Date.now(); }\n  else { hit.wrong = Number(hit.wrong || 0) + 1; hit.right = 0; hit.lastWrongAt = Date.now(); }\n  const now = Number(hit.right || 0) >= masteryNeed();\n  hit.mastered = now;\n  if (hit.id) await DB.update(T.QBANK, hit.id, JSON.parse(JSON.stringify(hit)));\n  if (now && !before) return { justMastered: true, q: hit };\n  return { justMastered: false, q: hit };\n}\nasync function saveQuestionsToBank(qs, meta) {\n  meta = meta || {};\n  let added = 0;\n  const seen = allBank().map(b => norm(b.q));\n  for (const q of (qs || [])) {\n    if (!q || !q.q) continue;\n    if (seen.indexOf(norm(q.q)) >= 0) continue;\n    const rec = { type: qtypeOf(q), q: q.q, explain: q.explain || '', cat: meta.cat || '综合', src: meta.src || 'ai', at: Date.now(), right: 0, wrong: 0, mastered: false };\n    if (rec.type === 'fill') { rec.answer = q.answer || ''; rec.keywords = q.keywords || []; }\n    else {\n      rec.options = q.options || [];\n      if (rec.type === 'multi') { rec.answerIndexes = (q.answerIndexes && q.answerIndexes.length) ? q.answerIndexes : [q.answerIndex]; rec.answerIndex = rec.answerIndexes[0] || 0; }\n      else rec.answerIndex = Number(q.answerIndex) || 0;\n    }\n    const r = await DB.create(T.QBANK, rec);\n    if (r) { S.qbank.push(Object.assign({ id: r.id }, rec)); seen.push(norm(q.q)); added++; }\n  }\n  return added;\n}\n/* 分类：默认「综合」，可自行增删；抽题可按分类取 */\nfunction bankCats() {\n  const set = {};\n  (cfg('bankCats') || []).forEach(c => { if (c) set[String(c)] = 1; });\n  allBank().forEach(q => { if (q.cat) set[String(q.cat)] = 1; });\n  return Object.keys(set);\n}\nfunction bankCountIn(cat) {\n  if (!cat) return allBank().length;\n  return allBank().filter(q => String(q.cat || '') === String(cat)).length;\n}\n/* 抽题：优先「没掌握」的、其次「最近没做过」的；可按分类与题型限制 */\nfunction drawFromBank(count, opts) {\n  opts = opts || {};\n  count = Math.max(1, Number(count) || 3);\n  let pool = allBank();\n  if (opts.cat) ",
  "{ const f = pool.filter(q => String(q.cat || '') === String(opts.cat)); if (f.length) pool = f; }\n  if (opts.kinds && opts.kinds.length) {\n    const f = pool.filter(q => opts.kinds.indexOf(qtypeOf(q)) >= 0);\n    if (f.length) pool = f;\n  }\n  if (opts.source && opts.source !== 'all') {\n    const f = pool.filter(q => String(q.src || '') === String(opts.source));\n    if (f.length) pool = f;\n  }\n  if (opts.focus) { const f = pool.filter(q => focusHit(q)); if (f.length) pool = f; }\n  if (opts.onlyUnmastered) {\n    const f = pool.filter(q => !isMastered(q));\n    if (f.length) pool = f;\n  }\n  const asked = cfg('askedQ') || [];\n  const fresh = pool.filter(q => asked.indexOf(q.id) < 0);\n  const poolN = (fresh.length >= count) ? fresh : pool;\n  // 未掌握的排在前面：掌握过的只在题量不够时兜底\n  const unmastered = shuffle(poolN.filter(q => !isMastered(q)).slice());\n  const mastered = shuffle(poolN.filter(q => isMastered(q)).slice());\n  const picked = unmastered.concat(mastered).slice(0, Math.min(count, poolN.length));\n  S.settings.askedQ = asked.concat(picked.map(q => q.id)).slice(-300);\n  saveSettings();\n  return picked.map(q => normQuestion(q));\n}\n/* 按占比把总数拆成若干份（用于「新题 / 错题 / 题库题」和「题型」配比）*/\nfunction mixCounts(total, mix, keys) {\n  total = Math.max(0, Math.round(Number(total) || 0));\n  const ks = (keys || Object.keys(mix || {})).filter(k => Number((mix || {})[k] || 0) > 0);\n  if (!ks.length || !total) return {};\n  const sumW = sum(ks.map(k => Number(mix[k]) || 0));\n  const out = {};\n  let used = 0;\n  ks.forEach((k, i) => {\n    if (i === ks.length - 1) { out[k] = Math.max(0, total - used); return; }\n    const n = Math.floor(total * (Number(mix[k]) || 0) / sumW);\n    out[k] = n; used += n;\n  });\n  // 四舍五入误差补到占比最大的一项\n  let rest = total - sum(ks.map(k => out[k]));\n  if (rest > 0) {\n    const top = ks.slice().sort((a, b) => (Number(mix[b]) || 0) - (Number(mix[a]) || 0))[0];\n    out[top] = (out[top] || 0) + rest;\n  }\n  return out;\n}\nfunction mixText(mix) {\n  const ks = Object.keys(mix || {}).filter(k => Number(mix[k]) > 0);\n  const total = sum(ks.map(k => Number(mix[k])));\n  if (!ks.length || !total) return '（未设置）';\n  return ks.map(k => (MIX_LABEL[k] || k) + ' ' + Math.round(Number(mix[k]) / total * 100) + '%').join(' · ');\n}\nconst MIX_LABEL = { fresh: '新题', wrong: '错题', bank: '题库题', choice: '单选', fill: '填空', multi: '多选', tf: '判断' };\n/* 统一的答题渲染：choice / tf / multi 点选，fill 输入 */\nfunction qInputHTML(qx, i, answers, actName, field) {\n  const ans = answers ? answers[i] : null;\n  if (qIsPick(qx)) {\n    const multi = qx.type === 'multi';\n    return `<div class=\"opts\">${(qx.options || []).map((o, k) => `<button class=\"opt ${qChose(qx, ans, k) ? 'on' : ''}\" data-act=\"${actName}\" data-i=\"${i}\" data-k=\"${k}\">\n      <span class=\"k\">${'ABCD'[k]}</span><span>${esc(o)}</span></button>`).join('')}</div>`\n      + (multi ? `<div class=\"tiny mt6\" style=\"color:var(--gold)\">多选题 · 可以选多项，选完一起提交</div>` : '');\n  }\n  return `<input class=\"input\" data-in=\"${field || 'ans'}.${i}\" value=\"${esc(ansOf({ answers: answers || {} }, i, field))}\" placeholder=\"写下你的答案\">`;\n}\n/* 统一的结果渲染：标出正确项与你的选择 */\nfunction qResultHTML(qx, i, answers) {\n  const ans = answers ? answers[i] : null;\n  if (qIsPick(qx)) {\n    const right = (qx.type === 'multi') ? (qx.answerIndexes || [qx.answerIndex]) : [qx.answerIndex];\n    return (qx.options || []).map((o, k) => {\n      const isRight = right.indexOf(k) >= 0;\n      const chose = qChose(qx, ans, k);\n      return `<div class=\"opt ${isRight ? 'right' : (chose ? 'wrong' : '')}\">\n        <span class=\"k\">${'ABCD'[k]}</span><span>${esc(o)}</span></div>`;\n    }).join('');\n  }\n  const myTxt = (ans == null || String(ans) === '') ? '（空）' : String(ans);\n  return `<div class=\"opt ${qx.ok ? 'right' : 'wrong'}\"><span>你的答案：${esc(myTxt)}</span></div>\n    <div class=\"opt right\" style=\"margin-top:6px\"><span>参考答案：${esc(qAnswerText(qx))}</span></div>`;\n}\n/* 答题卡题号：多选/判断也标一下题型 */\nfunction qNoText(qx, i) { return (i + 1) + '. ' + ((qx && (qx.type === 'multi' || qx.type === 'tf')) ? '【' + qTypeLabel(qx.type) + '】' : ''); }\nfunction pickByKind(pool, kind, n) {\n  if (!n) return [];\n  const f = (pool || []).filter(q => qtypeOf(q) === kind);\n  return shuffle(f.slice()).slice(0, n);\n}\nfunction pickByKindMix(pool, count, kindMix, kindKeys) {\n  count = Math.max(1, Number(count) || 1);\n  if (!kindKeys || !kindKeys.length) return shuffle((pool || []).slice()).slice(0, Math.min(count, pool.length));\n  const totalW = sum(kindKeys.map(k => Number(kindMix[k]) || 0)) || 1;\n  const out = [];\n  kindKeys.forEach(k => {\n    const n = Math.round(count * (Number(kindMix[k]) || 0) / totalW);\n    pickByKind(pool, k, n).forEach(q => { if (out.indexOf(q) < 0) out.push(q); });\n  });\n  if (out.length < count) shuffle((pool || []).slice()).forEach(q => { if (out.length < count && out.indexOf(q) < 0) out.push(q); });\n  return out.slice(0, count);\n}\n/* 统一组卷：按「新题 / 错题 / 题库题」× 「题型」两重配比凑出一份卷子\n   · 新题＝AI 现出（出不来自动用题库兜住，绝不给空卷）\n   · 错题＝错题本里还没掌握的（可按题型配比）\n   · 题库题＝题库里优先抽没掌握的\n   题目不够时会互相补位，最后去重打乱。 */\nasync function buildQuizSet(total, opts) {\n  opts = opts || {};\n  total = Math.max(1, Math.round(Number(total) || 3));\n  const srcMix = opts.srcMix || cfg('quizMixSrc') || { fresh: 1, wrong: 1, bank: 1 };\n  const kindMix = opts.kindMix || cfg('quizMixKind') || { choice: 1, fill: 1, multi: 1, tf: 1 };\n  const cat = opts.cat != null ? opts.cat : (cfg('punishCat') || '');\n  const kindKeys = Object.keys(kindMix).filter(k => Number(kindMix[k]) > 0);\n  const onlyUnmastered = opts.onlyUnmastered !== false;\n  const focusOnly = ((cfg('quizFocusMode') || 'focus') === 'focus') && focusKeys().length > 0;\n  const srcN = mixCounts(total, srcMix, ['fresh', 'wrong', 'bank']);\n  const out = [];\n  const push = arr => { (arr || []).forEach(q => { if (q && q.q) out.push(q); }); };\n  /* ① 错题（错题本里没掌握的优先） */\n  if (srcN.wrong) {\n    let pool = mistakeQs().map(m => normQuestion({\n      type: m.qType || 'choice', q: m.q, options: m.options, answerIndex: m.answerIndex,\n      answerIndexes: m.answerIndexes, answer: m.answer, keywords: m.keywords, explain: m.explain\n    }));\n    const un = pool.filter(q => !isMastered(q));\n    if (onlyUnmastered && un.length) pool = un;\n    if (focusOnly) { const f = pool.filter(q => focusHit(q)); if (f.length) pool = f; }\n    push(pickByKindMix(pool, srcN.wrong, kindMix, kindKeys));\n  }\n  /* ② 题库题 */\n  if (srcN.bank) push(drawFromBank(srcN.bank, { cat: cat, onlyUnmastered: onlyUnmastered, focus: focusOnly }));\n  /* ③ 新题：AI 现出，失败或本地模式则用题库补 */\n  if (srcN.fresh) {\n    let added = false;\n    const allowFresh = (opts.allowFresh != null) ? !!opts.allowFresh : (cfg('quizSource') !== 'local');\n    if (allowFresh || opts.forceAI) {\n      S.loading = opts.loading || 'quiz';\n      try {\n        const data = await genQuestionsAI(opts.charIds || [], srcN.fresh, {\n          purpose: opts.purpose || '用户在作答一份练习题，需要检验掌握程度',\n          context: opts.context || ('练习题' + (cat ? '，知识点分类：' + cat : '')),\n          kinds: (kindKeys.length && kindKeys.length < Q_TYPES.length) ? kindKeys : [],\n          cat: cat\n        });\n        if (data && data.qs && data.qs.length) { push(data.qs); added = true; }\n      } catch (e) { console.warn('buildQuizSet 新题失败', e); }\n      S.loading = '';\n    }\n    if (!added) push(drawFromBank(srcN.fresh, { cat: cat, onlyUnmastered: onlyUnmastered, focus: focusOnly }));\n  }\n  /* ④ 任何原因导致不够：题库兜底补足 */\n  if (out.length < total) push(drawFromBank(total - out.length, { cat: cat }));\n  /* 去重 + 打乱 */\n  const seen = {}, final = [];\n  shuffle(out.slice()).forEach(q => { const k = norm(q.q); if (seen[k]) return; seen[k] = 1; final.push(q); });\n  return final.slice(0, total);\n}\nfunction guessCat(s) {\n  const txt = (((s && s.plan) || []).map(t => t.content).join(' ') + ' ' + ((S.review && S.review.summary) || '')).toLowerCase();\n  const map = [['资料分析', ['资料', '增长率', '比重', '图表']], ['英语', ['英语', '单词', '阅读', 'english']],\n  ['语文', ['语文', '古诗', '成语', '作文']], ['数学', ['数学', '计算', '方程', '几何']],\n  ['逻辑', ['逻辑', '推理', '判断']], ['常识', ['常识', '时政', '历史']]];\n  for (const it of map) { if (it[1].some(k => txt.indexOf(k) >= 0)) return it[0]; }\n  return '';\n}\nfunction quizQs(obj) { return (obj && (obj.qs || obj.questions)) || []; }\nfunction quizMissing(qs, answers) {\n  return (qs || []).map((q, i) => i).filter(i => !qAnswered((qs || [])[i], answers ? answers[i] : null));\n}\nfunction gradeQuiz(quiz) {\n  const list = quizQs(quiz);   // 兼容两种字段名\n  quiz.qs = list; quiz.questions = list;\n  if (!quiz.answers) quiz.answers = {};\n  let right = 0;\n  list.forEach((q, i) => {\n    const ok = gradeOneQuestion(q, quiz.answers[i]);\n    q.ok = ok; if (ok) right++;\n  });\n  quiz.right = right; quiz.total = list.length;\n  quiz.rate = list.length ? right / list.length * 100 : 0;\n  return quiz;\n}\n/* 判分后统一回写题库掌握度；返回本次刚好被标记为「已掌握」的题 */\nasync function bumpMasteryAll(qs) {\n  const just = [];\n  for (const q of (qs || [])) {\n    const r = await bumpMastery(q, !!q.ok);\n    if (r && r.justMastered) just.push(r.q);\n  }\n  return just;\n}\nfunction collectFillAnswers() {\n  document.querySelectorAll('[data-in^=\"ans.\"]').forEach(el => setDraftPath(el.dataset.in, el.value));\n  document.querySelectorAll('[data-in^=\"pans.\"]').forEach(el => setDraftPath(el.dataset.in, el.value));\n}\n/* AI 出题：按题型需求分批请求（单批 ≤6 道），避免长 JSON 被截断/超时；\n   某一批失败不影响其它批，最终只要有题就算成功。 */\nasync function genQuestionsAI(charIds, count, opts) {\n  opts = opts || {};\n  count = Math.max(1, Math.round(Number(count) || 3));\n  const cid = (charIds && charIds.length) ? charIds[0] : anyCharId();\n  const wantKinds = (opts.kinds && opts.kinds.length) ? opts.kinds.slice() : [];\n  const seen = {}; allBank().forEach(b => { seen[norm(b.q)] = 1; });\n  const fresh = [];\n  let dup = 0, lastErr = '', weakness = [], advice = '';\n  const batchN = 6;\n  const batches = Math.ceil(count / batchN);\n  for (let bi = 0; bi < batches; bi++) {\n    const need = Math.min(batchN, count - fresh.length);\n    if (need <= 0) break;\n    const exist = allBank().map(b => b.q).concat(fresh.map(q => q.q)).slice(-50);\n    const avoid = exist.length ? promptText('quiz.avoid', { list: exist.map((q, i) => `${i + 1}. ${String(q).slice(0, 40)}`).join('\\n') }) : '';\n    const kindLine = wantKinds.length\n      ? '【题型要求】这一批 ' + need + ' 道题只用这些题型：' + wantKinds.map(k => qTypeLabel(k)).join('、') + '，尽量平分。'\n      : '';\n    const inst = promptText('quiz.gen', {\n      purpose: opts.purpose || '用户刚结束一段专注学习，需要检验效果',\n      context: opts.context || '（未填写）',\n      focus: focusLine(),\n      weak: weakSummary(6) + (opts.cat ? '\\n【知识点分类】本次只出「' + opts.cat + '」这一类的题。' : ''),\n      avoid: (avoid ? avoid + '\\n' : '') + kindLine,\n      rules: promptText('quiz.rules', { count: need }),\n      count: need\n    });\n    let text = '';\n    try { text = await aiGen([cid], promptTags('quiz.gen'), inst); }\n    catch (e) { lastErr = (e && e.message) || String(e); continue; }\n    const data = parseJSON(text);\n    if (!data) { lastErr = '出题结果解析失败'; continue; }\n    if (!weakness.length && data.weakness) weakness = (data.weakness || []).slice(0, 3);\n    if (!advice && data.advice) advice = String(data.advice || '').trim();\n    const arr = (data.questions || []).map(normQuestion)\n      .filter(q => q.q && (q.type === 'fill' || (q.options || []).length >= 2));\n    // 符合题型要求的排在前面，其它题型兜在后面（总比没有强）\n    const prefer = wantKinds.length ? arr.filter(q => wantKinds.indexOf(q.type) >= 0) : arr;\n    prefer.concat(arr.filter(q => prefer.indexOf(q) < 0)).forEach(q => {\n      const k = norm(q.q);\n      if (seen[k]) { dup++; return; }\n      seen[k] = 1; fresh.push(q);\n    });\n    if (fresh.length >= count) break;\n  }\n  if (!fresh.length) throw new Error(dup ? ('AI 出的 ' + dup + ' 道题都和题库重复了，请再点一次换一批') : ('模型没有给出可用的题目' + (lastErr ? '：' + lastErr : '，请重试')));\n  return { weakness: weakness, advice: advice, qs: fresh.slice(0, count) };\n}\n/* ==========================================================\n   视图 · 学习首页（v1.9.2 校验标记 F）\n   ========================================================== */\nfunction sessionsToday() { const t = dkey(); return (S.sessions || []).filter(s => s.date === t); }\nfunction focusSecOf(list) { return sum((list || []).map(x => x.totalFocusSec || 0)); }\n/* 首页第一屏 = 「现在能做什么」。其余状态卡按「紧急 → 参考」往下排 */\nfunction heroHTML(running, s) {\n  const chars = activeChars();\n  const who = chars.length ? chars.map(c => esc(c.name)).join('、') : '还没有陪伴角色';\n  return `<div class=\"card hero\">\n    <div class=\"tiny\" style=\"letter-spacing:.6px;color:#c8cffe\">${running ? '正在进行' : '现在就开始'}</div>\n    <div class=\"hero-t\">${running ? '专注进行中 · ' + (s.phase === 'break' ? '休息中' : '第 ' + s.cycle + '/' + s.cycles + ' 轮') : '开始一段专注'}</div>\n    <div class=\"tiny mt6\">${running ? '剩余 ' + fmtClock(remainSec()) + ' · ' + (s.paused ? '已暂停' : '计时中') : '陪伴：' + who}</div>\n    ${running\n      ? `<button class=\"btn primary block mt12\" style=\"min-height:50px;font-size:15px\" data-act=\"gotoView\" data-view=\"running\">回到专注</button>\n      <button class=\"btn block mt8\" data-act=\"wlApplyOpen\">🎟 临时要用别的应用（向 TA 申请）</button>`\n      : `<button class=\"btn primary block mt12\" style=\"min-height:52px;font-size:15.5px\" data-act=\"gotoSetup\">▶️ 开始一段专注</button>\n      <div class=\"row mt8\" style=\"gap:8px\">\n        <button class=\"btn grow\" data-act=\"openInvite\" data-k=\"focus\">📨 专注邀约</button>\n        <button class=\"btn sleep grow\" data-act=\"openInvite\" data-k=\"sleep\">🌙 睡眠陪伴</button>\n      </div>\n      <div class=\"row mt8\" style=\"gap:8px\">\n      </div>`}\n  </div>`;\n}\n/* 做题统计：专注校验 + 惩罚练习 + 失约写题补救，全部算进来 */\nfunction quizStat() {\n  const pick = (list, getT, getR) => {\n    const total = sum(list.map(getT)), right = sum(list.map(getR));\n    return { total: total, right: right, rate: total ? Math.round(right / total * 100) : 0 };\n  };\n  const sess = (S.sessions || []).filter(s => Number(s.quizTotal) > 0);\n  const apptQuiz = (S.appts || []).filter(a => a.remedy && a.remedy.type === 'quiz' && Number(a.remedy.total) > 0);\n  const all = pick(sess.concat(apptQuiz),\n    x => Number(x.quizTotal || (x.remedy ? x.remedy.total : 0)) || 0,\n    x => Number(x.quizScore || (x.remedy ? x.remedy.right : 0)) || 0);\n  const todaySess = sess.filter(s => s.date === dkey());\n  const todayAppt = apptQuiz.filter(a => a.remedy && dkey(new Date(a.remedy.at || a.startAt || 0)) === dkey());\n  const t = pick(todaySess.concat(todayAppt),\n    x => Number(x.quizTotal || (x.remedy ? x.remedy.total : 0)) || 0,\n    x => Number(x.quizScore || (x.remedy ? x.remedy.right : 0)) || 0);\n  return {\n    total: all.total, right: all.right, rate: all.rate,\n    tTotal: t.total, tRight: t.right, tRate: t.rate,\n    rounds: sess.length + apptQuiz.length, mist: mistakeList().length\n  };\n}\nfunction quizStatHTML() {\n  const q = quizStat();\n  const tone = q.rate >= 80 ? 'var(--teal)' : (q.rate >= 60 ? 'var(--gold)' : '#ff9aa6');\n  return `<div class=\"card\">\n    <div class=\"row between\"><h3>做题统计</h3><span class=\"tiny\">专注校验 · 惩罚练习 · 失约补救</span></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600\">${q.total}<span class=\"tiny\">题</span></div><div class=\"tiny\">累计做题</div></div>\n      <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600;color:var(--teal)\">${q.right}</div><div class=\"tiny\">答对</div></div>\n      <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600;color:${tone}\">${q.rate}%</div><div class=\"tiny\">总正确率</div></div>\n      <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600;color:${q.mist ? '#ff9aa6' : 'inherit'}\">${q.mist}</div><div class=\"tiny\">错题本</div></div>\n    </div>\n    <div class=\"bar mt10\"><i style=\"width:${q.rate}%\"></i></div>\n    <div class=\"tiny mt6\">${q.total ? '今天做了 ' + q.tTotal + ' 题，答对 ' + q.tRight + '（' + q.tRate + '%）· 共 ' + q.rounds + ' 次答题记录' : '还没有答题记录 —— 专注结束走一次校验就会开始统计。'}</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"checks\">✅ 校验记录</button>\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"mistakes\">📕 错题本</button></div>\n  </div>`;\n}\nVIEWS.home = function () {\n  const s = S.session;\n  const running = s && s.status === 'running';\n  const today = sessionsToday();\n  const mins = Math.round(focusSecOf(today) / 60);\n  const rounds = sum(today.map(x => x.cycle || 0));\n  const vio = sum(today.map(x => (x.violations || []).filter(v => !v.excused).length));\n  const pend = pendingPunish(), rews = pendingRewards(), chars = activeChars();\n  const plan = running ? s.plan : (cfg('lastPlan') || []);\n  const doneN = plan.filter(t => t.done).length;\n  return `\n  ${heroHTML(running, s)}\n  ${(function () {\n      const ms = (S.appts || []).filter(x => x.needEssay && x.status === 'missed');\n      if (!ms.length) return '';\n      return `<div class=\"card\" style=\"border-color:rgba(255,123,138,.55);background:linear-gradient(160deg,rgba(255,123,138,.16),rgba(255,255,255,.03))\">\n      <div class=\"row between\"><div class=\"grow\"><h3 style=\"color:#ff9aa6\">💔 有 ${ms.length} 次失约说明没写</h3>\n        <div class=\"sub\">${esc(ms[0].task || '')} · ${esc(apptTimeText(ms[0]))} —— 原因分析和保证书还得补上，TA 记着这件事。</div></div>\n        <button class=\"btn warn sm\" data-act=\"missOpen\" data-id=\"${esc(ms[0].id)}\">去写</button></div></div>`;\n    })()}\n  ${(function () {\n      const pends = (S.sessions || []).filter(x => x.status === 'review').sort((a, b) => (b.startAt || 0) - (a.startAt || 0));\n      const pend = pends[0];\n      if (!pend || running) return '';\n      return `<div class=\"card tight\" style=\"border-color:rgba(124,140,255,.5)\">\n      <div class=\"row between\"><div class=\"grow\"><div class=\"tiny\">📝 有 ${pends.length} 段专注还没校验</div>\n        <div style=\"font-size:14px\">${esc(pend.taskName || ((pend.plan || []).map(t => t.content).join('、') || '（未记录任务）'))}</div>\n        <div class=\"tiny mt6\">${esc(pend.date || '')} ${pend.startAt ? hm(pend.startAt) : ''} · 第 ${pend.cycle || 1}/${pend.cycles || 1} 轮 · 校验完才计入有效</div></div>\n        <button class=\"btn primary sm\" data-act=\"gotoView\" data-view=\"review\">去校验</button></div></div>`;\n    })()}\n  ${todosHTML()}\n  ${invitesHTML()}\n  ${pend.length ? `<div class=\"card glow\" style=\"border-color:rgba(255,123,138,.5)\"><div class=\"row between\">\n    <div class=\"grow\"><h3 style=\"color:#ff9aa6\">⚠️ 有 ${pend.length} 项惩罚未完成</h3>\n    <div class=\"sub\">${esc(pend[0].title)} · 完成后才解除限制</div></div>\n    <button class=\"btn warn sm\" data-act=\"openLock\">去执行</button></div></div>` : ''}\n  ${rews.length ? `<div class=\"card\" style=\"border-color:rgba(255,201,120,.45);background:linear-gradient(160deg,rgba(255,201,120,.12),rgba(255,255,255,.03))\">\n    <div class=\"row between\"><div class=\"grow\"><h3 style=\"color:var(--gold)\">🎁 ${esc(charName(rews[0].charId))} 要给你一份奖励</h3>\n    <div class=\"sub\">${esc(rews[0].want || '')}${rews.length > 1 ? ' 等 ' + rews.length + ' 份' : ''} · 去聊天室让 TA 亲手交给你；已经在聊天室领到了就点进去按「TA 已经给我了」同步</div></div>\n    <button class=\"btn sm primary\" data-act=\"gotoView\" data-view=\"rewards\">去看看</button></div></div>` : ''}\n  ${!S.chars.length ? `<div class=\"card\"><h3>先创建 / 选择陪伴角色</h3>\n    <div class=\"sub\">陪伴、答疑、出题、惩罚都需要角色。请先在小手机的聊天 APP 里创建角色。</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"roles\">选择陪伴角色</button></div>` : ''}\n  ${(S.appts || []).filter(a => a.status === 'pending').length ? (function () {\n        const a = S.appts.filter(x => x.status === 'pending').sort((x, y) => x.startAt - y.startAt)[0];\n        return `<div class=\"card\" style=\"border-color:rgba(124,140,255,.45)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>🗓 约好的专注</h3>\n      <div class=\"sub\">${esc(a.task)} · ${Number(a.minutes) || 0} 分钟 · ${esc(charName((a.charIds || [])[0]))} 监督</div>\n      <div class=\"tiny mt6\" data-cd=\"${esc(a.id)}\">${apptCountdownText(a)}</div>\n      <div class=\"tiny mt6\">到点前 TA 会来催你；连着催 ${apptMaxNudge()} 次没开始就开罚</div></div>\n      <button class=\"btn primary sm\" data-act=\"apptStart\" data-id=\"${esc(a.id)}\">现在开始</button></div></div>`;\n      })() : ''}\n  ${quizStatHTML()}\n  <div class=\"sec\">今天</div>\n  <div class=\"card tight\"><div class=\"row\" style=\"gap:0\">\n    <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600\">${mins}<span class=\"tiny\">分</span></div><div class=\"tiny\">今日专注</div></div>\n    <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600\">${rounds}<span class=\"tiny\">轮</span></div><div class=\"tiny\">完成轮次</div></div>\n    <div class=\"grow center\"><div style=\"font-size:20px;font-weight:600;color:${vio ? '#ff9aa6' : 'inherit'}\">${vio}</div><div class=\"tiny\">今日违规</div></div>\n  </div></div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>${running ? '本轮任务' : '下次要做的任务'}</h3>\n      <span class=\"tiny\">${plan.length ? doneN + '/' + plan.length : '未设置'}</span></div>\n    ${plan.length ? `<div class=\"bar mt6 ${doneN < plan.length ? 'warn' : ''}\"><i style=\"width:${doneN / plan.length * 100}%\"></i></div>` : ''}\n    <div class=\"mt10\">${plan.length ? plan.map((t, i) => `<div class=\"todo ${t.done ? 'done' : ''}\">\n      <button class=\"ck ${t.done ? 'on' : ''}\" data-act=\"todoToggle\" data-i=\"${i}\">✓</button>\n      <div class=\"tx\">${esc(t.content)}<div class=\"meta\">${t.est ? '预估 ' + t.est + ' 分钟' : '未填预估'}</div></div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:12px\">还没有任务</div>`}</div>\n    <button class=\"btn block ghost sm mt6\" data-act=\"gotoSetup\">${plan.length ? '编辑任务 / 重新开始' : '添加任务'}</button>\n    ${!running && plan.length ? `<div class=\"tiny mt10\">提示：未开倒计时就勾选任务会被判定为「未计时开始任务」违规。</div>` : ''}\n  </div>\n  ${(function () {\n      const g = activeGoal();\n      if (!g) return '';\n      const d = goalDays(g);\n      return `<div class=\"card mt14\" style=\"border-color:rgba(94,234,212,.35)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>🎯 ${esc(g.name)}</h3>\n      <div class=\"tiny\">${esc(goalPhase(d))} · ${esc(g.date)}</div></div>\n      <div style=\"text-align:right\"><div style=\"font-size:26px;font-weight:300;color:var(--teal)\">${Math.max(0, d)}</div><div class=\"tiny\">天后</div></div></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"goals\">管理目标</button>\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"periodrep\">看这周报告</button></div></div>`;\n    })()}\n  ${(function () {\n      const c = (activeChars() || [])[0];\n      if (!c) return '';\n      const w = wishOf(c.id);\n      if (!w) return `<div class=\"card tight\"><div class=\"row between\">\n      <div class=\"grow\"><div class=\"tiny\">${esc(c.name)} 心底的事</div>\n      <div style=\"font-size:14.5px\">他还没说出口</div></div>\n      <button class=\"btn sm ghost\" data-act=\"wishGen\" data-id=\"${esc(c.id)}\">让他说出来</button></div>\n      <div class=\"tiny mt6\">TA 心里有一件一直想要的事，只有你陪他一起攒够专注时间才会实现。让他自己说出来，或你替他写一件。</div></div>`;\n      const p = wishGain(w), need = wishNeedOf(w), rd = wishReady(w);\n      return `<div class=\"card tight\"><div class=\"row between\">\n      <div class=\"grow\"><div class=\"tiny\">${esc(c.name)} 心底的事</div>\n      <div style=\"font-size:14.5px\">${esc(w.text)}</div></div>\n      <button class=\"btn sm ${rd ? 'primary' : 'ghost'}\" data-act=\"${rd ? 'wishFinish' : 'gotoView'}\" data-id=\"${esc(c.id)}\" data-view=\"bond\">${rd ? '让它实现' : '明细'}</button></div>\n      <div class=\"bar mt8\"><i style=\"width:${wishPct(w)}%\"></i></div>\n      <div class=\"tiny mt6\">${rd ? '攒够了 ' + wishMinText(need) + '，去让它实现' : '你们一起攒了 ' + p + ' / ' + need + ' 分钟 · 还差 ' + wishMinText(wishLeftMin(w))}</div>\n      <div class=\"tiny mt6\" style=\"color:var(--dim2)\">只有通过考核的专注会推进它；进度只增不减，不会倒退。</div></div>`;\n    })()}\n  <div class=\"card tight\"><div class=\"row between\">\n    <div class=\"grow\"><div class=\"tiny\">专注币</div>\n      <div style=\"font-size:14.5px\">🪙 ${coinBal()} 点${(Number(cfg('freePass')) || 0) ? ' · 免罚卡 ' + (Number(cfg('freePass')) || 0) + ' 张' : ''}</div></div>\n    <button class=\"btn sm ghost\" data-act=\"gotoView\" data-view=\"coin\">去兑换</button></div>\n    <div class=\"tiny mt6\">通过考核的专注按分钟折算成币，可以换免罚卡、专属壁纸、或者让 TA 兑现一个愿望。</div></div>\n  ${notesBottleLine()}\n  <div class=\"card\"><h3>去哪找什么</h3>\n    <div class=\"tiny mt6\">同类功能已经收到一个地方了 —— 点进去页顶有标签切换，不用再来回找。</div>\n    <div class=\"hubgrid\">\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"plan\">\n        <span class=\"hi\">🗓</span><span class=\"hn\">计划与邀请</span>\n        <span class=\"hd\">预约专注 ${(S.appts || []).filter(a => a.status === 'pending').length} · 待办 ${(S.todos || []).filter(t => !t.done).length} · TA 的邀请 ${(S.invites || []).filter(i => i.status === 'new').length}</span></button>\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"learn\">\n        <span class=\"hi\">📕</span><span class=\"hn\">学习档案</span>\n        <span class=\"hd\">错题本 ${mistakeList().length} · 题库 ${allBank().length} · 私密记忆</span></button>\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"motiv\">\n        <span class=\"hi\">💞</span><span class=\"hn\">激励中心</span>\n        <span class=\"hd\">心愿 ${wishPct(wishOf((activeChars() || [])[0] ? (activeChars() || [])[0].id : ''))}% · 专注币 ${coinBal()} · 目标 ${activeGoal() ? Math.max(0, goalDays(activeGoal())) + ' 天' : '未设'}</span></button>\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"insight\">\n        <span class=\"hi\">📈</span><span class=\"hn\">报告与趋势</span>\n        <span class=\"hd\">学习报告 · 专注趋势 · 打卡日历</span></button>\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"prize\">\n        <span class=\"hi\">🎁</span><span class=\"hn\">奖励与账本</span>\n        <span class=\"hd\">奖励中心${rews.length ? ' ' + rews.length + ' 待领' : ''} · 礼物图鉴 · 账本</span></button>\n      <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"content\">\n        <span class=\"hi\">🖼</span><span class=\"hn\">内容库</span>\n        <span class=\"hd\">壁纸 ${(S.album || []).length} · 生成记录 ${(S.gen || []).length} · 星星瓶 ${noteAll().length} · 收藏 ${(S.fav || []).filter(x => x.kind !== 'folder').length}</span></button>\n    </div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"me\">⚙️ 设置与数据</button>\n    </div>\n  </div>`;\n};\n/* ==========================================================\n   视图 · 专注设置 / 角色管理\n   ========================================================== */\n/* ---------- 番茄模板：把这套时长/轮数/校验时机存下来，下次一键套用 ---------- */\nfunction fpList() { return (cfg('focusPresets') || []).slice(); }\nfunction fpText(p) {\n  if (!p) return '';\n  return '专注 ' + (Number(p.focusMin) || 25) + ' 分 · 休息 ' + (Number(p.breakMin) || 5) + ' 分 · '\n    + (Number(p.cycles) || 1) + ' 轮 · ' + (p.reviewEvery === 'session' ? '整段结束校验' : '每轮校验')\n    + ((p.plan || []).length ? ' · 带 ' + p.plan.length + ' 条任务' : '');\n}\nfunction fpDefaultName(d) {\n  return (Number(d.focusMin) || 25) + '+' + (Number(d.breakMin) || 5) + ' ×' + (Number(d.cycles) || 1);\n}\nfunction fpShow() { if (modalStack.length) { closeAllSheets(); ACTIONS.fpManage(); } else render(); }\nfunction initDraft() {\n  const st = S.settings;\n  const plan = ((st.lastPlan && st.lastPlan.length) ? st.lastPlan : [{ content: '', est: '' }])\n    .map(t => ({ content: t.content || '', est: t.est || '' }));\n  S.draft = {\n    charIds: (st.charIds || []).slice(), focusMin: st.focusMin || 25, breakMin: st.breakMin || 5,\n    cycles: st.cycles || 4, reviewEvery: st.reviewEvery || 'focus', plan: plan,\n    fpSel: (S.draft && S.draft.fpSel) || ''\n  };\n}\nVIEWS.setup = function () {\n  const d = S.draft.plan ? S.draft : (initDraft(), S.draft);\n  const sel = d.charIds || [], wl = cfg('whitelist') || [], lib = cfg('punishLib') || [], fps = fpList();\n  const fpSel = fps.filter(p => String(p.id) === String(S.draft.fpSel))[0] || null;\n  return `\n  <div class=\"card\">\n    <div class=\"row between\"><h3>陪伴角色</h3><span class=\"row\" style=\"gap:6px\">\n      <button class=\"btn sm ghost\" data-act=\"reloadChars\">🔄</button>\n      <button class=\"btn sm\" data-act=\"randomChar\">🎲 随机抽取</button><button class=\"btn sm ghost\" data-act=\"reloadChars\">🔄 刷新头像</button></span></div>\n    <div class=\"sub\">可多选。多选时角色会轮流鼓励你、各自汇报自己的任务进度。选完当场保存，首页跟着更新。</div>\n    <div class=\"chips mt10\">${S.chars.length ? S.chars.map(c => `<button class=\"chip ${sel.indexOf(c.id) >= 0 ? 'on' : ''}\" data-act=\"toggleChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('')\n      : `<div class=\"empty\" style=\"padding:8px\">还没有角色可用</div>`}</div>\n    ${sel.length ? `<div class=\"row wrap mt10\" style=\"gap:8px\">${sel.map(id => { const c = charById(id); return c ? charAvatar(c) : ''; }).join('')}</div>` : ''}\n  </div>\n  <div class=\"card\"><div class=\"row between\"><h3>🔒 锁机挡位（本次专注）</h3><span class=\"tiny\">默认：${({off:'关闭',L1:'L1 提醒',L2:'L2 看守',L3:'L3 死锁'})[cfg('focusLevel') || 'off']}</span></div>\n    <div class=\"sub\">给这一场专注单独选一个挡位；不选就用「我的 → 锁机」的全局挡。</div>\n    <div class=\"chips mt8\">\n      <button class=\"chip ${S.draft.assistForSession == null ? 'on' : ''}\" data-act=\"assistSessionPick\" data-v=\"\">默认（${({off:'关',L1:'L1',L2:'L2',L3:'L3'})[cfg('focusLevel') || 'off']}）</button>\n      <button class=\"chip ${S.draft.assistForSession === 'off' ? 'on' : ''}\" data-act=\"assistSessionPick\" data-v=\"off\">⛔ 关</button>\n      <button class=\"chip ${S.draft.assistForSession === 'L1' ? 'on' : ''}\" data-act=\"assistSessionPick\" data-v=\"L1\">🛡 L1</button>\n      <button class=\"chip ${S.draft.assistForSession === 'L2' ? 'on' : ''}\" data-act=\"assistSessionPick\" data-v=\"L2\">🛰 L2</button>\n      <button class=\"chip ${S.draft.assistForSession === 'L3' ? 'on' : ''}\" data-act=\"assistSessionPick\" data-v=\"L3\">⚑ L3</button>\n    </div>\n    <div class=\"tiny mt8\">L1 勿扰+离开通知 · L2 看守锁（白名单外应用带回）· L3 在 L2 上加承诺（离开/失约自动开罚）。L2/L3 需新版 APK。</div></div>\n  <div class=\"card\">\n    <h3>番茄设置（数字都可以自己填）</h3>\n    <div class=\"row between mt8\"><span class=\"tiny\">🍅 我的模板 · 点一下就套用</span>\n      <button class=\"btn sm ghost\" data-act=\"fpSave\">💾 存成模板</button></div>\n    <div class=\"chips mt6\">\n      ${fps.length ? fps.map(p => `<button class=\"chip ${String(fpSel && fpSel.id) === String(p.id) ? 'on' : ''}\" data-act=\"fpUse\" data-id=\"${esc(p.id)}\">${esc(p.name)}</button>`).join('')\n      : `<span class=\"tiny\">还没有模板 —— 把下面的数字调好，点「存成模板」，下次一键套回来。</span>`}\n      ${fps.length ? `<button class=\"chip\" data-act=\"fpManage\">⚙️ 管理</button>` : ''}\n    </div>\n    ${fpSel ? `<div class=\"tiny mt8\" style=\"background:var(--card2);border-radius:10px;padding:10px;line-height:1.7\">\n      已套用「${esc(fpSel.name)}」：${esc(fpText(fpSel))}\n      ${(fpSel.plan || []).length ? `<button class=\"btn sm ghost block mt6\" data-act=\"fpUsePlan\" data-id=\"${esc(fpSel.id)}\">把模板里的 ${fpSel.plan.length} 条任务也套上</button>` : ''}\n      <button class=\"btn sm ghost block mt6\" data-act=\"fpDel\" data-id=\"${esc(fpSel.id)}\">删除这个模板</button></div>` : ''}\n    <div class=\"hr\"></div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">专注时长（分钟）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"focusMin\" data-num=\"1\" value=\"${d.focusMin}\"></div>\n      <div class=\"grow\"><label class=\"fl\">休息时长（分钟）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"breakMin\" data-num=\"1\" value=\"${d.breakMin}\"></div>\n      <div class=\"grow\"><label class=\"fl\">循环轮数</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"cycles\" data-num=\"1\" value=\"${d.cycles}\"></div>\n    </div>\n    <label class=\"fl\">校验时机</label>\n    <div class=\"chips\">\n      <button class=\"chip ${d.reviewEvery === 'focus' ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"reviewEvery\" data-v=\"focus\">每轮校验</button>\n      <button class=\"chip ${d.reviewEvery === 'session' ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"reviewEvery\" data-v=\"session\">整段结束校验</button>\n    </div>\n    <label class=\"fl\">角色提醒的语音形式</label>\n    <div class=\"chips\">${VOICE_MODES.map(([k, n]) => `<button class=\"chip ${(cfg('voiceMode') || 'cue') === k ? 'on' : ''}\" data-act=\"setVoiceMode\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <div class=\"tiny mt6\">语音需要在小手机「设置 → 语音」里配好语音服务。</div>\n  </div>\n  <div class=\"card\">\n    <h3>壁纸样式</h3>\n    <div class=\"sub\">专注中「先攒一张、完成一个任务解锁一张」的壁纸，按哪种画法生成。</div>\n    <div class=\"chips mt8\">${WALL_STYLES.map(([k, n]) => `<button class=\"chip ${(cfg('wallStyle') || 'gaze') === k ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"wallStyle\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <div class=\"tiny mt6\">${esc((WALL_STYLES.filter(x => x[0] === (cfg('wallStyle') || 'gaze'))[0] || WALL_STYLES[0])[2])}</div>\n    <div class=\"tiny mt6\">三套提示词都能在「我的 → 提示词与台词 → 生图」里逐条改；选「三种轮换」则每张换一种。</div>\n  </div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>任务预设</h3><span class=\"tiny\">内容 + 预估完成时间</span></div>\n    <div class=\"mt10\">${(d.plan || []).map((t, i) => `<div class=\"row\" style=\"gap:7px;margin-bottom:8px\">\n      <input class=\"input grow\" data-in=\"plan.${i}.content\" value=\"${esc(t.content)}\" placeholder=\"任务内容，如：资料分析 30 题\">\n      <input class=\"input\" style=\"width:70px;flex:0 0 70px\" type=\"number\" inputmode=\"numeric\" data-in=\"plan.${i}.est\" data-num=\"1\" value=\"${t.est || ''}\" placeholder=\"分钟\">\n      <button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"planDel\" data-i=\"${i}\">✕</button></div>`).join('')}</div>\n    <button class=\"btn block ghost sm\" data-act=\"planAdd\">＋ 添加一条任务</button>\n    <button class=\"btn block ghost sm mt6\" data-act=\"planFromTodos\">📝 从 TA 记的待办里选</button>\n  </div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>监督与惩罚</h3>\n      <button class=\"btn sm ${cfg('punishEnabled') ? 'warn' : 'ghost'}\" data-act=\"toggleSetting\" data-k=\"punishEnabled\">${cfg('punishEnabled') ? '惩罚模式已开 · 点此只记录' : '仅记录不罚 · 点此开启'}</button></div>\n    <button class=\"btn sm block mt10\" data-act=\"quizMixOpen\">⚙️ 出题配比与题库分类（惩罚 / 校验共用）</button>\n    <div class=\"sub\">违规场景：中途离开专注页、任务超时未完成、未开倒计时直接开始任务、考核未通过、预约专注没开始。</div>\n    <div class=\"chips mt8\">\n      <button class=\"chip ${cfg('punishTrigger').leave ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"leave\">中途离开触发</button>\n      <button class=\"chip ${cfg('punishTrigger').timeout ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"timeout\">超时未完成触发</button>\n      <button class=\"chip ${cfg('punishTrigger').untimed ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"untimed\">未计时开始触发</button>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">超时多少秒没确认就自动扣款（0 = 立刻执行）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.punishAutoSec\" data-num=\"1\" value=\"${Number(cfg('punishAutoSec') != null ? cfg('punishAutoSec') : 300)}\"></div>\n    </div>\n    <div class=\"tiny mt6\">抽到「转账」或「购买礼物」的惩罚会先进锁定页，让你自己选：<b>直接扣款</b> / <b>用完成一件事补救</b> / <b>再约一段专注补救</b>（后两条都免掉扣款）。<br>\n    超过上面设定的秒数你还没确认，才会自动扣款 —— 不会不打招呼就划走你的钱。答题 / 抄写 / 反思 / 打卡这几类必须你自己做，无法自动。</div>\n    <div class=\"hr\"></div>\n    <div class=\"row between\"><span class=\"tiny\">惩罚库（触发时从启用项里抽一项）</span>\n      <button class=\"btn sm ghost\" data-act=\"editPunishItem\">＋ 添加</button></div>\n    <div class=\"mt6\">${lib.length ? lib.map(p => `<div class=\"item\" style=\"padding:8px 0\">\n      <div class=\"ic\">${PUNISH_ICON[p.kind] || '⚙️'}</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${esc(p.title)} <span class=\"tiny\">${esc(punKindLabel(p.kind))}${p.enabled ? '' : ' · 已停用'}</span></div>\n      <div class=\"tiny\">${punSummary(p)}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"togglePunishItem\" data-id=\"${esc(p.id)}\">${p.enabled ? '停用' : '启用'}</button>\n      <button class=\"btn sm ghost\" data-act=\"editPunishItem\" data-id=\"${esc(p.id)}\">改</button></div>`).join('')\n      : `<div class=\"tiny\">惩罚库是空的 —— 加一项，否则违规只会被记录。</div>`}</div>\n    <div class=\"tiny mt6\">任务完成度低会加量 ×1.5、全清减量 ×0.5；每项的金额 / 题量 / 字数 / 间隔都能在弹窗里改。</div>\n    <div class=\"hr\"></div>\n    <div class=\"row between\"><span class=\"tiny\">白名单应用（专注中离开去看它，可申诉豁免，每次最多 3 次）</span>\n      <button class=\"btn sm ghost\" data-act=\"addWhite\">＋ 添加</button></div>\n    <div class=\"chips mt6\">${wl.length ? wl.map((x, i) => `<button class=\"chip\" data-act=\"delWhiteAsk\" data-i=\"${i}\">${esc(x.name)} ✕</button>`).join('')\n      : `<span class=\"tiny\">未设置白名单 —— 专注中离开一律按违规处理。</span>`}</div>\n  </div>\n  <button class=\"btn primary block\" style=\"min-height:52px;font-size:15px\" data-act=\"startFocus\">开始专注</button>\n  <div class=\"tiny center mt10\">开启后请留在本页：切后台、划掉 APP 都会按离开计时。</div>`;\n};\nVIEWS.roles = function () {\n  const sel = cfg('charIds') || [];\n  return `<div class=\"card\"><h3>选择陪伴角色</h3>\n    <div class=\"sub\">可多选，也可以随机。选择会保存为默认陪伴阵容。</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"randomCharSaved\">🎲 随机抽一位</button>\n    <button class=\"btn sm grow\" data-act=\"clearChars\">清空</button></div></div>\n  ${S.chars.length ? S.chars.map(c => `<div class=\"card tight\">\n    <div class=\"row\">${charAvatar(c, 'avatar lg')}\n      <div class=\"grow\" style=\"min-width:0\"><div class=\"row between\"><b>${esc(c.name)}</b>\n        <span class=\"pill ${sel.indexOf(c.id) >= 0 ? 'ok' : ''}\">${sel.indexOf(c.id) >= 0 ? '陪伴中' : '未选'}</span></div>\n        <div class=\"tiny ellip\">${esc(String(c.persona || c.description || c.prompt || '暂无简介').slice(0, 60))}</div></div></div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow ${sel.indexOf(c.id) >= 0 ? '' : 'primary'}\" data-act=\"toggleSavedChar\" data-id=\"${esc(c.id)}\">${sel.indexOf(c.id) >= 0 ? '取消陪伴' : '选为陪伴'}</button>\n      <button class=\"btn sm ghost\" data-act=\"testVoice\" data-id=\"${esc(c.id)}\">试听声音</button></div></div>`).join('')\n      : `<div class=\"empty\">还没有角色。请先在小手机聊天 APP 里创建角色。</div>`}`;\n};\n/* ==========================================================\n   视图 · 专注中\n   ========================================================== */\nfunction currentTaskIdx(s) { return (s.plan || []).findIndex(t => !t.done); }\nfunction trackTaskTimer(s) {\n  const i = currentTaskIdx(s);\n  if (i !== s.curTaskIdx) { s.curTaskIdx = i; s.curTaskSince = Date.now(); s.taskAsked = false; }\n  if (!s.curTaskSince) s.curTaskSince = Date.now();\n}\nfunction checkTaskDue(s) {\n  const i = s.curTaskIdx;\n  if (i == null || i < 0 || s.taskAsked) return;\n  const t = s.plan[i];\n  if (!t || !Number(t.est)) return;\n  if (Date.now() - (s.curTaskSince || s.startAt) >= Number(t.est) * 60000) { s.taskAsked = true; askTaskOnTime(i); }\n}\nfunction askTaskOnTime(i) {\n  const s = S.session; if (!s || !s.plan[i]) return;\n  const t = s.plan[i];\n  const w = openSheet(`<h3>⏱ 预估时间到了</h3>\n    <div class=\"sub\">「${esc(t.content)}」预估 ${t.est} 分钟，现在按时完成了吗？</div>\n    <div class=\"row mt14\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-td=\"no\">还没完成</button>\n    <button class=\"btn primary grow\" data-td=\"yes\">按时完成了</button></div>`);\n  w.addEventListener('click', async e => {\n    const b = e.target.closest('[data-td]'); if (!b) return;\n    closeSheet(w);\n    if (b.dataset.td === 'yes') {\n      s.plan[i].done = true; s.plan[i].onTime = true;\n      pushMsg(s, 'sys', `✓ 按时完成：${s.plan[i].content}`);\n      await saveSession(true); render();\n      onTaskDone(s, s.plan[i].content);      // 完成一个任务 → 解锁一张 + 生成下一张\n      roleSay(s, 'cheer');\n    } else askDelay(i);\n  });\n}\nfunction askDelay(i) {\n  const s = S.session; if (!s || !s.plan[i]) return;\n  const w = openSheet(`<h3>还没完成</h3><div class=\"sub\">给自己补一点时间，还是按规则记为「超时未完成」？</div>\n    <div class=\"chips mt10\">${[5, 10, 20, 30].map(m => `<button class=\"chip\" data-dl=\"${m}\">再给 ${m} 分钟</button>`).join('')}</div>\n    <button class=\"btn warn block mt14\" data-dl=\"fail\">记为超时未完成</button>`);\n  w.addEventListener('click', async e => {\n    const b = e.target.closest('[data-dl]'); if (!b) return;\n    closeSheet(w);\n    const v = b.dataset.dl;\n    if (v === 'fail') {\n      s.violations = s.violations || [];\n      s.violations.push({ type: 'timeout', at: Date.now(), detail: `任务「${s.plan[i].content}」超时未完成`, excused: false });\n      s.taskAsked = false;\n      bumpSelfTasks(s, -10, '「' + s.plan[i].content + '」超时没完成');\n      await saveSession(true); render();\n      await coinDeductFor('任务超时未完成', 'timeout');\n      if (cfg('punishEnabled') && cfg('punishTrigger').timeout) await triggerPunish('任务超时未完成', {});\n      else pushMsg(s, 'sys', '⚠️ 已记录：任务超时未完成');\n    } else {\n      s.plan[i].est = Number(s.plan[i].est || 0) + Number(v);\n      s.curTaskSince = Date.now(); s.taskAsked = false;\n      pushMsg(s, 'sys', `⌛ 任务延长 ${v} 分钟（现预估 ${s.plan[i].est} 分钟）`);\n      await saveSession(true); render();\n    }\n  });\n}\n/* 延长任务预估之后：问一句「本次专注的倒计时要不要也一起延长」\n   · 选延长 → focusMin 与 phaseEndsAt 同步 +N 分钟（两者一起动，进度环与时长结算才都对）\n   · 选不延长 → 倒计时照原样走，只是这个任务的时间会更紧\n   注意：必须放在顶层。早前它被插进了别的函数体里，调用时就会报 askExtendFocus is not defined */\nasync function askExtendFocus(s, minutes) {\n  if (!s || s.status !== 'running' || s.phase !== 'focus') return;\n  if (typeof confirmBox !== 'function') return;   // 宿主没有弹窗组件就不问，不影响「延长任务」主流程\n  minutes = Math.round(Number(minutes) || 0);\n  if (minutes <= 0) return;                        // 只问「延长」；减时无需问总时长\n  const idx = (typeof currentTaskIdx === 'function') ? currentTaskIdx(s) : -1;\n  const name = (idx >= 0 && s.plan && s.plan[idx] && s.plan[idx].content) || '这个任务';\n  const left = Math.max(0, Math.round(remainSec() / 60));\n  const total = Number(s.focusMin || 25);\n  const ok = await confirmBox('专注总时长也延长吗？',\n    '「' + name + '」的时间已经往后加了 ' + minutes + ' 分钟。\\n\\n'\n    + '要不要把本次专注的倒计时也一起延长 ' + minutes + ' 分钟？\\n'\n    + '· 延长：总时长 ' + total + ' → ' + (total + minutes) + ' 分钟，还剩约 ' + (left + minutes) + ' 分钟\\n'\n    + '· 不延长：倒计时照原样走，只是这个任务的时间会更紧',\n    '延长 ' + minutes + ' 分钟');\n  if (!ok) { toast('总时长不变，倒计时照原样走'); return; }\n  s.focusMin = total + minutes;\n  s.lockUntil = sessionEndAt(s);\n  syncLockNow();\n  s.phaseEndsAt = Number(s.phaseEndsAt || Date.now()) + minutes * 60000;\n  pushMsg(s, 'sys', `本次专注总时长延长 ${minutes} 分钟（现 ${s.focusMin} 分钟，还剩约 ${Math.round(remainSec() / 60)} 分钟）`);\n  S.lastTick = Date.now();\n  await saveSession(true);\n  toast('已把总时长延长 ' + minutes + ' 分钟');\n  render();\n}\n/* ---------- 聊天框里的语音：直接复听 / 循环 ----------\n   角色说过的每一句都连音频一起留档了（见 voiceSay）。这里做的是把它挂回聊天气泡：\n   · 优先用消息自己带的 ref（刚说完就被记下的那种）\n   · 没有就用文字去语音留档里找同一位角色说过的一模一样的一句\n   这样重开 APP、翻旧消息时也照样能复听，不用重新合成。 */\nfunction findMsgByAt(at) {\n  const key = String(at || '');\n  if (!key) return null;\n  const a = (S.session && S.session.msgs) || [];\n  const b = (S.sleep && S.sleep.chat) || [];\n  return a.filter(m => String(m.at) === key)[0] || b.filter(m => String(m.at) === key)[0] || null;\n}\nfunction msgVoiceRef(m) {\n  m = m || {};\n  if (m.role !== 'char' || !m.text) return '';\n  if (m.ref) return String(m.ref);\n  const t = String(m.text);\n  const hit = voiceLogs().filter(x => x && x.ref && String(x.out || '') === t\n    && (!m.charId || !(x.charIds || []).length || String(x.charIds[0]) === String(m.charId)))[0];\n  return hit ? String(hit.ref) : '';\n}\nfunction msgVoiceBarHTML(m) {\n  const ref = msgVoiceRef(m);\n  if (!ref) return '';\n  const on = S.voiceLoop && String(S.voiceLoop.msgAt) === String(m.at);\n  return `<div class=\"vbar\" data-vbar=\"${esc(m.at)}\">\n    <button data-act=\"msgReplay\" data-at=\"${esc(m.at)}\">🔊 复听</button>\n    <button class=\"${on ? 'on' : ''}\" data-act=\"msgLoop\" data-at=\"${esc(m.at)}\">${on ? '⏹ 停止循环' : '🔁 循环这句'}</button></div>`;\n}\n/* 刚合成出来的音频立刻挂回那条消息，按钮当场出现，不用等下一次重绘 */\nfunction attachRefToMsg(charId, text, ref) {\n  if (!ref || !text) return false;\n  const try2 = arr => {\n    const list = (arr || []).filter(m => m && m.role === 'char' && !m.ref\n      && String(m.text) === String(text) && (!charId || String(m.charId) === String(charId)));\n    const m = list[list.length - 1];      // 只挂最新那一条：别给历史里同文的旧消息误挂\n    if (m) { m.ref = ref; return true; }\n    return false;\n  };\n  return try2(S.session && S.session.msgs) || try2(S.sleep && S.sleep.chat);\n}\nfunction refreshMsgVoice() {\n  try {\n    document.querySelectorAll('[data-mat]').forEach(el => {\n      const m = findMsgByAt(el.getAttribute('data-mat'));\n      if (!m) return;\n      const want = msgVoiceBarHTML(m);\n      const bar = el.querySelector('[data-vbar]');\n      if (!want) { if (bar) bar.remove(); return; }\n      if (bar) bar.outerHTML = want;                 // 已有按钮：只更新「复听 / 停止循环」的状态\n      else el.insertAdjacentHTML('beforeend', want); // 刚拿到音频：当场把按钮补上\n    });\n  } catch (e) { }\n}\nfunction scrollChats() {\n  ['msgBox', 'sleepMsgBox', 'scLog'].forEach(id => {\n    const b = document.getElementById(id);\n    if (b) b.scrollTop = b.scrollHeight;\n  });\n}\nlet msgLoopBusy = false;\nasync function msgLoopRun(at) {\n  if (msgLoopBusy) return;\n  msgLoopBusy = true;\n  while (S.voiceLoop && String(S.voiceLoop.msgAt) === String(at)) {\n    const ok = await playVoiceRefOnce(S.voiceLoop.refs[0]);\n    if (!ok) { toast('播不出来：先在「设置 → 语音」里配好语音服务'); S.voiceLoop = null; break; }\n    if (!S.voiceLoop || String(S.voiceLoop.msgAt) !== String(at)) break;\n    await new Promise(r => setTimeout(r, voiceGap()));\n  }\n  msgLoopBusy = false;\n  try { render(); scrollChats(); } catch (e) { }\n}\n/* 本场所有语音串成一个循环：专注用这一场的角色消息，睡前闲聊用这一场的对话 */\nfunction msgLoopSrc() {\n  const st = S.sleep;\n  if (st && st.running && S.view === 'sleep') return { list: (st.chat || []), where: '这次睡前闲聊' };\n  const s = S.session;\n  return { list: ((s && s.msgs) || []), where: '这场专注' };\n}\nfunction msgLoopAllRefs() {\n  const src = msgLoopSrc();\n  return src.list.filter(m => m && m.role === 'char').map(msgVoiceRef).filter(Boolean);\n}\nasync function msgLoopAllRun() {\n  if (msgLoopBusy) return;\n  msgLoopBusy = true;\n  while (S.voiceLoop && S.voiceLoop.chatAll) {\n    const cur = S.voiceLoop;\n    const ref = cur.refs[cur.i % cur.refs.length];\n    const ok = await playVoiceRefOnce(ref);\n    if (!ok) { toast('播不出来：先在「设置 → 语音」里配好语音服务'); S.voiceLoop = null; break; }\n    if (!S.voiceLoop || S.voiceLoop !== cur) break;\n    cur.i = cur.refs.length > 1 ? (cur.i + 1) % cur.refs.length : 0;\n    paintVoiceLoop();\n    await new Promise(r => setTimeout(r, voiceGap()));\n  }\n  msgLoopBusy = false;\n  renderKeepChat();\n}\nObject.assign(ACTIONS, {\n  msgLoopAll: async () => {\n    const refs = msgLoopAllRefs();\n    if (!refs.length) {\n      toast('这一场还没有留下音频的语音 —— 等角色出声后再点，或把语音形式调成「每条角色消息都语音」');\n      return;\n    }\n    if (S.voiceLoop && S.voiceLoop.chatAll) { voiceLoopStop(); return; }\n    stopVoice();\n    S.voiceLoop = { refs: refs, i: 0, oneId: '', chatAll: true, msgAt: '__all__', label: '本场 ' + refs.length + ' 句' };\n    render(); scrollChats();\n    msgLoopAllRun();\n  },\n  msgLoopAllStop: () => { voiceLoopStop(); },\n  msgReplay: async el => {\n    const m = findMsgByAt(el.dataset.at);\n    const ref = m ? msgVoiceRef(m) : '';\n    if (!ref) { toast('这条没有留下音频（说这句时可能没配好语音服务）'); return; }\n    stopVoice();\n    const ok = await playVoiceRefOnce(ref);\n    if (!ok) toast('播不出来：先在「设置 → 语音」里配好语音服务');\n  },\n  msgLoop: async el => {\n    const at = String(el.dataset.at || '');\n    const m = findMsgByAt(at);\n    const ref = m ? msgVoiceRef(m) : '';\n    if (!ref) { toast('这条没有留下音频，没法循环'); return; }\n    if (S.voiceLoop && String(S.voiceLoop.msgAt) === at) { voiceLoopStop(); return; }\n    stopVoice();\n    S.voiceLoop = { refs: [ref], i: 0, oneId: '', msgAt: at, label: '聊天框 · 循环这一句' };\n    render(); scrollChats();\n    msgLoopRun(at);\n  }\n});\nfunction msgHTML(m) {\n  if (m.role === 'sys') return `<div class=\"msg sys\"><div class=\"bd\">${esc(m.text)}</div></div>`;\n  if (m.role === 'me') return `<div class=\"msg me\"><div class=\"bd\">${esc(m.text)}</div></div>`;\n  const c = charById(m.charId);\n  /* data-mat = 这条消息的时间戳：刚合成出音频时，靠它把按钮就地补进这条气泡 */\n  return `<div class=\"msg\" data-mat=\"${esc(m.at)}\">${charAvatar(c)}<div class=\"bd\"><div class=\"who\">${esc(c ? c.name : '角色')} · ${hm(m.at)}</div>${esc(m.text).replace(/\\n/g, '<br>')}${msgVoiceBarHTML(m)}</div></div>`;\n}\n/* 聊天框重画后把滚动条放回最底（按钮加进来会让气泡变高） */\nfunction renderKeepChat() {\n  try { render(); } catch (e) { }\n  setTimeout(scrollChats, 60);\n  setTimeout(scrollChats, 260);\n}\nfunction renderRunLight() {\n  const el = document.getElementById('ringTime');\n  if (!el || S.lock) return;\n  const s = S.session; if (!s) return;\n  el.textContent = fmtClock(remainSec());\n  const ring = document.getElementById('ring');\n  if (ring) { ring.style.setProperty('--p', clamp(100 - remainSec() / phaseTotalSec() * 100, 0, 100)); ring.classList.toggle('paused', !!s.paused); }\n  const sub = document.getElementById('ringSub');\n  if (sub) sub.textContent = s.phase === 'break' ? '休息一下' : (s.paused ? '已暂停 · ' + (s.pauseReason || '') : '专注中 · 请留在本页');\n}\nfunction scrollMsgs() { const b = document.getElementById('msgBox'); if (b) b.scrollTop = b.scrollHeight; }\nVIEWS.running = function () {\n  const s = S.session;\n  if (!s) return `<div class=\"card\"><h3>当前没有进行中的专注</h3><button class=\"btn primary block mt10\" data-act=\"gotoSetup\">去开始一段专注</button></div>`;\n  if (s.status === 'review') return `<div class=\"card glow\"><h3>本轮已结束，等待校验</h3>\n    <div class=\"sub\">填写反馈与总结 → 出题答题达标，任务才生效。</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"review\">进入校验</button></div>`;\n  if (s.status !== 'running') return `<div class=\"card\"><h3>这段专注已经结束了</h3>\n    <div class=\"sub\">${esc(s.summary || '')}</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"home\">回首页</button></div>`;\n  const isBreak = s.phase === 'break';\n  const doneN = s.plan.filter(t => t.done).length;\n  const bad = (s.violations || []).filter(v => !v.excused).length;\n  const chars = (s.charIds || []).map(charById).filter(Boolean);\n  const ci = currentTaskIdx(s);\n  const cur = ci >= 0 ? s.plan[ci] : null;\n  let nxt = null;\n  for (let i = ci + 1; i < s.plan.length; i++) { if (!s.plan[i].done) { nxt = s.plan[i]; break; } }\n  const curLeft = (cur && Number(cur.est)) ? Math.max(0, Number(cur.est) - (Date.now() - (s.curTaskSince || s.startAt)) / 60000) : null;\n  const lastMsg = (s.msgs || []).filter(m => m.role === 'char').slice(-1)[0];\n  const msgs = (s.msgs || []).slice(-80);   // 多留一些：以前只画最近 40 条，翻不到更早的话容易觉得「聊的内容不全」\n  const vm = cfg('voiceMode') || 'cue';\n  return `\n  <div class=\"card tight\"><div class=\"row between\"><div class=\"grow\">\n    <div class=\"row wrap\" style=\"gap:7px\">\n      <span class=\"pill ${isBreak ? 'ok' : 'run'}\">${isBreak ? '休息中' : '第 ' + s.cycle + '/' + s.cycles + ' 轮 · 专注'}</span>\n      <span class=\"pill\">${s.reviewEvery === 'session' ? '整段结束校验' : '每轮校验'}</span>\n      ${s.paused ? `<span class=\"pill warn\">已暂停</span>` : ''}\n      ${bad ? `<span class=\"pill bad\">违规 ${bad}</span>` : ''}\n    </div>\n    <div class=\"tiny mt6\">${isBreak ? '休息阶段不锁定、不催促' : '开始于 ' + hm(s.startAt) + ' · ' + (chars.map(c => esc(c.name)).join('、') || '无角色')}</div>\n  </div><button class=\"btn sm ghost\" data-act=\"abortAsk\">结束</button></div></div>\n  <div class=\"ringwrap\"><div class=\"ring ${s.paused ? 'paused' : ''}\" id=\"ring\" style=\"--p:${clamp(100 - remainSec() / phaseTotalSec() * 100, 0, 100)}\">\n    <div class=\"core\"><div class=\"t\" id=\"ringTime\">${fmtClock(remainSec())}</div>\n    <div class=\"s\" id=\"ringSub\">${isBreak ? '休息一下' : (s.paused ? '已暂停 · ' + esc(s.pauseReason || '') : '专注中 · 请留在本页')}</div></div></div></div>\n  <div class=\"row\" style=\"gap:9px;margin:14px 0 12px\">\n    ${s.paused ? `<button class=\"btn primary grow\" data-act=\"resumeSession\">▶️ 继续</button>`\n      : `<button class=\"btn grow\" data-act=\"pauseAsk\" ${isBreak ? 'disabled' : ''}>⏸ 暂停</button>`}\n    ${isBreak ? `<button class=\"btn teal grow\" data-act=\"skipBreak\">跳过休息</button>`\n      : `<button class=\"btn teal grow\" data-act=\"openQA\">❓ 答疑</button>`}\n  </div>\n  ${(s.assistLevel === 'L1' || s.assistLevel === 'L2' || s.assistLevel === 'L3') ? `<div class=\"row\" style=\"gap:9px;margin:-4px 0 12px\">\n    <button class=\"btn sm ghost grow\" data-act=\"wlApplyOpen\">🎟 申请通行证</button></div>` : ''}\n  ${(!isBreak && !s.paused) ? (function () {\n      const used = noteOfSession(s).length, lim = noteLimit();\n      const leftN = lim ? Math.max(0, lim - used) : 99;\n      return `<button class=\"btn block\" style=\"min-height:48px;margin:-4px 0 12px;background:linear-gradient(135deg,rgba(255,201,120,.22),rgba(165,139,255,.16));border-color:rgba(255,201,120,.4)\"\n        data-act=\"noteOpen\" ${leftN ? '' : 'disabled'}>📝 撑不住了？递张小纸条给 ${esc(charName(pickOneChar(s.charIds)))}\n        <span class=\"tiny\">${lim ? '（这场还能递 ' + leftN + ' 张）' : ''}</span></button>`;\n    })() : ''}\n  ${s.noteRestUntil ? `<div class=\"tiny center\" style=\"margin:-4px 0 12px;color:var(--teal)\">🌿 他让你松一口气：到点自动接着走</div>` : ''}\n  <div class=\"card\">\n    <div class=\"row between\"><span class=\"tiny\">当前任务</span><span class=\"tiny\">${s.plan.length ? doneN + '/' + s.plan.length : '未设置'}</span></div>\n    ${cur ? `<div class=\"nowtask mt6\"><div class=\"lbl\">NOW · 第 ${ci + 1} 项</div>\n      <div class=\"tx\">${esc(cur.content)}</div>\n      <div class=\"tiny mt6\">${Number(cur.est) ? (curLeft > 0 ? '预估 ' + cur.est + ' 分钟 · 还剩约 ' + Math.ceil(curLeft) + ' 分钟' : '预估 ' + cur.est + ' 分钟 · 已超预估') : '未填预估时间'}</div>\n      <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm primary grow\" data-act=\"skipTask\">标记完成，下一项</button>\n      <button class=\"btn sm ghost\" data-act=\"extendOpen\">⏱ 加/减时间</button></div>\n      ${s.extendOpen ? `<div class=\"row mt8\" style=\"gap:6px;align-items:center;flex-wrap:wrap\"><input id=\"extendIn\" inputmode=\"numeric\" value=\"${esc(s.extendVal == null ? '10' : s.extendVal)}\" placeholder=\"10\" style=\"width:74px;padding:6px 8px;border-radius:8px;border:1px solid rgba(128,128,128,.35);background:transparent;color:inherit;font-size:14px\" oninput=\"try{S.session.extendVal=this.value}catch(e){}\"><span class=\"tiny\">分钟（负数=缩短）</span><label class=\"tiny\" style=\"display:flex;align-items:center;gap:5px\"><input type=\"checkbox\" id=\"extendFocusToo\" ${s.extendFocusToo !== false ? 'checked' : ''} onchange=\"try{S.session.extendFocusToo=this.checked}catch(e){}\"> 专注总时长也一起加减</label><button class=\"btn sm primary\" data-act=\"extendApply\">确定</button><button class=\"btn sm ghost\" data-act=\"extendCancel\">取消</button></div>` : ''}</div></div>`\n      : `<div class=\"empty\" style=\"padding:14px\">${s.plan.length ? '本轮任务已全部勾完 🎉' : '本次没有设置任务清单'}</div>`}\n    ${nxt ? `<div class=\"nexttask mt10\"><div class=\"lbl\">NEXT · 下一个任务</div>\n      <div class=\"tx\">${esc(nxt.content)}${Number(nxt.est) ? '（预估 ' + nxt.est + ' 分钟）' : ''}</div></div>` : ''}\n    ${s.plan.length ? `<div class=\"mt10\"><div class=\"tiny\">全部任务</div>${s.plan.map((t, i) => `\n      <div class=\"todo ${t.done ? 'done' : ''}\" style=\"margin-top:6px\">\n        <button class=\"ck ${t.done ? 'on' : ''}\" data-act=\"todoToggle\" data-i=\"${i}\">✓</button>\n        <div class=\"tx\">${esc(t.content)}<div class=\"meta\">${Number(t.est) ? '预估 ' + t.est + ' 分钟' : '未填预估'}${i === ci ? ' · 进行中' : ''}</div></div></div>`).join('')}</div>` : ''}\n    <button class=\"btn block ghost sm mt10\" data-act=\"extraAdd\">＋ 临时追加一条任务</button>\n    ${(s.extraTasks || []).length ? `<div class=\"hr\"></div><div class=\"tiny\">临时追加的（${s.extraTasks.filter(t => t.done).length}/${s.extraTasks.length}）</div>${s.extraTasks.map((t, i) => `<div class=\"todo ${t.done ? 'done' : ''}\" style=\"margin-top:6px\">\n      <button class=\"ck ${t.done ? 'on' : ''}\" data-act=\"extraToggle\" data-i=\"${i}\">✓</button><div class=\"tx\">${esc(t.content)}<div class=\"meta\">${Number(t.est) ? '预估 ' + t.est + ' 分钟' : '未填预估'}${t.at ? ' · ' + hm(t.at) + ' 追加' : ''}</div></div></div>`).join('')}` : ''}\n  </div>\n  ${(s.selfTasks || []).length ? `<div class=\"card\"><h3>TA 这段时间也要做的事</h3>\n    ${s.selfTasks.map(x => `<div style=\"padding:8px 0\">\n      <div class=\"row\">${charAvatar(charById(x.charId))}\n        <div class=\"grow\" style=\"min-width:0\"><div class=\"row between\"><span style=\"font-size:13px\">${esc(x.text)}</span>\n          <span class=\"tiny\">${Number(x.progress) || 0}%${x.done ? ' · 已完成' : ''}</span></div>\n          <div class=\"tiny\">${esc(charName(x.charId))} 陪你一起 · 和你的任务同步</div></div></div>\n      <div class=\"bar mt6\"><i style=\"width:${Number(x.progress) || 0}%\"></i></div></div>`).join('')}\n    <div class=\"tiny mt6\">TA 的进度跟着你的任务走，不会因失误倒退。</div></div>` : ''}\n  ${noteBoardHTML()}\n  <div class=\"card\">\n    <div class=\"row between\"><h3>角色消息</h3>\n      <button class=\"btn sm ghost\" data-act=\"voiceSheet\">🔊 ${vm === 'off' ? '语音关' : vm === 'all' ? '全部语音' : '催促语音'}</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ${S.voiceLoop && S.voiceLoop.chatAll ? 'primary' : 'ghost'} grow\" data-act=\"msgLoopAll\">${S.voiceLoop && S.voiceLoop.chatAll ? '⏹ 停止循环' : '🔁 循环本场所有语音'}</button>\n      <span class=\"tiny\" style=\"align-self:center\">已留住 ${msgLoopAllRefs().length} 句</span></div>\n    <div class=\"tiny\" data-vloop=\"1\" style=\"margin-top:6px;color:var(--teal)\"></div>\n    <div id=\"msgBox\" style=\"max-height:40vh;overflow-y:auto;margin-top:8px\">\n      ${msgs.length ? msgs.map(m => msgHTML(m)).join('') : `<div class=\"empty\" style=\"padding:14px\">角色马上会来说点什么…</div>`}</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"pokeChar\">让角色说句话</button>\n    <button class=\"btn sm grow\" data-act=\"openQA\">问个问题</button></div>\n  </div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>专注壁纸</h3>\n      <span class=\"pill ${s.wallpaperLoading ? 'run' : (s.wallUnlocked ? 'ok' : '')}\">${s.wallpaperLoading ? '正在生成…' : '已攒 ' + ((s.walls || []).length || (s.wallpaperData ? 1 : 0)) + ' 张 · 可下载 ' + (Number(s.wallUnlocked) || 0) + ' 张'}</span></div>\n    <div class=\"tiny mt6\">做完一项任务解锁一张壁纸；没做完的那张保持上锁。</div>\n    ${s.phase === 'break' ? `<div class=\"tiny mt8\" style=\"background:rgba(94,234,212,.12);border:1px solid rgba(94,234,212,.35);border-radius:10px;padding:9px;line-height:1.7;color:var(--teal)\">现在正是休息时段 —— 刚解锁的那张可以下载了。</div>` : ''}\n    ${s.wallpaperError ? `<div class=\"tiny\" style=\"color:#ff9aa6\">${esc(s.wallpaperError)}</div>` : ''}\n    ${s.wallpaperData ? `<img src=\"${s.wallpaperData}\" style=\"width:100%;border-radius:12px;margin-top:10px;display:block;opacity:${canSaveWallpaper() ? '1' : '.72'}\" alt=\"\">` : ''}\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"genWallpaper\">＋ 手动再攒一张</button>\n      <button class=\"btn sm grow ${canSaveWallpaper() ? 'primary' : ''}\" data-act=\"saveWallpaper\" ${canSaveWallpaper() ? '' : 'disabled'}>\n        ${canSaveWallpaper() ? '⬇️ 下载已解锁的 ' + (Number(s.wallUnlocked) || 0) + ' 张' : '完成一个任务后可下载'}</button></div>\n    <button class=\"btn block ghost sm mt8\" data-act=\"openWallPrompt\">✏️ 改这套提示词（当前样式：${esc(wallStyleLabel())}）</button>\n    <div class=\"tiny mt6\">已解锁的在壁纸库可下载或存媒体库；上锁的答题或完成任务解锁。</div>\n  </div>\n  ${isBreak ? `<button class=\"btn teal block\" data-act=\"skipBreak\">跳过休息，直接下一轮</button>` : ''}\n  ${(s.violations || []).length ? `<div class=\"card\"><h3>违规记录</h3>${s.violations.map(v => `<div class=\"item\">\n    <div class=\"ic\">${v.excused ? '✅' : '⚠️'}</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(v.detail || v.type)}</div>\n    <div class=\"tiny\">${hm(v.at)}${v.excused ? ' · 已申诉豁免' : ' · 计入'}</div></div></div>`).join('')}</div>` : ''}\n  <div class=\"floatbar\" id=\"floatBar\">\n    ${lastMsg ? charAvatar(charById(lastMsg.charId)) : `<div class=\"avatar\" style=\"background:#2a3145\">…</div>`}\n    <div class=\"fx\"><div class=\"who2\" id=\"floatMsgWho\">${esc(lastMsg ? charName(lastMsg.charId) : '等待角色')}</div>\n      <div id=\"floatMsgText\" data-at=\"${lastMsg ? lastMsg.at : ''}\">${esc(lastMsg ? lastMsg.text : '角色正在陪着你…')}</div></div>\n    <button class=\"mini\" data-act=\"pokeChar\">💬</button><button class=\"mini\" data-act=\"openQA\">❓</button>\n  </div>`;\n};\n/* ==========================================================\n   视图 · 校验流程\n   ========================================================== */\n/* 当前这一屏真正在作答的那份卷子：按「正在看的页面」判断，\n   而不是按「哪个对象存在」——避免旧卷子（残留的练习 / 解锁答题 / 惩罚）把答案抢走 */\nfunction answerTarget() {\n  if (S.view === 'unlockquiz' && S.unlockQuiz) return S.unlockQuiz;\n  if (S.view === 'review' && S.review && S.review.stage === 'quiz') return S.review;\n  if (S.view === 'mistakes' && S.practice) return S.practice;\n  if (S.lock && S.quiz) return S.quiz;\n  return null;\n}\n/* 输入框取值：草稿优先（用户刚打的字先算），再回落到已存答案 —— 重绘不会把字清掉 */\nfunction ansOf(obj, i, field) {\n  const d = ((S.draft && S.draft[field || 'ans']) || {})[String(i)];\n  if (d != null && String(d) !== '') return String(d);\n  return (obj && obj.answers && obj.answers[i] != null) ? String(obj.answers[i]) : '';\n}\nfunction resetAnsDraft(field) {\n  S.draft[field || 'ans'] = {};\n}\nfunction ensureReview() {\n  if (!S.review) S.review = { stage: 'feedback', questions: [], answers: {}, pass: false, right: 0, total: 0, rate: 0, weakness: [], advice: '', reply: '' };\n  return S.review;\n}\nVIEWS.review = function () {\n  /* 所有待校验的都列出来，让你自己选做哪一条；顺手把「首页说有、点进来又没有」修掉 */\n  const pendingAll = (S.sessions || []).filter(x => x && x.status === 'review').sort((a, b) => (b.startAt || 0) - (a.startAt || 0));\n  let s = S.session;\n  if (!s || s.status !== 'review') {\n    const pick = S.draft.reviewPick ? pendingAll.find(x => String(x.id || x.dbId) === String(S.draft.reviewPick)) : null;\n    s = pick || pendingAll[0] || null;\n    S.session = s;\n    S.review = null;                       // 换了一条就重新填\n  }\n  if (!s) return `<div class=\"card\"><h3>现在没有待校验的专注</h3>\n    <div class=\"sub\">待校验的专注都会先列在这一页，首页只是给个提示。如果首页还在提示「有专注未校验」，回首页再看一次就会同步；也可能那条已经校验过了。</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"home\">回首页</button></div>`;\n  const R = ensureReview();\n  const picker = pendingAll.length > 1 ? `<div class=\"card tight\"><div class=\"tiny\">共有 <b>${pendingAll.length}</b> 段专注等着校验，点一条来做：</div>\n    <div class=\"mt8\">${pendingAll.map(x => {\n      const cur = String(x.id || x.dbId) === String(s.id || s.dbId);\n      return `<div class=\"item ${cur ? 'sel' : ''}\" data-act=\"reviewPick\" data-id=\"${esc(x.id || x.dbId)}\" style=\"cursor:pointer\">\n        <div class=\"ic\">${cur ? '📝' : '⏳'}</div>\n        <div class=\"grow\"><div style=\"font-size:13px\">${esc(x.taskName || ((x.plan || []).map(t => t.content).join('、') || '（未记录任务）'))}</div>\n        <div class=\"tiny\">${esc(x.date || '')} ${x.startAt ? hm(x.startAt) : ''} · 第 ${x.cycle || 1}/${x.cycles || 1} 轮 · ${Math.round((x.totalFocusSec || 0) / 60)} 分钟${cur ? ' · 正在填这一条' : ''}</div></div>\n        <div class=\"ic\">${cur ? '' : '›'}</div></div>`;\n    }).join('')}</div>\n    <div class=\"tiny mt6\">一次只填一条；填完这条（通过或失败）即可，然后再回来做下一条。</div></div>` : '';\n  /* 校验已完成、只等开始休息（例如校验后离开了再回来） */\n  if (s.pendingBreak) return picker + `<div class=\"card glow\">\n    <h3>第 ${s.cycle}/${s.cycles} 轮 · 校验已通过</h3>\n    <div class=\"sub\">校验这段时间不计入专注时长。点下面开始休息，休息结束后自动开始第 ${(s.cycle || 1) + 1}/${s.cycles} 轮。</div>\n    <button class=\"btn teal block mt12\" data-act=\"nextRound\">开始休息 ${Number(s.breakMin) || 5} 分钟 → 下一轮</button>\n    <button class=\"btn ghost block mt8\" data-act=\"abortAsk\">结束这轮，不继续了</button></div>`;\n  const doneN = (s.plan || []).filter(t => t.done).length;\n  const head = picker + `<div class=\"card tight\"><div class=\"row between\"><div class=\"grow\"><h3>本次专注记录</h3>\n    <div class=\"tiny\">专注 ${Math.round((s.totalFocusSec || 0) / 60)} 分钟 · 第 ${s.cycle}/${s.cycles} 轮 · 任务 ${doneN}/${s.plan.length}</div></div>\n    <span class=\"pill ${R.stage === 'result' ? (R.pass ? 'ok' : 'bad') : 'run'}\">${R.stage === 'result' ? (R.pass ? '考核通过' : '考核失败') : '待校验'}</span></div></div>`;\n  if (R.stage === 'feedback') return head + `\n    ${S.draft.reviewErr ? `<div class=\"card\" style=\"border-color:rgba(255,123,138,.5);background:rgba(255,123,138,.08)\">\n      <h3 style=\"color:#ff9aa6\">这次没能出题</h3>\n      <div class=\"tiny mt6\">${esc(S.draft.reviewErr)}</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn sm primary grow\" data-act=\"reviewRetry\">再试一次</button>\n        <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"qbank\">去题库加题</button></div>\n      <button class=\"btn sm ghost block mt8\" data-act=\"reviewSkip\">跳过校验，记为完成（不给币、不推进心愿）</button>\n      <div class=\"tiny mt6\">想彻底避免：把「我的 → 考核参数 → 题目来源」设为 AI 出题，或先在题库里放几道题当底。</div>\n    </div>` : ''}\n    <div class=\"card\"><h3>① 填写反馈与总结</h3>\n      <div class=\"sub\">必须走完整个校验流程，本次专注任务才算生效。</div>\n      <label class=\"fl\">本次学习反馈（状态如何、卡在哪）</label>\n      <textarea data-in=\"reviewFeedback\" placeholder=\"例如：前半段状态不错，后半段有点困\">${esc(S.draft.reviewFeedback || '')}</textarea>\n      <label class=\"fl\">学习总结（必填，会作为角色可见的记忆）</label>\n      <textarea data-in=\"reviewSummary\" placeholder=\"例如：完成了资料分析 30 题，增长率公式还不熟\">${esc(S.draft.reviewSummary || '')}</textarea>\n      <label class=\"fl\">希望考察的知识点（可选 · 留空就按上面的总结和历史薄弱点出题）</label>\n      <input class=\"input\" data-in=\"setting.quizFocus\" value=\"${esc(cfg('quizFocus') || '')}\" placeholder=\"例如：资料分析里的增长率与比重 / 英语的时态一致性\">\n      <div class=\"chips mt6\">\n        <button class=\"chip ${(cfg('quizFocusMode') || 'focus') === 'focus' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizFocusMode\" data-v=\"focus\">🎯 优先考这个范围</button>\n        <button class=\"chip ${cfg('quizFocusMode') === 'mix' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizFocusMode\" data-v=\"mix\">🧩 和总结混合</button>\n      </div>\n      ${cfg('quizFocus') ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">这次会围着你写的方向出题${(cfg('quizFocusMode') || 'focus') === 'mix' ? '（约一半落在这个范围）' : ''}。</div>` : ''}\n      <div class=\"tiny mt6\">任务完成度：${doneN}/${s.plan.length}（可在专注页勾选）· 校验时机：${s.reviewEvery === 'session' ? '整段结束校验' : '每轮校验（第 ' + (s.cycle || 1) + '/' + s.cycles + ' 轮结束时触发）'}</div>\n      <button class=\"btn primary block mt14\" data-act=\"reviewSubmit\" ${S.loading === 'review' ? 'disabled' : ''}>${S.loading === 'review' ? '正在生成题目…' : '② 出题校验'}</button>\n      <div class=\"tiny center mt10\">${S.loading === 'review' ? '<span class=\"spin\"></span> AI 正在按你的总结与薄弱点出题，题干和答案会一起写进题库。请勿重复点击。' : '题目由 AI 生成并把标准答案一起写进题库；提交后判分在本地瞬时完成。'}</div>\n    </div>`;\n  if (R.stage === 'quiz') {\n    const answered = R.questions.filter((q, i) => R.answers[i] != null && String(R.answers[i]) !== '').length;\n    return head + `<div class=\"card\">\n      <div class=\"row between\"><h3>② 答题校验</h3><span class=\"tiny\">${answered}/${R.questions.length}</span></div>\n      <div class=\"sub\">达标（正确率 ≥ ${Number(cfg('passRatio') || 80)}%）后本次专注立即生效并跳到壁纸奖励；未达标判定任务未完成并触发惩罚。</div>\n      <div class=\"mt10\">${R.questions.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n        ${qInputHTML(qx, i, R.answers, 'pickOpt')}</div>`).join('')}</div>\n      <button class=\"btn primary block\" data-act=\"gradeNow\">提交答卷</button></div>`;\n  }\n  const cid = pickOneChar(s.charIds);\n  return head + `\n  <div class=\"card ${R.pass ? 'glow' : ''}\" style=\"${R.pass ? '' : 'border-color:rgba(255,123,138,.45)'}\">\n    <div class=\"center\"><div style=\"font-size:30px\">${R.pass ? '✅' : '⚠️'}</div>\n      <div style=\"font-size:17px;font-weight:600;margin-top:6px\">${R.pass ? '任务生效 · 考核通过' : '任务未完成 · 考核失败'}</div>\n      <div class=\"tiny mt6\">${R.total ? '答对 ' + R.right + '/' + R.total + '（' + Math.round(R.rate) + '%）' : '本次跳过了校验'}${R.pass || R.total ? '' : ' · 未达达标线'}</div></div>\n    ${s.reviewEvery === 'focus' && R.pass && (s.cycle || 1) < s.cycles && s.status === 'running'\n        ? `<div class=\"tiny mt8\" style=\"background:var(--accent-soft);border-radius:10px;padding:9px;line-height:1.7\">「每轮校验」已完成第 ${s.cycle}/${s.cycles} 轮 —— 点下面的「继续下一轮」进入休息，休息结束自动开始下一轮专注。</div>` : ''}\n    <div class=\"hr\"></div>\n    ${R.questions.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n      ${qResultHTML(qx, i, R.answers)}\n      ${qx.explain ? `<div class=\"exp\">${esc(qx.explain)}</div>` : ''}</div>`).join('')}\n  </div>\n  ${R.reply ? `<div class=\"card\"><div class=\"row\">${charAvatar(charById(cid))}\n    <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\"><div class=\"who\">${esc(charName(cid))}</div>${esc(R.reply)}</div></div>\n    <button class=\"btn sm ghost mt10\" data-act=\"replayReply\">🔊 再听一遍</button></div>` : ''}\n  ${R.advice ? `<div class=\"card\"><h3>点拨</h3><div style=\"font-size:13px;line-height:1.75;margin-top:6px\">${esc(R.advice)}</div></div>` : ''}\n  <div class=\"card\"><div class=\"tiny\">这张壁纸已存入壁纸库（默认上锁，可答题或完成任务解锁）。错题与薄弱点已存入私密学习记忆，角色看不到。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      ${R.pass ? `<button class=\"btn primary grow\" data-act=\"gotoView\" data-view=\"reward\">🏆 查看壁纸奖励</button>`\n      : `<button class=\"btn ghost grow\" data-act=\"reviewAgain\">再考一次</button>\n         <button class=\"btn primary grow\" data-act=\"reviewDone\">认了，回首页</button>`}\n      <button class=\"btn ghost\" data-act=\"gotoView\" data-view=\"album\">壁纸库</button></div></div>`;\n};\nVIEWS.reward = function () {\n  const s = S.session, R = S.review;\n  if (!s || !R || !R.pass) return `<div class=\"card\"><h3>没有可领取的奖励</h3>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"home\">回首页</button></div>`;\n  const cid = pickOneChar(s.charIds);\n  const wrong = R.questions.filter(q => !q.ok).length;\n  const more = !!R.moreRounds;\n  return `\n  <div class=\"card glow\" style=\"text-align:center;background:linear-gradient(160deg,rgba(94,234,212,.16),rgba(124,140,255,.1));border-color:rgba(94,234,212,.35)\">\n    <div style=\"font-size:46px\">🏆</div>\n    <div style=\"font-size:19px;font-weight:700;margin-top:6px\">考核通过 · 任务生效</div>\n    <div class=\"tiny mt6\">答对 ${R.right}/${R.total}（${Math.round(R.rate)}%）${wrong ? ' · 错题 ' + wrong + ' 道已入私密库' : ' · 全对'}</div>\n  </div>\n  ${s.wallpaperData ? `<div class=\"card\" style=\"padding:8px\">\n      <img src=\"${s.wallpaperData}\" style=\"width:100%;border-radius:14px;display:block\" alt=\"\">\n      <button class=\"btn primary block mt10\" data-act=\"saveWallpaper\">⬇️ 下载这张图片</button></div>`\n      : `<div class=\"card\"><h3>本次壁纸还没生成</h3><div class=\"tiny\">${esc(s.wallpaperError || '生图接口未返回图片')}</div>\n        <button class=\"btn primary block mt10\" data-act=\"genWallpaper\">生成壁纸奖励</button></div>`}\n  <div class=\"card\"><div class=\"row\">${charAvatar(charById(cid))}\n    <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\"><div class=\"who\">${esc(charName(cid))}</div>${esc(R.reply || '做完了，去休息一会儿吧。')}</div></div>\n    ${R.advice ? `<div class=\"hr\"></div><div style=\"font-size:13px;line-height:1.7\">${esc(R.advice)}</div>` : ''}</div>\n  <div class=\"row\" style=\"gap:9px\"><button class=\"btn ghost grow\" data-act=\"gotoView\" data-view=\"album\">🖼 壁纸库</button>\n    ${more ? `<button class=\"btn teal grow\" data-act=\"nextRound\">开始休息 ${Number(s.breakMin) || 5} 分钟 → 下一轮</button>` : `<button class=\"btn primary grow\" data-act=\"reviewDone\">完成，回首页</button>`}</div>\n  ${more ? `<div class=\"tiny center mt8\" style=\"color:var(--dim2)\">校验这段时间不算专注时长。点按钮才开始休息，休息结束自动开始第 ${(s.cycle || 1) + 1}/${s.cycles} 轮。</div>` : ''}`;\n};\n/* ==========================================================\n   惩罚锁定页\n   ========================================================== */\nlet lockTick = null;\nfunction stopLockTick() { if (lockTick) { clearInterval(lockTick); lockTick = null; } }\n/* 限时打卡惩罚需要一个每秒走动的倒计时（只改一个文本节点，不重画整页） */\nfunction startLockTick(p) {\n  stopLockTick();\n  if (!p) return;\n  const moneyKind = (p.kind === 'pay' || p.kind === 'gift');\n  if (p.kind !== 'checkin' && !moneyKind) return;\n  const paint = () => {\n    if (p.kind === 'checkin') {\n      const el = document.getElementById('chkIn');\n      if (!el) { stopLockTick(); return; }\n      const left = Math.max(0, Math.ceil(((p.nextAt || 0) - Date.now()) / 1000));\n      el.textContent = (p.checkinDone || 0) >= (Number(p.checkinCount) || 4) ? '已全部打卡' : (left > 0 ? '下次可打卡：' + fmtClock(left) : '现在可以打卡');\n      return;\n    }\n    const el = document.getElementById('punishCd');\n    if (!el) { stopLockTick(); return; }\n    const left = Math.max(0, Math.round(((p.confirmUntil || 0) - Date.now()) / 1000));\n    if (left > 0) el.textContent = '还剩 ' + fmtClock(left) + ' 没确认，就自动执行扣款';\n    else {\n      el.textContent = '时间到 —— 正在自动执行…';\n      stopLockTick();\n      autoRunPunish(p, true);            // 超时未确认 → 自动扣款\n    }\n  };\n  paint();\n  lockTick = setInterval(paint, 1000);\n}\nfunction renderLock() {\n  const p = S.lock ? S.lock.punish : null;\n  if (!p) { S.lock = null; render(); return; }\n  /* 惩罚页是全屏独立滚动容器（.lock），得单独记住它的 scrollTop ——\n     否则答一道选择题就会被弹回最上面（普通页面的滚动位置管不到这里） */\n  const prevLock = document.querySelector('.lock');\n  const keepTop = prevLock ? (prevLock.scrollTop || 0) : 0;\n  $('#view').innerHTML = `<div class=\"lock\">${lockHTML(p)}</div>`;\n  const newLock = document.querySelector('.lock');\n  if (newLock && keepTop > 0) {\n    try {\n      newLock.scrollTop = keepTop;\n      if (Math.abs(newLock.scrollTop - keepTop) > 8) requestAnimationFrame(function () { try { newLock.scrollTop = keepTop; } catch (e) { } });\n    } catch (e) { }\n  }\n  $('#tabbar').style.display = 'none';\n  const nb = document.getElementById('navBack'); if (nb) nb.style.display = 'none';\n  $('#tbTitle').textContent = '惩罚执行中'; $('#tbSub').textContent = 'LOCK';\n  startLockTick(p);\n}\nfunction quizBody(p) {\n  const q = S.quiz;\n  if (!q) {\n    const cats = bankCats();\n    const cat = cfg('punishCat') || '';\n    const src = Object.assign({ fresh: 1, wrong: 1, bank: 1 }, cfg('quizMixSrc') || {});\n    const kind = Object.assign({ choice: 1, fill: 1, multi: 1, tf: 1 }, cfg('quizMixKind') || {});\n    const kinds = Q_TYPES.filter(([k]) => Number(kind[k]) > 0).map(([k, n]) => n).join('/') || '（未设题型）';\n    return `<div class=\"card\"><h3>练习题惩罚</h3>\n      <div class=\"sub\">需要完成 ${p.count} 道题，正确率达到 ${p.ratio}% 才能解除锁定。</div>\n      <div class=\"kv mt6\"><span class=\"k\">来源配比</span><span>${esc(mixText(src))}</span></div>\n      <div class=\"kv\"><span class=\"k\">题型</span><span>${esc(kinds)}</span></div>\n      <label class=\"fl\">这次抽哪个分类的题</label>\n      <div class=\"chips\">\n        <button class=\"chip ${!cat ? 'on' : ''}\" data-act=\"punishCatPickLock\" data-v=\"\">全部分类</button>\n        ${cats.map(c => `<button class=\"chip ${String(cat) === String(c) ? 'on' : ''}\" data-act=\"punishCatPickLock\" data-v=\"${esc(c)}\">📁 ${esc(c)}</button>`).join('')}\n      </div>\n      <div class=\"tiny mt6\">分类可以在题库里管理（题库 → 管理分类），也能批量把题移过去。某分类题太少时会自动用别的分类补足，不会给空卷。</div>\n      <button class=\"btn warn block mt10\" data-act=\"genPunishQuiz\" ${S.loading === 'quiz' ? 'disabled' : ''}>${S.loading === 'quiz' ? '正在出题…' : '抽取 ' + p.count + ' 道题'}</button>\n      ${S.loading === 'quiz' ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> 正在按「新题 / 错题 / 题库题」配比组卷，题多时会分批请求，稍等…</div>` : ''}\n      <button class=\"btn ghost block sm mt8\" data-act=\"quizMixOpen\">⚙️ 改配比 / 掌握度阈值</button></div>`;\n  }\n  if (q.graded) return `<div class=\"card\">\n    <div class=\"center\"><div style=\"font-size:26px;font-weight:700;color:${q.pass ? '#5eead4' : '#ff9aa6'}\">${q.right}/${q.total}</div>\n      <div class=\"tiny\">正确率 ${Math.round(q.rate)}% · 要求 ${p.ratio}%</div></div>\n    ${q.pass ? `<div class=\"tiny center mt10\">✅ 达标，惩罚完成</div>`\n      : `<div class=\"tiny center mt10\">未达标，错题已记入私密学习记忆。</div>\n         <button class=\"btn warn block mt10\" data-act=\"genPunishQuiz\">再抽一批</button>`}\n    <div class=\"hr\"></div>\n    ${q.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n      ${qResultHTML(qx, i, q.answers)}\n      ${qx.explain ? `<div class=\"exp\">${esc(qx.explain)}</div>` : ''}</div>`).join('')}</div>`;\n  return `<div class=\"card\"><div class=\"row between\"><h3>共 ${q.qs.length} 题 · 全部作答后提交</h3>\n    <span class=\"tiny\">${Object.keys(q.answers).filter(k => qAnswered(q.qs[Number(k)], q.answers[k])).length}/${q.qs.length}</span></div>\n    <div class=\"mt10\">${q.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n      ${qInputHTML(qx, i, q.answers, 'pickOpt')}</div>`).join('')}</div>\n    <button class=\"btn warn block\" data-act=\"gradeNow\">提交答卷</button></div>`;\n}\nfunction lockHTML(p) {\n  const c = charById(p.charId);\n  let body = '';\n  if (p.kind === 'quiz') body = quizBody(p);\n  else if (p.kind === 'pay' || p.kind === 'gift') {\n    const isPay = p.kind === 'pay';\n    const money = isPay ? ('¥' + Number(p.amount || 0).toLocaleString()) : ('「' + (p.gift || '') + '」¥' + Number(p.price || 0).toLocaleString());\n    const doing = p.remedy && p.remedy.type === 'task' && p.remedy.text;\n    body = `<div class=\"card\">\n      <div class=\"center\"><div style=\"font-size:32px;font-weight:700\">${isPay ? money : esc(money)}</div>\n        <div class=\"tiny\">${isPay ? '转给' : '送给'} ${esc(c ? c.name : '陪伴角色')}</div></div>\n      <div class=\"hr\"></div>\n      <div class=\"kv\"><span class=\"k\">惩罚项目</span><span>${esc(p.title)}</span></div>\n      <div class=\"kv\"><span class=\"k\">力度</span><span>${esc(multLabel(p.mult))}</span></div>\n      ${p.confirmUntil ? `<div class=\"tiny mt10\" id=\"punishCd\" style=\"background:var(--warn-soft);border-radius:10px;padding:9px;line-height:1.7;color:#ffb3bd\">—</div>` : ''}\n      </div>\n    ${doing ? `<div class=\"card\" style=\"border-color:rgba(94,234,212,.5);background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03))\">\n      <div class=\"tiny\">你选的补救方式是完成一件事 —— 做完再点下面，这次扣款就免掉。</div>\n      <div style=\"font-size:14.5px;margin-top:6px;font-weight:600\">${esc(p.remedy.text)}</div>\n      <button class=\"btn teal block mt10\" style=\"min-height:50px\" data-act=\"remedyTaskDone\" data-id=\"${esc(p.id)}\">✅ 我做完了，免掉这次</button>\n      <button class=\"btn ghost block sm mt8\" data-act=\"remedyTaskAsk\" data-id=\"${esc(p.id)}\">换一件</button></div>`\n      : `<div class=\"card\"><h3>你想怎么处理这次惩罚</h3>\n        <div class=\"tiny\">三条路选一条。不选的话，倒计时走完就自动扣款。</div>\n        <button class=\"btn warn block mt10\" style=\"min-height:50px\" data-act=\"${isPay ? 'doPay' : 'doGift'}\">${isPay ? '直接转账 ' + money : '直接购买并赠送 ' + money}</button>\n        <button class=\"btn block mt8\" data-act=\"remedyTaskAsk\" data-id=\"${esc(p.id)}\">✅ 用「完成一件事」补救（免掉扣款）</button>\n        <button class=\"btn block mt8\" data-act=\"remedyAppt\" data-id=\"${esc(p.id)}\">🗓 再约一段专注来补救（免掉扣款）</button>\n        <div class=\"tiny mt8\">补救的两条路都不用花钱，但要真的做到 —— 选了「完成一件事」就得做完才能解除；选了「再约一段」而新的那一段又没来，两笔一起算。</div></div>`}`;\n  }\n  else if (p.kind === 'txt') {\n    const need = txtTarget(p), got = txtCount(S.draft.punTxt || '');\n    body = `<div class=\"card\">\n      <div class=\"tiny\">把下面这段内容<b>抄写 ${Number(p.count) || 1} 遍</b>，抄完粘贴到下面提交（标点、空格不计入字数）。</div>\n      <div style=\"background:var(--card2);border-radius:10px;padding:10px;margin-top:8px;font-size:13.5px;line-height:1.7\">${esc(p.text || '')}</div>\n      <div class=\"tiny mt6\">目标 ≥ ${need} 字${got ? ' · 当前 ' + got + ' 字' : ''}</div>\n      <textarea id=\"punTxt\" data-in=\"punTxt\" placeholder=\"在这里抄写 / 粘贴\" style=\"min-height:130px;margin-top:8px\">${esc(S.draft.punTxt || '')}</textarea>\n      <button class=\"btn warn block mt10\" data-act=\"punishTextSubmit\">抄完了，提交</button></div>`;\n  } else if (p.kind === 'essay') {\n    const need = Math.max(20, Number(p.minWords) || 200), got = txtCount(S.draft.punTxt || '');\n    body = `<div class=\"card\">\n      <div class=\"tiny\">${esc(p.detail || '写一段反思')} —— 至少 <b>${need}</b> 字${got ? '（当前 ' + got + ' 字）' : ''}。</div>\n      <textarea id=\"punTxt\" data-in=\"punTxt\" placeholder=\"写在这里…\" style=\"min-height:170px;margin-top:8px\">${esc(S.draft.punTxt || '')}</textarea>\n      <button class=\"btn warn block mt10\" data-act=\"punishTextSubmit\">写完了，提交</button></div>`;\n  } else if (p.kind === 'act') body = `<div class=\"card\"><div class=\"center\"><div style=\"font-size:40px\">🏃</div>\n    <div style=\"font-size:16px;font-weight:600;margin-top:6px\">${esc(p.actName || p.title)}</div>\n    <div class=\"tiny mt6\">${esc(p.detail || '做完回来点下面的按钮')}</div></div>\n    <button class=\"btn warn block\" style=\"min-height:50px\" data-act=\"punishActDone\">我做到了</button>`;\n  else body = `<div class=\"card\">\n    <div class=\"tiny\">限时打卡：在 <b>${Number(p.checkinMin) || 20} 分钟</b>内，每 <b>${Number(p.checkinGap) || 5} 分钟</b>回来点一次「我在」，共 <b>${Number(p.checkinCount) || 4} 次</b>。</div>\n    <div class=\"center mt10\"><div style=\"font-size:28px;font-weight:700\">${p.checkinDone || 0} / ${Number(p.checkinCount) || 4}</div>\n      <div class=\"tiny\" id=\"chkIn\">—</div></div>\n    <div class=\"bar mt10\"><i style=\"width:${clamp((p.checkinDone || 0) / (Number(p.checkinCount) || 4) * 100, 0, 100)}%\"></i></div>\n    <button class=\"btn warn block mt10\" style=\"min-height:50px\" data-act=\"punishCheckin\">我在</button>\n    ${(p.checkinAt || []).length ? `<div class=\"tiny mt8\">已打卡：${(p.checkinAt || []).map(t => hm(t)).join('、')}</div>` : ''}</div>`;\n  return `\n  <div class=\"center skull\">🔒</div>\n  <div class=\"center\" style=\"margin:10px 0 4px\"><div style=\"font-size:20px;font-weight:700\">惩罚执行中</div>\n    <div class=\"tiny mt6\">未完成前，本 APP 保持锁定状态</div></div>\n  <div class=\"card mt14\" style=\"border-color:rgba(255,123,138,.4)\">\n    <div class=\"sub\">触发原因：${esc(reasonText(p.reason))}</div>\n    <div class=\"mt6\" style=\"font-size:14px\"><b>${esc(p.title)}</b></div>\n    <div class=\"tiny mt6\">${esc(p.detail || '')}</div></div>\n  ${p.line ? `<div class=\"card\" style=\"background:var(--warn-soft);border-color:rgba(255,123,138,.3)\">\n    <div class=\"row\">${charAvatar(c)}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">\n      <div class=\"who\">${esc(c ? c.name : '角色')} · 惩罚台词</div>${esc(p.line)}</div></div>\n    <button class=\"btn sm ghost mt10\" data-act=\"replayLine\">🔊 再听一遍</button></div>`\n      : `<div class=\"card\"><div class=\"tiny\"><span class=\"spin\"></span> 角色正在想怎么罚你…</div></div>`}\n  ${body}\n  ${(function () {\n    /* 有卡：直接免。没卡但币够：当场换一张再免 —— 不用退出锁定页跑去专注币页。 */\n    const have = Number(cfg('freePass')) || 0;\n    if (have > 0) return `<button class=\"btn block mt10\" data-act=\"useFreePass\">🎫 用一张免罚卡免掉这次（剩 ${have} 张）</button>`;\n    const cost = freePassCost();\n    const bal = coinBal();\n    return `<div class=\"card\" style=\"background:var(--card2)\">\n      <div class=\"tiny\">你现在没有免罚卡。可以用专注币现换一张，换了直接免掉这次 —— 不用先出去换。</div>\n      <div class=\"row between mt8\"><span style=\"font-size:13.5px\">🎫 免罚卡 ×1</span><span style=\"font-size:13.5px;color:var(--gold)\">${cost} 专注币</span></div>\n      <button class=\"btn ${bal >= cost ? 'primary' : 'ghost'} block mt10\" style=\"min-height:48px\" data-act=\"lockBuyFreePass\" ${bal >= cost ? '' : 'disabled'}>${bal >= cost ? ('🪙 花 ' + cost + ' 专注币换一张，免掉这次（余额 ' + bal + '）') : ('专注币不够：有 ' + bal + ' / 需 ' + cost)}\n      </button>\n      <div class=\"tiny mt6\" style=\"color:var(--dim2)\">专注币来自通过考核的专注时长。币不够就先把这次做完，或者去学一段攒回来。</div>\n    </div>`;\n  })()}\n  <div class=\"tiny center mt14\">规则是你自己定的，做完就自由了。</div>`;\n}\n/* ==========================================================\n   视图 · 壁纸库 / 答题解锁\n   ========================================================== */\nVIEWS.album = function () {\n  const all = S.album || [];\n  const locked = all.filter(x => x.locked).length;\n  const tip = S.draft.albumUnlockedTip || ''; S.draft.albumUnlockedTip = '';\n  const bigId = S.draft.albumBig;\n  const big = bigId ? all.find(x => String(x.id) === String(bigId)) : null;\n  if (big) {\n    const meta = `<div class=\"row between\"><h3>${esc(big.title)}</h3>\n      <button class=\"btn sm ghost\" data-act=\"albumClose\">返回列表</button></div>\n      <div class=\"tiny mt6\">${big.date} · ${big.kind === 'sleep' ? '睡眠壁纸' : big.kind === 'reward' ? '奖励留念' : big.kind === 'streak' ? '连续作息奖励' : '专注壁纸'}\n        ${big.locked ? ' · <span style=\"color:#ff9aa6\">未解锁</span>' : ' · 已解锁'}${big.unlockNote ? ' · ' + esc(big.unlockNote) : ''}</div>\n      ${big.note ? `<div class=\"tiny mt6\">${esc(big.note)}</div>` : ''}`;\n    if (big.locked) return `<div class=\"card\">${meta}\n      <div class=\"card mt10\" style=\"background:var(--card2);min-height:170px;display:grid;place-items:center\">\n        <div class=\"center\"><div style=\"font-size:34px\">🔒</div><div class=\"tiny mt6\">解锁后可查看与保存</div></div></div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"albumUnlockQuiz\" data-id=\"${esc(big.id)}\">答题解锁</button>\n        <button class=\"btn grow\" data-act=\"albumUnlockTask\" data-id=\"${esc(big.id)}\">完成任务解锁</button></div>\n      ${big.unlockType === 'task' && big.unlockTask ? `<div class=\"card mt10\" style=\"background:var(--card2)\">\n        <div class=\"tiny\">待完成任务</div><div style=\"font-size:13.5px;margin-top:4px\">${esc(big.unlockTask)}</div>\n        <button class=\"btn primary block mt10\" data-act=\"albumTaskDone\" data-id=\"${esc(big.id)}\">我完成了，解锁</button></div>` : ''}</div>`;\n    return `<div class=\"card\">${meta}\n      <img id=\"albBig\" data-ref=\"${esc(big.id)}\" src=\"\" style=\"width:100%;border-radius:14px;margin-top:10px;display:block;background:#1a2030;min-height:200px\" alt=\"\">\n      <button class=\"btn primary block mt10\" data-act=\"albumDownload\" data-id=\"${esc(big.id)}\">⬇️ 下载这张壁纸</button>\n      <button class=\"btn block ghost mt8\" data-act=\"albumFav\" data-id=\"${esc(big.id)}\">⭐ 收藏这张壁纸</button></div>`;\n  }\n  return `\n  ${tip ? `<div class=\"card\" style=\"border-color:rgba(94,234,212,.45);background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03))\">\n    <h3 style=\"color:var(--teal)\">🔓 ${esc(tip)}</h3><div class=\"tiny mt6\">下面可以直接保存这张壁纸了。</div></div>` : ''}\n  <div class=\"card\"><div class=\"row between\"><h3>壁纸库（${all.length}）</h3>\n    <span class=\"pill\">${locked ? locked + ' 张未解锁' : '全部已解锁'}</span></div>\n    <div class=\"sub\">专注奖励图、睡眠壁纸、奖励留念都会进这里。历史壁纸默认上锁，答题或完成任务后即可查看和保存。</div></div>\n  ${all.length ? `<div class=\"card\"><div class=\"row wrap\" style=\"gap:9px\">\n    ${all.slice(0, 30).map(it => `<div style=\"width:calc(50% - 5px)\" data-act=\"albumOpen\" data-id=\"${esc(it.id)}\">\n      <div id=\"alb_${esc(it.id)}\" style=\"width:100%;aspect-ratio:3/4;border-radius:12px;background:#1a2030 center/cover no-repeat;position:relative;${it.locked ? 'filter:blur(7px) brightness(.7);' : ''}\">\n        ${it.locked ? `<div style=\"position:absolute;inset:0;display:grid;place-items:center;font-size:24px;background:rgba(8,10,18,.35)\">🔒</div>` : ''}</div>\n      <div class=\"tiny ellip mt6\" style=\"text-align:center\">${esc(it.title)} · ${it.date}</div></div>`).join('')}\n  </div></div>` : `<div class=\"empty\">壁纸库还是空的。专注通过校验、或睡眠里生成壁纸后会出现在这里。</div>`}`;\n};\nVIEWS.unlockquiz = function () {\n  const U = S.unlockQuiz;\n  if (!U) return `<div class=\"card\"><h3>没有进行中的解锁答题</h3><button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"album\">回壁纸库</button></div>`;\n  const item = (S.album || []).find(x => String(x.id) === String(U.albumId));\n  const bar = Number(cfg('passRatio') || 80);\n  if (U.graded) return `\n    <div class=\"card ${U.pass ? 'glow' : ''}\" style=\"${U.pass ? '' : 'border-color:rgba(255,123,138,.45)'}\">\n      <div class=\"center\"><div style=\"font-size:28px\">${U.pass ? '🔓' : '📕'}</div>\n        <div style=\"font-size:17px;font-weight:600;margin-top:6px\">${U.pass ? '达标，壁纸已解锁' : '未达标'}</div>\n        <div class=\"tiny mt6\">答对 ${U.right}/${U.total}（${Math.round(U.rate)}%）· 要求 ${bar}%</div></div>\n      ${U.pass ? `<button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"album\">去壁纸库保存</button>`\n      : `<div class=\"row mt10\" style=\"gap:9px\"><button class=\"btn ghost grow\" data-act=\"albumQuizBack\">回壁纸库</button>\n         <button class=\"btn primary grow\" data-act=\"albumQuizAgain\">再答一批</button></div>`}</div>\n    ${U.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n      ${qResultHTML(qx, i, U.answers)}\n      ${qx.explain ? `<div class=\"exp\">${esc(qx.explain)}</div>` : ''}</div>`).join('')}`;\n  const answered = U.qs.filter((qx, i) => qAnswered(qx, U.answers[i])).length;\n  return `<div class=\"card\"><div class=\"row between\"><h3>答题解锁 · ${esc(item ? item.title : '')}</h3>\n    <span class=\"tiny\">${answered}/${U.qs.length}</span></div>\n    <div class=\"sub\">答对达到 ${bar}% 即解锁这张壁纸。</div></div>\n  ${U.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n    ${qInputHTML(qx, i, U.answers, 'pickOpt')}</div>`).join('')}\n  <button class=\"btn primary block\" data-act=\"gradeNow\">提交答卷</button>\n  <button class=\"btn block ghost sm mt10\" data-act=\"albumQuizCancel\">放弃解锁</button>`;\n};\n/* ==========================================================\n   视图 · 奖励中心\n   ========================================================== */\nVIEWS.rewards = function () {\n  const all = S.rewards || [];\n  const pend = all.filter(r => !r.claimed);\n  const done = all.filter(r => r.claimed);\n  const kinds = rewardKinds();\n  const KINDS_ALL = [['gift', '送礼物'], ['pay', '转账'], ['redpack', '发红包'], ['act', '做一件让你开心的事']];\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,201,120,.14),rgba(255,255,255,.03));border-color:rgba(255,201,120,.3)\">\n    <h3>🎁 奖励中心</h3>\n    <div class=\"sub\">考核通过、作息达标后，TA 会在聊天室亲手给你奖励 —— 回复自动留作凭证。</div>\n  </div>\n  ${pend.length ? pend.map(r => {\n    const c = charById(r.charId);\n    return `<div class=\"card glow\" style=\"border-color:rgba(255,201,120,.45)\">\n      <div class=\"row between\"><span class=\"tiny\">${esc(REWARD_KIND_LABEL[r.kind] || '奖励')}${r.reason ? ' · ' + esc(r.reason) : ''}</span>\n        <span class=\"pill warn\">待领取</span></div>\n      <div class=\"row mt6\">${charAvatar(c)}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">\n        <div class=\"who\">${esc(charName(r.charId))}</div>${r.line ? esc(r.line) : '（去聊天室让 TA 亲口说）'}</div></div>\n      <div class=\"hr\"></div>\n      <div class=\"kv\"><span class=\"k\">TA 要给你</span><span><b>${esc(r.want || '')}</b></span></div>\n      ${r.kind === 'gift' ? `<div class=\"kv\"><span class=\"k\">价值</span><span>¥${Number(r.price || 0).toLocaleString()}</span></div>` : ''}\n      ${(r.kind === 'pay' || r.kind === 'redpack') ? `<div class=\"kv\"><span class=\"k\">金额</span><span>¥${Number(r.amount || 0).toLocaleString()}</span></div>` : ''}\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"rewardClaim\" data-id=\"${esc(r.id)}\" ${r.delivering ? 'disabled' : ''}>${r.delivering ? '正在交给 TA…' : '去聊天室领奖'}</button>\n        <button class=\"btn grow\" data-act=\"rewardManual\" data-id=\"${esc(r.id)}\">TA 已经给我了</button></div>\n      <div class=\"row mt8\"><button class=\"btn ghost sm\" data-act=\"rewardDismiss\">先放着</button></div>\n      ${r.delivering ? `<div class=\"tiny mt10\"><span class=\"spin\"></span> 已把奖励申请写进聊天室，等 TA 回复…</div>` : ''}\n      <div class=\"tiny mt8\" style=\"color:var(--dim2)\">已经自己在聊天室领到了、APP 却还显示「待领取」？点「TA 已经给我了」，把 TA 的原话贴进来就能同步。</div></div>`;\n  }).join('') : `<div class=\"empty\">现在没有待领取的奖励。<br>连续规律作息达标、或专注考核通过后，角色可能会送你点什么。</div>`}\n  <div class=\"card\">\n    <div class=\"row between\"><h3>奖励设置</h3><button class=\"btn sm ghost\" data-act=\"rewardGiveNow\">让 TA 现在送一份</button></div>\n    <div class=\"sub\">勾选允许出现的奖励形式。</div>\n    <div class=\"chips mt6\">${KINDS_ALL.map(([k, n]) => `<button class=\"chip ${kinds.indexOf(k) >= 0 ? 'on' : ''}\" data-act=\"toggleRewardKind\" data-k=\"${k}\">${n}</button>`).join('')}</div>\n    <label class=\"fl\">奖励申请怎么写进聊天室</label>\n    <div class=\"chips\">\n      <button class=\"chip ${(cfg('rewardAskStyle') || 'card') === 'card' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"rewardAskStyle\" data-v=\"card\">系统卡片（推荐，不像你在索要）</button>\n      <button class=\"chip ${cfg('rewardAskStyle') === 'user' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"rewardAskStyle\" data-v=\"user\">以你的消息发出</button>\n    </div>\n    <button class=\"btn sm ghost block mt6\" data-act=\"gotoView\" data-view=\"prompts\">改奖励申请的原话 ›</button>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">礼物价值</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rewardGiftPrice\" value=\"${Number(cfg('rewardGiftPrice') || 199)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">转账金额</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rewardPayAmount\" value=\"${Number(cfg('rewardPayAmount') || 520)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">红包金额</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rewardPackAmount\" value=\"${Number(cfg('rewardPackAmount') || 88)}\"></div>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">每通过几轮专注给一次奖励</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rewardEveryRounds\" value=\"${Number(cfg('rewardEveryRounds') || 3)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">连续作息奖励（天）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.streakNextMile\" value=\"${nextMile(sleepStreak())}\"></div>\n    </div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${cfg('rewardWallpaper') ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"rewardWallpaper\">领取时附赠留念壁纸</button>\n      <button class=\"chip ${cfg('rewardOnStreak') ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"rewardOnStreak\">连续规律作息达标时给奖励</button>\n    </div>\n  </div>\n  <div class=\"card\"><h3>已领取的奖励（${done.length}）</h3>\n    ${done.length ? done.slice(0, 20).map(r => `<div class=\"card tight\">\n      <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(r.at))} · ${esc(REWARD_KIND_LABEL[r.kind] || '奖励')}${r.reason ? ' · ' + esc(r.reason) : ''}</span>\n        <span class=\"pill ${r.proof ? 'ok' : ''}\">${r.proof ? (r.proofFromAi ? '凭证（补生成）' : '已抓取凭证') : '待领取'}</span></div>\n      <div class=\"row mt6\">${charAvatar(charById(r.charId))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.2px\">\n        <div class=\"who\">${esc(charName(r.charId))} · 原话</div>${esc(r.proof || r.line || '（还没回复）')}</div></div>\n      ${r.taskText ? `<div class=\"tiny mt6\" style=\"color:var(--dim2)\">已写进聊天室的申请：${esc(String(r.taskText).slice(0, 56))}…</div>` : ''}\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn sm ghost grow\" data-act=\"openRewardChat\" data-id=\"${esc(r.id)}\">打开聊天室</button>\n        ${r.wallId ? `<button class=\"btn sm ghost grow\" data-act=\"albumOpen\" data-id=\"${esc(r.wallId)}\">看留念壁纸</button>` : ''}</div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:10px\">还没有领取过奖励</div>`}</div>`;\n};\n/* ==========================================================\n   视图 · 收藏夹（文件夹可多层）\n   ========================================================== */\nconst FAV_ICON = { text: '💬', image: '🖼', audio: '🔊', story: '🌙', report: '📄', wall: '🖼', msg: '💬' };\nVIEWS.fav = function () {\n  const cur = S.draft.favCur || '';\n  const path = favPath(cur);\n  const kids = favChildren(cur);\n  const folders = kids.filter(x => x.kind === 'folder');\n  const items = kids.filter(x => x.kind !== 'folder');\n  const totalItems = favAll().filter(f => f.kind !== 'folder').length;\n  const totalFolders = favAll().filter(f => f.kind === 'folder').length;\n  return `<div class=\"card\">\n    <div class=\"row between\"><h3>⭐ 收藏夹</h3><span class=\"tiny\">${totalItems} 条 · ${totalFolders} 个文件夹</span></div>\n    <div class=\"row wrap mt10\" style=\"gap:6px;align-items:center\">\n      <button class=\"chip ${cur ? '' : 'on'}\" data-act=\"favOpen\" data-id=\"\">收藏夹</button>\n      ${path.map(f => `<span class=\"tiny\">›</span><button class=\"chip ${String(f.id) === String(cur) ? 'on' : ''}\" data-act=\"favOpen\" data-id=\"${esc(f.id)}\">${esc(f.name)}</button>`).join('')}\n    </div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"favNewFolder\">＋ 新建文件夹</button>\n      <button class=\"btn sm grow\" data-act=\"favNewNote\">＋ 记一条</button>\n    </div>\n    ${cur ? `<button class=\"btn sm ghost block mt8\" data-act=\"favOpen\" data-id=\"${esc((path[path.length - 2] || {}).id || '')}\">↑ 返回上一层</button>` : ''}\n    <div class=\"tiny mt6\">当前目录：${cur ? esc(favName(cur)) : '收藏夹根目录'}。文件夹能一层层往下建，条目可以用「移动」换到别的文件夹；删文件夹会连里面的东西一起删。</div>\n  </div>\n  ${folders.length ? `<div class=\"card\"><h3>文件夹（${folders.length}）</h3>\n    ${folders.map(f => `<div class=\"item\"><div class=\"ic\">📁</div>\n      <div class=\"grow\" data-act=\"favOpen\" data-id=\"${esc(f.id)}\" style=\"cursor:pointer\">\n        <div style=\"font-size:13.5px\">${esc(f.name)}</div>\n        <div class=\"tiny\">${favCountIn(f.id)} 项 · ${dkey(new Date(f.at))}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"favRen\" data-id=\"${esc(f.id)}\">改名</button>\n      <button class=\"btn sm ghost\" data-act=\"favDel\" data-id=\"${esc(f.id)}\">删</button></div>`).join('')}\n  </div>` : ''}\n  ${items.length ? `<div class=\"card\"><h3>条目（${items.length}）</h3>\n    ${items.map(x => `<div class=\"item\"><div class=\"ic\">${FAV_ICON[x.type] || '📌'}</div>\n      <div class=\"grow\" data-act=\"favView\" data-id=\"${esc(x.id)}\" style=\"cursor:pointer\">\n        <div style=\"font-size:13px\">${esc(x.name)}</div>\n        <div class=\"tiny ellip\">${esc(String(x.content || '').replace(/\\n/g, ' ').slice(0, 54)) || (x.ref ? '（媒体文件）' : '')}</div>\n        <div class=\"tiny\">${dkey(new Date(x.at))}${x.charId ? ' · ' + esc(charName(x.charId)) : ''}${x.from ? ' · 来自' + esc(x.from) : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"favMove\" data-id=\"${esc(x.id)}\">移动</button>\n      <button class=\"btn sm ghost\" data-act=\"favDel\" data-id=\"${esc(x.id)}\">删</button></div>`).join('')}\n  </div>` : (!folders.length ? `<div class=\"empty\">这个文件夹还是空的。<br>可以从「生成记录」「壁纸库」「睡前闲聊」「睡眠报告」「睡前故事」里点 ⭐ 收藏进来，也可以在这里自己记一条。</div>` : '')}`;\n};\nObject.assign(ACTIONS, {\n  favOpen: async el => { S.draft.favCur = el.dataset.id || ''; render(); window.scrollTo(0, 0); },\n  favNewFolder: () => {\n    openSheet(`<h3>新建文件夹</h3>\n      <label class=\"fl\">名字</label><input class=\"input\" id=\"favDirName\" placeholder=\"例如：哄睡语音 / 喜欢的台词 / 专注壁纸\">\n      <div class=\"tiny mt6\">会建在「${S.draft.favCur ? esc(favName(S.draft.favCur)) : '收藏夹根目录'}」下面。</div>\n      <button class=\"btn primary block mt12\" data-act=\"favNewFolderSave\">创建</button>`);\n  },\n  favNewFolderSave: async () => {\n    const n = (document.getElementById('favDirName').value || '').trim();\n    if (!n) { toast('请填一个名字'); return; }\n    await favSave({ kind: 'folder', parentId: S.draft.favCur || '', name: n, at: Date.now() });\n    closeAllSheets(); toast('已新建文件夹：' + n); render();\n  },\n  favNewNote: () => {\n    openSheet(`<h3>记一条</h3>\n      <label class=\"fl\">标题</label><input class=\"input\" id=\"favNoteTitle\" placeholder=\"例如：今天 TA 说的那句话\">\n      <label class=\"fl\">内容</label><textarea id=\"favNoteBody\" style=\"min-height:140px\" placeholder=\"粘贴或写点什么\"></textarea>\n      <div class=\"tiny mt6\">会存到「${S.draft.favCur ? esc(favName(S.draft.favCur)) : '收藏夹根目录'}」。</div>\n      <button class=\"btn primary block mt12\" data-act=\"favNewNoteSave\">保存</button>`);\n  },\n  favNewNoteSave: async () => {\n    const t = (document.getElementById('favNoteTitle').value || '').trim();\n    const b = (document.getElementById('favNoteBody').value || '').trim();\n    if (!t && !b) { toast('至少写点内容'); return; }\n    await favSave({ kind: 'item', parentId: S.draft.favCur || '', name: t || (b.slice(0, 14) + '…'), type: 'text', content: b, at: Date.now(), from: '手动记录' });\n    closeAllSheets(); toast('已收藏'); render();\n  },\n  favRen: el => {\n    const f = favAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!f) return;\n    openSheet(`<h3>重命名</h3><input class=\"input\" id=\"favRenName\" value=\"${esc(f.name)}\">\n      <button class=\"btn primary block mt12\" data-act=\"favRenSave\" data-id=\"${esc(f.id)}\">保存</button>`);\n  },\n  favRenSave: async el => {\n    const f = favAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!f) return;\n    const n = (document.getElementById('favRenName').value || '').trim();\n    if (!n) { toast('名字不能空'); return; }\n    f.name = n; await favSave(f); closeAllSheets(); render();\n  },\n  favDel: async el => {\n    const f = favAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!f) return;\n    const ok = await confirmBox('删除收藏？', f.kind === 'folder'\n      ? '「' + f.name + '」里的 ' + favCountIn(f.id) + ' 项内容都会一起删掉，不可恢复。'\n      : '「' + f.name + '」将被删除，不可恢复。', '删除');\n    if (!ok) return;\n    if (f.ref) await sdk(() => API.media.delete({ ref: f.ref }), null);\n    await favRemove(f);\n    closeAllSheets(); toast('已删除'); render();\n  },\n  favMove: el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    const opts = favFolderOptions(x.kind === 'folder' ? x.id : '');\n    openSheet(`<h3>移动到…</h3>\n      <div class=\"tiny\">现在在「${x.parentId ? esc(favName(x.parentId)) : '收藏夹根目录'}」</div>\n      <div class=\"chips mt10\">\n        <button class=\"chip ${(x.parentId || '') === '' ? 'on' : ''}\" data-mv=\"\">收藏夹（根目录）</button>\n        ${opts.map(o => `<button class=\"chip ${String(x.parentId || '') === String(o.id) ? 'on' : ''}\" data-mv=\"${esc(o.id)}\">${'　'.repeat(o.depth)}📁 ${esc(o.name)}</button>`).join('')}\n      </div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"favMoveTo\" data-id=\"${esc(x.id)}\">移过去</button></div>`);\n    const w = modalStack[modalStack.length - 1];\n    if (w) w.dataset.target = x.parentId || '';\n    let target = x.parentId || '';\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-mv]'); if (!b) return;\n      target = b.dataset.mv;\n      w.dataset.target = target;\n      w.querySelectorAll('[data-mv]').forEach(y => y.classList.toggle('on', y === b));\n    });\n  },\n  favMoveTo: async el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    const w = modalStack[modalStack.length - 1];\n    const target = (w && w.dataset.target) || '';\n    x.parentId = target; await favSave(x);\n    closeAllSheets(); toast('已移动到「' + (target ? favName(target) : '收藏夹根目录') + '」'); render();\n  },\n  favView: async el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    let img = '', audio = false;\n    if (x.ref) {\n      const g = await sdk(() => API.media.get({ ref: x.ref }), null);\n      if (g && g.dataUrl) {\n        /* 引用里装的到底是音频还是图片，要按真实数据判断 ——\n           以前不区分，把音频塞进 <img> 会显示成一张空图，文字还被顶掉了 */\n        if (String(x.type) === 'audio' || /^data:audio|^data:application\\/octet-stream/i.test(String(g.dataUrl))) audio = true;\n        else img = String(g.dataUrl);\n      }\n    }\n    else if (x.type === 'image' && /^data:image/.test(String(x.content || ''))) img = String(x.content);\n    openSheet(`<h3>${esc(x.name)}</h3>\n      <div class=\"tiny\">${dkey(new Date(x.at))}${x.charId ? ' · ' + esc(charName(x.charId)) : ''}${x.from ? ' · 来自' + esc(x.from) : ''}${audio ? ' · 🔊 语音' : ''}</div>\n      ${img ? `<img src=\"${img}\" style=\"width:100%;border-radius:12px;margin-top:10px;display:block\" alt=\"\">` : ''}\n      ${(x.content && (!img || audio)) ? `<div style=\"font-size:13.5px;line-height:1.85;white-space:pre-wrap;background:var(--card2);border-radius:10px;padding:12px;margin-top:10px;max-height:46vh;overflow:auto\">${esc(x.content)}</div>` : ''}\n      <div class=\"row mt12\" style=\"gap:8px\">\n        ${x.ref ? `<button class=\"btn grow\" data-act=\"favPlay\" data-id=\"${esc(x.id)}\">🔊 播放</button>` : ''}\n        ${img ? `<button class=\"btn grow\" data-act=\"favSaveImg\" data-id=\"${esc(x.id)}\">💾 保存图片</button>` : ''}\n        <button class=\"btn ghost grow\" data-act=\"favCopy\" data-id=\"${esc(x.id)}\">复制文字</button></div>\n      <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"favMove\" data-id=\"${esc(x.id)}\">移到别的文件夹</button>\n        <button class=\"btn ghost grow\" data-act=\"favDel\" data-id=\"${esc(x.id)}\">删除</button></div>`);\n  },\n  favPlay: async el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x || !x.ref) { toast('这条没有音频文件'); return; }\n    const ok = await playRef(x.ref);\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  favSaveImg: async el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    let img = '';\n    if (x.ref) { const g = await sdk(() => API.media.get({ ref: x.ref }), null); if (g && g.dataUrl) img = g.dataUrl; }\n    else if (/^data:image/.test(String(x.content || ''))) img = String(x.content);\n    if (!img) { toast('这条没有图片'); return; }\n    saveImageAnywhere(img, (x.name || 'fav') + '.png', x.name, x.charId || anyCharId());\n  },\n  favCopy: async el => {\n    const x = favAll().find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    try {\n      const ta = document.createElement('textarea');\n      ta.value = String(x.content || '');\n      document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove();\n      toast('已复制');\n    } catch (e) { toast('复制失败，请长按选择文本'); }\n  },\n  /* 收藏面板的保存 / 新建文件夹 */\n  favPickSave: async () => {\n    const p = S.favPending || {};\n    const box = document.getElementById('favTitle');\n    const title = (box && box.value ? box.value : '').trim() || p.title || '未命名收藏';\n    await favSave({\n      kind: 'item', parentId: S.favPickDir || '', name: title, type: p.kind || 'text',\n      content: p.content || '', ref: p.ref || '', charId: p.charId || '', from: p.from || '', at: Date.now()\n    });\n    closeAllSheets();\n    toast('已收藏到「' + (S.favPickDir ? favName(S.favPickDir) : '收藏夹') + '」');\n    S.favPending = null;\n  },\n  favPickNewDir: () => {\n    openSheet(`<h3>新建文件夹</h3>\n      <label class=\"fl\">名字</label><input class=\"input\" id=\"favPickDirName\" placeholder=\"例如：喜欢的台词\">\n      <div class=\"tiny mt6\">会建在「${S.favPickDir ? esc(favName(S.favPickDir)) : '收藏夹根目录'}」下面。</div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"favPickNewDirSave\">建好并选中</button></div>`);\n  },\n  favPickNewDirSave: async () => {\n    const n = (document.getElementById('favPickDirName').value || '').trim();\n    if (!n) { toast('请填一个名字'); return; }\n    const keep = S.favPending;\n    const t = document.getElementById('favTitle');\n    if (keep && t) keep.title = (t.value || keep.title || '').trim();\n    const saved = await favSave({ kind: 'folder', parentId: S.favPickDir || '', name: n, at: Date.now() });\n    closeAllSheets();\n    if (saved) S.favPickDir = saved.id;\n    toast('文件夹已建好：' + n);\n    if (keep) openFavPicker(keep);\n  }\n});\n/* ==========================================================\n   视图 · 生成记录（本 APP 所有大模型调用留档）\n   ========================================================== */\nconst GEN_TABS = [['all', '全部'], ['text', '💬 消息'], ['voice', '🔊 语音'], ['image', '🖼 壁纸']];\nfunction genTagOf(x) { return x.tag === 'image' ? 'image' : (x.tag === 'voice' ? 'voice' : 'text'); }\nVIEWS.genlog = function () {\n  const all = S.gen || [];\n  const tab = S.draft.genTab || 'all';\n  const list = tab === 'all' ? all : all.filter(x => genTagOf(x) === tab);\n  const n = t => all.filter(x => genTagOf(x) === t).length;\n  return `<div class=\"card\">\n    <div class=\"row between\"><h3>生成记录（${all.length}）</h3>\n      <button class=\"btn sm ghost\" data-act=\"genClear\" ${all.length ? '' : 'disabled'}>清空</button></div>\n    <div class=\"sub\">只留「实际产出的内容」：角色说过的每句话、读出来的每段语音、每张壁纸用的生图提示词。点开可以看全文、复制、收藏到收藏夹。<b>语音类可以在这里直接复听、循环读</b> —— 存过音频的不用重新合成。</div>\n    ${S.voiceLoop ? `<div class=\"tiny mt8\" style=\"background:var(--accent-soft);border-radius:10px;padding:9px;color:#c9cfff\">🔁 <span data-vloop=\"1\"></span>\n      <button class=\"btn sm ghost\" style=\"min-height:28px;padding:0 9px;margin-left:6px\" data-act=\"voiceLoopStop\">停止循环</button></div>` : ''}\n    <div class=\"chips mt10\">${GEN_TABS.map(([k, lb]) => `<button class=\"chip ${tab === k ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"genTab\" data-v=\"${k}\">${lb} ${k === 'all' ? all.length : n(k)}</button>`).join('')}</div>\n    ${(tab === 'voice' || tab === 'all') && n('voice') ? `<div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"genLoopRecent\" data-n=\"5\">🔁 循环最近 5 条语音</button>\n      <button class=\"btn sm ghost grow\" data-act=\"genLoopRecent\" data-n=\"10\">最近 10 条</button></div>` : ''}\n    <div class=\"tiny mt6\">最多保留最近\n      <input class=\"input\" style=\"display:inline-block;width:72px;padding:3px 6px;min-height:auto\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.genLogKeep\" value=\"${Number(cfg('genLogKeep') || 200)}\"> 条（超出的自动删最旧）</div></div>\n  ${list.length ? list.slice(0, 80).map(x => {\n    const tg = genTagOf(x);\n    return `<div class=\"card tight\">\n    <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(x.at))} ${hm(x.at)} · ${tg === 'image' ? '🖼 生图提示词' : tg === 'voice' ? '🔊 语音' : '💬 消息'}${x.ms ? ' · ' + (x.ms / 1000).toFixed(1) + 's' : ''}</span>\n      <span class=\"pill ${x.err ? 'bad' : 'ok'}\">${x.err ? '失败' : (x.name || '')}</span></div>\n    <div class=\"tiny mt6\" style=\"max-height:4.6em;overflow:hidden;line-height:1.6\">${esc(String(x.out || '（空）').slice(0, 140))}</div>\n    <div class=\"row between mt6\"><span class=\"tiny\">${esc(x.name || '')}</span>\n      <span class=\"tiny\">${(x.charIds || []).map(id => esc(charName(id))).join('、') || '—'}</span></div>\n    ${tg === 'voice' ? `<div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm grow ${x.ref ? '' : 'ghost'}\" data-act=\"genReplay\" data-id=\"${esc(x.id)}\" ${x.ref ? '' : 'disabled'}>${x.ref ? '🔊 复听这句' : '（这条没有音频）'}</button>\n      <button class=\"btn sm ${S.voiceLoop && S.voiceLoop.oneId === x.id ? 'primary' : 'ghost'}\" data-act=\"genLoopOne\" data-id=\"${esc(x.id)}\" ${x.ref ? '' : 'disabled'}>${S.voiceLoop && S.voiceLoop.oneId === x.id ? '⏹ 停循环' : '🔁 循环这句'}</button></div>` : ''}\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"genOpen\" data-id=\"${esc(x.id)}\">看全文</button>\n      <button class=\"btn sm ghost\" data-act=\"genFav\" data-id=\"${esc(x.id)}\">⭐</button>\n      <button class=\"btn sm ghost\" data-act=\"genDel\" data-id=\"${esc(x.id)}\">删</button></div></div>`;\n  }).join('')\n      : `<div class=\"empty\">这一类还没有记录。<br>角色说过的每句话、读出的语音、生图提示词都会自动记在这里。</div>`}`;\n};\nObject.assign(ACTIONS, {\n  /* ---- 语音留档：复听 / 循环读 ---- */\n  genReplay: async el => {\n    const x = genById(el.dataset.id);\n    if (!x) return;\n    if (!x.ref) { toast('这条没有留下音频文件（当时可能没配好语音服务）'); return; }\n    const ok = await playVoiceRefOnce(x.ref);\n    if (!ok) toast('播不出来：先在「设置 → 语音」里配好语音服务');\n  },\n  genLoopOne: async el => {\n    const x = genById(el.dataset.id);\n    if (!x) return;\n    if (!x.ref) { toast('这条没有留下音频文件，没法循环'); return; }\n    if (S.voiceLoop && S.voiceLoop.oneId === x.id) { voiceLoopStop(); return; }\n    stopVoice();\n    S.voiceLoop = { refs: [x.ref], i: 0, oneId: x.id, label: (x.name || '') + ' · ' + String(x.out || '').slice(0, 16) };\n    render();\n    if (voiceLoopRunning) return;\n    voiceLoopRunning = true;\n    while (S.voiceLoop && S.voiceLoop.oneId === x.id) {\n      const ok = await playVoiceRefOnce(S.voiceLoop.refs[0]);\n      if (!ok) { toast('播不出来：先在「设置 → 语音」里配好语音服务'); S.voiceLoop = null; break; }\n      if (!S.voiceLoop || S.voiceLoop.oneId !== x.id) break;\n      await new Promise(r => setTimeout(r, voiceGap()));   // 句间留一点气口，不会听着像卡带\n    }\n    voiceLoopRunning = false;\n    render();\n  },\n  /* 把最近 N 条语音串成一个循环读的队列 */\n  genLoopRecent: async el => {\n    const n = clamp(Number((el && el.dataset && el.dataset.n) || 5), 1, 30);\n    const list = voiceLogs().filter(x => x.ref).slice(0, n);\n    if (!list.length) { toast('最近还没有存下音频的语音'); return; }\n    stopVoice();\n    S.voiceLoop = { refs: list.map(x => x.ref), i: 0, label: '最近 ' + list.length + ' 条', oneId: '' };\n    render();\n    if (voiceLoopRunning) return;\n    voiceLoopRunning = true;\n    while (S.voiceLoop && !S.voiceLoop.oneId) {\n      const cur = S.voiceLoop;\n      const ok = await playVoiceRefOnce(cur.refs[cur.i % cur.refs.length]);\n      if (!ok) { toast('播不出来：先在「设置 → 语音」里配好语音服务'); S.voiceLoop = null; break; }\n      if (!S.voiceLoop || S.voiceLoop !== cur) break;\n      cur.i = cur.refs.length > 1 ? (cur.i + 1) % cur.refs.length : 0;\n      paintVoiceLoop();\n      await new Promise(r => setTimeout(r, voiceGap()));\n    }\n    voiceLoopRunning = false;\n    render();\n  },\n  voiceLoopStop: () => { voiceLoopStop(); },\n  genOpen: el => {\n    const x = (S.gen || []).find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    const tg = genTagOf(x);\n    const w = openSheet(`<h3>${esc(x.name || x.kind || '生成记录')}</h3>\n      <div class=\"tiny\">${dkey(new Date(x.at))} ${hm(x.at)} · ${tg === 'image' ? '生图提示词' : tg === 'voice' ? '语音' : '消息'}${x.ms ? ' · 耗时 ' + (x.ms / 1000).toFixed(1) + ' 秒' : ''} · 角色：${(x.charIds || []).map(id => esc(charName(id))).join('、') || '—'}</div>\n      <div style=\"font-size:13.5px;line-height:1.8;white-space:pre-wrap;background:var(--card2);border-radius:10px;padding:12px;margin-top:8px;max-height:46vh;overflow:auto\">${esc(x.err ? ('❌ ' + (x.out || '') + '\\n' + x.err) : (x.out || '（空）'))}</div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"genCopy\" data-id=\"${esc(x.id)}\">复制内容</button>\n        <button class=\"btn grow\" data-act=\"genFav\" data-id=\"${esc(x.id)}\">⭐ 收藏</button>\n        <button class=\"btn primary grow\" data-act=\"closeSheet\">关闭</button></div>\n      ${tg === 'voice' ? `<div class=\"row mt8\" style=\"gap:8px\">\n        <button class=\"btn grow ${x.ref ? '' : 'ghost'}\" data-act=\"genReplay\" data-id=\"${esc(x.id)}\" ${x.ref ? '' : 'disabled'}>${x.ref ? '🔊 复听这句' : '（这条没有音频）'}</button>\n        <button class=\"btn ${S.voiceLoop && S.voiceLoop.oneId === x.id ? 'primary' : 'ghost'}\" data-act=\"genLoopOne\" data-id=\"${esc(x.id)}\" ${x.ref ? '' : 'disabled'}>${S.voiceLoop && S.voiceLoop.oneId === x.id ? '⏹ 停' : '🔁 循环'}</button></div>` : ''}\n      <button class=\"btn block ghost sm mt8\" data-act=\"genTogglePrompt\" data-id=\"${esc(x.id)}\">看这次用的提示词（调试用）</button>\n      <div class=\"tiny mt6\" id=\"genPromptBox\" style=\"display:none;white-space:pre-wrap;line-height:1.7;background:var(--card2);border-radius:10px;padding:10px;max-height:34vh;overflow:auto\">${esc(x.instruction || '（这条没有记录提示词）')}</div>`);\n  },\n  genCopy: el => {\n    const x = (S.gen || []).find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    const txt = '【' + (x.name || '') + '】' + dkey(new Date(x.at)) + ' ' + hm(x.at) + '\\n--- 提示词 ---\\n' + (x.instruction || '') + '\\n--- 返回 ---\\n' + (x.err ? ('[失败] ' + x.err) : (x.out || ''));\n    try {\n      const ta = document.createElement('textarea');\n      ta.value = txt; document.body.appendChild(ta); ta.select();\n      document.execCommand('copy'); ta.remove();\n      toast('已复制到剪贴板');\n    } catch (e) { toast('复制失败，请长按选择文本'); }\n  },\n  genDel: async el => {\n    await DB.remove(T.GEN, el.dataset.id);\n    S.gen = (S.gen || []).filter(x => String(x.id) !== String(el.dataset.id));\n    render();\n  },\n  genTogglePrompt: () => {\n    const b = document.getElementById('genPromptBox');\n    if (b) b.style.display = b.style.display === 'none' ? 'block' : 'none';\n  },\n  genFav: el => {\n    const x = (S.gen || []).find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    const tg = genTagOf(x);\n    /* 语音类必须把音频引用一起带过去：只存文字的话，收藏夹里就只剩一段文字，\n       点开也没有「播放」按钮 —— 看起来就是「收藏之后不是语音了」。\n       没有音频引用（当时没合成成功）的仍按文字收藏，别给一个按不动的播放键。 */\n    const asVoice = (tg === 'voice') && !!x.ref;\n    openFavPicker({\n      kind: tg === 'image' ? 'image' : (asVoice ? 'audio' : 'text'),\n      title: (x.name || '生成内容') + ' · ' + dkey(new Date(x.at)),\n      content: x.out || '', ref: asVoice ? String(x.ref) : '',\n      charId: (x.charIds || [])[0] || '', from: '生成记录'\n    });\n  },\n  genClear: async () => {\n    const ok = await confirmBox('清空生成记录？', '所有已留档的提示词与输出都会被删除，不可恢复。', '清空');\n    if (!ok) return;\n    for (const x of (S.gen || [])) if (x.id) await DB.remove(T.GEN, x.id);\n    S.gen = []; toast('已清空生成记录'); render();\n  }\n});\n/* ==========================================================\n   视图 · 答疑助手（专用窗口，全部记录留存）\n   · 普通模式：不扮演角色，就是个学习助手（qa.assistant）\n   · 角色模式：由陪伴角色以人设回答（qa.answer）\n   ========================================================== */\nfunction qaModeNow() { return cfg('qaMode') === 'companion' ? 'companion' : 'assistant'; }\nVIEWS.qa = function () {\n  const mode = qaModeNow();\n  const list = S.qa || [];\n  const pend = S.draft.qaPending || '';\n  const cid = anyCharId();\n  const favN = list.filter(x => x.fav).length;\n  return `\n  <div class=\"card hero-soft\"><div class=\"row between\"><div class=\"grow\"><h3>❓ 答疑助手</h3>\n      <div class=\"tiny mt6\">把所有问题都问在这里 —— 会完整留存（连同答案），随时回看、收藏、发到聊天室。</div></div>\n      <div style=\"font-size:30px\">🧑‍🏫</div></div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${mode === 'assistant' ? 'on' : ''}\" data-act=\"qaMode\" data-v=\"assistant\">🧑‍🏫 普通 AI（不扮演，纯讲题）</button>\n      <button class=\"chip ${mode === 'companion' ? 'on' : ''}\" data-act=\"qaMode\" data-v=\"companion\" ${cid ? '' : 'disabled'}>💞 让 ${esc(cid ? charName(cid) : '角色')} 来答</button>\n    </div>\n    <div class=\"tiny mt6\">${mode === 'assistant'\n      ? '当前由普通 AI 回答：直接给结论与思路，不带人设、不扮演角色，适合讲题和概念。<br>（说明：优先走宿主的通用模型通道；这台小手机若没提供该通道，会自动退回「借角色通道、但明确要求忽略人设」，回答依然不会用角色的语气。）'\n      : '当前由 ' + esc(cid ? charName(cid) : '角色') + ' 以他的人设回答，适合你更想听他说的时候。'}</div>\n  </div>\n  <div class=\"card\">\n    <label class=\"fl\">问一个问题（可以贴题目原文）</label>\n    <textarea id=\"qaInput\" data-in=\"qaDraft\" style=\"min-height:110px\" placeholder=\"例如：资料分析里的「增长率」和「增长量」怎么快速区分？给我举个例。\">${esc(S.draft.qaDraft || '')}</textarea>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" style=\"min-height:46px\" data-act=\"qaAsk\" ${S.busy === 'qa' ? 'disabled' : ''}>${S.busy === 'qa' ? '正在解答…' : '发送问题'}</button>\n      <button class=\"btn ghost\" data-act=\"qaClearDraft\" ${S.draft.qaDraft ? '' : 'disabled'}>清空</button></div>\n    ${S.busy === 'qa' ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> 正在解答，完成后才能再问下一题。</div>` : ''}\n  </div>\n  ${(pend || S.draft.qaAnswer) ? `<div class=\"card\">\n    <div class=\"msg me\"><div class=\"bd\">${esc(pend || S.draft.qaLastQ || '')}</div></div>\n    ${S.draft.qaAnswer\n      ? `<div class=\"msg\">${mode === 'companion' ? charAvatar(charById(anyCharId())) : '<div class=\"avatar\" style=\"background:linear-gradient(135deg,#3ddad0,#4fb3ff)\">师</div>'}\n          <div class=\"bd\"><div class=\"who\">${mode === 'companion' ? esc(charName(anyCharId())) : '学习助手'} · ${hm(Date.now())}</div>${esc(S.draft.qaAnswer).replace(/\\n/g, '<br>')}</div></div>`\n      : `<div class=\"msg\"><div class=\"bd\"><span class=\"spin\"></span> 正在想…</div></div>`}\n  </div>` : ''}\n  <div class=\"card\"><div class=\"row between\"><h3>问答记录（${list.length}）</h3>\n      ${favN ? `<span class=\"tiny\">已收藏 ${favN} 条</span>` : ''}</div>\n    <div class=\"tiny mt6\">所有提问与解答都会留在这里（存在本机，导出备份时一起带走）。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"genlog\">🧾 生成记录</button>\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"fav\">⭐ 收藏夹</button>\n      <button class=\"btn sm ghost\" data-act=\"qaClear\" ${list.length ? '' : 'disabled'}>清空记录</button></div></div>\n  ${list.length ? list.slice(0, 60).map(r => `<div class=\"card tight\">\n    <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(r.at))} ${hm(r.at)} · ${r.mode === 'companion' ? esc(charName(r.charId)) : '普通 AI'}${r.fav ? ' · ⭐' : ''}</span>\n      <span class=\"row\" style=\"gap:5px\">\n        <button class=\"btn sm ghost\" data-act=\"qaFav\" data-id=\"${esc(r.id)}\">${r.fav ? '取消收藏' : '⭐'}</button>\n        <button class=\"btn sm ghost\" data-act=\"qaToChat\" data-id=\"${esc(r.id)}\">发到聊天</button>\n        <button class=\"btn sm ghost\" data-act=\"qaDel\" data-id=\"${esc(r.id)}\">删</button></span></div>\n    <div class=\"msg me\" style=\"margin:8px 0 6px\"><div class=\"bd\" style=\"max-width:92%\">${esc(r.q)}</div></div>\n    <div style=\"font-size:13.4px;line-height:1.8;white-space:pre-wrap\">${esc(r.a || '（没有答案）').replace(/\\n/g, '<br>')}</div></div>`).join('')\n      : `<div class=\"empty\">还没有提问记录。<br>上面写一个问题试试 —— 普通 AI 模式只讲题，不扮演角色。</div>`}`;\n};\nObject.assign(ACTIONS, {\n  qaMode: async el => {\n    S.settings.qaMode = el.dataset.v === 'companion' ? 'companion' : 'assistant';\n    await saveSettings(true);\n    toast(S.settings.qaMode === 'assistant' ? '已切到普通 AI：不扮演角色' : '已切到角色答疑');\n    render();\n  },\n  qaClearDraft: () => { S.draft.qaDraft = ''; render(); },\n  qaAsk: async () => {\n    if (S.busy === 'qa') { toast('正在解答，稍等一下'); return; }\n    const box = document.getElementById('qaInput');\n    const q = box ? String(box.value || '').trim() : String(S.draft.qaDraft || '').trim();\n    if (!q) { toast('先写一个问题'); return; }\n    const mode = qaModeNow();\n    /* 两种模式都用同一个「角色通道」：宿主的 ai.generate 必须先有角色才能解析模型与 API 配置，\n       所以这里必须带上一个角色 id；普通模式下我们只是借它走通生成，提示词里明确要求忽略人设。 */\n    const cid = anyCharId();\n    if (!cid) { toast('请先在「我的 → 选择陪伴角色」里选一位角色（普通模式只是借它走通生成，不会用他的人设说话）'); return; }\n    S.draft.qaDraft = ''; S.draft.qaPending = q; S.draft.qaAnswer = ''; S.draft.qaLastQ = q;\n    S.busy = 'qa'; render();\n    let text = '';\n    try {\n      text = await pGen(mode === 'companion' ? 'qa.answer' : 'qa.assistant', { question: q }, [cid], undefined, mode !== 'companion');\n    } catch (e) { text = ''; }\n    S.busy = '';\n    if (!text) {\n      S.draft.qaPending = '';\n      S.draft.qaDraft = q;\n      toast('没拿到回答：检查 API 配置或稍后重试');\n      render(); return;\n    }\n    text = String(text).trim();\n    const rec = { q: q, a: text, at: Date.now(), mode: mode, charId: cid, fav: false };\n    const r = await DB.create(T.QA, rec);\n    if (r) rec.id = r.id;\n    S.qa = [rec].concat(S.qa || []);\n    S.draft.qaPending = ''; S.draft.qaAnswer = text;\n    if (mode === 'companion') await syncChatLine(cid, '（答疑）' + text.slice(0, 120), 'assistant');\n    toast('已解答并留档');\n    render();\n  },\n  qaFav: async el => {\n    const r = (S.qa || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!r) return;\n    r.fav = !r.fav;\n    await DB.update(T.QA, r.id, JSON.parse(JSON.stringify(r)));\n    toast(r.fav ? '已收藏' : '已取消收藏');\n    render();\n  },\n  qaDel: async el => {\n    await DB.remove(T.QA, el.dataset.id);\n    S.qa = (S.qa || []).filter(x => St",
  "ring(x.id) !== String(el.dataset.id));\n    render();\n  },\n  qaClear: async () => {\n    const ok = await confirmBox('清空答疑记录？', '所有提问与答案都会被删除，不可恢复（建议先导出备份）。', '清空');\n    if (!ok) return;\n    for (const r of (S.qa || [])) if (r.id) await DB.remove(T.QA, r.id);\n    S.qa = []; toast('已清空'); render();\n  },\n  qaToChat: async el => {\n    const r = (S.qa || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!r) return;\n    const cid = r.charId || anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    await sdk(() => API.chat.writeHistory({\n      characterId: cid, role: 'system',\n      content: '[答疑] 问：' + r.q + '\\n答：' + String(r.a || '').slice(0, 600)\n    }), null);\n    toast('已发到聊天室');\n  }\n});\n/* ==========================================================\n   视图 · 改提示词（独立整页，写起来不受弹层干扰）\n   ========================================================== */\nVIEWS.promptedit = function () {\n  const id = S.draft.promptId, def = promptDef(id);\n  if (!def) return `<div class=\"card\"><h3>找不到这条提示词</h3>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"prompts\">回提示词列表</button></div>`;\n  const edited = isPromptEdited(id);\n  const vars = String(def.vars || '').split(/[,，\\s]+/).map(x => x.trim()).filter(Boolean);\n  return `\n  <div class=\"card\"><div class=\"row between\"><div class=\"grow\"><h3>${esc(def.n)}</h3>\n      <div class=\"tiny\">分组：${esc(def.g)} · 场景标签：${esc(def.tags || '（无）')}</div></div>\n      <span class=\"pill ${edited ? 'warn' : 'ok'}\">${edited ? '已自定义' : '默认'}</span></div>\n    <div class=\"tiny mt6\">生成时除了这段指令，宿主还会自动附上角色设定、人设与记忆，以及本 APP「${esc(def.tags || '无标签')}」的预设条目。</div>\n  </div>\n  <div class=\"card\">\n    <label class=\"fl\">提示词正文（直接改，写完点最下面的保存）</label>\n    <textarea id=\"promptBox\" data-in=\"promptDraft\" style=\"min-height:46vh;line-height:1.7\">${esc(S.draft.promptDraft != null ? S.draft.promptDraft : promptRaw(id))}</textarea>\n    ${vars.length ? `<div class=\"tiny mt8\">点一下就把变量插到光标处：</div>\n      <div class=\"chips mt6\">${vars.map(v => `<button class=\"chip\" data-act=\"promptInsertVar\" data-v=\"${esc(v)}\">{{${esc(v)}}}</button>`).join('')}</div>` : '<div class=\"tiny mt8\">这条没有变量。</div>'}\n    <div class=\"tiny mt6\">变量写成 {{名字}}，生成前会被真实数据替换 —— 不需要就删掉，但别改名字。</div>\n  </div>\n  <button class=\"btn primary block\" style=\"min-height:50px;font-size:15px\" data-act=\"savePrompt\" data-id=\"${esc(id)}\">保存这条提示词</button>\n  <div class=\"row mt10\" style=\"gap:8px\">\n    <button class=\"btn ghost grow\" data-act=\"promptShowDef\">${S.draft.promptShowDef ? '收起默认版本' : '看默认版本'}</button>\n    <button class=\"btn ghost grow\" data-act=\"resetPrompt\" data-id=\"${esc(id)}\" ${edited ? '' : 'disabled'}>恢复默认</button></div>\n  ${S.draft.promptShowDef ? `<div class=\"card mt10\"><div class=\"tiny\">默认版本（只读，可长按复制）</div>\n    <div style=\"font-size:12.8px;line-height:1.8;white-space:pre-wrap;background:var(--card2);border-radius:10px;padding:11px;margin-top:8px;max-height:44vh;overflow:auto\">${esc(def.def)}</div></div>` : ''}\n  <button class=\"btn block ghost sm mt10\" data-act=\"gotoView\" data-view=\"prompts\">← 回提示词列表</button>`;\n};\n/* ==========================================================\n   视图 · 提示词设置\n   ========================================================== */\nVIEWS.prompts = function () {\n  const groups = [];\n  PROMPT_DEFS.forEach(p => { if (groups.indexOf(p.g) < 0) groups.push(p.g); });\n  const edited = PROMPT_DEFS.filter(p => isPromptEdited(p.id)).length;\n  let html = `<div class=\"card\"><div class=\"row between\"><h3>提示词设置（${PROMPT_DEFS.length} 条）</h3>\n      <span class=\"pill ${edited ? 'warn' : 'ok'}\">${edited ? edited + ' 条已自定义' : '全部默认'}</span></div>\n    <div class=\"sub\">这里是本 APP 每一次让角色生成内容时用的指令。点「改」就能编辑文案；双花括号里的变量会在生成前被真实数据替换，请保留。</div>\n    <div class=\"tiny mt6\">生成时除了这些指令，宿主还会自动附上「设置 → 提示词预设」里适配本 APP 场景的条目（专注陪伴、出题校验、睡眠报告等），那部分也可以在预设里改。</div>\n    <button class=\"btn sm ghost block mt10\" data-act=\"resetAllPrompts\" ${edited ? '' : 'disabled'}>全部恢复默认</button></div>`;\n  groups.forEach(g => {\n    html += `<div class=\"card\"><h3>${esc(g)}</h3>` + PROMPT_DEFS.filter(p => p.g === g).map(p => `\n      <div class=\"item\"><div class=\"ic\">${isPromptEdited(p.id) ? '✏️' : '📄'}</div>\n        <div class=\"grow\"><div style=\"font-size:13px\">${esc(p.n)}</div>\n          <div class=\"tiny\">变量：${p.vars ? esc(p.vars) : '（无）'}</div></div>\n        <button class=\"btn sm ghost\" data-act=\"openPromptEdit\" data-id=\"${esc(p.id)}\">改</button>\n        ${isPromptEdited(p.id) ? `<button class=\"btn sm ghost\" data-act=\"resetPrompt\" data-id=\"${esc(p.id)}\">还原</button>` : ''}</div>`).join('') + `</div>`;\n  });\n  return html;\n};\nObject.assign(ACTIONS, {\n  /* 改成整页编辑：弹层在手机上会被键盘顶来顶去、点一下就来回伸缩，这里彻底避开 */\n  openPromptEdit: el => {\n    const id = el.dataset.id, def = promptDef(id);\n    if (!def) { toast('找不到这条提示词'); return; }\n    S.draft.promptId = id;\n    S.draft.promptDraft = promptRaw(id);\n    S.draft.promptShowDef = false;\n    if (S.view !== 'promptedit') S.draft.promptBack = S.view || 'prompts';\n    go('promptedit');\n  },\n  promptShowDef: () => { S.draft.promptShowDef = !S.draft.promptShowDef; render(); },\n  promptInsertVar: el => {\n    const name = el.dataset.v;\n    if (!name) return;\n    const box = document.getElementById('promptBox');\n    const token = '{{' + name + '}}';\n    if (box) {\n      const s0 = (box.selectionStart == null) ? box.value.length : box.selectionStart;\n      const s1 = (box.selectionEnd == null) ? box.value.length : box.selectionEnd;\n      box.value = box.value.slice(0, s0) + token + box.value.slice(s1);\n      S.draft.promptDraft = box.value;\n      try { box.focus(); box.setSelectionRange(s0 + token.length, s0 + token.length); } catch (e) { }\n    } else {\n      S.draft.promptDraft = (S.draft.promptDraft || '') + token;\n    }\n    toast('已插入 ' + token);\n  },\n  _openPromptSheetOld: el => {\n    const id = el.dataset.id, def = promptDef(id);\n    if (!def) return;\n    openSheet(`<h3>${esc(def.n)}</h3>\n      <div class=\"tiny\">可用变量：${def.vars ? esc(def.vars) : '（无）'} —— 写成 {{变量名}}，生成前会被替换掉。</div>\n      <textarea id=\"promptBox\" style=\"min-height:230px;margin-top:8px\">${esc(promptRaw(id))}</textarea>\n      <div class=\"tiny mt6\">场景标签（决定跟哪些预设条目一起进提示词）：${esc(def.tags || '（无）')}</div>\n      <div class=\"tiny mt6\">生成链路：角色设定／人设／记忆（宿主自动）+ 本 APP「${esc(def.tags || '无标签')}」预设条目 + 上面的指令。</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn ghost grow\" data-act=\"resetPrompt\" data-id=\"${esc(id)}\">恢复默认</button>\n        <button class=\"btn primary grow\" data-act=\"savePrompt\" data-id=\"${esc(id)}\">保存</button></div>`);\n  },\n  savePrompt: async el => {\n    const id = (el && el.dataset && el.dataset.id) || S.draft.promptId;\n    const def = promptDef(id);\n    if (!def) { toast('找不到这条提示词'); return; }\n    const box = document.getElementById('promptBox');\n    const v = box ? box.value : (S.draft.promptDraft || '');\n    if (!v || !v.trim()) { toast('内容不能为空；想还原请点「恢复默认」'); return; }\n    S.draft.promptDraft = v;\n    if (v === def.def) delete S.settings.prompts[id]; else S.settings.prompts[id] = v;\n    await saveSettings(true);\n    closeAllSheets(); toast('已保存，下一次生成就用新文案');\n    go(S.draft.promptBack || 'prompts');\n  },\n  resetPrompt: async el => {\n    const id = (el && el.dataset && el.dataset.id) || S.draft.promptId;\n    if (!id || !S.settings.prompts) return;\n    const def = promptDef(id);\n    delete S.settings.prompts[id];\n    await saveSettings(true);\n    S.draft.promptDraft = def ? def.def : '';\n    S.draft.promptShowDef = false;\n    toast('已恢复默认');\n    render();\n  },\n  resetAllPrompts: async () => {\n    const ok = await confirmBox('恢复全部默认提示词？', '你自定义过的所有提示词都会被还原成出厂文案。', '恢复默认');\n    if (!ok) return;\n    S.settings.prompts = {};\n    await saveSettings(true); toast('已全部恢复默认'); render();\n  }\n});\n/* ==========================================================\n   视图 · 错题本\n   ========================================================== */\nfunction mistakeList() { return (S.priv || []).filter(p => p.kind === 'mistake').sort((a, b) => b.at - a.at); }\nfunction mistakeQs() { return mistakeList().filter(m => m.q && (m.qType === 'fill' || (m.options || []).length >= 2)); }\nVIEWS.mistakes = function () {\n  const list = mistakeList(), P = S.practice;\n  if (P) {\n    if (P.graded) return `\n      <div class=\"card ${P.pass ? 'glow' : ''}\"><div class=\"center\"><div style=\"font-size:30px\">${P.pass ? '🎉' : '📕'}</div>\n        <div style=\"font-size:17px;font-weight:600;margin-top:6px\">重做完成 · 答对 ${P.right}/${P.total}</div>\n        <div class=\"tiny mt6\">${P.pass ? '这批错题已经掌握了，可以移出错题本。' : '还有没掌握的，再刷一遍吧。'}</div></div></div>\n      ${P.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n        ${qResultHTML(qx, i, P.answers)}\n        ${qx.explain ? `<div class=\"exp\">${esc(qx.explain)}</div>` : ''}</div>`).join('')}\n      <div class=\"row\" style=\"gap:9px\"><button class=\"btn ghost grow\" data-act=\"practiceMistakes\">再来一遍</button>\n        <button class=\"btn primary grow\" data-act=\"pracMastered\">答对的移出错题本</button></div>\n      <button class=\"btn block ghost sm mt10\" data-act=\"pracExit\">退出练习</button>`;\n    const answered = P.qs.filter((q, i) => P.answers[i] != null && String(P.answers[i]) !== '').length;\n    return `<div class=\"card\"><div class=\"row between\"><h3>重做错题</h3><span class=\"tiny\">${answered}/${P.qs.length}</span></div>\n      <div class=\"sub\">全部答完提交，立刻看到答案与解析。</div>\n      <div class=\"mt10\">${P.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n        ${qInputHTML(qx, i, P.answers, 'pracPick', 'pans')}</div>`).join('')}</div>\n      <button class=\"btn primary block\" data-act=\"pracSubmit\">提交答卷</button>\n      <button class=\"btn block ghost sm mt10\" data-act=\"pracExit\">退出练习</button></div>`;\n  }\n  const folders = (cfg('mistakeFolders') || []).slice();\n  const filter = S.draft.mFilter || 'all';\n  const shown = filter === 'all' ? list : (filter === 'none' ? list.filter(m => !m.folder) : list.filter(m => m.folder === filter));\n  const selMode = !!S.draft.mSelMode;\n  const sel = S.draft.mSel || {};\n  const selN = Object.keys(sel).length;\n  const cntOf = f => (f === 'all' ? list.length : (f === 'none' ? list.filter(m => !m.folder).length : list.filter(m => m.folder === f).length));\n  return `<div class=\"card\"><div class=\"row between\"><h3>错题本（${list.length}）</h3>\n      <button class=\"btn sm ${selMode ? 'primary' : 'ghost'}\" data-act=\"mBatch\" ${list.length ? '' : 'disabled'}>${selMode ? '完成选择' : '☑️ 批量'}</button></div>\n    <div class=\"sub\">专注校验、惩罚练习、壁纸解锁里答错的题会自动进来，连同正确答案与解析。角色看不到这里。每题都能写自己的要点备注，也能归类到文件夹。</div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${filter === 'all' ? 'on' : ''}\" data-act=\"mFilter\" data-v=\"all\">全部 ${cntOf('all')}</button>\n      <button class=\"chip ${filter === 'none' ? 'on' : ''}\" data-act=\"mFilter\" data-v=\"none\">未分类 ${cntOf('none')}</button>\n      ${folders.map(f => `<button class=\"chip ${filter === f ? 'on' : ''}\" data-act=\"mFilter\" data-v=\"${esc(f)}\">📁 ${esc(f)} ${cntOf(f)}</button>`).join('')}\n    </div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"mFolderNew\">＋ 新建文件夹</button>\n      ${selMode ? `<button class=\"btn sm grow\" data-act=\"mSelectAll\">${selN && selN >= shown.length ? '取消全选' : '全选'}</button>\n      <button class=\"btn sm warn grow\" data-act=\"mDelSel\" ${selN ? '' : 'disabled'}>删除 ${selN} 条</button>` : ''}\n    </div>\n    ${selMode ? `<div class=\"tiny mt8\" style=\"background:var(--accent-soft);border-radius:10px;padding:9px;color:#c9cfff\">已选 <b>${selN}</b> 条 —— 点条目即可选中 / 取消；也可以选中后直接归类到文件夹。</div>\n      <div class=\"chips mt8\">\n        ${folders.map(f => `<button class=\"chip\" data-act=\"mMoveSel\" data-v=\"${esc(f)}\">→ ${esc(f)}</button>`).join('')}\n        ${folders.length ? '<button class=\"chip\" data-act=\"mMoveSel\" data-v=\"\">→ 取消分类</button>' : ''}\n      </div>` : ''}\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary sm grow\" data-act=\"practiceMistakes\" ${list.length ? '' : 'disabled'}>重做全部错题</button>\n      <button class=\"btn sm grow\" data-act=\"pushMistakesToBank\" ${list.length ? '' : 'disabled'}>全部存入题库</button></div></div>\n  ${shown.length ? shown.map(m => `<div class=\"mcard ${sel[String(m.id)] ? 'sel' : ''}\" ${selMode ? `data-act=\"mPick\" data-id=\"${esc(m.id)}\" style=\"cursor:pointer\"` : ''}>\n    <div class=\"row between\"><span class=\"tiny\">${esc(m.date || '')} · ${esc(m.src || '')}${m.cat ? ' · ' + esc(m.cat) : ''}${m.folder ? ' · 📁 ' + esc(m.folder) : ''}</span>\n      <span class=\"row\" style=\"gap:5px\">${selMode ? `<span class=\"pill ${sel[String(m.id)] ? 'run' : ''}\">${sel[String(m.id)] ? '已选 ✓' : '未选'}</span>`\n        : `<button class=\"btn sm ghost\" data-act=\"mNote\" data-id=\"${esc(m.id)}\">${m.note ? '✏️ 备注' : '＋ 备注'}</button>\n           <button class=\"btn sm ghost\" data-act=\"mFolderAsk\" data-id=\"${esc(m.id)}\">分类</button>\n           <button class=\"btn sm ghost\" data-act=\"delMistake\" data-id=\"${esc(m.id)}\">已掌握</button>`}</span></div>\n    <div style=\"font-size:13.2px;line-height:1.6;margin-top:5px\">${esc(m.q || m.content)}</div>\n    ${(m.options || []).length ? `<div class=\"mt6\">${m.options.map((o, i) => {\n      const right = (m.qType === 'multi') ? normChoiceSet(m.answerIndexes) : [Number(m.answerIndex)];\n      const mine = (m.qType === 'multi') ? normChoiceSet(m.myIdxes) : (m.myIdx == null ? [] : [Number(m.myIdx)]);\n      const isR = right.indexOf(i) >= 0, isM = mine.indexOf(i) >= 0;\n      return `<div class=\"opt ${isR ? 'right' : (isM ? 'wrong' : '')}\" style=\"margin-bottom:5px\">\n        <span class=\"k\">${'ABCD'[i]}</span><span>${esc(o)}</span>${isR ? '<span class=\"tiny\" style=\"margin-left:auto\">正确</span>' : (isM ? '<span class=\"tiny\" style=\"margin-left:auto\">我选的</span>' : '')}</div>`;\n    }).join('')}</div>`\n      : `<div class=\"opt right mt6\"><span>参考答案：${esc(m.answer || (m.keywords || []).join('/'))}</span></div>\n         <div class=\"opt wrong mt6\"><span>我的答案：${esc(m.my || '未作答')}</span></div>`}\n    ${m.explain ? `<div class=\"exp\">${esc(m.explain)}</div>` : ''}\n    ${m.note ? `<div class=\"tiny mt6\" style=\"background:rgba(255,201,120,.14);border:1px solid rgba(255,201,120,.3);border-radius:8px;padding:8px;line-height:1.7;color:#ffe0b0\">📝 我的要点：${esc(m.note)}</div>` : ''}\n  </div>`).join('')\n      : `<div class=\"empty\">${filter === 'all' ? '错题本还是空的。答错的题会自动进来。' : '这个分类下还没有错题。'}</div>`}`;\n};\n/* ==========================================================\n   视图 · 私密记忆 / 题库\n   ========================================================== */\n/* ==========================================================\n   加 / 减时间（专注页 · 当前任务卡）\n   · extendCur 只负责展开输入行；真正改时长在 extendApply\n   · 正数=延长，负数=缩短；只改这个任务的预估，不动倒计时\n   ========================================================== */\nObject.assign(ACTIONS, {\n  /* 展开输入行 */\n  extendOpen: async () => {\n    const s = S.session; if (!s) return;\n    s.extendOpen = true;\n    if (s.extendVal == null) s.extendVal = '10';\n    render();\n  },\n  /* 收起输入行，不改动任何数值 */\n  extendCancel: async () => {\n    const s = S.session; if (!s) return;\n    s.extendOpen = false;\n    render();\n  },\n  extendApply: async () => {\n    const s = S.session; if (!s) return;\n    const i = currentTaskIdx(s); if (i < 0) return;\n    const box = document.getElementById('extendIn');\n    const raw = (box && box.value != null && box.value !== '') ? box.value : (s.extendVal == null ? '10' : s.extendVal);\n    const min = Math.round(Number(raw));\n    if (!min) { toast('请填要加/减的分钟数（负数表示缩短）'); return; }\n    s.extendVal = String(min);\n    s.extendOpen = false;\n    s.plan[i].est = Math.max(0, Number(s.plan[i].est || 0) + min);\n    s.curTaskSince = Date.now(); s.taskAsked = false;\n    pushMsg(s, 'sys', `⌛ 「${s.plan[i].content}」${min > 0 ? '延长' : '缩短'} ${Math.abs(min)} 分钟（现预估 ${s.plan[i].est} 分钟）`);\n    await saveSession(true);\n    toast('已' + (min > 0 ? '延长' : '缩短') + ' ' + Math.abs(min) + ' 分钟');\n    render();\n        /* 勾了「专注总时长也一起加减」→ 倒计时同步：加则一起加，减则一起减（至少给这轮留 1 分钟） */\n    const too = s.extendFocusToo !== false;\n    if (too) {\n      const delta = min * 60000;\n      let endAt = Number(s.phaseEndsAt || Date.now()) + delta;\n      if (endAt < Date.now() + 60000) endAt = Date.now() + 60000;   // 别把倒计时减到已经没时间\n      s.phaseEndsAt = endAt;\n      s.focusMin = Math.max(1, Number(s.focusMin || 25) + min);\n      s.lockUntil = sessionEndAt(s);\n  syncLockNow();\n      pushMsg(s, 'sys', `⏱ 本次专注总时长${min > 0 ? '延长' : '缩短'} ${Math.abs(min)} 分钟（现 ${s.focusMin} 分钟，还剩约 ${Math.max(0, Math.round((endAt - Date.now()) / 60000))} 分钟）`);\n      S.lastTick = Date.now();\n      await saveSession(true);\n      toast('总时长也' + (min > 0 ? '延长' : '缩短') + '了 ' + Math.abs(min) + ' 分钟');\n      render();\n    }   // 加时才问总时长；缩短不动倒计时\n  }\n});\n/* 任务时长加了之后，问一句「本次专注的倒计时要不要也一起延」。\n   · 选延长 → focusMin 与 phaseEndsAt 同步加（进度环和时长结算才都对）\n   · 宿主没有弹窗组件时静默跳过，不影响主流程，也不会再报未定义 */\nasync function askExtendFocus(s, minutes) {\n  if (!s || s.status !== 'running' || s.phase !== 'focus') return;\n  if (typeof confirmBox !== 'function') return;\n  minutes = Math.round(Number(minutes) || 0);\n  if (minutes <= 0) return;\n  const idx = (typeof currentTaskIdx === 'function') ? currentTaskIdx(s) : -1;\n  const name = (idx >= 0 && s.plan && s.plan[idx] && s.plan[idx].content) || '这个任务';\n  const left = Math.max(0, Math.round(remainSec() / 60));\n  const total = Number(s.focusMin || 25);\n  const ok = await confirmBox('专注总时长也延长吗？',\n    '「' + name + '」的时间已经往后加了 ' + minutes + ' 分钟。\\n\\n'\n    + '要不要把本次专注的倒计时也一起延长 ' + minutes + ' 分钟？\\n'\n    + '· 延长：总时长 ' + total + ' → ' + (total + minutes) + ' 分钟，还剩约 ' + (left + minutes) + ' 分钟\\n'\n    + '· 不延长：倒计时照原样走，只是这个任务的时间会更紧',\n    '延长 ' + minutes + ' 分钟');\n  if (!ok) { toast('总时长不变，倒计时照原样走'); return; }\n  s.focusMin = total + minutes;\n  s.lockUntil = sessionEndAt(s);\n  syncLockNow();\n  s.phaseEndsAt = Number(s.phaseEndsAt || Date.now()) + minutes * 60000;\n  pushMsg(s, 'sys', `⏱ 本次专注总时长延长 ${minutes} 分钟（现 ${s.focusMin} 分钟，还剩约 ${Math.round(remainSec() / 60)} 分钟）`);\n  S.lastTick = Date.now();\n  await saveSession(true);\n  toast('已把总时长延长 ' + minutes + ' 分钟');\n  render();\n}\nVIEWS.weak = function () {\n  const tab = S.draft.weakTab || 'weak';\n  const list = privOf(tab, 100);\n  const tabs = [['weak', '薄弱点'], ['qa', '答疑记录']];\n  return `<div class=\"card\"><div class=\"chips\">\n    ${tabs.map(([k, n]) => `<button class=\"chip ${tab === k ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"weakTab\" data-v=\"${k}\">${n} ${privOf(k).length}</button>`).join('')}\n    <button class=\"chip\" data-act=\"gotoView\" data-view=\"mistakes\">错题本 ${mistakeList().length} ›</button></div>\n    <div class=\"tiny mt10\">🔒 私密记忆库：角色在对话中看不到，也不会主动提起你的错题与薄弱项；只有出题、点拨和惩罚练习会调用它。</div></div>\n  <div class=\"card\">${list.length ? list.map(x => `<div class=\"item\"><div class=\"ic\">${tab === 'weak' ? '🎯' : '💬'}</div>\n    <div class=\"grow\"><div style=\"font-size:12.8px;line-height:1.6;white-space:pre-wrap\">${esc(x.content)}</div>\n    <div class=\"tiny\">${x.date} ${hm(x.at)}</div></div>\n    <button class=\"btn sm ghost\" data-act=\"delPriv\" data-id=\"${esc(x.id)}\">删</button></div>`).join('')\n      : `<div class=\"empty\">还没有记录。校验出题、答疑会自动存进这里。</div>`}</div>\n  <div class=\"card\"><h3>对外记忆库（角色可见）</h3>\n    <div class=\"tiny\">任务完成状态、专注时长、你的总结、睡眠报告、惩罚与奖励记录 —— 这些会同步给角色。</div>\n    <div class=\"mt10\">${(S.pub || []).slice(0, 10).map(p => `<div class=\"item\"><div class=\"ic\">📌</div>\n      <div class=\"grow\"><div style=\"font-size:12.5px\">${esc(p.text)}</div><div class=\"tiny\">${p.date}</div></div></div>`).join('') || `<div class=\"empty\" style=\"padding:10px\">暂无</div>`}</div></div>`;\n};\nVIEWS.qbank = function () {\n  const d = S.draft, kind = d.qKind || 'choice';\n  const selMode = !!d.bankSelMode;\n  const sel = d.bankSel || {};\n  const selN = Object.keys(sel).length;\n  const cats = bankCats();\n  const filter = d.qCatFilter == null ? 'all' : d.qCatFilter;\n  const all = allBank();\n  const shown = filter === 'all' ? all : (filter === 'none' ? all.filter(q => !q.cat) : all.filter(q => String(q.cat || '') === String(filter)));\n  const cntOf = c => (c === 'all' ? all.length : (c === 'none' ? all.filter(q => !q.cat).length : all.filter(q => String(q.cat || '') === String(c)).length));\n  const masteredN = all.filter(q => isMastered(q)).length;\n  const typeN = t => all.filter(q => qtypeOf(q) === t).length;\n  return `<div class=\"card\"><div class=\"row between\"><h3>题库（${all.length} 题）</h3>\n    <button class=\"btn sm ${selMode ? 'primary' : 'ghost'}\" data-act=\"bankSelect\" ${all.length ? '' : 'disabled'}>${selMode ? '完成选择' : '☑️ 批量'}</button></div>\n    <div class=\"sub\">AI 出题会把题干、标准答案、解析一起写进这里，判分在本地瞬时完成。每题都记着<b>做对了几次</b>：做对满 ${masteryNeed()} 次就标为「已掌握」，之后抽题会优先出还没掌握的题。</div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length}</div><div class=\"tiny\">总题数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600;color:var(--teal)\">${masteredN}</div><div class=\"tiny\">已掌握</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length - masteredN}</div><div class=\"tiny\">待掌握</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${cats.length}</div><div class=\"tiny\">分类</div></div>\n    </div>\n    <div class=\"tiny mt6\">题型：单选 ${typeN('choice')} · 多选 ${typeN('multi')} · 判断 ${typeN('tf')} · 填空 ${typeN('fill')}</div>\n    <div class=\"tiny mt6\" style=\"background:var(--card2);border-radius:10px;padding:9px;line-height:1.7\">\n      <b>掌握度怎么影响出题</b>：每道题都记着做对次数。做对一次 +1，<b>答错就清零</b>；做对累计到 ${masteryNeed()} 次（可在「我的 → 监督与惩罚 → 出题配比」里改）就标为「已掌握」。抽题时<b>优先抽没掌握的题</b>，掌握过的只在题量不够时兜底 —— 所以一直做对，这道题以后就很少再出现；手滑答错，它会重新回到你的卷子里。\n    </div>\n    <div class=\"bar mt10\"><i style=\"width:${all.length ? masteredN / all.length * 100 : 0}%\"></i></div>\n    <div class=\"tiny mt6\">掌握进度 ${masteredN}/${all.length}${all.length ? '（' + Math.round(masteredN / all.length * 100) + '%）' : ''}</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"bankCatNew\">＋ 新建分类</button>\n      <button class=\"btn sm ghost grow\" data-act=\"bankCatManage\">⚙️ 管理分类</button>\n      <button class=\"btn sm ghost grow\" data-act=\"importBank\">导入题目</button></div>\n    <div class=\"tiny mt8\">按分类看：</div>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${filter === 'all' ? 'on' : ''}\" data-act=\"bankCatFilter\" data-v=\"all\">全部 ${cntOf('all')}</button>\n      <button class=\"chip ${filter === 'none' ? 'on' : ''}\" data-act=\"bankCatFilter\" data-v=\"none\">未分类 ${cntOf('none')}</button>\n      ${cats.map(c => `<button class=\"chip ${String(filter) === String(c) ? 'on' : ''}\" data-act=\"bankCatFilter\" data-v=\"${esc(c)}\">📁 ${esc(c)} ${cntOf(c)}</button>`).join('')}\n    </div>\n    ${selMode ? `<div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"bankAll\">${selN && selN >= shown.length ? '取消全选' : '全选本页'}</button>\n      <button class=\"btn sm warn grow\" data-act=\"bankDelSel\" ${selN ? '' : 'disabled'}>删除选中的 ${selN} 道</button></div>\n      <div class=\"tiny mt8\" style=\"background:var(--accent-soft);border-radius:10px;padding:9px;color:#c9cfff\">已选 <b>${selN}</b> 道 —— 点条目选中 / 取消，选好后可以「批量移进某个分类」或删除。</div>\n      <div class=\"tiny mt6\">批量移到分类：</div>\n      <div class=\"chips mt6\">${cats.map(c => `<button class=\"chip\" data-act=\"bankMoveSel\" data-v=\"${esc(c)}\" ${selN ? '' : 'disabled'}>→ ${esc(c)}</button>`).join('')}\n      <button class=\"chip\" data-act=\"bankMoveSel\" data-v=\"\" ${selN ? '' : 'disabled'}>→ 取消分类</button></div>` : ''}\n  </div>\n  <div class=\"card\"><div class=\"row between\"><h3 style=\"margin:0\">✍️ 手动添加题目</h3>\n    <button class=\"btn sm ${d.qAddOpen ? 'ghost' : 'primary'}\" data-act=\"bankAddToggle\">${d.qAddOpen ? '收起' : '＋ 展开'}</button></div>\n    ${d.qAddOpen ? '' : `<div class=\"tiny mt6\">平时收起来不占地方。AI 出题、错题重做入库都会自动把题存进题库，只有想自己出题时才需要展开这里。</div>`}\n    ${d.qAddOpen ? `<div class=\"chips mt6\">${Q_TYPES.map(([k, n]) => `<button class=\"chip ${kind === k ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"qKind\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <label class=\"fl\">题干</label><textarea data-in=\"qText\" placeholder=\"题目内容\">${esc(d.qText || '')}</textarea>\n    ${kind === 'fill' ? `<label class=\"fl\">参考答案</label><input class=\"input\" data-in=\"qAnswer\" value=\"${esc(d.qAnswer || '')}\">\n      <label class=\"fl\">判分关键词（逗号分隔）</label><input class=\"input\" data-in=\"qKeywords\" value=\"${esc(d.qKeywords || '')}\">`\n      : `<label class=\"fl\">选项（每行一个${kind === 'tf' ? '，判断题可留空，默认「正确 / 错误」' : ''}）</label>\n      <textarea data-in=\"qOpts\" placeholder=\"${kind === 'tf' ? '判断题可以不填' : '选项A&#10;选项B&#10;选项C&#10;选项D'}\">${esc(d.qOpts || '')}</textarea>\n      <label class=\"fl\">${kind === 'multi' ? '正确选项（可多选）' : '正确选项'}</label>\n      <div class=\"chips\">${['A', 'B', 'C', 'D'].map(k => `<button class=\"chip ${(kind === 'multi' ? (d.qAnsMul || []).indexOf(k) >= 0 : (d.qAns || 'A') === k) ? 'on' : ''}\" data-act=\"${kind === 'multi' ? 'qAnsMulPick' : 'setDraft'}\" ${kind === 'multi' ? '' : 'data-k=\"qAns\"'} data-v=\"${k}\">${k}</button>`).join('')}</div>`}\n    <label class=\"fl\">解析（可选）</label><input class=\"input\" data-in=\"qExplain\" value=\"${esc(d.qExplain || '')}\">\n    <label class=\"fl\">归到哪个分类</label>\n    <div class=\"chips\">${cats.map(c => `<button class=\"chip ${(d.qCat || '综合') === c ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"qCat\" data-v=\"${esc(c)}\">${esc(c)}</button>`).join('')}\n      <button class=\"chip ${!d.qCat ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"qCat\" data-v=\"\">不分类</button></div>\n    <button class=\"btn primary block mt14\" data-act=\"addBank\">加入题库</button>\n    <div class=\"tiny mt6\">加进来的题同样计入掌握度：做对满 ${masteryNeed()} 次标为已掌握，之后抽题会优先避开它。</div>` : ''}</div>\n  <div class=\"card\"><div class=\"row between\"><h3>${filter === 'all' ? '全部题目' : (filter === 'none' ? '未分类' : '📁 ' + esc(filter))}（${shown.length}）</h3>\n    <span class=\"tiny\">${selMode ? '点击选择' : ''}</span></div>\n    ${shown.length ? shown.map((q, i) => {\n      const m = isMastered(q);\n      const rt = Number(q.right || 0);\n      return `<div class=\"item ${sel[String(q.id || i)] ? 'sel' : ''}\" ${selMode ? `data-act=\"bankPick\" data-i=\"${esc(q.id || i)}\" style=\"cursor:pointer\"` : ''}>\n      ${selMode ? `<button class=\"ck ${sel[String(q.id || i)] ? 'on' : ''}\">✓</button>` : `<div class=\"ic\">${qtypeOf(q) === 'fill' ? '✍️' : qtypeOf(q) === 'multi' ? '☑️' : qtypeOf(q) === 'tf' ? '⚖️' : '🔘'}</div>`}\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${esc(q.q)}</div>\n        <div class=\"tiny\">${esc(qAnswerText(normQuestion(q)))}</div>\n        <div class=\"tiny mt6\">\n          <span class=\"pill ${m ? 'ok' : (rt ? 'warn' : '')}\">${masteryText(q)}</span>\n          <span class=\"pill\">${qTypeLabel(qtypeOf(q))}</span>\n          ${q.cat ? `<span class=\"pill\">📁 ${esc(q.cat)}</span>` : ''}\n        </div></div>\n      ${selMode ? '' : `<button class=\"btn sm ghost\" data-act=\"bankEditCat\" data-id=\"${esc(q.id || i)}\">分类</button>\n      <button class=\"btn sm ghost\" data-act=\"bankResetMastery\" data-id=\"${esc(q.id || i)}\">重置</button>\n      <button class=\"btn sm ghost\" data-act=\"delBank\" data-id=\"${esc(q.id || i)}\">删</button>`}</div>`;\n    }).join('') : `<div class=\"empty\">${filter === 'all' ? '题库还是空的。开 AI 出题后会自动充实，也可以自己加题或导入。' : '这个分类下还没有题目。'}</div>`}</div>`;\n};\n/* ==========================================================\n   视图 · 专注邀约 / 睡眠陪伴（聊天室 + 号面板进来时落到这里）\n   —— 可以「现在就开始」，也可以「预订一个时间段」\n   ========================================================== */\nconst INVITE_MODES = [['小憩', 20], ['午睡', 30], ['长睡眠', 480]];\nfunction inviteKind() { return S.draft.inviteKind === 'sleep' ? 'sleep' : 'focus'; }\nfunction inviteCharId() {\n  const ids = (S.chars || []).map(c => c.id);\n  if (S.draft.inviteChar && ids.indexOf(S.draft.inviteChar) >= 0) return S.draft.inviteChar;\n  const fromCfg = (cfg('sleepCharIds') || []).concat(cfg('charIds') || []).filter(id => charById(id));\n  return fromCfg[0] || (ids[0] || '');\n}\nfunction inviteDefaultDate() {\n  const d = new Date(Date.now() + 30 * 60000);\n  return { date: dkey(d), time: pad2(d.getHours()) + ':' + pad2(d.getMinutes()) };\n}\nVIEWS.invite = function () {\n  const kind = inviteKind();\n  const fromChat = !!S.draft.inviteFromChat;\n  const foot = `<div class=\"row\" style=\"gap:8px\">\n      <button class=\"btn ghost grow\" data-act=\"inviteBack\">${fromChat ? '返回聊天室' : '回首页'}</button></div>\n    <div class=\"tiny center mt10\">TA 应你的那句话会写进聊天室，也会成为这段陪伴的第一句话。</div>`;\n  if (!S.chars.length) return `<div class=\"card\"><h3>还没有角色</h3>\n    <div class=\"sub\">先在小手机聊天 APP 里创建角色，才能给 TA 发邀请。</div>${foot}</div>`;\n  const cid = inviteCharId();\n  const busy = S.busy === 'invite';\n  const head = `<div class=\"invite-hero ${kind === 'sleep' ? 'sleep' : ''}\">\n    <div class=\"row between\"><div class=\"grow\">\n      <div style=\"font-size:18px;font-weight:700\">${kind === 'sleep' ? '💞 睡眠陪伴' : '📨 专注邀约'}</div>\n      <div class=\"tiny mt6\" style=\"color:var(--dim)\">${kind === 'sleep'\n        ? 'APP 会把邀请写进你们的聊天室，请 TA 亲口应你一声，然后直接开始陪你睡：环境描写、哄睡语音、睡眠壁纸照常。'\n        : '可以现在就跟他一起开始一段专注；也可以预订一个时间段，到点前 TA 会来催你准备开始。'}</div>\n    </div><div style=\"font-size:32px\">${kind === 'sleep' ? '🌙' : '🎯'}</div></div>\n    ${fromChat ? '<div class=\"tiny mt8\" style=\"color:var(--teal)\">你是从聊天室 + 号面板进来的 —— 已经自动带上当前对话的角色。</div>' : ''}\n  </div>`;\n  const charCard = `<div class=\"card\"><h3>${kind === 'sleep' ? '谁陪你睡' : '谁来陪你 / 监督'}</h3>\n    <div class=\"chips mt6\">${S.chars.map(c => `<button class=\"chip ${String(cid) === String(c.id) ? 'on' : ''}\" data-act=\"inviteChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('')}</div>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"inviteRandomChar\">🎲 随机抽一位</button></div></div>`;\n  if (kind === 'sleep') {\n    const cur = S.draft.invMode || cfg('sleepMode') || '午睡';\n    const mins = S.draft.invMin != null ? S.draft.invMin : Number(cfg('sleepMinutes') || 30);\n    return head + charCard + `<div class=\"card\">\n      <h3>睡多久</h3>\n      <div class=\"chips mt6\">${INVITE_MODES.map(([n, m]) => `<button class=\"chip ${cur === n ? 'on' : ''}\" data-act=\"inviteMode\" data-v=\"${n}\" data-m=\"${m}\">${n} · ${m >= 60 ? (m / 60) + ' 小时' : m + ' 分钟'}</button>`).join('')}</div>\n      <label class=\"fl\">时长（分钟，到点会提醒但不强制结束）</label>\n      <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"invMin\" data-num=\"1\" value=\"${Number(mins) || 30}\">\n      <label class=\"fl\">想跟 TA 说的话（可留空）</label>\n      <input class=\"input\" data-in=\"invNote\" value=\"${esc(S.draft.invNote || '')}\" placeholder=\"例如：今晚别让我玩手机了，陪我躺一会儿\">\n      <button class=\"btn sleep block mt12\" data-act=\"inviteSend\" data-mode=\"start\" ${busy ? 'disabled' : ''}>${busy ? '正在请 TA 应你…' : '🌙 发出邀请，直接开睡'}</button>\n      <button class=\"btn block ghost mt8\" data-act=\"inviteSend\" data-mode=\"only\" ${busy ? 'disabled' : ''}>只发邀请，先不开计时</button>\n      ${busy ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> 已把邀请写进聊天室，等 TA 应你一声…</div>` : ''}\n      <div class=\"tiny mt6\">会消耗一次你自己的 API（请 TA 回你一句）。</div>\n    </div>` + foot;\n  }\n  const planMode = S.draft.invitePlan === 'book' ? 'book' : 'now';\n  const mins = S.draft.inviteMin != null ? S.draft.inviteMin : Number(cfg('focusMin') || 25);\n  const presets = ((cfg('lastPlan') || []).map(t => t.content).filter(Boolean)).slice(0, 5);\n  const d0 = inviteDefaultDate();\n  const defDate = S.draft.inviteDate || d0.date;\n  const defTime = S.draft.inviteTime || d0.time;\n  const adv = apptAdvance(), gap = apptGap(), nMax = apptMaxNudge(), gr = apptGrace();\n  const modeCard = `<div class=\"card\">\n    <h3>现在，还是先约个时间</h3>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${planMode === 'now' ? 'on' : ''}\" data-act=\"invitePlanMode\" data-v=\"now\">现在就一起专注</button>\n      <button class=\"chip ${planMode === 'book' ? 'on' : ''}\" data-act=\"invitePlanMode\" data-v=\"book\">📅 预订一个时间段</button>\n    </div>\n    <div class=\"tiny mt6\">${planMode === 'now'\n      ? '发出去之后会在聊天室里写一张邀约卡、请 TA 应你一声，然后立刻开始计时。'\n      : '约好之后 TA 会在开始前 ' + adv + ' 分钟第一次来催你，之后每 ' + gap + ' 分钟催一次、共 ' + nMax + ' 次' + (gr ? '，第 ' + nMax + ' 次之后再过 ' + gr + ' 分钟' : '') + '；连着催 ' + nMax + ' 次你还没点「现在开始」，就按惩罚库开罚。'}</div>\n  </div>`;\n  if (planMode === 'book') {\n    return head + charCard + modeCard + `<div class=\"card\">\n      <h3>预订哪一段</h3>\n      <div class=\"row\" style=\"gap:10px\">\n        <div class=\"grow\"><label class=\"fl\">日期</label><input class=\"input\" type=\"date\" data-in=\"inviteDate\" value=\"${esc(defDate)}\"></div>\n        <div class=\"grow\" style=\"max-width:132px\"><label class=\"fl\">开始时间</label><input class=\"input\" type=\"time\" data-in=\"inviteTime\" value=\"${esc(defTime)}\"></div>\n      </div>\n      <label class=\"fl\">这一段时间做什么</label>\n      <input class=\"input\" data-in=\"inviteTask\" value=\"${esc(S.draft.inviteTask || '')}\" placeholder=\"例如：资料分析 30 题\">\n      ${presets.length ? `<div class=\"chips mt6\">${presets.map(t => `<button class=\"chip ${S.draft.inviteTask === t ? 'on' : ''}\" data-act=\"inviteTaskPick\" data-v=\"${esc(t)}\">${esc(t)}</button>`).join('')}</div>` : ''}\n      <label class=\"fl\">多久</label>\n      <div class=\"chips\">${[15, 25, 30, 45, 60, 90].map(m => `<button class=\"chip ${Number(mins) === m ? 'on' : ''}\" data-act=\"inviteMinPick\" data-v=\"${m}\">${m} 分钟</button>`).join('')}</div>\n      <input class=\"input mt6\" type=\"number\" inputmode=\"numeric\" data-in=\"inviteMin\" data-num=\"1\" value=\"${Number(mins) || 25}\">\n      <div class=\"tiny mt10\" style=\"background:var(--card2);border-radius:10px;padding:10px;line-height:1.7\">\n        按现在的设置，TA 会在这几个时间点来催你：<br>\n        ${apptTimesOf({ startAt: inviteParse() }).map((t, i) => `${i + 1}. ${hm(t)}`).join('　')}<br>\n        第 ${nMax} 次之后再过 ${gr} 分钟你还没点「现在开始」，就按惩罚库开罚。\n      </div>\n      <button class=\"btn block ghost sm mt10\" data-act=\"inviteBookAdvanced\">＋ 分段任务 / 每段休息 / 校验时机（去完整表单里设）</button>\n      <button class=\"btn primary block mt10\" data-act=\"inviteBook\" ${busy ? 'disabled' : ''}>${busy ? '正在约…' : '🗓 约好，让 TA 到点来催我'}</button>\n      <div class=\"tiny mt6\">会把这条约定写进聊天室，并排好催促。开始时间要晚于现在（至少留 1 分钟）。</div>\n      <button class=\"btn block ghost sm mt8\" data-act=\"gotoView\" data-view=\"appt\">看所有预约 / 改催促节奏</button>\n    </div>` + foot;\n  }\n  return head + charCard + modeCard + `<div class=\"card\">\n    <h3>这一段专注做什么</h3>\n    <input class=\"input mt6\" data-in=\"inviteTask\" value=\"${esc(S.draft.inviteTask || '')}\" placeholder=\"例如：资料分析 30 题\">\n    ${presets.length ? `<div class=\"chips mt6\">${presets.map(t => `<button class=\"chip ${S.draft.inviteTask === t ? 'on' : ''}\" data-act=\"inviteTaskPick\" data-v=\"${esc(t)}\">${esc(t)}</button>`).join('')}</div>` : ''}\n    <label class=\"fl\">多久</label>\n    <div class=\"chips\">${[15, 25, 30, 45, 60, 90].map(m => `<button class=\"chip ${Number(mins) === m ? 'on' : ''}\" data-act=\"inviteMinPick\" data-v=\"${m}\">${m} 分钟</button>`).join('')}</div>\n    <input class=\"input mt6\" type=\"number\" inputmode=\"numeric\" data-in=\"inviteMin\" data-num=\"1\" value=\"${Number(mins) || 25}\">\n    <button class=\"btn primary block mt12\" data-act=\"inviteSend\" data-mode=\"start\" ${busy ? 'disabled' : ''}>${busy ? '正在请 TA 应你…' : '📨 发出邀约，立刻开始专注'}</button>\n    <button class=\"btn block ghost mt8\" data-act=\"inviteSend\" data-mode=\"only\" ${busy ? 'disabled' : ''}>只发邀约，先不开计时</button>\n    ${busy ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> 已把邀约写进聊天室，等 TA 应你一声…</div>` : ''}\n    <div class=\"tiny mt6\">会走一次你的 API；只想自己开一段就用首页「开始一段专注」。</div>\n  </div>` + foot;\n};\n/* ==========================================================\n   视图 · 睡眠 / 报告 / 故事 / 闹钟\n   ========================================================== */\nVIEWS.sleep = function () {\n  const st = S.sleep, a = cfg('alarm') || {}, d = S.draft;\n  const dMin = d.sleepMin != null ? d.sleepMin : (cfg('sleepMinutes') || 30);\n  const dMode = d.sleepMode || '午睡';\n  const recent = (S.sleeps || []).slice(0, 6);\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(165,139,255,.16),rgba(255,255,255,.03));border-color:rgba(165,139,255,.25)\">\n    <div class=\"row between\"><div><div style=\"font-size:22px;font-weight:300\">${hm(Date.now())}</div>\n      <div class=\"tiny\">${new Date().getHours() >= 21 || new Date().getHours() < 6 ? '夜深了，把灯调暗一点' : '随时可以眯一会儿'}</div></div>\n      <div style=\"font-size:34px\">🌙</div></div></div>\n  ${st && st.running ? `<div class=\"card\" style=\"text-align:center;padding:24px 14px;background:linear-gradient(160deg,rgba(165,139,255,.18),rgba(255,255,255,.03));border-color:rgba(165,139,255,.3)\">\n    <div class=\"tiny\">${esc(st.mode)}中 · 正计时 · 开始于 ${hm(st.startAt)}</div>\n    <div id=\"sleepClock\" style=\"font-size:48px;font-weight:200;letter-spacing:2px;margin:12px 0 4px\">${fmtClock((Date.now() - st.startAt) / 1000)}</div>\n    <div class=\"tiny\" id=\"sleepLeft\"></div>\n    <div class=\"tiny mt6\">${st.wp ? '壁纸已自动铺为整页背景' : (st.wpLoading ? '正在生成壁纸并铺为背景…' : (st.wpErr ? '壁纸生成失败，可点下面重试' : '稍等，会自动生成壁纸并铺为背景'))}</div>\n    <div class=\"tiny mt6\" id=\"sleepPhase\">${sleepPhaseText()}</div>\n    <div class=\"tiny mt6\">${(st.charIds || []).length ? '陪伴：' + (st.charIds || []).map(id => esc(charName(id))).join('、') : ''}</div>\n    ${st.inviteLine ? `<div class=\"tiny mt8\" style=\"color:#c9c2ff\">TA 应你的话：${esc(st.inviteLine)}</div>` : ''}\n    <div class=\"row mt14\" style=\"gap:9px\">\n      <button class=\"btn ghost grow\" data-act=\"gotoView\" data-view=\"story\">🔊 故事</button>\n      <button class=\"btn ghost grow\" data-act=\"endSleep\">结束并记录</button></div>\n    <div class=\"chips mt10\" style=\"justify-content:center\">\n      <button class=\"chip ${cfg('sleepWallBg') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"sleepWallBg\">用壁纸当背景</button>\n      <button class=\"chip\" data-act=\"genSleepWallpaper\" ${st.wpLoading ? 'disabled' : ''}>${st.wp ? '换一张壁纸' : '重新生成壁纸'}</button>\n    </div>\n    ${S.chars.length ? `<div class=\"tiny mt10\" style=\"text-align:center\">陪你睡的角色（点一下当场换人，壁纸和闲聊立刻跟着换）</div>\n    <div class=\"chips mt6\" style=\"justify-content:center\">${S.chars.map(c => `<button class=\"chip ${(st.charIds || []).indexOf(c.id) >= 0 ? 'on' : ''}\" data-act=\"sleepSwitchChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('')}</div>` : ''}\n    ${st.lullaby ? `<div class=\"chips mt10\" style=\"justify-content:center\">\n      <button class=\"chip\" data-act=\"lullabyReplay\">🔊 哄睡语重播</button>\n      <button class=\"chip\" data-act=\"lullabyAgain\">换一句哄我睡</button></div>` : ''}\n    <button class=\"btn ghost block mt10\" data-act=\"sleepBreak\">🌗 我醒了一下（不结束，记个中断点）</button>\n    ${(st.breaks || []).length ? `<div class=\"mt8\" style=\"text-align:left\">\n      <div class=\"tiny\">已标记中断 ${st.breaks.length} 次 · 计时继续走，结束时会写进睡眠报告</div>\n      ${st.breaks.map((b, i) => `<div class=\"tiny\">${i + 1}. ${hm(b.at)}（睡眠第 ${Math.max(0, Math.round((b.at - st.startAt) / 60000))} 分钟）${b.note ? ' · ' + esc(b.note) : ''}\n        <button class=\"btn sm ghost\" style=\"min-height:26px;padding:0 8px\" data-act=\"delSleepBreak\" data-i=\"${i}\">删</button></div>`).join('')}\n    </div>` : ''}</div>\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(120,110,200,.16),rgba(255,255,255,.03));border-color:rgba(165,139,255,.25)\">\n    <div class=\"row between\"><span class=\"tiny\">🛏 睡前的房间</span>\n      <span class=\"tiny\">${st.scene ? esc(charName(st.sceneChar)) : '<span class=\"spin\"></span> 正在铺床…'}</span></div>\n    <div style=\"font-size:13.5px;line-height:1.85;margin-top:6px;color:#d9dcf0\">${st.scene ? esc(st.scene) : '（正在描写你们一起睡下的这个房间…）'}</div>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"sceneReroll\">↺ 换一段环境</button>\n      <button class=\"btn sm ghost grow\" data-act=\"sceneSaveFav\">⭐ 收藏这段</button></div></div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>💬 睡前闲聊</h3><span class=\"tiny\" id=\"sleepChatCount\">${(st.chat || []).length} 句</span></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ${S.voiceLoop && S.voiceLoop.chatAll ? 'primary' : 'ghost'} grow\" data-act=\"msgLoopAll\">${S.voiceLoop && S.voiceLoop.chatAll ? '⏹ 停止循环' : '🔁 循环本场所有语音'}</button>\n      <span class=\"tiny\" style=\"align-self:center\">已留住 ${msgLoopAllRefs().length} 句</span></div>\n    <div class=\"tiny\" data-vloop=\"1\" style=\"margin-top:6px;color:var(--teal)\"></div>\n    <div class=\"tiny mt6\">聊完直接把手机放下就行 —— 从你最后一次互动（或切屏）开始才算正式入睡。</div>\n    <div id=\"sleepMsgBox\" style=\"max-height:40vh;overflow-y:auto;margin-top:8px\">\n      ${(st.chat || []).length ? (st.chat || []).map(m => msgHTML(m)).join('') : `<div class=\"empty\" style=\"padding:14px\">说点什么吧，比如「我睡不着」</div>`}\n    </div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <input class=\"input grow\" id=\"sleepInput\" data-in=\"sleepDraft\" value=\"${esc(S.draft.sleepDraft || '')}\" placeholder=\"说点什么…\">\n      <button class=\"btn primary\" data-act=\"sleepChatSend\">发送</button>\n    </div>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"sleepChatFav\">⭐ 收藏这段对话</button>\n      <button class=\"btn sm ghost grow\" data-act=\"genlogOpen\">🧾 看生成记录</button></div>\n  </div>\n  <div class=\"card\"><div class=\"row between\"><h3>睡眠壁纸</h3>\n    <span class=\"pill ${st.wp ? 'ok' : (st.wpLoading ? 'run' : '')}\">${st.wp ? '已生成' : st.wpLoading ? '生成中…' : (st.wpErr ? '生成失败' : '未生成')}</span></div>\n    <div class=\"tiny mt6\">开始正计时后会自动生成一张角色入睡的画面，并铺成整页背景；同时进壁纸库且不上锁，结束睡眠后也能直接保存。</div>\n    ${st.wpErr ? `<div class=\"tiny\" style=\"color:#ff9aa6\">${esc(st.wpErr)}</div>` : ''}\n    ${st.wp ? `<img src=\"${st.wp}\" style=\"width:100%;border-radius:12px;margin-top:10px;display:block\" alt=\"\">` : ''}\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"genSleepWallpaper\" ${st.wpLoading ? 'disabled' : ''}>${st.wp ? '重新生成' : '生成睡眠壁纸'}</button>\n      <button class=\"btn sm grow ${st.wp ? 'primary' : ''}\" data-act=\"downloadSleepWallpaper\" ${st.wp ? '' : 'disabled'}>下载</button></div>\n    <button class=\"btn block ghost sm mt8\" data-act=\"openSleepWallPrompt\">✏️ 改这套壁纸的提示词（当前：${esc(sleepWallStyleName(sleepWallStyle() === 'rotate' ? (st.wallStyleKey || 'calm') : sleepWallStyle()))}）</button>\n    <div class=\"chips mt6\">${SLEEP_WALL_STYLES.map(([k, n]) => `<button class=\"chip ${sleepWallStyle() === k ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"sleepWallStyle\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <button class=\"btn block ghost sm mt8\" data-act=\"sleepWallUpload\">⬆️ 用我自己的图片当睡眠壁纸</button></div>`\n      : `<div class=\"card\"><h3>陪伴角色（可多选 / 随机）</h3>\n    <div class=\"sub\">哄睡语音、睡前闲聊、睡眠壁纸、叫醒都由这里选出的角色陪你。多选时会随机挑一位开口。</div>\n    <div class=\"chips mt10\">${S.chars.length ? S.chars.map(c => `<button class=\"chip ${(cfg('sleepCharIds') || []).indexOf(c.id) >= 0 ? 'on' : ''}\" data-act=\"toggleSleepChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('') : `<div class=\"tiny\">还没有角色，请先在小手机聊天 APP 里创建</div>`}</div>\n    <div class=\"tiny mt6\">没选也不会卡住：开始睡眠时会先退到专注阵容，再没有就自动用第一位角色，并告诉你用的是谁。</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"randomSleepChar\">🎲 随机抽一位</button>\n      <button class=\"btn sm ghost grow\" data-act=\"clearSleepChar\">清空</button></div>\n    ${(cfg('sleepCharIds') || []).length ? `<div class=\"row wrap mt10\" style=\"gap:8px\">${(cfg('sleepCharIds') || []).map(id => { const c = charById(id); return c ? charAvatar(c) : ''; }).join('')}</div>` : ''}\n    <div class=\"chips mt10\">\n      <button class=\"chip ${cfg('sleepLullaby') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"sleepLullaby\">开始睡眠时生成哄睡语音</button>\n      <button class=\"chip ${cfg('sleepChat') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"sleepChat\">允许睡前闲聊</button>\n      <button class=\"chip ${cfg('sleepChatVoice') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"sleepChatVoice\">睡前闲聊的回复读出来</button>\n    </div>\n    <div class=\"tiny mt6\">开着=TA 每句回话都读出来（多花语音合成）；专注里的语音设置不管这里。</div>\n    <div class=\"chips mt6\">\n    </div></div>\n  <div class=\"card\"><h3>睡眠模式</h3>\n    <div class=\"chips mt6\">${SLEEP_MODES.map(([n, m]) => `<button class=\"chip ${dMode === n ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"sleepMode\" data-v=\"${n}\">${n} · ${m >= 60 ? (m / 60) + '小时' : m + '分钟'}</button>`).join('')}</div>\n    <label class=\"fl\">时长（分钟，可手动改；只是提醒，不强制结束）</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"sleepMin\" data-num=\"1\" value=\"${dMin}\">\n    <label class=\"fl\">多久不动屏幕算入睡（分钟）</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.sleepIdleMin\" value=\"${Number(cfg('sleepIdleMin') || 5)}\">\n    <div class=\"tiny mt10\" style=\"background:var(--card2);border-radius:10px;padding:10px;line-height:1.7\">\n      <b>计时规则（本次生效）</b>：<br>\n      · <b>酝酿睡意</b> = 还没睡的时间：和角色闲聊、切到别的 APP、手指碰屏幕，都算醒着。<br>\n      · <b>睡眠</b> = 你在睡眠页连续 ${Number(cfg('sleepIdleMin') || 5)} 分钟不动屏幕、也不互动之后，才开始计入。<br>\n      · 睡着后又碰了屏幕 → 安静计时归零，再安静满 ${Number(cfg('sleepIdleMin') || 5)} 分钟才继续计入。<br>\n      · 切到别的 APP 的时间不计入睡眠；若切走后直接睡了，结束时可在面板里一键按「从切走那刻起睡到现在」修正，也能手填分钟数。</div>\n    <div class=\"hr\"></div>\n    <h3>睡眠壁纸样式</h3>\n    <div class=\"chips mt6\">${SLEEP_WALL_STYLES.map(([k, n]) => `<button class=\"chip ${sleepWallStyle() === k ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"sleepWallStyle\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"openSleepWallPrompt\">✏️ 改这套提示词</button>\n      </div>\n    <div class=\"tiny mt6\">选「每次换一种」则每次开始睡眠自动换一套。提示词可以直接改，改完对之后生成的壁纸生效。</div>\n    <div class=\"row mt14\" style=\"gap:8px\"><button class=\"btn sleep grow\" data-act=\"startSleep\">开始睡眠</button>\n    <button class=\"btn ghost\" data-act=\"noTargetSleep\">不定时</button></div>\n    <button class=\"btn block mt8\" data-act=\"openInvite\" data-k=\"sleep\" style=\"background:linear-gradient(135deg,rgba(165,139,255,.28),rgba(124,140,255,.18));border-color:rgba(165,139,255,.45)\">💞 睡眠陪伴（邀请 TA 一起睡）</button>\n    <div class=\"tiny mt6\">和「开始睡眠」的区别：会先写一张邀请卡进聊天室、请 TA 应你一声，再开始记录。</div></div>`}\n  ${(!st || !st.running) && (S.lastSleepWall || S.lastSleepWallRef) ? `<div class=\"card\">\n    <div class=\"row between\"><h3>上次睡眠的纪念壁纸</h3><button class=\"btn sm ghost\" data-act=\"clearSleepWall\">清除</button></div>\n    <div class=\"tiny mt6\">${S.lastSleepInfo ? esc(S.lastSleepInfo.mode) + ' · 已睡 ' + fmtDur(S.lastSleepInfo.seconds) + ' · ' + hm(S.lastSleepInfo.startAt) : ''}</div>\n    <img src=\"${S.lastSleepWall}\" style=\"width:100%;border-radius:12px;margin-top:10px;display:block\" alt=\"\">\n    <button class=\"btn primary block mt10\" data-act=\"downloadSleepWallpaper\">⬇️ 下载这张壁纸</button>\n    <button class=\"btn block ghost mt8\" data-act=\"sleepWallUpload\">⬆️ 换成我自己的图片</button></div>` : ''}\n  <div class=\"card\"><div class=\"row between\"><h3>连续规律作息</h3>\n    <span class=\"pill ${sleepStreak() ? 'ok' : ''}\">已连续 ${sleepStreak()} 天</span></div>\n    <div class=\"tiny mt6\">每天睡满 ${Number(cfg('sleepValidHours') || 4)} 小时算达标 · 下一个奖励：连续 ${nextMile(sleepStreak())} 天</div>\n    <div class=\"bar mt10\"><i style=\"width:${clamp(sleepStreak() / nextMile(sleepStreak()) * 100, 0, 100)}%\"></i></div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>睡眠报告</h3><button class=\"btn sm\" data-act=\"gotoView\" data-view=\"sleepreport\">最近一份</button></div>\n    <div class=\"sub\">结束睡眠后自动生成：质量分析、睡眠观察、作息建议、角色碎碎念。报告会同步进角色的短期记忆。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>睡前故事</h3><button class=\"btn sm\" data-act=\"gotoView\" data-view=\"story\">去听</button></div>\n    <div class=\"sub\">角色用语音朗读睡前故事，可切换风格、时长与陪伴角色。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>语音闹钟</h3><button class=\"btn sm\" data-act=\"gotoView\" data-view=\"alarm\">设置</button></div>\n    <div class=\"sub\">${a.enabled ? `${esc(a.time)} · ${a.repeat ? '每天' : '仅一次'} · 由 ${esc(charName(a.charId || anyCharId()))} 唤醒` : '未开启'}</div></div>\n  <div class=\"card\"><h3>睡眠记录</h3>\n    ${recent.length ? recent.map(r => `<div class=\"item\" data-act=\"sleepRec\" data-id=\"${esc(r.id)}\" style=\"cursor:pointer\">\n      <div class=\"ic\">💤</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(r.mode || '睡眠')} · ${fmtDur(r.seconds)}${(r.breaks || []).length ? ` · 中断 ${r.breaks.length} 次` : ''}</div>\n      <div class=\"tiny\">${r.date} ${hm(r.startAt)} – ${hm(r.endAt)}${r.drowsySec != null ? ' · 酝酿 ' + fmtDur(r.drowsySec) + ' / 入睡 ' + fmtDur(r.sleepSec != null ? r.sleepSec : Math.max(0, r.seconds - r.drowsySec)) : ''} · ${r.report ? '点开看睡眠报告' : '点开可生成报告'}</div></div>\n      <div class=\"ic\">›</div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:12px\">还没有记录</div>`}\n    <div class=\"tiny mt6\">点任意一条记录可以打开那次的睡眠报告与中断点。</div>\n    ${recent.length > 1 ? `<div class=\"tiny mt6\">近 ${recent.length} 次平均 ${fmtDur(sum(recent.map(r => r.seconds)) / recent.length)}</div>` : ''}</div>`;\n};\nVIEWS.sleepreport = function () {\n  const R = S.report;\n  if (!R || !R.rec) return `<div class=\"card\"><h3>还没有睡眠报告</h3>\n    <div class=\"sub\">结束一次睡眠记录后会自动生成；也可以从睡眠记录里挑一条来生成。</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"sleep\">去睡眠页</button></div>`;\n  const rec = R.rec, streak = sleepStreak(), mile = nextMile(streak);\n  const brks = rec.breaks || [];\n  const breakCard = brks.length ? `<div class=\"card\"><h3>🌗 中途醒来（${brks.length} 次）</h3>\n    <div class=\"tiny mt6\">这些是你当时标记的中断点：睡眠没有中断、计时照走，但碎片化会影响恢复效果。</div>\n    ${brks.map((b, i) => `<div class=\"item\"><div class=\"ic\">${i + 1}</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${hm(b.at)}${b.note ? ' · ' + esc(b.note) : ''}</div>\n      <div class=\"tiny\">入睡后第 ${Math.max(0, Math.round((b.at - rec.startAt) / 60000))} 分钟</div></div></div>`).join('')}\n    <div class=\"mt10\"><div class=\"tiny\">睡眠被切成 ${brks.length + 1} 段</div>\n      <div class=\"bar mt6\"><i style=\"width:${Math.round(100 / (brks.length + 1))}%\"></i></div></div></div>` : '';\n  const drowsySec = (rec.drowsySec != null ? rec.drowsySec : 0);\n  const sleepSecReal = (rec.sleepSec != null ? rec.sleepSec : Math.max(0, rec.seconds - drowsySec));\n  const deepSec = Number(rec.deepSec) || 0;\n  const durCard = `<div class=\"card\"><h3>⏱ 时长拆分</h3>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:19px;font-weight:600\">${fmtDur(rec.seconds)}</div><div class=\"tiny\">总时长</div></div>\n      <div class=\"grow center\"><div style=\"font-size:19px;font-weight:600;color:${drowsySec >= 1800 ? 'var(--gold)' : 'inherit'}\">${fmtDur(drowsySec)}</div><div class=\"tiny\">酝酿睡意</div></div>\n      <div class=\"grow center\"><div style=\"font-size:19px;font-weight:600;color:var(--teal)\">${fmtDur(sleepSecReal)}</div><div class=\"tiny\">实际入睡</div></div>\n      <div class=\"grow center\"><div style=\"font-size:19px;font-weight:600;color:#b9a2ff\">${deepSec ? fmtDur(deepSec) : '—'}</div><div class=\"tiny\">预计深睡</div></div>\n    </div>\n    <div class=\"bar mt10\"><i style=\"width:${rec.seconds ? clamp(sleepSecReal / rec.seconds * 100, 0, 100) : 100}%\"></i></div>\n    <div class=\"tiny mt6\">${hm(rec.startAt)} 开始记录 → 共 ${fmtDur(rec.seconds)} 里只有 ${fmtDur(sleepSecReal)} 记作睡眠（规则：连续 ${Number(rec.idleMin || cfg('sleepIdleMin') || 5)} 分钟不动屏幕、不互动之后才开始计入）→ ${hm(rec.endAt)} 结束记录。${(rec.chat || []).length ? ' 睡前和角色聊了 ' + (rec.chat || []).length + ' 句。' : ''}\n      ${rec.manual ? ' <b>睡眠时长由你手动修正过。</b>' : ''}${rec.asleep ? ' 自评：' + esc(asleepLabel(rec.asleep)) + '。' : ''}${deepSec ? ' 预计深度睡眠 ' + fmtDur(deepSec) + '（占实际入睡 ' + Math.round(deepSec / Math.max(1, sleepSecReal) * 100) + '%）。' : ''}</div>\n    ${rec.lullaby ? `<div class=\"tiny mt6\">哄睡语：${esc(rec.lullaby)}</div>` : ''}\n    ${rec.inviteLine ? `<div class=\"tiny mt6\">他应你的话：${esc(rec.inviteLine)}</div>` : ''}</div>`;\n  if (!R.loading && !R.quality && !R.observe) return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(165,139,255,.18),rgba(255,255,255,.03));border-color:rgba(165,139,255,.3)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>睡眠报告 · ${esc(rec.date)}</h3>\n      <div class=\"tiny\">${esc(rec.mode || '睡眠')} · ${hm(rec.startAt)} – ${hm(rec.endAt)} · 共 ${fmtDur(rec.seconds)}</div></div>\n      <div style=\"font-size:30px\">🌙</div></div></div>\n  ${durCard}\n  ${breakCard}\n  <div class=\"card\"><h3>这份记录还没有生成报告</h3>\n    <div class=\"tiny\">点下面让角色看一遍这次的睡眠数据（含中断点），写出质量分析、睡眠观察、作息建议和碎碎念。</div>\n    <button class=\"btn primary block mt10\" data-act=\"genThisReport\">生成这份报告</button>\n    <button class=\"btn ghost block mt8\" data-act=\"gotoView\" data-view=\"sleep\">回睡眠页</button></div>`;\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(165,139,255,.18),rgba(255,255,255,.03));border-color:rgba(165,139,255,.3)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>睡眠报告 · ${esc(rec.date)}</h3>\n      <div class=\"tiny\">${esc(rec.mode || '睡眠')} · ${hm(rec.startAt)} – ${hm(rec.endAt)} · 共 ${fmtDur(rec.seconds)}${brks.length ? ' · 中途醒来 ' + brks.length + ' 次' : ''}</div></div>\n      <div style=\"font-size:30px\">🌙</div></div>\n    ${R.loading ? `<div class=\"tiny mt10\"><span class=\"spin\"></span> 角色正在看你的睡眠数据…</div>` : ''}</div>\n  ${R.loading ? '' : `\n  ${durCard}\n  ${breakCard}\n  <div class=\"card\"><h3>🫧 睡眠质量分析</h3><div style=\"font-size:13.5px;line-height:1.75;margin-top:6px\">${esc(R.quality || '—').replace(/\\n/g, '<br>')}</div></div>\n  <div class=\"card\"><h3>👀 睡眠观察</h3><div style=\"font-size:13.5px;line-height:1.75;margin-top:6px\">${esc(R.observe || '—').replace(/\\n/g, '<br>')}</div></div>\n  <div class=\"card\"><h3>🌿 健康作息建议</h3><div style=\"font-size:13.5px;line-height:1.75;margin-top:6px\">${esc(R.advice || '—').replace(/\\n/g, '<br>')}</div></div>\n  <div class=\"card\" style=\"background:var(--card2)\"><div class=\"row\">${charAvatar(charById(R.charId))}\n    <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.8px\"><div class=\"who\">${esc(charName(R.charId))} · 碎碎念</div>${esc(R.murmur || '好好睡，我在。')}</div></div>\n    ${R.murmur ? `<button class=\"btn sm ghost mt10\" data-act=\"replayReport\">🔊 再听一遍</button>` : ''}</div>\n  <div class=\"card\"><div class=\"row between\"><h3>连续规律作息</h3><span class=\"pill ${streak ? 'ok' : ''}\">已连续 ${streak} 天</span></div>\n    <div class=\"tiny mt6\">每天睡满 ${Number(cfg('sleepValidHours') || 4)} 小时算达标 · 下一次奖励：连续 ${mile} 天</div>\n    <div class=\"bar mt10\"><i style=\"width:${clamp(streak / mile * 100, 0, 100)}%\"></i></div>\n    ${R.reward ? `<div class=\"hr\"></div><b style=\"color:var(--gold)\">🎉 达成连续 ${R.reward.streak} 天</b>\n      <div class=\"tiny mt6\">${esc((R.reward.ask && R.reward.ask.line) || R.reward.line || '')}</div>\n      ${R.reward.ask ? `<div class=\"card mt10\" style=\"background:var(--card2)\"><div class=\"tiny\">TA 要给你</div>\n        <div style=\"font-size:14px;margin-top:4px\"><b>${esc(R.reward.ask.want || '')}</b></div></div>\n        <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"rewards\">去领取奖励</button>` : ''}` : ''}</div>\n    ${rec.albumId ? `<button class=\"btn ghost grow\" data-act=\"albumOpen\" data-id=\"${esc(rec.albumId)}\">🌙 看那晚的壁纸</button>` : ''}\n    <button class=\"btn primary grow\" data-act=\"gotoView\" data-view=\"sleep\">回睡眠页</button></div>\n  <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"regenSleepReport\">重新生成报告</button>\n    <button class=\"btn ghost grow\" data-act=\"reportFav\">⭐ 收藏这份报告</button></div>\n  <div class=\"tiny center mt6\">报告会存在这条睡眠记录里，随时从「睡眠 → 睡眠记录」点开重看。</div>`}`;\n};\nVIEWS.story = function () {\n  const st = S.story, sty = cfg('story') || {};\n  const styles = ['温柔治愈', '童话', '科幻夜航', '古风', '哲理小品', '星空漫谈'];\n  const mins = [5, 10, 20, 30];\n  const cid = S.draft.storyChar || sty.charId || anyCharId();\n  const saved = (st && (st.audioRefs || []).filter(Boolean).length) || 0;\n  return st ? `<div class=\"card\"><div class=\"row between\"><h3>${esc(st.title)}</h3>\n      <span class=\"pill ${st.playing ? 'run' : ''}\">${st.playing ? '朗读中' : (st.idx >= st.paras.length ? '已听完' : '已暂停')}</span></div>\n    <div class=\"tiny mt6\">${esc(st.style)} · 约 ${st.minutes} 分钟 · 由 ${esc(charName(st.charId))} 讲述 · 第 ${Math.min(st.idx + 1, st.paras.length)}/${st.paras.length} 段</div>\n    <div class=\"tiny mt6\">语音已留存 ${saved}/${st.paras.length} 段：听过或正要听的段落会自动存进媒体库，下次重听不用重新生成。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">${st.playing ? `<button class=\"btn grow\" data-act=\"pauseStory\">⏸ 暂停</button>`\n      : `<button class=\"btn sleep grow\" data-act=\"resumeStory\">▶️ ${st.idx > 0 && st.idx < st.paras.length ? '接着听到第 ' + (st.idx + 1) + ' 段' : '开始朗读'}</button>`}\n      <button class=\"btn ghost grow\" data-act=\"stopStory\">⏹ 结束</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn ghost sm grow\" data-act=\"storyRestart\">↺ 从头听</button>\n      <button class=\"btn ghost sm grow\" data-act=\"saveStoryAudio\">💾 保存语音</button>\n      <button class=\"btn ghost sm grow\" data-act=\"storyFav\">⭐ 收藏</button></div>\n    <button class=\"btn sleep block mt8\" data-act=\"storyWhole\" ${S.loading === 'whole' ? 'disabled' : ''}>\n      ${S.loading === 'whole' ? '正在合成整篇音频…' : '🎧 整篇连播'}</button>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn ghost sm grow\" data-act=\"storyExport\">💾 导出整篇音频</button></div>\n    <div class=\"tiny mt6\">整篇连播把这个故事合成成<b>一段音频</b>一次播完，中间不再逐段请求、听重复听也不用重新合成。${st.wholeRef ? '本次已存好整篇音频，再点无需重新合成。' : ''}<br>\n    <span style=\"color:#ffb37a\">实测：退出 APP 会停止播放</span>——宿主在 APP 关闭时会停掉自己的播放器，所以想彻底脱离 APP 听，只能点「导出整篇音频」把文件存出来，再用手机自己的播放器播（能否找到存下来的文件，取决于小手机里有没有可见的媒体/文件入口）。</div></div>\n    <div class=\"card\"><div class=\"story\">${st.paras.map((p, i) => `<p id=\"para${i}\" class=\"${i === st.idx && st.playing ? 'playing' : ''}\" style=\"${i < st.idx ? 'opacity:.45' : ''}\">${esc(p)}</p>`).join('')}</div></div>`\n    : `<div class=\"card\"><h3>故事风格</h3><div class=\"chips mt6\">${styles.map(x => `<button class=\"chip ${(S.draft.storyStyle || sty.style) === x ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"storyStyle\" data-v=\"${x}\">${x}</button>`).join('')}</div>\n    <h3 class=\"mt14\">时长</h3><div class=\"chips mt6\">${mins.map(m => `<button class=\"chip ${(S.draft.storyMin || sty.minutes) === m ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"storyMin\" data-v=\"${m}\" data-num=\"1\">${m} 分钟</button>`).join('')}</div>\n    <h3 class=\"mt14\">谁来读</h3><div class=\"chips mt6\">${S.chars.length ? S.chars.map(c => `<button class=\"chip ${cid === c.id ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"storyChar\" data-v=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('') : `<div class=\"tiny\">还没有角色</div>`}</div>\n    <button class=\"btn sleep block mt14\" data-act=\"genStory\">生成故事并开始朗读</button>\n    ${S.loading === 'story' ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> ${esc(charName(cid))} 正在准备故事…</div>` : ''}\n    <div class=\"tiny mt10\">按每分钟约 200 字生成，分段落逐段朗读；每段语音会存进媒体库，重开 APP 也能接着听。</div></div>\n    ${(S.stories || []).length ? `<div class=\"card\"><h3>往期故事（${(S.stories || []).length}）</h3>\n      ${(S.stories || []).slice(0, 10).map(x => `<div class=\"item\"><div class=\"ic\">🌙</div>\n        <div class=\"grow\"><div style=\"font-size:13px\">${esc(x.title || '睡前故事')}</div>\n        <div class=\"tiny\">${esc(x.date || '')} · ${esc(x.style || '')} · ${(x.paras || []).length} 段 · 听到第 ${Math.min((x.idx || 0) + 1, (x.paras || []).length)} 段 · 语音留存 ${(x.audioRefs || []).filter(Boolean).length} 段${x.wholeRef ? ' · 已存整篇音频' : ''}</div></div>\n        <button class=\"btn sm\" style=\"flex:0 0 auto\" data-act=\"openStory\" data-id=\"${esc(x.id)}\">${(x.idx || 0) >= (x.paras || []).length ? '重听' : '接着听'}</button>\n        <button class=\"btn sm ghost\" data-act=\"delStory\" data-id=\"${esc(x.id)}\">删</button></div>`).join('')}</div>` : ''}`;\n};\nVIEWS.alarm = function () {\n  const a = cfg('alarm') || {};\n  return `<div class=\"card\"><h3>起床闹钟</h3>\n    <label class=\"fl\">时间</label><input class=\"input\" type=\"time\" data-in=\"alarmTime\" value=\"${esc(a.time || '07:00')}\">\n    <label class=\"fl\">音量提示</label><input type=\"range\" min=\"0\" max=\"100\" data-in=\"alarmVolume\" data-num=\"1\" value=\"${a.volume || 70}\">\n    <div class=\"tiny\">当前 ${a.volume || 70}%（音量由系统与语音服务决定，这里仅作提示）</div>\n    <div class=\"chips mt10\"><button class=\"chip ${a.repeat ? 'on' : ''}\" data-act=\"toggleAlarmField\" data-k=\"repeat\">每天重复</button>\n    <button class=\"chip ${a.enabled ? 'on' : ''}\" data-act=\"toggleAlarmField\" data-k=\"enabled\">启用闹钟</button></div>\n    <label class=\"fl\">谁来叫醒</label><div class=\"chips\">${S.chars.length ? S.chars.map(c => `<button class=\"chip ${(a.charId || anyCharId()) === c.id ? 'on' : ''}\" data-act=\"setAlarmChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('') : `<div class=\"tiny\">还没有角色</div>`}</div>\n    <div class=\"row mt14\" style=\"gap:8px\"><button class=\"btn sleep grow\" data-act=\"saveAlarm\">保存闹钟</button>\n    <button class=\"btn ghost grow\" data-act=\"testAlarm\">试听唤醒</button></div>\n    <div class=\"tiny mt10\">到点弹通知 + 角色语音唤醒；保存时还会在系统时钟立一个闹钟兜底（APK，被杀也响）。语音唤醒仍需打开小手机。</div></div>\n  ${(S.alarms || []).length ? `<div class=\"card\"><h3>已排程</h3>${S.alarms.slice(0, 5).map(x => `<div class=\"item\">\n    <div class=\"ic\">⏰</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(x.time || '')} ${x.repeat ? '每天' : '仅一次'}</div>\n    <div class=\"tiny\">${esc(charName(x.charId))} 唤醒</div></div>\n    <button class=\"btn sm ghost\" data-act=\"delAlarm\" data-id=\"${esc(x.id)}\">删</button></div>`).join('')}</div>` : ''}`;\n};\n/* ==========================================================\n   视图 · 数据 / 日历 / 礼物 / 账本\n   ========================================================== */\nfunction lastNDays(n) {\n  const out = [], now = new Date();\n  for (let i = n - 1; i >= 0; i--) {\n    const d = new Date(now); d.setDate(now.getDate() - i);\n    out.push({ key: dkey(d), label: ['日', '一', '二', '三', '四', '五', '六'][d.getDay()], date: d });\n  }\n  return out;\n}\nfunction sessionsOn(key) { return (S.sessions || []).filter(s => s.date === key); }\nVIEWS.stats = function () {\n  const days = lastNDays(7);\n  const focusMin = days.map(d => Math.round(focusSecOf(sessionsOn(d.key)) / 60));\n  /* 睡眠统计口径 = 实际入睡时长（sleepSec）：总时长里含「酝酿睡意」（睡前聊天/玩手机）那段，\n     不该算成睡眠。旧记录没有 sleepSec 字段时回落到总时长。 */\n  const sleepH = days.map(d => sum((S.sleeps || []).filter(s => s.date === d.key).map(s => (s.sleepSec != null ? s.sleepSec : s.seconds))) / 3600);\n  const maxF = Math.max(30, Math.max.apply(null, focusMin.concat([1])));\n  const maxS = Math.max(1, Math.max.apply(null, sleepH));\n  const all = S.sessions || [];\n  const passed = all.filter(s => s.status === 'passed').length;\n  const failed = all.filter(s => s.status === 'failed').length;\n  const vio = sum(all.map(s => (s.violations || []).filter(v => !v.excused).length));\n  const wc = {};\n  privOf('weak', 200).forEach(w => { const k = String(w.content || '').split('：')[0].slice(0, 16); if (k) wc[k] = (wc[k] || 0) + 1; });\n  const top = Object.keys(wc).sort((a, b) => wc[b] - wc[a]).slice(0, 6);\n  const mistakes = privOf('mistake', 6);\n  return `\n  <div class=\"card\"><div class=\"row between\"><h3>本周专注时长</h3><span class=\"tiny\">共 ${sum(focusMin)} 分钟</span></div>\n    <div class=\"bars\">${days.map((d, i) => `<div class=\"col\"><div class=\"vl\">${focusMin[i] || ''}</div>\n      <div class=\"bg\" style=\"height:${Math.max(3, focusMin[i] / maxF * 82)}%\"></div><div class=\"lb\">${d.label}</div></div>`).join('')}</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>本周睡眠时长</h3><span class=\"tiny\">共 ${sum(sleepH).toFixed(1)} 小时（按实际入睡算）</span></div>\n    <div class=\"bars\">${days.map((d, i) => `<div class=\"col\"><div class=\"vl\">${sleepH[i] ? sleepH[i].toFixed(1) : ''}</div>\n      <div class=\"bg sleep\" style=\"height:${Math.max(3, sleepH[i] / maxS * 82)}%\"></div><div class=\"lb\">${d.label}</div></div>`).join('')}</div></div>\n  <div class=\"card\"><h3>总览</h3><div class=\"row wrap mt10\" style=\"gap:10px\">\n    <div class=\"grow center\" style=\"min-width:30%\"><div style=\"font-size:19px;font-weight:600\">${(Math.round(focusSecOf(all) / 60) / 60).toFixed(1)}<span class=\"tiny\">h</span></div><div class=\"tiny\">累计专注</div></div>\n    <div class=\"grow center\" style=\"min-width:30%\" data-act=\"openChecks\" data-f=\"passed\"><div style=\"font-size:19px;font-weight:600;color:var(--teal)\">${passed}</div><div class=\"tiny\">考核通过 ›</div></div>\n    <div class=\"grow center\" style=\"min-width:30%\" data-act=\"openChecks\" data-f=\"failed\"><div style=\"font-size:19px;font-weight:600;color:${failed ? '#ff9aa6' : 'inherit'}\">${failed}</div><div class=\"tiny\">考核失败 › 点开看是哪次</div></div>\n    <div class=\"grow center\" style=\"min-width:30%\"><div style=\"font-size:19px;font-weight:600;color:${vio ? '#ff9aa6' : 'inherit'}\">${vio}</div><div class=\"tiny\">违规次数</div></div>\n    <div class=\"grow center\" style=\"min-width:30%\"><div style=\"font-size:19px;font-weight:600\">${(S.puns || []).length}</div><div class=\"tiny\">惩罚次数</div></div>\n    <div class=\"grow center\" style=\"min-width:30%\"><div style=\"font-size:19px;font-weight:600\">${mistakeList().length}</div><div class=\"tiny\">错题条数</div></div>\n  </div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"calendar\">📅 打卡日历</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"mistakes\">📕 错题本</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"periodrep\">📈 学习报告</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"trend\">📊 专注趋势</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"openChecks\" data-f=\"all\">✅ 校验记录（${reviewedList().length}）</button>\n      <button class=\"btn sm grow\" data-act=\"openChecks\" data-f=\"failed\">⚠️ 考核失败（${failed}）</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"goals\">🎯 目标倒计时</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"coin\">🪙 专注币</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\">      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"sleepreport\">🌙 睡眠报告</button></div>\n    <div class=\"tiny mt10\">连续规律作息：已连续 <b>${sleepStreak()}</b> 天 · 下一次奖励在 ${nextMile(sleepStreak())} 天</div></div>\n  <div class=\"card\"><h3>薄弱点 Top</h3>${top.length ? top.map((k, i) => `<div class=\"item\">\n    <div class=\"ic\">${['①', '②', '③', '④', '⑤', '⑥'][i]}</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(k)}</div>\n    <div class=\"tiny\">出现 ${wc[k]} 次</div></div></div>`).join('') : `<div class=\"empty\" style=\"padding:12px\">完成带出题的校验后会出现薄弱点画像</div>`}</div>\n  <div class=\"card\"><div class=\"row between\"><h3>最近错题</h3><span class=\"tiny\">角色看不到</span></div>\n    ${mistakes.length ? mistakes.map(m => `<div class=\"item\"><div class=\"ic\">✏️</div>\n      <div class=\"grow\"><div style=\"font-size:12.5px;line-height:1.55\">${esc(m.q || m.content)}</div><div class=\"tiny\">${m.date}</div></div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:12px\">暂无错题</div>`}\n    <button class=\"btn block ghost sm mt6\" data-act=\"gotoView\" data-view=\"weak\">查看全部私密记录</button></div>`;\n};\nVIEWS.calendar = function () {\n  const base = S.draft.calMonth ? new Date(S.draft.calMonth) : new Date();\n  const y = base.getFullYear(), m = base.getMonth();\n  const startWd = new Date(y, m, 1).getDay(), daysIn = new Date(y, m + 1, 0).getDate(), todayK = dkey();\n  let cells = '';\n  for (let i = 0; i < startWd; i++) cells += `<div class=\"d blank\"></div>`;\n  for (let i = 1; i <= daysIn; i++) {\n    const k = `${y}-${pad2(m + 1)}-${pad2(i)}`;\n    const ss = sessionsOn(k);\n    const pass = ss.filter(s => s.status === 'passed').length, fail = ss.filter(s => s.status === 'failed').length;\n    const slept = (S.sleeps || []).some(s => s.date === k);\n    /* 每一天都能点：点开看那天的专注 / 睡眠 / 背书明细 */\n    const picked = String(S.draft.calDay || '') === k;\n    cells += `<div class=\"d ${pass ? 'ok' : (fail ? 'part' : '')} ${k === todayK ? 'today' : ''}\" data-act=\"calDay\" data-k=\"${k}\" style=\"cursor:pointer${picked ? ';box-shadow:0 0 0 2px var(--accent)' : ''}\">${i}${slept && !pass ? '<span style=\"position:absolute;bottom:3px;width:4px;height:4px;border-radius:50%;background:#a58bff\"></span>' : ''}</div>`;\n  }\n  const ms = (S.sessions || []).filter(s => s.date && s.date.startsWith(`${y}-${pad2(m + 1)}`));\n  return `<div class=\"card\"><div class=\"row between\">\n      <button class=\"btn sm ghost\" data-act=\"calMove\" data-v=\"-1\">‹ 上月</button><b>${y} 年 ${m + 1} 月</b>\n      <button class=\"btn sm ghost\" data-act=\"calMove\" data-v=\"1\">下月 ›</button></div>\n    <div class=\"cal mt14\">${['日', '一', '二', '三', '四', '五', '六'].map(w => `<div class=\"wd\">${w}</div>`).join('')}${cells}</div>\n    <div class=\"tiny mt10\">🟦 考核通过　🟪 有记录但未过　🟣小点 有睡眠记录</div></div>\n  <div class=\"card\"><h3>本月记录（${ms.length} 次专注）</h3>\n    ${ms.length ? ms.sort((a, b) => b.startAt - a.startAt).map(s => `<div class=\"item\">\n      <div class=\"ic\">${s.status === 'passed' ? '✅' : s.status === 'failed' ? '⚠️' : '⏳'}</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${Math.round((s.totalFocusSec || 0) / 60)} 分钟 · ${(s.plan || []).filter(t => t.done).length}/${(s.plan || []).length} 项</div>\n      <div class=\"tiny\">${s.date} ${hm(s.startAt)} · ${s.status === 'passed' ? '考核通过' : s.status === 'failed' ? '考核失败' : '进行中／未校验'}${s.quizTotal ? ' · 答对 ' + s.quizScore + '/' + s.quizTotal : ''}</div>\n      ${s.summary ? `<div class=\"tiny\">总结：${esc(s.summary)}</div>` : ''}</div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:12px\">这个月还没有记录</div>`}</div>\n  ${calDayHTML()}`;\n};\n/* 点选某一天 → 那天的专注 / 睡眠 / 背书明细。三个数据源都从本机读，不额外请求。 */\nfunction calDayHTML() {\n  const k = String(S.draft.calDay || '');\n  if (!k) return `<div class=\"card tight\"><div class=\"tiny\">点上面任意一天，就能看到那天的专注、睡眠和背书明细。</div></div>`;\n  const ss = sessionsOn(k).slice().sort((a, b) => (b.startAt || 0) - (a.startAt || 0));\n  const sl = (S.sleeps || []).filter(x => x.date === k).slice().sort((a, b) => (b.startAt || 0) - (a.startAt || 0));\n  const rl = (S.rlogs || []).filter(x => x.date === k).slice().sort((a, b) => (b.at || 0) - (a.at || 0));\n  const pass = ss.filter(s => s.status === 'passed').length;\n  const fail = ss.filter(s => s.status === 'failed').length;\n  const focusMin = Math.round(sum(ss.map(s => s.totalFocusSec || 0)) / 60);\n  const rcN = sum(rl.map(x => Number(x.total) || 0));\n  const rcCoin = sum(rl.map(x => Number(x.coin) || 0));\n  const sleepSec = sum(sl.map(x => (x.sleepSec != null ? x.sleepSec : x.seconds)));\n  return `<div class=\"card\" style=\"border-color:rgba(124,140,255,.45)\">\n    <div class=\"row between\"><h3>${esc(k)} 的记录</h3>\n      <button class=\"btn sm ghost\" data-act=\"calDayClose\">收起</button></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${focusMin}<span class=\"tiny\">分</span></div><div class=\"tiny\">专注</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600;color:var(--teal)\">${pass}</div><div class=\"tiny\">通过</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600;color:${fail ? '#ff9aa6' : 'inherit'}\">${fail}</div><div class=\"tiny\">未过</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${rcN}</div><div class=\"tiny\">背书条数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${sleepSec ? (sleepSec / 3600).toFixed(1) : '—'}</div><div class=\"tiny\">睡眠(时)</div></div>\n    </div>\n    ${sl.length ? `<div class=\"hr\"></div><div class=\"tiny\">🌙 睡眠</div>${sl.map(x => `<div class=\"item\" style=\"padding:7px 0\">\n      <div class=\"ic\">🌙</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${esc(x.mode || '睡眠')} · 总 ${fmtDur(x.seconds)} · 实际入睡 ${fmtDur(x.sleepSec != null ? x.sleepSec : x.seconds)}</div>\n      <div class=\"tiny\">${hm(x.startAt)} – ${hm(x.endAt)}${(x.breaks || []).length ? ' · 中途醒来 ' + x.breaks.length + ' 次' : ''}${x.asleep ? ' · 自评 ' + esc(asleepLabel(x.asleep)) : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"sleepRec\" data-id=\"${esc(x.id)}\">看报告</button></div>`).join('')}` : ''}\n    ${ss.length ? `<div class=\"hr\"></div><div class=\"tiny\">🎯 专注</div>${ss.map(s => `<div class=\"item\" style=\"padding:7px 0\">\n      <div class=\"ic\">${s.status === 'passed' ? '✅' : s.status === 'failed' ? '⚠️' : '⏳'}</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${Math.round((s.totalFocusSec || 0) / 60)} 分钟 · ${(s.plan || []).filter(t => t.done).length}/${(s.plan || []).length} 项 · ${s.status === 'passed' ? '考核通过' : s.status === 'failed' ? '考核失败' : '未校验'}</div>\n      <div class=\"tiny\">${hm(s.startAt)}${s.quizTotal ? ' · 答对 ' + s.quizScore + '/' + s.quizTotal : ''}${s.summary ? ' · ' + esc(String(s.summary).slice(0, 30)) : ''}</div></div>\n      ${s.reviewQs ? `<button class=\"btn sm ghost\" data-act=\"checkOpen\" data-id=\"${esc(s.id || s.dbId)}\">看校验</button>` : ''}\n    </div>`).join('')}` : ''}\n    ${rl.length ? `<div class=\"hr\"></div><div class=\"tiny\">📖 背书（${rcN} 条${rcCoin ? ' · +' + rcCoin + ' 币' : ''}）</div>\n      ${rl.map(x => `<div class=\"item\" style=\"padding:7px 0\"><div class=\"ic\">📖</div>\n        <div class=\"grow\"><div class=\"tiny\">${hm(x.at)} · ${x.total || 0} 条${x.dictationN ? ' · 默写 ' + x.dictationN : ''}${Number(x.coin) ? ' · +' + x.coin + ' 币' : ''}</div>\n        <div class=\"tiny\" style=\"color:var(--dim2)\">${x.scope === 'chat' ? '抽背' : (x.bookId ? esc(rcBookName(x.bookId)) : '综合')}</div></div></div>`).join('')}` : ''}\n    ${(!sl.length && !ss.length && !rl.length) ? `<div class=\"tiny mt8\">这一天没有记录。</div>` : ''}\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"periodrep\">看这周的報告</button>\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"rcstats\">看背书统计</button>\n    </div>\n  </div>`;\n}\nVIEWS.gifts = function () {\n  const all = S.gifts || [];\n  const fromThem = all.filter(x => x.from === 'char'), fromMe = all.filter(x => x.from !== 'char');\n  const grid = (list, label) => list.length ? `<div class=\"card\">\n    <div class=\"row between\"><h3>${label}（${list.length}）</h3><span class=\"tiny\">价值 ¥${sum(list.map(x => x.price)).toLocaleString()}</span></div>\n    <div class=\"row wrap mt10\" style=\"gap:12px\">${list.map(x => `<div style=\"width:calc(33.3% - 8px);text-align:center\">\n      <div style=\"font-size:30px\">${esc(x.emoji || '🎁')}</div><div class=\"tiny ellip\">${esc(x.name)}</div>\n      <div class=\"tiny\">${esc(charName(x.charId))}</div></div>`).join('')}</div></div>` : '';\n  return `<div class=\"card\"><h3>礼物图鉴（${all.length}）</h3>\n    <div class=\"sub\">「TA 送我的」是角色给你的奖励礼物；「我送的」是你主动送或在惩罚里买的。</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"buyGiftFree\">主动送一件礼物</button>\n    <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"ledger\">看账本</button></div></div>\n  ${grid(fromThem, '🎁 TA 送我的')}${grid(fromMe, '我送的礼物')}\n  ${all.length ? '' : '<div class=\"empty\">还没有礼物</div>'}`;\n};\nVIEWS.ledger = function () {\n  const l = S.ledger || [];\n  const income = sum(l.filter(x => x.type === 'income').map(x => x.amount));\n  const out = sum(l.filter(x => x.type === 'pay' || x.type === 'redpack').map(x => x.amount));\n  const gift = sum(l.filter(x => x.type === 'gift').map(x => x.amount));\n  const realCount = l.filter(x => x.real).length;\n  return `<div class=\"card\"><h3>账本</h3><div class=\"row mt10\">\n    <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600;color:var(--teal)\">¥${income.toLocaleString()}</div><div class=\"tiny\">TA 给我的</div></div>\n    <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">¥${out.toLocaleString()}</div><div class=\"tiny\">惩罚转账</div></div>\n    <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">¥${gift.toLocaleString()}</div><div class=\"tiny\">礼物支出</div></div>\n    <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${l.length}</div><div class=\"tiny\">笔数</div></div></div>\n    <div class=\"tiny mt10\">「TA 给我的」金额取自 TA 在聊天室里回复的原文（凭证在奖励中心可查）；小手机钱包只支持支出，所以这部分不会真的加到你的余额。其中 ${realCount} 笔支出是从钱包<b>真实扣款</b>的。</div></div>\n  <div class=\"card\">${l.length ? l.slice(0, 60).map(x => {\n    const isIn = x.type === 'income';\n    const icon = isIn ? (String(x.note || '').indexOf('红包') >= 0 ? '🧧' : '💰') : x.type === 'pay' ? '💸' : x.type === 'redpack' ? '🧧' : '🎁';\n    return `<div class=\"item\"><div class=\"ic\">${icon}</div><div class=\"grow\"><div style=\"font-size:13px\">${esc(x.note || '')}</div>\n      <div class=\"tiny\">${dkey(new Date(x.at))} ${hm(x.at)} · ${esc(charName(x.charId))} · ${isIn ? 'TA 给我的' : x.real ? '真实扣款' : '仅记账'}</div></div>\n      <div style=\"font-size:14px;color:${isIn ? 'var(--teal)' : '#ff9aa6'}\">${isIn ? '+' : '-'}¥${Number(x.amount || 0).toLocaleString()}</div></div>`;\n  }).join('') : `<div class=\"empty\">还没有记录</div>`}</div>`;\n};\n/* ==========================================================\n   视图 · 我的\n   ========================================================== */\nVIEWS.me = function () {\n  const lib = cfg('punishLib') || [], texts = cfg('punishTexts') || [], wl = cfg('whitelist') || [];\n  return `\n  <div class=\"card hero-soft\"><h3>我的东西放哪了</h3>\n    <div class=\"tiny mt6\">内容和记录都收进这六个大类了，每个里面页顶都有标签切换。</div>\n    <div class=\"hubgrid\">\n      ${[['plan', '🗓', '计划与邀请'], ['learn', '📕', '学习档案'], ['motiv', '💞', '激励中心'],\n         ['insight', '📈', '报告与趋势'], ['prize', '🎁', '奖励与账本'], ['content', '🖼', '内容库']].map(([k, ic, n]) => `\n        <button class=\"hubcell\" data-act=\"gotoView\" data-view=\"${k}\"><span class=\"hi\">${ic}</span><span class=\"hn\">${n}</span></button>`).join('')}\n    </div>\n  </div>\n  <div class=\"card\"><h3>🔒 锁机（分级）</h3>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${assistLevelNow() === 'L3' ? 'on' : ''}\" data-act=\"focusLevelPick\" data-v=\"L3\">⚑ L3 死锁</button>\n      <button class=\"chip ${assistLevelNow() === 'L2' ? 'on' : ''}\" data-act=\"focusLevelPick\" data-v=\"L2\">🛰 L2 看守</button>\n      <button class=\"chip ${assistLevelNow() === 'L1' ? 'on' : ''}\" data-act=\"focusLevelPick\" data-v=\"L1\">🛡 L1 提醒</button>\n      <button class=\"chip ${assistLevelNow() === 'off' ? 'on' : ''}\" data-act=\"focusLevelPick\" data-v=\"off\">⛔ 关闭</button>\n    </div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"lockedAppsSheet\">🧱 白名单 ${(cfg('lockedApps') || []).length}</button>\n      <button class=\"btn sm grow\" data-act=\"wlSheetOpen\">🎟 通行证 ${activeWlPasses().length}</button>\n    </div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"widgetPin\">🧩 桌面组件</button>\n    </div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>监督与惩罚</h3>\n    <span class=\"pill ${cfg('punishEnabled') ? 'bad' : 'ok'}\">${cfg('punishEnabled') ? '惩罚模式开启' : '仅记录不惩罚'}</span></div>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('punishEnabled') ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"punishEnabled\">开启惩罚模式</button>\n      <button class=\"chip ${cfg('punishTrigger').leave ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"leave\">中途离开触发</button>\n      <button class=\"chip ${cfg('punishTrigger').timeout ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"timeout\">超时未完成触发</button>\n      <button class=\"chip ${cfg('punishTrigger').untimed ? 'on' : ''}\" data-act=\"toggleTrigger\" data-k=\"untimed\">未计时开始触发</button>\n    </div>\n    <div class=\"tiny mt6\">转账 / 送礼类会先弹锁定页让你确认（可直接执行，也能用「完成一件事」或「再约一段专注」补救免掉）；超过 ${Number(cfg('punishAutoSec') != null ? cfg('punishAutoSec') : 300)} 秒没确认才自动扣款。可在「我的 → 监督与惩罚」改这个秒数。</div></div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>惩罚库</h3><button class=\"btn sm\" data-act=\"editPunishItem\">＋ 添加</button></div>\n    <div class=\"sub\">7 种惩罚类型（转账/答题/礼物/抄写/反思/做事/打卡），触发时抽一项执行；数量金额都能改。</div>\n    <div class=\"mt10\">${lib.map(p => `<div class=\"item\"><div class=\"ic\">${PUNISH_ICON[p.kind] || '⚙️'}</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(p.title)} <span class=\"tiny\">${esc(punKindLabel(p.kind))}</span></div>\n      <div class=\"tiny\">${punSummary(p)}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"togglePunishItem\" data-id=\"${esc(p.id)}\">${p.enabled ? '停用' : '启用'}</button>\n      <button class=\"btn sm ghost\" data-act=\"editPunishItem\" data-id=\"${esc(p.id)}\">改</button></div>`).join('')}</div></div>\n  <div class=\"card\">\n    <div class=\"row between\"><h3>自定义惩罚文案</h3><button class=\"btn sm\" data-act=\"addPunishText\">＋ 添加</button></div>\n    <div class=\"sub\">角色宣布惩罚时优先让 AI 生成，失败时用这些台词兜底。</div>\n    ${texts.map((t, i) => `<div class=\"item\"><div class=\"ic\">💬</div><div class=\"grow\" style=\"font-size:12.8px\">${esc(t)}</div>\n      <button class=\"btn sm ghost\" data-act=\"delPunishText\" data-i=\"${i}\">删</button></div>`).join('')}</div>\n  <details class=\"card\"><summary><span>⚙️ 考核 · 奖励 · 通知参数</span></summary>\n  <div class=\"sec\">考核参数</div>\n  <div class=\"card\"><h3>考核参数（数字都可自己填）</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">校验出题数量（题）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.reviewQuestions\" value=\"${Number(cfg('reviewQuestions') || 3)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">达标正确率（%）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.passRatio\" value=\"${Number(cfg('passRatio') || 80)}\"></div>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">离开宽限（秒）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.graceSec\" value=\"${Number(cfg('graceSec') || 8)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">角色消息间隔（分钟）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.msgGapMin\" value=\"${Number(cfg('msgGapMin') || 8)}\"></div>\n    </div>\n    <label class=\"fl\">题目来源</label>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('reviewSource') !== 'local' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"reviewSource\" data-v=\"ai\">AI 出题（答案一起写进题库）</button>\n      <button class=\"chip ${cfg('reviewSource') === 'local' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"reviewSource\" data-v=\"local\">只用题库已有的题</button>\n    </div>\n    <div class=\"tiny\">题库现有 ${allBank().length} 道。AI 出题会把题干、标准答案、解析一起写进题库，所以判分是本地瞬时的。</div>\n    <label class=\"fl\">希望考察的知识点（可选）</label>\n    <input class=\"input\" data-in=\"setting.quizFocus\" value=\"${esc(cfg('quizFocus') || '')}\" placeholder=\"例如：资料分析里的增长率与比重 / 英语的时态一致性\">\n    <div class=\"chips mt6\">\n      <button class=\"chip ${(cfg('quizFocusMode') || 'focus') === 'focus' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizFocusMode\" data-v=\"focus\">🎯 优先考这个范围</button>\n      <button class=\"chip ${cfg('quizFocusMode') === 'mix' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizFocusMode\" data-v=\"mix\">🧩 和总结混合出题</button>\n    </div>\n    <div class=\"tiny mt6\">留空=按学习总结出题；填了=重点考察这个方向（受出题配比约束）。</div>\n    <label class=\"fl\">惩罚练习题来源</label>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('quizSource') !== 'local' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizSource\" data-v=\"ai\">AI 出题（存进题库）</button>\n      <button class=\"chip ${cfg('quizSource') === 'local' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"quizSource\" data-v=\"local\">只用题库已有的题</button>\n    </div>\n    <button class=\"btn sm block mt10\" data-act=\"quizMixOpen\">⚙️ 出题配比 · 来源占比 / 题型占比 / 掌握度</button>\n    <div class=\"tiny mt6\">当前来源配比：${esc(mixText(Object.assign({ fresh: 1, wrong: 1, bank: 1 }, cfg('quizMixSrc') || {})))}　题型：${esc(mixText(Object.assign({ choice: 1, fill: 1, multi: 1, tf: 1 }, cfg('quizMixKind') || {})))}</div>\n    <button class=\"btn sm block mt10\" data-act=\"gotoView\" data-view=\"qbank\">管理题库（${S.qbank.length}）</button></div>\n  <div class=\"card\"><h3>睡眠与奖励参数</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">作息达标时长（小时）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.sleepValidHours\" value=\"${Number(cfg('sleepValidHours') || 4)}\"></div>\n      <div class=\"grow\"><label class=\"fl\">壁纸解锁题量</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.albumQuizCount\" value=\"${Number(cfg('albumQuizCount') || 3)}\"></div>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">下一个连续作息奖励（天）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.streakNextMile\" value=\"${nextMile(sleepStreak())}\"></div>\n    </div>\n    <button class=\"btn block sm mt6\" data-act=\"setStreakMiles\">把「下一个奖励天数」写入里程碑</button>\n    <div class=\"tiny mt6\">当前里程碑：${streakMiles().join(' / ')} 天 · 已连续 ${sleepStreak()} 天</div></div>\n  <div class=\"card\"><h3>通知与同步</h3>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('notif') ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"notif\">角色后台提醒通知</button>\n      <button class=\"chip ${cfg('syncChat') ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"syncChat\">角色消息同步到聊天室（默认关）</button>\n    </div>\n    <label class=\"fl\">角色提醒的语音形式</label>\n    <div class=\"chips\">${VOICE_MODES.map(([k, n]) => `<button class=\"chip ${(cfg('voiceMode') || 'cue') === k ? 'on' : ''}\" data-act=\"setVoiceMode\" data-v=\"${k}\">${n}</button>`).join('')}</div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">语音循环时两句之间停多久（毫秒）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.voiceGapMs\" data-num=\"1\" value=\"${voiceGap()}\"></div>\n    </div>\n    <div class=\"tiny mt6\">复听/循环的句间停顿，默认 700 毫秒（可填 200~5000）。</div>\n    <button class=\"btn block sm mt10\" data-act=\"checkNotifPerm\">通知说明</button>\n    <div class=\"tiny mt6\">提醒会落系统通知栏（APK）；后台冻结时延迟，重开补跑。</div></div>\n  </details>\n  <div class=\"sec\">壁纸</div>\n  <div class=\"card\"><h3>🖼 壁纸</h3>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">两件事分开管：<b>你的壁纸</b>（上传后铺满全局，优先于 AI 生成的）和 <b>要不要让 AI 生成壁纸</b>。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"wallPickCustom\">⬆️ 上传我的壁纸</button>\n      ${cfg('customWallUse') ? `<button class=\"btn sm ghost\" data-act=\"wallClearCustom\">撤掉</button>` : ''}\n    </div>\n    <div class=\"tiny mt6\">${customWallUrl() ? '✅ 正在用你上传的壁纸（专注中/睡眠中的那张专属壁纸仍优先显示）。' : (cfg('customWallRef') ? '存过一张自定义壁纸，点「上传我的壁纸」可以换一张，或先点上面的按钮重新启用。' : '还没上传过。上传后它会铺满整个 APP 的背景。')}</div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${wallMode() === 'none' ? 'on' : ''}\" data-act=\"wallMode\" data-v=\"none\">🚫 全部不生成</button>\n      <button class=\"chip ${wallMode() === 'ai' ? 'on' : ''}\" data-act=\"wallMode\" data-v=\"ai\">🤖 只用 AI 生成</button>\n      <button class=\"chip ${wallMode() === 'custom' ? 'on' : ''}\" data-act=\"wallMode\" data-v=\"custom\">🖼 只用我的壁纸</button>\n      <button class=\"chip ${wallMode() === 'both' ? 'on' : ''}\" data-act=\"wallMode\" data-v=\"both\">✨ AI + 我的壁纸</button>\n      <button class=\"chip ${cfg('wallVary') !== false ? 'on' : ''}\" data-act=\"wallToggleVary\">画面每次有变化</button>\n    </div>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">· <b>关掉生成</b>后：专注、睡眠、奖励都不再调生图 —— 不再消耗额度，也不会再被重复的图刷屏；已经生成的壁纸都还在壁纸库里。<br>\n    · <b>画面每次有变化</b>打开时，每次生成会随机换机位 / 光线 / 构图 / 氛围，同一个样式不会每次都长一样。<br>\n    · 嫌图重复得厉害，最干脆的办法就是：上传一张自己的图 + 关掉生成。</div>\n  </div>\n  <details class=\"card\"><summary><span>💾 数据与备份</span></summary>\n  <div class=\"card\" style=\"border:0;background:transparent;padding:2px 0 0\"><h3 style=\"display:none\">数据</h3>\n    <div class=\"row\" style=\"gap:8px\">      <button class=\"btn sm ghost\" data-act=\"clearAlbum\">清空壁纸库</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"exportData\">导出备份</button>\n      <button class=\"btn sm grow\" data-act=\"importData\">导入备份</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"genlog\">🧾 生成记录（${(S.gen || []).length}）</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"fav\">⭐ 收藏夹（${(S.fav || []).filter(x => x.kind !== 'folder').length}）</button>\n    </div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"todos\">📝 待办清单（${(S.todos || []).filter(t => !t.done).length}）</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"invites\">💌 TA 的邀请（${(S.invites || []).filter(i => i.status === 'new').length}）</button>\n    </div>\n    <button class=\"btn block sm ghost mt10\" data-act=\"clearAll\" style=\"color:#ff9aa6\">清空本 APP 全部数据</button>\n    <div class=\"tiny mt6\">数据在本机（IndexedDB）；清浏览器数据/换设备前先导出。备份含收藏夹（含层级）、生成记录、故事、待办与邀请；含媒体时连原始文件一起打包。</div></details>\n  <details class=\"card\"><summary><span>🧰 进阶功能（提示词 · 心愿 · 币 · 目标 · 报告等）</span></summary>\n  <div class=\"card\"><div class=\"row between\"><h3>❓ 答疑助手</h3>\n    <button class=\"btn sm primary\" data-act=\"gotoView\" data-view=\"qa\">去提问</button></div>\n    <div class=\"tiny mt6\">${cfg('qaMode') === 'companion' ? '当前：由陪伴角色以人设回答' : '当前：普通 AI（不扮演角色，纯讲题）'} · 已留档 ${(S.qa || []).length} 条问答</div>\n    <div class=\"sub\">所有提问与解答都会完整留存（独立窗口，随时回看、收藏、发到聊天室）；模式可以随时切换，两条答疑提示词也都能改。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>提示词与台词</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"prompts\">去修改</button></div>\n    <div class=\"tiny mt6\">共 ${PROMPT_DEFS.length} 条可改</div>\n    <div class=\"sub\">APP 每次让角色生成内容用的指令都在这里：开场鼓励、催促进度、角色自己的任务、TA 应你的邀请、出题与解析格式、私密答疑、惩罚台词、奖励申请、睡眠报告、叫醒台词、睡前故事、几种壁纸的生图提示词。逐条可改、可还原。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>⭐ 星星瓶</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"bottle\">去看看</button></div>\n    <div class=\"tiny mt6\">已收集 ${noteAll().length} 张纸条 · 那些坚持不下去的瞬间，他都留了一句话给你。专注时撑不住就写一张递给他。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>💞 TA 的心愿</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"bond\">去查看</button></div>\n    <div class=\"tiny mt6\">${esc(wishBrief(anyCharId()))}</div>\n    <div class=\"tiny mt6\">TA 心底有一件一直想要的事，只有你陪他一起攒够专注时间才会实现。只有通过考核的专注能推进它；你没做到，他那边也跟着退（连坐）。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>🪙 专注币</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"coin\">去兑换</button></div>\n    <div class=\"tiny mt6\">当前 ${coinBal()} 点（今日 +${coinToday()}）· 专注 1 分钟 = ${coinRate()} 点${coinBonus() ? '，通过考核再 +' + coinBonus() + '%' : ''} · 免罚卡 ${Number(cfg('freePass')) || 0} 张</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>🎯 目标与倒计时</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"goals\">去设置</button></div>\n    <div class=\"tiny mt6\">${esc(goalBrief())}</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>📈 学习报告 / 专注趋势</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"periodrep\">看报告</button></div>\n    <div class=\"tiny mt6\">周报 / 月报由角色按真实数据写；趋势看你在一天里什么时候真的学得进去。</div>\n    <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"trend\">📊 专注趋势</button>\n      <button class=\"btn sm grow\" data-act=\"gotoView\" data-view=\"periodrep\">📈 学习报告（${(cfg('periodReports') || []).length}）</button></div></div>\n  </details>\n  <div class=\"card\"><div class=\"row between\"><h3>🌅 晨间闭环</h3>\n    <button class=\"btn sm\" data-act=\"morningToggle\">${morningCfg().enabled ? '已开启 · 点此关掉' : '未开启 · 点此开启'}</button></div>\n    <div class=\"tiny mt6\">每天早上到点：TA 叫你起床 → 顺口说一句昨晚睡得怎么样 → 提醒今天的安排和目标还剩几天，还能一键带着「今天第一件事」开始专注。</div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">时间</label><input class=\"input\" type=\"time\" id=\"mTime\" value=\"${esc(morningCfg().time)}\"></div></div>\n    <label class=\"fl\">谁来叫醒</label>\n    <div class=\"chips\">${S.chars.length ? S.chars.map(c => `<button class=\"chip ${(morningCfg().charId || anyCharId()) === c.id ? 'on' : ''}\" data-act=\"morningChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('') : `<div class=\"tiny\">还没有角色</div>`}</div>\n    <div class=\"chips mt8\"><button class=\"chip ${morningCfg().voice ? 'on' : ''}\" data-act=\"morningVoice\">用语音读出来</button></div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"morningSave\">保存晨间问候</button>\n      <button class=\"btn sm ghost grow\" data-act=\"morningTry\">立刻试一次</button></div>\n    <div class=\"tiny mt6\">会同时在系统时钟立闹钟（APK 被杀也响；改时间需自行删旧闹钟）。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>🗓 预约专注</h3>\n    <button class=\"btn sm\" data-act=\"gotoView\" data-view=\"appt\">去设置</button></div>\n    <div class=\"sub\">跟 TA 约好时间一起专注：选好日期、时长、专注事项，TA 提前来催你准备开始；连着催 ${apptMaxNudge()} 次你还没点开始，就直接按惩罚库开罚。</div>\n    <div class=\"tiny mt6\">当前：提前 ${apptAdvance()} 分钟开始催 · 每 ${apptGap()} 分钟一次 · 共 ${apptMaxNudge()} 次 · 第 ${apptMaxNudge()} 次后 ${apptGrace()} 分钟仍没开始就开罚${(S.appts || []).filter(a => a.status === 'pending').length ? ' · 待开始 ' + (S.appts || []).filter(a => a.status === 'pending').length + ' 个' : ''}</div></div>\n  <details class=\"card\"><summary><span>📨 聊天室 · 角色工具 · 权限自检</span></summary>\n  <div class=\"card\" style=\"border:0;background:transparent;padding:2px 0 0\"><div class=\"row between\"><h3>📨 聊天室入口（+ 号面板）</h3>\n    <button class=\"btn sm\" data-act=\"openInvite\" data-k=\"focus\">试一次</button></div>\n    <div class=\"tiny mt6\">在聊天室点输入框旁的 <b>+ 号</b>，能看到两个本 APP 的入口：<b>「专注邀约」</b>和<b>「睡眠陪伴」</b>。点进去会直接打开本 APP 的对应页面，并自动带上当前对话的角色。<br>\n    · <b>专注邀约</b>：可以现在就开始一起专注，也可以预订一个时间段 —— 到点前 TA 会来催你，连着催 ${apptMaxNudge()} 次没开始就开罚。<br>\n    · <b>睡眠陪伴</b>：邀请 TA 陪你一起睡，TA 应你一声后直接开始记录。</div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>🧰 角色主动帮你的方式</h3>\n    </div>\n    <div class=\"tiny mt6\">TA 能在普通聊天里直接查专注、记待办、约专注、邀你睡（细则见帮助中心）。</div>\n    <div class=\"chips mt8\">\n      <button class=\"chip\" data-act=\"gotoView\" data-view=\"todos\">📝 待办 ${(S.todos || []).length}</button>\n      <button class=\"chip\" data-act=\"gotoView\" data-view=\"invites\">💌 TA 的邀请 ${(S.invites || []).length}</button>\n          </div></div>\n  <div class=\"card\"><div class=\"row between\"><h3>🔎 权限自检</h3>\n    <button class=\"btn sm\" data-act=\"permCheck\">检查</button></div>\n    <div class=\"tiny mt6\">看看这个包到底拿到了哪些权限、注册了哪些工具与入口 —— 不确定某个功能为什么不通时，先点它。</div></div>\n  </details>\n  <div class=\"card\"><h3>关于</h3>\n    <div class=\"tiny\">角色陪伴专注 v1.10.0（内置版）· 作者 doris —— 历史更新记录见「📖 帮助与说明」。</div>\n    <button class=\"btn block sm mt10\" data-act=\"gotoView\" data-view=\"help\">📖 帮助与说明</button></div>`;\n};\n/* ==========================================================\n   视图 · 学习助手（独立窗口：答疑 + 全部记录留档）\n   ========================================================== */\nfunction qaMode() { return cfg('qaMode') === 'char' ? 'char' : 'plain'; }\nfunction qaAsk() { return String(S.draft.qaQ || ''); }\nasync function askQA() {\n  const q = qaAsk().trim();\n  if (!q) { toast('先写下你要问的问题'); return; }\n  if (S.draft.qaBusy) { toast('正在回答上一条，稍等一下'); return; }\n  const mode = qaMode();\n  const cid = mode === 'char' ? pickOneChar(null) : '';\n  if (mode === 'char' && !cid) { toast('还没有角色，先用普通学习助手吧'); return; }\n  S.draft.qaBusy = true; render();\n  const hist = (S.qlogs || []).slice(0, 4).reverse()\n    .map(x => '问：' + String(x.q).slice(0, 80) + '\\n答：' + String(x.a || '').replace(/\\n/g, ' ').slice(0, 120)).join('\\n');\n  let text = '';\n  try {\n    if (mode === 'char') text = await pGen('qa.answer', { question: q }, [cid]);\n    else text = await pGen('qa.assistant', { question: q, history: hist || '（这是第一条问题）' }, [], undefined, true);\n  } catch (e) { text = ''; }\n  S.draft.qaBusy = false;\n  if (!text) { toast('回答失败了：检查 API 配置，或稍后再问一次'); render(); return; }\n  text = String(text).trim();\n  const rec = { q: q.slice(0, 500), a: text, at: Date.now(), date: dkey(), mode: mode, charId: cid || '' };\n  const r = await DB.create(T.QA, rec);\n  if (r) rec.id = r.id;\n  S.qlogs = [rec].concat(S.qlogs || []);\n  if (mode === 'char' && cid) {\n    await syncTimeline(cid, `用户在学习助手里问了一个问题：${q.slice(0, 60)}｜你答：${text.slice(0, 80)}`, 'qa', {});\n  }\n  S.draft.qaQ = '';\n  S.draft.qaOpen = rec.id;\n  render();\n  window.scrollTo(0, 0);\n  toast('已记进学习助手记录');\n}\nVIEWS.qa = function () {\n  const all = S.qlogs || [];\n  const kw = String(S.draft.qaKb || '').trim().toLowerCase();\n  const list = kw ? all.filter(x => (String(x.q) + ' ' + String(x.a)).toLowerCase().indexOf(kw) >= 0) : all;\n  const mode = qaMode();\n  const open = S.draft.qaOpen ? (all.find(x => String(x.id) === String(S.draft.qaOpen)) || null) : null;\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03));border-color:rgba(94,234,212,.3)\">\n    <h3>❓ 学习助手</h3>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">独立窗口的答疑：问什么都可以，答完自动留档。<br>\n    默认用 <b>普通学习助手</b>：不扮演任何角色、不寒暄、不调情，只把问题讲清楚 —— 结论、步骤、例子都会给全。</div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${mode === 'plain' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"qaMode\" data-v=\"plain\">🧭 普通学习助手（推荐）</button>\n      <button class=\"chip ${mode === 'char' ? 'on' : ''}\" data-act=\"setSetting\" data-k=\"qaMode\" data-v=\"char\">🎭 由陪伴角色回答</button>\n    </div>\n    <div class=\"tiny mt6\">${mode === 'char' ? '当前由角色按人设回答（会带情绪和口吻），记录同样留档。' : '当前是纯功能答疑，不受角色人设影响 —— 想换回角色口吻就点上面那个按钮。'}</div>\n  </div>\n  <div class=\"card\">\n    <h3>${open ? '继续问' : '问一个问题'}</h3>\n    <textarea id=\"qaInput\" data-in=\"qaQ\" style=\"min-height:100px\" placeholder=\"例如：资料分析里「同比」和「环比」到底怎么区分？举个题算一下。\">${esc(S.draft.qaQ || '')}</textarea>\n    <div class=\"tiny mt6\">当前 <b data-count-for=\"qaQ\">${String(S.draft.qaQ || '').length}</b> 字</div>\n    <button class=\"btn primary block mt10\" data-act=\"qaSend\" ${S.draft.qaBusy ? 'disabled' : ''}>${S.draft.qaBusy ? '正在回答…' : (mode === 'char' ? '🎭 问 ' + esc(charName(pickOneChar(null))) : '🧭 问学习助手')}</button>\n    <div class=\"tiny mt6\">每次提问都会走一次你自己的 API；回答与提问都会留在下面的记录里。</div>\n  </div>\n  ${open ? `<div class=\"card\" style=\"border-color:rgba(94,234,212,.45)\">\n    <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(open.at))} ${hm(open.at)} · ${open.mode === 'char' ? '角色回答' : '学习助手'}</span>\n      <button class=\"btn sm ghost\" data-act=\"qaClose\">收起</button></div>\n    <div style=\"font-size:13.6px;font-weight:600;margin-top:6px;line-height:1.6\">${esc(open.q)}</div>\n    <div class=\"hr\"></div>\n    <div style=\"font-size:13.5px;line-height:1.85;white-space:pre-wrap\">${esc(open.a)}</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"qaCopy\" data-id=\"${esc(open.id)}\">复制回答</button>\n      <button class=\"btn sm ghost grow\" data-act=\"qaFav\" data-id=\"${esc(open.id)}\">⭐ 收藏</button>\n      <button class=\"btn sm ghost grow\" data-act=\"qaDel\" data-id=\"${esc(open.id)}\">删除</button></div></div>` : ''}\n  <div class=\"card\">\n    <div class=\"row between\"><h3>全部记录（${all.length}）</h3>\n      <button class=\"btn sm ghost\" data-act=\"qaClear\" ${all.length ? '' : 'disabled'}>清空</button></div>\n    <input class=\"input mt6\" data-in=\"qaKb\" value=\"${esc(S.draft.qaKb || '')}\" placeholder=\"搜问题或答案的关键词…\">\n    ${list.length ? list.slice(0, 60).map(x => `<div class=\"item\" data-act=\"qaOpenItem\" data-id=\"${esc(x.id)}\" style=\"cursor:pointer\">\n      <div class=\"ic\">${x.mode === 'char' ? '🎭' : '🧭'}</div>\n      <div class=\"grow\"><div style=\"font-size:13px;line-height:1.55\">${esc(String(x.q).slice(0, 70))}</div>\n        <div class=\"tiny ellip\">${esc(String(x.a || '').replace(/\\n/g, ' ').slice(0, 60))}</div>\n        <div class=\"tiny\">${dkey(new Date(x.at))} ${hm(x.at)}${x.charId ? ' · ' + esc(charName(x.charId)) : ''}</div></div>\n      <div class=\"ic\">›</div></div>`).join('')\n      : `<div class=\"empty\">${kw ? '没有匹配的记录' : '还没有提问记录。<br>上面问一个问题，问答会全部留在这里。'}</div>`}\n  </div>`;\n};\nObject.assign(ACTIONS, {\n  qaSend: () => { askQA(); },\n  qaClose: () => { S.draft.qaOpen = ''; render(); },\n  qaOpenItem: el => { S.draft.qaOpen = el.dataset.id; render(); window.scrollTo(0, 0); },\n  qaCopy: el => {\n    const x = (S.qlogs || []).find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    try {\n      const ta = document.createElement('textarea');\n      ta.value = '问：' + x.q + '\\n\\n答：' + x.a;\n      document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove();\n      toast('已复制');\n    } catch (e) { toast('复制失败，请长按选择文本'); }\n  },\n  qaFav: el => {\n    const x = (S.qlogs || []).find(y => String(y.id) === String(el.dataset.id));\n    if (!x) return;\n    openFavPicker({ kind: 'text', title: '学习助手 · ' + String(x.q).slice(0, 20), content: '问：' + x.q + '\\n\\n答：' + x.a, charId: x.charId || '', from: '学习助手' });\n  },\n  qaDel: async el => {\n    await DB.remove(T.QA, el.dataset.id);\n    S.qlogs = (S.qlogs || []).filter(y => String(y.id) !== String(el.dataset.id));\n    if (String(S.draft.qaOpen) === String(el.dataset.id)) S.draft.qaOpen = '';\n    toast('已删除'); render();\n  },\n  qaClear: async () => {\n    const ok = await confirmBox('清空答疑记录？', '所有问答都会删掉，不可恢复（生成记录里还留有当时的提示词与返回）。', '清空');\n    if (!ok) return;\n    for (const x of (S.qlogs || [])) if (x.id) await DB.remove(T.QA, x.id);\n    S.qlogs = []; S.draft.qaOpen = ''; toast('已清空'); render();\n  }\n});\n/* ==========================================================\n   视图 · 专注校验记录（每条专注的校验都能单独点开看）\n   ========================================================== */\nfunction reviewedList() {\n  return (S.sessions || []).filter(s => s && (s.reviewQs || s.reviewAt || s.status === 'review' || s.status === 'passed' || s.status === 'failed'))\n    .sort((a, b) => (b.reviewAt || b.startAt || 0) - (a.reviewAt || a.startAt || 0));\n}\nfunction checkStateOf(s) {\n  if (s.status === 'passed') return ['通过', 'ok'];\n  if (s.status === 'failed') return ['失败', 'bad'];\n  if (s.status === 'review') return ['待校验', 'warn'];\n  return ['进行中', 'run'];\n}\nVIEWS.checks = function () {\n  const all = reviewedList();\n  const f = S.draft.checkFilter || 'all';\n  const list = f === 'all' ? all : all.filter(s => (f === 'failed' ? s.status === 'failed' : f === 'passed' ? s.status === 'passed' : (s.status === 'review' || s.status === 'running')));\n  const n = k => (k === 'all' ? all.length : all.filter(s => (k === 'failed' ? s.status === 'failed' : k === 'passed' ? s.status === 'passed' : (s.status === 'review' || s.status === 'running'))).length);\n  return `\n  <div class=\"card hero-soft\"><h3>✅ 专注校验记录</h3>\n    <div class=\"tiny mt6\">每一段专注（每一轮）的校验都单独留档 —— 点开任意一条能看到：当时做的是哪个任务、每道题的题干与你的答案、正确的答案与解析、以及这次被归纳出的薄弱知识点。</div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${f === 'all' ? 'on' : ''}\" data-act=\"checkFilter\" data-v=\"all\">全部 ${n('all')}</button>\n      <button class=\"chip ${f === 'passed' ? 'on' : ''}\" data-act=\"checkFilter\" data-v=\"passed\">✅ 通过 ${n('passed')}</button>\n      <button class=\"chip ${f === 'failed' ? 'on' : ''}\" data-act=\"checkFilter\" data-v=\"failed\">⚠️ 失败 ${n('failed')}</button>\n      <button class=\"chip ${f === 'pending' ? 'on' : ''}\" data-act=\"checkFilter\" data-v=\"pending\">⏳ 待校验 ${n('pending')}</button>\n    </div></div>\n  ${list.length ? list.slice(0, 60).map(s => {\n    const st = checkStateOf(s);\n    const wrongN = (s.reviewQs || []).filter(q => !q.ok).length;\n    return `<div class=\"card tight\" data-act=\"checkOpen\" data-id=\"${esc(s.id || s.dbId)}\" style=\"cursor:pointer\">\n      <div class=\"row between\"><span class=\"tiny\">${esc(s.date || '')} ${s.startAt ? hm(s.startAt) : ''} · 第 ${s.reviewRound || s.cycle || 1}/${s.cycles || 1} 轮</span>\n        <span class=\"pill ${st[1]}\">${st[0]}</span></div>\n      <div style=\"font-size:13.5px;margin-top:5px\">${esc(s.taskName || ((s.plan || []).map(t => t.content).join('、') || '（未记录任务）'))}</div>\n      <div class=\"tiny mt6\">${s.reviewQs ? '答对 ' + (s.quizScore || 0) + '/' + (s.quizTotal || 0) + '（' + (s.quizTotal ? Math.round((s.quizScore || 0) / s.quizTotal * 100) : 0) + '%）' : (s.status === 'review' ? '还没提交校验' : '这条没有留下答题明细')}\n        ${wrongN ? ' · 错 ' + wrongN + ' 题' : ''}${(s.weakGroups || []).length ? ' · 薄弱点 ' + s.weakGroups.length + ' 条' : ''}</div>\n      <div class=\"row between mt6\"><span class=\"tiny\">${Math.round((s.totalFocusSec || 0) / 60)} 分钟${s.skippedReview ? ' · 跳过校验' : ''}</span>\n        <span class=\"tiny\">点开看详细 ›</span></div></div>`;\n  }).join('')\n      : `<div class=\"empty\">这里还没有记录。<br>完成一段专注并走完校验后，这一条就会留在这里，随时点开回看。</div>`}`;\n};\nObject.assign(ACTIONS, {\n  checkFilter: el => { S.draft.checkFilter = el.dataset.v; render(); },\n  openChecks: el => {\n    S.draft.checkFilter = (el && el.dataset && el.dataset.f) || 'all';\n    go('checks');\n  },\n  checkOpen: el => {\n    const id = el.dataset.id;\n    const s = (S.sessions || []).find(x => String(x.id || x.dbId) === String(id));\n    if (!s) { toast('找不到这条记录'); return; }\n    const st = checkStateOf(s);\n    const qs = s.reviewQs || [];\n    openSheet(`<h3>${esc(s.taskName || '专注校验')}</h3>\n      <div class=\"tiny\">${esc(s.date || '')} ${s.startAt ? hm(s.startAt) : ''} · 第 ${s.reviewRound || s.cycle || 1}/${s.cycles || 1} 轮 · 专注 ${Math.round((s.totalFocusSec || 0) / 60)} 分钟 · <b>${st[0]}</b>${s.skippedReview ? '（跳过校验）' : ''}</div>\n      ${qs.length ? `<div class=\"kv\"><span class=\"k\">答对</span><span>${s.quizScore || 0}/${s.quizTotal || 0}</span></div>` : ''}\n      ${s.feedback ? `<div class=\"kv\"><span class=\"k\">当时的状态</span><span>${esc(s.feedback)}</span></div>` : ''}\n      ${s.summary ? `<div class=\"kv\"><span class=\"k\">学习总结</span><span>${esc(s.summary)}</span></div>` : ''}\n      ${(s.plan || []).length ? `<div class=\"kv\"><span class=\"k\">任务完成</span><span>${(s.plan || []).filter(t => t.done).length}/${(s.plan || []).length} 项</span></div>` : ''}\n      ${s.reviewAt ? `<div class=\"tiny mt6\">校验时间：${dkey(new Date(s.reviewAt))} ${hm(s.reviewAt)}</div>` : ''}\n      ${(s.weakGroups || []).length ? `<div class=\"card mt10\" style=\"background:var(--card2)\">\n        <div class=\"tiny\">这次归纳出的薄弱知识点</div>\n        ${(s.weakGroups || []).map(g => `<div style=\"margin-top:7px\">\n          <div style=\"font-size:13px\">🎯 ${esc(g.point)}${g.level ? ' <span class=\"tiny\">' + esc(g.level) + '</span>' : ''}</div>\n          ${g.why ? `<div class=\"tiny\">${esc(g.why)}</div>` : ''}\n          ${g.tip ? `<div class=\"tiny\" style=\"color:var(--teal)\">怎么补：${esc(g.tip)}</div>` : ''}</div>`).join('')}</div>` : ''}\n      ${qs.length ? `<div class=\"hr\"></div>\n        ${qs.map((q, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(q, i)} ${esc(q.q)}</div>\n          <div class=\"opt\" style=\"border-color:${q.ok ? 'rgba(94,234,212,.55)' : 'rgba(255,123,138,.5)'};background:${q.ok ? 'rgba(94,234,212,.1)' : 'var(--warn-soft)'}\">\n            <span>我的答案：${esc(q.my)} ${q.ok ? '✅' : '❌'}</span></div>\n          ${q.ok ? '' : (qIsPick(q)\n            ? `<div class=\"opt right\" style=\"margin-top:6px\"><span>正确答案：${esc(qAnswerText(q))}</span></div>`\n            : `<div class=\"opt right\" style=\"margin-top:6px\"><span>参考答案：${esc(qAnswerText(q))}</span></div>`)}\n          ${q.explain ? `<div class=\"exp\">${esc(q.explain)}</div>` : ''}</div>`).join('')}`\n        : `<div class=\"tiny mt8\">这条记录没有留下答题明细（旧版本生成的专注不保存题目）。</div>`}\n      ${s.advice ? `<div class=\"card mt10\" style=\"background:var(--card2)\"><div class=\"tiny\">当时的点拨</div><div style=\"font-size:13px;margin-top:5px\">${esc(s.advice)}</div></div>` : ''}\n      <button class=\"btn primary block mt12\" data-act=\"closeSheet\">关闭</button>`);\n  }\n});\n/* ==========================================================\n   视图 · 失约说明（原因分析 + 保证书）\n   ========================================================== */\nVIEWS.missed = function () {\n  const list = (S.appts || []).filter(a => a.needEssay && a.status === 'missed');\n  const a = S.draft.missedId ? (list.find(x => String(x.id) === String(S.draft.missedId)) || list[0]) : list[0];\n  if (!a) return `<div class=\"card\"><h3>没有待补写的失约说明</h3>\n    <div class=\"sub\">有约好的专注没开始、而且还没补写说明时，这里会出现表格。</div>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"home\">回首页</button></div>`;\n  const cid = (a.charIds || [])[0] || anyCharId();\n  const whyN = txtCount(S.draft.missWhy || ''), prN = txtCount(S.draft.missPromise || '');\n  const needWhy = 30, needPr = 50;\n  return `\n  <div class=\"card\" style=\"border-color:rgba(255,123,138,.5);background:linear-gradient(160deg,rgba(255,123,138,.14),rgba(255,255,255,.03))\">\n    <div class=\"row between\"><div class=\"grow\"><h3 style=\"color:#ff9aa6\">💔 你失约了</h3>\n      <div class=\"tiny mt6\">${esc(apptTimeText(a))} 约好一起专注 ${Number(a.minutes) || 0} 分钟：「${esc(a.task || '')}」<br>\n      催了 ${Number(a.nudgeCount) || apptMaxNudge()} 次，你一次都没有点开始。</div></div>\n      <div style=\"font-size:30px\">🕯</div></div>\n    <div class=\"row mt10\">${charAvatar(charById(cid))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.4px\">\n      <div class=\"who\">${esc(charName(cid))}</div>我等了你 ${Number(a.nudgeCount) || apptMaxNudge()} 次……你先跟我说清楚。</div></div>\n  </div>\n  <div class=\"card\"><h3>① 原因分析（至少 ${needWhy} 字）</h3>\n    <div class=\"tiny mt6\">写清当时到底发生了什么、为什么会错过，以及这件事跟你自己的关系。糊弄过去的话，TA 看得出来。</div>\n    <textarea data-in=\"missWhy\" placeholder=\"例如：七点半在打游戏，想着再一局就结束，结果拖到九点，也没跟你打招呼。问题是我根本没把约定当回事。\">${esc(S.draft.missWhy || '')}</textarea>\n    <div class=\"tiny mt6\">当前 <b data-count-for=\"missWhy\">${whyN}</b> / ${needWhy} 字</div></div>\n  <div class=\"card\"><h3>② 保证书（至少 ${needPr} 字）</h3>\n    <div class=\"tiny mt6\">写清楚下次怎么避免：具体到时间点、具体动作、做不到认什么罚。</div>\n    <textarea data-in=\"missPromise\" placeholder=\"例如：以后约好的时间提前 10 分钟就把游戏关掉、手机放远，到点立刻点开始；如果再一次没开始，我认双倍惩罚，这一周不再提任何奖励。\" style=\"min-height:130px\">${esc(S.draft.missPromise || '')}</textarea>\n    <div class=\"tiny mt6\">当前 <b data-count-for=\"missPromise\">${prN}</b> / ${needPr} 字</div></div>\n  <div class=\"card\"><h3>③ 补救：换取减轻这次惩罚</h3>\n    <div class=\"tiny\">除了写说明，你还可以用下面两种方式补救 —— 做到之后，这次失约的惩罚会立刻免掉（已经扣掉的不会退，但会记为「已补救」）。</div>\n    ${a.remedy && a.remedy.type === 'task' ? `<div class=\"card tight mt10\" style=\"border-color:rgba(94,234,212,.5);background:linear-gradient(160deg,rgba(94,234,212,.12),rgba(255,255,255,.03))\">\n      <div class=\"tiny\">你要完成的事</div>\n      <div style=\"font-size:14.5px;font-weight:600;margin-top:4px\">${esc(a.remedy.text)}</div>\n      ${a.remedy.doneAt ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">已完成 · ${dkey(new Date(a.remedy.doneAt))} ${hm(a.remedy.doneAt)}</div>`\n        : `<button class=\"btn teal block mt10\" data-act=\"missRemedyTaskDone\" data-id=\"${esc(a.id)}\">✅ 我做完了</button>\n           <button class=\"btn ghost block sm mt8\" data-act=\"missRemedyTaskAsk\" data-id=\"${esc(a.id)}\">换一件</button>`}</div>`\n      : `<button class=\"btn block\" data-act=\"missRemedyTaskAsk\" data-id=\"${esc(a.id)}\">✅ 用「完成一件事」补救</button>`}\n    ${a.remedy && a.remedy.type === 'quiz' ? `<div class=\"card tight mt10\" style=\"border-color:rgba(94,234,212,.5);background:linear-gradient(160deg,rgba(94,234,212,.12),rgba(255,255,255,.03))\">\n      <div class=\"tiny\">写题补救 · 已答对 ${a.remedy.right}/${a.remedy.total}（${Math.round((a.remedy.right || 0) / Math.max(1, a.remedy.total || 1) * 100)}%）${a.remedy.pass ? ' · 已达标' : ' · 未达标，还可以再答一次'}</div>\n      ${a.remedy.pass ? '' : `<button class=\"btn teal block mt8\" data-act=\"missQuizOpen\" data-id=\"${esc(a.id)}\">再答一次</button>`}</div>`\n      : `<button class=\"btn block mt8\" data-act=\"missQuizOpen\" data-id=\"${esc(a.id)}\">✍️ 用「写几道题」补救（答对 ${Number(cfg('passRatio') || 80)}% 即达标）</button>`}\n    <div class=\"tiny mt6\">题目从你的题库里抽；题库空的话先去「学习档案 → 题库」加几道，或把考核参数里的题目来源设为 AI 出题。</div></div>\n  <div class=\"card tight\"><div class=\"tiny\">惩罚按规则处理：转账 / 送礼类会先进锁定页让你确认（也可以直接用上面的补救免掉），超时未确认才自动扣款。提交后，这份说明和你的保证会一起写进 TA 的记忆，他会以角色身份回你一句。</div></div>\n  <button class=\"btn primary block\" style=\"min-height:50px\" data-act=\"missSubmit\" ${S.loading === 'miss' ? 'disabled' : ''}>${S.loading === 'miss' ? '正在交给 TA…' : '提交，交给 TA'}</button>\n  ${list.length > 1 ? `<div class=\"card mt10\"><h3>其他待补写的（${list.length - 1}）</h3>\n    ${list.filter(x => x !== a).map(x => `<div class=\"item\"><div class=\"ic\">💔</div>\n      <div class=\"grow\" data-act=\"missOpen\" data-id=\"${esc(x.id)}\" style=\"cursor:pointer\">\n        <div style=\"font-size:13px\">${esc(x.task || '')}</div>\n        <div class=\"tiny\">${esc(apptTimeText(x))} · 催了 ${Number(x.nudgeCount) || 0} 次</div></div>\n      <div class=\"ic\">›</div></div>`).join('')}</div>` : ''}\n  <button class=\"btn ghost block mt8\" data-act=\"gotoView\" data-view=\"home\">稍后再写</button>\n  <div class=\"tiny center mt10\">不写也能离开，但首页会一直挂着这件事，TA 也记着。</div>`;\n};\nObject.assign(ACTIONS, {\n  missOpen: el => { S.draft.missedId = el.dataset.id; render(); window.scrollTo(0, 0); },\n  missSubmit: async () => {\n    const list = (S.appts || []).filter(a => a.needEssay && a.status === 'missed');\n    const a = S.draft.missedId ? (list.find(x => String(x.id) === String(S.draft.missedId)) || list[0]) : list[0];\n    if (!a) { toast('没有待补写的失约'); return; }\n    const why = String(S.draft.missWhy || '').trim();\n    const promise = String(S.draft.missPromise || '').trim();\n    if (txtCount(why) < 30) { toast('原因分析太短了，至少 30 字'); return; }\n    if (txtCount(promise) < 50) { toast('保证书太短了，至少 50 字'); return; }\n    const cid = (a.charIds || [])[0] || anyCharId();\n    S.loading = 'miss'; render();\n    let line = '';\n    try {\n      line = await pGen('appt.missed', {\n        time: apptTimeText(a), task: a.task || '一起专注', minutes: Number(a.minutes) || 0,\n        nudges: Number(a.nudgeCount) || apptMaxNudge(), why: why, promise: promise\n      }, [cid]);\n    } catch (e) { line = ''; }\n    if (!line) line = '……行，我听到了。下次别再让我一个人等。';\n    line = String(line).replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 200);\n    S.loading = '';\n    a.needEssay = false; a.essayAt = Date.now(); a.essayWhy = why; a.essayPromise = promise; a.essayReply = line;\n    await updateAppt(a);\n    if (cid) {\n      await syncTimeline(cid, '用户为他失约的「' + (a.task || '') + '」（' + apptTimeText(a) + '）补写了说明。\\n原因分析：' + why + '\\n保证书：' + promise + '\\n你的回应：' + line, 'appt_essay', {});\n      await addPublic('missed', '失约说明 · ' + (a.task || '') + '：' + why.slice(0, 60), cid, {});\n      await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n    }\n    S.draft.missWhy = ''; S.draft.missPromise = ''; S.draft.missedId = '';\n    toast(cid ? charName(cid) + '：' + line : '已提交');\n    go('home');\n  },\n  /* ---- 失约补救 ①：完成一件事 ---- */\n  missRemedyTaskAsk: el => {\n    const a = missApptOf(el);\n    if (!a) { toast('找不到这次的预约记录'); return; }\n    const w = openSheet(`<h3>✅ 用完成一件事来补救</h3>\n      <div class=\"tiny\">选一件真的要做完的事。做完回来点「我做完了」，这次失约的惩罚立刻免掉。</div>\n      <div class=\"chips mt10\">${PUNISH_REMEDY_TASKS.map(t => `<button class=\"chip\" data-mrt=\"${esc(t)}\">${esc(t)}</button>`).join('')}</div>\n      <label class=\"fl\">或者自己写一件</label>\n      <input class=\"input\" id=\"missRemedyText\" value=\"${esc((a.remedy && a.remedy.type === 'task' && a.remedy.text) || '')}\" placeholder=\"例如：把这次错题按题型整理成 3 组，每组写一句规律\">\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">算了</button>\n        <button class=\"btn primary grow\" data-act=\"missRemedyTaskSave\" data-id=\"${esc(a.id)}\">就这件，开始做</button></div>`);\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-mrt]'); if (!b) return;\n      const i = document.getElementById('missRemedyText'); if (i) i.value = b.dataset.mrt;\n      w.querySelectorAll('[data-mrt]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  missRemedyTaskSave: async el => {\n    const a = missApptOf(el);\n    if (!a) return;\n    const v = ((document.getElementById('missRemedyText') || {}).value || '').trim();\n    if (!v) { toast('先选一件或写一件要做的事'); return; }\n    a.remedy = { type: 'task', text: v.slice(0, 90), at: Date.now() };\n    await updateAppt(a);\n    closeAllSheets();\n    S.draft.missedId = a.id;\n    toast('已记下，做完点「我做完了」');\n    render();\n  },\n  missRemedyTaskDone: async el => {\n    const a = missApptOf(el);\n    if (!a || !a.remedy || !a.remedy.text) { toast('先选一件要做的事'); return; }\n    const ok = await confirmBox('确认做完了？', '「' + a.remedy.text + '」\\n\\n确认后这次失约的惩罚免掉。没做完就别点。', '做完了，免掉惩罚');\n    if (!ok) return;\n    await missRemedyFinish(a, '完成任务：' + a.remedy.text);\n  },\n  /* ---- 失约补救 ②：写题 ---- */\n  missQuizOpen: el => {\n    const a = missApptOf(el);\n    if (!a) { toast('找不到这次的预约记录'); return; }\n    const count = clamp(Number(cfg('reviewQuestions') || 3) + 2, 3, 8);\n    const qs = drawFromBank(count);\n    if (!qs.length) { toast('题库是空的：先去「学习档案 → 题库」加几道题'); return; }\n    S.draft.missQuiz = { apptId: a.id, qs: qs, answers: {} };\n    missQuizRender();\n  },\n  missQuizSubmit: async () => {\n    const Q = S.draft.missQuiz;\n    if (!Q) return;\n    Q.qs.forEach((q, i) => {\n      if (q.type !== 'fill') return;\n      const el = document.getElementById('mqFill' + i);\n      if (el) Q.answers[i] = el.value;\n    });\n    const miss = quizMissing(Q.qs, Q.answers);\n    if (miss.length) { toast('还有 ' + miss.length + ' 题没作答'); return; }\n    gradeQuiz(Q);\n    await bumpMasteryAll(Q.qs);\n    for (let i = 0; i < Q.qs.length; i++) { if (!Q.qs[i].ok) await recordMistake(Q.qs[i], Q.answers[i], '失约补救'); }\n    const pass = Q.rate >= Number(cfg('passRatio') || 80);\n    const a = (S.appts || []).find(x => String(x.id) === String(Q.apptId));\n    if (!a) { closeAllSheets(); S.draft.missQuiz = null; toast('预约记录不见了'); return; }\n    a.remedy = { type: 'quiz', right: Q.right, total: Q.total, pass: pass, at: Date.now() };\n    await updateAppt(a);\n    closeAllSheets();\n    S.draft.missedId = a.id; S.draft.missQuiz = null;\n    if (pass) await missRemedyFinish(a, '写题补救：答对 ' + Q.right + '/' + Q.total);\n    else { toast('答对 ' + Q.right + '/' + Q.total + '，没达标 —— 还能再答一次'); render(); }\n  }\n});\n/* ---------- 失约相关的公共小工具 ---------- */\nfunction missedApptList() { return (S.appts || []).filter(a => a.needEssay && a.status === 'missed'); }\nfunction missApptOf(el) {\n  const id = el && el.dataset && el.dataset.id;\n  const list = missedApptList();\n  if (id) return list.find(x => String(x.id) === String(id)) || (S.appts || []).find(x => String(x.id) === String(id)) || null;\n  return S.draft.missedId ? (list.find(x => String(x.id) === String(S.draft.missedId)) || list[0]) : list[0] || null;\n}\nfunction missLinkedPunish() {\n  return (S.puns || []).filter(p => p.status === 'pending' && p.reason === '预约专注没有开始')\n    .sort((x, y) => (y.at || 0) - (x.at || 0))[0] || null;\n}\nasync function missRemedyFinish(a, detail) {\n  if (!a) return;\n  a.remedy = a.remedy || {};\n  a.remedy.doneAt = Date.now();\n  a.remedyDone = true;\n  a.needEssay = false;                 // 补救做到，就不再拦着你写说明了\n  await updateAppt(a);\n  const cid = (a.charIds || [])[0] || anyCharId();\n  if (cid) {\n    await syncTimeline(cid, `用户用补救换掉了上次失约（${a.task || ''} ${apptTimeText(a)}）的惩罚：${detail}。`, 'miss_remedy', {});\n    await addPublic('remedy', charName(cid) + '：你这次没花钱，但你做到了 —— ' + detail, cid, {});\n    await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: '[失约补救] ' + detail }), null);\n  }\n  const p = missLinkedPunish();\n  if (p) { p.byPass = true; await completePunish(p, '以补救免掉：' + detail); }\n  else { toast('已记为补救完成 · 惩罚免掉'); }\n  S.draft.missWhy = ''; S.draft.missPromise = ''; S.draft.missedId = '';\n  render();\n}\nfunction missQuizRender() {\n  const Q = S.draft.missQuiz;\n  if (!Q) return;\n  const bar = Number(cfg('passRatio') || 80);\n  const w = openSheet(`<h3>✍️ 写题补救</h3>\n    <div class=\"tiny\">共 ${Q.qs.length} 题，答对 ${bar}% 即达标；达标就免掉这次失约的惩罚。答错的题会进错题本。</div>\n    <div class=\"mt10\">${Q.qs.map((qx, i) => `<div class=\"q\"><div class=\"qt\">${qNoText(qx, i)} ${esc(qx.q)}</div>\n      ${qIsPick(qx)\n        ? `<div class=\"opts\">${(qx.options || []).map((o, k) => `<button class=\"opt ${qChose(qx, Q.answers[i], k) ? 'on' : ''}\" data-mqi=\"${i}\" data-mqk=\"${k}\">\n            <span class=\"k\">${'ABCD'[k]}</span><span>${esc(o)}</span></button>`).join('')}</div>`\n        : `<input class=\"input\" id=\"mqFill${i}\" value=\"${esc(Q.answers[i] == null ? '' : Q.answers[i])}\" placeholder=\"写下你的答案\">`}</div>`).join('')}</div>\n    <button class=\"btn primary block mt12\" data-act=\"missQuizSubmit\">提交答卷</button>\n    <button class=\"btn ghost block sm mt8\" data-act=\"closeSheet\">先不写了</button>`);\n  w.addEventListener('click', e => {\n    const b = e.target.closest('[data-mqi]'); if (!b) return;\n    const i = Number(b.dataset.mqi), k = Number(b.dataset.mqk);\n    const qx = Q.qs[i] || null;\n    if (qx && qx.type === 'multi') {\n      const cur = normChoiceSet(Q.answers[i]);\n      const pos = cur.indexOf(k);\n      if (pos >= 0) cur.splice(pos, 1); else cur.push(k);\n      cur.sort((a, b2) => a - b2);\n      Q.answers[i] = cur;\n      w.querySelectorAll('[data-mqi=\"' + i + '\"]').forEach(x => x.classList.toggle('on', cur.indexOf(Number(x.dataset.mqk)) >= 0));\n      return;\n    }\n    Q.answers[i] = k;\n    w.querySelectorAll('[data-mqi=\"' + i + '\"]').forEach(x => x.classList.toggle('on', x === b));\n  });\n}\nVIEWS.help = function () {\n  return `\n  <div class=\"card hero\"><h3>📖 快速上手</h3>\n    <div class=\"tiny\" style=\"line-height:1.9\">下面按主题折叠了全部机制说明，点标题展开。最常用的四件事：<br>\n    · <b>开始专注</b>：首页「现在能做的那件事」→ 开始；<br>\n    · <b>让 TA 催你</b>：聊天室 + 号 → 专注邀约 → 预订时间段（APK 会同时立系统闹钟）；<br>\n    · <b>拿壁纸</b>：完成任务即解锁，内容库 → 壁纸库下载；嫌图费额度就设「只用我的壁纸」；<br>\n    · <b>被罚了</b>：锁定页做完惩罚即解锁；有争议去「失约说明」补写。</div></div>\n  <div class=\"card hero\"><h3>🆕 本次更新 · v1.10.0（内置版）</h3>\n    <div class=\"tiny\" style=\"line-height:1.9\">· <b>免安装内置版</b>：随小手机直接带，数据与你装过的市场版完全同源；<br>\n    · <b>到点唤醒兜底</b>：预约 / 晨间叫早 / 起床闹钟保存时都会在系统时钟立闹钟 —— 小手机被杀也准时响；<br>\n    · <b>催促与提醒落系统通知栏</b>：人不在 app 里也能收到；<br>\n    · <b>到点确认弹层</b>：预约到点直接问「现在开始吗」；<br>\n    · <b>壁纸生图闸门统一</b>：开自定义壁纸默认暂停生图，奖励壁纸也受总开关控制；<br>\n    · <b>导出/保存走系统通道</b>：APK 里备份与存图不再依赖浏览器下载；<br>\n    · <b>界面精简</b>：帮助中心折叠化、重复入口收敛、设置页归类折叠。</div></div>\n  <details class=\"card\"><summary><span>🆕 TA 会主动来找你</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">给角色装了 5 个工具，他在<b>普通聊天</b>里就能真的动手做这些事（不需要你打开本 APP）：<br>\n    · <b>查我的专注情况</b> —— 问「我这两天学得怎么样」，他会去读你的真实记录（今日/本周分钟数、次数、通过率、最有效率的时段、违规、连续打卡、专注币）。<br>\n    · <b>看昨晚睡得怎么样</b> —— 他知道你昨晚睡了多久、酝酿了多久、中途醒了几次。<br>\n    · <b>帮我记一条待办</b> —— 你说「帮我记一下」，这条待办就进了「首页 → 📝 待办」，开始专注时能直接选。<br>\n    · <b>跟我约一段专注</b> —— 他约你的时间会变成一条真的预约：到点前提醒你准备，每 5 分钟催一次、共 3 次，连着催 3 次没开始就按惩罚库开罚。<br>\n    · <b>邀我一起睡</b> —— 他邀请你一起睡，会写进「💌 TA 的邀请」并给你发一条通知，你打开就能一键躺下（他会说一句哄你入睡的话）。<br><br",
  ">\n    他也可以直接在回复里写这两种卡：<b>[陪睡:小憩:20:早点睡]</b>、<b>[约专注:21:00:背单词:25]</b>。一次回复最多写一个，你那边会看到一张卡。<br><br>\n    <b>觉得他太主动了？</b>「设置 → 聊天工具箱」里可以关掉本 APP 的工具；「设置 → 提示词预设」里可以关掉「角色陪伴专注 · TA 主动约你」这一条；APP 内「我的 → 待办 / TA 的邀请」里也能随时删掉他记的东西。</div></details>\n  <details class=\"card\"><summary><span>📨 从聊天室 + 号面板进来</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">聊天室输入框旁点 <b>+ 号</b>，里面有两个本 APP 的入口：<br>\n    · <b>专注邀约</b>：可以「现在就一起专注」，也可以「📅 预订一个时间段」。<br>\n    · <b>睡眠陪伴</b>：选睡多久、可以留一句话，TA 应你一声后直接开始睡眠记录。<br><br>\n    <b>从聊天室进来时会直接打开本 APP 的对应页面，并自动带上当前对话的角色</b>，不用再选。你也可以在 APP 里从「首页」或「睡眠」页打开同一个页面。<br><br>\n    <b>要花钱的地方</b>：每次发邀请都会走一次你自己的 API（请 TA 回你一句）；不想消耗就用首页的「开始一段专注」或睡眠页的「开始睡眠」。</div></details>\n    <details class=\"card\"><summary><span>📅 预约专注 · 预订与催促</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">在「专注邀约 → 📅 预订时间段」里选日期、时间、时长、事项。约好之后：<br>\n    · 聊天室写一条约定 + TA 记进记忆；<br>\n    · 到点前按节奏催你（默认 T-10 / T-5 / T-0，可改）：系统通知 + 聊天室提醒卡；<br>\n    · APK 会在系统时钟立到点闹钟兜底（小手机被杀也响；改期需自行删旧闹钟）；<br>\n    · 页面开着时到点会弹「现在开始」确认；连催 ${apptMaxNudge()} 次没开始就按惩罚库开罚。<br>\n    <b>硬边界</b>：催促走宿主定时任务，小手机完全关闭时不实时运行，重开补跑；开罚只能在小手机被打开时执行。</div></details>\n  <details class=\"card\"><summary><span>关于「应用锁定」的边界</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">本 APP 是跑在小手机里的网页应用，没有系统级权限，<b>无法真正锁住手机上的其他 APP</b>。实际做法是：<br>\n    1. 专注期间切出去、切后台、划掉进程，回来时会被记录为「中途离开」；<br>\n    2. 触发惩罚后 APP 进入全屏锁定页，必须做完惩罚才解锁；<br>\n    3. 想更接近「锁机」，请把专注页留在前台，并用手机自带的专注模式／屏幕使用时间限制。</div></details>\n  <details class=\"card\"><summary><span>离开是怎么被检测到的</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">页面隐藏事件 + 计时心跳双重检测。≤ 宽限时间不记违规；主动点「暂停」不算违规但要写明原因并冻结计时。休息阶段不检测、不惩罚。</div></details>\n  <details class=\"card\"><summary><span>两套记忆库</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>对外记忆库（角色可见）</b>：任务完成状态、专注时长、你写的总结、睡眠报告、惩罚与奖励记录、角色自己的任务进度。<br>\n    <b>私密学习记忆库（角色看不到）</b>：错题、薄弱点、答疑记录。只有出题、点拨和惩罚练习会调用它，角色在对话里不会主动提起。</div></details>\n  <details class=\"card\"><summary><span>奖励与凭证</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">奖励不由 APP 伪造：APP 会把奖励申请当作「系统通知」写进你和 TA 的聊天室（默认用卡片，不会伪装成你在索要），请 TA 亲自给你（TA 可以用聊天室自带的红包／转账），再把 TA 的回复原样抓回来作为凭证。本版本已声明 <b>chat.read</b>，所以正常情况下会直接抓到；抓不到时才回落到「补生成」并标记出来。<br><br>\n    <b>仍然存在的宿主限制</b>：「当前会话」只有从聊天室卡片／+ 号面板进入 APP 时才拿得到；从桌面直接打开时，APP 只能按角色读最近消息。两条都拿不到时，可以在「奖励中心 → TA 已经给我了」里手动贴原话同步。</div></details>\n  <details class=\"card\"><summary><span>💞 TA 的心愿 —— 你陪他一起实现</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>方向是反的</b>：不是你许愿让 TA 满足你，而是 TA 心里有一件一直想要的事，只有你陪他一起投入足够多的专注时间，它才会真的实现。<br><br>\n    <b>这件事由 TA 自己说</b>：点「让他说出来」，AI 会按他的人设、你们的记忆和关系生成一件「只有他才会说出口」的事，并写进他的记忆和聊天历史。你也可以「替他写一件」。<br><br>\n    <b>只有专注能推进它</b>：每通过一次考核，这段专注多少分钟就加进心愿进度。攒够需要的分钟数（默认 600 分钟，可改），就能「真正实现」—— 点下去，APP 会写出实现那一刻的画面（scene）和 TA 对你说的话（line），连同「你们一起投入了多少时间」做一张卡写进聊天室，并朗读那句话。<br><br>\n    <b>只有专注能推进它</b>：睡眠、惩罚、花专注币这些都不算推进 —— 心愿只认「通过考核的专注」。而且进度只增不减：连坐已移除，失误和爽约都不会让它倒退。</div></details>\n  <details class=\"card\"><summary><span>🔗 角色自己的任务（不再连坐）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">每次专注开始，TA 也会给自己安排一件这段时间要陪你一起做的事，显示在专注页里。<br>\n    <b>它的进度不受你的表现影响</b> —— 之前那套「连坐」（你的违规拖着 TA 的任务后退、心愿进度也跟着退、一轮结束还要念你一句）已经按你的要求整块去掉：不会再有进度倒退，也不会再出现「因为你，TA 差一点没做完」这类判定。</div></details>\n  <details class=\"card\"><summary><span>🪙 专注币（专注时长当货币）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">只有<b>通过考核的那段专注</b>才折算成币：专注分钟 × 每分钟点数（默认 1）＋ 考核通过加成（默认 +20%）。没通过的轮次不给币，惩罚和睡眠也不给、不扣。<br><br>\n    能换：🎫 免罚卡 · 💬 让 TA 夸你一句 · 🖼 一张专属壁纸（进壁纸库、不上锁）· 🌠 跟 TA 提一个愿望 · 🕊 今天放你一马。<br>\n    <span style=\"color:var(--dim2)\">注：小手机钱包只支持支出，所以专注币是 APP 内部的点数，不会变成钱包里的钱。</span></div></details>\n  <details class=\"card\"><summary><span>🎯 目标倒计时 · 📈 学习报告 · 📊 专注趋势</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>目标</b>：写下考试 / 提交日期，首页挂倒计时，并且让 TA 的督促语气跟着剩余时间变（积累期强调积累，冲刺期更紧，最后几天让你稳住作息）。<br>\n    <b>周报 / 月报</b>：由角色按你的真实数据写 —— 专注合计与次数、考核通过率、违规次数、最有效率的时段、睡眠平均与酝酿过久次数、错题集中板块、距离长期目标还剩几天。要求「只依据数据、不许编造数字」，模型没给出可用结果时自动用本地兜底版本。<br>\n    <b>趋势</b>：按每次专注的开始时间统计，看一天八个时段、星期几、最近 8 周分别投入多少，还能让 TA 点评一句。</div></details>\n  <details class=\"card\"><summary><span>🌅 晨间闭环</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">在「我的 → 晨间闭环」设一个时间和叫醒你的角色。到点：① 通知 + 面板 + 语音向你道早安；② 顺口说一句昨晚睡得怎么样；③ 提醒今天的预约专注和目标还剩几天；④ 让你写下「今天第一件事」，点一下就带着它进专注流程。<br>\n    <b>系统闹钟兜底</b>：保存晨间问候/闹钟时会在系统时钟立一个到点闹钟（APK），小手机被杀也准时响；TA 的语音早安仍需打开小手机补播。</div></details>\n  <details class=\"card\"><summary><span>想改提示词怎么办</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">本 APP 所有让角色生成内容的指令都在「我的 → 提示词与台词」里，逐条可改、可单条还原、可全部恢复默认；文案里的双花括号变量会在生成前替换成真实数据，请保留。<br>\n    另外「设置 → 提示词预设」里还有本 APP 注册的场景条目（专注陪伴、出题校验、惩罚、睡眠、心愿、目标、报告、晨间、专注币、邀约与陪睡，以及「角色陪伴专注 · TA 主动约你」），那部分也能在那里直接编辑或关掉。</div></details>\n  <details class=\"card\"><summary><span>专注壁纸的节奏 · 怎么下载</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>一张一张来的节奏：</b><br>\n    ① <b>开始专注</b> → 先攒下第 1 张（上锁，作为专注页背景）；<br>\n    ② <b>每完成一个任务</b> → <b>解锁一张</b>（休息时段就能下载它）；<br>\n    ③ 同时开始攒<b>下一张新的</b>，留给下一项任务解锁。<br>\n    所以「做完几项任务 = 能下载几张」，永远只领先任务一步：5 项任务最多 5 张可下载，最后那张没完成的任务对应的壁纸保持上锁。<br><br>\n    <b>下载方式</b>：卡片上点「下载」或「存进小手机媒体库」，也可以去「内容库 → 壁纸库」处理；<br><br>\n    另外两个生成点（不属于专注壁纸）：<b>睡眠壁纸</b>在每次开始睡眠记录时生成 1 张（不上锁、可直接下载）；<b>奖励留念</b>在领取奖励时生成 1 张（可在奖励设置里关掉）；专注币兑换「一张专属壁纸」也会生成 1 张。</div></details>\n  <details class=\"card\"><summary><span>睡眠怎么算时长（重要）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">开始睡眠前要先选陪伴角色（可多选，也可随机抽一位）。开始后自动做三件事：<b>生成睡眠壁纸当整页背景</b>、<b>让角色说一句哄睡的话并读出来</b>、正计时。<br><br>\n    <b>① 酝酿睡意 = 没睡的时间。</b>和角色闲聊、切到别的 APP、手指碰屏幕，这些都算「还醒着」，全部计入酝酿睡意。<br>\n    <b>② 睡眠 = 安静满 N 分钟之后才算。</b>你在睡眠页 <b>连续 N 分钟不动屏幕、也不和角色互动</b>（N 默认 5，可在睡眠页改），从这一档安静开始才计入睡眠。<br>\n    <b>③ 睡着后又碰了屏幕</b>：安静计时归零，那之后的 N 分钟又算酝酿，等再次安静满 N 分钟才继续计入。<br>\n    <b>④ 切到别的 APP 的时间不计入睡眠</b>（按你还醒着算）。切走之后直接睡了，结束时点「我切走之后就睡到现在」就能补上，也可以手填分钟数。<br><br>\n    报告会分别给出总时长 / 酝酿睡意 / 实际入睡，连续规律作息达标按<b>实际入睡</b>算。</div></details>\n  <details class=\"card\"><summary><span>所有 AI 生成都留档</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">本 APP 每一次调用大模型都会记录在「我的 → 生成记录」：陪伴台词、催问进度、角色自己的任务、TA 应你的邀请、出题与解析、私密答疑、惩罚台词与批改、奖励申请与兜底台词、睡眠报告、哄睡语、睡前闲聊、睡前故事、叫醒台词、以及几种壁纸的生图提示词。每条都能看完整的提示词和模型返回、复制全文、单独删除或整体清空；保留上限可自己改（默认最近 200 条）。<br>留档只存在本机（IndexedDB），不会上传。</div></details>\n  <details class=\"card\"><summary><span>惩罚有哪些类型</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">7 种，都能自定义参数：<br>\n    💸 <b>转账给角色</b>（金额，会尝试真实扣款，钱包不可用可仅记账）<br>\n    ✍️ <b>完成练习题</b>（题量、达标正确率）<br>\n    🎁 <b>购买礼物</b>（礼物名、价格）<br>\n    📝 <b>抄写指定内容</b>（抄写文本、遍数；按去标点字数校验）<br>\n    📄 <b>写反思／检讨</b>（最少字数）<br>\n    🏃 <b>做一件具体的事</b>（做完点确认）<br>\n    ⏰ <b>限时打卡</b>（总时长、间隔、次数；必须按时回来点「我在」）</div></details>\n  <details class=\"card\"><summary><span>睡眠计时页怎么看（详情）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">开始睡眠后，计时页从上到下：<br>\n    ① <b>计时与时长</b> —— 总 / 酝酿 / 睡眠三个数字实时走；<br>\n    ② <b>睡前的房间</b> —— 一段环境描写（<b>第三人称、角色用名字、用户称「你」</b>），可换一段或收藏；<br>\n    ③ <b>💬 睡前闲聊</b> —— 哄睡语是第一条消息，之后可以一直聊（每句都算互动，酝酿往后推）；<br>\n    ④ 中断点、睡眠壁纸、故事入口。<br>\n    结束时会问你两个问题：<b>真的睡着了吗</b>和<b>预计深度睡眠多少分钟</b>，两者都会写进报告。</div></details>\n  <details class=\"card\"><summary><span>睡眠壁纸可以用自己的图</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">睡眠壁纸卡片上有「⬆️ 用我自己的图片当睡眠壁纸」：选一张本地图片就能替换角色生成的画面，会立刻铺成计时页背景，同时存进壁纸库（不上锁、可直接保存）。<br>\n    本版本已声明 <b>media.pick</b>，所以会优先调用小手机的媒体选择器；宿主没开放时自动退化成应用内文件选择，效果一样。</div></details>\n  <details class=\"card\"><summary><span>备份与导出</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">「我的 → 数据 → 导出备份」有三种：<b>含语音和图片</b>（原始文件打包成 .json，可能几十 MB，换设备导入即恢复）、<b>不含媒体</b>、<b>文字版</b>。<br>\n    备份内容包括：设置、专注与睡眠记录（含中断点、时长拆分、报告）、预约专注、题库、错题与私密记忆、惩罚、奖励、账本、礼物、生成记录、收藏夹（含文件夹层级）、睡前故事、待办清单、TA 的邀请。</div></details>\n  <details class=\"card\"><summary><span>收藏夹与文件夹</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">入口在「我的 → ⭐ 收藏夹」，也能从生成记录、壁纸库、睡前故事、睡眠报告、睡前闲聊、睡眠环境描写处点 ⭐ 收藏。<br>\n    <b>文件夹可以一层层往下建</b>，顶部面包屑可以逐层返回；任何条目都能「移动」到别的文件夹。删文件夹会连里面的内容一起删掉，会先二次确认。</div></details>\n  <details class=\"card\"><summary><span>睡眠中断点与睡眠报告</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>中断点</b>：睡着途中突然醒了但还想接着睡 —— 不要结束睡眠，点「🌗 我醒了一下」记一个标记（可写原因）。计时照走、睡眠不中断，可随时删掉误记的标记。<br>\n    <b>报告</b>：结束睡眠会自动生成并跳到报告页，四块 —— 睡眠质量分析、睡眠观察、健康作息建议、角色碎碎念；<b>有中断点时会单独分析中断的时间点、次数和对睡眠完整性的影响</b>。<br>\n    <b>报告存在哪</b>：写进这条睡眠记录里，「睡眠 → 睡眠记录」点任意一条就能打开；没有报告的历史记录会显示「生成这份报告」按钮。报告同时会同步进这个角色的短期记忆。</div></details>\n  <details class=\"card\"><summary><span>睡眠与故事的留存</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">睡眠是<b>正计时且会存下来</b>的：开始时会写入本地数据库，中途离开小程序、关掉 APP 都不影响计时，重开后自动接着上次继续，到设定时长会提醒但不强制结束。<br>\n    睡眠壁纸生成即进壁纸库（<b>不锁</b>，可直接保存），并单独存了一份引用，重开 APP 也能重新保存、发到聊天室。<br>\n    睡前故事的故事文本、听到第几段、每一段已生成的语音都会留存：下次从「睡眠 → 睡前故事 → 往期故事」点「接着听」，听过的段落不会重新生成语音。</div></details>\n  <details class=\"card\"><summary><span>睡前故事能后台播放吗（实测结论：不能）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">实测：<b>只要退出 APP，播放就会停止</b>——不论逐段朗读还是整篇连播。原因是播放由小手机的播放器代播，而 APP 关闭时宿主会把这个播放器一并停掉。宿主目前也没有给 APP「关闭后继续播放音频」的能力，所以这一条在 APP 侧无解，不是设置问题。<br>\n    <b>想真正锁屏／退出后听</b>：用「💾 导出整篇音频」把音频文件存出来（先存小手机媒体库，失败则走浏览器下载），再用手机自己的播放器播放。能否找到存下来的文件，取决于小手机里有没有可见的媒体／文件入口。</div></details>\n  <details class=\"card\"><summary><span>通知 / 语音 / 生图</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">角色语音依赖你在小手机「设置 → 语音」里配置的服务；生图依赖「设置 → 生图」；所有 AI 生成都用你自己配置的 API key。</div></details>\n  <details class=\"card\"><summary><span>📜 旧版本更新记录（v1.9.2 ~ v2.2.0）</span></summary>\n    <div class=\"tiny\" style=\"line-height:1.8\">角色陪伴专注 v2.2.0 · 作者 doris<br>带虚拟角色陪伴监督的专注工具：学习模块 + 睡眠模块 + 壁纸库、奖励中心与收藏夹。<br>\n    <b>v2.2.0 抽背重做</b>：① 「🎤 让 TA 抽背」改成<b>聊天室</b>形式 —— TA 说一句、你答一句，先看清题目再作答（不再用语音、不再藏题干）；② 每张卡随机以<b>默写 / 填空 / 接力</b>形式考察，长答案出「答上半句、你接下半句」；③ 提供<b>纯本地出题</b>开关（默认开），完全不调用大模型，AI 换问法可选；④ 抽背结果直接写回卡片等级与对错次数，并记进背书流水。<br>\n    <b>v2.1.0 小纸条 · 语音复听 · 同步修复</b>：\n    ① <b>小纸条 × 星星瓶</b>：专注撑不住时写张小纸条递给角色，他会在纸条边上给你写一句批注；心情对了还会松一松 —— 让你歇一会儿（到点自动接着走）/ 多攒一张壁纸 / 现在就出声哄你一句。所有纸条收进「内容库 → ⭐ 星星瓶」，哄你睡时他会接着你今天递过的纸条说；\n    ② <b>语音留档可复听</b>：角色说过的每一句都连音频一起留档（不用重新合成），生成记录里可单条复听、循环读，也能把最近几条串起来循环；\n    ③ <b>修复角色任务进度不显示</b>：TA 的进度现在和你的任务同步，你勾完一项他那边就走到哪；\n    ④ <b>卡片 / + 号面板跳转精确化</b>：改成显式映射表，卡片里带的时长、事项、时间会直接预填到对应页面；\n    ⑤ 启动自检补上新组件，缺了会直接在首页点名。\n    <b>v2.0.0 掌握度与出题配比</b>：① 题库每题都记「做对几次」，做对满 N 次（可设）标为已掌握，抽题优先未掌握 —— 掌握度直接影响该题以后还出不出现；② 惩罚/校验统一按「新题 / 错题 / 题库题」× 「单选 / 多选 / 判断 / 填空」双重配比组卷，可按分类出题；③ 题库支持自定义知识点分类、批量移动与筛选；④ AI 出题改成分批请求，不再长 JSON 超时导致「没新题」；⑤ 修复睡眠页换陪睡角色不生效（壁纸/报告一直用错角色）。<br>\n    <b>v1.9.3 界面整理</b>：同类功能合成一个入口（计划与邀请 / 学习档案 / 激励中心 / 报告与趋势 / 奖励与账本 / 内容库），页顶标签切换；首页改成「先能做的那件事」在最上面；重复入口收掉；整体重新配了色与间距。<br>\n    <b>v1.9.2</b>：① 权限 <b>chat.tools</b>；② 角色可主动调用 <b>5 个工具</b>并支持 <b>[陪睡:…] / [约专注:…]</b> 两种卡片指令；③ + 号面板入口为 <b>「专注邀约」「睡眠陪伴」</b>（直接打开本 APP，并带上当前对话的角色）；④ 专注邀约支持 <b>预订时间段</b>，到点前 TA 来催、连着催 3 次没开始就开罚。</div></details>`;\n};\n/* ==========================================================\n   动作 · 通用 / 设置\n   ========================================================== */\nObject.assign(ACTIONS, {\n  gotoSetup: () => { initDraft(); go('setup'); },\n  /* 就地改壁纸提示词：不用先去提示词设置里翻 */\n  openWallPrompt: () => {\n    const v = cfg('wallStyle') || 'gaze';\n    const pid = wallPromptId(v === 'rotate' ? 'gaze' : v);\n    if (!promptDef(pid)) { toast('找不到这条提示词'); return; }\n    ACTIONS.openPromptEdit({ dataset: { id: pid } });\n  },\n  openSleepWallPrompt: () => {\n    const pid = sleepWallPromptIdForEdit();\n    if (!promptDef(pid)) { toast('找不到这条提示词'); return; }\n    ACTIONS.openPromptEdit({ dataset: { id: pid } });\n  },\n  /* ---------------- 壁纸：自己的图 + 生成总开关 + 画面变化 ---------------- */\n  wallPickCustom: async () => {\n    toast('选一张图当全局壁纸…');\n    let url = '';\n    try { url = await pickImageData(); } catch (e) { url = ''; }\n    if (!url) { toast('没有选到图片'); return; }\n    const ok = await setCustomWall(url);\n    toast(ok ? '已改用你的壁纸，铺全局' : '没存下来，再试一次');\n    render();\n  },\n  wallClearCustom: async () => {\n    S.settings.customWallUse = false;\n    await saveSettings(true);\n    S.customWallData = '';\n    renderWall(); render();\n    toast('已撤掉自定义壁纸（图还在媒体库里，随时能再启用）');\n  },\n  wallMode: async (el) => {\n    const mode = el.dataset.v;\n    if (mode === 'none') {\n      S.settings.wallGenOff = true;\n    } else {\n      S.settings.wallGenOff = false;\n      if (mode === 'ai') {\n        S.settings.customWallUse = false;\n        S.settings.wallGenWithCustom = false;\n      } else {\n        if (!cfg('customWallRef') && !S.customWallData) { toast('先点「上传我的壁纸」选一张，再切这个模式'); render(); return; }\n        S.settings.customWallUse = true;\n        S.settings.wallGenWithCustom = mode === 'both';\n      }\n    }\n    await saveSettings(true);\n    toast({\n      none: '已停止所有 AI 壁纸生成（专注/睡眠/奖励都不再生图，不再耗额度）',\n      ai: '只用 AI 生成壁纸，你的自定义壁纸不再铺全局',\n      custom: '只用你的自定义壁纸，AI 不再生图',\n      both: 'AI 继续生成 + 你的壁纸铺全局（专注/睡眠中的专属壁纸仍优先显示）'\n    }[mode] || '已更新壁纸模式');\n    renderWall(); render();\n  },\n  wallToggleVary: async () => {\n    S.settings.wallVary = !(S.settings.wallVary !== false);\n    await saveSettings(true);\n    toast(S.settings.wallVary !== false ? '已开启：每次生成换机位/光线/构图' : '已关闭：每次按同一套模板画');\n    render();\n  },\n  /* ---------------- 番茄模板 ---------------- */\n  fpSave: () => {\n    const d = S.draft;\n    const planN = (d.plan || []).filter(t => t.content && t.content.trim()).length;\n    S.draft.fpWithPlan = planN > 0;\n    const w = openSheet(`<h3>💾 存成番茄模板</h3>\n      <div class=\"tiny\">会存下：${esc(fpText({ focusMin: d.focusMin, breakMin: d.breakMin, cycles: d.cycles, reviewEvery: d.reviewEvery }))}${planN ? '，以及现在的 ' + planN + ' 条任务' : '（现在没有可存的任务）'}。</div>\n      <label class=\"fl\">模板名字</label>\n      <input class=\"input\" id=\"fpName\" value=\"${esc(fpDefaultName(d))}\" placeholder=\"例如：25+5 四轮 / 深夜 50 分钟\">\n      ${planN ? `<button class=\"chip on mt10\" id=\"fpWithPlan\" data-fpplan=\"1\">把 ${planN} 条任务也一起存进模板</button>` : ''}\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"fpSaveDo\">保存模板</button></div>`);\n    const chip = document.getElementById('fpWithPlan');\n    if (chip) chip.addEventListener('click', () => {\n      S.draft.fpWithPlan = !S.draft.fpWithPlan;\n      chip.classList.toggle('on', !!S.draft.fpWithPlan);\n    });\n  },\n  fpSaveDo: async () => {\n    const d = S.draft;\n    const name = ((document.getElementById('fpName') || {}).value || '').trim() || fpDefaultName(d);\n    const plan = d.fpWithPlan\n      ? (d.plan || []).filter(t => t.content && t.content.trim()).map(t => ({ content: t.content.trim(), est: Number(t.est) || 0 }))\n      : [];\n    const rec = {\n      id: uid(), name: name.slice(0, 20), focusMin: Number(d.focusMin) || 25,\n      breakMin: Number(d.breakMin) || 5, cycles: Number(d.cycles) || 1,\n      reviewEvery: d.reviewEvery === 'session' ? 'session' : 'focus',\n      plan: plan, at: Date.now()\n    };\n    S.settings.focusPresets = fpList().concat([rec]);\n    S.draft.fpSel = rec.id;\n    await saveSettings(true);\n    closeAllSheets();\n    toast('已存为模板：' + rec.name + (plan.length ? '（含 ' + plan.length + ' 条任务）' : ''));\n    render();\n  },\n  fpUse: el => {\n    const p = fpList().find(x => String(x.id) === String(el.dataset.id));\n    if (!p) return;\n    S.draft.fpSel = p.id;\n    S.draft.focusMin = Number(p.focusMin) || 25;\n    S.draft.breakMin = Number(p.breakMin) || 5;\n    S.draft.cycles = Number(p.cycles) || 1;\n    S.draft.reviewEvery = p.reviewEvery === 'session' ? 'session' : 'focus';\n    toast('已套用「' + p.name + '」：' + fpText(p));\n    render();\n  },\n  fpUsePlan: async el => {\n    const p = fpList().find(x => String(x.id) === String(el.dataset.id));\n    if (!p || !(p.plan || []).length) return;\n    S.draft.plan = (p.plan || []).map(t => ({ content: t.content, est: t.est || '' }));\n    S.draft.fpSel = p.id;\n    toast('已套用模板里的 ' + S.draft.plan.length + ' 条任务');\n    render();\n  },\n  fpDel: async el => {\n    const p = fpList().find(x => String(x.id) === String(el.dataset.id));\n    if (!p) return;\n    const inSheet = modalStack.length > 0;\n    const ok = await confirmBox('删除这个模板？', '「' + p.name + '」会被删掉；已经开始的专注不受影响。', '删除');\n    if (!ok) return;\n    S.settings.focusPresets = fpList().filter(x => String(x.id) !== String(p.id));\n    if (String(S.draft.fpSel) === String(p.id)) S.draft.fpSel = '';\n    await saveSettings(true);\n    closeAllSheets();\n    toast('已删除模板：' + p.name);\n    if (inSheet) ACTIONS.fpManage(); else render();\n  },\n  fpRen: async el => {\n    const id = el.dataset.id;\n    const inp = document.querySelector('[data-fpn=\"' + id + '\"]');\n    const v = inp ? (inp.value || '').trim() : '';\n    const p = fpList().find(x => String(x.id) === String(id));\n    if (!p) return;\n    if (!v) { toast('名字不能空'); return; }\n    p.name = v.slice(0, 20);\n    await saveSettings(true);\n    toast('已改名：' + p.name);\n    fpShow();\n  },\n  fpManage: () => {\n    const list = fpList();\n    openSheet(`<h3>⚙️ 管理番茄模板（${list.length}）</h3>\n      <div class=\"tiny\">名字可以直接在框里改，改完点右边的「保存」。套用请回专注设置页点模板。</div>\n      <div class=\"mt10\">${list.length ? list.map(p => `<div class=\"item\" style=\"padding:9px 0\">\n        <div class=\"ic\">🍅</div>\n        <div class=\"grow\"><input class=\"input\" style=\"padding:7px 9px;font-size:13px\" data-fpn=\"${esc(p.id)}\" value=\"${esc(p.name)}\">\n          <div class=\"tiny mt6\">${esc(fpText(p))}</div></div>\n        <button class=\"btn sm ghost\" data-act=\"fpRen\" data-id=\"${esc(p.id)}\">保存</button>\n        <button class=\"btn sm ghost\" data-act=\"fpDel\" data-id=\"${esc(p.id)}\">删</button></div>`).join('')\n        : `<div class=\"tiny\">还没有模板。回到专注设置页，把时长轮数调好再点「存成模板」。</div>`}</div>\n      <button class=\"btn primary block mt12\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  delWhiteAsk: async el => {\n    const i = Number(el.dataset.i);\n    const x = (cfg('whitelist') || [])[i];\n    if (!x) return;\n    const ok = await confirmBox('移出白名单？', '「' + x.name + '」将不再享受专注中的申诉豁免。', '移出');\n    if (!ok) return;\n    S.settings.whitelist.splice(i, 1);\n    await saveSettings(true);\n    toast('已移出白名单：' + x.name);\n    render();\n  },\n  setDraft: el => {\n    const k = el.dataset.k, v = el.dataset.num === '1' ? Number(el.dataset.v) : el.dataset.v;\n    S.draft[k] = v;\n    if (k === 'sleepMode') { const hit = SLEEP_MODES.find(x => x[0] === v); if (hit) S.draft.sleepMin = hit[1]; }\n    /* 校验时机：当场就存进设置，避免「选了每轮校验却没生效」 */\n    if (k === 'reviewEvery') { S.settings.reviewEvery = v === 'session' ? 'session' : 'focus'; saveSettings(true); }\n    render();\n  },\n  toggleChar: el => {\n    const arr = S.draft.charIds || [], i = arr.indexOf(el.dataset.id);\n    if (i >= 0) arr.splice(i, 1); else arr.push(el.dataset.id);\n    S.draft.charIds = arr;\n    S.settings.charIds = arr.slice();     // 立刻写进设置：首页 / 其它页同步更新\n    saveSettings();\n    render();\n  },\n  randomChar: () => {\n    if (!S.chars.length) { toast('还没有可用角色'); return; }\n    const c = S.chars[Math.floor(Math.random() * S.chars.length)];\n    S.draft.charIds = [c.id]; toast('随机抽到：' + c.name); render();\n  },\n  planAdd: () => { (S.draft.plan = S.draft.plan || []).push({ content: '', est: '' }); render(); },\n  planDel: el => {\n    S.draft.plan.splice(Number(el.dataset.i), 1);\n    if (!S.draft.plan.length) S.draft.plan.push({ content: '', est: '' });\n    render();\n  },\n  /* 从 TA 记的待办里挑一条当本次任务 */\n  planFromTodos: () => {\n    const open = (S.todos || []).filter(t => !t.done);\n    if (!open.length) { toast('TA 还没给你记待办；在聊天里跟他说「帮我记一下…」就行'); return; }\n    const w = openSheet(`<h3>从待办里选</h3>\n      <div class=\"tiny\">选中的会放进「任务预设」，并标记为已排入。</div>\n      <div class=\"chips mt10\">${open.map(t => `<button class=\"chip\" data-td=\"${esc(t.id)}\">${esc(t.text)}${Number(t.minutes) ? ' · ' + t.minutes + ' 分' : ''}</button>`).join('')}</div>\n      <button class=\"btn block ghost mt12\" data-act=\"closeSheet\">取消</button>`);\n    w.addEventListener('click', async e => {\n      const b = e.target.closest('[data-td]'); if (!b) return;\n      const t = (S.todos || []).find(x => String(x.id) === String(b.dataset.td));\n      if (!t) return;\n      S.draft.plan = (S.draft.plan || []).filter(p => p.content);\n      if (!S.draft.plan.length) S.draft.plan = [];\n      S.draft.plan.push({ content: t.text, est: Number(t.minutes) || 0 });\n      t.usedAt = Date.now();\n      await saveTodo(t);\n      closeAllSheets(); toast('已加入任务：' + t.text); render();\n    });\n  },\n  setVoiceMode: async el => {\n    S.settings.voiceMode = el.dataset.v;\n    if (S.session) S.session.voiceOn = el.dataset.v !== 'off';\n    await saveSettings(true); if (S.session) await saveSession(true);\n    toast('语音模式已更新'); render();\n  },\n  setSetting: async el => {\n    S.settings[el.dataset.k] = el.dataset.num === '1' ? Number(el.dataset.v) : el.dataset.v;\n    await saveSettings(); render();\n  },\n  toggleSetting: async el => { S.settings[el.dataset.k] = !S.settings[el.dataset.k]; await saveSettings(); render(); },\n  toggleTrigger: async el => { S.settings.punishTrigger[el.dataset.k] = !S.settings.punishTrigger[el.dataset.k]; await saveSettings(); render(); },\n  setStreakMiles: async () => {\n    const v = Number(cfg('streakNextMile') || 0);\n    if (!v) { toast('先填一个天数'); return; }\n    S.settings.sleepStreakMiles = streakMiles().filter(x => x < v).concat([v]).sort((a, b) => a - b);\n    await saveSettings(true);\n    toast('里程碑：' + S.settings.sleepStreakMiles.join(' / ') + ' 天'); render();\n  },\n  togglePunishItem: async el => {\n    const p = (cfg('punishLib') || []).find(x => x.id === el.dataset.id);\n    if (!p) return;\n    p.enabled = !p.enabled; await saveSettings(true); render();\n  },\n  punishFields: () => { },\n  editPunishItem: el => {\n    const id = el && el.dataset.id;\n    const found = id ? (cfg('punishLib') || []).find(x => x.id === id) : null;\n    const it = found ? JSON.parse(JSON.stringify(found)) : {\n      id: 'p_' + uid(), kind: 'pay', title: '', detail: '', amount: 10000, count: 20, ratio: 80,\n      gift: '一束向日葵', price: 199, enabled: true,\n      text: '', minWords: 200, actName: '', checkinMin: 20, checkinGap: 5, checkinCount: 4\n    };\n    S.draft.editPunish = it;\n    const w = openSheet(`<h3>${id ? '编辑' : '添加'}惩罚项目</h3>\n      <label class=\"fl\">标题</label><input class=\"input\" id=\"pTitle\" value=\"${esc(it.title)}\" placeholder=\"如：给陪伴角色转账 10000 元\">\n      <label class=\"fl\">类型（参数都可以自己填）</label>\n      <div class=\"chips\">\n        ${PUNISH_KINDS.map(([k, n]) => `<button class=\"chip ${it.kind === k ? 'on' : ''}\" data-act=\"punishKind\" data-v=\"${k}\">${PUNISH_ICON[k] || ''} ${n}</button>`).join('')}\n      </div>\n      <div id=\"pFields\">${punishFieldsHTML(it)}</div>\n      <label class=\"fl\">说明</label><input class=\"input\" id=\"pDetail\" value=\"${esc(it.detail || '')}\">\n      <div class=\"row mt14\" style=\"gap:10px\">\n        ${id ? `<button class=\"btn ghost\" data-act=\"delPunishItem\" data-id=\"${esc(it.id)}\">删除</button>` : `<button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>`}\n        <button class=\"btn primary grow\" data-act=\"savePunishItem\" data-id=\"${esc(it.id)}\">保存</button></div>`);\n  },\n  punishKind: el => {\n    const it = S.draft.editPunish; if (!it) return;\n    it.kind = el.dataset.v;\n    const f = document.getElementById('pFields'); if (f) f.innerHTML = punishFieldsHTML(it);\n    document.querySelectorAll('[data-act=\"punishKind\"]').forEach(b => b.classList.toggle('on', b.dataset.v === it.kind));\n  },\n  savePunishItem: async () => {\n    const it = S.draft.editPunish; if (!it) return;\n    it.title = (document.getElementById('pTitle').value || '').trim() || '未命名惩罚';\n    it.detail = (document.getElementById('pDetail').value || '').trim();\n    if (it.kind === 'pay') it.amount = Number(document.getElementById('pAmount').value) || 0;\n    if (it.kind === 'quiz') { it.count = Number(document.getElementById('pCount').value) || 20; it.ratio = Number(document.getElementById('pRatio').value) || 80; }\n    if (it.kind === 'gift') { it.gift = (document.getElementById('pGift').value || '').trim() || '一件小礼物'; it.price = Number(document.getElementById('pPrice').value) || 0; }\n    if (it.kind === 'txt') {\n      it.text = (document.getElementById('pTxt').value || '').trim();\n      it.count = Math.max(1, Number(document.getElementById('pCount').value) || 1);\n      if (!it.text) { toast('请填写要抄写的内容'); return; }\n    }\n    if (it.kind === 'essay') it.minWords = Math.max(20, Number(document.getElementById('pMinWords').value) || 200);\n    if (it.kind === 'act') {\n      it.actName = (document.getElementById('pAct').value || '').trim();\n      if (!it.actName) { toast('请填写要做的事'); return; }\n    }\n    if (it.kind === 'checkin') {\n      it.checkinMin = Math.max(1, Number(document.getElementById('pChkMin').value) || 20);\n      it.checkinGap = Math.max(1, Number(document.getElementById('pChkGap').value) || 5);\n      it.checkinCount = Math.max(1, Number(document.getElementById('pChkCount').value) || 4);\n    }\n    const lib = cfg('punishLib'), i = lib.findIndex(x => x.id === it.id);\n    if (i >= 0) lib[i] = it; else lib.push(it);\n    await saveSettings(true); closeAllSheets(); toast('已保存'); render();\n  },\n  delPunishItem: async el => {\n    S.settings.punishLib = (cfg('punishLib') || []).filter(x => x.id !== el.dataset.id);\n    await saveSettings(true); closeAllSheets(); render();\n  },\n  addPunishText: () => { openSheet(`<h3>添加惩罚台词</h3><textarea id=\"ptNew\" placeholder=\"例如：这就是你说的再学十分钟吗？\"></textarea>\n    <button class=\"btn primary block mt14\" data-act=\"savePunishText\">保存</button>`); },\n  savePunishText: async () => {\n    const v = (document.getElementById('ptNew').value || '').trim();\n    if (!v) { toast('请填写内容'); return; }\n    S.settings.punishTexts = (cfg('punishTexts') || []).concat([v]);\n    await saveSettings(true); closeAllSheets(); render();\n  },\n  delPunishText: async el => { S.settings.punishTexts.splice(Number(el.dataset.i), 1); await saveSettings(true); render(); },\n  addWhite: () => { openSheet(`<h3>添加白名单应用</h3><label class=\"fl\">应用名</label><input class=\"input\" id=\"wlName\" placeholder=\"如：词典\">\n    <label class=\"fl\">用途（可选）</label><input class=\"input\" id=\"wlNote\" placeholder=\"如：查单词\">\n    <button class=\"btn primary block mt14\" data-act=\"saveWhite\">保存</button>`); },\n  saveWhite: async () => {\n    const n = (document.getElementById('wlName').value || '').trim();\n    if (!n) { toast('请填写应用名'); return; }\n    S.settings.whitelist = (cfg('whitelist') || []).concat([{ name: n, note: (document.getElementById('wlNote').value || '').trim() }]);\n    await saveSettings(true); closeAllSheets(); render();\n  },\n  delWhite: async el => { S.settings.whitelist.splice(Number(el.dataset.i), 1); await saveSettings(true); render(); },\n  permCheck: async () => {\n    let man = null, cap = null;\n    try { man = (API && API.app && API.app.getManifest) ? await API.app.getManifest() : null; } catch (e) { man = null; }\n    try { cap = (API && API.app && API.app.getCapabilities) ? await API.app.getCapabilities() : null; } catch (e) { cap = null; }\n    const m2 = (man && man.manifest) ? man.manifest : man;\n    const perms = (m2 && m2.permissions) || [];\n    const ext = ((m2 || {}).extensions) || {};\n    const chat = ext.chat || {};\n    const plus = chat.plusActions || [];\n    const dirs = chat.directives || [];\n    const tools = ext.tools || [];\n    const events = ext.events || [];\n    const hasTools = perms.indexOf('chat.tools') >= 0;\n    const launch = await sdk(() => API.app.getLaunchContext(), null);\n    const srcText = launch\n      ? [launch.source, launch.actionId || launch.entry, launch.directiveId].filter(Boolean).join(' · ')\n      : '桌面直接打开';\n    openSheet(`<h3>权限自检</h3>\n      <div class=\"kv\"><span class=\"k\">APP 版本</span><span>${esc((m2 && m2.version) || '读不到')}</span></div>\n      <div class=\"kv\"><span class=\"k\">chat.tools（角色调用工具）</span>\n        <span style=\"color:${hasTools ? 'var(--teal)' : '#ff9aa6'}\">${perms.length ? (hasTools ? '已授权 ✅' : '未授权 ❌') : '读不到'}</span></div>\n      <div class=\"kv\"><span class=\"k\">注册的工具</span><span style=\"color:${tools.length ? 'var(--teal)' : 'var(--dim2)'}\">${tools.length ? tools.length + ' 个 ✅' : '0 个'}</span></div>\n      <div class=\"kv\"><span class=\"k\">卡片指令</span><span style=\"color:${dirs.length ? 'var(--teal)' : 'var(--dim2)'}\">${dirs.length ? dirs.length + ' 条 ✅' : '0 条'}</span></div>\n      <div class=\"kv\"><span class=\"k\">+ 号面板入口</span><span style=\"color:${plus.length ? 'var(--teal)' : '#ffb37a'}\">${perms.length ? (plus.length ? plus.length + ' 个 ✅' : '未注册 ❌') : '读不到'}</span></div>\n      <div class=\"kv\"><span class=\"k\">后台事件</span><span style=\"color:${events.length ? 'var(--teal)' : 'var(--dim2)'}\">${events.length ? events.length + ' 条 ✅' : '0 条'}</span></div>\n      <div class=\"kv\"><span class=\"k\">本次打开方式</span><span>${esc(srcText)}</span></div>\n      ${plus.length ? `<div class=\"tiny mt10\">面板入口：${esc(plus.map(p => p.label + (p.presentation ? '（' + p.presentation + '）' : '')).join('、'))}</div>` : ''}\n      ${tools.length ? `<div class=\"tiny mt6\">工具：${esc(tools.map(t => t.name || t.id).join('、'))}</div>` : ''}\n      ${dirs.length ? `<div class=\"tiny mt6\">指令：${esc(dirs.map(d => d.syntax || d.label).join('　'))}</div>` : ''}\n      <div class=\"tiny mt10\">已声明权限（${perms.length}）：${esc(perms.join('、')) || '读不到'}</div>\n      <button class=\"btn block ghost sm mt8\" data-act=\"permCheckRaw\">看原始返回（调试）</button>\n      <button class=\"btn primary block mt10\" data-act=\"closeSheet\">知道了</button>`);\n    S.draft.permRaw = '【manifest】\\n' + JSON.stringify(man, null, 2) + '\\n\\n【capabilities】\\n' + JSON.stringify(cap, null, 2);\n  },\n  permCheckRaw: () => {\n    openSheet(`<h3>原始返回</h3><div class=\"tiny\" style=\"white-space:pre-wrap;line-height:1.7;max-height:56vh;overflow:auto;background:var(--card2);border-radius:10px;padding:10px\">${esc(S.draft.permRaw || '（没有数据）')}</div>\n      <button class=\"btn primary block mt10\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  checkNotifPerm: () => { openSheet(`<h3>通知说明</h3><div class=\"tiny\" style=\"line-height:1.8\">\n    本 APP <b>不设置桌面图标角标（红点）</b>，只在应用内和系统通知栏提示。<br>\n    收不到提醒时：1. 确认小手机「设置」里已允许通知；2. 手机浏览器／PWA 也需要允许通知；3. APP 完全关闭时定时任务不实时运行，重新打开后会补跑到期的提醒。</div>\n    <button class=\"btn primary block mt14\" data-act=\"closeSheet\">知道了</button>`); },\n  reloadChars: async () => { await reloadChars(false); },\n  randomCharSaved: async () => {\n    if (!S.chars.length) { toast('还没有角色'); return; }\n    const c = S.chars[Math.floor(Math.random() * S.chars.length)];\n    S.settings.charIds = [c.id]; await saveSettings(true); toast('随机抽到：' + c.name); render();\n  },\n  clearChars: async () => { S.settings.charIds = []; await saveSettings(true); render(); },\n  toggleSavedChar: async el => {\n    const arr = S.settings.charIds || [], i = arr.indexOf(el.dataset.id);\n    if (i >= 0) arr.splice(i, 1); else arr.push(el.dataset.id);\n    S.settings.charIds = arr; if (S.draft) S.draft.charIds = arr.slice();\n    await saveSettings(true);\n    toast(arr.length ? '专注陪伴：' + arr.map(id => charName(id)).join('、') : '已清空专注陪伴阵容');\n    render();\n  },\n  testVoice: async el => {\n    toast('生成试听语音…');\n    const ok = await speak(el.dataset.id, `我是${charName(el.dataset.id)}，今天也一起加油吧。`);\n    if (!ok) toast('语音不可用：请先在小手机「设置 → 语音」里配置');\n  }\n});\n/* 惩罚类型：金额 / 答题 / 礼物 / 抄写 / 反思 / 做事 / 限时打卡 —— 都可自定义参数 */\n/* v1.9.2 校验标记 J */\nconst PUNISH_KINDS = [\n  ['pay', '转账给角色'], ['quiz', '完成练习题'], ['gift', '购买礼物'],\n  ['txt', '抄写指定内容'], ['essay', '写反思 / 检讨'], ['act', '做一件具体的事'], ['checkin', '限时打卡']\n];\nconst PUNISH_ICON = { pay: '💸', quiz: '✍️', gift: '🎁', txt: '📝', essay: '📄', act: '🏃', checkin: '⏰' };\nfunction punKindLabel(k) { const hit = PUNISH_KINDS.filter(x => x[0] === k)[0]; return hit ? hit[1] : '自定义'; }\nfunction punSummary(p) {\n  if (p.kind === 'pay') return '金额 ¥' + (p.amount || 0);\n  if (p.kind === 'quiz') return (p.count || 20) + ' 题 · 正确率 ' + (p.ratio || 80) + '%';\n  if (p.kind === 'gift') return esc(p.gift || '指定礼物') + ' · ¥' + (p.price || 0);\n  if (p.kind === 'txt') return '抄写 ' + (p.count || 1) + ' 遍 · 约 ' + String(p.text || '').length + ' 字/遍';\n  if (p.kind === 'essay') return '至少 ' + (p.minWords || 200) + ' 字';\n  if (p.kind === 'act') return esc(p.actName || '');\n  if (p.kind === 'checkin') return (p.checkinMin || 20) + ' 分钟内 · 每 ' + (p.checkinGap || 5) + ' 分钟打卡 · 共 ' + (p.checkinCount || 4) + ' 次';\n  return '';\n}\nfunction txtCount(s) { return String(s || '').replace(/[\\s，。、；：！？,.;:!?\"'“”‘’（）()【】\\[\\]《》—…·~`\\-]/g, '').length; }\nfunction txtTarget(p) { return txtCount(p.text || '') * Math.max(1, Number(p.count) || 1); }\nfunction punishFieldsHTML(it) {\n  if (it.kind === 'pay') return `<label class=\"fl\">金额（元）</label><input class=\"input\" id=\"pAmount\" type=\"number\" inputmode=\"numeric\" value=\"${it.amount || 10000}\">`;\n  if (it.kind === 'quiz') return `<div class=\"row\" style=\"gap:10px\">\n    <div class=\"grow\"><label class=\"fl\">题量</label><input class=\"input\" id=\"pCount\" type=\"number\" inputmode=\"numeric\" value=\"${it.count || 20}\"></div>\n    <div class=\"grow\"><label class=\"fl\">达标正确率 %</label><input class=\"input\" id=\"pRatio\" type=\"number\" inputmode=\"numeric\" value=\"${it.ratio || 80}\"></div></div>`;\n  if (it.kind === 'gift') return `<div class=\"row\" style=\"gap:10px\">\n    <div class=\"grow\"><label class=\"fl\">礼物名</label><input class=\"input\" id=\"pGift\" value=\"${esc(it.gift || '')}\"></div>\n    <div class=\"grow\" style=\"max-width:120px\"><label class=\"fl\">价格</label><input class=\"input\" id=\"pPrice\" type=\"number\" inputmode=\"numeric\" value=\"${it.price || 199}\"></div></div>`;\n  if (it.kind === 'txt') return `<label class=\"fl\">要抄写的内容</label><textarea id=\"pTxt\" placeholder=\"例如：想清楚再开始，比开始了再想更快。\">${esc(it.text || '')}</textarea>\n    <label class=\"fl\">抄几遍</label><input class=\"input\" id=\"pCount\" type=\"number\" inputmode=\"numeric\" value=\"${it.count || 1}\">`;\n  if (it.kind === 'essay') return `<label class=\"fl\">最少字数</label><input class=\"input\" id=\"pMinWords\" type=\"number\" inputmode=\"numeric\" value=\"${it.minWords || 200}\">\n    <div class=\"tiny mt6\">写作要求用下面的「说明」写，会显示在惩罚页上。</div>`;\n  if (it.kind === 'act') return `<label class=\"fl\">要做的事</label><input class=\"input\" id=\"pAct\" value=\"${esc(it.actName || '')}\" placeholder=\"例如：喝一杯温水，再做 20 个深蹲\">`;\n  return `<div class=\"row\" style=\"gap:10px\">\n    <div class=\"grow\"><label class=\"fl\">总时长（分钟）</label><input class=\"input\" id=\"pChkMin\" type=\"number\" inputmode=\"numeric\" value=\"${it.checkinMin || 20}\"></div>\n    <div class=\"grow\"><label class=\"fl\">间隔（分钟）</label><input class=\"input\" id=\"pChkGap\" type=\"number\" inputmode=\"numeric\" value=\"${it.checkinGap || 5}\"></div>\n    <div class=\"grow\"><label class=\"fl\">打卡次数</label><input class=\"input\" id=\"pChkCount\" type=\"number\" inputmode=\"numeric\" value=\"${it.checkinCount || 4}\"></div></div>`;\n}\n/* ==========================================================\n   动作 · 专注流程\n   ========================================================== */\nObject.assign(ACTIONS, {\n  startFocus: async () => {\n    const d = S.draft;\n    const charIds = (d.charIds || []).filter(id => charById(id));\n    if (!charIds.length) { toast('请先选择至少一位陪伴角色'); go('roles'); return; }\n    const plan = (d.plan || []).filter(t => t.content && t.content.trim());\n    S.settings.charIds = charIds.slice();\n    S.settings.lastPlan = plan.map(t => ({ content: t.content.trim(), est: Number(t.est) || 0 }));\n    S.settings.focusMin = Number(d.focusMin) || 25;\n    S.settings.breakMin = Number(d.breakMin) || 5;\n    S.settings.cycles = Number(d.cycles) || 1;\n    S.settings.reviewEvery = d.reviewEvery;\n    await saveSettings(true);\n    if (pendingPunish().length) { toast('请先完成未完成的惩罚'); S.lock = { punish: pendingPunish()[0] }; render(); return; }\n    await startSession({ charIds: charIds, focusMin: d.focusMin, breakMin: d.breakMin, cycles: d.cycles, plan: plan, reviewEvery: d.reviewEvery, voiceOn: cfg('voiceMode') !== 'off' });\n  },\n  todoToggle: async el => {\n    const s = S.session, i = Number(el.dataset.i);\n    if (!s || s.status !== 'running') {\n      const ok = await confirmBox('未开启倒计时就标记任务', '你没有启动专注倒计时就直接标记任务，按你设定的规则这属于违规。现在去开倒计时，还是认罚？', '认罚，抽惩罚');\n      if (!ok) { initDraft(); go('setup'); return; }\n      await triggerPunish('未计时开始任务', {}); return;\n    }\n    s.plan[i].done = !s.plan[i].done;\n    pushMsg(s, 'sys', s.plan[i].done ? `✓ 完成：${s.plan[i].content}` : `取消勾选：${s.plan[i].content}`);\n    syncSelfTasksFromPlan(s);                                // TA 的进度跟着你走\n    await saveSession(true); render();\n    if (s.plan[i].done) onTaskDone(s, s.plan[i].content);   // 完成一个任务 → 解锁一张 + 生成下一张\n  },\n  extraToggle: async el => {\n    const s = S.session; if (!s || !s.extraTasks) return;\n    const i = Number(el.dataset.i);\n    const t = s.extraTasks[i];\n    if (!t) return;\n    t.done = !t.done;\n    if (t.done) pushMsg(s, 'sys', '✓ 完成（追加）：' + t.content);\n    syncSelfTasksFromPlan(s);\n    await saveSession(true); render();\n    /* 追加的任务和原清单任务同权：完成一个也解锁一张壁纸、并攒下一张新的 */\n    if (t.done) onTaskDone(s, t.content);\n  },\n  extraAdd: () => {\n    const s = S.session;\n    const lastMin = (s && s.extraLastMin) || 10;      // 记住上次填的分钟数，省得每次重填\n    openSheet(`<h3>临时追加任务</h3>\n      <label class=\"fl\">任务内容</label>\n      <input class=\"input\" id=\"extraTask\" placeholder=\"例如：把错题整理一遍\">\n      <label class=\"fl\">预估要花多久（分钟）</label>\n      <input class=\"input\" id=\"extraMin\" type=\"number\" inputmode=\"numeric\" value=\"${Number(lastMin) || 10}\">\n      <label class=\"tiny mt8\" style=\"display:flex;align-items:center;gap:6px\">\n        <input type=\"checkbox\" id=\"extraAddTime\" ${(s && s.extraAddTime === false) ? '' : 'checked'}>\n        同时把本次专注的倒计时也延长这么多</label>\n      <div class=\"tiny mt6\">不勾就只加一条任务、倒计时照原样走；勾了则任务和专注总时长一起往后延。</div>\n      <div class=\"row mt14\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"extraSave\">添加</button></div>`);\n  },\n  extraSave: async () => {\n    const v = (document.getElementById('extraTask').value || '').trim();\n    if (!v) { toast('请填写内容'); return; }\n    const s = S.session; if (!s) return;\n    const minBox = document.getElementById('extraMin');\n    const min = Math.max(0, Math.round(Number(minBox && minBox.value) || 0));\n    const tooBox = document.getElementById('extraAddTime');\n    const too = tooBox ? !!tooBox.checked : true;\n    s.extraAddTime = too;                 // 记住你的偏好，下次默认跟着走\n    if (min) s.extraLastMin = min;\n    s.extraTasks = s.extraTasks || [];\n    s.extraTasks.push({ content: v, est: min, done: false, at: Date.now() });\n    let msg = '＋ 追加任务：' + v + (min ? '（预估 ' + min + ' 分钟）' : '');\n    if (min && too) {\n      /* 只有专注阶段才动倒计时：休息阶段加任务不该把休息时间拉长 */\n      if (s.phase === 'focus') {\n        s.focusMin = Math.max(1, Number(s.focusMin || 25) + min);\n      s.lockUntil = sessionEndAt(s);\n  syncLockNow();\n        s.lockUntil = sessionEndAt(s);\n  syncLockNow();\n        s.phaseEndsAt = Number(s.phaseEndsAt || Date.now()) + min * 60000;\n        S.lastTick = Date.now();\n        msg += ' · 专注总时长延长 ' + min + ' 分钟（现 ' + s.focusMin + ' 分钟）';\n      } else {\n        msg += ' · 现在是休息阶段，专注总时长未改';\n      }\n    }\n    pushMsg(s, 'sys', msg);\n    await saveSession(true);\n    toast(min && too ? ('已追加任务，专注延长 ' + min + ' 分钟') : '已追加任务');\n    closeAllSheets(); render();\n  },\n  pauseAsk: () => {\n    if (assistLevelFor(S.session) === 'L3') { openLockCooldownSheet(); return; }\n    openSheet(`<h3>暂停专注</h3><div class=\"sub\">主动暂停不算违规，但需要写明原因；暂停期间计时冻结。</div>\n    <textarea id=\"pauseReason\" placeholder=\"例如：去洗手间 / 接水 / 接电话\"></textarea>\n    <div class=\"row mt14\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n    <button class=\"btn primary grow\" data-act=\"doPause\">确认暂停</button></div>`); },\n  doPause: async () => {\n    const r = (document.getElementById('pauseReason').value || '').trim();\n    if (!r) { toast('请写明暂停原因'); return; }\n    const s = S.session; if (!s) return;\n    s.paused = true; s.pausedAt = Date.now(); s.pauseReason = r;\n    pushMsg(s, 'sys', `⏸ 用户主动暂停：${r}`);\n    await saveSession(true); closeAllSheets(); render();\n  },\n  resumeSession: async () => {\n    const s = S.session; if (!s || !s.paused) return;\n    const delta = Date.now() - s.pausedAt;\n    s.phaseEndsAt += delta; s.paused = false; s.pausedAt = 0; s.pauseReason = '';\n    pushMsg(s, 'sys', `▶️ 继续专注（暂停 ${fmtDur(delta / 1000)}）`);\n    S.lastTick = Date.now(); s.justResumed = true;\n    await saveSession(true); render();\n  },\n  skipBreak: async () => { const s = S.session; if (!s || s.phase !== 'break') return; s.phaseEndsAt = Date.now(); await onPhaseEnd(); },\n  abortAsk: async () => {\n    const s = S.session; if (!s) return;\n    const ok = await confirmBox('结束当前阶段？', s.phase === 'break' ? '将跳过休息进入下一轮。' : '将立即进入结束校验流程（填写反馈 → 出题答题）。', '结束');\n    if (!ok) return;\n    if (s.phase === 'focus') s.phaseEndsAt = Date.now();\n    await onPhaseEnd();\n  },\n  skipTask: async () => {\n    const s = S.session; if (!s) return;\n    const i = currentTaskIdx(s);\n    if (i < 0) { toast('本轮任务都完成了'); return; }\n    s.plan[i].done = true;\n    pushMsg(s, 'sys', `✓ 完成：${s.plan[i].content}`);\n    s.curTaskIdx = null; s.curTaskSince = 0; s.taskAsked = false;\n    await saveSession(true); render();\n    onTaskDone(s, s.plan[i].content);      // 完成一个任务 → 解锁一张 + 生成下一张\n    roleSay(s, Math.random() < 0.5 ? 'cheer' : 'nudge');\n  },\n  extendCur: async () => {\n    const s = S.session; if (!s) return;\n    const i = currentTaskIdx(s); if (i < 0) return;\n    s.plan[i].est = Number(s.plan[i].est || 0) + 10;\n    s.curTaskSince = Date.now(); s.taskAsked = false;\n    pushMsg(s, 'sys', `⌛ 「${s.plan[i].content}」延长 10 分钟（现预估 ${s.plan[i].est} 分钟）`);\n    await saveSession(true); toast('任务已延长 10 分钟'); render();\n    await askExtendFocus(s, 10);      // 顺手问一句：本次专注的总时长要不要也一起延\n  },\n  pokeChar: async () => {\n    const s = S.session;\n    if (!s) { toast('先开始一段专注'); return; }\n    if (S.msgBusy) { toast('角色正在输入…'); return; }\n    S.msgBusy = true; toast('让角色说句话…');\n    await roleSay(s, Math.random() < 0.5 ? 'nudge' : 'self');\n    S.msgBusy = false;\n  },\n  voiceSheet: () => {\n    const cur = cfg('voiceMode') || 'cue';\n    const w = openSheet(`<h3>角色提醒的语音形式</h3><div class=\"sub\">语音依赖小手机「设置 → 语音」里配置的服务。</div>\n      <div class=\"mt10\">${VOICE_MODES.map(([k, n]) => `<button class=\"btn block ${cur === k ? 'primary' : 'ghost'} mt6\" data-vm=\"${k}\">${n}</button>`).join('')}</div>`);\n    w.addEventListener('click', async e => {\n      const b = e.target.closest('[data-vm]'); if (!b) return;\n      S.settings.voiceMode = b.dataset.vm;\n      if (S.session) S.session.voiceOn = b.dataset.vm !== 'off';\n      await saveSettings(true); if (S.session) await saveSession(true);\n      closeSheet(w); toast('语音模式已更新'); render();\n    });\n  },\n  /* 专注中点「答疑」→ 去专门的答疑窗口（不再是个小弹层） */\n  openQA: () => {\n    if (S.lock) { ACTIONS.qaAskSheet(); return; }\n    go('qa');\n  },\n  qaAskSheet: () => {\n    const s = S.session;\n    const cid = pickOneChar(s ? s.charIds : null);\n    if (!cid) { toast('还没有角色'); return; }\n    openSheet(`<h3>问 ${esc(charName(cid))}</h3>\n      <div class=\"tiny\">🔒 答疑会存入私密学习记忆库，角色不会把它带进日常对话。</div>\n      <div id=\"qaLog\" class=\"mt10\" style=\"max-height:38vh;overflow-y:auto\"></div>\n      <textarea id=\"qaInput\" placeholder=\"输入你的问题，例如：资料分析的增长率怎么快速算？\"></textarea>\n      <button class=\"btn primary block mt10\" data-act=\"sendQA\">发送</button>`);\n  },\n  sendQA: async () => {\n    const ta = document.getElementById('qaInput');\n    const q = (ta.value || '').trim(); if (!q) return;\n    const log = document.getElementById('qaLog');\n    const s = S.session, cid = pickOneChar(s ? s.charIds : null);\n    log.insertAdjacentHTML('beforeend', `<div class=\"msg me\"><div class=\"bd\">${esc(q)}</div></div>\n      <div class=\"msg\" id=\"qaWait\"><div class=\"bd\"><span class=\"spin\"></span> 正在解答…</div></div>`);\n    log.scrollTop = log.scrollHeight; ta.value = '';\n    let text = '';\n    try { text = await pGen('qa.answer', { question: q }, [cid]); } catch (e) { }\n    const w = document.getElementById('qaWait'); if (w) w.remove();\n    if (!text) log.insertAdjacentHTML('beforeend', `<div class=\"msg\"><div class=\"bd\">回答失败了，请检查 API 配置或稍后重试。</div></div>`);\n    else {\n      log.insertAdjacentHTML('beforeend', `<div class=\"msg\">${charAvatar(charById(cid))}<div class=\"bd\">\n        <div class=\"who\">${esc(charName(cid))} · 私密答疑</div>${esc(text).replace(/\\n/g, '<br>')}</div></div>`);\n      log.scrollTop = log.scrollHeight;\n      await addPrivate('qa', `${q}\\n→ ${text}`, { subject: '答疑', charId: cid });\n      if (s) pushMsg(s, 'sys', '答疑已存入私密学习记忆（角色不会主动提起）');\n      await saveSession();\n    }\n  },\n  genWallpaper: async () => {\n    const s = S.session; if (!s) return;\n    if (s.wallpaperLoading) { toast('正在生成中…'); return; }\n    s.wallpaperError = ''; render();\n    s.wallTarget = (s.walls || []).length + 1;      // 再添一张新的（同样等任务完成才解锁）\n    ensureWall(s, s.wallTarget, s.wallTask || '这段专注');\n  },\n  saveWallpaper: async () => {\n    const s = S.session;\n    if (!s) { toast('还没有专注记录'); return; }\n    if (!canSaveWallpaper()) { toast('完成一个任务后，这张壁纸就能在休息时段下载了'); return; }\n    const url = await unlockableWall(s);\n    if (!url) { toast('这张还在生成中，稍等一下再点'); return; }\n    saveImageAnywhere(url, 'focus_wallpaper_' + dkey() + '.png', '专注壁纸 · ' + dkey(), pickOneChar(s.charIds));\n    toast('已解锁的那张开始下载（共可下载 ' + (s.wallUnlocked || 0) + ' 张）');\n  },\n  sendWallToChat: async () => {\n    const s = S.session;\n    if (!s || !s.wallpaperData) { toast('还没有生成壁纸'); return; }\n    const cid = pickOneChar(s.charIds);\n    const ok = await sendImageCard(cid, s.wallpaperData, '专注壁纸 · ' + dkey());\n    toast(ok ? '已发到聊天室：去那里保存' : '发送失败，请先选择陪伴角色');\n  },\n  genlogOpen: () => go('genlog'),\n  /* ---- 校验流程 ---- */\n  reviewSubmit: async () => {\n    const s = S.session; if (!s) return;\n    if (S.loading) { toast('正在生成题目，请稍等…'); return; }\n    const R = ensureReview();\n    R.feedback = (S.draft.reviewFeedback || '').trim();\n    R.summary = (S.draft.reviewSummary || '').trim();\n    if (!R.summary) { toast('学习总结必填'); return; }\n    const count = Math.max(1, Number(cfg('reviewQuestions') || 3));\n    const cat = guessCat(s);\n    let qs = [];\n    S.loading = 'review'; render();\n    try {\n      qs = await buildQuizSet(count, {\n        charIds: s.charIds,\n        cat: cat || '',\n        srcMix: cfg('quizMixSrc'), kindMix: cfg('quizMixKind'),\n        allowFresh: cfg('reviewSource') !== 'local',\n        context: '任务清单：' + (s.plan.map(t => t.content).join('；') || '无') + '；用户总结：' + R.summary,\n        purpose: '用户刚结束一段专注学习，请按薄弱点出题；新题、错题、题库题按设置比例混合',\n        loading: 'review'\n      });\n    } catch (e) { qs = []; }\n    S.loading = '';\n    if (qs.length) {\n      const added = await saveQuestionsToBank(qs, { src: 'mix', cat: cat || '综合' });\n      if (added) toast('题目已出，其中 ' + added + ' 道新题已存入题库');\n    }\n    if (!qs.length) {\n      /* 既不给出题、题库又是空的 —— 这里原来是死路（点了没反应），现在给出明确的三条出口 */\n      S.draft.reviewErr = (cfg('reviewSource') === 'local')\n        ? '校验来源设成了「只用题库已有的题」，但题库是空的。'\n        : 'AI 出题没有返回可用结果（可能是 API 报错、超时，或返回的题和题库重复），题库里也没有可用的题。';\n      render();\n      toast('这次没能生成题目，看下面的三个选项');\n      return;\n    }\n    S.draft.reviewErr = '';\n    R.questions = qs; R.answers = {}; resetAnsDraft('ans'); R.stage = 'quiz';\n    render();\n  },\n  /* 真的没法校验时的出口：记为完成，但明确不给币、不推进心愿 */\n  reviewSkip: async () => {\n    const s = S.session; if (!s) { toast('没有待校验的专注'); return; }\n    const ok = await confirmBox('跳过这次校验？',\n      '这段专注会记为「完成」，但：不给专注币、不推进 TA 的心愿进度，也不会触发惩罚。\\n\\n'\n      + '这是给你留的出口（题目实在出不来时用），建议先去题库加几道题，下次就能正常校验。', '跳过校验，记为完成');\n    if (!ok) return;\n    const R = ensureReview();\n    const doneN = (s.plan || []).filter(t => t.done).length;\n    s.status = 'passed'; s.skippedReview = true; s.reviewAt = Date.now();\n    s.summary = R.summary || '（本次跳过了校验）';\n    s.quizScore = 0; s.quizTotal = 0;\n    const cid = pickOneChar(s.charIds);\n    await addPublic('task', `专注任务：${doneN}/${s.plan.length} 项完成，时长 ${Math.round((s.totalFocusSec || 0) / 60)} 分钟，校验被跳过`, cid, { sessionId: s.id });\n    await syncTimeline(cid, `${charName(cid)}陪伴的专注结束（校验被跳过）：${doneN}/${s.plan.length} 项任务完成。`, 'focus_skip_review', {});\n    await saveSession(true);\n    R.pass = true; R.rate = 0; R.total = 0; R.right = 0;\n    R.reply = '这次先这样，下次把题补上，我照旧查你。';\n    S.draft.reviewErr = '';\n    toast('已记为完成（未给专注币）');\n    go('reward');\n  },\n  reviewRetry: () => { S.draft.reviewErr = ''; ACTIONS.reviewSubmit(); },\n  /* 在待校验列表里换一条来做 */\n  reviewPick: el => {\n    const t = (S.sessions || []).find(x => String(x.id || x.dbId) === String(el.dataset.id));\n    if (!t) { toast('找不到这条记录'); return; }\n    S.session = t;\n    S.review = null;\n    S.draft.reviewPick = String(el.dataset.id);\n    S.draft.ans = {}; S.draft.pans = {};\n    S.draft.reviewFeedback = ''; S.draft.reviewSummary = ''; S.draft.reviewErr = '';\n    render();\n    window.scrollTo(0, 0);\n  },\n  reviewAgain: () => {\n    const R = ensureReview();\n    R.questions = drawFromBank(Math.max(1, Number(cfg('reviewQuestions') || 3)), { cat: guessCat(S.session) });\n    R.answers = {}; S.draft.ans = {}; R.stage = R.questions.length ? 'quiz' : 'result';\n    render();\n  },\n  reviewDone: async () => {\n    const s = S.session;\n    if (s && s.pendingBreak) { await ACTIONS.nextRound(); return; }     // 每轮校验：先休息，再下一轮\n    S.review = null; S.draft.ans = {}; S.draft.reviewFeedback = ''; S.draft.reviewSummary = '';\n    if (s && s.status === 'running') { startTicking(); go('running'); return; }\n    S.session = null; go('home');\n  },\n  /* 校验通过后，从这里开始休息；休息结束自动进入下一轮专注 */\n  nextRound: async () => {\n    const s = S.session;\n    if (!s) { toast('没有进行中的专注'); return; }\n    if (S.review) S.review.moreRounds = false;\n    const bk = Math.max(1, Number(s.breakMin) || 5);\n    s.pendingBreak = false;\n    s.phase = 'break';\n    s.phaseEndsAt = Date.now() + bk * 60000;\n    s.status = 'running';\n    s.paused = false;\n    pushMsg(s, 'sys', '校验通过 · 开始休息 ' + bk + ' 分钟，休息结束自动进入第 ' + ((s.cycle || 1) + 1) + '/' + s.cycles + ' 轮专注');\n    S.lastTick = Date.now();\n    startTicking();\n    await saveSession(true);\n    go('running');\n  },\n  replayReply: async () => {\n    const R = S.review; if (!R || !R.reply) return;\n    const cid = R.replyChar || pickOneChar(S.session ? S.session.charIds : null);\n    /* 复用优先：通过考核时已经存过这份音频，直接播。\n       引用可能在三处：本次校验对象、当前会话对象、已落库的会话列表。逐个找。 */\n    let ref = R.replyRef || (S.session && S.session.replyRef) || '';\n    if (!ref && S.session) {\n      const s2 = (S.sessions || []).find(x => String(x.id) === String(S.session.id) || String(x.dbId) === String(S.session.dbId));\n      ref = (s2 && s2.replyRef) || '';\n    }\n    if (ref) {\n      const ok0 = await playVoiceRefOnce(ref);\n      if (ok0) return;\n      R.replyRef = '';\n    }\n    const vr = await voiceSay(cid, R.reply, 'reviewFinish', '专注收尾台词');\n    if (vr && vr.ref) R.replyRef = vr.ref;\n    if (!vr || !vr.ok) toast('播放失败，请检查语音配置');\n  },\n  /* 统一提交入口：惩罚练习 / 专注校验 / 壁纸解锁 都走这里 */\n  gradeNow: async () => {\n    try {\n      collectFillAnswers();\n      if (S.lock && S.quiz) { await ACTIONS.submitQuiz(); return; }\n      if (S.unlockQuiz) { await ACTIONS.albumQuizSubmit(); return; }\n      if (S.review && S.review.stage === 'quiz') { await ACTIONS.reviewGrade(); return; }\n      toast('当前没有可提交的答卷');\n    } catch (e) { console.warn(e); toast('判分出错：' + ((e && e.message) || e)); }\n  },\n  pickOpt: el => {\n    const i = Number(el.dataset.i), k = Number(el.dataset.k);\n    const quiz = answerTarget();\n    if (!quiz) { toast('这一屏没有正在作答的题目'); return; }\n    const qx = quizQs(quiz)[i] || null;\n    if (qx && qx.type === 'multi') {\n      /* 多选：点一下切换选中，可以同时选多项 */\n      const cur = normChoiceSet(quiz.answers[i]);\n      const pos = cur.indexOf(k);\n      if (pos >= 0) cur.splice(pos, 1); else cur.push(k);\n      cur.sort((a, b) => a - b);\n      quiz.answers[i] = cur;\n    } else {\n      quiz.answers[i] = k;\n    }\n    S.draft.ans = S.draft.ans || {};\n    S.draft.ans[String(i)] = quiz.answers[i];\n    if (quiz === S.practice) { S.draft.pans = S.draft.pans || {}; S.draft.pans[String(i)] = quiz.answers[i]; }\n    render();\n  }\n});\n/* ==========================================================\n   校验判分与收尾\n   ========================================================== */\nObject.assign(ACTIONS, {\n  reviewGrade: async () => {\n    const R = ensureReview();\n    if (R.stage !== 'quiz') { toast('当前没有待提交的答卷'); return; }\n    collectFillAnswers();\n    Object.keys(S.draft.ans || {}).forEach(k => { R.answers[Number(k)] = S.draft.ans[k]; });\n    const miss = quizMissing(R.questions, R.answers);\n    if (miss.length) { toast('还有 ' + miss.length + ' 题没作答' + (R.questions.some(q => q.type === 'multi') ? '（多选题至少选一项）' : '')); return; }\n    gradeQuiz(R);\n    await bumpMasteryAll(R.questions);          // 题库掌握度：答对累计、答错清零\n    R.pass = R.rate >= Number(cfg('passRatio') || 80);\n    R.weakness = R.questions.filter(q => !q.ok).map(q => ({ point: q.q.slice(0, 18), reason: '本次答错' }));\n    R.advice = R.advice || localAdvice(R);\n    R.reply = R.pass ? '这轮我给你过了，去休息一下。' : '这次没过，按规矩来。';\n    R.replyChar = pickOneChar(S.session ? S.session.charIds : null);\n    R.stage = 'result';\n    if (R.pass) { afterReview(R); go('reward'); return; }\n    render();\n    afterReview(R);\n  },\n  submitQuiz: async () => {\n    const p = S.lock && S.lock.punish, q = S.quiz;\n    if (!p || !q) { toast('没有可提交的答卷'); return; }\n    if (q.graded) { toast('这份答卷已经提交过了'); return; }\n    collectFillAnswers();\n    Object.keys(S.draft.ans || {}).forEach(k => { q.answers[Number(k)] = S.draft.ans[k]; });\n    const miss = quizMissing(q.qs, q.answers);\n    if (miss.length) { toast('还有 ' + miss.length + ' 题没作答'); return; }\n    gradeQuiz(q);\n    q.pass = q.rate >= p.ratio; q.graded = true;\n    for (let i = 0; i < q.qs.length; i++) {\n      const x = q.qs[i]; if (x.ok) continue;\n      const my = q.answers[i];\n      await recordMistake(x, my, '惩罚练习');\n    }\n    const justM = await bumpMasteryAll(q.qs);      // 题库掌握度：答对累计、答错清零\n    if (justM.length) toast('有 ' + justM.length + ' 道题做对满 ' + masteryNeed() + ' 次，已标为掌握');\n    render();\n    if (q.pass) {\n      const right = q.right, total = q.total;\n      S.quiz = null;\n      await genGradeLine(p, right, total);\n      await completePunish(p, '答对 ' + right + '/' + total + '（' + Math.round(right / total * 100) + '%）');\n    }\n  },\n  genPunishQuiz: async () => {\n    const p = S.lock && S.lock.punish;\n    if (!p || S.loading) return;\n    S.quiz = null;\n    if (!S.settings.punishCat) S.settings.punishCat = '';\n    S.loading = 'quiz'; render();\n    let qs = [];\n    let err = '';\n    try {\n      qs = await buildQuizSet(p.count, {\n        charIds: [p.charId],\n        cat: p.cat || cfg('punishCat') || '',\n        srcMix: cfg('quizMixSrc'), kindMix: cfg('quizMixKind'),\n        allowFresh: cfg('quizSource') !== 'local',\n        purpose: '用户正在接受惩罚练习，需要完成 ' + p.count + ' 道题且正确率 ≥ ' + p.ratio + '% 才能解除锁定',\n        context: '惩罚练习题，按他的薄弱点出。新题、错题、题库题按设置的比例混合。',\n        loading: 'quiz'\n      });\n    } catch (e) { err = (e && e.message) || String(e); qs = []; }\n    S.loading = '';\n    if (!qs.length) {\n      render();\n      toast(err ? ('出题失败：' + err + '。可以先把「题目来源」设成 AI 出题，或到题库加几道题') : '题库是空的：请到「题库」加题，或开启 AI 出题');\n      return;\n    }\n    const added = await saveQuestionsToBank(qs.filter(q => q.type !== 'fill' || q.answer || (q.keywords || []).length), { src: 'mix', cat: p.cat || cfg('punishCat') || '综合' });\n    if (added) toast('已补进题库 ' + added + ' 道新题');\n    S.quiz = { qs: qs, answers: {}, graded: false, pass: false };\n    S.draft.ans = {}; render();\n  }\n});\nasync function recordMistake(q, my, src) {\n  let myT = '', rT = '';\n  if (qIsPick(q)) {\n    const idxs = q.type === 'multi' ? normChoiceSet(my) : (my == null || my === '' ? [] : [Number(my)]);\n    myT = idxs.length ? idxs.map(k => 'ABCD'[k] + ' ' + String((q.options || [])[k] || '')).join('　') : '未作答';\n    const right = q.type === 'multi' ? (q.answerIndexes || [q.answerIndex]) : [q.answerIndex];\n    rT = (right || []).map(k => 'ABCD'[k] + ' ' + String((q.options || [])[k] || '')).join('　');\n  } else {\n    myT = String(my || '未作答');\n    rT = qAnswerText(q);\n  }\n  await addPrivate('mistake', `【${src}】${q.q}｜正确答案：${rT}｜我的答案：${myT}`, {\n    subject: '错题', src: src, q: q.q, qType: qtypeOf(q), options: q.options || [],\n    answerIndex: q.answerIndex, answerIndexes: q.answerIndexes || [], answer: q.answer || '', keywords: q.keywords || [],\n    explain: q.explain || '', my: myT, myIdx: qIsPick(q) && q.type !== 'multi' ? Number(my) : null,\n    myIdxes: q.type === 'multi' ? normChoiceSet(my) : []\n  });\n}\nfunction localAdvice(R) {\n  const wrong = R.questions.filter(q => !q.ok);\n  if (!wrong.length) return `这次 ${R.total} 题全对，状态不错，保持这个节奏。`;\n  return `错在 ${wrong.length} 题：${wrong.map(q => q.q.slice(0, 14)).join('；')}。把这几处对应的原文再翻一遍，比多刷十道题更管用。`;\n}\n/* 把错题交给 AI 归纳成知识点（不照抄题目），存进私密记忆与校验记录 */\nasync function classifyWrong(R, cid, s) {\n  const wrongIdx = (R.questions || []).map((q, i) => i).filter(i => !R.questions[i].ok);\n  if (!wrongIdx.length) { R.wGroups = []; R.wSummary = ''; return; }\n  const subject = ((s && s.plan) || []).filter(t => t.content).map(t => t.content).join('、') || R.summary || '（未填）';\n  const wrong = wrongIdx.map((i, k) => {\n    const q = R.questions[i];\n    const right = q.type === 'choice' ? ((q.options || [])[q.answerIndex] || '') : (q.answer || (q.keywords || []).join('/'));\n    const mine = q.type === 'choice' ? ((q.options || [])[R.answers[i]] || '未作答') : (R.answers[i] || '未作答');\n    return (k + 1) + '. 题干：' + String(q.q).slice(0, 70) + '｜正确答案：' + right + '｜他的答案：' + mine;\n  }).join('\\n');\n  let data = null;\n  try {\n    const text = await pGen('review.classify', { subject: subject, wrong: wrong, context: R.summary || '' }, [cid]);\n    data = parseJSON(text);\n  } catch (e) { data = null; }\n  const groups = (data && data.groups ? data.groups : []).map(g => ({\n    point: String(g.point || '').slice(0, 20), level: String(g.level || '').slice(0, 10),\n    why: String(g.why || '').slice(0, 70), tip: String(g.tip || '').slice(0, 70)\n  })).filter(g => g.point).slice(0, 4);\n  if (!groups.length) groups.push({ point: '本次错题集中的内容', level: '会但不熟', why: '这次共错 ' + wrongIdx.length + ' 题', tip: '把这几处的原文再过一遍' });\n  R.wGroups = groups;\n  R.wSummary = (data && data.summary) ? String(data.summary).slice(0, 140) : '';\n}\nlet reviewBusy = false;\nasync function afterReview(R) {\n  const s = S.session; if (!s || reviewBusy) return;\n  reviewBusy = true;\n  try {\n    const cid = R.replyChar || pickOneChar(s.charIds);\n    try { await classifyWrong(R, cid, s); } catch (e) { R.wGroups = R.wGroups || []; }   // 先归纳知识点，再入库\n    for (let i = 0; i < R.questions.length; i++) {\n      const q = R.questions[i]; if (q.ok) continue;\n      await recordMistake(q, R.answers[i], '专注校验');\n    }\n    /* 薄弱点：先让 AI 把错题归纳成知识点再入库，不再直接堆错题原文 */\n    if (R.wGroups && R.wGroups.length) {\n      for (const g of R.wGroups) {\n        await addPrivate('weak', '【' + (g.point || '知识点') + '】' + (g.level ? g.level + ' · ' : '') + (g.why || '') + (g.tip ? '｜怎么补：' + g.tip : ''), {\n          subject: '薄弱点', point: g.point, level: g.level, why: g.why, tip: g.tip, sessionId: s.id, classified: true\n        });\n      }\n    } else {\n      for (const w of (R.weakness || [])) await addPrivate('weak', `${w.point || ''}${w.reason ? '：' + w.reason : ''}`, { subject: '薄弱点', sessionId: s.id });\n    }\n    if (R.pass) s.passedRounds = (s.passedRounds || 0) + 1;\n    const moreRounds = R.pass && s.reviewEvery === 'focus' && (s.cycle || 1) < s.cycles;\n    s.status = moreRounds ? 'review' : (R.pass ? 'passed' : 'failed');\n    R.moreRounds = moreRounds;\n    if (moreRounds) {\n      /* 校验期间不计入专注时间，也不提前开始休息：\n         休息计时从用户点「继续下一轮」那一刻才开始，休息结束再自动开始下一轮 */\n      s.pendingBreak = true; s.paused = false;\n    }\n    s.summary = R.summary; s.feedback = R.feedback; s.advice = R.advice;\n    s.weakness = R.weakness; s.quizScore = R.right; s.quizTotal = R.total; s.reviewAt = Date.now();\n    /* 留一份校验明细：之后可以在「报告与趋势 → 专注校验」里单独点开查看 */\n    s.reviewRound = s.cycle || 1;\n    s.taskName = ((s.plan || []).filter(t => t.content).map(t => t.content).join('、') || '（未设置任务）').slice(0, 80);\n    s.reviewQs = R.questions.map((q, i) => ({\n      q: q.q, type: q.type, options: q.options || [], answerIndex: q.answerIndex,\n      answer: q.answer || '', keywords: q.keywords || [], explain: q.explain || '',\n      ok: !!q.ok, my: (q.type === 'choice' ? ((q.options || [])[R.answers[i]] || '未作答') : (R.answers[i] || '未作答'))\n    })).slice(0, 20);\n    s.weakGroups = R.wGroups || [];\n    const doneN = s.plan.filter(t => t.done).length;\n    const taskText = `专注任务：${doneN}/${s.plan.length} 项完成，时长 ${Math.round((s.totalFocusSec || 0) / 60)} 分钟，状态${R.pass ? '考核通过（完成）' : '考核失败（未完成）'}`;\n    await addPublic('task', taskText, cid, { sessionId: s.id });\n    if (R.summary) await addPublic('summary', `学习总结：${R.summary}`, cid, { sessionId: s.id });\n    await syncTimeline(cid, `${charName(cid)}陪伴的专注结束：${taskText}；用户总结：${R.summary || '（未填）'}`, 'focus_review', { pass: R.pass });\n    if (R.pass) await syncChatLine(cid, `[角色陪伴专注] ${taskText}`);\n    await saveSession(true);\n    if (!R.pass) {\n      const lostMin = Math.round((s.totalFocusSec || (s.focusMin || 0) * 60) / 60);\n      // 连坐：你没通过，你们一起攒的那件事也跟着往后退一截\n      await wishConnectHit(cid, Math.max(1, Math.round(lostMin * wishPenaltyRate() / 100)), '这次考核没过');\n      bumpSelfTasks(s, -25, '你这次考核没过');\n      await settleSelfTasks(s, cid, '考核没过');\n      await coinDeductFor('考核未通过', 'fail');\n      await triggerPunish('考核未通过', {});\n      reviewBusy = false; return;\n    }\n    // 通过：结账专注币 + 把这段专注推进 TA 的心愿，再让角色说收尾台词\n    const mins = Math.round((s.totalFocusSec || (s.focusMin || 0) * 60) / 60);\n    const earn = Math.max(1, Math.round(mins * coinRate() * (1 + coinBonus() / 100)));\n    await coinAdd(earn, '通过考核的专注 ' + mins + ' 分钟');\n    await addWishProgress(cid, mins, '你把 ' + mins + ' 分钟真的交给了他');\n    try {\n      const line = await pGen('review.finish', { summary: R.summary, goal: goalPromptLine() }, [cid]);\n      if (line) {\n        R.reply = line.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n        R.replyChar = cid;\n        if (S.view === 'reward' || S.view === 'review') render();\n        /* 收尾台词的音频后台存一份挂在这次校验上 ——\n           「🔊 再听一遍」直接复用，不重新合成。 */\n        if (shouldSpeak('punish')) {\n          voiceSay(cid, R.reply, 'reviewFinish', '专注收尾台词').then(async vr => {\n            if (!vr || !vr.ref) return;\n            R.replyRef = vr.ref;\n            s.replyRef = vr.ref;          // 写进会话本身，随 saveSession 一起落库\n            await saveSession(true);\n          }).catch(() => { });\n        }\n      }\n    } catch (e) { }\n    const every = Math.max(1, Number(cfg('rewardEveryRounds') || 3));\n    if (s.passedRounds % every === 0) {\n      const rw = await createRewardGift(`通过第 ${s.passedRounds} 轮专注考核`, 0);\n      if (rw) { R.newReward = rw; if (S.view === 'reward') render(); }\n    }\n  } catch (e) { console.warn('afterReview', e); }\n  reviewBusy = false;\n}\n/* ==========================================================\n   动作 · 惩罚\n   ========================================================== */\nObject.assign(ACTIONS, {\n  openLock: () => {\n    const p = pendingPunish()[0];\n    if (!p) { toast('没有未完成的惩罚'); return; }\n    S.lock = { punish: p }; S.quiz = null; render();\n  },\n  replayLine: async () => {\n    const p = S.lock && S.lock.punish;\n    if (!p || !p.line) return;\n    /* 复用优先：宣布惩罚时已经存过一份音频，直接播那份，不重新合成。 */\n    if (p.lineRef) {\n      const ok0 = await playVoiceRefOnce(p.lineRef);\n      if (ok0) return;\n      p.lineRef = '';          // 存的音频取不到了（换设备 / 媒体库被清）→ 清掉坏引用，下面重合成\n      await savePun(p);\n    }\n    const vr = await voiceSay(p.charId || anyCharId(), p.line, 'punish', '惩罚台词');\n    if (vr && vr.ref) { p.lineRef = vr.ref; await savePun(p); }\n    if (!vr || !vr.ok) toast('语音播放失败，请检查语音配置');\n  },\n  doPay: async () => {\n    const p = S.lock && S.lock.punish; if (!p || S.paying) return;\n    let acc = null;\n    try { const w = await API.wallet.get(); acc = ((w && w.accounts) || [])[0] || null; } catch (e) { acc = null; }\n    if (!acc) {\n      const ok = await confirmBox('钱包不可用', '没有读到小手机的钱包账户，无法真实扣款。要改为「仅记账」完成这项惩罚吗？', '仅记账完成');\n      if (!ok) return;\n      await addLedger('pay', p.amount, p.charId, `惩罚转账（仅记账）· ${p.title}`, false);\n      await completePunish(p, `已记账 ¥${Number(p.amount).toLocaleString()}（未真实扣款）`); return;\n    }\n    S.paying = true; render();\n    let r = null;\n    try {\n      r = await API.wallet.pay({ amount: p.amount, accountId: acc.id, title: '角色陪伴专注 · 惩罚', detail: p.title, category: '惩罚', relatedOrderId: 'focus_' + p.id });\n    } catch (e) { r = { ok: false, error: (e && e.message) || '扣款失败' }; }\n    S.paying = false;\n    if (!r || !r.ok) {\n      const err = (r && r.error) || '扣款失败';\n      toast(err);\n      const go2 = await confirmBox('扣款未成功', err + '\\n\\n要改为「仅记账」完成这项惩罚吗？', '仅记账完成');\n      if (!go2) { render(); return; }\n      await addLedger('pay', p.amount, p.charId, `惩罚转账（仅记账）· ${p.title}`, false);\n      await completePunish(p, `已记账 ¥${Number(p.amount).toLocaleString()}（未真实扣款）`); return;\n    }\n    await addLedger('pay', p.amount, p.charId, `惩罚转账 · ${p.title}`, true);\n    await completePunish(p, `已从「${acc.name || '账户'}」真实扣款 ¥${Number(p.amount).toLocaleString()}`);\n  },\n  doGift: async () => {\n    const p = S.lock && S.lock.punish; if (!p || S.paying) return;\n    let acc = null;\n    try { const w = await API.wallet.get(); acc = ((w && w.accounts) || [])[0] || null; } catch (e) { acc = null; }\n    if (!acc) {\n      const ok = await confirmBox('钱包不可用', '没有读到钱包账户，无法真实扣款。要记为「已购买（仅记账）」吗？', '仅记账完成');\n      if (!ok) return;\n      await giftTo(p.charId, p.gift, p.price, { real: false });\n      await completePunish(p, `已赠送「${p.gift}」（未真实扣款）`); return;\n    }\n    S.paying = true; render();\n    let r = null;\n    try { r = await API.wallet.pay({ amount: p.price, accountId: acc.id, title: '角色陪伴专注 · 惩罚礼物', detail: p.gift, category: '惩罚' }); }\n    catch (e) { r = { ok: false, error: (e && e.message) || '扣款失败' }; }\n    S.paying = false;\n    const paid = !!(r && r.ok);\n    if (!paid) {\n      toast((r && r.error) || '扣款失败');\n      const go2 = await confirmBox('扣款未成功', '要记为「已购买（仅记账）」完成这项惩罚吗？', '仅记账完成');\n      if (!go2) { render(); return; }\n    }\n    await giftTo(p.charId, p.gift, p.price, { real: paid });\n    await completePunish(p, `已赠送「${p.gift}」` + (paid ? '（已从钱包扣款）' : '（仅记账）'));\n  },\n  /* ---- 新增惩罚类型的完成流程 ---- */\n  punishTextSubmit: async () => {\n    const p = S.lock && S.lock.punish; if (!p) return;\n    const el = document.getElementById('punTxt');\n    const txt = el ? (el.value || '') : (S.draft.punTxt || '');\n    S.draft.punTxt = txt;\n    const n = txtCount(txt);\n    if (p.kind === 'txt') {\n      const need = txtTarget(p);\n      if (n < need) { toast('还差 ' + (need - n) + ' 字，抄完再提交'); return; }\n      await completePunish(p, '已抄写 ' + n + ' 字（目标 ' + need + '，' + (Number(p.count) || 1) + ' 遍）');\n      return;\n    }\n    const need = Math.max(20, Number(p.minWords) || 200);\n    if (n < need) { toast('还差 ' + (need - n) + ' 字'); return; }\n    await completePunish(p, '已写 ' + n + ' 字的反思');\n  },\n  punishActDone: async () => {\n    const p = S.lock && S.lock.punish; if (!p) return;\n    const ok = await confirmBox('确认已经做完了？', p.actName || p.title || '', '做完了');\n    if (!ok) return;\n    await completePunish(p, '已完成：' + (p.actName || p.title || ''));\n  },\n  punishCheckin: async () => {\n    const p = S.lock && S.lock.punish;\n    if (!p || p.kind !== 'checkin') return;\n    const now = Date.now();\n    if (p.nextAt && now < p.nextAt) { toast('还没到下一次，' + Math.ceil((p.nextAt - now) / 1000) + ' 秒后再点'); return; }\n    const gapMs = Math.max(1, Number(p.checkinGap) || 5) * 60000;\n    const need = Math.max(1, Number(p.checkinCount) || 4);\n    p.checkinDone = (p.checkinDone || 0) + 1;\n    p.checkinAt = (p.checkinAt || []).concat([now]);\n    p.nextAt = now + gapMs;\n    await savePun(p);\n    if (p.checkinDone >= need) { await completePunish(p, '限时打卡完成 ' + p.checkinDone + ' 次'); return; }\n    render(); startLockTick(p);\n    toast('打卡 ' + p.checkinDone + '/' + need + '，' + Math.max(1, Number(p.checkinGap) || 5) + ' 分钟后再来');\n  },\n  /* ---- 惩罚补救 ---- */\n  remedyTaskAsk: el => {\n    const rec = (el && el.dataset && el.dataset.id)\n      ? ((S.puns || []).find(x => String(x.id) === String(el.dataset.id)) || (S.lock && S.lock.punish))\n      : (S.lock && S.lock.punish);\n    if (!rec) { toast('找不到这次惩罚'); return; }\n    remedyTaskAsk(rec);\n  },\n  remedyTaskSave: async el => {\n    const rec = (S.puns || []).find(x => String(x.id) === String(el.dataset.id)) || (S.lock && S.lock.punish);\n    if (!rec) return;\n    const v = ((document.getElementById('remedyTask') || {}).value || '').trim();\n    if (!v) { toast('先选一件或写一件要做的事'); return; }\n    rec.remedy = { type: 'task', text: v.slice(0, 80), at: Date.now() };\n    await savePun(rec);\n    closeAllSheets();\n    if (S.lock) { S.lock.punish = rec; }\n    toast('补救任务已记下 —— 做完点「我做完了」');\n    render();\n  },\n  remedyTaskDone: async el => {\n    const rec = (S.puns || []).find(x => String(x.id) === String(el.dataset.id)) || (S.lock && S.lock.punish);\n    if (!rec) return;\n    const text = (rec.remedy && rec.remedy.text) || '这件事';\n    const ok = await confirmBox('确认做完了？', '「' + text + '」\\n\\n确认后这次扣款免掉、限制解除。没做完就别点。', '做完了，免掉扣款');\n    if (!ok) return;\n    const cid = rec.charId || anyCharId();\n    rec.remedy.doneAt = Date.now();\n    await savePun(rec);\n    if (cid) {\n      await syncTimeline(cid, `用户没有直接付钱，而是用完成任务来补救上次的惩罚（${rec.title}）：他做完了「${text}」。`, 'punish_remedy', {});\n      await addPublic('remedy', charName(cid) + '：你没花钱，但你做完了「' + text + '」', cid, {});\n      await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: '[惩罚补救] 用户选择用完成一件事来补救「' + rec.title + '」，他做完了：' + text }), null);\n    }\n    await completePunish(rec, '以完成任务补救：' + text);\n  },\n  remedyAppt: async el => {\n    const rec = (S.puns || []).find(x => String(x.id) === String(el.dataset.id)) || (S.lock && S.lock.punish);\n    if (!rec) return;\n    await remedyApptDo(rec);\n  },\n  buyGiftFree: () => {\n    openSheet(`<h3>送一件礼物给角色</h3>\n      <div class=\"tiny\">这是你主动送的，会记为你的支出。</div>\n      <label class=\"fl\">礼物名称</label><input class=\"input\" id=\"giftName\" placeholder=\"如：一束向日葵\">\n      <button class=\"btn primary block mt14\" data-act=\"giftPick\">送出</button>`);\n  },\n  giftPick: async () => {\n    const g = (document.getElementById('giftName').value || '').trim();\n    if (!g) { toast('请填写礼物名称'); return; }\n    await giftTo(anyCharId(), g, 99, { real: false });\n    closeAllSheets(); toast('已送出：' + g); render();\n  }\n});\nfunction pickGiftEmoji(name) {\n  const n = String(name || '');\n  if (/花/.test(n)) return '🌻';\n  if (/蛋糕|甜|点心/.test(n)) return '🍰';\n  if (/奶茶|咖啡/.test(n)) return '🧋';\n  if (/书|笔/.test(n)) return '📖';\n  if (/包/.test(n)) return '👜';\n  if (/戒指|项链|首饰/.test(n)) return '💍';\n  if (/游戏|机/.test(n)) return '🎮';\n  if (/音乐|唱片|专辑/.test(n)) return '🎧';\n  if (/围巾/.test(n)) return '🧣';\n  if (/外卖|夜宵/.test(n)) return '🍜';\n  return '🎁';\n}\nasync function giftTo(charId, name, price, opt) {\n  opt = opt || {};\n  const from = opt.from === 'char' ? 'char' : 'me';\n  const rec = { name: name, price: Number(price) || 0, emoji: pickGiftEmoji(name), charId: charId || '', at: Date.now(), real: !!opt.real, from: from };\n  const r = await DB.create(T.GIFT, rec);\n  if (r) S.gifts.unshift(Object.assign({ id: r.id }, rec));\n  if (from === 'char') { await syncTimeline(charId, `${charName(charId)}送了用户一件礼物：${name}。`, 'gift_from_char', {}); return rec; }\n  await addLedger('gift', rec.price, rec.charId, `赠送礼物 · ${name}`, !!opt.real);\n  await syncTimeline(charId, `用户送了${charName(charId)}一份礼物：${name}。`, 'gift', {});\n  return rec;\n}\nasync function addLedger(type, amount, charId, note, real) {\n  const rec = { type: type, amount: Number(amount) || 0, charId: charId || '', note: note || '', at: Date.now(), real: !!real };\n  const r = await DB.create(T.LEDGER, rec);\n  if (r) S.ledger.unshift(Object.assign({ id: r.id }, rec));\n  return rec;\n}\nasync function genGradeLine(p, right, total) {\n  const cid = p.charId || anyCharId(); if (!cid) return;\n  let text = '';\n  try {\n    text = await pGen('punish.grade', { right: right, total: total, rate: Math.round(right / total * 100) }, [cid]);\n  } catch (e) { }\n  if (!text) text = `做完了，${right}/${total}。下次别让我抓到。`;\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  toast(text);\n  if (shouldSpeak('punish')) speak(cid, text);\n  if (S.session) { pushMsg(S.session, 'char', text, { charId: cid }); await saveSession(true); }\n  await syncChatLine(cid, text, 'assistant');\n}\n/* ==========================================================\n   动作 · 壁纸库\n   ========================================================== */\nObject.assign(ACTIONS, {\n  albumOpen: el => { S.draft.albumBig = el.dataset.id; go('album'); },\n  albumFav: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    if (item.locked) { toast('先解锁才能收藏'); return; }\n    openFavPicker({\n      kind: 'image', title: item.title || ('壁纸 · ' + item.date),\n      content: '', ref: item.ref || '', charId: item.charId || '', from: '壁纸库'\n    });\n  },\n  albumClose: () => { S.draft.albumBig = ''; render(); },\n  albumUnlockQuiz: el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    const count = Math.max(1, Number(cfg('albumQuizCount') || 3));\n    const qs = drawFromBank(count, { cat: item.cat || '' });\n    if (!qs.length) { toast('题库是空的：请到「题库」加题，或开启 AI 出题'); return; }\n    S.unlockQuiz = { albumId: item.id, qs: qs, answers: {}, graded: false, pass: false, right: 0, total: 0, rate: 0 };\n    S.draft.ans = {};\n    closeAllSheets(); go('unlockquiz');\n  },\n  albumQuizBack: () => { S.draft.ans = {}; go('album'); },\n  albumQuizAgain: () => {\n    const U = S.unlockQuiz;\n    if (!U) { go('album'); return; }\n    const item = (S.album || []).find(x => String(x.id) === String(U.albumId));\n    if (!item) { go('album'); return; }\n    const qs = drawFromBank(Math.max(1, Number(cfg('albumQuizCount') || 3)));\n    if (!qs.length) { toast('题库是空的'); return; }\n    U.qs = qs; U.answers = {}; U.graded = false; U.pass = false;\n    S.draft.ans = {}; render();\n  },\n  albumQuizCancel: () => { S.unlockQuiz = null; S.draft.ans = {}; go('album'); },\n  albumQuizSubmit: async () => {\n    const U = S.unlockQuiz; if (!U || U.graded) return;\n    collectFillAnswers();\n    Object.keys(S.draft.ans || {}).forEach(k => { U.answers[Number(k)] = S.draft.ans[k]; });\n    const miss = quizMissing(U.qs, U.answers);\n    if (miss.length) { toast('还有 ' + miss.length + ' 题没作答'); return; }\n    gradeQuiz(U);\n    await bumpMasteryAll(U.qs);\n    U.pass = U.rate >= Number(cfg('passRatio') || 80);\n    U.graded = true;\n    const item = (S.album || []).find(x => String(x.id) === String(U.albumId));\n    if (!U.pass || !item) { render(); return; }\n    for (let i = 0; i < U.qs.length; i++) {\n      const q = U.qs[i]; if (q.ok) continue;\n      await recordMistake(q, U.answers[i], '壁纸解锁');\n    }\n    item.unlockType = 'quiz';\n    await unlockAlbumItem(item, '答题 ' + U.right + '/' + U.total);\n    S.unlockQuiz = null; S.draft.ans = {};\n    S.draft.albumBig = item.id;\n    S.draft.albumUnlockedTip = '答题 ' + U.right + '/' + U.total + ' 达标，已解锁';\n    go('album');\n  },\n  albumUnlockTask: el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    const presets = ((cfg('lastPlan') || []).map(t => t.content).filter(Boolean)).slice(0, 4);\n    const w = openSheet(`<h3>完成任务解锁</h3>\n      <div class=\"tiny\">给自己定一件要完成的事，做完回来点「我完成了，解锁」，这张壁纸就归你。</div>\n      ${presets.length ? `<div class=\"chips mt10\">${presets.map(t => `<button class=\"chip\" data-ut=\"${esc(t)}\">${esc(t)}</button>`).join('')}</div>` : ''}\n      <label class=\"fl\">任务内容</label><input class=\"input\" id=\"albumTaskInput\" placeholder=\"例如：把错题本里 5 道题重做一遍\">\n      <div class=\"row mt14\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"albumSetTask\" data-id=\"${esc(item.id)}\">确定，开始做</button></div>`);\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-ut]'); if (!b) return;\n      const inp = document.getElementById('albumTaskInput');\n      if (inp) inp.value = b.dataset.ut;\n      document.querySelectorAll('[data-ut]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  albumSetTask: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    const v = (document.getElementById('albumTaskInput').value || '').trim();\n    if (!v) { toast('请填写要完成的任务'); return; }\n    item.unlockType = 'task'; item.unlockTask = v;\n    if (item.id) await DB.update(T.ALBUM, item.id, JSON.parse(JSON.stringify(Object.assign({}, item, { dataUrl: '' }))));\n    closeAllSheets(); S.draft.albumBig = item.id;\n    toast('任务已记录，做完回来点「我完成了，解锁」');\n    if (S.view !== 'album') { S.unlockQuiz = null; go('album'); } else render();\n  },\n  albumTaskDone: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    const ok = await confirmBox('确认完成了？', `任务：${item.unlockTask || ''}\\n确认后立即解锁这张壁纸。`, '我完成了');\n    if (!ok) return;\n    await unlockAlbumItem(item, '完成任务解锁：' + (item.unlockTask || ''));\n    S.draft.albumBig = item.id;\n    S.draft.albumUnlockedTip = '任务完成，已解锁';\n    go('album');\n  },\n  albumDownload: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    if (item.locked) { toast('先解锁才能保存'); return; }\n    const url = await albumImage(item);\n    saveImageAnywhere(url, (item.title || 'wallpaper') + '_' + item.date + '.png', item.title, item.charId || anyCharId());\n  },\n  albumSendChat: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item) return;\n    if (item.locked) { toast('先解锁才能发送'); return; }\n    const url = await albumImage(item);\n    if (!url) { toast('图片读取失败'); return; }\n    const ok = await sendImageCard(item.charId || anyCharId(), url, item.title || '壁纸');\n    toast(ok ? '已发到聊天室：去那里打开图片保存' : '发送失败，请先选择陪伴角色');\n  },\n  albumSaveHelp: async el => {\n    const item = (S.album || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!item || item.locked) return;\n    const url = await albumImage(item);\n    openSavePanel(url, item.title || '保存图片', (item.title || 'wallpaper') + '_' + item.date + '.png', item.charId || anyCharId());\n  },\n  clearAlbum: async () => {\n    const ok = await confirmBox('清空壁纸库？', '所有壁纸记录与存储的图片都会被删除，不可恢复。', '清空');\n    if (!ok) return;\n    for (const it of (S.album || [])) {\n      if (it.ref) await sdk(() => API.media.delete({ ref: it.ref }));\n      if (it.id) await DB.remove(T.ALBUM, it.id);\n    }\n    S.album = []; toast('已清空壁纸库'); render();\n  }\n});\n/* ==========================================================\n   动作 · 奖励\n   ========================================================== */\nObject.assign(ACTIONS, {\n  toggleRewardKind: async el => {\n    const k = el.dataset.k, arr = rewardKinds().slice(), i = arr.indexOf(k);\n    if (i >= 0) { if (arr.length <= 1) { toast('至少留一种奖励形式'); return; } arr.splice(i, 1); }\n    else arr.push(k);\n    S.settings.rewardKinds = arr; await saveSettings(true); render();\n  },\n  rewardGiveNow: async () => {\n    toast('角色正在准备送你的奖励…');\n    const rec = await createRewardGift('手动领取', 0);\n    if (rec) render();\n  },\n  rewardClaim: async el => {\n    const rec = (S.rewards || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!rec) return;\n    if (rec.claimed) {\n      const open = await confirmBox('这份奖励已经领过了', '凭证：' + (rec.proof || rec.want || '') + '\\n\\n要打开聊天室看看当时的记录吗？', '打开聊天室');\n      if (open) sdk(() => API.chat.openConversation({ characterId: rec.charId || anyCharId() }));\n      return;\n    }\n    await deliverReward(rec);\n  },\n  rewardDismiss: () => { toast('先放着，随时可以回来领'); go('home'); },\n  /* 手动同步：用户自己在聊天室领到了，APP 抓不到原话时用这条 */\n  rewardManual: el => {\n    const rec = (S.rewards || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!rec) return;\n    openSheet(`<h3>TA 已经在聊天室给你了？</h3>\n      <div class=\"tiny\">本版本已经声明 chat.read 权限，正常情况下 APP 会自己把 TA 的回复抓回来；只有抓不到时（比如那条回复还没生成、或权限被关掉）才需要手动贴。</div>\n      <label class=\"fl\">TA 的原话（可留空，只标记为已领取）</label>\n      <textarea id=\"proofBox\" placeholder=\"例如：拿去，别省着花。\">${esc(rec.proof || '')}</textarea>\n      <div class=\"tiny mt6\">金额会从原话里的 ¥数字 自动识别，记进账本「TA 给我的」。</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn ghost grow\" data-act=\"openRewardChat\" data-id=\"${esc(rec.id)}\">打开聊天室</button>\n        <button class=\"btn primary grow\" data-act=\"rewardManualSave\" data-id=\"${esc(rec.id)}\">确认已领取</button></div>`);\n  },\n  rewardManualSave: async el => {\n    const rec = (S.rewards || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!rec) return;\n    const box = document.getElementById('proofBox');\n    const v = box ? (box.value || '').trim() : '';\n    const proof = v || rec.proof || rec.want || '';\n    closeAllSheets();\n    await finishReward(rec, proof, '', { manual: true, skipWall: true });\n  },\n  openRewardChat: el => {\n    const rec = (S.rewards || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!rec) return;\n    sdk(() => API.chat.openConversation({ characterId: rec.charId || anyCharId() }));\n  }\n});\n/* ==========================================================\n   动作 · 错题本\n   ========================================================== */\nObject.assign(ACTIONS, {\n  practiceMistakes: () => {\n    const ms = mistakeQs();\n    if (!ms.length) { toast('错题本里还没有可重做的题'); return; }\n    S.practice = {\n      qs: ms.map(m => normQuestion({ type: m.qType || 'choice', q: m.q, options: m.options, answerIndex: m.answerIndex, answerIndexes: m.answerIndexes, answer: m.answer, keywords: m.keywords, explain: m.explain })),\n      answers: {}, graded: false, pass: false\n    };\n    S.draft.pans = {}; render();\n  },\n  pracPick: el => {\n    const P = S.practice; if (!P) return;\n    const i = Number(el.dataset.i), k = Number(el.dataset.k);\n    const qx = quizQs(P)[i] || null;\n    if (qx && qx.type === 'multi') {\n      const cur = normChoiceSet(P.answers[i]);\n      const pos = cur.indexOf(k);\n      if (pos >= 0) cur.splice(pos, 1); else cur.push(k);\n      cur.sort((a, b) => a - b);\n      P.answers[i] = cur;\n    } else P.answers[i] = k;\n    S.draft.pans = S.draft.pans || {};\n    S.draft.pans[String(i)] = P.answers[i];\n    render();\n  },\n  pracSubmit: () => {\n    const P = S.practice; if (!P || P.graded) return;\n    collectFillAnswers();\n    Object.keys(S.draft.pans || {}).forEach(k => { P.answers[Number(k)] = S.draft.pans[k]; });\n    const miss = P.qs.map((q, i) => i).filter(i => P.answers[i] == null || String(P.answers[i]) === '');\n    if (miss.length) { toast('还有 ' + miss.length + ' 题没作答'); return; }\n    gradeQuiz(P); P.pass = P.rate >= 100; P.graded = true;\n    bumpMasteryAll(P.qs).then(just => {\n      if (just.length) { toast('有 ' + just.length + ' 道题做对满 ' + masteryNeed() + ' 次，已标为掌握'); render(); }\n    });\n    render();\n  },\n  pracMastered: async () => {\n    const P = S.practice; if (!P) return;\n    let n = 0;\n    for (let i = 0; i < P.qs.length; i++) {\n      if (!P.qs[i].ok) continue;\n      const hit = mistakeList().find(m => m.q && norm(m.q) === norm(P.qs[i].q));\n      if (hit) { await DB.remove(T.PRIV, hit.id); S.priv = S.priv.filter(x => String(x.id) !== String(hit.id)); n++; }\n    }\n    S.practice = null; toast('已移出 ' + n + ' 道掌握的错题'); render();\n  },\n  pracExit: () => { S.practice = null; render(); },\n  delMistake: async el => {\n    await DB.remove(T.PRIV, el.dataset.id);\n    S.priv = S.priv.filter(x => String(x.id) !== String(el.dataset.id));\n    toast('已移出错题本'); render();\n  },\n  /* ---- 错题：备注要点 ---- */\n  mNote: el => {\n    const m = mistakeList().find(x => String(x.id) === String(el.dataset.id));\n    if (!m) return;\n    openSheet(`<h3>📝 这题的要点</h3>\n      <div class=\"tiny\">写给自己看的：错在哪、下次怎么避免、要记住的那一句话。角色看不到这里。</div>\n      <div class=\"tiny mt8\" style=\"line-height:1.6;background:var(--card2);border-radius:10px;padding:9px\">${esc(String(m.q || m.content || '').slice(0, 120))}</div>\n      <textarea id=\"mNoteBox\" style=\"min-height:130px;margin-top:8px\" placeholder=\"例如：搞混的是「同比」和「环比」——同比是跟去年同期比，环比是跟上个月比。下次先看清问题问的是哪一个。\">${esc(m.note || '')}</textarea>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"mNoteSave\" data-id=\"${esc(m.id)}\">保存要点</button></div>`);\n  },\n  mNoteSave: async el => {\n    const m = mistakeList().find(x => String(x.id) === String(el.dataset.id));\n    if (!m) return;\n    const v = ((document.getElementById('mNoteBox') || {}).value || '').trim();\n    m.note = v; m.noteAt = Date.now();\n    const copy = JSON.parse(JSON.stringify(m));\n    await DB.update(T.PRIV, m.id, copy);\n    closeAllSheets(); toast(v ? '要点已保存' : '已清空要点'); render();\n  },\n  /* ---- 错题：文件夹分类 ---- */\n  mFolderNew: () => {\n    openSheet(`<h3>新建错题文件夹</h3>\n      <label class=\"fl\">名字</label><input class=\"input\" id=\"mFolderName\" placeholder=\"例如：资料分析 / 英语语法 / 常错公式\">\n      <div class=\"tiny mt6\">建好之后可以在每道错题上点「分类」放进去，也能按文件夹筛选。</div>\n      <button class=\"btn primary block mt12\" data-act=\"mFolderNewSave\">创建</button>`);\n  },\n  mFolderNewSave: async () => {\n    const n = ((document.getElementById('mFolderName') || {}).value || '').trim();\n    if (!n) { toast('请填一个名字'); return; }\n    const arr = (cfg('mistakeFolders') || []).slice();\n    if (arr.indexOf(n) >= 0) { toast('已经有这个文件夹了'); return; }\n    S.settings.mistakeFolders = arr.concat([n]);\n    await saveSettings(true);\n    closeAllSheets(); toast('已新建：' + n); render();\n  },\n  mFolderAsk: el => {\n    const m = mistakeList().find(x => String(x.id) === String(el.dataset.id));\n    if (!m) return;\n    const arr = (cfg('mistakeFolders') || []).slice();\n    openSheet(`<h3>这题归到哪一类</h3>\n      <div class=\"chips mt10\">\n        <button class=\"chip ${!m.folder ? 'on' : ''}\" data-mf=\"\">不分类</button>\n        ${arr.map(f => `<button class=\"chip ${m.folder === f ? 'on' : ''}\" data-mf=\"${esc(f)}\">📁 ${esc(f)}</button>`).join('')}\n      </div>\n      ${arr.length ? '' : '<div class=\"tiny mt10\">还没有文件夹，点下面新建一个。</div>'}\n      <button class=\"btn sm ghost block mt10\" data-act=\"mFolderNew\">＋ 新建文件夹</button>\n      <button class=\"btn primary block mt8\" data-act=\"mFolderSave\" data-id=\"${esc(m.id)}\">保存分类</button>`);\n    S.draft.mFolderPick = m.folder || '';\n    const w = modalStack[modalStack.length - 1];\n    if (w) w.addEventListener('click', e => {\n      const b = e.target.closest('[data-mf]'); if (!b) return;\n      S.draft.mFolderPick = b.dataset.mf;\n      w.querySelectorAll('[data-mf]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  mFolderSave: async el => {\n    const m = mistakeList().find(x => String(x.id) === String(el.dataset.id));\n    if (!m) return;\n    m.folder = S.draft.mFolderPick || '';\n    await DB.update(T.PRIV, m.id, JSON.parse(JSON.stringify(m)));\n    closeAllSheets(); toast(m.folder ? '已归到「' + m.folder + '」' : '已取消分类'); render();\n  },\n  mFilter: el => { S.draft.mFilter = el.dataset.v || 'all'; S.draft.mSel = {}; render(); },\n  /* ---- 错题：批量选择 ---- */\n  mBatch: () => { S.draft.mSelMode = !S.draft.mSelMode; S.draft.mSel = {}; render(); },\n  mPick: el => {\n    const id = String(el.dataset.id);\n    S.draft.mSel = S.draft.mSel || {};\n    if (S.draft.mSel[id]) delete S.draft.mSel[id]; else S.draft.mSel[id] = 1;\n    render();\n  },\n  mSelectAll: () => {\n    const filter = S.draft.mFilter || 'all';\n    const list = mistakeList();\n    const shown = filter === 'all' ? list : (filter === 'none' ? list.filter(m => !m.folder) : list.filter(m => m.folder === filter));\n    const cur = S.draft.mSel || {};\n    if (Object.keys(cur).length && Object.keys(cur).length >= shown.length) S.draft.mSel = {};\n    else { const m = {}; shown.forEach(x => { m[String(x.id)] = 1; }); S.draft.mSel = m; }\n    render();\n  },\n  mDelSel: async () => {\n    const sel = S.draft.mSel || {};\n    const items = mistakeList().filter(m => sel[String(m.id)]);\n    if (!items.length) { toast('还没选错题'); return; }\n    const ok = await confirmBox('删除选中的错题？', '将删除 ' + items.length + ' 条（含它们的备注），删掉后不可恢复。', '删除 ' + items.length + ' 条');\n    if (!ok) return;\n    for (const m of items) if (m.id) await DB.remove(T.PRIV, m.id);\n    S.priv = (S.priv || []).filter(x => items.indexOf(x) < 0);\n    S.draft.mSel = {}; S.draft.mSelMode = false;\n    toast('已删除 ' + items.length + ' 条'); render();\n  },\n  mMoveSel: async el => {\n    const f = el.dataset.v || '';\n    const sel = S.draft.mSel || {};\n    const items = mistakeList().filter(m => sel[String(m.id)]);\n    if (!items.length) { toast('还没选错题'); return; }\n    for (const m of items) { m.folder = f; await DB.update(T.PRIV, m.id, JSON.parse(JSON.stringify(m))); }\n    S.draft.mSel = {};\n    toast(f ? '已把 ' + items.length + ' 条归到「' + f + '」' : '已取消这 ' + items.length + ' 条的分类');\n    render();\n  },\n  pushMistakesToBank: async () => {\n    const ms = mistakeQs();\n    if (!ms.length) { toast('没有可入库的错题'); return; }\n    const qs = ms.map(m => normQuestion({ type: m.qType || 'choice', q: m.q, options: m.options, answerIndex: m.answerIndex, answerIndexes: m.answerIndexes, answer: m.answer, keywords: m.keywords, explain: m.explain }));\n    const added = await saveQuestionsToBank(qs, { src: 'mistake', cat: guessCat(S.session) || '综合' });\n    toast('已存入题库 ' + added + ' 道（重复的会跳过）'); render();\n  },\n  delPriv: async el => {\n    await DB.remove(T.PRIV, el.dataset.id);\n    S.priv = S.priv.filter(x => String(x.id) !== String(el.dataset.id));\n    render();\n  }\n});\n/* ==========================================================\n   动作 · 题库\n   ========================================================== */\n/* ---------- 题库：查找、改分类、批量移动、重置掌握度 ---------- */\nfunction bankFind(idOrI) {\n  const all = allBank();\n  return all.find(q => String(q.id) === String(idOrI))\n    || all[Number(idOrI)] || null;\n}\nfunction bankSelItems() {\n  const sel = (S.draft && S.draft.bankSel) || {};\n  return Object.keys(sel).map(k => bankFind(k)).filter(Boolean);\n}\nasync function bankSaveRec(q) {\n  if (!q || !q.id) return;\n  await DB.update(T.QBANK, q.id, JSON.parse(JSON.stringify(q)));\n}\nObject.assign(ACTIONS, {\n  bankAddToggle: () => { S.draft.qAddOpen = !S.draft.qAddOpen; render(); },\n  /* ---- 出题配比面板：来源占比 / 题型占比 / 掌握度阈值 / 惩罚分类 ---- */\n  quizMixOpen: () => {\n    const src = Object.assign({ fresh: 1, wrong: 1, bank: 1 }, cfg('quizMixSrc') || {});\n    const kind = Object.assign({ choice: 1, fill: 1, multi: 1, tf: 1 }, cfg('quizMixKind') || {});\n    const cats = bankCats();\n    const cat = cfg('punishCat') || '';\n    openSheet(`<h3>⚙️ 出题配比</h3>\n      <div class=\"tiny\">按占比凑出一份卷子：先按「来源」分题量，再按「题型」配比挑题。数字是权重，不是必须的题量 —— 总共出几道题由各处的设置决定（校验题量 / 惩罚题量）。</div>\n      <label class=\"fl\">① 题目来源占比（新题 / 错题 / 题库题）</label>\n      <div class=\"row\" style=\"gap:8px\">\n        ${[['fresh', '🆕 新题（AI 现出）'], ['wrong', '📕 错题（错题本）'], ['bank', '📚 题库题']].map(([k, n]) => `<div class=\"grow\"><div class=\"tiny\">${n}</div>\n          <input class=\"input mt6\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.quizMixSrc.${k}\" data-num=\"1\" value=\"${Number(src[k] || 0)}\"></div>`).join('')}\n      </div>\n      <div class=\"tiny mt6\">现在：${esc(mixText(src))}</div>\n      <div class=\"row mt6\" style=\"gap:6px\"><button class=\"btn sm ghost grow\" data-act=\"quizMixPreset\" data-v=\"even\">三等分（各 1/3）</button>\n        <button class=\"btn sm ghost grow\" data-act=\"quizMixPreset\" data-v=\"fresh\">多出新题</button>\n        <button class=\"btn sm ghost grow\" data-act=\"quizMixPreset\" data-v=\"wrong\">多练错题</button></div>\n      <label class=\"fl\">② 题型占比（单选 / 多选 / 判断 / 填空）</label>\n      <div class=\"row wrap\" style=\"gap:8px\">\n        ${Q_TYPES.map(([k, n]) => `<div class=\"grow\" style=\"min-width:66px\"><div class=\"tiny\">${n}</div>\n          <input class=\"input mt6\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.quizMixKind.${k}\" data-num=\"1\" value=\"${Number(kind[k] || 0)}\"></div>`).join('')}\n      </div>\n      <div class=\"tiny mt6\">现在：${esc(mixText(kind))}（某题型权重填 0 = 不出这种题）</div>\n      <label class=\"fl\">③ 做对几次算「已掌握」（掌握度阈值）</label>\n      <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.masteryNeed\" data-num=\"1\" value=\"${masteryNeed()}\">\n      <div class=\"tiny mt6\">题库里每道题都记着做对次数：做对累计到 ${masteryNeed()} 次就标为「已掌握」，答错会清零重来。抽题时<b>优先抽没掌握的</b>，所以掌握度直接影响这道题以后还出不出现。</div>\n      <label class=\"fl\">④ 惩罚练习抽哪个分类的题</label>\n      <div class=\"chips mt6\">\n        <button class=\"chip ${!cat ? 'on' : ''}\" data-act=\"punishCatPick\" data-v=\"\">全部分类</button>\n        ${cats.map(c => `<button class=\"chip ${String(cat) === String(c) ? 'on' : ''}\" data-act=\"punishCatPick\" data-v=\"${esc(c)}\">📁 ${esc(c)}（${bankCountIn(c)}）</button>`).join('')}\n      </div>\n      <div class=\"tiny mt6\">题库共 ${allBank().length} 道 · 已掌握 ${allBank().filter(q => isMastered(q)).length} 道 · 待掌握 ${allBank().filter(q => !isMastered(q)).length} 道</div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn grow\" data-act=\"mixGoBank\">去题库管理</button>\n        <button class=\"btn primary grow\" data-act=\"closeSheet\">完成</button></div>`);\n  },\n  mixGoBank: () => { closeAllSheets(); go('qbank'); window.scrollTo(0, 0); },\n  quizMixPreset: async el => {\n    const v = el.dataset.v;\n    if (v === 'fresh') S.settings.quizMixSrc = { fresh: 3, wrong: 1, bank: 1 };\n    else if (v === 'wrong') S.settings.quizMixSrc = { fresh: 1, wrong: 3, bank: 1 };\n    else S.settings.quizMixSrc = { fresh: 1, wrong: 1, bank: 1 };\n    await saveSettings(true);\n    toast('配比已设为：' + mixText(S.settings.quizMixSrc));\n    closeAllSheets(); ACTIONS.quizMixOpen();\n  },\n  punishCatPick: async el => {\n    S.settings.punishCat = el.dataset.v || '';\n    await saveSettings(true);\n    toast(S.settings.punishCat ? ('惩罚练习只抽「' + S.settings.punishCat + '」的题') : '惩罚练习抽全部分类的题');\n    closeAllSheets(); ACTIONS.quizMixOpen();\n  },\n  /* 惩罚锁定页里直接换分类（不弹弹层，就地在锁定页上换） */\n  punishCatPickLock: async el => {\n    S.settings.punishCat = el.dataset.v || '';\n    await saveSettings(true);\n    toast(S.settings.punishCat ? ('这次抽「' + S.settings.punishCat + '」分类的题') : '这次抽全部分类的题');\n    render();\n  },\n  quizMixOpenFromLock: () => { ACTIONS.quizMixOpen(); },\n  addBank: async () => {\n    const d = S.draft, q = (d.qText || '').trim();\n    if (!q) { toast('请填写题干'); return; }\n    const kind = (d.qKind === 'fill' || d.qKind === 'multi' || d.qKind === 'tf') ? d.qKind : 'choice';\n    const cat = d.qCat != null ? String(d.qCat) : (guessCat(S.session) || '综合');\n    const rec = { type: kind, q: q, explain: (d.qExplain || '').trim(), cat: cat, src: 'manual', at: Date.now(), right: 0, wrong: 0, mastered: false };\n    if (kind === 'fill') {\n      rec.answer = (d.qAnswer || '').trim();\n      rec.keywords = (d.qKeywords || '').split(/[,，、]/).map(s => s.trim()).filter(Boolean);\n      if (!rec.answer && !rec.keywords.length) { toast('填空题需要答案或关键词'); return; }\n    } else {\n      let opts = (d.qOpts || '').split('\\n').map(s => s.trim()).filter(Boolean).slice(0, 5);\n      if (kind === 'tf' && opts.length < 2) opts = ['正确', '错误'];\n      if (opts.length < 2) { toast('至少 2 个选项（判断题可留空，会自动用「正确 / 错误」）'); return; }\n      rec.options = opts;\n      if (kind === 'multi') {\n        const picked = (d.qAnsMul || []).map(k => 'ABCD'.indexOf(k)).filter(k => k >= 0 && k < opts.length);\n        if (picked.length < 2) { toast('多选题至少选 2 个正确选项'); return; }\n        rec.answerIndexes = Array.from(new Set(picked)).sort((a, b) => a - b);\n        rec.answerIndex = rec.answerIndexes[0];\n      } else {\n        rec.answerIndex = Math.max(0, Math.min(opts.length - 1, 'ABCD'.indexOf(d.qAns || 'A')));\n      }\n    }\n    const r = await DB.create(T.QBANK, rec);\n    if (r) S.qbank.unshift(Object.assign({ id: r.id }, rec));\n    if (cat && bankCats().indexOf(cat) < 0) S.settings.bankCats = (cfg('bankCats') || []).concat([cat]);\n    S.draft.qText = ''; S.draft.qOpts = ''; S.draft.qAnswer = ''; S.draft.qKeywords = ''; S.draft.qExplain = ''; S.draft.qAnsMul = [];\n    saveSettings();\n    toast('已加入题库' + (cat ? '（分类：' + cat + '）' : '')); render();\n  },\n  qAnsMulPick: el => {\n    const k = el.dataset.v;\n    const arr = (S.draft.qAnsMul || []).slice();\n    const i = arr.indexOf(k);\n    if (i >= 0) arr.splice(i, 1); else arr.push(k);\n    S.draft.qAnsMul = arr;\n    render();\n  },\n  delBank: async el => {\n    await DB.remove(T.QBANK, el.dataset.id);\n    S.qbank = S.qbank.filter(q => String(q.id) !== String(el.dataset.id));\n    S.draft.bankSel = {};\n    render();\n  },\n  /* ---- 分类管理 ---- */\n  bankCatFilter: el => { S.draft.qCatFilter = el.dataset.v || 'all'; S.draft.bankSel = {}; render(); },\n  bankCatNew: () => {\n    openSheet(`<h3>新建题库分类</h3>\n      <div class=\"tiny\">分类就是知识点，比如「资料分析」「英语语法」「常错公式」。题目可以批量归到某个分类，惩罚练习也能只抽某一类。</div>\n      <label class=\"fl\">分类名</label><input class=\"input\" id=\"bankCatName\" placeholder=\"例如：资料分析\">\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"bankCatNewSave\">创建</button></div>`);\n  },\n  bankCatNewSave: async () => {\n    const n = ((document.getElementById('bankCatName') || {}).value || '').trim();\n    if (!n) { toast('请填一个分类名'); return; }\n    const arr = (cfg('bankCats') || []).slice();\n    if (arr.indexOf(n) >= 0) { toast('已经有这个分类了'); return; }\n    S.settings.bankCats = arr.concat([n]);\n    await saveSettings(true);\n    closeAllSheets();\n    S.draft.qCatFilter = n;\n    toast('已新建分类：' + n); render();\n  },\n  bankCatManage: () => {\n    const cats = bankCats();\n    openSheet(`<h3>⚙️ 管理分类（${cats.length}）</h3>\n      <div class=\"tiny\">改名会同步改掉这个分类下所有题目的分类。删分类只是把题目变回「未分类」，题目本身不会丢。</div>\n      <div class=\"mt10\">${cats.length ? cats.map(c => `<div class=\"item\" style=\"padding:9px 0\">\n        <div class=\"ic\">📁</div>\n        <div class=\"grow\"><input class=\"input\" style=\"padding:7px 9px;font-size:13px\" id=\"bc_${esc(c)}\" value=\"${esc(c)}\">\n          <div class=\"tiny mt6\">${bankCountIn(c)} 道题</div></div>\n        <button class=\"btn sm ghost\" data-act=\"bankCatRen\" data-v=\"${esc(c)}\">改名</button>\n        <button class=\"btn sm ghost\" data-act=\"bankCatDel\" data-v=\"${esc(c)}\">删</button></div>`).join('')\n        : `<div class=\"tiny\">还没有分类。点下面的「新建」加一个。</div>`}</div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn grow\" data-act=\"bankCatNew\">＋ 新建分类</button>\n        <button class=\"btn primary grow\" data-act=\"closeSheet\">关闭</button></div>`);\n  },\n  bankCatRen: async el => {\n    const old = el.dataset.v;\n    const box = document.getElementById('bc_' + old);\n    const nv = box ? (box.value || '').trim() : '';\n    if (!nv) { toast('名字不能空'); return; }\n    if (nv !== old && bankCats().indexOf(nv) >= 0) { toast('已经有这个分类了'); return; }\n    S.settings.bankCats = (cfg('bankCats') || []).map(c => (c === old ? nv : c));\n    if (String(S.draft.qCatFilter) === String(old)) S.draft.qCatFilter = nv;\n    if (String(cfg('punishCat')) === String(old)) S.settings.punishCat = nv;\n    for (const q of allBank()) {\n      if (String(q.cat || '') !== String(old)) continue;\n      q.cat = nv; await bankSaveRec(q);\n    }\n    await saveSettings(true);\n    toast('已改名：' + old + ' → ' + nv);\n    closeAllSheets(); ACTIONS.bankCatManage();\n  },\n  bankCatDel: async el => {\n    const c = el.dataset.v;\n    const n = bankCountIn(c);\n    const ok = await confirmBox('删除分类「' + c + '」？', n ? ('这个分类下的 ' + n + ' 道题会变成「未分类」，题目不会丢。') : '这个分类下没有题目。', '删除分类');\n    if (!ok) return;\n    S.settings.bankCats = (cfg('bankCats') || []).filter(x => x !== c);\n    if (String(S.draft.qCatFilter) === String(c)) S.draft.qCatFilter = 'all';\n    if (String(cfg('punishCat')) === String(c)) S.settings.punishCat = '';\n    for (const q of allBank()) {\n      if (String(q.cat || '') !== String(c)) continue;\n      q.cat = ''; await bankSaveRec(q);\n    }\n    await saveSettings(true);\n    toast('已删除分类：' + c);\n    closeAllSheets(); ACTIONS.bankCatManage();\n  },\n  bankEditCat: el => {\n    const q = bankFind(el.dataset.id);\n    if (!q) return;\n    const cats = bankCats();\n    openSheet(`<h3>这题归到哪一类</h3>\n      <div class=\"tiny mt6\" style=\"line-height:1.6;background:var(--card2);border-radius:10px;padding:9px\">${esc(String(q.q || '').slice(0, 100))}</div>\n      <div class=\"chips mt10\">\n        <button class=\"chip ${!q.cat ? 'on' : ''}\" data-bc=\"\">不分类</button>\n        ${cats.map(c => `<button class=\"chip ${String(q.cat || '') === String(c) ? 'on' : ''}\" data-bc=\"${esc(c)}\">📁 ${esc(c)}</button>`).join('')}\n      </div>\n      <button class=\"btn sm ghost block mt10\" data-act=\"bankCatNew\">＋ 新建分类</button>\n      <button class=\"btn primary block mt12\" data-act=\"bankEditCatSave\" data-id=\"${esc(q.id)}\">保存分类</button>`);\n    S.draft.bankCatPick = q.cat || '';\n    const w = modalStack[modalStack.length - 1];\n    if (w) w.addEventListener('click', e => {\n      const b = e.target.closest('[data-bc]'); if (!b) return;\n      S.draft.bankCatPick = b.dataset.bc;\n      w.querySelectorAll('[data-bc]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  bankEditCatSave: async el => {\n    const q = bankFind(el.dataset.id);\n    if (!q) return;\n    q.cat = S.draft.bankCatPick || '';\n    await bankSaveRec(q);\n    closeAllSheets(); toast(q.cat ? '已归到「' + q.cat + '」' : '已取消分类'); render();\n  },\n  bankResetMastery: async el => {\n    const q = bankFind(el.dataset.id);\n    if (!q) return;\n    q.right = 0; q.wrong = 0; q.mastered = false;\n    await bankSaveRec(q);\n    toast('已重置掌握度（做对 0/' + masteryNeed() + ' 次）'); render();\n  },\n  /* ---- 批量选择 / 移动 / 删除 ---- */\n  bankSelect: () => {\n    S.draft.bankSelMode = !S.draft.bankSelMode;\n    S.draft.bankSel = {};\n    render();\n  },\n  bankPick: el => {\n    const k = String(el.dataset.i);\n    S.draft.bankSel = S.draft.bankSel || {};\n    if (S.draft.bankSel[k]) delete S.draft.bankSel[k]; else S.draft.bankSel[k] = 1;\n    render();\n  },\n  bankAll: () => {\n    const filter = S.draft.qCatFilter == null ? 'all' : S.draft.qCatFilter;\n    const all = allBank();\n    const shown = filter === 'all' ? all : (filter === 'none' ? all.filter(q => !q.cat) : all.filter(q => String(q.cat || '') === String(filter)));\n    const cur = S.draft.bankSel || {};\n    const chosen = shown.filter(q => cur[String(q.id)]).length;\n    if (chosen >= shown.length && shown.length) S.draft.bankSel = {};\n    else { const m = {}; shown.forEach(q => { m[String(q.id)] = 1; }); S.draft.bankSel = m; }\n    render();\n  },\n  bankMoveSel: async el => {\n    const cat = el.dataset.v || '';\n    const items = bankSelItems();\n    if (!items.length) { toast('还没选题目'); return; }\n    for (const q of items) { q.cat = cat; await bankSaveRec(q); }\n    if (cat && bankCats().indexOf(cat) < 0) { S.settings.bankCats = (cfg('bankCats') || []).concat([cat]); await saveSettings(true); }\n    S.draft.bankSel = {}; S.draft.bankSelMode = false;\n    toast(cat ? ('已把 ' + items.length + ' 道题移进「' + cat + '」') : ('已取消 ' + items.length + ' 道题的分类'));\n    render();\n  },\n  bankDelSel: async () => {\n    const items = bankSelItems();\n    if (!items.length) { toast('还没选题目'); return; }\n    const ok = await confirmBox('删除选中的题目？', '将删除 ' + items.length + ' 道题，删掉后不可恢复。', '删除 ' + items.length + ' 道');\n    if (!ok) return;\n    for (const q of items) if (q && q.id) await DB.remove(T.QBANK, q.id);\n    S.qbank = (S.qbank || []).filter(q => items.indexOf(q) < 0);\n    S.draft.bankSel = {}; S.draft.bankSelMode = false;\n    toast('已删除 ' + items.length + ' 道题'); render();\n  },\n  importBank: () => {\n    openSheet(`<h3>导入题库</h3><div class=\"tiny\">支持两种格式：<br>1. JSON 数组：[{\"type\":\"choice\",\"q\":\"题干\",\"options\":[\"A\",\"B\"],\"answerIndex\":0}]<br>2. 每行一题：题干|选项A|选项B|选项C|选项D|正确项字母（两段则视为填空题：题干|答案）</div>\n      <textarea id=\"bankText\" style=\"min-height:150px;margin-top:10px\" placeholder=\"粘贴内容\"></textarea>\n      <div class=\"row mt10\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"importBankDo\">导入</button></div>\n      <div class=\"tiny mt10\">也可以选文件：<input type=\"file\" id=\"bankFile\" accept=\".json,.txt,.csv\" style=\"margin-top:6px\"></div>`);\n  },\n  importBankDo: async () => {\n    let text = ((document.getElementById('bankText') || {}).value || '').trim();\n    const fileEl = document.getElementById('bankFile');\n    if (!text && fileEl && fileEl.files && fileEl.files[0]) text = await fileEl.files[0].text();\n    if (!text) { toast('没有可导入的内容'); return; }\n    const arr = [];\n    const data = parseJSON(text);\n    if (data && Array.isArray(data.questions || data)) (data.questions || data).forEach(q => arr.push(normQuestion(q)));\n    else text.split('\\n').map(s => s.trim()).filter(Boolean).forEach(line => {\n      const p = line.split(/[|｜\\t]/).map(s => s.trim());\n      if (p.length >= 3) {\n        const opts = p.slice(1, 5).filter(Boolean);\n        const ans = p[5] || 'A';\n        arr.push(normQuestion({ type: 'choice', q: p[0], options: opts, answerIndex: Math.max(0, 'ABCD'.indexOf(ans.toUpperCase())) }));\n      } else if (p.length === 2) arr.push(normQuestion({ type: 'fill', q: p[0], answer: p[1], keywords: [p[1]] }));\n    });\n    let added = 0;\n    const defCat = (cfg('punishCat') || '').trim();\n    for (const q of arr) {\n      if (!q.q) continue;\n      const rec = Object.assign({}, q, {\n        cat: q.cat || defCat || '综合', src: 'import', at: Date.now(),\n        right: Number(q.right || 0), wrong: Number(q.wrong || 0), mastered: !!q.mastered\n      });\n      const r = await DB.create(T.QBANK, rec);\n      if (r) { S.qbank.unshift(Object.assign({ id: r.id }, rec)); added++; }\n    }\n    if (!(cfg('bankCats') || []).length) {\n      const set = {}; allBank().forEach(q => { if (q.cat) set[q.cat] = 1; });\n      S.settings.bankCats = Object.keys(set);\n    }\n    closeAllSheets(); toast('导入 ' + added + ' 道题'); render();\n  },\n  calMove: el => {\n    const base = S.draft.calMonth ? new Date(S.draft.calMonth) : new Date();\n    base.setMonth(base.getMonth() + Number(el.dataset.v));\n    S.draft.calMonth = base.getTime();\n    S.draft.calDay = '';              // 换月份就把选中的那天收起来\n    render();\n  },\n  /* 点选某一天：再点一次收起 */\n  calDay: el => {\n    const k = String(el.dataset.k || '');\n    S.draft.calDay = (String(S.draft.calDay || '') === k) ? '' : k;\n    render();\n  },\n  calDayClose: () => { S.draft.calDay = ''; render(); }\n});\n/* ==========================================================\n   动作 · 邀请（专注邀约 / 睡眠陪伴）\n   ========================================================== */\nfunction inviteParse() {\n  const dp = String(S.draft.inviteDate || '').split('-').map(Number);\n  const tp = String(S.draft.inviteTime || '').split(':').map(Number);\n  if (!dp[0] || !dp[1] || !dp[2]) return 0;\n  const d = new Date(dp[0], dp[1] - 1, dp[2], tp[0] || 0, tp[1] || 0, 0, 0);\n  return d.getTime() || 0;\n}\nObject.assign(ACTIONS, {\n  openInvite: el => {\n    const k = (el && el.dataset && el.dataset.k) === 'sleep' ? 'sleep' : 'focus';\n    S.draft.inviteKind = k;\n    S.draft.inviteFromChat = false;\n    if (!S.draft.inviteChar) S.draft.inviteChar = inviteCharId();\n    if (k === 'sleep') {\n      if (S.draft.invMode == null) S.draft.invMode = cfg('sleepMode') || '午睡';\n      if (S.draft.invMin == null) S.draft.invMin = Number(cfg('sleepMinutes') || 30);\n    } else {\n      if (S.draft.inviteMin == null) S.draft.inviteMin = Number(cfg('focusMin') || 25);\n      if (!S.draft.invitePlan) S.draft.invitePlan = 'now';\n      const d0 = inviteDefaultDate();\n      if (!S.draft.inviteDate) S.draft.inviteDate = d0.date;\n      if (!S.draft.inviteTime) S.draft.inviteTime = d0.time;\n    }\n    go('invite');\n  },\n  inviteChar: el => {\n    S.draft.inviteChar = el.dataset.id;\n    /* 选谁就当场记下来：邀请页、首页、睡眠页立刻一致 */\n    if (inviteKind() === 'sleep') { S.settings.sleepCharIds = [el.dataset.id]; }\n    S.settings.charIds = [el.dataset.id];\n    saveSettings();\n    toast('已选：' + charName(el.dataset.id));\n    render();\n  },\n  inviteRandomChar: () => {\n    if (!S.chars.length) return;\n    S.draft.inviteChar = S.chars[Math.floor(Math.random() * S.chars.length)].id;\n    render();\n  },\n  inviteMode: el => {\n    S.draft.invMode = el.dataset.v;\n    S.draft.invMin = Number(el.dataset.m) || 30;\n    render();\n  },\n  inviteMinPick: el => { S.draft.inviteMin = Number(el.dataset.v) || 25; render(); },\n  inviteTaskPick: el => { S.draft.inviteTask = el.dataset.v; render(); },\n  invitePlanMode: el => {\n    S.draft.invitePlan = el.dataset.v === 'book' ? 'book' : 'now';\n    if (S.draft.invitePlan === 'book') {\n      const d0 = inviteDefaultDate();\n      if (!S.draft.inviteDate) S.draft.inviteDate = d0.date;\n      if (!S.draft.inviteTime) S.draft.inviteTime = d0.time;\n    }\n    render();\n  },\n  inviteSend: async el => {\n    if (S.busy === 'invite') { toast('正在等 TA 应你，请稍候…'); return; }\n    const startNow = (el && el.dataset && el.dataset.mode) === 'start';\n    if (inviteKind() === 'sleep') await sendSleepInvite(startNow);\n    else await sendFocusInvite(startNow);\n  },\n  /* 预订一个专注时间段：真的排进「预约专注」，到点 TA 会来催 */\n  inviteBook: async () => {\n    if (S.busy === 'invite') { toast('正在处理，请稍候…'); return; }\n    const cid = inviteCharId();\n    if (!cid) { toast('请先选一位角色'); return; }\n    const task = String(S.draft.inviteTask || '').trim();\n    if (!task) { toast('先写清楚这一段要做什么'); return; }\n    const startAt = inviteParse();\n    if (!startAt) { toast('日期或时间格式不对'); return; }\n    if (startAt - Date.now() < 60000) { toast('开始时间要晚于现在（至少留 1 分钟）'); return; }\n    const minutes = clamp(Number(S.draft.inviteMin) || Number(cfg('focusMin') || 25), 1, 600);\n    const d = new Date(startAt);\n    const nm = charName(cid);\n    const rec = {\n      id: '', date: dkey(d), time: pad2(d.getHours()) + ':' + pad2(d.getMinutes()), startAt: startAt,\n      minutes: minutes, task: task.slice(0, 60), charIds: [cid],\n      status: 'pending', nudgeCount: 0, createdAt: Date.now(), note: ''\n    };\n    S.busy = 'invite'; render();\n    await createAppt(rec);\n    const nowMs = Date.now();\n    if (startAt - nowMs < apptAdvance() * 60000) {\n      rec.nudgeCount = apptTimesOf(rec).filter(t => t < nowMs - 60000).length;\n      rec.note = '离开始不足 ' + apptAdvance() + ' 分钟，前面 ' + rec.nudgeCount + ' 次催促来不及发出（还是会按约定开罚）';\n      await updateAppt(rec);\n    }\n    const n = await scheduleAppt(rec);\n    const times = apptTimesOf(rec);\n    await syncTimeline(cid, `用户和你约好 ${rec.date} ${rec.time} 一起专注 ${minutes} 分钟：${task}。你要负责到点催他开始（提前 ${apptAdvance()} 分钟起，每 ${apptGap()} 分钟一次，共 ${apptMaxNudge()} 次），连着催 ${apptMaxNudge()} 次没开始就按规矩罚。`, 'appt_make', {});\n    await sdk(() => API.chat.writeHistory({\n      characterId: cid, role: 'user',\n      content: `[专注邀约] 我跟你约好了：${rec.date} ${rec.time} 一起专注 ${minutes} 分钟，内容是「${task}」。到点前来催我，别让我拖。`\n    }), null);\n    await sdk(() => API.chat.sendCard({\n      characterId: cid, role: 'user', historyRole: 'user',\n      summary: `和${nm}约好 ${rec.date} ${rec.time} 一起专注 ${minutes} 分钟：${task}`,\n      historyText: `[专注邀约·已约好] ${rec.date} ${rec.time} 一起专注 ${minutes} 分钟：${task}（${nm}会提前来催，催 ${apptMaxNudge()} 次没开始按规矩罚）`,\n      card: {\n        appLabel: '角色陪伴专注', title: '专注邀约 · 已约好', subtitle: rec.date + ' ' + rec.time, status: '到点 TA 来催你',\n        accentColor: '#7c8cff', height: 250,\n        sections: [{ title: '约定', rows: [\n          { label: '做什么', value: task },\n          { label: '多久', value: minutes + ' 分钟' },\n          { label: '催促', value: times.map(t => hm(t)).join(' / ') }\n        ] }],\n        html: '<div style=\"padding:14px;font:13.5px/1.8 -apple-system,BlinkMacSystemFont,sans-serif\">'\n          + '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 专注邀约</div>'\n          + '<div style=\"margin-top:8px\">约好了：<b>' + rec.date + ' ' + rec.time + '</b>，一起专注 <b>' + minutes + ' 分钟</b>。</div>'\n          + '<div style=\"margin-top:6px;color:#c8cfe3\">' + esc(task) + '</div>'\n          + '<div style=\"margin-top:8px;color:#8b97ad;font-size:12px\">' + nm + ' 会在这几个时间点来催你：' + times.map(t => hm(t)).join(' / ') + '。连着催 ' + apptMaxNudge() + ' 次还没开始，就按惩罚库开罚。</div></div>'\n      }\n    }), null);\n    S.busy = '';\n    S.draft.inviteTask = '';\n    closeAllSheets();\n    toast(n ? '约好了：' + rec.date + ' ' + rec.time + ' · 已排好 ' + n + ' 次催促' : '预约已记下（宿主定时任务不可用，到时自己留意）');\n    go('appt');\n  },\n  inviteBack: async () => {\n    if (S.draft.inviteFromChat) {\n      const r = await sdk(() => API.app.close({}), undefined);\n      if (r !== undefined) { S.draft.inviteFromChat = false; return; }\n    }\n    S.draft.inviteFromChat = false;\n    go('home');\n  }\n});\n/* 发专注邀约：写进聊天室 → 请 TA 应一声 →（可选）直接开始专注 */\nasync function sendFocusInvite(startNow) {\n  const cid = inviteCharId();\n  if (!cid) { toast('请先选一位角色'); return; }\n  const task = String(S.draft.inviteTask || '').trim() || '和你一起安静地待一会儿';\n  const minutes = clamp(Number(S.draft.inviteMin) || Number(cfg('focusMin') || 25), 1, 600);\n  const nm = charName(cid);\n  S.busy = 'invite'; render();\n  await sdk(() => API.chat.writeHistory({\n    characterId: cid, role: 'user',\n    content: `[专注邀约] 我想约你陪我现在一起专注 ${minutes} 分钟，内容是「${task}」。你应我一声。`\n  }), null);\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'user', historyRole: 'user',\n    summary: '用户给' + nm + '发了专注邀约：' + minutes + ' 分钟 · ' + task,\n    historyText: `[专注邀约] 用户约${nm}现在一起专注 ${minutes} 分钟：${task}`,\n    card: {\n      appLabel: '角色陪伴专注', title: '陪他专注一会儿', subtitle: 'FOCUS INVITE', status: '等你应一声',\n      accentColor: '#7c8cff', height: 240,\n      sections: [{ title: '邀约内容', rows: [\n        { label: '做什么', value: task },\n        { label: '多久', value: minutes + ' 分钟' }\n      ] }],\n      html: '<div style=\"padding:14px;font:13.5px/1.8 -apple-system,BlinkMacSystemFont,sans-serif\">'\n        + '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 邀约</div>'\n        + '<div style=\"margin-top:8px\">他想约你陪着一起专注 <b>' + minutes + ' 分钟</b>。</div>'\n        + '<div style=\"margin-top:6px;color:#c8cfe3\">' + esc(task) + '</div>'\n        + '<div style=\"margin-top:8px;color:#8b97ad;font-size:12px\">应他一声，这段就开始了。</div></div>'\n    }\n  }), null);\n  let line = '';\n  try {\n    const ret = await API.chat.requestReply({ characterId: cid });\n    line = (ret && (ret.text || ret.content)) || '';\n  } catch (e) { line = ''; }\n  if (!line) { const cap = await captureChatReply(cid, Date.now() - 60000); line = cap ? cap.text : ''; }\n  if (!line) {\n    let t2 = '';\n    try { t2 = await pGen('invite.reply', { kind: '陪他一起专注', minutes: String(minutes), task: '，内容是「' + task + '」', note: '' }, [cid]); } catch (e) { t2 = ''; }\n    line = t2 || '好，我在。开始吧。';\n  }\n  line = String(line).replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 120);\n  await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n  await syncTimeline(cid, `用户在聊天室给${nm}发了专注邀约：${minutes} 分钟 · ${task}。${nm}应他：${line}`, 'focus_invite', {});\n  S.busy = '';\n  if (!startNow) {\n    toast('邀约已发到聊天室，TA 应你：' + line);\n    render();\n    return;\n  }\n  toast('TA 应你了：' + line);\n  await startSession({\n    charIds: [cid], focusMin: minutes, breakMin: Math.max(1, Number(cfg('breakMin') || 5)), cycles: 1,\n    plan: [{ content: task, est: minutes }], reviewEvery: 'focus', voiceOn: cfg('voiceMode') !== 'off'\n  });\n  const s = S.session;\n  if (s && line) { pushMsg(s, 'char', line, { charId: cid, kind: 'invite' }); await saveSession(true); render(); }\n}\n/* 发陪睡邀请：写进聊天室 → 请 TA 应一声 →（可选）直接开始睡眠 */\nasync function sendSleepInvite(startNow) {\n  const cid = inviteCharId();\n  if (!cid) { toast('请先选一位角色'); return; }\n  const mode = S.draft.invMode || cfg('sleepMode') || '午睡';\n  const minutes = clamp(Number(S.draft.invMin) || Number(cfg('sleepMinutes') || 30), 1, 1440);\n  const note = String(S.draft.invNote || '').trim();\n  const nm = charName(cid);\n  S.busy = 'invite'; render();\n  S.settings.sleepCharIds = [cid];\n  await saveSettings(true);\n  await sdk(() => API.chat.writeHistory({\n    characterId: cid, role: 'user',\n    content: `（${nm}，我要去${mode}了，陪我一起。${note ? '想跟你说：' + note : ''}）这次记录 ${minutes} 分钟。`\n  }), null);\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'user', historyRole: 'user',\n    summary: '用户邀请' + nm + '陪他一起睡（' + mode + ' ' + minutes + ' 分钟）',\n    historyText: '[一起睡] 用户邀请' + nm + '陪他一起' + mode + '，时长 ' + minutes + ' 分钟。' + (note ? '他想说：' + note : ''),\n    card: {\n      appLabel: '角色陪伴专注', title: '邀请你陪他一起睡', subtitle: 'GOOD NIGHT', status: '等你应一声',\n      accentColor: '#a58bff', height: 250,\n      sections: [{ title: '邀请内容', rows: [\n        { label: '一起', value: mode + ' · ' + minutes + ' 分钟' },\n        { label: '他想说', value: note || '（没留言）' }\n      ] }],\n      html: '<div style=\"padding:14px;font:13.5px/1.8 -apple-system,BlinkMacSystemFont,sans-serif\">'\n        + '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 晚安邀请</div>'\n        + '<div style=\"margin-top:8px\">他邀请你陪他一起' + esc(mode) + '（' + minutes + ' 分钟）。</div>'\n        + (note ? '<div style=\"margin-top:6px;color:#c8cfe3\">「' + esc(note) + '」</div>' : '')\n        + '<div style=\"margin-top:8px;color:#8b97ad;font-size:12px\">应他一声，然后一起躺下。</div></div>'\n    }\n  }), null);\n  let line = '';\n  try {\n    const ret = await API.chat.requestReply({ characterId: cid });\n    line = (ret && (ret.text || ret.content)) || '';\n  } catch (e) { line = ''; }\n  if (!line) { const cap = await captureChatReply(cid, Date.now() - 60000); line = cap ? cap.text : ''; }\n  if (!line) {\n    let t2 = '';\n    try { t2 = await pGen('invite.reply', { kind: '陪他一起' + mode, minutes: String(minutes), task: '', note: note ? '他还想说：' + note : '' }, [cid]); } catch (e) { t2 = ''; }\n    line = t2 || '来，躺下吧，我在。';\n  }\n  line = String(line).replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 120);\n  await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n  await syncTimeline(cid, `用户邀请${nm}陪他一起${mode}（${minutes} 分钟）：${note || '（没留言）'}。${nm}应他：${line}`, 'sleep_invite', {});\n  S.busy = '';\n  if (!startNow) {\n    toast('邀请已写进聊天室，TA 应你：' + line);\n    render();\n    return;\n  }\n  const ok = await startSleep(mode, minutes);\n  if (ok !== false) {\n    const st = S.sleep;\n    if (st && line) {\n      st.inviteLine = line; st.inviteChar = cid;\n      st.chat = (st.chat || []).concat([{ role: 'char', charId: cid, text: line, at: Date.now(), kind: 'invite' }]);\n      if (st.chat.length > 60) st.chat = st.chat.slice(-60);\n      await saveSleepSession();\n      if (shouldSpeak('invite')) speak(cid, line);\n      if (S.view === 'sleep') render();\n    }\n    toast('已开始：' + nm + '陪你' + mode);\n  }\n}\n/* ==========================================================\n   动作 · 睡眠 / 故事 / 闹钟\n   ========================================================== */\nObject.assign(ACTIONS, {\n  startSleep: async () => {\n    const ok = await startSleep(S.draft.sleepMode || '午睡', Number(S.draft.sleepMin || 30));\n    if (ok !== false) toast('已开始记录睡眠（正计时）');\n  },\n  noTargetSleep: async () => {\n    const ok = await startSleep('小憩', 0);\n    if (ok !== false) toast('已开始记录睡眠（正计时）');\n  },\n  toggleSleepChar: async el => {\n    const arr = (S.settings.sleepCharIds || []).slice();\n    const i = arr.indexOf(el.dataset.id);\n    if (i >= 0) arr.splice(i, 1); else arr.push(el.dataset.id);\n    S.settings.sleepCharIds = arr;\n    await saveSettings(true);\n    await applySleepChars();          // 正在睡的话当场换人\n    toast(arr.length ? '睡眠陪伴：' + arr.map(id => charName(id)).join('、') : '已清空，将使用专注阵容');\n    render();\n  },\n  clearSleepChar: async () => { S.settings.sleepCharIds = []; await saveSettings(true); await applySleepChars(); render(); },\n  randomSleepChar: async () => {\n    if (!S.chars.length) { toast('还没有角色'); return; }\n    const c = S.chars[Math.floor(Math.random() * S.chars.length)];\n    S.settings.sleepCharIds = [c.id];\n    await saveSettings(true); await applySleepChars();\n    toast('随机抽到：' + c.name + '（正在睡的话已当场更换）'); render();\n  },\n  /* 正在睡眠时随手换一位陪睡角色：立刻生效并让新人说一句 */\n  sleepSwitchChar: async el => {\n    const cid = el.dataset.id;\n    if (!cid || !charById(cid)) return;\n    S.settings.sleepCharIds = [cid];\n    await saveSettings(true);\n    const st = S.sleep;\n    if (st && st.running) {\n      st.charIds = [cid];\n      st.lullabyChar = cid; st.sceneChar = cid;\n      await saveSleepSession();\n      const line = charName(cid) + '陪着你。今晚我在。';\n      st.chat = st.chat || [];\n      st.chat.push({ role: 'char', charId: cid, text: line, at: Date.now(), kind: 'switch' });\n      if (st.chat.length > 60) st.chat = st.chat.slice(-60);\n      await saveSleepSession();\n      toast('已换成：' + charName(cid));\n      await genSleepScene();\n      if (S.view === 'sleep') render();\n      return;\n    }\n    toast('已选陪睡角色：' + charName(cid));\n    render();\n  },\n  lullabyReplay: async () => {\n    const st = S.sleep; if (!st || !st.lullaby) return;\n    const ok = st.lullabyRef ? await playRef(st.lullabyRef) : await speak(st.lullabyChar || sleepCharId(), st.lullaby);\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  lullabyAgain: async () => { const st = S.sleep; if (!st) return; st.lullabyRef = ''; await playLullaby(); },\n  /* 睡前闲聊：互动＝还醒着，这段时间记作酝酿睡意 */\n  sleepChatOpen: () => {\n    const st = S.sleep;\n ",
  "   if (!st || !st.running) { toast('先开始睡眠，再来闲聊'); return; }\n    if (cfg('sleepChat') === false) { toast('睡前闲聊已在睡眠设置里关掉'); return; }\n    const w = openSheet(`<h3>💬 睡前闲聊</h3>\n      <div class=\"tiny\">和 TA 说两句再睡。你一互动就算「还醒着」—— 这段时间记作酝酿睡意；聊完保持这个页面连续 ${Number(cfg('sleepIdleMin') || 5)} 分钟不动屏幕，才开始计入睡眠。</div>\n      <div id=\"scLog\" class=\"mt10\" style=\"max-height:36vh;overflow-y:auto\">\n        ${(st.chat || []).length ? (st.chat || []).map(m => msgHTML({ role: m.role === 'me' ? 'me' : 'char', text: m.text, charId: m.charId, at: m.at })).join('')\n          : `<div class=\"tiny center\" style=\"padding:14px\">说点什么吧，比如「我睡不着」</div>`}</div>\n      <textarea id=\"scInput\" placeholder=\"说点什么…（TA 会尽量短、温柔地回你）\"></textarea>\n      <button class=\"btn primary block mt10\" data-act=\"sleepChatSend\">发过去</button>\n      <div class=\"tiny mt6\">聊完把手机放下就行，不必点「结束」—— 之后安静满 ${Number(cfg('sleepIdleMin') || 5)} 分钟就开始算睡眠。</div>`);\n    const log = w.querySelector('#scLog'); if (log) log.scrollTop = log.scrollHeight;\n    setTimeout(() => { const i = document.getElementById('scInput'); if (i) i.focus(); }, 150);\n  },\n  sleepChatSend: async () => {\n    const st = S.sleep; if (!st || !st.running) return;\n    const inp = document.getElementById('sleepInput') || document.getElementById('scInput');\n    const q = inp ? (inp.value || '').trim() : '';\n    if (!q) { toast('先说一句吧'); return; }\n    const cid = sleepCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    st.chat = st.chat || [];\n    st.chat.push({ role: 'me', text: q, at: Date.now() });\n    S.draft.sleepDraft = '';\n    if (inp) inp.value = '';\n    const log = document.getElementById('sleepMsgBox') || document.getElementById('scLog');\n    if (log) {\n      log.insertAdjacentHTML('beforeend', msgHTML({ role: 'me', text: q, at: Date.now() }) +\n        `<div class=\"msg\" id=\"scWait\">${charAvatar(charById(cid))}<div class=\"bd\"><span class=\"spin\"></span> ${esc(charName(cid))} 在回你…</div></div>`);\n      log.scrollTop = log.scrollHeight;\n    }\n    await markSleepActive('chat');\n    const hist = st.chat.slice(-9, -1).map(m => (m.role === 'me' ? '用户：' : (charName(m.charId) + '：')) + m.text).join('\\n');\n    let text = '';\n    try { text = await pGen('sleep.chat', { question: q, history: hist || '（这是第一句）', mode: st.mode || '睡觉' }, [cid]); } catch (e) { text = ''; }\n    const wait = document.getElementById('scWait'); if (wait) wait.remove();\n    if (!text) text = '嗯，我在。别想太多了，闭上眼吧。';\n    text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '').slice(0, 400);\n    st.chat.push({ role: 'char', charId: cid, text: text, at: Date.now() });\n    if (st.chat.length > 60) st.chat = st.chat.slice(-60);\n    await markSleepActive('chat');\n    if (log) {\n      log.insertAdjacentHTML('beforeend', msgHTML({ role: 'char', text: text, charId: cid, at: Date.now() }));\n      log.scrollTop = log.scrollHeight;\n    }\n    const ph = document.getElementById('sleepPhase'); if (ph) ph.textContent = sleepPhaseText();\n    const cnt = document.getElementById('sleepChatCount'); if (cnt) cnt.textContent = (st.chat || []).length + ' 句';\n    /* 睡前闲聊的语音由它自己的开关管（默认开）—— 不挂在「角色提醒的语音形式」上，\n       那一档只管专注里的催促/惩罚/唤醒。 */\n    if (cfg('sleepChatVoice') !== false) speak(cid, text, 'sleepChat', '睡前闲聊');\n  },\n  sceneReroll: async () => {\n    const st = S.sleep;\n    if (!st || !st.running) { toast('先开始睡眠'); return; }\n    st.scene = ''; render();\n    await genSleepScene();\n  },\n  sceneSaveFav: () => {\n    const st = S.sleep;\n    if (!st || !st.scene) { toast('还没有环境描写'); return; }\n    openFavPicker({ kind: 'text', title: '睡前的房间 · ' + dkey(new Date(st.startAt)), content: st.scene, charId: st.sceneChar || '', from: '睡眠环境描写' });\n  },\n  sleepChatFav: () => {\n    const st = S.sleep;\n    const rows = (st && st.chat) || [];\n    if (!rows.length) { toast('还没有聊天内容'); return; }\n    const text = rows.map(m => (m.role === 'me' ? '我：' : (charName(m.charId) + '：')) + m.text).join('\\n');\n    openFavPicker({ kind: 'text', title: '睡前闲聊 · ' + dkey(new Date(st.startAt)), content: text, charId: (st.charIds || [])[0] || '', from: '睡前闲聊' });\n  },\n  /* 点开某条睡眠记录：有报告直接看，没有就给一个生成入口 */\n  sleepRec: el => {\n    const rec = (S.sleeps || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!rec) return;\n    S.report = Object.assign({ rec: rec, loading: false, quality: '', observe: '', advice: '', murmur: '', charId: anyCharId() }, rec.report || {});\n    go('sleepreport');\n  },\n  genThisReport: () => {\n    const R = S.report; if (!R || !R.rec) return;\n    genSleepReport(R.rec);\n  },\n  /* 中断点：中途醒了但还想睡 —— 不结束睡眠、正计时继续，只打标记，最终进报告分析 */\n  sleepBreak: () => {\n    const st = S.sleep;\n    if (!st || !st.running) { toast('先开始睡眠，再来记中断点'); return; }\n    const presets = ['起夜', '做梦惊醒', '外面有声音', '有点不舒服', '翻来覆去', '醒了但还是想睡'];\n    const w = openSheet(`<h3>🌗 记一个中断点</h3>\n      <div class=\"tiny\">睡眠不结束、正计时不中断，只在记录里打一个「中途醒来」的标记；结束睡眠时会写进报告一起分析。</div>\n      <div class=\"tiny mt6\">总 ${fmtDur(sleepElapsedSec())} · 其中睡眠 ${fmtDur(sleepSleepSec())} · 酝酿 ${fmtDur(sleepDrowsySec())}</div>\n      <div class=\"chips mt10\">${presets.map(x => `<button class=\"chip\" data-bk=\"${esc(x)}\">${esc(x)}</button>`).join('')}</div>\n      <label class=\"fl\">补充说明（可留空）</label>\n      <input class=\"input\" id=\"breakNote\" placeholder=\"例如：醒了大概十分钟又睡回去\">\n      <div class=\"row mt10\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"sleepBreakSave\">记下这个中断点</button></div>`);\n    w.addEventListener('click', e => {\n      const b = e.target.closest('[data-bk]'); if (!b) return;\n      const inp = document.getElementById('breakNote');\n      if (inp) inp.value = b.dataset.bk;\n      w.querySelectorAll('[data-bk]').forEach(x => x.classList.toggle('on', x === b));\n    });\n  },\n  sleepBreakSave: async () => {\n    const st = S.sleep; if (!st) return;\n    const inp = document.getElementById('breakNote');\n    const note = inp ? (inp.value || '').trim() : '';\n    st.breaks = st.breaks || [];\n    st.breaks.push({ at: Date.now(), note: note });\n    await saveSleepSession();\n    await markSleepActive('break');\n    closeAllSheets(); render();\n    toast('已记下中断点 ' + hm(Date.now()) + '，继续睡吧');\n  },\n  delSleepBreak: async el => {\n    const st = S.sleep; if (!st || !st.breaks) return;\n    st.breaks.splice(Number(el.dataset.i), 1);\n    await saveSleepSession(); render();\n  },\n  endSleep: () => endSleepAsk(),\n  endSleepDo: async () => {\n    const inp = document.getElementById('deepMin');\n    const deepMin = inp ? (Number(inp.value) || 0) : (Number(S.draft.deepMin) || 0);\n    const rin = document.getElementById('realSleepMin');\n    const realSleepMin = rin ? (Number(rin.value) || 0) : (Number(S.draft.realSleepMin) || 0);\n    S.draft.deepMin = deepMin; S.draft.realSleepMin = realSleepMin;\n    closeAllSheets();\n    await endSleep({ asleep: S.draft.asleep || 'asleep', deepMin: deepMin, realSleepMin: realSleepMin });\n    S.draft.asleep = ''; S.draft.deepMin = null; S.draft.realSleepMin = null;\n  },\n  /* 结束面板里的快捷修正：切走之后就直接睡了 */\n  sleepFromAway: () => {\n    const at = S.draft.awayAt;\n    if (!at) { toast('没有记录到你离开睡眠页的时间'); return; }\n    const min = Math.max(1, Math.round((Date.now() - at) / 60000));\n    S.draft.realSleepMin = min;\n    const rin = document.getElementById('realSleepMin');\n    if (rin) rin.value = String(min);\n    const din = document.getElementById('deepMin');\n    if (din && !Number(din.value)) din.value = String(Math.round(min * 0.4));\n    toast('已按「从 ' + hm(at) + ' 睡到现在」填成 ' + min + ' 分钟');\n  },\n  clearSleepWall: async () => {\n    S.lastSleepWall = ''; S.lastSleepWallRef = ''; S.lastSleepInfo = null;\n    S.settings.lastSleepWallRef = ''; S.settings.lastSleepInfo = null;\n    await saveSettings(true); render();\n  },\n  genSleepWallpaper: () => genSleepWallpaper(),\n  /* 自己上传睡眠壁纸：优先走宿主媒体选择（本版本已声明 media.pick），不行再退化为应用内选文件 */\n  sleepWallUpload: async () => {\n    toast('选一张图片…');\n    const url = await pickImageData();\n    if (!url) { toast('没有选到图片'); return; }\n    const st = S.sleep;\n    const cid = sleepCharId() || anyCharId();\n    const put = await sdk(() => API.media.put({ dataUrl: url }), null);\n    const ref = (put && put.ref) || '';\n    if (st && st.running) {\n      st.wp = url; st.wpRef = ref;\n      if (!st.albumId) {\n        const item = await saveAlbum('sleep', url, { title: '睡眠壁纸（自传） ' + dkey(), locked: false, note: (st.mode || '睡眠') + ' · 自己上传', charId: cid });\n        if (item) st.albumId = item.id;\n      }\n      await saveSleepSession(); render();\n      toast('已设为这次睡眠的壁纸，并铺成背景');\n      return;\n    }\n    S.lastSleepWall = url; S.lastSleepWallRef = ref;\n    S.settings.lastSleepWallRef = ref;\n    await saveAlbum('sleep', url, { title: '睡眠壁纸（自传） ' + dkey(), locked: false, note: '自己上传', charId: cid });\n    await saveSettings(true); render();\n    toast('已换成你自己的图片');\n  },\n  downloadSleepWallpaper: async () => {\n    const url = await sleepWallUrl();\n    if (!url) { toast('还没有壁纸，先生成一张'); return; }\n    saveImageAnywhere(url, 'sleep_wallpaper_' + dkey() + '.png', '睡眠壁纸 · ' + dkey(), anyCharId());\n  },\n  sendSleepWallToChat: async () => {\n    const url = await sleepWallUrl();\n    const cid = anyCharId();\n    if (!url) { toast('还没有壁纸，先生成一张'); return; }\n    if (!cid) { toast('还没有角色'); return; }\n    const ok = await sendImageCard(cid, url, '睡眠壁纸 · ' + dkey());\n    toast(ok ? '已发到聊天室：去那里保存' : '发送失败');\n  },\n  replayReport: async () => {\n    const R = S.report; if (!R) return;\n    const text = R.murmur || R.quality || '';\n    if (!text) return;\n    /* 复用优先：生成报告时已经存过一份音频，直接播那份。\n       存的那份取不到（换设备 / 媒体库被清）才重新合成。 */\n    const ref = R.murmurRef || (R.rec && R.rec.report && R.rec.report.murmurRef) || '';\n    if (ref) {\n      const ok0 = await playVoiceRefOnce(ref);\n      if (ok0) return;\n      R.murmurRef = '';\n      if (R.rec && R.rec.report) R.rec.report.murmurRef = '';\n    }\n    const vr = await voiceSay(R.charId || anyCharId(), text, 'sleepReport', '睡眠报告碎碎念');\n    if (vr && vr.ref) {\n      R.murmurRef = vr.ref;\n      if (R.rec) { R.rec.report = R.rec.report || {}; R.rec.report.murmurRef = vr.ref; }\n    }\n    if (!vr || !vr.ok) toast('播放失败，请检查语音配置');\n  },\n  regenSleepReport: () => { if (S.report && S.report.rec) genSleepReport(S.report.rec); },\n  reportFav: () => {\n    const R = S.report;\n    if (!R || !R.rec) { toast('没有可收藏的报告'); return; }\n    const rec = R.rec;\n    const txt = '睡眠报告 ' + rec.date + '（' + (rec.mode || '睡眠') + ' · ' + fmtDur(rec.seconds) + '）'\n      + '\\n总时长：' + fmtDur(rec.seconds) + '｜酝酿睡意：' + fmtDur(rec.drowsySec || 0) + '｜实际入睡：' + fmtDur(rec.sleepSec != null ? rec.sleepSec : rec.seconds)\n      + (rec.deepSec ? '｜预计深睡：' + fmtDur(rec.deepSec) : '')\n      + '\\n【质量分析】' + (R.quality || '')\n      + '\\n【睡眠观察】' + (R.observe || '')\n      + '\\n【作息建议】' + (R.advice || '')\n      + '\\n【碎碎念】' + (R.murmur || '');\n    openFavPicker({ kind: 'report', title: '睡眠报告 · ' + rec.date, content: txt, charId: R.charId || '', from: '睡眠报告' });\n  },\n  genStory: async () => {\n    const sty = cfg('story') || {};\n    const cid = S.draft.storyChar || sty.charId || anyCharId();\n    if (!cid) { toast('请先选择朗读角色'); return; }\n    const style = S.draft.storyStyle || sty.style || '温柔治愈';\n    const minutes = Number(S.draft.storyMin || sty.minutes || 10);\n    const words = Math.round(minutes * 200);\n    S.loading = 'story'; render();\n    let text = '';\n    try {\n      text = await pGen('story.gen', { style: style, words: words }, [cid]);\n    } catch (e) { }\n    S.loading = '';\n    if (!text) { render(); toast('故事生成失败，请检查 API 配置或稍后重试'); return; }\n    const paras = text.split(/\\n+/).map(s => s.trim()).filter(s => s.length > 1);\n    S.story = { title: style + '的睡前故事', style: style, minutes: minutes, charId: cid, paras: paras, audioRefs: [], idx: 0, playing: true, at: Date.now(), date: dkey() };\n    cfg('story').charId = cid; cfg('story').style = style; cfg('story').minutes = minutes;\n    saveSettings();\n    await saveStory(S.story);      // 先落库：故事文本和进度都不会丢\n    await loadStories();\n    render();\n    playStoryFrom(0);\n  },\n  pauseStory: () => { if (S.story) { S.story.playing = false; stopVoice(); render(); } },\n  resumeStory: () => {\n    const st = S.story; if (!st) return;\n    playStoryFrom(st.idx >= st.paras.length ? 0 : st.idx);\n  },\n  stopStory: async () => {\n    if (!S.story) return;\n    S.story.playing = false;\n    await saveStory(S.story);      // 结束也保存进度，下次接着听\n    stopVoice(); S.story = null; await loadStories(); render();\n  },\n  storyRestart: () => { if (S.story) playStoryFrom(0); },\n  storyFav: () => {\n    const st = S.story;\n    if (!st || !(st.paras || []).length) { toast('还没有故事内容'); return; }\n    openFavPicker({\n      kind: 'story', title: (st.title || '睡前故事') + ' · ' + (st.date || dkey()),\n      content: (st.paras || []).join('\\n\\n'), charId: st.charId || '', from: '睡前故事'\n    });\n  },\n  openStory: el => {\n    const it = (S.stories || []).find(x => String(x.id) === String(el.dataset.id));\n    openStoryItem(it);\n  },\n  delStory: async el => {\n    const it = (S.stories || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!it) return;\n    const ok = await confirmBox('删除这个故事？', '故事文本与已留存的语音都会一起删掉。', '删除');\n    if (!ok) return;\n    for (const ref of (it.audioRefs || [])) if (ref) await sdk(() => API.media.delete({ ref: ref }));\n    await DB.remove(T.STORY, it.id);\n    if (S.story && S.story.dbId === it.id) S.story = null;\n    await loadStories(); toast('已删除'); render();\n  },\n  saveStoryAudio: async () => {\n    const st = S.story; if (!st) return;\n    if (S.loading) return;\n    S.loading = 'audio'; toast('正在把语音逐段存下来…');\n    st.audioRefs = st.audioRefs || [];\n    let n = 0;\n    for (let i = 0; i < st.paras.length && i < 40; i++) {\n      if (st.audioRefs[i]) { n++; continue; }\n      const ref = await ttsRefOnly(st.charId, st.paras[i]);\n      if (ref) { st.audioRefs[i] = ref; n++; await saveStory(st); }\n    }\n    let exported = 0;\n    for (let i = 0; i < st.audioRefs.length && exported < 3; i++) {\n      const ref = st.audioRefs[i]; if (!ref) continue;\n      const g = await sdk(() => API.media.get({ ref: ref }), null);\n      if (!g || !g.dataUrl) continue;\n      const sv = await sdk(() => API.media.save({ dataUrl: g.dataUrl, type: 'custom_app_media' }), null);\n      if (sv) exported++;\n    }\n    S.loading = '';\n    render();\n    toast('已留存 ' + n + '/' + st.paras.length + ' 段语音' + (exported ? '，并导出 ' + exported + ' 段到小手机媒体库' : ''));\n  },\n  /* 整篇连播：合成一段音频 → 存媒体库 → 交给宿主一次播完 */\n  storyWhole: async () => {\n    const st = S.story; if (!st) return;\n    if (S.loading) { toast('正在处理，请稍候…'); return; }\n    st.playing = false; stopVoice();\n    let ref = st.wholeRef || '', mode = '已留存的整篇音频';\n    if (!ref) {\n      S.loading = 'whole'; render();\n      const r = await synthWholeStory(st);\n      if (r && r.dataUrl) {\n        const put = await sdk(() => API.media.put({ dataUrl: r.dataUrl }), null);\n        if (put && put.ref) { ref = put.ref; st.wholeRef = ref; mode = r.mode; await saveStory(st); }\n      }\n      S.loading = '';\n      if (!ref) { render(); toast('整篇合成失败（可能是语音服务一次给不了这么长），改用「开始朗读」逐段听吧'); return; }\n    }\n    st.playing = true; st.idx = st.paras.length; render();\n    const ok = await playRef(ref);\n    st.playing = false;\n    render();\n    toast(ok ? '整篇连播结束（' + mode + '）可再来一次' : '播放失败，请检查语音配置');\n  },\n  /* 导出整篇音频：存到小手机媒体库，失败时退化为浏览器下载 */\n  storyExport: async () => {\n    const st = S.story; if (!st) return;\n    if (S.loading) { toast('正在处理，请稍候…'); return; }\n    let ref = st.wholeRef || '';\n    S.loading = 'whole'; render();\n    let url = '';\n    if (ref) {\n      const g = await sdk(() => API.media.get({ ref: ref }), null);\n      if (g && g.dataUrl) url = g.dataUrl;\n    }\n    if (!url) {\n      const r = await synthWholeStory(st);\n      if (r && r.dataUrl) {\n        url = r.dataUrl;\n        const put = await sdk(() => API.media.put({ dataUrl: url }), null);\n        if (put && put.ref) { ref = put.ref; st.wholeRef = ref; await saveStory(st); }\n      }\n    }\n    S.loading = '';\n    if (!url) { render(); toast('合成失败，无法导出（可能是语音服务一次给不了这么长）'); return; }\n    let saved = false;\n    const sv = await sdk(() => API.media.save({ dataUrl: url, type: 'custom_app_media' }), null);\n    if (sv) saved = true;\n    if (!saved) {\n      try {\n        const a = document.createElement('a');\n        a.href = url; a.download = 'story_' + (st.date || dkey()) + '.mp3';\n        document.body.appendChild(a); a.click(); a.remove();\n        saved = true;\n      } catch (e) { saved = false; }\n    }\n    render();\n    toast(saved ? '整篇音频已导出，用小手机自己的播放器打开即可后台听' : '导出失败，请检查语音配置');\n  },\n  toggleAlarmField: async el => {\n    const a = cfg('alarm'); a[el.dataset.k] = !a[el.dataset.k];\n    await saveSettings(); render();\n  },\n  setAlarmChar: async el => { cfg('alarm').charId = el.dataset.id; await saveSettings(); render(); },\n  saveAlarm: async () => {\n    const a = cfg('alarm');\n    const t = S.draft.alarmTime || a.time;\n    if (!/^\\d{2}:\\d{2}$/.test(t)) { toast('请选择时间'); return; }\n    a.time = t;\n    a.volume = S.draft.alarmVolume != null ? S.draft.alarmVolume : a.volume;\n    a.enabled = true;\n    if (!a.charId) a.charId = anyCharId();\n    await saveSettings(true);\n    for (const o of (S.alarms || []).filter(x => x.time === t)) { await DB.remove(T.ALARM, o.id); S.alarms = S.alarms.filter(x => x.id !== o.id); }\n    const rec = { time: t, repeat: !!a.repeat, charId: a.charId, enabled: true, at: Date.now() };\n    const r = await DB.create(T.ALARM, rec);\n    if (r) S.alarms.unshift(Object.assign({ id: r.id }, rec));\n    await scheduleAlarm(a);\n    toast('闹钟已保存：' + t); render();\n  },\n  testAlarm: async () => {\n    const a = cfg('alarm'), cid = a.charId || anyCharId();\n    toast('试听中…');\n    let text = '';\n    try { text = await pGen('wake.line', { time: '用户正在试听闹钟语音，' }, [cid]); } catch (e) { }\n    if (!text) text = '该起床了，别赖床。';\n    const ok = await speak(cid, text);\n    if (!ok) toast('语音失败，请先在小手机设置里配置语音服务');\n  },\n  delAlarm: async el => {\n    await DB.remove(T.ALARM, el.dataset.id);\n    S.alarms = (S.alarms || []).filter(x => x.id !== el.dataset.id);\n    cfg('alarm').enabled = false;\n    await saveSettings(true); render();\n  }\n});\n/* ---------- 故事与语音留存：每段语音存成媒体库引用，进度存库 ---------- */\nasync function saveStory(st) {\n  if (!st) return;\n  const data = {\n    title: st.title, style: st.style, minutes: st.minutes, charId: st.charId,\n    paras: st.paras || [], audioRefs: (st.audioRefs || []).map(x => x || ''),\n    wholeRef: st.wholeRef || '',\n    idx: st.idx || 0, at: st.at || Date.now(), date: st.date || dkey()\n  };\n  if (st.dbId) { await DB.update(T.STORY, st.dbId, data); return; }\n  const r = await DB.create(T.STORY, data);\n  if (r) st.dbId = r.id;\n}\nasync function loadStories() {\n  S.stories = ((await DB.list(T.STORY)) || []).sort((a, b) => (b.at || 0) - (a.at || 0));\n}\nasync function playRef(ref) {\n  if (!ref || !API || !API.voice || !API.voice.play) return false;\n  try { await API.voice.play({ dataUrl: ref }); return true; } catch (e) { return false; }\n}\n/* 生成一段语音 → 存进媒体库换引用 → 播放。返回 { ok, ref } */\nasync function ttsPlay(charId, text) {\n  if (!API || !API.voice || !API.voice.tts || !charId || !text) return { ok: false, ref: '' };\n  let dataUrl = '';\n  const lk = aiLock('生成语音');\n  try {\n    const r = await ttsJoined(charId, text);\n    if (r && r.dataUrl) dataUrl = r.dataUrl;\n  } catch (e) { console.warn('tts', e); return { ok: false, ref: '' }; }\n  finally { aiUnlock(lk); }\n  if (!dataUrl) return { ok: false, ref: '' };\n  let ref = '';\n  const put = await sdk(() => API.media.put({ dataUrl: dataUrl }), null);\n  if (put && put.ref) ref = put.ref;\n  let ok = false;\n  try { await API.voice.play({ dataUrl: ref || dataUrl }); ok = true; } catch (e) { ok = false; }\n  await logVoice('tts', charId, text, ok, ref, '语音朗读');\n  /* 哄睡语、睡前闲聊这类走 ttsPlay 的声音，也把引用挂回它对应的那条消息 */\n  if (ref && attachRefToMsg(charId, text, ref)) {\n    try { await saveSleepSession(); } catch (e) { }\n    refreshMsgVoice();\n  }\n  return { ok: ok, ref: ref };\n}\n/* ---------- 整篇连播：把故事合成成一段音频，交给宿主播放器连续播放 ---------- */\nasync function ttsRaw(charId, text) {\n  if (!API || !API.voice || !API.voice.tts || !charId || !text) return null;\n  const lk = aiLock('生成语音');\n  try {\n    const r = await API.voice.tts({ characterId: charId, text: text });\n    return (r && r.dataUrl) ? r : null;\n  } catch (e) { return null; }\n  finally { aiUnlock(lk); }\n}\nfunction b64ToBytes(b64) {\n  const bin = atob(b64); const a = new Uint8Array(bin.length);\n  for (let i = 0; i < bin.length; i++) a[i] = bin.charCodeAt(i);\n  return a;\n}\nfunction bytesToB64(bytes) {\n  let s = ''; const CH = 0x8000;\n  for (let i = 0; i < bytes.length; i += CH) s += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));\n  return btoa(s);\n}\n/* 先试整篇一次合成；不行再分段合成并按字节拼成一段（仅 mp3/mpeg 支持拼接） */\nasync function synthWholeStory(st) {\n  if (!st) return null;\n  const full = (st.paras || []).join('\\n\\n');\n  const one = await ttsRaw(st.charId, full);\n  if (one && one.dataUrl) return { dataUrl: one.dataUrl, mode: '整篇一次合成' };\n  const chunks = []; let cur = '';\n  (st.paras || []).forEach(p => {\n    if (cur && (cur.length + p.length) > 500) { chunks.push(cur); cur = p; }\n    else cur = cur ? (cur + '\\n\\n' + p) : p;\n  });\n  if (cur) chunks.push(cur);\n  const parts = [];\n  for (const c of chunks) {\n    const rr = await ttsRaw(st.charId, c);\n    if (!rr || !rr.dataUrl) return null;\n    parts.push(rr);\n  }\n  const mime = String(parts[0].mimeType || 'audio/mpeg');\n  const canJoin = parts.every(x => /mpeg|mp3/i.test(String(x.mimeType || mime)));\n  if (!canJoin) return null;\n  const bufs = parts.map(x => b64ToBytes(String(x.dataUrl).split(',')[1]));\n  let total = 0; bufs.forEach(b => { total += b.length; });\n  const all = new Uint8Array(total); let off = 0;\n  bufs.forEach(b => { all.set(b, off); off += b.length; });\n  return { dataUrl: 'data:' + mime + ';base64,' + bytesToB64(all), mode: '分段合成后拼成一段（' + parts.length + ' 段）' };\n}\n/* 只生成并留存语音，不播放（「保存语音」用） */\nasync function ttsRefOnly(charId, text) {\n  if (!API || !API.voice || !API.voice.tts || !charId || !text) return '';\n  const lk = aiLock('生成语音');\n  try {\n    const r = await ttsJoined(charId, text);\n    if (!r || !r.dataUrl) return '';\n    const put = await sdk(() => API.media.put({ dataUrl: r.dataUrl }), null);\n    return (put && put.ref) ? put.ref : '';\n  } catch (e) { return ''; }\n  finally { aiUnlock(lk); }\n}\nasync function openStoryItem(item) {\n  if (!item) return;\n  S.story = Object.assign({}, item, {\n    playing: false, idx: item.idx || 0,\n    audioRefs: (item.audioRefs || []).slice()\n  });\n  go('story');\n}\nasync function playStoryFrom(from) {\n  const st = S.story; if (!st) return;\n  st.playing = true; st.idx = from || 0; render();\n  while (st.playing && st.idx < st.paras.length) {\n    const i = st.idx;\n    const el = document.getElementById('para' + i);\n    if (el) { el.classList.add('playing'); el.scrollIntoView({ block: 'center', behavior: 'smooth' }); }\n    const ref = (st.audioRefs || [])[i] || '';\n    let ok = ref ? await playRef(ref) : false;      // 已有留存语音，直接重播\n    if (!st.playing) break;\n    if (!ok) {\n      const r = await ttsPlay(st.charId, st.paras[i]);\n      ok = r.ok;\n      if (r.ref) { st.audioRefs = st.audioRefs || []; st.audioRefs[i] = r.ref; await saveStory(st); }\n    }\n    if (!st.playing) break;\n    if (!ok) await new Promise(r => setTimeout(r, Math.min(20000, Math.max(3000, st.paras[i].length * 260))));\n    if (el) el.classList.remove('playing');\n    st.idx = i + 1;\n    await saveStory(st);                            // 每段都存进度，离开后能接着听\n  }\n  if (st.idx >= st.paras.length) { st.playing = false; toast('故事讲完了，晚安'); }\n  await saveStory(st);\n  render();\n}\nlet alarmTimer = null, lastAlarmFire = '';\nfunction startAlarmLoop() {\n  if (alarmTimer) return;\n  alarmTimer = setInterval(checkAlarm, 20000);\n  checkAlarm();\n}\nasync function checkAlarm() {\n  const a = cfg('alarm');\n  if (!a || !a.enabled || !a.time) return;\n  const now = new Date(), cur = pad2(now.getHours()) + ':' + pad2(now.getMinutes());\n  if (cur !== a.time || lastAlarmFire === dkey() + cur) return;\n  lastAlarmFire = dkey() + cur;\n  await fireAlarm(a);\n}\nasync function fireAlarm(a) {\n  const cid = a.charId || anyCharId();\n  let text = '';\n  try { text = await pGen('wake.line', { time: a.time + ' 的闹钟响了，' }, [cid]); } catch (e) { }\n  if (!text) text = '该起床了，别赖床。';\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  notify('⏰ ' + a.time, text);\n  openSheet(`<h3>⏰ ${esc(a.time)} 起床了</h3>\n    <div class=\"row mt10\">${charAvatar(charById(cid))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:14px\">${esc(text)}</div></div>\n    <div class=\"row mt14\" style=\"gap:10px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">再睡五分钟</button>\n    <button class=\"btn sleep grow\" data-act=\"stopAlarm\">我起来了</button></div>`);\n  if (!a.repeat) { cfg('alarm').enabled = false; saveSettings(true); }\n  if (shouldSpeak('wake')) speak(cid, text);\n  if (cid) await syncTimeline(cid, `闹钟 ${a.time} 响了，${charName(cid)}负责叫用户起床。`, 'alarm_fired', { time: a.time });\n  await syncChatLine(cid, text, 'assistant');\n  render();\n}\nasync function scheduleAlarm(a, silent) {\n  if (!API || !API.tasks || !a || !a.time) return;\n  const now = new Date(), parts = String(a.time).split(':');\n  const target = new Date(now);\n  target.setHours(Number(parts[0]), Number(parts[1]), 0, 0);\n  if (target.getTime() <= now.getTime()) target.setDate(target.getDate() + 1);\n  const who = charName(a.charId || anyCharId());\n  await sdk(() => API.tasks.schedule({\n    id: 'focus_alarm_' + a.time, delayMs: Math.max(60000, target.getTime() - now.getTime()),\n    actions: [\n      { type: 'notification', title: '⏰ ' + a.time, body: who + ' 在叫你起床' },\n      { type: 'shell.notify', title: '⏰ ' + a.time, body: who + ' 在叫你起床' }\n    ]\n  }));\n  /* 系统闹钟兜底：早上页面必然是死的，宿主任务只能补跑 —— 只有系统时钟的闹钟能准时响。\n     只在用户主动保存时立（boot 重排不重复立）；改时间不会自动撤旧闹钟。 */\n  if (!silent) bookSystemAlarm(Number(parts[0]), Number(parts[1]), 'TA叫你起床');\n}\n/* ==========================================================\n   备份 · 打包与下载\n   ========================================================== */\nfunction legacyBlobDownload(name, text, mime) {\n  try {\n    const blob = new Blob([text], { type: mime || 'application/json' });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement('a');\n    a.href = url; a.download = name; a.rel = 'noopener';\n    document.body.appendChild(a); a.click(); a.remove();\n    setTimeout(() => { try { URL.revokeObjectURL(url); } catch (e) { } }, 5000);\n    return true;\n  } catch (e) { return false; }\n}\nfunction utf8B64(s) {\n  try {\n    const bytes = new TextEncoder().encode(String(s));\n    let bin = '';\n    const CH = 0x8000;\n    for (let i = 0; i < bytes.length; i += CH) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + CH));\n    return btoa(bin);\n  } catch (e) { return ''; }\n}\n/* 导出统一入口：APK 里走宿主 media.download（原生分块写盘），网页回退 <a download>。\n   返回 true = 导出已发起（原生路径是异步的，失败会自动落回 legacy）。 */\nfunction blobDownload(name, text, mime) {\n  try {\n    if (API && API.media && API.media.download) {\n      Promise.resolve(API.media.download({ dataUrl: 'data:' + (mime || 'application/json') + ';base64,' + utf8B64(text), filename: name }))\n        .catch(() => { legacyBlobDownload(name, text, mime); });\n      return true;\n    }\n  } catch (e) { }\n  return legacyBlobDownload(name, text, mime);\n}\n/* 把媒体引用批量换回 dataURL（语音/图片的真实字节） */\nasync function collectMedia(refs) {\n  const out = {};\n  const uniq = [];\n  (refs || []).forEach(r => { if (r && uniq.indexOf(r) < 0) uniq.push(r); });\n  for (const r of uniq) {\n    const g = await sdk(() => API.media.get({ ref: r }), null);\n    if (g && g.dataUrl) out[r] = g.dataUrl;\n  }\n  return out;\n}\nasync function buildBackup(withMedia) {\n  const pack = {\n    v: 2, at: Date.now(), app: '角色陪伴专注',\n    settings: S.settings, sessions: S.sessions, priv: S.priv, pub: S.pub, puns: S.puns,\n    gifts: S.gifts, ledger: S.ledger, sleeps: S.sleeps, qbank: S.qbank, rewards: S.rewards,\n    fav: S.fav, gen: S.gen, stories: S.stories, appts: S.appts,\n    todos: S.todos, invites: S.invites, qa: S.qa,\n    books: S.books, cards: S.cards, rlogs: S.rlogs, media: {}\n  };\n  if (withMedia) {\n    const refs = [];\n    (S.fav || []).forEach(f => { if (f.ref) refs.push(f.ref); });\n    (S.stories || []).forEach(s => {\n      (s.audioRefs || []).forEach(r => { if (r) refs.push(r); });\n      if (s.wholeRef) refs.push(s.wholeRef);\n    });\n    pack.media = await collectMedia(refs);\n  }\n  return pack;\n}\n/* ==========================================================\n   动作 · 备份\n   ========================================================== */\nObject.assign(ACTIONS, {\n  stopAlarm: () => { stopVoice(); closeAllSheets(); toast('早上好'); },\n  exportData: () => {\n    const favMedia = (S.fav || []).filter(f => f.ref).length;\n    const storyMedia = (S.stories || []).reduce((n, s) => n + (s.audioRefs || []).filter(Boolean).length + (s.wholeRef ? 1 : 0), 0);\n    openSheet(`<h3>导出备份</h3>\n      <div class=\"tiny\">备份内容：设置、专注与睡眠记录、预约专注、题库、错题与私密记忆、惩罚、奖励、账本、礼物、生成记录、收藏夹（含文件夹层级）、睡前故事、待办清单、TA 的邀请。</div>\n      <div class=\"kv mt10\"><span class=\"k\">带媒体（语音＋图片）</span><span>${favMedia} 个收藏媒体 · ${storyMedia} 段故事语音</span></div>\n      <div class=\"tiny\">带媒体会把语音、图片的原始文件一起打包，体积可能很大（几十 MB），所以会<b>下载成 .json 文件</b>；不带媒体的备份很小，可以直接复制文字。</div>\n      <button class=\"btn primary block mt12\" data-act=\"exportDo\" data-media=\"1\">⬇️ 下载备份（含语音和图片）</button>\n      <button class=\"btn block mt8\" data-act=\"exportDo\" data-media=\"0\">⬇️ 下载备份（不含媒体，体积小）</button>\n      <button class=\"btn block ghost mt8\" data-act=\"exportText\">只看文字版（可复制）</button>`);\n  },\n  exportDo: async el => {\n    const withMedia = el.dataset.media === '1';\n    toast(withMedia ? '正在打包（含媒体，可能要几十秒）…' : '正在打包…');\n    const pack = await buildBackup(withMedia);\n    const txt = JSON.stringify(pack);\n    const name = 'focus_companion_backup_' + dkey() + (withMedia ? '_full' : '_lite') + '.json';\n    const ok = blobDownload(name, txt);\n    toast(ok ? ('已下载 ' + name + '（约 ' + Math.max(1, Math.round(txt.length / 1024)) + ' KB）') : '下载被拦截，改用「只看文字版」复制');\n  },\n  exportText: async () => {\n    const pack = await buildBackup(false);\n    const txt = JSON.stringify(pack);\n    openSheet(`<h3>备份（文字版）</h3><div class=\"tiny\">复制下面全部内容保存起来；导入时粘贴回来。这一版不含语音与图片文件。</div>\n      <textarea style=\"min-height:170px;margin-top:10px\" id=\"exportBox\">${esc(txt)}</textarea>\n      <div class=\"row mt10\" style=\"gap:10px\"><button class=\"btn grow\" data-act=\"copyExport\">复制</button>\n      <button class=\"btn primary grow\" data-act=\"closeSheet\">关闭</button></div>`);\n  },\n  copyExport: () => {\n    const t = document.getElementById('exportBox');\n    try { t.select(); document.execCommand('copy'); toast('已复制'); } catch (e) { toast('请长按手动复制'); }\n  },\n  importData: () => { openSheet(`<h3>导入备份</h3>\n    <div class=\"tiny\">选备份文件，或把备份内容粘贴到下面。导入会覆盖当前数据（含收藏夹与生成记录）。</div>\n    <input type=\"file\" id=\"importFile\" accept=\".json,.txt\" style=\"margin-top:10px\">\n    <textarea id=\"importBox\" style=\"min-height:130px;margin-top:10px\" placeholder=\"或在这里粘贴备份内容\"></textarea>\n    <button class=\"btn warn block mt10\" data-act=\"importDataDo\">覆盖导入</button>`); },\n  importDataDo: async () => {\n    let raw = ((document.getElementById('importBox') || {}).value || '').trim();\n    const fileEl = document.getElementById('importFile');\n    if (!raw && fileEl && fileEl.files && fileEl.files[0]) raw = await fileEl.files[0].text();\n    if (!raw) { toast('请选择文件或粘贴内容'); return; }\n    const pack = parseJSON(raw);\n    if (!pack || !pack.settings) { toast('内容无法解析'); return; }\n    const mediaN = Object.keys(pack.media || {}).length;\n    const ok = await confirmBox('确认导入？', '当前数据会被覆盖（含收藏夹与生成记录）。' + (mediaN ? '\\n本次备份含 ' + mediaN + ' 个语音/图片文件，会一起恢复。' : ''), '覆盖导入');\n    if (!ok) return;\n    S.settings = Object.assign(defaults(), pack.settings);\n    await saveSettings(true);\n    // 先把媒体写回媒体库，建立「旧引用 → 新引用」映射\n    const refMap = {};\n    const media = pack.media || {};\n    for (const oldRef of Object.keys(media)) {\n      const put = await sdk(() => API.media.put({ dataUrl: media[oldRef] }), null);\n      if (put && put.ref) refMap[oldRef] = put.ref;\n    }\n    const writeAll = async (table, arr) => {\n      for (const o of await DB.list(table)) await DB.remove(table, o.id);\n      for (const item of (arr || [])) await DB.create(table, item);\n    };\n    await writeAll(T.PRIV, pack.priv);\n    await writeAll(T.PUB, pack.pub);\n    await writeAll(T.LEDGER, pack.ledger);\n    await writeAll(T.GIFT, pack.gifts);\n    await writeAll(T.SLEEP, pack.sleeps);\n    await writeAll(T.QBANK, pack.qbank);\n    await writeAll(T.SESSION, (pack.sessions || []).map(s => ({ data: s })));\n    await writeAll(T.PUN, (pack.puns || []).map(p => ({ data: p })));\n    await writeAll(T.REWARD, (pack.rewards || []).map(p => ({ data: p })));\n    await writeAll(T.GEN, (pack.gen || []).map(g => { const c = Object.assign({}, g); delete c.id; return c; }));\n    await writeAll(T.FAV, (pack.fav || []).map(f => {\n      const c = Object.assign({}, f); delete c.id;\n      if (c.ref) c.ref = refMap[c.ref] || c.ref;\n      return c;\n    }));\n    await writeAll(T.APPT, (pack.appts || []).map(a => { const c = Object.assign({}, a); delete c.id; return c; }));\n    await writeAll(T.TODO, (pack.todos || []).map(a => { const c = Object.assign({}, a); delete c.id; return c; }));\n    await writeAll(T.INVITE, (pack.invites || []).map(a => { const c = Object.assign({}, a); delete c.id; return c; }));\n    await writeAll(T.QA, (pack.qa || []).map(a => { const c = Object.assign({}, a); delete c.id; return c; }));\n    await writeAll(T.STORY, (pack.stories || []).map(s => {\n      const c = Object.assign({}, s); delete c.id; delete c.dbId;\n      c.audioRefs = (c.audioRefs || []).map(r => refMap[r] || '');\n      if (c.wholeRef && refMap[c.wholeRef]) c.wholeRef = refMap[c.wholeRef];\n      return c;\n    }));\n    /* 背书模块：词本与卡片要保住 id 对应关系 */\n    await writeAll(T.BOOK, (pack.books || []).map(b => { const c = Object.assign({}, b); delete c.id; return c; }));\n    await writeAll(T.CARD, (pack.cards || []).map(c0 => { const c = Object.assign({}, c0); delete c.id; return c; }));\n    await writeAll(T.RLOG, (pack.rlogs || []).map(r => { const c = Object.assign({}, r); delete c.id; return c; }));\n    closeAllSheets(); await loadAll(); toast('导入完成' + (mediaN ? '（含 ' + mediaN + ' 个媒体文件）' : '')); render();\n  },\n  clearAll: async () => {\n    const ok = await confirmBox('清空全部数据？', '设置、记录、题库、账本都会被删除，不可恢复。', '清空');\n    if (!ok) return;\n    for (const p of (S.wlPasses || [])) cancelWlCheckinNative(p.id);\n    let cleared = false;\n    if (API && API.app && typeof API.app.clearData === 'function') {\n      const r = await sdk(() => API.app.clearData({}), null);\n      cleared = !!(r && r.ok);\n    }\n    if (!cleared) {\n      for (const t of Object.values(T)) {\n        for (const r of await DB.list(t)) await DB.remove(t, r.id);\n      }\n    }\n    S.settings = defaults();\n    const r2 = await DB.create(T.SET, { data: S.settings });\n    S.settingId = r2 ? r2.id : null;\n    await loadAll(); closeAllSheets(); toast('已清空'); render();\n  }\n});\n/* ==========================================================\n   TA 的心愿：你陪他一起实现他心底那件事\n   ----------------------------------------------------------\n   这不是「TA 满足你的愿望」，而是反过来：\n\n   · 心愿由 TA 自己说出来（AI 按人设/记忆生成），或者你替他写；\n     那是他心底最想要的东西——想和你一起去的地方、想一起完成\n     的事、想看到的某个画面。\n   · 推进心愿的只有一种东西：你们一起专注。每通过一次考核，\n     这段专注的分钟数就加进心愿进度。\n   · 攒到需要的分钟数 → 心愿就能「真正实现」：APP 会写出实现\n     的那一刻的画面 + TA 说的话，做一张卡写进聊天室。\n   · 连坐：你没做到（考核没过、中途离开、爽约），TA 那边的\n     进度也跟着往后退一截——你们是一起的。\n   · 全程没有数值可以手动加，也没有「补一点」的按钮。\n   ========================================================== */\nfunction wishNeedMin() { return clamp(Number(cfg('wishNeedMin') || 600), 30, 20000); }\nfunction wishPenaltyRate() { return clamp(Number(cfg('wishPenalty') || 50), 0, 200); }\nfunction wishAll() { return (cfg('wishes') || []).slice().sort((a, b) => (b.at || 0) - (a.at || 0)); }\nfunction wishOf(cid) {\n  const arr = wishAll().filter(w => String(w.charId) === String(cid) && (w.status === 'active' || w.status === 'ready'));\n  return arr[0] || null;\n}\nfunction wishDoneList(cid) { return wishAll().filter(w => String(w.charId) === String(cid) && w.status === 'done'); }\nfunction wishNeedOf(w) { return w ? clamp(Number(w.need) || wishNeedMin(), 30, 20000) : wishNeedMin(); }\nfunction wishGain(w) { return w ? Math.max(0, Math.round(Number(w.gained) || 0)) : 0; }\nfunction wishPct(w) { return w ? clamp(Math.round(wishGain(w) / wishNeedOf(w) * 100), 0, 100) : 0; }\nfunction wishLeftMin(w) { return w ? Math.max(0, wishNeedOf(w) - wishGain(w)) : 0; }\nfunction wishReady(w) { return !!w && wishGain(w) >= wishNeedOf(w); }\nfunction wishEntries(w) { return (w && w.entries) || []; }\nfunction wishBrief(cid) {\n  const w = wishOf(cid);\n  if (!w) return '（TA 还没说出他心底那件事）';\n  const done = wishDoneList(cid).length;\n  return w.text + '（一起攒了 ' + wishGain(w) + ' / ' + wishNeedOf(w) + ' 分钟'\n    + (wishReady(w) ? '，可以实现它了' : '，还差 ' + wishMinText(wishLeftMin(w))) + '）'\n    + (done ? '；你们已经一起实现过 ' + done + ' 件' : '');\n}\nfunction wishMinText(m) {\n  m = Math.max(0, Math.round(m));\n  if (m >= 60) return Math.floor(m / 60) + ' 小时' + (m % 60 ? ' ' + (m % 60) + ' 分' : '');\n  return m + ' 分钟';\n}\n/* 推进 / 连坐扣减：d 是分钟。正 = 离 TA 的心愿更近一点；负 = 被拖回来一点 */\nasync function addWishProgress(cid, d, why, kind) {\n  d = Math.round(Number(d) || 0);\n  if (!cid || !d) return;\n  const w = wishOf(cid);\n  if (!w) return;\n  w.gained = Math.max(0, wishGain(w) + d);\n  w.entries = (w.entries || []).concat([{ at: Date.now(), d: d, why: String(why || '').slice(0, 60), kind: kind || (d > 0 ? 'focus' : 'connect') }]).slice(-150);\n  if (wishReady(w) && w.status !== 'ready') {\n    w.status = 'ready'; w.readyAt = Date.now();\n    await saveSettings(true);\n    await addPublic('wish', `${charName(cid)}心底那件事「${w.text}」已经攒够了，可以实现它了。`, cid, {});\n    await syncTimeline(cid, `用户为了你最想要的那件事「${w.text}」累计一起专注到 ${wishMinText(wishGain(w))}，够实现了。`, 'wish_ready', {});\n    toast('攒够了：TA 心底那件事可以实现它了');\n    if (cfg('wishNotice') !== false) wishSay(cid, w);\n    if (S.ready) render();\n    return;\n  }\n  await saveSettings();\n  if (S.session) {\n    pushMsg(S.session, 'sys', (d > 0 ? '↑ ' : '↓ ') + '你们一起的事 ' + (d > 0 ? '+' : '') + d + ' 分钟：' + why + '（' + wishGain(w) + '/' + wishNeedOf(w) + ' 分钟）');\n    await saveSession();\n  }\n  toast((d > 0 ? '+ ' : '− ') + Math.abs(d) + ' 分钟 · ' + why);\n  if (S.ready) render();\n}\n/* 连坐：你没做到，TA 那边的进度也跟着退一截 */\nasync function wishConnectHit(cid, mins, why) {\n  /* 连坐已移除：心愿进度不会再因为你的失误而倒退 */\n  return;\n}\n/* 让 TA 说出他心底最想要的那件事 */\nasync function wishGenAI(cid) {\n  if (!cid) { toast('还没有角色'); return null; }\n  if (S.loading) { toast('正在生成，请稍候…'); return null; }\n  S.loading = 'wishgen'; render();\n  const cur = wishOf(cid);\n  let data = null;\n  try {\n    const text = await pGen('wish.gen', {\n      goal: goalBrief(), focusMin: cfg('focusMin') || 25,\n      existing: cur ? ('（他上次说的是：' + cur.text + '，可以换一个更深的，也可以就是它）') : '（还没有说过）'\n    }, [cid]);\n    data = parseJSON(text);\n  } catch (e) { data = null; }\n  S.loading = '';\n  if (!data || !data.text) { toast('AI 没给出可用结果，可以自己替他写一个'); render(); return null; }\n  const w = await wishMake(cid, { text: String(data.text), why: String(data.why || ''), from: 'char' });\n  render();\n  return w;\n}\n/* 建一个心愿（TA 自己说的 / 你替他写） */\nasync function wishMake(cid, o) {\n  if (!cid) return null;\n  const old = wishOf(cid);\n  if (old && o.keepOld !== true) { old.status = 'dropped'; old.dropAt = Date.now(); }\n  const w = {\n    id: uid(), charId: cid, text: String(o.text || '').slice(0, 70), why: String(o.why || '').slice(0, 200),\n    from: o.from === 'me' ? 'me' : 'char', need: clamp(Number(o.need) || wishNeedMin(), 30, 20000),\n    gained: 0, entries: [], at: Date.now(), status: 'active'\n  };\n  S.settings.wishes = (cfg('wishes') || []).concat([w]);\n  await saveSettings(true);\n  await wishTell(cid, w);\n  return w;\n}\n/* 把心愿告诉 TA：写进记忆 + 聊天历史 */\nasync function wishTell(cid, w) {\n  if (!cid || !w) return;\n  const need = wishNeedOf(w);\n  await syncTimeline(cid, `你把心底最想要的那件事告诉了用户：「${w.text}」${w.why ? '（' + w.why + '）' : ''}。说好只有你们一起专注、累计 ${wishMinText(need)}，这件事才能真正实现。`, 'wish_make', {});\n  await syncChatLine(cid, '（我说了一件对我很重要的事）' + w.text + '。我一直在等这件事，只有你陪我一起把这些小时攒下来，它才会真的发生。', 'assistant');\n  await addPublic('wish', `${charName(cid)}心底的事：${w.text}（需要一起专注 ${wishMinText(need)}）`, cid, {});\n}\n/* 攒满 → TA 先说一句 */\nasync function wishSay(cid, w) {\n  if (!cid || !w) return;\n  let text = '';\n  try { text = await pGen('bond.line', { wish: w.text, need: String(wishMinText(wishNeedOf(w))), why: '你们一起把它攒够了' }, [cid]); } catch (e) { text = ''; }\n  if (!text) text = '那件事……我们真的做到了。走吧，我带你去看。';\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  toast(text);\n  if (shouldSpeak('cheer')) speak(cid, text);\n  await syncChatLine(cid, text, 'assistant');\n  if (S.session) { pushMsg(S.session, 'char', text, { charId: cid, kind: 'wish' }); await saveSession(true); }\n}\n/* 真正实现的那一刻 */\nasync function wishFinishDo(cid, w) {\n  if (!cid || !w) return;\n  if (!wishReady(w)) { toast('还没攒够'); return; }\n  if (S.loading) { toast('正在生成，请稍候…'); return; }\n  S.loading = 'wishfin'; render();\n  const mins = wishGain(w);\n  let scene = '', line = '';\n  try {\n    const text = await pGen('wish.finish', { text: w.text, why: w.why || '（没写原因）', min: wishMinText(mins), days: Math.max(1, Math.round((Date.now() - (w.at || Date.now())) / 86400000)) }, [cid]);\n    const d = parseJSON(text);\n    if (d && (d.scene || d.line)) { scene = String(d.scene || ''); line = String(d.line || ''); }\n  } catch (e) { }\n  S.loading = '';\n  if (!scene && !line) {\n    scene = `那一刻来得比想象中安静。${charName(cid)}站在原地愣了两秒，才慢慢笑起来——这就是他一直想要的那件事，是你陪着他一起把这段时间一小时一小时攒出来的。`;\n    line = '你真的陪我做到了。';\n  }\n  scene = scene.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  line = line.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  w.status = 'done'; w.doneAt = Date.now(); w.finalScene = scene; w.finalLine = line; w.doneMin = mins;\n  await saveSettings(true);\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'system', historyRole: 'system',\n    summary: 'TA 心底那件事实现了：' + w.text, historyText: '[你们一起做到的] ' + w.text + '。' + scene + ' ' + line,\n    card: {\n      appLabel: '角色陪伴专注', title: 'TA 心底那件事，实现了', subtitle: 'MADE IT', status: '你们一起做到的',\n      accentColor: '#5eead4', height: 320,\n      sections: [\n        { title: '他等了很久的', rows: [{ label: '心愿', value: w.text }] },\n        { title: '你们一起攒下的', rows: [{ label: '专注投入', value: wishMinText(mins) }] }\n      ],\n      html: '<div style=\"padding:14px;font:13.5px/1.8 -apple-system,BlinkMacSystemFont,sans-serif\">'\n        + '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 一起实现</div>'\n        + '<div style=\"margin-top:8px;font-weight:600\">' + esc(w.text) + '</div>'\n        + '<div style=\"margin-top:8px;white-space:pre-wrap;color:#c8cfe3\">' + esc(scene) + '</div>'\n        + '<div style=\"margin-top:10px;color:#e8ecf5\">「' + esc(line) + '」</div></div>'\n    }\n  }), null);\n  await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n  await addPublic('wish', `${charName(cid)}心底那件事实现了：${w.text}｜${scene}`, cid, {});\n  await syncTimeline(cid, `你和用户一起把「${w.text}」真正实现了（累计专注 ${wishMinText(mins)}）。那一刻：${scene}｜你说：${line}`, 'wish_done', {});\n  toast('实现了：' + w.text);\n  if (cfg('wishNotice') !== false && line && shouldSpeak('cheer')) speak(cid, line);\n  render();\n}\n/* 连坐台词：TA 的任务被拖了 / 被推了 */\nasync function selfTaskSay(cid, selfTask, progress, why, up) {\n  if (!cid || cfg('selfTaskConnect') === false) return;\n  let text = '';\n  try { text = await pGen('connect.line', { selfTask: selfTask || '自己的事', progress: String(Math.round(progress || 0)), why: why || '' }, [cid]); } catch (e) { text = ''; }\n  if (!text) text = up ? '你带着我一起往前走了，谢了。' : '……因为你，我这件事又得往后拖了。';\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  toast(text);\n  if (shouldSpeak('punish')) speak(cid, text);\n  await syncChatLine(cid, text, 'assistant');\n  if (S.session) { pushMsg(S.session, 'char', text, { charId: cid, kind: 'connect' }); await saveSession(true); }\n}\n/* 兼容旧调用点：不再有任何数值，只把事件写进角色记忆（保留空实现，防止旧路径报错） */\nasync function addBond(cid, d, why) {\n  if (!cid || !why) return;\n  await syncTimeline(cid, `【记录了这件事】${why}`, 'record', {});\n}\n/* 旧的「好感度」字段已废弃，这里保留只读桩，防止老备份/旧路径报错 */\nconst BOND_TIERS = [[0, '—', '']];\nfunction bondOf() { return { v: 0, events: [], at: 0 }; }\nfunction bondTier() { return [0, '—', '']; }\nfunction bondNextAt() { return 0; }\nfunction bondLabel() { return ''; }\nfunction bondPct() { return 0; }\n/* ==========================================================\n   专注币：把专注时长变成能花的东西\n   ========================================================== */\n/* v1.9.2 校验标记 I */\nconst COIN_SHOP = [\n  { k: 'praise', name: '让 TA 夸你一句', cost: 50, icon: '💬', desc: '现在就让 TA 认真夸你一句，并读出来。' },\n  { k: 'pass', name: '免罚卡', cost: 200, icon: '🎫', desc: '下次触发惩罚时，可以在惩罚锁定页直接免掉这一次（一次用一张）。' },\n  { k: 'wall', name: '一张专属壁纸', cost: 300, icon: '🖼', desc: '让 TA 为你生成一张只属于这次的留念壁纸，直接进壁纸库（不上锁）。' },\n  { k: 'wish', name: '跟 TA 提一个愿望', cost: 400, icon: '🌠', desc: '把愿望写进聊天室，由 TA 亲口答应并兑现。' },\n  { k: 'skipday', name: '今天放你一马', cost: 600, icon: '🕊', desc: '免掉今天的违规惩罚（记录仍然保留），TA 会念一句，但不再罚你。' }\n];\n/* 余额允许为负：失约扣币可以把它扣成负的（见「监督与惩罚 → 失约扣专注币」）。\n   兑换时仍然会拦「余额不够」，所以负数不会白送东西。 */\nfunction coinBal() { return Math.round(Number(cfg('coinBalance') || 0)); }\n/* 免罚卡的单价：从兑换商店里取，保证「惩罚页现换」和「专注币页兑换」永远同价 */\nfunction freePassCost() {\n  const it = (typeof COIN_SHOP !== 'undefined' ? COIN_SHOP : []).filter(x => x.k === 'pass')[0];\n  return it ? Number(it.cost) : 200;\n}\nfunction coinRate() { return clamp(Number(cfg('coinRate') != null ? cfg('coinRate') : 1) || 1, 0.1, 10); }\nfunction coinBonus() { return clamp(Number(cfg('coinBonus') != null ? cfg('coinBonus') : 20) || 0, 0, 200); }\nfunction coinLog() { return (S.settings.coinLog || []).slice().sort((a, b) => b.at - a.at); }\nfunction coinToday() { const k = dkey(); return sum(coinLog().filter(x => x.d > 0 && dkey(new Date(x.at)) === k).map(x => x.d)); }\nfunction coinTotal() { return sum(coinLog().filter(x => x.d > 0).map(x => x.d)); }\nasync function coinAdd(d, why) {\n  d = Math.round(d);\n  if (!d) return 0;\n  /* 不再把余额夹在 0 以上 —— 扣币（失约扣币/惩罚扣币）允许扣成负数 */\n  S.settings.coinBalance = coinBal() + d;\n  S.settings.coinLog = (S.settings.coinLog || []).concat([{ at: Date.now(), d: d, why: why || '' }]).slice(-200);\n  await saveSettings();\n  if (d > 0) toast('+' + d + ' 专注币 · ' + why);\n  return d;\n}\n/* ---------- 违规扣专注币 ----------\n   · 开关默认关；打开后只扣你填了数值的那几类（填 0 就不扣）。\n   · 和原有惩罚并行：转账/做题/抄写照旧，扣币只是额外再加一笔。\n   · 余额可以为负 —— 扣成负数也是真实数值，兑换时仍会拦「不够」。 */\nfunction coinDeductCfg() {\n  const base = { on: false, miss: 50, leave: 0, fail: 0, timeout: 0 };\n  const cur = cfg('coinDeduct');\n  return Object.assign(base, (cur && typeof cur === 'object' && !Array.isArray(cur)) ? cur : {});\n}\nasync function coinDeductFor(reason, key) {\n  const c = coinDeductCfg();\n  if (!c.on) return 0;\n  const n = Math.round(Number(c[key] || 0));\n  if (!n) return 0;\n  await coinAdd(-n, reason + ' · 扣专注币');\n  toast('− ' + n + ' 专注币（' + reason + '）· 余额 ' + coinBal());\n  return n;\n}\nasync function coinSpend(kind) {\n  const it = COIN_SHOP.filter(x => x.k === kind)[0];\n  if (!it) return false;\n  if (coinBal() < it.cost) { toast('专注币不够：还差 ' + (it.cost - coinBal()) + ' 点'); return false; }\n  const cid = anyCharId();\n  if (!cid && it.k !== 'pass') { toast('还没有角色'); return false; }\n  await coinAdd(-it.cost, '兑换：' + it.name);\n  if (it.k === 'pass') {\n    S.settings.freePass = (Number(cfg('freePass')) || 0) + 1;\n    await saveSettings();\n    toast('已获得一张免罚卡（现有 ' + S.settings.freePass + ' 张）');\n  } else if (it.k === 'skipday') {\n    S.settings.pardonDate = dkey();\n    if (cid) await syncTimeline(cid, `用户花专注币换了「今天放他一马」，今天的违规只记录、不再罚。`, 'coin_skipday', {});\n    await saveSettings();\n    toast('今天放你一马：今天的违规只记录、不罚');\n  } else if (it.k === 'praise') await coinPraise(cid);\n  else if (it.k === 'wall') await coinWall(cid);\n  else if (it.k === 'wish') { closeAllSheets(); ACTIONS.coinWishAsk(); return true; }\n  if (cid) await addBond(cid, 1, '在你身上花了专注币');\n  render();\n  return true;\n}\nasync function coinPraise(cid) {\n  const mins = Math.round(coinTotal());\n  let text = '';\n  try { text = await pGen('coin.praise', { minutes: mins }, [cid]); } catch (e) { text = ''; }\n  if (!text) text = '这段时间你都坚持下来了，我看到了。';\n  text = text.replace(/^[\"'“‘\\s]+|[\"'”’\\s]+$/g, '');\n  toast(text);\n  if (shouldSpeak('cheer')) speak(cid, text);\n  await syncChatLine(cid, text, 'assistant');\n  await addPublic('coin', `${charName(cid)}用专注币换来的夸赞：${text}`, cid, {});\n  if (S.session) { pushMsg(S.session, 'char', text, { charId: cid, kind: 'coin' }); await saveSession(true); }\n}\nasync function coinWall(cid) {\n  if (!API || !API.ai || !API.ai.generateImage) { toast('生图不可用，请先在小手机设置里配置生图 API'); return; }\n  const c = charById(cid);\n  toast('正在生成你的专属壁纸…');\n  try {\n    const r = await genImgLogged('img.coin', '专注币兑换壁纸', promptText('img.coin', { charName: (c && c.name) ? c.name : '一位角色', coin: coinBal() + ' 点' }), cid, () => API.ai.generateImage({\n      prompt: promptText('img.coin', { charName: (c && c.name) ? c.name : '一位角色', coin: coinBal() + ' 点' }),\n      characterId: cid || undefined, useReferenceImage: true, timeoutMs: 120000\n    }));\n    if (r && r.dataUrl) {\n      const item = await saveAlbum('reward', r.dataUrl, { title: '专注币换的壁纸 · ' + dkey(), note: '专注币兑换', locked: false, charId: cid });\n      toast(item ? '壁纸已进壁纸库，可直接保存' : '壁纸生成了，但入库失败');\n      if (cid) await syncTimeline(cid, `用户花专注币换了一张你给的壁纸。`, 'coin_wall', {});\n    } else toast('生图没有返回图片');\n  } catch (e) { toast('生图失败：' + ((e && e.message) || e)); }\n}\nasync function coinWishDone(cid, wish) {\n  await addPublic('coin', `用户用专注币许了一个愿：${wish}`, cid, {});\n  if (!cid) return;\n  const askedAt = Date.now();\n  let line = '';\n  try { line = await pGen('coin.wish', { wish: wish }, [cid]); } catch (e) { line = ''; }\n  if (!line) line = '行，这个我记下了，会给你。';\n  line = line.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  await sdk(() => API.chat.sendCard({\n    characterId: cid, role: 'system', historyRole: 'system',\n    summary: '专注币许愿：' + wish,\n    historyText: '[专注币·许愿] 用户用攒下的专注币向' + charName(cid) + '提了一个愿望：' + wish,\n    card: {\n      appLabel: '角色陪伴专注', title: 'TA 用专注币许了个愿', subtitle: 'FOCUS COIN', status: '等你兑现',\n      accentColor: '#ffc978', height: 230,\n      sections: [{ title: '愿望内容', rows: [{ label: '由你兑现', value: wish }] }]\n    }\n  }), null);\n  try { await API.chat.requestReply({ characterId: cid }); } catch (e) { }\n  await syncChatLine(cid, line, 'assistant');\n  await syncTimeline(cid, `用户花专注币向你许愿：${wish}，你的回应：${line}`, 'coin_wish', {});\n  if (shouldSpeak('cheer')) speak(cid, line);\n  toast('已写进聊天室：' + line);\n}\n/* ==========================================================\n   长期目标与倒计时\n   ========================================================== */\nfunction goals() { return (cfg('goals') || []).slice(); }\nfunction goalDays(g) {\n  const t = new Date(String(g.date) + 'T00:00:00').getTime();\n  const n = new Date(); n.setHours(0, 0, 0, 0);\n  return Math.round((t - n.getTime()) / 86400000);\n}\nfunction goalPhase(d) {\n  if (d > 60) return '积累期';\n  if (d > 21) return '进行中';\n  if (d > 7) return '冲刺期';\n  if (d > 1) return '最后一周';\n  if (d === 1) return '明天就是';\n  if (d === 0) return '就是今天';\n  return '已经过去';\n}\nfunction activeGoal() {\n  const list = goals().filter(g => !g.done);\n  if (!list.length) return null;\n  const fut = list.filter(g => goalDays(g) >= 0).sort((a, b) => goalDays(a) - goalDays(b));\n  return fut[0] || list.sort((a, b) => goalDays(b) - goalDays(a))[0];\n}\nfunction goalBrief() {\n  const g = activeGoal();\n  if (!g) return '（还没设定长期目标）';\n  const d = goalDays(g);\n  return `「${g.name}」${d >= 0 ? '还有 ' + d + ' 天' : '已经过去 ' + (-d) + ' 天'}（${goalPhase(d)}）`;\n}\nfunction goalPromptLine() {\n  const g = activeGoal();\n  if (!g) return '（用户没有设定长期目标，督促时就专注当下这段。）';\n  const d = goalDays(g);\n  return `用户的长期目标是「${g.name}」${g.note ? '（' + g.note + '）' : ''}，${d >= 0 ? '还剩 ' + d + ' 天' : '已经过去 ' + (-d) + ' 天'}，阶段：${goalPhase(d)}。请结合剩余时间调整语气：积累期强调每天积累，冲刺期可以更催一点，最后几天以稳住作息、别熬夜为主。`;\n}\n/* ==========================================================\n   统计内核：周报 / 月报 / 趋势 共用\n   ========================================================== */\n/* v1.9.2 校验标记 K */\nconst SLOT_LABEL = ['0-3 点', '3-6 点', '6-9 点', '9-12 点', '12-15 点', '15-18 点', '18-21 点', '21-24 点'];\nconst WD_LABEL = ['周一', '周二', '周三', '周四', '周五', '周六', '周日'];\nfunction midnight(d) { const t = new Date(d || Date.now()); t.setHours(0, 0, 0, 0); return t.getTime(); }\nfunction periodRange(kind) {\n  const now = Date.now(), today = midnight();\n  if (kind === 'lastweek') {\n    const wd = (new Date(today).getDay() + 6) % 7;\n    const from = today - (wd + 7) * 86400000;\n    return { kind: kind, name: '上周', from: from, to: from + 7 * 86400000 };\n  }\n  if (kind === 'lastmonth') {\n    const d = new Date(); const from = new Date(d.getFullYear(), d.getMonth() - 1, 1).getTime();\n    return { kind: kind, name: '上月', from: from, to: new Date(d.getFullYear(), d.getMonth(), 1).getTime() };\n  }\n  if (kind === 'month') { const d = new Date(); return { kind: kind, name: '本月', from: new Date(d.getFullYear(), d.getMonth(), 1).getTime(), to: now }; }\n  if (kind === 'all') return { kind: kind, name: '全部', from: 0, to: now };\n  const wd = (new Date(today).getDay() + 6) % 7;\n  return { kind: 'week', name: '本周', from: today - wd * 86400000, to: now };\n}\nfunction periodStats(kind) {\n  const R = periodRange(kind);\n  const sess = (S.sessions || []).filter(s => s.startAt >= R.from && s.startAt < R.to);\n  const sleeps = (S.sleeps || []).filter(s => s.startAt >= R.from && s.startAt < R.to);\n  const mistakes = (S.priv || []).filter(p => p.kind === 'mistake' && p.at >= R.from && p.at < R.to);\n  const focusMin = Math.round(sum(sess.map(s => s.totalFocusSec || 0)) / 60);\n  const passed = sess.filter(s => s.status === 'passed').length;\n  const graded = sess.filter(s => s.status === 'passed' || s.status === 'failed').length;\n  const vio = sum(sess.map(s => (s.violations || []).filter(v => !v.excused).length));\n  const slotMin = [0, 0, 0, 0, 0, 0, 0, 0];\n  sess.forEach(s => { const h = new Date(s.startAt).getHours(); slotMin[Math.floor(h / 3)] += (s.totalFocusSec || 0) / 60; });\n  const bestSlot = slotMin.indexOf(Math.max.apply(null, slotMin));\n  const drowsy = sleeps.filter(s => (s.drowsySec || 0) >= 1800).length;\n  /* 平均睡眠同样按「实际入睡」算：总时长含酝酿阶段，算成睡眠会虚高 */\n  const sleepAvg = sleeps.length ? sum(sleeps.map(s => (s.sleepSec != null ? s.sleepSec : s.seconds))) / sleeps.length / 3600 : 0;\n  const topWeak = {};\n  (S.priv || []).filter(p => p.kind === 'weak' && p.at >= R.from && p.at < R.to)\n    .forEach(w => { const k = String(w.content || '').split(/[：:]/)[0].slice(0, 14); if (k) topWeak[k] = (topWeak[k] || 0) + 1; });\n  const weakTop = Object.keys(topWeak).sort((a, b) => topWeak[b] - topWeak[a]).slice(0, 4);\n  const days = [];\n  for (let t = R.from; t < Math.min(R.to, midnight() + 86400000); t += 86400000) {\n    const to = t + 86400000;\n    const m = Math.round(sum(sess.filter(s => s.startAt >= t && s.startAt < to).map(s => s.totalFocusSec || 0)) / 60);\n    const d = new Date(t);\n    days.push({ label: (d.getMonth() + 1) + '/' + d.getDate(), min: m });\n    if (days.length > 31) break;\n  }\n  return {\n    range: R, focusMin: focusMin, sessions: sess.length, passed: passed, graded: graded,\n    passRate: graded ? Math.round(passed / graded * 100) : 0, vio: vio, bestHour: sess.length ? SLOT_LABEL[bestSlot] : '—',\n    slotMin: slotMin, sleepAvg: sleepAvg, sleepDays: sleeps.length, drowsy: drowsy,\n    mistakes: mistakes.length, topWeak: weakTop.length ? weakTop.join('、') : '（没有明显集中的板块）',\n    dayBars: days, avgMin: sess.length ? Math.round(focusMin / sess.length) : 0,\n    longest: Math.round(Math.max.apply(null, [0].concat(sess.map(s => (s.totalFocusSec || 0) / 60))))\n  };\n}\nfunction trendStats() {\n  const sess = S.sessions || [];\n  const slotMin = [0, 0, 0, 0, 0, 0, 0, 0], wdMin = [0, 0, 0, 0, 0, 0, 0], wdN = [0, 0, 0, 0, 0, 0, 0];\n  sess.forEach(s => {\n    const min = (s.totalFocusSec || 0) / 60, d = new Date(s.startAt);\n    slotMin[Math.floor(d.getHours() / 3)] += min;\n    const w = (d.getDay() + 6) % 7;\n    wdMin[w] += min; wdN[w]++;\n  });\n  const weeks = [];\n  const today = midnight(), wd0 = (new Date(today).getDay() + 6) % 7;\n  const thisMon = today - wd0 * 86400000;\n  for (let i = 7; i >= 0; i--) {\n    const from = thisMon - i * 7 * 86400000, to = from + 7 * 86400000;\n    const m = Math.round(sum(sess.filter(s => s.startAt >= from && s.startAt < to).map(s => s.totalFocusSec || 0)) / 60);\n    weeks.push({ label: i === 0 ? '本周' : '-' + i + '周', min: m });\n  }\n  const total = Math.round(sum(sess.map(s => s.totalFocusSec || 0)) / 60);\n  const vio = sum(sess.map(s => (s.violations || []).filter(v => !v.excused).length));\n  const best = slotMin.indexOf(Math.max.apply(null, slotMin));\n  const worst = slotMin.indexOf(Math.min.apply(null, slotMin));\n  return {\n    slotMin: slotMin, wdMin: wdMin, weeks: weeks, total: total, sessions: sess.length,\n    avgMin: sess.length ? Math.round(total / sess.length) : 0,\n    longest: Math.round(Math.max.apply(null, [0].concat(sess.map(s => (s.totalFocusSec || 0) / 60)))),\n    bestSlot: best, worstSlot: worst, vio: vio,\n    vioRate: sess.length ? Math.round(vio / sess.length * 100) : 0\n  };\n}\nfunction trendDataText() {\n  const t = trendStats();\n  if (!t.sessions) return '（还没有任何专注记录）';\n  const lines = [];\n  lines.push('按开始时间分的时段分布（分钟）：' + SLOT_LABEL.map((l, i) => l + '=' + Math.round(t.slotMin[i])).join('，'));\n  lines.push('按星期分布（分钟）：' + WD_LABEL.map((l, i) => l + '=' + Math.round(t.wdMin[i])).join('，'));\n  lines.push('最近 8 周（分钟）：' + t.weeks.map(w => w.label + '=' + w.min).join('，'));\n  lines.push('累计 ' + t.total + ' 分钟 · 共 ' + t.sessions + ' 次 · 平均单次 ' + t.avgMin + ' 分钟 · 最长一次 ' + t.longest + ' 分钟 · 违规率 ' + t.vioRate + '%');\n  return lines.join('\\n');\n}\n/* ==========================================================\n   晨间闭环：起床 → TA 说早安 + 顺口点评昨晚 → 今天的安排\n   ========================================================== */\nfunction morningCfg() {\n  const m = cfg('morning') || {};\n  return { enabled: !!m.enabled, time: m.time || '07:00', charId: m.charId || '', voice: m.voice !== false };\n}\nfunction sleepLineBrief() {\n  const s = (S.sleeps || [])[0];\n  if (!s) return '（昨晚没有睡眠记录）';\n  const real = (s.sleepSec != null ? s.sleepSec : s.seconds);\n  const drow = s.drowsySec || 0;\n  const brk = (s.breaks || []).length;\n  return `${hm(s.startAt)}–${hm(s.endAt)}，总 ${fmtDur(s.seconds)}（其中酝酿睡意 ${fmtDur(drow)}、实际入睡 ${fmtDur(real)}${brk ? '、中途醒来 ' + brk + ' 次' : ''}）`;\n}\nfunction todayApptBrief() {\n  const list = (S.appts || []).filter(a => a.status === 'pending' && midnight(a.startAt) === midnight());\n  if (!list.length) return '（今天还没有排预约专注）';\n  return list.sort((a, b) => a.startAt - b.startAt).map(a => a.time + ' 专注 ' + a.minutes + ' 分钟：' + a.task).join('；');\n}\nasync function fireMorning(force) {\n  const m = morningCfg();\n  const cid = m.charId || anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  const time = m.time;\n  const sleepLine = sleepLineBrief();\n  const apptLine = todayApptBrief();\n  const goal = goalBrief();\n  const streak = sleepStreak() ? '已连续 ' + sleepStreak() + ' 天' : '还没有连续记录';\n  let text = '';\n  if (!force) {\n    try {\n      text = await pGen('morning.line', { time: time, sleepLine: sleepLine, goal: goal, appt: apptLine, streak: streak }, [cid]);\n    } catch (e) { text = ''; }\n  }\n  if (!text) {\n    text = `早上好。${sleepLine.startsWith('（') ? '' : '昨晚 ' + sleepLine + '，'}${apptLine.startsWith('（') ? '' : '今天 ' + apptLine + '。'}起来吧，我等你开始。`;\n  }\n  text = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n  notify('🌅 ' + time + ' · ' + charName(cid), text);\n  const w = openSheet(`<h3>🌅 ${esc(time)} 早安</h3>\n    <div class=\"row mt10\">${charAvatar(charById(cid))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:14px\">${esc(text)}</div></div>\n    <div class=\"hr\"></div>\n    <div class=\"kv\"><span class=\"k\">昨晚睡眠</span><span>${esc(sleepLine)}</span></div>\n    <div class=\"kv\"><span class=\"k\">长期目标</span><span>${esc(goal)}</span></div>\n    <div class=\"kv\"><span class=\"k\">今天的安排</span><span>${esc(apptLine.startsWith('（') ? '还没排' : apptLine)}</span></div>\n    <label class=\"fl\">今天第一件事是什么（写下来，顺手就能开一段专注）</label>\n    <input class=\"input\" id=\"morningTask\" placeholder=\"例如：把昨天那章笔记补完\">\n    <div class=\"row mt12\" style=\"gap:8px\">\n      <button class=\"btn ghost grow\" data-act=\"closeSheet\">先起床</button>\n      <button class=\"btn primary grow\" data-act=\"morningStart\">写下并开始专注</button></div>\n    <div class=\"tiny mt8\">「开始专注」会带着这件事作为本次唯一任务，直接进入专注流程。</div>`);\n  if (m.voice) speak(cid, text);\n  await syncTimeline(cid, `${charName(cid)}在早上 ${time} 叫用户起床：${text}`, 'morning', {});\n  await syncChatLine(cid, text, 'assistant');\n  await addPublic('morning', `${charName(cid)}的早安：${text}`, cid, {});\n  render();\n}\nasync function checkMorning() {\n  const m = morningCfg();\n  if (!m.enabled || !m.time) return;\n  const now = new Date(), cur = pad2(now.getHours()) + ':' + pad2(now.getMinutes());\n  if (cur !== m.time || cfg('lastMorningFired') === dkey() + cur) return;\n  S.settings.lastMorningFired = dkey() + cur;\n  await saveSettings(true);\n  await fireMorning(false);\n}\nfunction startMorningLoop() {\n  if (S.morningTimer) return;\n  S.morningTimer = setInterval(() => { checkMorning(); }, 20000);\n  checkMorning();\n}\nasync function scheduleMorning(m, silent) {\n  if (!API || !API.tasks || !m || !m.enabled || !m.time) return;\n  const now = new Date(), parts = String(m.time).split(':');\n  const target = new Date(now);\n  target.setHours(Number(parts[0]), Number(parts[1]), 0, 0);\n  if (target.getTime() <= now.getTime()) target.setDate(target.getDate() + 1);\n  const who = charName(m.charId || anyCharId());\n  await sdk(() => API.tasks.schedule({\n    id: 'focus_morning', delayMs: Math.max(60000, target.getTime() - now.getTime()),\n    actions: [\n      { type: 'notification', title: '🌅 ' + m.time + ' 早安', body: who + ' 在等你起床' },\n      { type: 'shell.notify', title: '🌅 ' + m.time + ' 早安', body: who + ' 在等你起床' }\n    ]\n  }));\n  /* 晨间闭环的关键兜底：早上不会有人打开小手机，宿主任务只能补跑 ——\n     保存时直接在系统时钟立闹钟，被杀也准时响。 */\n  if (!silent) bookSystemAlarm(Number(parts[0]), Number(parts[1]), '晨间·TA叫你');\n}\n/* ==========================================================\n   预约专注：先跟角色约好时间，到点让 TA 来催你\n   ----------------------------------------------------------\n   流程：选好 日期 / 开始时间 / 时长 / 专注事项 / 陪伴角色 →\n   APP 用宿主的后台定时任务排好 N 次催促（默认 T-10、T-5、T-0）：\n   每次 = 一条系统通知 + 在聊天室里写一张卡 + 请 TA 亲口回你一句 →\n   你点「现在开始」就直接进入专注 →\n   连着催 N 次你都没点开始，过了宽限就按惩罚库开罚（全屏锁定）。\n   ----------------------------------------------------------\n   两条硬边界（先说清楚，不糊弄）：\n   ① 催促靠宿主后台定时任务：小手机/浏览器完全关闭时不实时运行，\n      重新打开后会补跑已到期的任务 —— 可能一次收到好几条催促。\n      已排好的任务宿主没有「撤回」接口，所以取消预约后到点仍可能\n      响一次通知，忽略即可（APP 这边不会再拿它开罚）。\n   ② 「开罚」这个判定只能在 APP 被打开时执行（APP 没法自己弹出来）。\n      所以：APP 开着 → 到点即锁；APP 没开着 → 下次打开时立刻锁。\n   ========================================================== */\nconst APPT_STATUS = {\n  pending: '待开始', started: '已开始', done: '已完成', missed: '已错过 · 已开罚',\n  skipped: '这次放过了', canceled: '已取消'\n};\nfunction apptAdvance() { return clamp(Number(cfg('apptAdvanceMin') != null ? cfg('apptAdvanceMin') : 10) || 0, 0, 240); }\nfunction apptGap() { return clamp(Number(cfg('apptGapMin') || 5), 1, 240); }\nfunction apptMaxNudge() { return clamp(Number(cfg('apptMaxNudge') || 3), 1, 6); }\nfunction apptGrace() { return clamp(Number(cfg('apptGraceMin') || 0), 0, 120); }\n/* ---------- 预约的分段任务：把一个时间段拆成几段，各自有事项与时长 ---------- */\nfunction apptSegsOf(src) {\n  const arr = (src && src.segments) ? src.segments : (S.draft.apptSegs || []);\n  return (arr || []).filter(s => s && (s.content || Number(s.min)));\n}\nfunction apptSegTotal(src) {\n  const segs = apptSegsOf(src);\n  const t = sum(segs.map(s => Number(s.min) || 0));\n  return t > 0 ? Math.round(t) : 0;\n}\nfunction apptSegText(segs) {\n  const list = (segs || []).filter(s => s && s.content);\n  if (!list.length) return '';\n  return list.map((s, i) => (i + 1) + '. ' + s.content + '（' + (Number(s.min) || 0) + ' 分）').join('　');\n}\n/* 把一个预约（或邀请）变成专注会话的参数：分段 → 任务清单，合计 → 时长 */\nfunction sessionOptsFromAppt(a, fbTask, fbMin) {\n  const segs = apptSegsOf(a);\n  const total = apptSegTotal(a) || clamp(Number((a && a.minutes) || fbMin || cfg('focusMin') || 25), 1, 600);\n  const plan = segs.length\n    ? segs.map(s => ({ content: String(s.content || '专注').slice(0, 60), est: Number(s.min) || Math.round(total / segs.length) }))\n    : [{ content: String((a && a.task) || fbTask || '安静地学一会儿').slice(0, 60), est: total }];\n  const breakMin = Math.max(1, Number((a && a.breakMin) || cfg('breakMin') || 5));\n  const reviewEvery = (a && a.reviewEvery) === 'session' ? 'session' : 'focus';\n  return { focusMin: total, breakMin: breakMin, cycles: 1, plan: plan, reviewEvery: reviewEvery };\n}\nfunction apptTimesOf(a) {\n  const adv = apptAdvance(), gap = apptGap(), n = apptMaxNudge();\n  const out = [];\n  for (let i = 0; i < n; i++) out.push(a.startAt - (adv - i * gap) * 60000);\n  return out;\n}\nfunction apptTimeText(a) {\n  if (!a || !a.startAt) return '（未设置时间）';\n  const d = new Date(a.startAt);\n  return pad2(d.getMonth() + 1) + '/' + pad2(d.getDate()) + ' ' + pad2(d.getHours()) + ':' + pad2(d.getMinutes());\n}\nfunction apptCountdownText(a) {\n  if (!a || a.status !== 'pending') return '';\n  const left = a.startAt - Date.now();\n  if (left > 0) return '距开始 ' + fmtDur(left / 1000) + '（' + apptTimeText(a) + '）';\n  const over = (Date.now() - a.startAt) / 60000;\n  return '已到开始时间 · 已催 ' + (a.nudgeCount || 0) + '/' + apptMaxNudge() + ' 次 · 过了 ' + fmtDur(over * 60);\n}\n/* 系统闹钟兜底（通用）：借壳的 ACTION_SET_ALARM 在系统时钟里立一个闹钟，\n   时钟 App 里确认一次后，就算小手机被杀掉也会准时响 —— 这是「到点提醒」唯一不依赖\n   页面存活的通道（自建 AlarmManager 全屏唤醒排在 M3，需要重打 APK）。\n   注意：取消/改期不会自动撤销旧闹钟，要到时钟 App 里删，文案里有说明。 */\nasync function bookSystemAlarm(hour, minute, msg) {\n  try {\n    if (!API || !API.device || !API.device.alarmSet) return false;\n    const r = await sdk(() => API.device.alarmSet({ hour: hour, minute: minute, message: msg }), null);\n    if (r && r.ok) { toast('⏰ 已在系统时钟立好 ' + pad2(hour) + ':' + pad2(minute) + ' 的闹钟（去时钟 App 确认一次就准时响）'); return true; }\n    if (r && r.reason) toast('系统闹钟没设上：' + (r.reason || '当前环境不支持'));\n    return false;\n  } catch (e) { return false; }\n}\nasync function bookSystemAlarmForAppt(rec) {\n  try {\n    if (cfg('apptSysAlarm') === false) return;\n    if (!API || !API.device || !API.device.alarmSet || !rec || !rec.startAt) return;\n    const d = new Date(rec.startAt);\n    await bookSystemAlarm(d.getHours(), d.getMinutes(), ('TA约你·' + (rec.task || '专注')).slice(0, 18));\n  } catch (e) { }\n}\nasync function createAppt(rec) {\n  const r = await DB.create(T.APPT, rec);\n  if (r) rec.id = r.id;\n  S.appts = (S.appts || []).filter(x => String(x.id) !== String(rec.id)).concat([rec])\n    .sort((a, b) => (a.startAt || 0) - (b.startAt || 0));\n  await bookSystemAlarmForAppt(rec);\n  return rec;\n}\nasync function updateAppt(a) {\n  if (!a || !a.id) return;\n  await DB.update(T.APPT, a.id, JSON.parse(JSON.stringify(a)));\n}\nasync function removeAppt(a) {\n  if (!a || !a.id) return;\n  await DB.remove(T.APPT, a.id);\n  S.appts = (S.appts || []).filter(x => String(x.id) !== String(a.id));\n}\n/* 排催促任务：同一个预约用固定 id，改期就覆盖，不会越排越多 */\nasync function scheduleAppt(a) {\n  if (!API || !API.tasks || !a || !a.id) return 0;\n  const cid = (a.charIds && a.charIds.length ? a.charIds[0] : anyCharId());\n  if (!cid) return 0;\n  const name = charName(cid);\n  const now = Date.now(), times = apptTimesOf(a), n = times.length;\n  let ok = 0;\n  for (let i = 0; i < n; i++) {\n    const delay = times[i] - now;\n    if (delay < -60000) continue;                     // 已经过去很久的跳过\n    const left = Math.max(0, Math.round((a.startAt - times[i]) / 60000));\n    const body = left > 0\n      ? left + ' 分钟后（' + apptTimeText(a) + '）要一起专注 ' + a.minutes + ' 分钟：' + a.task\n      : '到点了！说好一起专注 ' + a.minutes + ' 分钟：' + a.task + '。快点「现在开始」。';\n    const actions = [{\n      type: 'notification',\n      title: '🗓 ' + name + ' 来催你了（第 ' + (i + 1) + '/' + n + ' 次）',\n      body: body\n    }];\n    /* 系统通知栏兜底：应用内通知在小手机页面冻结时看不见，壳渠道才真正弹出来（网页 no-op）。 */\n    actions.push({ type: 'shell.notify', title: '🗓 ' + name + ' 来催你了（第 ' + (i + 1) + '/' + n + ' 次）', body: body });\n    /* 聊天卡只挂在最后一次提醒上。\n       三个任务都带卡片时，APP 被冻结后恢复会把 T-10/T-5/T-0 的卡一起补发，\n       用户会在同一秒收到三张“第 1/3、2/3、3/3 次提醒”。通知仍然逐次补，\n       但聊天室只保留一张最终提醒卡，角色也只回一句。 */\n    const isFinalNudge = i === n - 1;\n    if (cfg('apptChatNudge') !== false && isFinalNudge) {\n      actions.push({\n        type: 'chat.card', characterId: cid, role: 'system', historyRole: 'system',\n        title: '预约专注 · 最后提醒',\n        subtitle: apptTimeText(a),\n        body: body,\n        summary: name + '应该在 ' + apptTimeText(a) + ' 提醒用户准备开始专注：' + a.task,\n        historyText: '[预约专注] ' + name + '最后一次提醒用户：' + body\n          + '（用户还没点开始；连着 ' + n + ' 次都没开始会被罚）'\n      });\n      actions.push({ type: 'chat.reply', characterId: cid });\n    }\n    await sdk(() => API.tasks.schedule({\n      id: 'focus_appt_' + a.id + '_n' + i,\n      delayMs: Math.max(20000, delay),\n      actions: actions\n    }), null);\n    ok++;\n  }\n  return ok;\n}\n/* ---------- 失约：TA 的反应 + 记忆（第一反应，不依赖 AI） ---------- */\nasync function missedApptReact(a) {\n  const cid = (a.charIds && a.charIds[0]) || anyCharId();\n  if (!cid) return;\n  const n = Number(a.nudgeCount) || apptMaxNudge();\n  const line = '我等了你 ' + n + ' 次，' + apptTimeText(a) + ' 那个时间你一直没出现。'\n    + '「' + (a.task || '约好的事') + '」我记着，你自己也说过的。';\n  await syncTimeline(cid, '你和用户约好 ' + apptTimeText(a) + ' 一起专注「' + (a.task || '') + '」（' + (a.minutes || 0)\n    + ' 分钟），你按时催了他 ' + n + ' 次，他一次都没有开始 —— 他失约了，你等了他很久。', 'appt_missed', {});\n  await addPublic('missed', charName(cid) + '：约好的专注「' + (a.task || '') + '」用户没有出现（催了 ' + n + ' 次）', cid, {});\n  await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'assistant', content: line }), null);\n  notify('💔 ' + charName(cid) + ' 在等你', '约好的 ' + (a.task || '专注') + ' 没有开始');\n  toast(charName(cid) + '：我等了你 ' + n + ' 次，你一直没出现');\n}\n/* 没开始 → 开罚 */\nasync function punishMissedAppt(a) {\n  const cid = (a.charIds && a.charIds.length ? a.charIds[0] : anyCharId());\n  if (cid) {\n    await syncTimeline(cid, '用户和' + charName(cid) + '约好一起专注「' + a.task + '」（' + apptTimeText(a) + '），'\n      + charName(cid) + '催了 ' + (a.nudgeCount || apptMaxNudge()) + ' 次用户都没有开始，按约定开罚。', 'appt_missed', {});\n  }\n  // 连坐：爽约不只是你的损失，TA 那边也跟着退\n  if (cid) await wishConnectHit(cid, Math.max(30, Math.round((Number(a.minutes) || 25) * wishPenaltyRate() / 100)), '说好一起专注，你没来');\n  /* 失约扣币：放在两个「只记录」分支之前 —— 这几类不罚的时候，扣币照样生效 */\n  await coinDeductFor('预约专注没有开始（失约）', 'miss');\n  if (cfg('apptPunish') === false) { toast('预约没开始：' + a.task + '（这个预约的惩罚开关关着，只记录）'); return; }\n  if (!cfg('punishEnabled')) { toast('预约没开始：' + a.task + '（惩罚模式未开启，只记录）'); return; }\n  await triggerPunish('预约专注没有开始', {});\n}\n/* 到点确认弹层：把「万事开头难」压成一次点击。后台隐藏 iframe（document.hidden）里不弹，\n   回到前台后由 20 秒一轮的补判接着催；一个预约同一轮只弹一次。 */\nfunction maybeApptStartSheet(a) {\n  try {\n    if (typeof document === 'undefined' || document.hidden) return;\n    if (S.lock || (S.session && S.session.status === 'running')) return;\n    if (S.draft && S.draft.apptSheetFor === a.id) return;\n    const cid = (a.charIds && a.charIds[0]) || anyCharId();\n    if (S.draft) S.draft.apptSheetFor = a.id;\n    openSheet(`<h3>⏰ ${esc(apptTimeText(a))} · 该开始了</h3>\n      <div class=\"sub\">${esc(charName(cid))} 和你约好了 ${esc(a.minutes)} 分钟的「${esc(a.task || '专注')}」，到点了。</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"apptStart\" data-id=\"${esc(a.id)}\">▶️ 现在开始</button>\n        <button class=\"btn ghost grow\" data-act=\"apptSnoozeSheet\">💤 再赖会儿</button></div>\n      <div class=\"tiny mt8\">再赖下去 TA 会接着催，${apptMaxNudge()} 次没开始就按约定开罚。</div>`);\n  } catch (e) { }\n}\n/* 判定：APP 打开时每 20 秒跑一次；APP 没开时靠宿主任务发通知，重开即补判 */\nasync function checkAppointments() {\n  if (!S.appts || !S.appts.length) return;\n  const now = Date.now();\n  let changed = false;\n  for (const a of S.appts) {\n    if (!a || !a.startAt) continue;\n    if (a.status === 'pending') {\n      const times = apptTimesOf(a), n = times.length;\n      const due = times.filter(t => now >= t).length;\n      if (due > (a.nudgeCount || 0)) {\n        a.nudgeCount = due; changed = true; await updateAppt(a);\n        maybeApptStartSheet(a);\n      }\n      // 时间被改到过去之类：至少要走过一次催促点才判\n      if ((a.nudgeCount || 0) >= n && now >= times[n - 1] + apptGrace() * 60000) {\n        const busy = S.session && S.session.status === 'running';\n        if (busy) {\n          a.status = 'skipped';\n          a.note = '到点的时候你已经在另一段专注里了，这次放过。';\n          changed = true; await updateAppt(a);\n        } else {\n          a.status = 'missed';\n          a.missedAt = now;\n          a.needEssay = true;                    // 需要补写「原因分析 + 保证书」\n          a.note = '催了 ' + n + ' 次都没点开始，已按惩罚库开罚；等你补写说明。';\n          changed = true; await updateAppt(a);\n          await missedApptReact(a);              // TA 的失约反应（记忆 + 聊天室）\n          await punishMissedAppt(a);             // 开罚（转账/送礼类会自动执行）\n        }\n      }\n      continue;\n    }\n    // 已经在专注里开始的预约：专注结束后标记完成\n    if (a.status === 'started' && now - (a.startedAt || 0) > 3 * 60000\n      && !(S.session && S.session.status === 'running')) {\n      a.status = 'done'; a.note = '已完成'; changed = true; await updateAppt(a);\n    }\n  }\n  if (changed) render();\n}\nlet apptTimer = null, apptCdTimer = null;\nfunction paintApptCountdown() {\n  if (S.lock) return;\n  document.querySelectorAll('[data-cd]').forEach(el => {\n    const a = (S.appts || []).find(x => String(x.id) === String(el.dataset.cd));\n    el.textContent = a ? apptCountdownText(a) : '';\n  });\n}\nfunction startApptLoop() {\n  if (apptTimer) return;\n  apptTimer = setInterval(() => { checkAppointments(); }, 20000);\n  apptCdTimer = setInterval(paintApptCountdown, 1000);\n  checkAppointments();\n}\n/* ---------- 预约页 ---------- */\nfunction apptCardHTML(a) {\n  const c = charById((a.charIds || [])[0]);\n  const times = apptTimesOf(a);\n  const n = times.length;\n  const st = a.status || 'pending';\n  const pill = st === 'pending' ? 'run' : (st === 'missed' ? 'bad' : (st === 'started' ? 'warn' : 'ok'));\n  return `<div class=\"card\" style=\"border-color:${st === 'missed' ? 'rgba(255,123,138,.45)' : 'rgba(124,140,255,.3)'}\">\n    <div class=\"row between\"><span class=\"tiny\">${esc(a.date || '')} ${esc(a.time || '')} · 专注 ${Number(a.minutes) || 0} 分钟</span>\n      <span class=\"pill ${pill}\">${esc(APPT_STATUS[st] || st)}</span></div>\n    <div style=\"font-size:15px;font-weight:600;margin-top:6px\">${esc(a.task || '')}${(a.segments || []).length > 1 ? ' <span class=\"tiny\">（共 ' + a.segments.length + ' 段）</span>' : ''}</div>\n    ${(a.segments || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">${(a.segments || []).map((s, i) => (i + 1) + '. ' + esc(s.content || '') + '（' + (Number(s.min) || 0) + ' 分）').join('<br>')}</div>` : ''}\n    ${(a.segments || []).length || a.breakMin != null ? `<div class=\"tiny mt6\">每段之间休息 ${Number(a.breakMin != null ? a.breakMin : (cfg('breakMin') || 5))} 分钟 · ${a.reviewEvery === 'session' ? '中间也校验' : '整段结束校验'}</div>` : ''}\n    ${st === 'pending' ? `<div class=\"tiny mt6\" data-cd=\"${esc(a.id)}\">${apptCountdownText(a)}</div>` : ''}\n    <div class=\"row mt8\">${charAvatar(c)}<div class=\"grow\" style=\"min-width:0\">\n      <div class=\"tiny\">${esc(c ? c.name : '角色')} 来监督你</div>\n      <div class=\"tiny\">催促时间点：${times.map(t => hm(t)).join(' / ')}</div></div></div>\n    ${a.nudgeCount ? `<div class=\"tiny mt6\" style=\"color:${st === 'missed' ? '#ff9aa6' : 'var(--gold)'}\">已催 ${a.nudgeCount}/${n} 次</div>` : ''}\n    ${a.note ? `<div class=\"tiny mt6\" style=\"color:var(--dim)\">${esc(a.note)}</div>` : ''}\n    ${st === 'pending' ? `<div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"apptStart\" data-id=\"${esc(a.id)}\">▶️ 现在开始</button>\n      <button class=\"btn ghost\" data-act=\"apptEdit\" data-id=\"${esc(a.id)}\">改期</button>\n      <button class=\"btn ghost\" data-act=\"apptCancel\" data-id=\"${esc(a.id)}\">取消</button></div>`\n      : `<div class=\"row mt10\" style=\"gap:8px\">\n      ${st === 'started' ? `<button class=\"btn primary grow\" data-act=\"gotoView\" data-view=\"running\">回到专注</button>` : ''}\n      <button class=\"btn ghost grow\" data-act=\"apptDel\" data-id=\"${esc(a.id)}\">从列表移除</button></div>`}\n  </div>`;\n}\nVIEWS.appt = function () {\n  const all = S.appts || [];\n  const pend = all.filter(a => a.status === 'pending').sort((a, b) => a.startAt - b.startAt);\n  const live = all.filter(a => a.status === 'started');\n  const past = all.filter(a => ['missed', 'done', 'skipped', 'canceled'].indexOf(a.status) >= 0)\n    .sort((a, b) => b.startAt - a.startAt).slice(0, 20);\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(124,140,255,.16),rgba(255,255,255,.03));border-color:rgba(124,140,255,.3)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>🗓 预约专注</h3>\n      <div class=\"tiny mt6\">跟 TA 约一个时间一起专注：开始前 ${apptAdvance()} 分钟 TA 会来催你准备，每 ${apptGap()} 分钟催一次，一共 ${apptMaxNudge()} 次；连着催 ${apptMaxNudge()} 次你都没点「现在开始」→ 直接按惩罚库开罚。</div></div>\n      <div style=\"font-size:30px\">⏳</div></div>\n    <button class=\"btn primary block mt12\" data-act=\"apptNew\">＋ 新约一个专注</button></div>\n  ${live.length ? live.map(a => apptCardHTML(a)).join('') : ''}\n  ${pend.length ? pend.map(a => apptCardHTML(a)).join('')\n      : (live.length ? '' : '<div class=\"empty\">还没有待开始的预约。<br>点上面「新约一个专注」，填好日期、时长和要做的事，剩下的交给 TA 催你。</div>')}\n  <div class=\"card\"><h3>催促与开罚设置</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">提前多久开始催（分钟）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptAdvanceMin\" data-num=\"1\" value=\"${apptAdvance()}\"></div>\n      <div class=\"grow\"><label class=\"fl\">每隔多久催一次（分钟）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptGapMin\" data-num=\"1\" value=\"${apptGap()}\"></div>\n      <div class=\"grow\" style=\"max-width:96px\"><label class=\"fl\">催几次</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptMaxNudge\" data-num=\"1\" value=\"${apptMaxNudge()}\"></div>\n    </div>\n    <label class=\"fl\">第 ${apptMaxNudge()} 次催促之后，再过多久开罚（分钟，0 = 立刻）</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptGraceMin\" data-num=\"1\" value=\"${apptGrace()}\">\n    <div class=\"chips mt10\">\n      <button class=\"chip ${cfg('apptChatNudge') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"apptChatNudge\">催促同时让 TA 在聊天室回你一句</button>\n      <button class=\"chip ${cfg('apptPunish') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"apptPunish\">没开始就开罚</button>\n      <button class=\"chip ${cfg('apptSysAlarm') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"apptSysAlarm\">⏰ 系统闹钟兜底（APK）</button>\n    </div>\n    <div class=\"tiny mt6\">催促同时落系统通知栏；APK 预约时会立系统闹钟兜底（改期需自行删旧闹钟）。</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"apptTestNudge\">试一次催促（立刻）</button>\n      <button class=\"btn sm ghost grow\" data-act=\"apptTestPunish\">试一次「没开始」的惩罚</button></div></div>\n  <div class=\"card\"><h3>它怎么提醒你</h3>\n    <div class=\"tiny\" style=\"line-height:1.8\">\n    ① <b>系统通知</b>：到时间点会弹一条「TA 来催你了（第 N/次）」的通知。<br>\n    ② <b>聊天室</b>：只会在最后一次提醒时写一张「预约专注 · 最后提醒」的卡，并请 TA 亲自回你一句（可在上面关掉）；前面几次只发系统通知，不会连续刷三张卡。<br>\n    ③ <b>APP 内</b>：预约页显示倒计时与已催次数；没开始就开罚时，APP 会立刻进入全屏惩罚页。<br><br>\n    <b>两条硬边界</b>（实测口径）：<br>\n    · 催促靠小手机的后台定时任务，小手机/浏览器完全关闭时不实时运行，重新打开后会<b>补跑已到期的任务</b> —— 可能会一次收到多条系统通知，但聊天室只保留最后一次提醒卡；<br>\n    · 已排好的任务宿主没有「撤回」接口：取消预约后到点仍可能响一次通知，忽略即可（APP 不会再拿它开罚）；<br>\n    · 「开罚」只能在 APP 被打开时执行（APP 没法自己把界面弹出来）。APP 开着 → 到点即锁；APP 没开 → 下次打开时立刻锁。</div></div>\n  ${past.length ? `<div class=\"card\"><h3>历史预约（${past.length}）</h3>\n    ${past.map(a => `<div class=\"item\">\n      <div class=\"ic\">${a.status === 'missed' ? '⚠️' : a.status === 'done' ? '✅' : a.status === 'canceled' ? '🚫' : '➖'}</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(a.task || '')}</div>\n        <div class=\"tiny\">${esc(a.date || '')} ${esc(a.time || '')} · ${Number(a.minutes) || 0} 分钟 · ${esc(APPT_STATUS[a.status] || a.status)}${a.nudgeCount ? ' · 催了 ' + a.nudgeCount + ' 次' : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"apptDel\" data-id=\"${esc(a.id)}\">删</button></div>`).join('')}</div>` : ''}`;\n};\nObject.assign(ACTIONS, {\n  apptNew: () => {\n    if (!S.chars.length) { toast('先在小手机聊天 APP 里创建角色，才能跟 TA 约专注'); return; }\n    const d = new Date();\n    if (!S.draft.apptDate) S.draft.apptDate = dkey(d);\n    if (!S.draft.apptTime) {\n      const t = new Date(Date.now() + 30 * 60000);\n      S.draft.apptTime = pad2(t.getHours()) + ':' + pad2(t.getMinutes());\n    }\n    if (S.draft.apptMinutes == null) S.draft.apptMinutes = Number(cfg('focusMin') || 25);\n    if (!S.draft.apptCharIds || !S.draft.apptCharIds.length) S.draft.apptCharIds = (cfg('charIds') || []).slice(0, 1);\n    if (!S.draft.apptSegs || !S.draft.apptSegs.length) S.draft.apptSegs = [{ content: S.draft.apptTask || '', min: Number(S.draft.apptMinutes) || Number(cfg('focusMin') || 25) }];\n    if (S.draft.apptBreakMin == null) S.draft.apptBreakMin = Number(cfg('breakMin') || 5);\n    if (!S.draft.apptReview) S.draft.apptReview = 'focus';\n    const mins = [15, 25, 30, 45, 60, 90];\n    const tasks = ['背单词 50 个', '资料分析 30 题', '写完这一章笔记', '申论一篇', '复习错题'];\n    const sel = S.draft.apptCharIds || [];\n    openSheet(`<h3>🗓 新约一个专注</h3>\n      ${S.draft.inviteReschedId ? `<div class=\"tiny\" style=\"background:var(--accent-soft);border-radius:10px;padding:9px;line-height:1.7;color:#c9cfff;margin-bottom:8px\">正在给 TA 的邀请改时间 —— 改好保存后，这条邀请会记为「已答应」，并按你定的时间排好催促。</div>` : ''}\n      <div class=\"tiny\">填好之后 TA 会按时来催你。日期选今天、时间挑一个即将到来的点就行。</div>\n      <div class=\"row mt10\" style=\"gap:10px\">\n        <div class=\"grow\"><label class=\"fl\">日期</label><input class=\"input\" type=\"date\" data-in=\"apptDate\" value=\"${esc(S.draft.apptDate)}\"></div>\n        <div class=\"grow\" style=\"max-width:132px\"><label class=\"fl\">开始时间</label><input class=\"input\" type=\"time\" data-in=\"apptTime\" value=\"${esc(S.draft.apptTime)}\"></div>\n      </div>\n      <label class=\"fl\">分段任务（可以只填一段；每段有自己的时长）</label>\n      <div class=\"mt6\">${(function () {\n        const segs = (S.draft.apptSegs && S.draft.apptSegs.length) ? S.draft.apptSegs : [{ content: S.draft.apptTask || '', min: Number(S.draft.apptMinutes) || 25 }];\n        return segs.map((sg, i) => `<div class=\"row\" style=\"gap:7px;margin-bottom:7px\">\n          <input class=\"input grow\" data-in=\"apptSegs.${i}.content\" value=\"${esc(sg.content || '')}\" placeholder=\"第 ${i + 1} 段做什么\">\n          <input class=\"input\" style=\"width:74px;flex:0 0 74px\" type=\"number\" inputmode=\"numeric\" data-in=\"apptSegs.${i}.min\" data-num=\"1\" value=\"${Number(sg.min) || 0}\" placeholder=\"分钟\">\n          ${segs.length > 1 ? `<button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"apptSegDel\" data-i=\"${i}\">✕</button>` : ''}</div>`).join('');\n      })()}</div>\n      <button class=\"btn block ghost sm\" data-act=\"apptSegAdd\">＋ 再加一段任务</button>\n      ${tasks.length ? `<div class=\"chips mt6\">${tasks.map(t => `<button class=\"chip\" data-act=\"apptSegFill\" data-v=\"${esc(t)}\">把「${esc(t)}」填进最后一段</button>`).join('')}</div>` : ''}\n      <div class=\"tiny mt6\">分段合计 ${apptSegTotal() || Number(S.draft.apptMinutes) || 25} 分钟${apptSegsOf().filter(s => s.content).length ? ' —— 倒计时按合计走，每段有自己的预估时间，到点会提醒你做下一段。' : '（只有一段时，就用下面的总时长。）'}</div>\n      <div class=\"row\" style=\"gap:10px\">\n        <div class=\"grow\"><label class=\"fl\">每段之间休息（分钟）</label>\n          <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"apptBreakMin\" data-num=\"1\" value=\"${Number(S.draft.apptBreakMin != null ? S.draft.apptBreakMin : (cfg('breakMin') || 5))}\"></div>\n      </div>\n      <label class=\"fl\">校验时机</label>\n      <div class=\"chips\">\n        <button class=\"chip ${(S.draft.apptReview || 'focus') === 'focus' ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"apptReview\" data-v=\"focus\">整段结束校验</button>\n        <button class=\"chip ${S.draft.apptReview === 'session' ? 'on' : ''}\" data-act=\"setDraft\" data-k=\"apptReview\" data-v=\"session\">中间也校验</button>\n      </div>\n      <label class=\"fl\">总时长（分钟，没有分段时用这个）</label>\n      <div class=\"chips\">${mins.map(m => `<button class=\"chip ${Number(S.draft.apptMinutes) === m ? 'on' : ''}\" data-act=\"apptSet\" data-k=\"apptMinutes\" data-v=\"${m}\" data-num=\"1\">${m}</button>`).join('')}</div>\n      <input class=\"input mt6\" type=\"number\" inputmode=\"numeric\" data-in=\"apptMinutes\" data-num=\"1\" value=\"${Number(S.draft.apptMinutes) || 25}\">\n      <label class=\"fl\">让谁来监督陪伴</label>\n      <div class=\"chips\">${S.chars.map(c => `<button class=\"chip ${sel.indexOf(c.id) >= 0 ? 'on' : ''}\" data-act=\"apptToggleChar\" data-id=\"${esc(c.id)}\">${esc(c.name)}</button>`).join('')}</div>\n      <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm grow\" data-act=\"apptRandomChar\">🎲 随机抽一位</button>\n        <button class=\"btn sm ghost grow\" data-act=\"apptClearChar\">清空</button></div>\n      <div class=\"tiny mt10\" style=\"background:var(--card2);border-radius:10px;padding:10px;line-height:1.7\">\n        按现在的设置，会在这几个时间点催你：<br>\n        ${apptTimesOf({ startAt: apptParse() }).map((t, i) => `${i + 1}. ${hm(t)}`).join('　')}<br>\n        第 ${apptMaxNudge()} 次之后再过 ${apptGrace()} 分钟你还没点「现在开始」，就按惩罚库开罚。\n      </div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn sm ghost grow\" data-act=\"apptAdvanced\">催得更细一点…</button></div>\n      <button class=\"btn primary block mt12\" data-act=\"apptSave\">约好，让 TA 按时来催我</button>\n      <div class=\"tiny mt8\">每次催促都会发一条通知、在聊天室里写一张卡，并请 TA 亲口回你一句（可在「预约专注」页关掉后两项）。</div>`);\n  },\n  apptSet: el => {\n    const k = el.dataset.k, v = el.dataset.num === '1' ? Number(el.dataset.v) : el.dataset.v;\n    S.draft[k] = v;\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  /* ---- 预约的分段任务 ---- */\n  apptSegAdd: () => {\n    const segs = (S.draft.apptSegs && S.draft.apptSegs.length) ? S.draft.apptSegs.slice() : [];\n    if (!segs.length && S.draft.apptTask) segs.push({ content: S.draft.apptTask, min: Number(S.draft.apptMinutes) || 25 });\n    segs.push({ content: '', min: 25 });\n    S.draft.apptSegs = segs;\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  apptSegDel: el => {\n    const i = Number(el.dataset.i);\n    const segs = (S.draft.apptSegs || []).slice();\n    segs.splice(i, 1);\n    S.draft.apptSegs = segs.length ? segs : [{ content: '', min: 25 }];\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  apptSegFill: el => {\n    const v = el.dataset.v;\n    const segs = (S.draft.apptSegs && S.draft.apptSegs.length) ? S.draft.apptSegs.slice() : [{ content: '', min: Number(S.draft.apptMinutes) || 25 }];\n    // 填进第一个空段，没空段就加一段\n    let idx = segs.findIndex(s => !s.content);\n    if (idx < 0) { segs.push({ content: v, min: 25 }); idx = segs.length - 1; }\n    else segs[idx].content = v;\n    S.draft.apptSegs = segs;\n    S.draft.apptTask = segs[0].content || '';\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  /* 邀请页里点「分段/休息设置」→ 带着草稿跳到预约表单 */\n  inviteBookAdvanced: () => {\n    S.draft.apptTask = S.draft.inviteTask || '';\n    S.draft.apptMinutes = Number(S.draft.inviteMin) || Number(cfg('focusMin') || 25);\n    S.draft.apptSegs = [{ content: S.draft.apptTask, min: S.draft.apptMinutes }];\n    S.draft.apptBreakMin = Number(cfg('breakMin') || 5);\n    S.draft.apptReview = 'focus';\n    S.draft.apptCharIds = [inviteCharId()].filter(Boolean);\n    const d0 = inviteDefaultDate();\n    S.draft.apptDate = S.draft.inviteDate || d0.date;\n    S.draft.apptTime = S.draft.inviteTime || d0.time;\n    ACTIONS.apptNew();\n  },\n  apptToggleChar: el => {\n    const arr = (S.draft.apptCharIds || []).slice();\n    const i = arr.indexOf(el.dataset.id);\n    if (i >= 0) arr.splice(i, 1); else arr.push(el.dataset.id);\n    S.draft.apptCharIds = arr;\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  apptClearChar: () => { S.draft.apptCharIds = []; closeAllSheets(); ACTIONS.apptNew(); },\n  apptRandomChar: () => {\n    if (!S.chars.length) return;\n    const c = S.chars[Math.floor(Math.random() * S.chars.length)];\n    S.draft.apptCharIds = [c.id];\n    closeAllSheets(); ACTIONS.apptNew();\n  },\n  apptAdvanced: () => {\n    openSheet(`<h3>催促节奏</h3>\n      <div class=\"tiny\">默认 T-10 / T-5 / T-0，可改；对新预约生效。</div>\n      <div class=\"row\" style=\"gap:10px\">\n        <div class=\"grow\"><label class=\"fl\">提前（分钟）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptAdvanceMin\" data-num=\"1\" value=\"${apptAdvance()}\"></div>\n        <div class=\"grow\"><label class=\"fl\">间隔（分钟）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptGapMin\" data-num=\"1\" value=\"${apptGap()}\"></div>\n        <div class=\"grow\"><label class=\"fl\">催几次</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptMaxNudge\" data-num=\"1\" value=\"${apptMaxNudge()}\"></div>\n      </div>\n      <label class=\"fl\">第 ${apptMaxNudge()} 次之后多久开罚（分钟，0 = 立刻）</label>\n      <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.apptGraceMin\" data-num=\"1\" value=\"${apptGrace()}\">\n      <button class=\"btn primary block mt12\" data-act=\"apptBackForm\">回到预约表单</button>`);\n  },\n  apptBackForm: () => { closeAllSheets(); ACTIONS.apptNew(); },\n  apptSave: async () => {\n    const segs = (S.draft.apptSegs || []).filter(s => s && String(s.content || '').trim()).map(s => ({ content: String(s.content).trim().slice(0, 60), min: clamp(Number(s.min) || 0, 0, 600) }));\n    let task = String(S.draft.apptTask || '').trim();\n    if (!task && segs.length) task = segs[0].content;\n    if (!task) { toast('先写清楚这次要做什么（分段任务里至少填一段）'); return; }\n    const charIds = (S.draft.apptCharIds || []).filter(id => charById(id));\n    if (!charIds.length) { toast('至少选一位监督陪伴的角色'); return; }\n    const startAt = apptParse();\n    if (!startAt) { toast('日期或时间格式不对'); return; }\n    if (startAt - Date.now() < 60000) { toast('开始时间要晚于现在（至少留 1 分钟）'); return; }\n    const segTotal = sum(segs.map(s => s.min));\n    const minutes = clamp(segTotal > 0 ? segTotal : (Number(S.draft.apptMinutes) || 25), 1, 600);\n    const breakMin = Math.max(1, Number(S.draft.apptBreakMin != null ? S.draft.apptBreakMin : (cfg('breakMin') || 5)) || 5);\n    const reviewEvery = S.draft.apptReview === 'session' ? 'session' : 'focus';\n    const d = new Date(startAt);\n    const editing = S.draft.apptEditId ? (S.appts || []).find(x => String(x.id) === String(S.draft.apptEditId)) : null;\n    const rec = editing || {\n      id: '', date: '', time: '', startAt: 0, minutes: 0, task: '',\n      charIds: [], status: 'pending', nudgeCount: 0, createdAt: Date.now(), note: ''\n    };\n    rec.date = dkey(d); rec.time = pad2(d.getHours()) + ':' + pad2(d.getMinutes());\n    rec.startAt = startAt; rec.minutes = minutes; rec.task = task.slice(0, 60);\n    rec.charIds = charIds.slice();\n    rec.segments = segs;\n    rec.breakMin = breakMin;\n    rec.reviewEvery = reviewEvery;\n    rec.status = 'pending'; rec.nudgeCount = 0; rec.startedAt = 0; rec.missedAt = 0;\n    const nowMs = Date.now();\n    rec.note = editing ? '已改期（催促按新时间重排）' : '';\n    if (startAt - nowMs < apptAdvance() * 60000) {\n      // 离开始不足「提前量」时，前面几次催促来不及发出；但规矩不变，仍会在开始时间后开罚\n      rec.nudgeCount = apptTimesOf(rec).filter(t => t < nowMs - 60000).length;\n      rec.note += '离开始不足 ' + apptAdvance() + ' 分钟，前面 ' + rec.nudgeCount + ' 次催促来不及发出（还是会按约定开罚）';\n    }\n    if (editing) await updateAppt(rec); else await createAppt(rec);\n    S.draft.apptEditId = '';\n    /* 这次是给「TA 的邀请」改时间：把那条邀请记为已答应，并指向这条预约 */\n    if (S.draft.inviteReschedId) {\n      const inv0 = (S.invites || []).find(x => String(x.id) === String(S.draft.inviteReschedId));\n      if (inv0) {\n        inv0.status = 'accepted';\n        inv0.acceptedAt = inv0.acceptedAt || Date.now();\n        inv0.apptId = rec.id;\n        inv0.reschedAt = Date.now();\n        if (inv0.id) await DB.update(T.INVITE, inv0.id, JSON.parse(JSON.stringify(inv0)));\n      }\n      S.draft.inviteReschedId = '';\n    }\n    const n = await scheduleAppt(rec);\n    const cid = charIds[0];\n    await syncTimeline(cid, '用户和' + charName(cid) + '约好 ' + rec.date + ' ' + rec.time + ' 一起专注 ' + minutes + ' 分钟：' + rec.task\n      + '。到时' + charName(cid) + '要负责催他开始（提前 ' + apptAdvance() + ' 分钟开始催，每 ' + apptGap() + ' 分钟一次，共 ' + apptMaxNudge() + ' 次），连着催 ' + apptMaxNudge() + ' 次没开始就按规矩罚。', 'appt_make', {});\n    await sdk(() => API.chat.writeHistory({\n      characterId: cid, role: 'system',\n      content: '[预约专注] 我和' + charName(cid) + '约好 ' + rec.date + ' ' + rec.time + ' 一起专注 ' + minutes + ' 分钟，内容是「' + rec.task + '」。到时候你要来催我。'\n    }), null);\n    S.draft.apptTask = '';\n    closeAllSheets();\n    toast(n ? ((editing ? '已改期：' : '约好了：') + rec.date + ' ' + rec.time + ' · 已排好 ' + n + ' 次催促')\n      : (editing ? '已改期（宿主定时任务不可用，到时自己留意）' : '预约已记下（宿主定时任务不可用，到时请自己留意）'));\n    if (S.view !== 'appt') go('appt'); else render();\n  },\n  apptEdit: el => {\n    const a = (S.appts || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!a) return;\n    const d = new Date(a.startAt);\n    S.draft.apptDate = dkey(d);\n    S.draft.apptTime = pad2(d.getHours()) + ':' + pad2(d.getMinutes());\n    S.draft.apptMinutes = a.minutes;\n    S.draft.apptTask = a.task;\n    S.draft.apptCharIds = (a.charIds || []).slice();\n    S.draft.apptSegs = (a.segments && a.segments.length) ? a.segments.map(s => ({ content: s.content, min: s.min })) : [{ content: a.task || '', min: Number(a.minutes) || 25 }];\n    S.draft.apptBreakMin = Number(a.breakMin != null ? a.breakMin : (cfg('breakMin') || 5));\n    S.draft.apptReview = a.reviewEvery === 'session' ? 'session' : 'focus';\n    S.draft.apptEditId = a.id;\n    closeAllSheets();\n    ACTIONS.apptNew();\n    const sheet = modalStack[modalStack.length - 1];\n    if (sheet) {\n      const tip = document.createElement('div');\n      tip.className = 'tiny';\n      tip.style.cssText = 'background:var(--accent-soft);border-radius:10px;padding:9px;margin-bottom:8px';\n      tip.textContent = '正在修改已有的预约（保存后会覆盖原预约，并按新时间重排催促）。';\n      const inner = sheet.querySelector('.sheet');\n      if (inner) inner.insertBefore(tip, inner.firstChild.nextSibling);\n    }\n  },\n  apptCancel: async el => {\n    const a = (S.appts || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!a) return;\n    const ok = await confirmBox('取消这个预约？',\n      '已经排进小手机后台的催促任务宿主没有撤回接口，到点可能仍会响一次通知 —— 忽略即可；APP 这边不会再拿它开罚。', '取消预约');\n    if (!ok) return;\n    a.status = 'canceled'; a.note = '已取消' + (a.nudgeCount ? '（取消前已被催 ' + a.nudgeCount + ' 次）' : '');\n    await updateAppt(a);\n    closeAllSheets(); toast('已取消'); render();\n  },\n  apptDel: async el => {\n    const a = (S.appts || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!a) return;\n    if (a.status === 'started') { toast('正在专注中的预约不能删'); return; }\n    await removeAppt(a); render();\n  },\n  apptSnoozeSheet: () => {\n    if (S.draft) S.draft.apptSheetFor = '';\n    closeAllSheets();\n    toast('先记着你这一会儿 —— TA 马上还会来催');\n  },\n  assistSessionPick: el => { S.draft.assistForSession = el.dataset.v === '' ? null : el.dataset.v; render(); },\n  lockedAppsSheet: () => openLockedAppsSheet(),\n  widgetPin: () => {\n    if (typeof API === 'undefined' || !API || !API.device || !API.device.focusWidgetPin) { toast('当前环境不支持桌面组件'); return; }\n    sdk(() => API.device.focusWidgetPin(), null).then((r) => {\n      toast(r && r.ok ? '已拉起系统添加组件引导' : ((r && r.reason) || '添加未成功'));\n      render();\n    }).catch(() => { });\n  },\n  lockedAppsPick: () => pickFromAppList('whitelist'),\n  lockedAppsAdd: async () => {\n    const name = (document.getElementById('laName') || {}).value || '';\n    if (!name.trim()) { toast('写个应用名称'); return; }\n    S.settings.lockedApps = (cfg('lockedApps') || []).concat([{ name: name.trim(), pkg: '' }]);\n    await saveSettings(true);\n    toast('🧱 已加入常驻白名单：' + name.trim());\n    openLockedAppsSheet(); render();\n  },\n  lockedAppsDel: async el => {\n    const i = Number(el.dataset.i);\n    S.settings.lockedApps = (cfg('lockedApps') || []).filter((x, k) => k !== i);\n    await saveSettings(true);\n    openLockedAppsSheet(); render();\n  },\n  appPickerOpen: el => { pickFromAppList(el.dataset.target || 'apply'); },\n  focusLevelPick: async el => {\n    S.settings.focusLevel = el.dataset.v;\n    await saveSettings(true);\n    toast({ off: '锁机已关闭', L1: 'L1 提醒锁：勿扰 + 离开系统通知', L2: 'L2 看守锁：白名单外应用会被带回小手机（需新版 APK）', L3: 'L3 承诺死锁：开始专注前要签承诺书' }[el.dataset.v] || '已更新');\n    render();\n  },\n  pledgeStart: async () => {\n    const o = S.draft.pledgeOpts || {};\n    closeAllSheets();\n    await startSession(Object.assign({}, o, { pledged: true }));\n  },\n  wlApplyOpen: el => {\n    const ds = (el && el.dataset) || {};\n    const perm = ds.perm === '1';\n    S.draft.wlMinutes = 15;\n    S.draft.wlMinutesCustom = '';\n    if (ds.app) {\n      /* 推荐/旧档案直接带入单个应用，仍走审批 */\n      S.draft.applyApps = [{ label: ds.app, pkg: ds.pkg || '' }];\n      openMultiApply(perm ? 'perm' : 'pass', S.draft.applyApps);\n      return;\n    }\n    S.draft.applyApps = [];\n    pickFromAppList(perm ? 'permApply' : 'passApply');\n  },\n  wlSheetOpen: () => openWlSheet(),\n  wlReasonPick: el => { S.draft.wlReason = el.dataset.v; openWlApply({ app: S.draft.wlAppName, reason: S.draft.wlReason }); },\n  wlMinPick: el => { S.draft.wlMinutes = Number(el.dataset.v) || 15; openWlApply({ app: S.draft.wlAppName, reason: S.draft.wlReason }); },\n  wlSubmit: () => submitWlApply(),\n  multiReasonPick: el => { S.draft.wlReason = el.dataset.v; openMultiApply(S.draft.applyMode, S.draft.applyApps); },\n  multiMinPick: el => { S.draft.wlMinutes = Number(el.dataset.v) || 15; openMultiApply(S.draft.applyMode, S.draft.applyApps); },\n  multiApplySubmit: () => { submitMultiApply(); },\n  multiRepick: () => { pickFromAppList(S.draft.applyMode === 'perm' ? 'permApply' : 'passApply'); },\n  recWhitelistAdd: el => {\n    const ds = (el && el.dataset) || {};\n    if (!ds.pkg) { toast('这个应用没有包名，无法放行'); return; }\n    const cur = cfg('lockedApps') || [];\n    const map = new Map(cur.filter(x => x.pkg).map(x => [x.pkg, x]));\n    map.set(ds.pkg, { name: ds.app || ds.pkg, pkg: ds.pkg });\n    S.settings.lockedApps = Array.from(map.values());\n    saveSettings(true);\n    syncLockNow();\n    toast('🧱 已按 TA 推荐放行：' + (ds.app || ds.pkg));\n    render();\n    if (typeof openLockedAppsSheet === 'function') openLockedAppsSheet();\n  },\n  wlCheckinPhoto: () => wlCheckinPhoto(),\n  wlRevoke: async el => {\n    const p = (S.wlPasses || []).find(x => x.id === el.dataset.id);\n    if (!p) return;\n    p.status = 'revoked';\n    if (p.dbId) await DB.update(T.WLP, p.dbId, JSON.parse(JSON.stringify(p)));\n    cancelWlCheckinNative(p.id);\n    toast('通行证已作废：' + p.app);\n    syncLockNow();\n    openWlSheet(); render();\n  },\n  apptStart: async el => {\n    const a = (S.appts || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!a) return;\n    closeAllSheets(); if (S.draft) S.draft.apptSheetFor = '';\n    if (a.status !== 'pending') { toast('这个预约已经处理过了'); return; }\n    if (pendingPunish().length) { toast('先把没完成的惩罚做完，再开始专注'); S.lock = { punish: pendingPunish()[0] }; render(); return; }\n    a.status = 'started'; a.startedAt = Date.now(); a.note = '按时开始';\n    await updateAppt(a);\n    const cid = (a.charIds && a.charIds[0]) || anyCharId();\n    await syncTimeline(cid, '用户按时开始了和' + charName(cid) + '约好的专注：' + a.task + '（' + a.minutes + ' 分钟）。', 'appt_start', {});\n    await addBond(cid, 3, '按时开始约好的专注');\n    const ids = ((a.charIds && a.charIds.length) ? a.charIds : [anyCharId()]).filter(Boolean);\n    const opt = sessionOptsFromAppt(a, a.task, a.minutes);\n    await startSession({\n      charIds: ids, focusMin: opt.focusMin, breakMin: opt.breakMin, cycles: opt.cycles,\n      plan: opt.plan, reviewEvery: opt.reviewEvery, voiceOn: cfg('voiceMode') !== 'off'\n    });\n  },\n  /* 立刻催一次：手动验证通知 / 聊天室卡片 / TA 会不会开口 */\n  apptTestNudge: async () => {\n    const cid = anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    const name = charName(cid);\n    toast('正在让 TA 来催你一次…');\n    await sdk(() => API.notifications.create({ title: '🗓 ' + name + ' 来催你了（试发）', body: '这是测试：到点前 TA 就会这样来催你。' }), null);\n    const cardOk = await sdk(() => API.chat.sendCard({\n      characterId: cid, role: 'system', historyRole: 'system',\n      summary: name + '提醒用户准备开始专注（试发）',\n      historyText: '[预约专注·试发] ' + name + '提醒用户准备开始专注。',\n      card: {\n        appLabel: '角色陪伴专注', title: '预约专注 · 试发提醒', subtitle: 'APPOINTMENT',\n        status: 'TA 该来催你了', accentColor: '#7c8cff', height: 220,\n        sections: [{ title: '提醒内容', rows: [\n          { label: '由谁监督', value: name },\n          { label: '该做的事', value: '准备开始专注' }\n        ] }]\n      }\n    }), null);\n    if (cardOk) { try { await API.chat.requestReply({ characterId: cid }); } catch (e) { } }\n    toast(cardOk ? '已发到聊天室，去那里看 TA 的反应' : '通知已发；聊天室卡片发送失败');\n  },\n  apptTestPunish: async () => {\n    const ok = await confirmBox('试一次「预约没开始」的开罚？', '会立刻从惩罚库里抽一项、并进入全屏惩罚锁定（就是真的罚，不是演练）。', '试一下');\n    if (!ok) return;\n    await punishMissedAppt({ task: '（测试）约好的专注', charIds: [anyCharId()], nudgeCount: apptMaxNudge() });\n  }\n});\nfunction apptParse() {\n  const dp = String(S.draft.apptDate || '').split('-').map(Number);\n  const tp = String(S.draft.apptTime || '').split(':').map(Number);\n  if (!dp[0] || !dp[1] || !dp[2]) return 0;\n  const d = new Date(dp[0], dp[1] - 1, dp[2], tp[0] || 0, tp[1] || 0, 0, 0);\n  return d.getTime() || 0;\n}\n/* ==========================================================\n   视图 · TA 的心愿（你陪他一起实现）\n   ========================================================== */\nconst WISH_RULES = [\n  ['↑', '一次专注通过考核 —— 这段专注的分钟数全数加进心愿'],\n  ['📌', '没通过的轮次不加 —— 只有通过考核的专注才算'],\n  ['📌', '睡眠、惩罚、花专注币这些不算推进 —— 心愿只认专注'],\n  ['📌', '进度只增不减：不会因为失误或爽约倒退（连坐已移除）']\n];\nVIEWS.bond = function () {\n  const ids = (S.chars || []).map(c => c.id);\n  if (!ids.length) return `<div class=\"card\"><h3>还没有角色</h3><div class=\"sub\">先在小手机聊天 APP 里创建角色。</div></div>`;\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,123,138,.12),rgba(124,140,255,.1));border-color:rgba(124,140,255,.3)\">\n    <h3>💞 TA 的心愿</h3>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">不是你许愿让 TA 满足你 —— 是反过来：<b>TA 心里有一件一直想要的事，只有你陪他一起投入足够多的专注时间，它才会真的实现。</b><br>\n    让 TA 自己说出来（AI 会按他的人设和记忆生成，那件事换成别人就不成立），你也可以替他写。<br>\n    推进它的只有专注：<b>每通过一次考核，这段专注的分钟数就加进心愿进度</b>。攒够需要的分钟，就能「真正实现」——APP 会写出实现那一刻的画面和 TA 说的话，做一张卡写进聊天室。<br>\n    进度只增不减，全程没有可以手动加的数值。</div>\n  </div>\n  ${ids.map(id => {\n    const c = charById(id), w = wishOf(id), p = wishGain(w), need = wishNeedOf(w);\n    const logs = wishEntries(w).slice().sort((a, b) => b.at - a.at);\n    const his = wishDoneList(id);\n    const hisHTML = his.length ? `<div class=\"hr\"></div><div class=\"tiny\">你们已经一起实现过（${his.length}）</div>\n      ${his.slice(0, 4).map(h => `<div class=\"item\" style=\"padding:7px 0\"><div class=\"ic\">🌠</div>\n        <div class=\"grow\" data-act=\"wishOpenScene\" data-id=\"${esc(h.id)}\" style=\"cursor:pointer\">\n          <div style=\"font-size:12.8px\">${esc(h.text)}</div>\n          <div class=\"tiny\">${dkey(new Date(h.doneAt || h.at))} · 一起投入 ${esc(wishMinText(h.doneMin || wishGain(h)))}${h.finalLine ? ' · 「' + esc(String(h.finalLine).slice(0, 26)) + '」' : ''}</div></div>\n        <div class=\"ic\">›</div></div>`).join('')}` : '';\n    if (!w) return `<div class=\"card\">\n      <div class=\"row\">${charAvatar(c, 'avatar lg')}<div class=\"grow\" style=\"min-width:0\">\n        <div class=\"row between\"><b>${esc(c ? c.name : '角色')}</b><span class=\"pill\">还没说出他想要什么</span></div>\n        <div class=\"tiny\">让 TA 自己说一件他心底一直想要的事 —— 那会是一件只有你陪着他攒够时间才能实现的事。</div></div></div>\n      <button class=\"btn primary block mt10\" data-act=\"wishGen\" data-id=\"${esc(id)}\" ${S.loading === 'wishgen' ? 'disabled' : ''}>${S.loading === 'wishgen' ? 'TA 正在想…' : '💭 让 TA 说出他心底想要的事'}</button>\n      <button class=\"btn ghost block mt8\" data-act=\"wishWrite\" data-id=\"${esc(id)}\">我来替他写一件</button>\n      ${hisHTML}</div>`;\n    const left = wishLeftMin(w), rd = wishReady(w);\n    return `<div class=\"card\" style=\"border-color:${rd ? 'rgba(255,201,120,.55)' : 'rgba(124,140,255,.3)'}\">\n      <div class=\"row\">${charAvatar(c)}\n        <div class=\"grow\" style=\"min-width:0\">\n          <div class=\"row between\"><b>${esc(c ? c.name : '角色')} 心底的事</b>\n            <span class=\"pill ${rd ? 'warn' : 'run'}\">${rd ? '可以实现它了' : '还在攒'}</span></div>\n          <div class=\"tiny\">${w.from === 'me' ? '你替他写的' : 'TA 自己说的'} · ${dkey(new Date(w.at))}</div></div></div>\n      <div style=\"font-size:16px;font-weight:600;margin-top:8px\">${esc(w.text)}</div>\n      ${w.why ? `<div class=\"tiny mt6\" style=\"font-size:12.4px;line-height:1.7;color:var(--dim)\">${esc(w.why)}</div>` : ''}\n      <div class=\"bar mt10\"><i style=\"width:${wishPct(w)}%\"></i></div>\n      <div class=\"tiny mt6\">${rd ? '你们一起攒够了 ' + wishMinText(need) + ' —— 去实现它' : '一起攒了 ' + p + ' / ' + need + ' 分钟 · 还差 ' + wishMinText(left)}</div>\n      <div class=\"tiny mt6\" style=\"color:var(--dim2)\">只有「通过考核的专注」会推进它：一次考核通过，这段专注多少分钟就加多少分钟。</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn ${rd ? 'primary' : 'ghost'} grow\" data-act=\"wishFinish\" data-id=\"${esc(id)}\" ${rd ? '' : 'disabled'}>${rd ? '🌠 让它真正实现' : '还差 ' + wishMinText(left)}</button>\n        <button class=\"btn ghost\" data-act=\"wishTell\" data-id=\"${esc(id)}\">再说一遍</button>\n        <button class=\"btn ghost\" data-act=\"wishChange\" data-id=\"${esc(id)}\">换一件</button></div>\n      ${logs.length ? `<div class=\"hr\"></div>\n        <div class=\"row between\"><span class=\"tiny\">你们一起攒下的（${logs.length} 笔）· 不能手动改</span>\n          <button class=\"btn sm ghost\" data-act=\"wishClearLog\" data-id=\"${esc(id)}\">清空流水</button></div>\n        ${logs.slice(0, 14).map(e => `<div class=\"item\" style=\"padding:7px 0\">\n          <div class=\"ic\" style=\"color:${e.d > 0 ? 'var(--teal)' : '#ff9aa6'}\">${e.d > 0 ? '＋' : '−'}</div>\n          <div class=\"grow\"><div style=\"font-size:12.6px;color:${e.d > 0 ? 'inherit' : '#ffb3bd'}\">${esc(e.why)}</div>\n          <div class=\"tiny\">${dkey(new Date(e.at))} ${hm(e.at)} · ${e.d > 0 ? '+' : ''}${e.d} 分钟${e.kind === 'connect' ? ' · 连坐' : ''}</div></div></div>`).join('')}` : `<div class=\"tiny mt8\">还没有流水。去专注 —— 通过一次考核，就在这里记下第一笔。</div>`}\n      ${hisHTML}</div>`;\n  }).join('')}\n  <div class=\"card\"><h3>什么会推动它</h3>\n    ${WISH_RULES.map(([d, w]) => `<div class=\"item\" style=\"padding:7px 0\">\n      <div class=\"ic\" style=\"color:${d === '↓' ? '#ff9aa6' : (d === '↑' ? 'var(--teal)' : 'var(--dim2)')}\">${d}</div>\n      <div class=\"grow\" style=\"font-size:12.5px\">${esc(w)}</div></div>`).join('')}\n    <div class=\"tiny mt6\">每笔流水都带时间、写进 TA 的短期记忆事件流 —— 所以你在普通聊天里，TA 是记得你最近为他攒了多少时间的。</div></div>\n  <div class=\"card\"><h3>心愿设置</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">默认需要多少分钟专注才能实现</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.wishNeedMin\" data-num=\"1\" value=\"${wishNeedMin()}\"></div>\n    </div>\n    <div class=\"chips mt6\">\n      <button class=\"chip ${cfg('wishNotice') !== false ? 'on' : ''}\" data-act=\"toggleSetting\" data-k=\"wishNotice\">攒够时让 TA 先说一句（并用语音读出来）</button>\n    </div>\n    <div class=\"tiny mt6\">连坐已移除：你的失误不会再让心愿进度倒退，也不会再出现「因为你，TA 差一点没做完」这类判定。</div>\n    <div class=\"tiny mt6\">攒够后点「让它真正实现」：APP 会写出实现那一刻的画面和 TA 说的话，连同「你们一起投入了多少时间」做一张卡写进聊天室；实现过的会留在这页下面，随时能回看。</div></div>`;\n};\n/* ==========================================================\n   视图 · 专注币\n   ========================================================== */\nVIEWS.coin = function () {\n  const log = coinLog();\n  const freePass = Number(cfg('freePass')) || 0;\n  const pardoned = cfg('pardonDate') === dkey();\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,201,120,.16),rgba(255,255,255,.03));border-color:rgba(255,201,120,.35)\">\n    <div class=\"row between\"><div><div style=\"font-size:34px;font-weight:300;letter-spacing:1px\">${coinBal()}<span class=\"tiny\" style=\"font-size:13px\"> 点</span></div>\n      <div class=\"tiny\">专注币余额 · 按专注时长 1 分钟 = ${coinRate()} 点</div></div>\n      <div style=\"font-size:34px\">🪙</div></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${coinToday()}</div><div class=\"tiny\">今日获得</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${coinTotal()}</div><div class=\"tiny\">累计获得</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${freePass}</div><div class=\"tiny\">免罚卡</div></div>\n      <div class=\"grow center\"><div style=\"font-size:16px;font-weight:600\">${log.filter(x => x.d < 0).length}</div><div class=\"tiny\">兑换次数</div></div>\n    </div>\n    ${pardoned ? `<div class=\"tiny mt8\" style=\"color:var(--gold)\">今天已用「放你一马」：今天的违规只记录、不罚。</div>` : ''}\n  </div>\n  <div class=\"card\"><h3>怎么赚</h3>\n    <div class=\"tiny\" style=\"line-height:1.8\">通过考核的那段专注会折算成专注币：<b>专注分钟 × ${coinRate()} 点</b>${coinBonus() ? '，通过考核再额外 +' + coinBonus() + '%' : ''}。<br>\n    没通过的轮次不给币（不然就白罚了）；惩罚、睡眠都不给、也不扣 —— 专注币只反映你真学进去的时间。</div>\n  </div>\n  <div class=\"card\"><h3>兑换商店</h3>\n    ${COIN_SHOP.map(it => `<div class=\"card tight\" style=\"background:var(--card2)\">\n      <div class=\"row between\"><div class=\"grow\"><div style=\"font-size:14px\">${it.icon} ${esc(it.name)}</div>\n        <div class=\"tiny mt6\">${esc(it.desc)}</div></div>\n        <div style=\"text-align:right\"><div style=\"font-size:14px;font-weight:600;color:var(--gold)\">${it.cost}</div>\n        <div class=\"tiny\">点</div></div></div>\n      <button class=\"btn ${coinBal() >= it.cost ? 'primary' : 'ghost'} block sm mt10\" data-act=\"coinBuy\" data-k=\"${it.k}\"\n        ${coinBal() >= it.cost ? '' : 'disabled'}>${coinBal() >= it.cost ? '兑换' : '还差 ' + (it.cost - coinBal()) + ' 点'}</button>\n    </div>`).join('')}\n    <div class=\"tiny mt6\">免罚卡在惩罚锁定页会以「🎫 用免罚卡」出现；「今天放你一马」对今天的违规生效一次。</div></div>\n  <div class=\"card\"><h3>换算规则</h3>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">每分钟专注给多少点</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" step=\"0.5\" data-in=\"setting.coinRate\" data-num=\"1\" value=\"${coinRate()}\"></div>\n      <div class=\"grow\"><label class=\"fl\">通过考核加成（%）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.coinBonus\" data-num=\"1\" value=\"${coinBonus()}\"></div>\n    </div>\n    <div class=\"tiny mt6\">调大之后要重新通过一次考核才会体现，已经赚到的不会补发。</div>\n    <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"coinAdjust\">手动修正余额</button>\n      <button class=\"btn sm ghost grow\" data-act=\"coinClear\">清空明细</button></div></div>\n  ${(function () {\n      const c = coinDeductCfg();\n      return `<div class=\"card\" style=\"border-color:${c.on ? 'rgba(255,123,138,.45)' : 'var(--line)'}\">\n    <div class=\"row between\"><h3>违规扣专注币</h3>\n      <button class=\"chip ${c.on ? 'on' : ''}\" data-act=\"coinDeductToggle\">${c.on ? '已开启' : '关闭中'}</button></div>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">打开后，下面填了数值的违规会<b>额外扣专注币</b>。这不是替代原有惩罚 —— 转账、做题、抄写那些照旧执行，扣币是叠加上去的。<br>\n    余额<b>允许扣成负数</b>：扣到负数也会如实记下来，只是负数时换不了东西（兑换仍会拦「不够」）。</div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">失约扣多少</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.coinDeduct.miss\" data-num=\"1\" value=\"${Number(c.miss) || 0}\"></div>\n      <div class=\"grow\"><label class=\"fl\">中途离开</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.coinDeduct.leave\" data-num=\"1\" value=\"${Number(c.leave) || 0}\"></div>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">考核未通过</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.coinDeduct.fail\" data-num=\"1\" value=\"${Number(c.fail) || 0}\"></div>\n      <div class=\"grow\"><label class=\"fl\">任务超时</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.coinDeduct.timeout\" data-num=\"1\" value=\"${Number(c.timeout) || 0}\"></div>\n    </div>\n    <div class=\"tiny mt6\">填 0 就是这一类不扣。改完不用点保存 —— 输入即生效（会随设置一起落库）。</div>\n    <div class=\"tiny mt6\" style=\"color:var(--dim2)\">当前余额 <b style=\"color:${coinBal() < 0 ? '#ff9aa6' : 'var(--gold)'}\">${coinBal()}</b> 点${coinBal() < 0 ? '（负数：说明被扣超了，学回来就行）' : ''}。每次扣除都会记进下面的收支明细。</div>\n  </div>`;\n    })()}\n  <div class=\"card\"><h3>收支明细（${log.length}）</h3>\n    ${log.length ? log.slice(0, 40).map(x => `<div class=\"item\" style=\"padding:8px 0\">\n      <div class=\"ic\" style=\"color:${x.d > 0 ? 'var(--teal)' : '#ff9aa6'}\">${x.d > 0 ? '🪙' : '🎁'}</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${esc(x.why || '')}</div>\n        <div class=\"tiny\">${dkey(new Date(x.at))} ${hm(x.at)}</div></div>\n      <div style=\"font-size:13.5px;color:${x.d > 0 ? 'var(--teal)' : '#ff9aa6'}\">${x.d > 0 ? '+' : ''}${x.d}</div></div>`).join('')\n      : `<div class=\"empty\" style=\"padding:10px\">还没有记录，去完成一段专注吧。</div>`}</div>`;\n};\n/* ==========================================================\n   视图 · 目标与倒计时\n   ========================================================== */\nVIEWS.goals = function () {\n  const list = goals().slice().sort((a, b) => goalDays(a) - goalDays(b));\n  const act = activeGoal();\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03));border-color:rgba(94,234,212,.3)\">\n    <h3>🎯 目标与倒计时</h3>\n    <div class=\"tiny mt6\">写下考试/提交日期：首页挂倒计时，TA 的督促语气跟着剩余时间变。</div>\n  </div>\n  ${act ? `<div class=\"card glow\"><div class=\"row between\">\n      <div class=\"grow\"><h3>${esc(act.name)}</h3>\n      <div class=\"tiny\">${esc(act.date)} · ${esc(goalPhase(goalDays(act)))}</div></div>\n      <div style=\"text-align:right\"><div style=\"font-size:30px;font-weight:300;color:var(--teal)\">${Math.max(0, goalDays(act))}</div>\n      <div class=\"tiny\">天后</div></div></div>\n    <div class=\"bar mt10\"><i style=\"width:${clamp(100 - (goalDays(act) / 180 * 100), 4, 100)}%\"></i></div>\n    <div class=\"tiny mt6\">${goalPromptLine()}</div></div>` : ''}\n  <div class=\"card\"><h3>＋ 添加一个目标</h3>\n    <label class=\"fl\">目标名称</label>\n    <input class=\"input\" id=\"goalName\" placeholder=\"例如：考研 / 六级 / 论文提交 / 面试\">\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">日期</label><input class=\"input\" type=\"date\" id=\"goalDate\" value=\"${esc(dkey())}\"></div>\n    </div>\n    <label class=\"fl\">一句话备注（可留空，会一起给 TA 看）</label>\n    <input class=\"input\" id=\"goalNote\" placeholder=\"例如：目标院校 XX，专业课两门\">\n    <button class=\"btn primary block mt12\" data-act=\"goalSave\">加上这个目标</button></div>\n  ${list.length ? list.map(g => {\n    const d = goalDays(g);\n    return `<div class=\"card tight\">\n    <div class=\"row between\"><div class=\"grow\">\n      <div style=\"font-size:14px\">${g.done ? '✅ ' : ''}${esc(g.name)}</div>\n      <div class=\"tiny\">${esc(g.date)} · ${esc(goalPhase(d))}${g.note ? ' · ' + esc(g.note) : ''}</div></div>\n      <div style=\"text-align:right\"><div style=\"font-size:20px;font-weight:600;color:${d < 0 ? 'var(--dim2)' : d <= 7 ? 'var(--gold)' : 'var(--teal)'}\">${d >= 0 ? d : '—'}</div>\n      <div class=\"tiny\">${d >= 0 ? '天' : '已过'}</div></div></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"goalTell\" data-id=\"${esc(g.id)}\">告诉 TA</button>\n      <button class=\"btn sm ghost grow\" data-act=\"goalDone\" data-id=\"${esc(g.id)}\">${g.done ? '取消完成' : '标记完成'}</button>\n      <button class=\"btn sm ghost\" data-act=\"goalDel\" data-id=\"${esc(g.id)}\">删</button></div>\n  </div>`;\n  }).join('') : `<div class=\"empty\">还没有设目标。<br>设一个，首页就会有倒计时，TA 的督促也会跟着变。</div>`}`;\n};\nObject.assign(ACTIONS, {\n  /* ---- TA 的心愿：让 TA 说 / 替他写 / 实现它 / 换一件 ---- */\n  wishGen: async el => {\n    const cid = el.dataset.id || anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    await wishGenAI(cid);\n  },\n  wishWrite: el => {\n    const cid = el.dataset.id || anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    const examples = ['想和你一起看完的那片海', '想让你陪我走完的一条路', '一直想亲手交到你手里的东西', '想和你一起看完的一场雪', '想听到你对我说的那句话'];\n    openSheet(`<h3>替他写一件他心底的事</h3>\n      <div class=\"tiny\">写一件「只有你陪他攒够时间才会实现」的事。他会把它当成自己一直想要的东西记住。</div>\n      <label class=\"fl\">他心底想要的事</label>\n      <input class=\"input\" id=\"wishText\" placeholder=\"例如：想和你一起看完的那片海\">\n      <div class=\"chips mt6\">${examples.map(x => `<button class=\"chip\" data-act=\"wishPick\" data-v=\"${esc(x)}\">${esc(x)}</button>`).join('')}</div>\n      <label class=\"fl\">为什么这对 TA 重要（可留空，会一起给 TA 看）</label>\n      <input class=\"input\" id=\"wishWhy\" placeholder=\"例如：他总说自己没有好好看过一次日出\">\n      <label class=\"fl\">需要你们一起攒多少分钟专注</label>\n      <input class=\"input\" type=\"number\" inputmode=\"numeric\" id=\"wishNeedBox\" value=\"${wishNeedMin()}\">\n      <div class=\"tiny mt6\">默认 ${wishNeedMin()} 分钟 ≈ ${wishMinText(wishNeedMin())}。按一段专注 25 分钟算，大约是 ${Math.max(1, Math.round(wishNeedMin() / 25))} 次通过的专注。</div>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">算了</button>\n        <button class=\"btn primary grow\" data-act=\"wishWriteSave\" data-id=\"${esc(cid)}\">就这件，交给他</button></div>`);\n  },\n  wishPick: el => {\n    const box = document.getElementById('wishText');\n    if (box) box.value = el.dataset.v;\n    document.querySelectorAll('[data-act=\"wishPick\"]').forEach(x => x.classList.toggle('on', x === el));\n  },\n  wishWriteSave: async el => {\n    const cid = el.dataset.id || anyCharId();\n    const text = ((document.getElementById('wishText') || {}).value || '').trim();\n    const why = ((document.getElementById('wishWhy') || {}).value || '').trim();\n    const need = clamp(Number((document.getElementById('wishNeedBox') || {}).value) || wishNeedMin(), 30, 20000);\n    if (!text) { toast('先写一件他心底想要的事'); return; }\n    if (!cid) { toast('还没有角色'); return; }\n    await wishMake(cid, { text: text, why: why, need: need, from: 'me' });\n    closeAllSheets();\n    toast('已交给他：' + text + '（一起攒够 ' + wishMinText(need) + ' 就能实现）');\n    if (S.view !== 'bond') go('bond'); else render();\n  },\n  wishTell: async el => {\n    const cid = el.dataset.id || anyCharId();\n    const w = wishOf(cid);\n    if (!w) { toast('TA 还没有说出他想要什么'); return; }\n    await wishTell(cid, w);\n    toast('已重新告诉他，去聊天室说一句吧');\n  },\n  wishFinish: async el => {\n    const cid = el.dataset.id || anyCharId();\n    const w = wishOf(cid);\n    if (!w) { toast('还没有心愿'); return; }\n    if (!wishReady(w)) { toast('还没攒够：还差 ' + wishMinText(wishLeftMin(w))); return; }\n    const ok = await confirmBox('让它真正实现？', '「' + w.text + '」\\n\\n你们一起攒了 ' + wishMinText(wishGain(w)) + '。'\n      + '点了之后，APP 会写出实现那一刻的画面和他对你说的话，并做一张卡写进聊天室。', '让它实现');\n    if (!ok) return;\n    await wishFinishDo(cid, w);\n  },\n  wishChange: async el => {\n    const cid = el.dataset.id || anyCharId();\n    if (!cid) return;\n    const w = wishOf(cid);\n    const ok = await confirmBox('换一件事？',\n      (w ? '「' + w.text + '」会作废（已攒的 ' + wishMinText(wishGain(w)) + ' 从小账上清掉，流水会保留）。\\n\\n' : '')\n      + '之后可以让 TA 重新说一件，或你替他写一件。', '换一件');\n    if (!ok) return;\n    if (w) { w.status = 'dropped'; w.dropAt = Date.now(); await saveSettings(true); }\n    toast('已作废，可以让 TA 重新说一件'); render();\n  },\n  wishOpenScene: el => {\n    const h = wishAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!h) return;\n    openSheet(`<h3>🌠 ${esc(h.text)}</h3>\n      <div class=\"tiny\">${dkey(new Date(h.doneAt || h.at))} 实现 · 你们一起投入 ${esc(wishMinText(h.doneMin || wishGain(h)))}</div>\n      ${h.why ? `<div class=\"tiny mt6\" style=\"line-height:1.7;color:var(--dim)\">${esc(h.why)}</div>` : ''}\n      <div style=\"font-size:13.8px;line-height:1.9;margin-top:10px;white-space:pre-wrap\">${esc(h.finalScene || '（这一刻没有留下描写）')}</div>\n      ${h.finalLine ? `<div class=\"card mt10\" style=\"background:var(--card2)\"><div class=\"row\">${charAvatar(charById(h.charId))}\n        <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.8px\"><div class=\"who\">${esc(charName(h.charId))}</div>「${esc(h.finalLine)}」</div></div>\n        <button class=\"btn sm ghost mt10\" data-act=\"wishReplay\" data-id=\"${esc(h.id)}\">🔊 再听一遍</button></div>` : ''}\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn sm ghost grow\" data-act=\"wishFavScene\" data-id=\"${esc(h.id)}\">⭐ 收藏这一刻</button>\n        <button class=\"btn sm ghost grow\" data-act=\"closeSheet\">关闭</button></div>`);\n  },\n  wishReplay: async el => {\n    const h = wishAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!h || !h.finalLine) return;\n    const ok = await speak(h.charId || anyCharId(), h.finalLine);\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  wishFavScene: el => {\n    const h = wishAll().find(x => String(x.id) === String(el.dataset.id));\n    if (!h) return;\n    const txt = '【一起实现】' + h.text\n      + '\\n一起投入：' + wishMinText(h.doneMin || wishGain(h))\n      + (h.why ? '\\n为什么重要：' + h.why : '')\n      + '\\n\\n' + (h.finalSce",
  "ne || '')\n      + (h.finalLine ? '\\n\\n「' + h.finalLine + '」' : '');\n    openFavPicker({ kind: 'report', title: '一起实现 · ' + h.text, content: txt, charId: h.charId || '', from: 'TA 的心愿' });\n  },\n  wishClearLog: async el => {\n    const cid = el.dataset.id || anyCharId();\n    if (!cid) return;\n    const w = wishOf(cid);\n    if (!w) { toast('没有进行中的心愿'); return; }\n    const ok = await confirmBox('清空流水？', '流水是这个心愿进度的唯一依据，清空后进度会归零（心愿本身保留）。', '清空');\n    if (!ok) return;\n    w.entries = []; w.gained = 0; w.status = 'active';\n    await saveSettings(true); toast('已清空'); render();\n  },\n  coinBuy: async el => { await coinSpend(el.dataset.k); },\n  coinDeductToggle: async () => {\n    const c = coinDeductCfg();\n    c.on = !c.on;\n    S.settings.coinDeduct = c;\n    await saveSettings(true);\n    toast(c.on ? '已开启违规扣专注币（失约扣 ' + (Number(c.miss) || 0) + '）' : '已关掉违规扣专注币');\n    render();\n  },\n  coinWishAsk: () => {\n    openSheet(`<h3>🌠 跟 TA 提一个愿望</h3>\n      <div class=\"tiny\">会把愿望写进聊天室，由 TA 亲口答应并兑现（TA 可以用聊天室自带的红包 / 转账，也可以亲手为你做点什么）。</div>\n      <label class=\"fl\">你的愿望</label>\n      <input class=\"input\" id=\"wishBox\" placeholder=\"例如：这周末陪我看一部电影\">\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">算了</button>\n      <button class=\"btn primary grow\" data-act=\"coinWishSend\">说给 TA 听</button></div>`);\n  },\n  coinWishSend: async () => {\n    const box = document.getElementById('wishBox');\n    const w = box ? (box.value || '').trim() : '';\n    if (!w) { toast('先写一个愿望'); return; }\n    closeAllSheets();\n    await coinWishDone(anyCharId(), w.slice(0, 80));\n    render();\n  },\n  coinAdjust: () => {\n    openSheet(`<h3>手动修正余额</h3>\n      <label class=\"fl\">余额（点）</label><input class=\"input\" type=\"number\" inputmode=\"numeric\" id=\"coinFix\" value=\"${coinBal()}\">\n      <button class=\"btn primary block mt12\" data-act=\"coinAdjustDo\">保存</button>`);\n  },\n  coinAdjustDo: async () => {\n    const v = Number((document.getElementById('coinFix') || {}).value) || 0;\n    S.settings.coinBalance = Math.max(0, Math.round(v));\n    await saveSettings(true); closeAllSheets(); toast('已修正为 ' + S.settings.coinBalance + ' 点'); render();\n  },\n  coinClear: async () => {\n    const ok = await confirmBox('清空收支明细？', '余额保留，只清掉明细记录。', '清空');\n    if (!ok) return;\n    S.settings.coinLog = [];\n    await saveSettings(true); toast('已清空明细'); render();\n  },\n  goalSave: async () => {\n    const n = (document.getElementById('goalName').value || '').trim();\n    const d = (document.getElementById('goalDate').value || '').trim();\n    const note = (document.getElementById('goalNote').value || '').trim();\n    if (!n) { toast('给目标起个名字'); return; }\n    if (!/^\\d{4}-\\d{2}-\\d{2}$/.test(d)) { toast('选一个日期'); return; }\n    S.settings.goals = goals().concat([{ id: uid(), name: n.slice(0, 30), date: d, note: note.slice(0, 60), createdAt: Date.now(), done: false }]);\n    await saveSettings(true);\n    toast('目标已加上：' + n); render();\n  },\n  goalDel: async el => {\n    S.settings.goals = goals().filter(g => String(g.id) !== String(el.dataset.id));\n    await saveSettings(true); render();\n  },\n  goalDone: async el => {\n    const g = goals().find(x => String(x.id) === String(el.dataset.id));\n    if (!g) return;\n    g.done = !g.done;\n    await saveSettings(true);\n    if (g.done) {\n      const cid = anyCharId();\n      if (cid) { await addBond(cid, 1, '完成了一个长期目标「' + g.name + '」'); await syncTimeline(cid, `用户完成了他设的长期目标「${g.name}」。`, 'goal_done', {}); }\n      toast('完成啦：' + g.name + '（已记一笔）');\n    }\n    render();\n  },\n  goalTell: async el => {\n    const g = goals().find(x => String(x.id) === String(el.dataset.id));\n    const cid = anyCharId();\n    if (!g || !cid) { toast('还没有角色'); return; }\n    await syncTimeline(cid, `用户把他的长期目标告诉你：「${g.name}」，日期 ${g.date}（${goalPhase(goalDays(g))}）${g.note ? '，备注：' + g.note : ''}。以后督促他时请结合这个目标的剩余时间。`, 'goal_tell', {});\n    await sdk(() => API.chat.writeHistory({\n      characterId: cid, role: 'user',\n      content: '我跟你说一下我的目标：' + g.name + '，' + g.date + '（' + goalPhase(goalDays(g)) + '）' + (g.note ? '，' + g.note : '') + '。以后记得盯着我。'\n    }), null);\n    toast('已告诉 TA，去聊天室说一句吧');\n  }\n});\n/* ==========================================================\n   视图 · 学习报告（周报 / 月报）\n   ========================================================== */\n/* ---------- 背书的周期汇总：学习报告要把这一摞数据一起说进去 ---------- */\nfunction rcPeriodStats(from, to) {\n  const list = (S.rlogs || []).filter(x => {\n    const t = Number(x.at) || 0;\n    return t >= Number(from || 0) && t < Number(to || (Date.now() + 86400000));\n  });\n  const total = sum(list.map(x => Number(x.total) || 0));\n  const right = sum(list.map(x => Number(x.right) || 0));\n  const dictN = sum(list.map(x => Number(x.dictationN) || 0));\n  const dictR = sum(list.map(x => Number(x.dictationRight) || 0));\n  const newN = sum(list.map(x => Number(x.newN) || 0));\n  const weakN = sum(list.map(x => Number(x.weakN) || 0));\n  const coin = sum(list.map(x => Number(x.coin) || 0));\n  const uniq = {};\n  list.forEach(x => { if (x.date && Number(x.total) > 0) uniq[x.date] = 1; });\n  return {\n    total: total, right: right, dictN: dictN, dictR: dictR,\n    newN: newN, weakN: weakN, coin: coin,\n    dayN: Object.keys(uniq).length,\n    cards: rcCards().length, weakNow: rcWeakCards().length,\n    dictRate: dictN ? Math.round(dictR / dictN * 100) : 0\n  };\n}\nfunction rcPeriodText(from, to) {\n  const s = rcPeriodStats(from, to);\n  if (!s.total && !s.newN) return '本周期没有背书记录。';\n  return '共背 ' + s.total + ' 条（答对 ' + s.right + ' 条）'\n    + (s.dictN ? '，其中默写 ' + s.dictN + ' 条、正确 ' + s.dictR + ' 条（' + s.dictRate + '%）' : '')\n    + (s.newN ? '，新掌握 ' + s.newN + ' 条' : '')\n    + (s.weakN ? '，攻克薄弱 ' + s.weakN + ' 张' : '')\n    + (s.coin ? '，获得专注币 ' + s.coin + ' 点' : '')\n    + '；有背书的天数 ' + s.dayN + ' 天。词本共 ' + s.cards + ' 张卡片，当前仍有 ' + s.weakNow + ' 张薄弱。';\n}\nfunction localPeriodReport(st, prev) {\n  const hl = [], pb = [], ad = [];\n  const rcS = rcPeriodStats(st.range.from, st.range.to);\n  if (st.focusMin > 0) hl.push(`专注合计 ${st.focusMin} 分钟，共 ${st.sessions} 次`);\n  if (rcS.total) hl.push(`背书 ${rcS.total} 条${rcS.dictN ? '，默写正确率 ' + rcS.dictRate + '%' : ''}${rcS.newN ? '，新掌握 ' + rcS.newN + ' 条' : ''}`);\n  if (rcS.weakN) hl.push(`攻克薄弱卡片 ${rcS.weakN} 张`);\n  if (st.passRate >= 80 && st.graded) hl.push(`考核通过率 ${st.passRate}%，发挥稳定`);\n  if (st.sleepDays >= 3) hl.push(`${st.sleepDays} 天有睡眠记录`);\n  if (prev && st.focusMin > prev.focusMin) hl.push(`比上一个周期多了 ${st.focusMin - prev.focusMin} 分钟`);\n  if (st.focusMin < (prev ? prev.focusMin : 0)) pb.push(`专注时长比上个周期少了 ${(prev ? prev.focusMin : 0) - st.focusMin} 分钟`);\n  if (st.vio) pb.push(`有 ${st.vio} 次中途离开或超时`);\n  if (st.graded && st.passRate < 80) pb.push(`考核通过率只有 ${st.passRate}%，正确率没达标`);\n  if (st.mistakes) pb.push(`新错题 ${st.mistakes} 道，集中在：${st.topWeak}`);\n  if (st.drowsy) pb.push(`有 ${st.drowsy} 次酝酿超过半小时才入睡（上床后还在玩手机）`);\n  ad.push('把最容易出效率的时段' + (st.bestHour === '—' ? '固定下来' : '（' + st.bestHour + '）固定成每天的第一段专注'));\n  if (st.mistakes) ad.push('错题挑 3 道重做一遍，比多刷十道新的更有用');\n  if (st.sleepAvg && st.sleepAvg < 6) ad.push('睡眠偏短，先把入睡时间往前挪 30 分钟');\n  return {\n    summary: `本周期专注 ${st.focusMin} 分钟（${st.sessions} 次${st.avgMin ? '，平均每次 ' + st.avgMin + ' 分钟' : ''}）`\n      + (st.graded ? `，考核通过率 ${st.passRate}%` : '')\n      + (st.vio ? `，违规 ${st.vio} 次` : '，没有违规')\n      + (st.sleepDays ? `；睡眠有记录 ${st.sleepDays} 天，平均 ${st.sleepAvg.toFixed(1)} 小时` : '；本周期没有睡眠记录')\n      + `。最有效率的时段是 ${st.bestHour}。`,\n    highlights: hl.slice(0, 3), problems: pb.slice(0, 3), advice: ad.slice(0, 3),\n    murmur: pb.length ? '这周有松动的地方，下周我盯着你。' : '就这样，保持住，我陪着你。'\n  };\n}\nasync function genPeriodReport(kind) {\n  if (S.loading) { toast('正在生成，请稍候…'); return; }\n  const cid = anyCharId();\n  if (!cid) { toast('还没有角色'); return; }\n  const st = periodStats(kind);\n  if (!st.sessions && !st.sleepDays) { toast('这个周期还没有任何记录'); return; }\n  const prev = periodStats(kind === 'month' ? 'lastmonth' : 'lastweek');\n  S.loading = 'period'; render();\n  let data = null;\n  try {\n    const text = await pGen('report.period', {\n      range: st.range.name, focusMin: st.focusMin, prevFocusMin: prev.focusMin, sessions: st.sessions,\n      passRate: st.passRate, vio: st.vio, bestHour: st.bestHour, sleepAvg: st.sleepAvg.toFixed(1),\n      sleepDays: st.sleepDays, drowsy: st.drowsy, mistakes: st.mistakes, topWeak: st.topWeak,\n      goals: goalBrief(), bond: wishBrief(cid), coin: coinBal(),\n      recite: rcPeriodText(st.range.from, st.range.to)\n    }, [cid]);\n    data = parseJSON(text);\n  } catch (e) { data = null; }\n  if (!data || !data.summary) { data = localPeriodReport(st, prev); toast('用了本地兜底报告（AI 没给出可用结果）'); }\n  const rec = {\n    id: uid(), kind: kind, name: st.range.name, from: st.range.from, to: st.range.to, at: Date.now(), charId: cid,\n    summary: String(data.summary || ''), highlights: (data.highlights || []).map(String).slice(0, 4),\n    problems: (data.problems || []).map(String).slice(0, 4), advice: (data.advice || []).map(String).slice(0, 4),\n    murmur: String(data.murmur || ''),\n    nums: {\n      focusMin: st.focusMin, sessions: st.sessions, passRate: st.passRate, vio: st.vio, bestHour: st.bestHour,\n      sleepAvg: Number(st.sleepAvg.toFixed(1)), sleepDays: st.sleepDays, mistakes: st.mistakes,\n      avgMin: st.avgMin, longest: st.longest,\n      recite: rcPeriodText(st.range.from, st.range.to),\n      rcTotal: rcPeriodStats(st.range.from, st.range.to).total,\n      rcDictRate: rcPeriodStats(st.range.from, st.range.to).dictRate\n    },\n    bars: st.dayBars\n  };\n  S.settings.periodReports = [rec].concat(cfg('periodReports') || []).slice(0, Math.max(5, Number(cfg('reportKeep') || 20)));\n  await saveSettings(true);\n  await syncTimeline(cid, `${st.range.name}学习报告：${rec.summary}｜问题：${rec.problems.join('；') || '无'}｜建议：${rec.advice.join('；')}`, 'period_report', { range: kind });\n  S.loading = ''; S.draft.periodOpen = rec.id;\n  render();\n  toast('报告已生成');\n  if (shouldSpeak('story') && rec.murmur) speak(cid, rec.murmur);\n}\nVIEWS.periodrep = function () {\n  const list = (cfg('periodReports') || []).slice().sort((a, b) => b.at - a.at);\n  const open = S.draft.periodOpen ? list.filter(x => String(x.id) === String(S.draft.periodOpen))[0] : list[0];\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(124,140,255,.16),rgba(255,255,255,.03));border-color:rgba(124,140,255,.3)\">\n    <h3>📈 学习报告</h3>\n    <div class=\"tiny mt6\">由角色读你的真实数据写出来：专注时长、考核通过率、违规、最有效率的时段、睡眠、错题集中在哪、以及距离你的长期目标还有几天。报告会存下来，随时回看。</div>\n    <div class=\"row mt12\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"genPeriod\" data-k=\"week\" ${S.loading === 'period' ? 'disabled' : ''}>${S.loading === 'period' ? '生成中…' : '生成本周报告'}</button>\n      <button class=\"btn grow\" data-act=\"genPeriod\" data-k=\"month\" ${S.loading === 'period' ? 'disabled' : ''}>生成本月报告</button></div>\n    ${S.loading === 'period' ? `<div class=\"tiny center mt10\"><span class=\"spin\"></span> 角色正在翻你这个周期的记录…</div>` : ''}\n  </div>\n  ${open ? `<div class=\"card\">\n    <div class=\"row between\"><div class=\"grow\"><h3>${esc(open.name)}报告 · ${dkey(new Date(open.at))}</h3>\n      <div class=\"tiny\">${dkey(new Date(open.from))} — ${dkey(new Date(Math.min(open.to, Date.now())))} · 由 ${esc(charName(open.charId))} 写</div></div>\n      <button class=\"btn sm ghost\" data-act=\"periodDel\" data-id=\"${esc(open.id)}\">删</button></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${open.nums.focusMin}<span class=\"tiny\">分</span></div><div class=\"tiny\">专注合计</div></div>\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${open.nums.sessions}</div><div class=\"tiny\">次数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${open.nums.passRate}%</div><div class=\"tiny\">考核通过率</div></div>\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600;color:${open.nums.vio ? '#ff9aa6' : 'inherit'}\">${open.nums.vio}</div><div class=\"tiny\">违规</div></div>\n    </div>\n    <div class=\"row mt6\">\n      <div class=\"grow center\"><div style=\"font-size:15px\">${esc(open.nums.bestHour)}</div><div class=\"tiny\">最有效率</div></div>\n      <div class=\"grow center\"><div style=\"font-size:15px\">${open.nums.sleepAvg}<span class=\"tiny\">h</span></div><div class=\"tiny\">平均睡眠</div></div>\n      <div class=\"grow center\"><div style=\"font-size:15px\">${open.nums.mistakes}</div><div class=\"tiny\">新错题</div></div>\n      <div class=\"grow center\"><div style=\"font-size:15px\">${open.nums.longest}<span class=\"tiny\">分</span></div><div class=\"tiny\">最长一次</div></div>\n    </div>\n    ${(open.bars || []).length > 1 ? `<div class=\"bars mt12\">${open.bars.map(b => {\n      const mx = Math.max.apply(null, [1].concat(open.bars.map(x => x.min)));\n      return `<div class=\"col\"><div class=\"vl\">${b.min || ''}</div><div class=\"bg\" style=\"height:${Math.max(3, b.min / mx * 78)}%\"></div><div class=\"lb\">${esc(b.label)}</div></div>`;\n    }).join('')}</div>` : ''}\n    <div class=\"hr\"></div>\n    <div style=\"font-size:13.5px;line-height:1.8\">${esc(open.summary)}</div>\n    ${open.nums.recite ? `<div class=\"card tight mt10\" style=\"background:var(--card2)\">\n      <div class=\"row between\"><span class=\"tiny\">📖 背书</span>\n        ${open.nums.rcTotal ? `<span class=\"tiny\">共 ${open.nums.rcTotal} 条${open.nums.rcDictRate ? ' · 默写正确率 ' + open.nums.rcDictRate + '%' : ''}</span>` : ''}</div>\n      <div style=\"font-size:12.9px;line-height:1.7;margin-top:4px\">${esc(open.nums.recite)}</div></div>` : ''}\n    ${(open.highlights || []).length ? `<div class=\"mt10\"><div class=\"tiny\" style=\"color:var(--teal)\">做得好的</div>\n      ${open.highlights.map(x => `<div class=\"tiny\" style=\"font-size:12.8px;line-height:1.7\">· ${esc(x)}</div>`).join('')}</div>` : ''}\n    ${(open.problems || []).length ? `<div class=\"mt10\"><div class=\"tiny\" style=\"color:var(--gold)\">要注意的</div>\n      ${open.problems.map(x => `<div class=\"tiny\" style=\"font-size:12.8px;line-height:1.7\">· ${esc(x)}</div>`).join('')}</div>` : ''}\n    ${(open.advice || []).length ? `<div class=\"mt10\"><div class=\"tiny\" style=\"color:#b9c2ff\">下一步</div>\n      ${open.advice.map(x => `<div class=\"tiny\" style=\"font-size:12.8px;line-height:1.7\">· ${esc(x)}</div>`).join('')}</div>` : ''}\n    ${open.murmur ? `<div class=\"card mt10\" style=\"background:var(--card2)\"><div class=\"row\">${charAvatar(charById(open.charId))}\n      <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\"><div class=\"who\">${esc(charName(open.charId))} · 碎碎念</div>${esc(open.murmur)}</div></div>\n      <button class=\"btn sm ghost mt10\" data-act=\"periodVoice\" data-id=\"${esc(open.id)}\">🔊 再听一遍</button></div>` : ''}\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"periodFav\" data-id=\"${esc(open.id)}\">⭐ 收藏这份报告</button>\n      <button class=\"btn sm ghost grow\" data-act=\"periodToChat\" data-id=\"${esc(open.id)}\">📨 让 TA 在聊天里说一句</button></div>\n  </div>` : `<div class=\"empty\">还没有报告。点上面「生成本周报告」，让角色翻一遍你的记录。</div>`}\n  ${list.length > 1 ? `<div class=\"card\"><h3>历史报告（${list.length}）</h3>\n    ${list.map(x => `<div class=\"item\" data-act=\"periodOpen\" data-id=\"${esc(x.id)}\" style=\"cursor:pointer\">\n      <div class=\"ic\">📈</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(x.name)}报告 · ${esc(x.nums.focusMin)} 分钟 · 通过率 ${esc(x.nums.passRate)}%</div>\n        <div class=\"tiny\">${dkey(new Date(x.at))} · ${esc(String(x.summary || '').slice(0, 40))}…</div></div>\n      <div class=\"ic\">›</div></div>`).join('')}</div>` : ''}`;\n};\n/* ==========================================================\n   视图 · 专注趋势\n   ========================================================== */\nVIEWS.trend = function () {\n  const t = trendStats();\n  const note = S.draft.trendNote || '';\n  const bars = (arr, labels, cls) => {\n    const mx = Math.max.apply(null, [1].concat(arr));\n    return `<div class=\"bars\">${arr.map((v, i) => `<div class=\"col\">\n      <div class=\"vl\">${Math.round(v) || ''}</div>\n      <div class=\"bg ${cls || ''}\" style=\"height:${Math.max(3, v / mx * 78)}%\"></div>\n      <div class=\"lb\">${esc(labels[i])}</div></div>`).join('')}</div>`;\n  };\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03));border-color:rgba(94,234,212,.3)\">\n    <h3>📊 专注趋势</h3>\n    <div class=\"tiny mt6\">按你每次专注的<b>开始时间</b>统计，看出你一天里什么时候真的学得进去。数据来自你已有的专注记录，不需要额外设置。</div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${t.total}<span class=\"tiny\">分</span></div><div class=\"tiny\">累计专注</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${t.sessions}</div><div class=\"tiny\">总次数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${t.avgMin}<span class=\"tiny\">分</span></div><div class=\"tiny\">平均单次</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${t.longest}<span class=\"tiny\">分</span></div><div class=\"tiny\">最长一次</div></div>\n    </div>\n  </div>\n  ${t.sessions ? `\n  <div class=\"card\"><h3>一天里的分布</h3>\n    <div class=\"tiny\">${esc(SLOT_LABEL[t.bestSlot])} 是你最有产出的时段${t.slotMin[t.worstSlot] < 1 ? '，' + SLOT_LABEL[t.worstSlot] + ' 基本没有产出' : ''}。</div>\n    ${bars(t.slotMin, ['0-3', '3-6', '6-9', '9-12', '12-15', '15-18', '18-21', '21-24'])}</div>\n  <div class=\"card\"><h3>一周里的分布</h3>\n    <div class=\"tiny\">按星期看哪里最容易断。</div>\n    ${bars(t.wdMin, ['一', '二', '三', '四', '五', '六', '日'])}</div>\n  <div class=\"card\"><h3>最近 8 周</h3>\n    ${bars(t.weeks.map(w => w.min), t.weeks.map(w => w.label), 'sleep')}\n    <div class=\"tiny mt6\">违规率 ${t.vioRate}%（${t.vio} 次违规 / ${t.sessions} 次专注）</div></div>\n  <div class=\"card\"><h3>让 TA 点评一下</h3>\n    <div class=\"tiny\">把这份分布交给角色，让 TA 说你哪个时段最容易进入状态、该怎么调整。</div>\n    <button class=\"btn primary block mt10\" data-act=\"trendExplain\" ${S.loading === 'trend' ? 'disabled' : ''}>${S.loading === 'trend' ? '正在看你的数据…' : '让 TA 点评'}</button>\n    ${note ? `<div class=\"card mt10\" style=\"background:var(--card2)\"><div class=\"row\">${charAvatar(charById(S.draft.trendChar || anyCharId()))}\n      <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">${esc(note).replace(/\\n/g, '<br>')}</div></div>\n      <div class=\"row mt10\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"trendVoice\">🔊 听一遍</button>\n      <button class=\"btn sm ghost grow\" data-act=\"trendFav\">⭐ 收藏</button>\n      <button class=\"btn sm ghost grow\" data-act=\"trendToChat\">📨 发到聊天室</button></div></div>` : ''}</div>`\n      : `<div class=\"empty\">还没有专注记录。<br>完成几段专注之后，这里就会长出你的时间分布。</div>`}`;\n};\nObject.assign(ACTIONS, {\n  genPeriod: async el => { await genPeriodReport(el.dataset.k); },\n  periodOpen: el => { S.draft.periodOpen = el.dataset.id; render(); window.scrollTo(0, 0); },\n  periodDel: async el => {\n    const ok = await confirmBox('删除这份报告？', '删除后不可恢复（可以重新生成）。', '删除');\n    if (!ok) return;\n    S.settings.periodReports = (cfg('periodReports') || []).filter(x => String(x.id) !== String(el.dataset.id));\n    if (String(S.draft.periodOpen) === String(el.dataset.id)) S.draft.periodOpen = '';\n    await saveSettings(true); render();\n  },\n  periodVoice: async el => {\n    const r = (cfg('periodReports') || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!r) return;\n    const ok = await speak(r.charId || anyCharId(), r.murmur || r.summary);\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  periodToChat: async el => {\n    const r = (cfg('periodReports') || []).find(x => String(x.id) === String(el.dataset.id));\n    const cid = (r && r.charId) || anyCharId();\n    if (!r || !cid) { toast('没有可发送的报告'); return; }\n    const txt = `${r.name}学习报告（${dkey(new Date(r.from))} — ${dkey(new Date(Math.min(r.to, Date.now())))}）：`\n      + `专注 ${r.nums.focusMin} 分钟 / ${r.nums.sessions} 次，考核通过率 ${r.nums.passRate}%，违规 ${r.nums.vio} 次，最有效率 ${r.nums.bestHour}。`\n      + `\\n${r.summary}` + ((r.problems || []).length ? `\\n要注意：${r.problems.join('；')}` : '')\n      + ((r.advice || []).length ? `\\n下一步：${r.advice.join('；')}` : '');\n    await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: '[学习报告] ' + txt }), null);\n    await sdk(() => API.chat.sendCard({\n      characterId: cid, role: 'system', historyRole: 'system', summary: '学习报告', historyText: txt,\n      card: {\n        appLabel: '角色陪伴专注', title: '这份' + r.name + '的学习报告', subtitle: 'REPORT', status: '看看他做了什么',\n        accentColor: '#7c8cff', height: 260,\n        sections: [\n          { title: '数据', rows: [\n            { label: '专注', value: r.nums.focusMin + ' 分钟 / ' + r.nums.sessions + ' 次' },\n            { label: '考核通过率', value: r.nums.passRate + '%' },\n            { label: '最有效率的时段', value: r.nums.bestHour }\n          ] },\n          { title: '结论', rows: [{ label: '整体', value: r.summary }] }\n        ],\n        html: '<div style=\"padding:14px;font:13.5px/1.75 -apple-system,BlinkMacSystemFont,sans-serif\">'\n          + '<div style=\"font-size:11.5px;letter-spacing:.5px;color:#8b97ad\">专注 APP · 学习报告</div>'\n          + '<div style=\"margin-top:8px\">' + esc(r.summary) + '</div></div>'\n      }\n    }), null);\n    try { await API.chat.requestReply({ characterId: cid }); } catch (e) { }\n    toast('已发到聊天室，等 TA 说一句');\n  },\n  periodFav: el => {\n    const r = (cfg('periodReports') || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!r) return;\n    const txt = `${r.name}学习报告 ${dkey(new Date(r.at))}\\n专注 ${r.nums.focusMin} 分钟 / ${r.nums.sessions} 次 · 通过率 ${r.nums.passRate}% · 违规 ${r.nums.vio} 次 · 最有效率 ${r.nums.bestHour} · 平均睡眠 ${r.nums.sleepAvg} 小时\\n【整体】${r.summary}\\n【做得好的】${(r.highlights || []).join('；')}\\n【要注意的】${(r.problems || []).join('；')}\\n【下一步】${(r.advice || []).join('；')}\\n【碎碎念】${r.murmur}`;\n    openFavPicker({ kind: 'report', title: r.name + '学习报告 · ' + dkey(new Date(r.at)), content: txt, charId: r.charId || '', from: '学习报告' });\n  },\n  trendExplain: async () => {\n    const t = trendStats();\n    const cid = anyCharId();\n    if (!t.sessions) { toast('还没有专注记录'); return; }\n    if (!cid) { toast('还没有角色'); return; }\n    S.loading = 'trend'; render();\n    let text = '';\n    try { text = await pGen('report.trend', { data: trendDataText() }, [cid]); } catch (e) { text = ''; }\n    if (!text) {\n      text = `你最出效率的是 ${SLOT_LABEL[t.bestSlot]}${t.slotMin[t.worstSlot] < 1 ? '，而 ' + SLOT_LABEL[t.worstSlot] + ' 基本没产出，就把重要的事挪到你状态最好的那一段' : ''}。累计 ${t.total} 分钟、平均每次 ${t.avgMin} 分钟${t.vioRate ? '，违规率 ' + t.vioRate + '%，先把中途离开压下去' : ''}。`;\n    }\n    S.draft.trendNote = text.replace(/^[\"'「」\\s]+|[\"'「」\\s]+$/g, '');\n    S.draft.trendChar = cid;\n    S.loading = '';\n    await addPublic('trend', `${charName(cid)}对趋势的点评：${S.draft.trendNote}`, cid, {});\n    render();\n  },\n  trendVoice: async () => {\n    if (!S.draft.trendNote) return;\n    const ok = await speak(S.draft.trendChar || anyCharId(), S.draft.trendNote);\n    if (!ok) toast('播放失败，请检查语音配置');\n  },\n  trendFav: () => {\n    if (!S.draft.trendNote) { toast('先让 TA 点评一次'); return; }\n    openFavPicker({ kind: 'text', title: '专注趋势点评 · ' + dkey(), content: S.draft.trendNote + '\\n\\n' + trendDataText(), charId: S.draft.trendChar || '', from: '专注趋势' });\n  },\n  trendToChat: async () => {\n    if (!S.draft.trendNote) { toast('先让 TA 点评一次'); return; }\n    const cid = S.draft.trendChar || anyCharId();\n    if (!cid) { toast('还没有角色'); return; }\n    await sdk(() => API.chat.writeHistory({ characterId: cid, role: 'system', content: '[专注趋势] ' + S.draft.trendNote }), null);\n    await syncChatLine(cid, S.draft.trendNote, 'assistant');\n    toast('已写进聊天室');\n  },\n  morningSave: async () => {\n    const m = cfg('morning') || {};\n    const t = (document.getElementById('mTime') || {}).value || m.time || '07:00';\n    m.time = t; m.enabled = true;\n    S.settings.morning = m;\n    await saveSettings(true);\n    await scheduleMorning(m);\n    toast('晨间问候已开启：每天 ' + t); render();\n  },\n  morningVoice: async () => {\n    const m = cfg('morning') || {};\n    m.voice = !m.voice;\n    S.settings.morning = m;\n    await saveSettings(true);\n    render();\n  },\n  /* 惩罚锁定页里当场用专注币换一张免罚卡，并直接免掉这次惩罚 ——\n     一步到位：扣币 → 发卡 → 立刻用掉，不用你先退出锁定页去别处换。 */\n  lockBuyFreePass: async () => {\n    const p = S.lock && S.lock.punish;\n    if (!p) { toast('当前没有进行中的惩罚'); return; }\n    if (S.passBusy) { toast('正在处理，别连点'); return; }\n    const cost = freePassCost();\n    const bal = coinBal();\n    if (bal < cost) { toast('专注币不够：还差 ' + (cost - bal) + ' 点'); return; }\n    S.passBusy = true;\n    await coinAdd(-cost, '兑换：免罚卡（惩罚页直接使用）');\n    /* 换到卡就立刻用掉：直接在这个入口把卡「加了又减」，不写进 freePass，\n       免得多绕一次「先 +1 再用 -1」—— 那两步之间被别的入口插一脚就会串数。 */\n    await saveSettings(true);\n    S.passBusy = false;\n    p.byPass = true;\n    const cid = p.charId || anyCharId();\n    if (cid) await syncTimeline(cid, '用户用专注币换了一张免罚卡，免掉了这次惩罚：' + p.title + '（花 ' + cost + ' 币）。', 'free_pass', {});\n    toast('已用 ' + cost + ' 专注币换卡，免掉这次惩罚');\n    await completePunish(p, '用专注币兑换的免罚卡免掉（花 ' + cost + ' 币）');\n  },\n  useFreePass: async () => {\n    const p = S.lock && S.lock.punish;\n    if (!p) { toast('当前没有进行中的惩罚'); return; }\n    if (S.passBusy) { toast('正在处理，别连点'); return; }\n    /* 卡数每次都从当前设置里【现读】，不用进函数时捕获的旧值 ——\n       确认弹窗停留期间卡数可能已经变了（弹窗、快捷入口都能扣），\n       用旧值减 1 写回去，就会出现「用了一张还剩一张」。 */\n    if (Number((S.settings && S.settings.freePass) || 0) <= 0) { toast('免罚卡已经用完了'); render(); return; }\n    const n = Number(S.settings.freePass) || 0;\n    const ok = await confirmBox('用一张免罚卡？', '这次惩罚会直接免掉（用掉后剩 ' + (n - 1) + ' 张）。这是你自己攒来的，TA 顶多念你一句。', '用掉它');\n    if (!ok) return;\n    const nowN = Number((S.settings && S.settings.freePass) || 0);\n    if (nowN <= 0) { toast('免罚卡已经用完了'); render(); return; }\n    S.passBusy = true;\n    S.settings.freePass = nowN - 1;\n    await saveSettings(true);              // 先落库再执行：避免「界面已免、卡没扣」\n    p.byPass = true;\n    const cid = p.charId || anyCharId();\n    if (cid) await syncTimeline(cid, '用户用一张免罚卡免掉了这次惩罚：' + p.title + '（免罚卡剩 ' + S.settings.freePass + ' 张）。', 'free_pass', {});\n    S.passBusy = false;\n    toast('已用掉一张免罚卡，剩 ' + S.settings.freePass + ' 张');\n    await completePunish(p, '用免罚卡免掉（剩 ' + S.settings.freePass + ' 张）');\n    render();\n  },\n  morningToggle: async () => {\n    const m = cfg('morning') || {};\n    m.enabled = !m.enabled;\n    S.settings.morning = m;\n    await saveSettings(true);\n    if (m.enabled) await scheduleMorning(m);\n    render();\n  },\n  morningChar: async el => { cfg('morning').charId = el.dataset.id; await saveSettings(true); render(); },\n  morningTry: async () => {\n    const m = cfg('morning') || {};\n    S.settings.morning = Object.assign({ time: '07:00' }, m);\n    await fireMorning(true);\n  },\n  morningStart: async () => {\n    const box = document.getElementById('morningTask');\n    const task = box ? (box.value || '').trim() : '';\n    const s2 = cfg('morning') || {};\n    closeAllSheets();\n    if (!task) { toast('先写下今天第一件事'); return; }\n    const cid = s2.charId || anyCharId();\n    const ids = [cid].filter(Boolean);\n    if (!ids.length) { toast('还没有角色'); return; }\n    await addPublic('morning', `今天第一件事：${task}`, cid, {});\n    if (cid) await syncTimeline(cid, `早上用户告诉你今天第一件事是：${task}`, 'morning_task', {});\n    await startSession({\n      charIds: ids, focusMin: Math.max(5, Number(cfg('focusMin') || 25)),\n      breakMin: Math.max(1, Number(cfg('breakMin') || 5)), cycles: 1,\n      plan: [{ content: task, est: Math.max(5, Number(cfg('focusMin') || 25)) }],\n      reviewEvery: 'focus', voiceOn: cfg('voiceMode') !== 'off'\n    });\n  }\n});\n/* ==========================================================\n   背书模块 · 记忆卡片（词本 / 背诵 / 默写 / 薄弱专项 / 统计）\n   ----------------------------------------------------------\n   设计要点：\n   ① 全部数据本地持久化（IndexedDB），跟着主备份一起导出／还原；\n   ② 复习调度在「进入背诵页」那一刻一次算好，不后台定时，省电；\n   ③ 防刷量：快速翻卡、翻开就点「熟练」都会被降权，不算真的记住；\n   ④ 和角色联动只在关键节点出气泡，答错只安抚、绝不打击；\n   ⑤ AI 全是辅助增强，可在「背书设置」一键全关，关掉后完整走本地逻辑。\n   ========================================================== */\n/* ---------- 记忆等级：0 不会 · 1 模糊 · 2 熟练 · 3 精通 ----------\n   权重（w）越高，在「权重随机」里被抽到的概率越大；\n   精通给一个很小的兜底权重（不是 0），避免整本只剩精通卡片时抽不出题。 */\nconst RC_LV = [\n  { k: 0, n: '不会', w: 8.0, color: '#ff9aa6' },\n  { k: 1, n: '模糊', w: 4.0, color: '#ffb37a' },\n  { k: 2, n: '熟练', w: 1.5, color: '#5eead4' },\n  { k: 3, n: '精通', w: 0.4, color: '#7c8cff' }\n];\nfunction rcLv(k) { return RC_LV[Math.max(0, Math.min(3, Number(k) || 0))]; }\nfunction rcLvName(k) { return rcLv(k).n; }\nfunction rcLvColor(k) { return rcLv(k).color; }\n/* ---------- 优先级：0 必背 · 1 重要 · 2 一般 ----------\n   和老数据兼容：没设过的卡片一律按「一般」算，行为跟以前完全一样。\n   「分轮抽卡」就是靠这个：焦点档 = 还没掌握的最高优先级那一档，\n   焦点档主抽，已过关的档回来复习，还没到的档只偶尔穿插。 */\nconst RC_PRI = [\n  { k: 0, n: '必背', color: '#ff7b8a', emoji: '🔴' },\n  { k: 1, n: '重要', color: '#ffc978', emoji: '🟡' },\n  { k: 2, n: '一般', color: '#8b97ad', emoji: '⚪' }\n];\nfunction rcPriOf(c) { return (c && c.pri != null) ? clamp(Number(c.pri) || 0, 0, 2) : 2; }\nfunction rcPri(k) { return RC_PRI[clamp(Number(k) || 0, 0, 2)]; }\nfunction rcPriName(k) { return rcPri(k).n; }\nfunction rcPriColor(k) { return rcPri(k).color; }\n/* 焦点档：还没掌握的最高优先级那一档；全掌握了返回 -1（那就全算复习） */\nfunction rcFocusTier(cards) {\n  const list = cards || [];\n  for (let t = 0; t <= 2; t++) {\n    if (list.some(c => rcPriOf(c) === t && Number(c.level || 0) < 2)) return t;\n  }\n  return -1;\n}\nfunction rcFocusText(cards) {\n  const t = rcFocusTier(cards);\n  return t < 0 ? '全部已掌握（转复习）' : rcPriName(t);\n}\n/* 热力标记：红=错误≥3 次（强制置顶）/ 橙=中度薄弱 / 黄=轻度薄弱 / 空=稳定 */\nfunction rcHeat(c) {\n  const wrong = Number((c && c.wrongN) || 0);\n  const lv = Number((c && c.level) || 0);\n  if (wrong >= 3) return { k: 'hot', n: '高频易错', color: '#ff7b8a', emoji: '🔴' };\n  if (wrong >= 2 || lv === 0) return { k: 'mid', n: '中度薄弱', color: '#ffb37a', emoji: '🟠' };\n  if (wrong >= 1 || lv === 1) return { k: 'low', n: '轻度薄弱', color: '#ffd77a', emoji: '🟡' };\n  return null;\n}\n/* ---------- 词本 ---------- */\nfunction rcBooks() { return (S.books || []).slice(); }\nfunction rcBookById(id) { return rcBooks().filter(b => String(b.id) === String(id))[0] || null; }\nfunction rcActiveBooks() { return rcBooks().filter(b => !b.archived).sort((a, b) => (b.at || 0) - (a.at || 0)); }\nfunction rcArchivedBooks() { return rcBooks().filter(b => b.archived).sort((a, b) => (b.at || 0) - (a.at || 0)); }\nfunction rcBookName(id) { const b = rcBookById(id); return b ? b.name : '（词本已删）'; }\n/* ---------- 卡片 ---------- */\nfunction rcCards() { return (S.cards || []).slice(); }\nfunction rcCardsOf(bookId) {\n  return rcCards().filter(c => String(c.bookId) === String(bookId))\n    .sort((a, b) => (a.order || 0) - (b.order || 0) || (a.at || 0) - (b.at || 0));\n}\nfunction rcCardById(id) { return rcCards().filter(c => String(c.id) === String(id))[0] || null; }\nfunction rcPetCardById(id) { return id ? rcCardById(id) : null; }\nfunction rcCardN(bookId) { return rcCardsOf(bookId).length; }\nfunction rcMasteredN(bookId) { return rcCardsOf(bookId).filter(c => Number(c.level) >= 2).length; }\nfunction rcWeakCards(bookId) {\n  /* 薄弱集：不会 / 模糊 / 出过错 的卡片。\n     红色（错误≥3）强制排最前，其余按「错误次数 + 等级」排。 */\n  const pool = bookId ? rcCardsOf(bookId) : rcCards();\n  return pool.filter(c => Number(c.wrongN || 0) > 0 || Number(c.level || 0) < 2)\n    .sort((a, b) => {\n      const ha = Number(a.wrongN || 0) >= 3 ? 1 : 0, hb = Number(b.wrongN || 0) >= 3 ? 1 : 0;\n      if (ha !== hb) return hb - ha;\n      const sa = Number(a.wrongN || 0) * 2 + (3 - Number(a.level || 0));\n      const sb = Number(b.wrongN || 0) * 2 + (3 - Number(b.level || 0));\n      return sb - sa;\n    });\n}\n/* 新增/更新词本。返回的对象里 id 为空 = 没存进去 ——\n   上层必须据此如实报错，不能不管成败都弹「已创建」，\n   那会变成「说建好了，列表里却没有」。 */\nasync function rcSaveBook(b) {\n  if (!b) return null;\n  if (b.id) { await DB.update(T.BOOK, b.id, JSON.parse(JSON.stringify(b))); return b; }\n  const r = await DB.create(T.BOOK, JSON.parse(JSON.stringify(b)));\n  if (r && r.id != null && r.id !== '') {\n    b.id = r.id;\n    S.books = [b].concat(S.books || []);\n  }\n  return b;\n}\n/* 删词本 = 连同它下面的全部卡片一起删（会二次确认） */\nasync function rcDelBook(b) {\n  if (!b) return 0;\n  const cards = rcCardsOf(b.id);\n  for (const c of cards) if (c.id) await DB.remove(T.CARD, c.id);\n  S.cards = (S.cards || []).filter(c => String(c.bookId) !== String(b.id));\n  if (b.id) await DB.remove(T.BOOK, b.id);\n  S.books = (S.books || []).filter(x => String(x.id) !== String(b.id));\n  return cards.length;\n}\n/* 新增/更新卡片 */\nasync function rcSaveCard(c) {\n  if (!c) return null;\n  if (c.id) { await DB.update(T.CARD, c.id, JSON.parse(JSON.stringify(c))); return c; }\n  const r = await DB.create(T.CARD, JSON.parse(JSON.stringify(c)));\n  if (r) { c.id = r.id; S.cards = (S.cards || []).concat([c]); }\n  return c;\n}\nasync function rcDelCard(c) {\n  if (!c || !c.id) return;\n  await DB.remove(T.CARD, c.id);\n  S.cards = (S.cards || []).filter(x => String(x.id) !== String(c.id));\n}\nfunction rcNewCard(bookId, q, a, hint) {\n  const order = rcCardsOf(bookId).length;\n  return {\n    id: '', bookId: String(bookId), q: String(q || '').trim(), a: String(a || '').trim(),\n    hint: String(hint || '').trim(),\n    level: 0, wrongN: 0, rightN: 0, streak: 0, paused: false,\n    pri: 2,                                   // 默认「一般」，老卡片也按这个算\n    lastAt: 0, at: Date.now(), order: order,\n    /* AI 对这张卡生成过的内容统统存这里 ——\n       生成一次就留着，下次点开先看上次的；不满意再重新生成。\n       （以前每点一次就重新问一遍 API，既烧额度又看不到上次的） */\n    ai: {},\n    tags: []                                  // 自定义标签：词本里能按它筛选\n  };\n}\n/* ---------- 卡片标签 ----------\n   标签只是一串短词，用来在词本里把卡片分组筛出来（「第一章」「易错」「名词解释」）。\n   老卡片没有这个字段，一律按「没有标签」算，行为跟以前完全一样。 */\nfunction rcTagsOf(c) { return (c && Array.isArray(c.tags)) ? c.tags.filter(Boolean) : []; }\n/* 把输入框里的一串文字拆成标签数组：逗号/顿号/分号/空格都当分隔符，去重、去 #、限 8 个 */\nfunction rcTagList(s) {\n  const out = [], seen = {};\n  String(s || '').split(/[,，、;；|\\s]+/).forEach(x => {\n    const t = String(x).trim().replace(/^#+/, '').slice(0, 10);\n    if (!t) return;\n    const k = t.toLowerCase();\n    if (seen[k]) return;\n    seen[k] = 1;\n    out.push(t);\n  });\n  return out.slice(0, 8);\n}\n/* 筛选命中：filter 形如 pri:0 / lv:2 / heat:hot / tag:第一章 */\nfunction rcFilterHit(c, f) {\n  f = String(f || '');\n  if (f.indexOf('pri:') === 0) return rcPriOf(c) === Number(f.slice(4));\n  if (f.indexOf('lv:') === 0) return Number(c.level || 0) === Number(f.slice(3));\n  if (f.indexOf('heat:') === 0) { const h = rcHeat(c); return !!h && h.k === f.slice(5); }\n  if (f.indexOf('tag:') === 0) return rcTagsOf(c).indexOf(f.slice(4)) >= 0;\n  return true;\n}\n/* 当前筛选条件写成人话，显示在按钮上 */\nfunction rcFilterLabel(f) {\n  f = String(f || '');\n  if (!f) return '筛选';\n  if (f.indexOf('pri:') === 0) return rcPriName(Number(f.slice(4)));\n  if (f.indexOf('lv:') === 0) return rcLvName(Number(f.slice(3)));\n  if (f === 'heat:hot') return '🔴 高频易错';\n  if (f.indexOf('tag:') === 0) return '#' + f.slice(4);\n  return '筛选';\n}\n/* ==========================================================\n   卡片上的 AI 内容：生成一次就留在卡片里\n   ----------------------------------------------------------\n   c.ai = { keys:{text,at}, hint:{…}, explain:{…}, compare:{…},\n            compress:{…}, expand:{…}, mnemonic:{…}, translate:{…},\n            variant:{ list:[{q,a}], at } }\n   统一走下面这一组函数读 / 写 / 删，别在各处自己拼字段。\n   ========================================================== */\nconst RC_AI_KINDS = {\n  keys:      { n: '关键词',   tip: '默写判分按这些词算' },\n  hint:      { n: '启发提示', tip: '只给回忆角度，不会说出答案' },\n  explain:   { n: '通俗解释', tip: '把这条讲明白' },\n  compare:   { n: '易混辨析', tip: '和相近概念的区别' },\n  compress:  { n: '背诵版',   tip: '压缩到得分点' },\n  expand:    { n: '详解',     tip: '补背景、逻辑、易错前提' },\n  mnemonic:  { n: '记忆口诀', tip: '把得分点编成顺口的短句' },\n  translate: { n: '例句词根', tip: '英语词条用' }\n};\nfunction rcCardAiGet(c, k) {\n  if (!c || !k) return null;\n  const box = (c.ai && typeof c.ai === 'object') ? c.ai : null;\n  if (!box || !box[k]) return null;\n  const it = box[k];\n  if (k === 'variant') return (it.list && it.list.length) ? it : null;\n  return String(it.text || '').trim() ? it : null;\n}\nasync function rcCardAiPut(c, k, text, extra) {\n  if (!c || !k) return null;\n  c.ai = (c.ai && typeof c.ai === 'object') ? c.ai : {};\n  const rec = Object.assign({ at: Date.now() }, extra || {});\n  if (k === 'variant') rec.list = Array.isArray(text) ? text : ((text && text.list) || []);\n  else rec.text = String(text || '').trim();\n  c.ai[k] = rec;\n  await rcSaveCard(c);\n  return rec;\n}\nasync function rcCardAiDel(c, k) {\n  if (!c || !k || !c.ai) return;\n  delete c.ai[k];\n  await rcSaveCard(c);\n}\n/* 这张卡上已经生成过哪些 —— 编辑表单里按这个列出来 */\nfunction rcCardAiList(c) {\n  const out = [];\n  Object.keys(RC_AI_KINDS).forEach(k => { const it = rcCardAiGet(c, k); if (it) out.push({ k: k, it: it }); });\n  return out;\n}\n/* ---------- 背诵流水（今日/累计统计都从这里算） ---------- */\nasync function rcLogAdd(rec) {\n  if (!rec) return null;\n  const r = await DB.create(T.RLOG, JSON.parse(JSON.stringify(rec)));\n  if (r) { rec.id = r.id; S.rlogs = [rec].concat(S.rlogs || []); }\n  return rec;\n}\nfunction rcTodayLogs() { const t = dkey(); return (S.rlogs || []).filter(x => x.date === t); }\n/* 词本预览：前几张卡片的题干，列表里给个印象 */\nfunction rcPeek(bookId, n) {\n  const list = rcCardsOf(bookId).slice(0, n || 3);\n  if (!list.length) return '（还没有卡片）';\n  return list.map(c => String(c.q || '').slice(0, 18)).join(' · ');\n}\n/* ==========================================================\n   视图 · 背书首页（词本列表）\n   ========================================================== */\nVIEWS.rcbooks = function () {\n  /* 每次进这一页都顺手补一次今日复盘：今天背过、但纪要还没跟上，就自动更新一份。\n     放在 render 之后异步跑，不挡你操作；AI 关着就写本地统计版。 */\n  setTimeout(() => { try { rcReviewAuto(); } catch (e) { } }, 400);\n  const active = rcActiveBooks(), arch = rcArchivedBooks();\n  const all = rcCards();\n  const today = rcTodayLogs();\n  const todayN = sum(today.map(x => Number(x.total) || 0));\n  const todayDict = sum(today.map(x => Number(x.dictationN) || 0));\n  const todayRight = sum(today.map(x => Number(x.dictationRight) || 0));\n  const todayNew = sum(today.map(x => Number(x.newN) || 0));\n  const todayWeak = sum(today.map(x => Number(x.weakN) || 0));\n  const weakN = rcWeakCards().length;\n  const doneN = all.filter(c => Number(c.level) >= 2).length;\n  return `\n  ${(S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) ? `<div class=\"card\" style=\"border-color:rgba(255,201,120,.55);background:linear-gradient(160deg,rgba(255,201,120,.14),rgba(255,255,255,.03))\">\n    <div class=\"row between\"><div class=\"grow\">\n      <div class=\"tiny\">📖 有一轮还没背完</div>\n      <div style=\"font-size:14.5px\">第 ${Math.min(S.recite.idx + 1, S.recite.queue.length)} / ${S.recite.queue.length} 条 · 已评 ${S.recite.done || 0} 条</div>\n      <div class=\"tiny mt6\">${S.recite.scope === 'weak' ? '薄弱专项' : (S.recite.scope === 'forget' ? '快忘的' : (S.recite.scope === 'plan' ? '🤖 今日计划' : (S.recite.scope === 'paper' ? 'AI 组卷' : (S.recite.scope === 'pick' ? '挑选的卡片' : (S.recite.bookId ? esc(rcBookName(S.recite.bookId)) : '综合')))))}</div></div>\n      <button class=\"btn sm primary\" data-act=\"rcResume\">继续</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"rcQuitFromHome\">结束并记账</button></div>\n  </div>` : ''}\n  <div class=\"card hero-soft\">\n    <div class=\"row between\"><div class=\"grow\"><h3>📖 背书</h3>\n      <div class=\"tiny mt6\">词本、卡片、背诵、默写、薄弱专项都在这儿。评测等级分「不会 / 模糊 / 熟练 / 精通」四档，调度会照等级和出错次数给卡片排队。</div></div>\n      <div style=\"font-size:30px\">📖</div></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${active.length}</div><div class=\"tiny\">词本</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length}</div><div class=\"tiny\">卡片</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600;color:var(--teal)\">${doneN}</div><div class=\"tiny\">熟练以上</div></div>\n      <div class=\"grow center\" data-act=\"gotoView\" data-view=\"rcweak\" style=\"cursor:pointer\">\n        <div style=\"font-size:17px;font-weight:600;color:${weakN ? 'var(--gold)' : 'inherit'};${weakN ? 'text-decoration:underline;text-underline-offset:3px;' : ''}\">${weakN}</div>\n        <div class=\"tiny\">薄弱卡片${weakN ? ' ›' : ''}</div></div>\n    </div>\n    <div class=\"tiny mt6\">今天背了 ${todayN} 条${todayDict ? '（默写 ' + todayDict + ' 条，正确 ' + todayRight + ' 条）' : ''}${todayNew ? ' · 新增 ' + todayNew + ' 张' : ''}${todayWeak ? ' · 攻克薄弱 ' + todayWeak + ' 张' : ''}</div>\n    ${(function () {\n      const goal = Math.max(0, Math.round(rcNum('rcDailyGoal', 20)) || 0);\n      if (!goal) return '';\n      const pct = clamp(Math.round(todayN / goal * 100), 0, 100);\n      return `<div class=\"mt6\"><div class=\"row between\"><span class=\"tiny\">今日目标 ${goal} 条</span>\n        <span class=\"tiny\" style=\"color:${pct >= 100 ? 'var(--teal)' : 'var(--dim2)'}\">${todayN} / ${goal}${pct >= 100 ? ' · 达标了' : ''}</span></div>\n        <div class=\"bar mt6\"><i style=\"width:${pct}%\"></i></div></div>`;\n    })()}\n    <button class=\"btn primary block mt10\" data-act=\"rcNewBook\">＋ 新建词本</button>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      ${rcAiOn('plan') ? `<button class=\"btn sm grow\" data-act=\"rcAiPlanBtn\" ${S.loading === 'rcplan' ? 'disabled' : ''}>${S.loading === 'rcplan' ? '想想…' : '🤖 今日计划'}</button>` : ''}\n      ${rcAiOn('pet') ? `<button class=\"btn sm grow\" data-act=\"rcAiPetOpen\">🎤 让 TA 抽背</button>` : ''}\n      <button class=\"btn sm ghost\" data-act=\"rcAiSheet\">🤖 AI</button></div>\n    <div class=\"row mt10\" style=\"gap:10px\">\n      <button class=\"btn sm ghost grow\" data-act=\"rcSets\">⚙️ 背书设置</button>\n      <button class=\"btn sm ghost grow\" data-act=\"rcRestoreOpen\">📥 还原备份</button></div>\n    ${S.draft.rcPlanAI ? `<div class=\"card tight mt10\" style=\"background:var(--card2)\">\n      <div class=\"tiny\">🤖 今天的建议</div>\n      <div style=\"font-size:13.4px;line-height:1.7;margin-top:4px\">背 ${Number(S.draft.rcPlanAI.count) || 0} 条 · 先背「${esc(S.draft.rcPlanAI.book || '')}」</div>\n      ${S.draft.rcPlanAI.why ? `<div class=\"tiny mt6\">${esc(S.draft.rcPlanAI.why)}</div>` : ''}\n      ${S.draft.rcPlanAI.line ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">${esc(S.draft.rcPlanAI.line)}</div>` : ''}\n      ${(function () {\n        const ids = S.draft.rcPlanPick || [];\n        if (!ids.length) return `<div class=\"tiny mt8\" style=\"color:var(--gold)\">这会儿没挑出可背的卡片（词本可能还是空的）。</div>`;\n        const bk = rcBookById(S.draft.rcPlanBookId);\n        /* 以前这里只报一句「挑了 N 条」+ 一个开始键 —— 你看不到具体是哪些题，\n           也没法减掉已经会的、或再添两条。现在把清单摊开：一条一行，可删可添。 */\n        const list = ids.map(rcCardById).filter(Boolean);\n        return `<div class=\"row between mt8\"><span class=\"tiny\">已经替你挑好这 <b>${list.length}</b> 条${bk ? '（' + esc(bk.name) + '）' : ''} · 按「优先级 + 出错多 + 久没碰」排</span>\n          <button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"rcPlanClear\">清空</button></div>\n        <div class=\"mt6\" style=\"max-height:34vh;overflow:auto\">${list.map((c, i) => `<div class=\"item\" style=\"padding:7px 0\">\n          <div class=\"ic\">${i + 1}</div>\n          <div class=\"grow\" style=\"min-width:0\"><div style=\"font-size:12.6px;line-height:1.55\">${esc(String(c.q).slice(0, 46))}</div>\n            <div class=\"tiny\">${esc(rcLvName(c.level))} · 错 ${Number(c.wrongN || 0)} 次 · ${esc(rcPriName(rcPriOf(c)))}</div></div>\n          <button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"rcPlanDrop\" data-id=\"${esc(c.id)}\">去掉</button></div>`).join('')}</div>\n        <div class=\"row mt8\" style=\"gap:6px\">\n          <button class=\"btn sm ghost grow\" data-act=\"rcPlanAddMore\" data-n=\"5\">＋ 再加 5 条</button>\n          <button class=\"btn sm ghost grow\" data-act=\"rcPlanAddMore\" data-n=\"10\">＋ 再加 10 条</button></div>\n        <button class=\"btn primary block mt8\" data-act=\"rcPlanStart\">▶️ 就按这 ${list.length} 条开始</button>`;\n      })()}\n    </div>` : ''}\n  ${(function () {\n      /* 今日复盘单独一张卡 —— 以前它藏在「今日计划」里面，没点过计划就根本看不到入口。 */\n      const today = rcTodayLogs();\n      const tN = sum(today.map(x => Number(x.total) || 0));\n      const rec = (cfg('rcReviews') || {})[dkey()] || null;\n      const line = rec ? rec.text : (S.draft.rcReviewAI || '');\n      return `<div class=\"card\">\n      <div class=\"row between\"><h3>📝 今日复盘</h3>\n        <span class=\"tiny\">${tN ? '今天背了 ' + tN + ' 条' : '今天还没开背'}${rec && rec.byAI === false ? ' · 本地版' : ''}</span></div>\n      ${line ? `<div style=\"font-size:13.2px;line-height:1.8;margin-top:6px;white-space:pre-wrap\">${esc(line)}</div>\n        <div class=\"tiny mt6\" style=\"color:var(--dim2)\">${rec && rec.at ? '更新于 ' + dkey(new Date(rec.at)) + ' ' + hm(rec.at) : ''}${(cfg('rcReviews') || {})[dkey()] ? ' · 已留档，历史可在统计页回看' : ''}</div>` : `<div class=\"tiny mt6\">今天背完一轮之后，这里会留一段复盘 —— 你翻了哪些词本、对多少、漏在哪。</div>`}\n      <div class=\"row mt10\" style=\"gap:10px\">\n        <button class=\"btn sm ${line ? 'ghost' : 'primary'} grow\" data-act=\"rcAiReviewBtn\" ${S.loading === 'rcreview' ? 'disabled' : ''}>${S.loading === 'rcreview' ? '正在写…' : (line ? '↺ 重新写一份' : '写今天的复盘')}</button>\n        ${line ? `<button class=\"btn sm ghost grow\" data-act=\"rcReviewFav\">⭐ 收藏</button>` : ''}\n        <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"rcstats\">历史</button></div>\n      ${rcAiOn('review') ? '' : '<div class=\"tiny mt6\" style=\"color:var(--dim2)\">AI 复盘已在背书设置里关掉，现在写的是本地统计版。</div>'}\n    </div>`;\n    })()}\n  </div>\n  ${active.length ? active.map(b => {\n    const n = rcCardN(b.id), m = rcMasteredN(b.id);\n    const pct = n ? Math.round(m / n * 100) : 0;\n    const weak = rcWeakCards(b.id).length;\n    return `<div class=\"card tight\">\n      <div class=\"row between\" data-act=\"rcOpenBook\" data-id=\"${esc(b.id)}\" style=\"cursor:pointer\">\n        <div class=\"grow\" style=\"min-width:0\">\n          <div style=\"font-size:14.5px;font-weight:600\">${esc(b.name)}</div>\n          <div class=\"tiny ellip\">${esc(rcPeek(b.id, 3))}</div>\n          <div class=\"tiny mt6\">${n} 张卡片 · 熟练以上 ${m}${weak ? ' · <span style=\"color:var(--gold)\">薄弱 ' + weak + '</span>' : ''}</div>\n        </div>\n        <div style=\"text-align:right\"><div style=\"font-size:17px;font-weight:600;color:var(--teal)\">${pct}%</div><div class=\"tiny\">掌握</div></div>\n      </div>\n      <div class=\"bar mt8\"><i style=\"width:${pct}%\"></i></div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn sm primary grow\" data-act=\"rcStart\" data-id=\"${esc(b.id)}\" ${n ? '' : 'disabled'}>${n ? '▶️ 开始背诵' : '先加卡片'}</button>\n        <button class=\"btn sm ghost\" data-act=\"rcOpenBook\" data-id=\"${esc(b.id)}\">卡片</button>\n        <button class=\"btn sm ghost\" data-act=\"rcBookMenu\" data-id=\"${esc(b.id)}\">⋯</button></div>\n    </div>`;\n  }).join('') : `<div class=\"empty\">还没有词本。<br>点上面「新建词本」起一个，比如「专业课」「公考」「英语单词」。</div>`}\n  ${arch.length ? `<div class=\"card\"><div class=\"row between\"><h3>已归档（${arch.length}）</h3>\n    <span class=\"tiny\">归档不删数据，只是不占首页</span></div>\n    ${arch.map(b => `<div class=\"item\"><div class=\"ic\">📦</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(b.name)}</div>\n      <div class=\"tiny\">${rcCardN(b.id)} 张卡片</div></div>\n      <button class=\"btn sm ghost\" data-act=\"rcUnarchive\" data-id=\"${esc(b.id)}\">取消归档</button>\n      <button class=\"btn sm ghost\" data-act=\"rcDelBookAsk\" data-id=\"${esc(b.id)}\">删</button></div>`).join('')}</div>` : ''}\n  <div class=\"card\"><div class=\"row between\"><h3>还能做什么</h3><span class=\"tiny\">下一轮会陆续补齐</span></div>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">\n    · 「批量导入」：粘贴一大段材料，自动切成题干/答案，一次最多 200 条；<br>\n    · 「AI 生成卡片」：把课文、笔记、课件粘进去，AI 帮你拆成整套卡片（要人工确认才入库）；<br>\n    · 背诵会话里可切换 <b>顺序 / 权重随机</b>、<b>卡片 / 默写</b>、三种遮罩、倒计时考试模式；<br>\n    · 薄弱专项、统计面板、AI 判分与启发提示。</div></div>`;\n};\n/* ==========================================================\n   批量导入解析\n   ----------------------------------------------------------\n   支持三种写法，够用且不瞎猜：\n   ① 【题干】…【答案】…（也认【问题】【题目】【解答】【答】）\n   ② 一行题干、下一行答案\n   ③ 自动过滤题号（1. / 1、/ (1) / 第1题）、空行、多余空格\n   解析完自动去掉空卡片，并按题干去重（重复的只提示、不擅自丢）\n   ========================================================== */\nfunction rcStripNo(s) {\n  return String(s || '')\n    .replace(/^\\s*[（(]\\s*\\d+\\s*[)）]\\s*/, '')\n    .replace(/^\\s*第\\s*\\d+\\s*[题问]?\\s*[.、)）:：]?\\s*/, '')\n    .replace(/^\\s*\\d+\\s*[.、)）:：]\\s*/, '')\n    .trim();\n}\nfunction rcNormQ(s) {\n  return String(s || '').toLowerCase().replace(/[\\s，,。.、：:；;！!？?\"'“”‘’()（）\\[\\]【】]/g, '');\n}\nfunction rcParseImport(text) {\n  const raw = [];\n  const t = String(text || '').replace(/\\r/g, '');\n  /* ① 带标记的写法：按标记切，一段文本里可以含多条 */\n  if (/【\\s*(题干|问题|题目|问)\\s*】/.test(t) || /【\\s*(答案|解答|答)\\s*】/.test(t)) {\n    const re = /【\\s*(题干|问题|题目|问)\\s*】([\\s\\S]*?)(?:【\\s*(?:答案|解答|答)\\s*】([\\s\\S]*?))?(?=【\\s*(?:题干|问题|题目|问)\\s*】|$)/g;\n    let m;\n    while ((m = re.exec(t)) !== null) {\n      const q = rcStripNo(String(m[2] || '').replace(/\\s+/g, ' ').trim());\n      const a = String(m[3] || '').trim().replace(/^\\s*[：:]\\s*/, '');\n      if (q) raw.push({ q: q, a: a, hint: '' });\n    }\n  }\n  /* ①b 一行一条：题干和答案写在同一行，用分隔符隔开。\n        这是从文档 / 网页复制材料时最常见的样子，以前只认「一行题干、一行答案」，\n        这种整段就会被错配成「第1行是题干、第2行是它的答案」—— 全歪。 */\n  if (!raw.length) {\n    const lines0 = t.split('\\n').map(x => x.replace(/[ \\t]+/g, ' ').trim()).filter(x => x !== '');\n    const SEP = /\\s*(?:\\|\\||｜\\||\\|{1,2}|={2,}|~{2,}|→|➔|>>|＞＞|·|・)\\s*/;\n    const withSep = lines0.filter(x => SEP.test(x));\n    if (withSep.length >= 2 && withSep.length >= lines0.length * 0.6) {\n      lines0.forEach(line => {\n        const parts = line.split(SEP).filter(x => String(x).trim() !== '');\n        if (parts.length < 2) return;\n        const q = rcStripNo(parts[0]);\n        const a = rcStripNo(parts.slice(1).join(' '));\n        if (q) raw.push({ q: q, a: a, hint: '' });\n      });\n    }\n    /* 再兜一层：一行里直接写「题干 答：答案」 */\n    if (!raw.length) {\n      const HIT = lines0.filter(x => /(?:^|[\\s。？?！!])(?:答|答案|解答)\\s*[：:]/.test(x));\n      if (HIT.length >= 2 && HIT.length >= lines0.length * 0.6) {\n        lines0.forEach(line => {\n          const m = line.match(/^([\\s\\S]+?)[\\s]*(?:答|答案|解答)\\s*[：:]\\s*([\\s\\S]*)$/);\n          if (!m) return;\n          const q = rcStripNo(m[1]);\n          const a = rcStripNo(m[2]);\n          if (q) raw.push({ q: q, a: a, hint: '' });\n        });\n      }\n    }\n  }\n  if (!raw.length) {\n    /* ② 一行题干、一行答案 */\n    const lines = t.split('\\n').map(x => x.replace(/[ \\t]+/g, ' ').trim()).filter(x => x !== '');\n    for (let i = 0; i < lines.length; i += 2) {\n      const q = rcStripNo(lines[i]);\n      const a = rcStripNo(lines[i + 1] || '');\n      if (q) raw.push({ q: q, a: a, hint: '' });\n    }\n  }\n  /* ③ 清洗：去空卡片 + 按题干去重 */\n  const clean = [], seen = {};\n  let dup = 0;\n  raw.forEach(c => {\n    if (!c.q) return;\n    const k = rcNormQ(c.q);\n    if (!k) return;\n    if (seen[k]) { dup++; return; }\n    seen[k] = 1;\n    clean.push(c);\n  });\n  return { list: clean.slice(0, 200), dup: dup, total: clean.length, cut: Math.max(0, clean.length - 200) };\n}\n/* ==========================================================\n   视图 · 词本详情（浏览全部卡片 / 新建 / 导入 / 导出）\n   ========================================================== */\nVIEWS.rcbook = function () {\n  const b = rcBookById(S.draft.rcBookId);\n  if (!b) return `<div class=\"card\"><h3>找不到这个词本</h3>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"rcbooks\">回背书首页</button></div>`;\n  const allCards = rcCardsOf(b.id);\n  const weak = rcWeakCards(b.id).length;\n  /* ---- 搜索卡片：题干 / 答案 / 关键词 / 笔记 全都能搜到 ---- */\n  const kw = String(S.draft.rcSearch || '').trim();\n  const nk = norm(kw);\n  /* 搜索把标签也算进来 —— 输「第一章」能直接搜到打了这个标签的卡片。\n     命中之后按「匹配得有多准」排序，代替原来的「录入顺序」：\n     题干完全等于 > 题干开头就是 > 题干中间出现 > 答案里有 >\n     提示词里有 > 笔记里有 > 标签里有。同分保持原来的录入顺序（稳定）。 */\n  const rcHitScore = c => {\n    if (!nk) return 0;\n    const q = norm(c.q), a = norm(c.a), h = norm(c.hint), nt = norm(c.note);\n    const tg = norm(rcTagsOf(c).join(',')), tr = norm((c.tricky || []).join(','));\n    if (q === nk) return 1000;\n    const qi = q.indexOf(nk);\n    if (qi === 0) return 900 - Math.min(200, q.length - nk.length);\n    if (qi > 0) return 700 - Math.min(200, qi) - Math.min(100, q.length - nk.length);\n    if (a.indexOf(nk) >= 0) return 500;\n    if (h.indexOf(nk) >= 0) return 400;\n    if (nt.indexOf(nk) >= 0) return 300;\n    if (tg.indexOf(nk) >= 0) return 200;\n    if (tr.indexOf(nk) >= 0) return 150;\n    return 0;\n  };\n  let list = nk ? allCards.filter(c => rcHitScore(c) > 0) : allCards.slice();\n  if (nk) list = list.map((c, i) => ({ c: c, s: rcHitScore(c), i: i }))\n    .sort((x, y) => (y.s - x.s) || (x.i - y.i)).map(x => x.c);\n  /* ---- 按标签 / 优先级 / 等级 / 热力筛选 ---- */\n  const filter = String(S.draft.rcFilter || '');\n  if (filter) list = list.filter(c => rcFilterHit(c, filter));\n  const tagStat = {};\n  allCards.forEach(c => rcTagsOf(c).forEach(t => { tagStat[t] = (tagStat[t] || 0) + 1; }));\n  const tagNames = Object.keys(tagStat).sort((a, b) => tagStat[b] - tagStat[a]);\n  const hotN = allCards.filter(c => { const h = rcHeat(c); return h && h.k === 'hot'; }).length;\n  const filtered = !!(kw || filter);\n  /* ⚠️ 这里以前每次渲染词本页都要实时跑一遍「全卡两两相似度比对」（O(n²)）——\n     卡片一多，这一页会直接卡住甚至画不出来，表现就是「查重复卡片点了没反应 / 查不到」。\n     现在不在渲染里算，改成点「🧹 查重复卡片」时才扫一次。 */\n  const lvN = k => allCards.filter(c => Number(c.level) === k).length;\n  /* 挑选模式：勾几张卡，批量设优先级 / 移动 / 复制 / 只背这几张 */\n  const selMode = !!S.draft.rcSelMode;\n  const selSel = S.draft.rcSelSel || {};\n  const selN = Object.keys(selSel).filter(k => selSel[k]).length;\n  return `\n  <div class=\"card hero-soft\">\n    <div class=\"row between\"><div class=\"grow\"><h3>${esc(b.name)}</h3>\n      <div class=\"tiny mt6\">${allCards.length} 张卡片 · 熟练以上 ${rcMasteredN(b.id)}${weak ? ' · <span style=\"color:var(--gold)\">薄弱 ' + weak + '</span>' : ''} · 建于 ${dkey(new Date(b.at))}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"rcBookMenu\" data-id=\"${esc(b.id)}\">⋯</button></div>\n    <div class=\"row mt10\">\n      ${RC_LV.slice().reverse().map(l => `<div class=\"grow center\"><div style=\"font-size:16px;font-weight:600;color:${l.color}\">${lvN(l.k)}</div><div class=\"tiny\">${l.n}</div></div>`).join('')}\n    </div>\n    ${filtered ? `<button class=\"btn primary block mt12\" style=\"min-height:48px\" data-act=\"rcStartList\" data-ids=\"${esc(list.map(c => c.id).join(','))}\" ${list.length ? '' : 'disabled'}>${list.length ? '▶️ 只背筛出的 ' + list.length + ' 张' : '没有符合条件的卡片'}</button>\n      <button class=\"btn block ghost sm mt8\" data-act=\"rcStart\" data-id=\"${esc(b.id)}\" ${allCards.length ? '' : 'disabled'}>▶️ 还是背整个词本（${allCards.length} 张）</button>` : `<button class=\"btn primary block mt12\" style=\"min-height:48px\" data-act=\"rcStart\" data-id=\"${esc(b.id)}\" ${list.length ? '' : 'disabled'}>${list.length ? '▶️ 开始背诵' : '先加几张卡片'}</button>`}\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"rcCardNew\" data-id=\"${esc(b.id)}\">＋ 新建卡片</button>\n      <button class=\"btn sm grow\" data-act=\"rcImportOpen\" data-id=\"${esc(b.id)}\">📥 批量导入</button>\n      <button class=\"btn sm ghost\" data-act=\"rcExportOpen\" data-id=\"${esc(b.id)}\">📤 导出</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <input class=\"input grow\" data-in=\"rcSearch\" value=\"${esc(kw)}\" placeholder=\"🔍 搜题干 / 答案 / 关键词 / 标签 / 笔记\">\n      ${kw ? `<button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"rcSearchClear\">清除</button>` : ''}\n    </div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ${filter ? 'primary' : 'ghost'} grow\" data-act=\"rcFilterOpen\">🔎 ${filter ? esc(rcFilterLabel(filter)) : ('筛选卡片（' + allCards.length + ' 张）')}</button>\n      ${filter ? `<button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"rcFilterClear\">清掉</button>` : ''}\n    </div>\n    ${filtered ? `<div class=\"tiny mt6\">筛出 <b>${list.length}</b> / ${allCards.length} 张${list.length ? '' : ' —— 换个条件试试'}</div>` : ''}\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ${selMode ? 'primary' : 'ghost'} grow\" data-act=\"${selMode ? 'rcSelModeOff' : 'rcSelModeOn'}\">${selMode ? '✅ 退出挑选' : '☑️ 挑选卡片'}</button>\n      <button class=\"btn sm ghost grow\" data-act=\"rcDupScan\" data-id=\"${esc(b.id)}\">🧹 查重复卡片</button>\n    </div>\n    ${selMode ? `<div class=\"tiny mt6\">当前焦点档：<b>${esc(rcFocusText(list))}</b> —— 焦点档会被重点抽，已过关的档穿插回来复习。</div>` : ''}\n  </div>\n  ${list.length ? list.map((c, i) => {\n    const h = rcHeat(c);\n    const on = !!selSel[String(c.id)];\n    return `<div class=\"card tight\" ${selMode ? `data-act=\"rcSelToggle\" data-id=\"${esc(c.id)}\" style=\"cursor:pointer;border-color:${on ? 'rgba(124,140,255,.85)' : 'var(--line)'};${on ? 'background:linear-gradient(160deg,rgba(124,140,255,.16),rgba(255,255,255,.03))' : ''}\"` : ''}>\n      <div class=\"row between\">\n        <span class=\"tiny\">${selMode ? (on ? '☑️ ' : '⬜ ') : ''}#${i + 1}${h ? ' <span style=\"color:' + h.color + '\">' + h.emoji + ' ' + h.n + '</span>' : ''}</span>\n        <span class=\"row\" style=\"gap:5px\">\n          <span class=\"pill\" style=\"color:${rcPriColor(rcPriOf(c))}\">${rcPri(c.pri == null ? 2 : c.pri).emoji} ${esc(rcPriName(rcPriOf(c)))}</span>\n          <span class=\"pill\" style=\"color:${rcLvColor(c.level)}\">${rcLvName(c.level)}</span>\n          ${Number(c.wrongN || 0) ? `<span class=\"pill bad\">错 ${c.wrongN}</span>` : ''}\n        </span></div>\n      <div style=\"font-size:13.4px;line-height:1.65;margin-top:6px\">${rcHi(String(c.q).slice(0, 90), kw)}</div>\n      ${rcTagsOf(c).length ? `<div class=\"row wrap mt6\" style=\"gap:5px\">${rcTagsOf(c).map(t => `<span class=\"pill\" data-act=\"rcFilterSet\" data-v=\"tag:${esc(t)}\" style=\"font-size:10.5px;cursor:pointer\">#${esc(t)}</span>`).join('')}</div>` : ''}\n      <div class=\"tiny mt6\" style=\"color:var(--dim);overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">答：${rcHi(String(c.a || '').replace(/\\n/g, ' ').slice(0, 60), kw)}</div>\n      ${c.note ? `<div class=\"tiny mt6\" style=\"color:var(--gold);overflow:hidden;text-overflow:ellipsis;white-space:nowrap\">📝 ${rcHi(String(c.note).slice(0, 40), kw)}</div>` : ''}\n      ${selMode ? '' : `<div class=\"row mt8\" style=\"gap:8px\">\n        <button class=\"btn sm ghost grow\" data-act=\"rcCardEdit\" data-id=\"${esc(c.id)}\">编辑</button>\n        <button class=\"btn sm ghost grow\" data-act=\"rcCardReset\" data-id=\"${esc(c.id)}\">重置掌握</button>\n        <button class=\"btn sm ghost\" data-act=\"rcCardDel\" data-id=\"${esc(c.id)}\">删</button></div>`}\n    </div>`;\n  }).join('') : `<div class=\"empty\">这个词本还是空的。<br>点「新建卡片」一条条加，或用「批量导入」粘贴一大段材料自动拆。</div>`}\n  ${selMode ? `<div style=\"height:200px\"></div>\n  <div style=\"position:fixed;left:12px;right:12px;bottom:calc(var(--ai-phone-app-safe-bottom,20px) + 72px);z-index:26;background:rgba(20,25,38,.97);border:1px solid var(--line);border-radius:15px;padding:10px 12px;backdrop-filter:blur(14px)\">\n    <div class=\"row between\"><span class=\"tiny\">已选 <b>${selN}</b> 张</span>\n      <span class=\"row\" style=\"gap:6px\">\n        <button class=\"btn sm ghost\" data-act=\"rcSelAll\">全选</button>\n        <button class=\"btn sm ghost\" data-act=\"rcSelNone\">清空</button>\n        <button class=\"btn sm ghost\" data-act=\"rcSelModeOff\">退出</button></span></div>\n    <div class=\"row mt6\" style=\"gap:6px\">\n      <button class=\"btn sm grow\" data-act=\"rcSelPri\" data-k=\"0\" ${selN ? '' : 'disabled'}>🔴 必背</button>\n      <button class=\"btn sm grow\" data-act=\"rcSelPri\" data-k=\"1\" ${selN ? '' : 'disabled'}>🟡 重要</button>\n      <button class=\"btn sm grow\" data-act=\"rcSelPri\" data-k=\"2\" ${selN ? '' : 'disabled'}>⚪ 一般</button>\n    </div>\n    <div class=\"row mt6\" style=\"gap:6px\">\n      <button class=\"btn sm grow\" data-act=\"rcSelMove\" ${selN ? '' : 'disabled'}>↔️ 移走</button>\n      <button class=\"btn sm grow\" data-act=\"rcSelCopy\" ${selN ? '' : 'disabled'}>⧉ 复制</button>\n    </div>\n    <button class=\"btn primary block mt6\" data-act=\"rcSelStart\" ${selN ? '' : 'disabled'}>▶️ 只背选中的 ${selN} 张</button>\n  </div>` : ''}`;\n};\n/* ---------- 搜索高亮：把命中的那段原样染上色 ----------\n   为什么要做「字符映射」而不是直接 indexOf：搜索走的是 norm() 归一化后的串\n   （去了标点、转了小写），归一化串里的位置对不回原文位置，直接切会把字切歪。\n   这里逐字构建 map：归一化后的第 k 个字符，对应原文的哪个下标。 */\nfunction rcHi(text, kw) {\n  const s = String(text == null ? '' : text);\n  const nk = norm(kw);\n  if (!nk) return esc(s);\n  const map = [];\n  let ns = '';\n  for (let i = 0; i < s.length; i++) {\n    const nch = norm(s[i]);\n    if (!nch) continue;\n    ns += nch;\n    for (let j = 0; j < nch.length; j++) map.push(i);\n  }\n  const at = ns.indexOf(nk);\n  if (at < 0) return esc(s);\n  const a = map[at], b = map[at + nk.length - 1];\n  if (a == null || b == null || b < a) return esc(s);\n  return esc(s.slice(0, a))\n    + '<span style=\"color:#ffe0b0;background:rgba(255,201,120,.2);border-radius:3px;padding:0 2px\">' + esc(s.slice(a, b + 1)) + '</span>'\n    + esc(s.slice(b + 1));\n}\n/* ==========================================================\n   视图 · 批量导入（粘贴 → 解析 → 预览 → 入库）\n   ========================================================== */\nVIEWS.rcimport = function () {\n  const b = rcBookById(S.draft.rcBookId);\n  if (!b) return `<div class=\"card\"><h3>先选一个词本</h3>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"rcbooks\">回背书首页</button></div>`;\n  const pv = S.draft.rcImportPreview;\n  return `\n  <div class=\"card hero-soft\">\n    <h3>📥 批量导入到「${esc(b.name)}」</h3>\n    <div class=\"tiny mt6\">支持三种写法，混着写也行：</div>\n    <div class=\"tiny mt6\" style=\"line-height:1.85;background:var(--card2);border-radius:10px;padding:10px\">\n      ① <b>【题干】…【答案】…</b>（也认【问题】【题目】/【解答】【答】）<br>\n      ② <b>一行题干，下一行答案</b><br>\n      ③ 题号（1. / 1、/ (1) / 第1题）与空行会自动过滤<br>\n      · 单次最多 <b>200 条</b>，超出的部分会被截掉（会告诉你）</div>\n  </div>\n  <div class=\"card\">\n    <label class=\"fl\">把材料粘到这里</label>\n    <textarea id=\"rcImportBox\" style=\"min-height:190px\" placeholder=\"例如：\\n1. 什么是边际效用？\\n指每增加一单位消费所带来的额外满足感。\\n2. 【题干】机会成本【答案】为选择某一方案而放弃的最高价值。\">${esc(S.draft.rcImportText || '')}</textarea>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"rcImportParse\">解析预览</button>\n      <button class=\"btn ghost\" data-act=\"rcImportClear\">清空</button></div>\n    ${rcAiOn('gen') ? `<button class=\"btn block mt8\" data-act=\"rcImportAi\" ${S.loading === 'rcgen' ? 'disabled' : ''}>${S.loading === 'rcgen' ? 'AI 正在拆题…' : '🤖 让 AI 把它拆成卡片'}</button>\n    <div class=\"tiny mt6\">适合粘一整段课文 / 笔记 / 课件：AI 替你切成「题干 + 答案 + 关键词」，切完照样先在这里预览，确认无误再入库。</div>` : ''}\n  </div>\n  ${pv ? `<div class=\"card\">\n    <div class=\"row between\"><h3>预览（${pv.list.length} 条）</h3>\n      <span class=\"tiny\">${pv.dup ? '重复 ' + pv.dup + ' 条已跳过 · ' : ''}${pv.cut ? '超出上限截掉 ' + pv.cut + ' 条 · ' : ''}解析到 ${pv.total} 条</span></div>\n    ${pv.dup ? `<div class=\"tiny mt6\" style=\"color:var(--gold)\">发现 ${pv.dup} 条题干重复，已经自动跳过（不会覆盖原有卡片）。</div>` : ''}\n    ${pv.cut ? `<div class=\"tiny mt6\" style=\"color:var(--gold)\">超过 200 条上限，只有前 200 条会被导入。</div>` : ''}\n    <div class=\"tiny mt8\">下面每一条都能直接改 —— 解析歪了一两条，就在这儿修，不用回去改原文重解析。</div>\n    <div class=\"mt8\" style=\"max-height:46vh;overflow:auto\">\n      ${pv.list.map((c, i) => `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:8px\">\n        <div class=\"row between\"><span class=\"tiny\">#${i + 1}</span>\n          <button class=\"btn sm ghost\" data-act=\"rcPreviewDel\" data-i=\"${i}\">删掉这条</button></div>\n        <input class=\"input mt6\" data-in=\"rcPreview.${i}.q\" value=\"${esc(c.q || '')}\" placeholder=\"题干\">\n        <textarea data-in=\"rcPreview.${i}.a\" style=\"min-height:56px;margin-top:6px\" placeholder=\"答案（可留空，导入后再补）\">${esc(c.a || '')}</textarea>\n      </div>`).join('')}\n    </div>\n    <button class=\"btn primary block mt12\" data-act=\"rcImportSave\" ${pv.list.length ? '' : 'disabled'}>确认导入 ${pv.list.length} 张卡片</button>\n    ${S.draft.rcImportFromAI ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">这些卡片是 AI 拆出来的 —— 确认无误再入库。</div>` : ''}\n  </div>` : ''}\n  <button class=\"btn block ghost sm mt10\" data-act=\"rcOpenBook\" data-id=\"${esc(b.id)}\">← 回「${esc(b.name)}」</button>`;\n};\n/* ==========================================================\n   视图 · 薄弱专项（只刷易错卡片）\n   ========================================================== */\nVIEWS.rcweak = function () {\n  const all = rcWeakCards();\n  const hot = all.filter(c => Number(c.wrongN || 0) >= 3);\n  const groups = {};\n  all.forEach(c => { const k = String(c.bookId); groups[k] = (groups[k] || 0) + 1; });\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(255,123,138,.14),rgba(255,255,255,.03));border-color:rgba(255,123,138,.3)\">\n    <div class=\"row between\"><div class=\"grow\"><h3>🔥 薄弱专项</h3>\n      <div class=\"tiny mt6\">只装「不会 / 模糊 / 出过错」的卡片。红色（错 ≥3 次）强制置顶，优先刷它们。</div></div>\n      <div style=\"font-size:30px\">🔥</div></div>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length}</div><div class=\"tiny\">薄弱卡片</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600;color:#ff7b8a\">${hot.length}</div><div class=\"tiny\">高频易错</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${Object.keys(groups).length}</div><div class=\"tiny\">涉及词本</div></div>\n    </div>\n    ${all.length ? `<button class=\"btn primary block mt12\" style=\"min-height:48px\" data-act=\"rcStartWeak\">▶️ 开始专刷薄弱（${all.length} 张）</button>` : ''}\n    ${(all.length && rcAiOn('weak')) ? `<button class=\"btn block mt8\" data-act=\"rcAiWeakBtn\" ${S.loading === 'rcweak' ? 'disabled' : ''}>${S.loading === 'rcweak' ? '正在归纳…' : '🤖 让 AI 归纳我总在错什么'}</button>` : ''}\n    ${(S.draft.rcWeakAI && S.draft.rcWeakAI.summary) ? `<div class=\"card tight mt10\" style=\"background:var(--card2)\">\n      <div class=\"row between\"><span class=\"tiny\">🤖 薄弱诊断${S.draft.rcWeakAIAt ? ' · ' + dkey(new Date(S.draft.rcWeakAIAt)) + ' ' + hm(S.draft.rcWeakAIAt) : ''}</span>\n        <button class=\"btn sm ghost\" data-act=\"rcWeakAiClear\">收起</button></div>\n      <div style=\"font-size:13.2px;line-height:1.75;margin-top:5px\">${esc(S.draft.rcWeakAI.summary)}</div>\n      ${(S.draft.rcWeakAI.groups || []).length ? `<div class=\"tiny mt8\" style=\"color:#ffb37a\">薄弱类别</div>${S.draft.rcWeakAI.groups.map(x => `<div class=\"tiny\" style=\"font-size:12.6px;line-height:1.7\">· ${esc(x)}</div>`).join('')}` : ''}\n      ${(S.draft.rcWeakAI.reasons || []).length ? `<div class=\"tiny mt8\" style=\"color:var(--gold)\">共性原因</div>${S.draft.rcWeakAI.reasons.map(x => `<div class=\"tiny\" style=\"font-size:12.6px;line-height:1.7\">· ${esc(x)}</div>`).join('')}` : ''}\n      ${(S.draft.rcWeakAI.advice || []).length ? `<div class=\"tiny mt8\" style=\"color:#b9c2ff\">怎么补</div>${S.draft.rcWeakAI.advice.map(x => `<div class=\"tiny\" style=\"font-size:12.6px;line-height:1.7\">· ${esc(x)}</div>`).join('')}` : ''}\n      <div class=\"tiny mt8\" style=\"color:var(--dim2)\">这只是归类建议，不改动你的卡片。</div></div>` : ''}\n  </div>\n  ${all.length ? all.slice(0, 80).map(c => {\n    const h = rcHeat(c);\n    return `<div class=\"card tight\">\n      <div class=\"row between\">\n        <span class=\"tiny\">${h ? '<span style=\"color:' + h.color + '\">' + h.emoji + ' ' + h.n + '</span>' : ''} · ${esc(rcBookName(c.bookId))}</span>\n        <span class=\"pill\" style=\"color:${rcLvColor(c.level)}\">${rcLvName(c.level)}</span></div>\n      <div style=\"font-size:13.2px;line-height:1.6;margin-top:6px\">${esc(String(c.q).slice(0, 80))}</div>\n      <div class=\"tiny mt6\" style=\"color:var(--dim)\">错 ${Number(c.wrongN || 0)} 次 · 对 ${Number(c.rightN || 0)} 次${c.lastAt ? ' · 上次 ' + dkey(new Date(c.lastAt)) : ''}</div>\n    </div>`;\n  }).join('') : `<div class=\"empty\">现在没有薄弱卡片。<br>背过一轮之后，出错和没记住的会自己聚到这里。</div>`}`;\n};\n/* ==========================================================\n   动作 · 背书（词本 / 卡片 / 导入 / 导出）\n   ========================================================== */\n/* 卡片编辑表单：抽成独立函数 —— AI 出结果后要重开这张表单才能把结果画出来，\n   因为弹窗不在 render() 的重绘范围里（render 只换 #view 的 innerHTML）。 */\n/* 卡片里的「默写记录 + 易错词」面板：\n   上面是已收进来的易错词（背诵时会挖空），下面是最近几次默写，\n   每次「漏掉的」都能点一下收成易错词 —— 这就是从「错了」到「专门练它」的那一步。 */\n/* ==========================================================\n   卡片编辑表单里的「AI 生成内容」区块\n   ----------------------------------------------------------\n   · 生成过的都在这里列着，点开就能看，还能直接改、删、重新生成；\n   · 没生成过的才去问 API；\n   · AI 的结果存在卡片自己的 ai 字段里，<b>不再往「答案」栏里塞</b> ——\n     详解是详解、口诀是口诀，答案栏始终是你要背的那份标准答案。\n   · 只有「关键词」和「背诵版」提供「填入」按钮（这两个本来就是要替换的），\n     其余一律只读留存，想用就复制走。\n   ========================================================== */\nfunction rcCardAiBlock(c) {\n  if (!c) return '';\n  const canKey = rcAiOn('key'), canEdit = rcAiOn('edit');\n  if (!canKey && !canEdit) return '';\n  const list = rcCardAiList(c);\n  const open = S.draft.rcAiOpenKind || '';\n  return `<div class=\"hr\"></div>\n    <div class=\"tiny\">🤖 AI 生成的内容（生成一次就留在卡片里，随时可改）</div>\n    <div class=\"row wrap mt6\" style=\"gap:6px\">\n      ${canKey ? `<button class=\"btn sm\" data-act=\"rcCardAiGen\" data-id=\"${esc(c.id)}\" data-k=\"keys\" ${S.loading === 'rckey' ? 'disabled' : ''}>${S.loading === 'rckey' ? '正在提…' : (rcCardAiGet(c, 'keys') ? '🔑 关键词（已生成）' : '🔑 自动提关键词')}</button>` : ''}\n      ${canEdit ? `<button class=\"btn sm\" data-act=\"rcCardAiGen\" data-id=\"${esc(c.id)}\" data-k=\"compress\" ${S.loading === 'rcedit' ? 'disabled' : ''}>${rcCardAiGet(c, 'compress') ? '✂️ 背诵版（已生成）' : '✂️ 精简成背诵版'}</button>` : ''}\n      ${canEdit ? `<button class=\"btn sm\" data-act=\"rcCardAiGen\" data-id=\"${esc(c.id)}\" data-k=\"expand\" ${S.loading === 'rcedit' ? 'disabled' : ''}>${rcCardAiGet(c, 'expand') ? '📖 详解（已生成）' : '📖 扩展详解'}</button>` : ''}\n      ${canEdit ? `<button class=\"btn sm\" data-act=\"rcCardAiGen\" data-id=\"${esc(c.id)}\" data-k=\"mnemonic\" ${S.loading === 'rcedit' ? 'disabled' : ''}>${rcCardAiGet(c, 'mnemonic') ? '🧠 口诀（已生成）' : '🧠 编个口诀'}</button>` : ''}\n    </div>\n    ${list.length ? list.map(x => {\n      const isV = x.k === 'variant';\n      const body = isV\n        ? (x.it.list || []).map((v, i) => `<div class=\"tiny mt6\" style=\"line-height:1.7\">变式 ${i + 1}：${esc(v.q)}<div style=\"color:var(--teal);margin-top:3px\">答：${esc(v.a || '—')}</div></div>`).join('')\n        : `<textarea data-in=\"rcAiEdit.${x.k}\" data-cid=\"${esc(c.id)}\" style=\"min-height:${x.k === 'mnemonic' ? 64 : 96}px;margin-top:6px\">${esc(x.it.text || '')}</textarea>`;\n      return `<div class=\"card tight mt8\" style=\"background:var(--card2)\">\n        <div class=\"row between\">\n          <span class=\"tiny\">${esc((RC_AI_KINDS[x.k] || {}).n || x.k)} · ${dkey(new Date(x.it.at))} ${hm(x.it.at)}</span>\n          <span class=\"row\" style=\"gap:5px\">\n            ${(x.k === 'keys' || x.k === 'compress') ? `<button class=\"btn sm ghost\" data-act=\"rcCardAiFill\" data-id=\"${esc(c.id)}\" data-k=\"${x.k}\">填入${x.k === 'keys' ? '关键词' : '答案'}</button>` : ''}\n            <button class=\"btn sm ghost\" data-act=\"rcCardAiGen\" data-id=\"${esc(c.id)}\" data-k=\"${x.k}\">↺ 重新生成</button>\n            <button class=\"btn sm ghost\" data-act=\"rcCardAiDrop\" data-id=\"${esc(c.id)}\" data-k=\"${x.k}\">删</button>\n          </span></div>\n        ${isV ? body : body}\n        ${!isV ? `<button class=\"btn sm ghost block mt6\" data-act=\"rcCardAiSaveEdit\" data-id=\"${esc(c.id)}\" data-k=\"${x.k}\">保存这条 AI 内容的改动</button>` : ''}\n      </div>`;\n    }).join('') : `<div class=\"tiny mt6\" style=\"color:var(--dim2)\">还没生成过 —— 点上面任一个按钮，生成后会留在这里（下次点开先看上次的，不用再烧一次 API）。</div>`}`;\n}\nfunction rcMistakePanel(c) {\n  if (!c) return '';\n  const ms = (c.mistakes || []).slice().reverse();\n  const tr = c.tricky || [];\n  if (!ms.length && !tr.length) return '';\n  return `<div class=\"hr\"></div>\n    <div class=\"tiny\">📝 默写记录与易错词</div>\n    ${tr.length ? `<div class=\"chips mt6\">${tr.map(k => `<button class=\"chip on\" data-act=\"rcUnTricky\" data-id=\"${esc(c.id)}\" data-k=\"${esc(k)}\">${esc(k)} ✕</button>`).join('')}</div>\n      <div class=\"tiny mt6\">这些词在背诵时会被<b>挖空</b>考你（把遮罩切到「挖空 · 只考易错词」）。点 ✕ 去掉。</div>`\n      : `<div class=\"tiny mt6\">还没标易错词 —— 下面每次默写里「漏掉的」点一下就能收进来。</div>`}\n    ${ms.length ? `<div class=\"tiny mt8\">最近 ${ms.length} 次默写</div>` : ''}\n    ${ms.map(m => `<div class=\"card tight\" style=\"background:var(--card2);margin-top:8px\">\n      <div class=\"row between\"><span class=\"tiny\">${dkey(new Date(m.at))} ${hm(m.at)} · ${rcLvName(m.lv)} · 覆盖率 ${m.pct}%</span></div>\n      <div class=\"tiny mt6\" style=\"line-height:1.7;color:var(--dim)\">你写的：${esc(String(m.text || '（空的）').slice(0, 160))}</div>\n      ${(m.miss || []).length ? `<div class=\"tiny mt6\">漏掉的（点一下收进易错词）：</div>\n        <div class=\"chips mt6\">${m.miss.map(k => `<button class=\"chip\" data-act=\"rcAddTricky\" data-id=\"${esc(c.id)}\" data-k=\"${esc(k)}\">${esc(k)} ＋</button>`).join('')}</div>` : ''}\n    </div>`).join('')}`;\n}\nfunction rcOpenCardEdit(c) {\n  if (!c) { toast('这张卡片不在了'); return; }\n  S.draft.rcEditId = c.id || '';      // 记住正在编辑谁，刷新表单时把输入框的字收回来\n  closeAllSheets();\n  openSheet(`<h3>编辑卡片</h3>\n    <label class=\"fl\">题干</label>\n    <textarea id=\"rcQ\" style=\"min-height:70px\">${esc(c.q)}</textarea>\n    <label class=\"fl\">完整答案</label>\n    <textarea id=\"rcA\" style=\"min-height:130px\">${esc(c.a || '')}</textarea>\n    <label class=\"fl\">提示关键词（逗号分隔）</label>\n    <input class=\"input\" id=\"rcH\" value=\"${esc(c.hint || '')}\">\n    <label class=\"fl\">优先级（决定它在哪一轮被重点抽）</label>\n    <div class=\"chips\">\n      ${RC_PRI.map(p => `<button class=\"chip ${rcPriOf(c) === p.k ? 'on' : ''}\" data-act=\"rcCardSetPri\" data-id=\"${esc(c.id)}\" data-k=\"${p.k}\">${p.emoji} ${p.n}</button>`).join('')}\n    </div>\n    <div class=\"tiny mt6\">「必背」整档过完才会轮到「重要」重点抽；被抽到时，已过关的档会穿插回来复习。</div>\n    <label class=\"fl\">我的记忆笔记（只给你看，不参与判分）</label>\n    <textarea id=\"rcNote\" style=\"min-height:80px\" placeholder=\"记你怎么记住这条 —— 联想、口诀、易混点、上次错在哪\">${esc(c.note || '')}</textarea>\n    <label class=\"fl\">标签（逗号分隔，词本里能按标签筛）</label>\n    <input class=\"input\" id=\"rcTags\" value=\"${esc(rcTagsOf(c).join(','))}\" placeholder=\"例如：第一章,易错,名词解释\">\n    <div class=\"tiny mt6\">现在等级：${rcLvName(c.level)} · 错 ${Number(c.wrongN || 0)} 次 · 对 ${Number(c.rightN || 0)} 次</div>\n    ${rcCardAiBlock(c)}\n    <div class=\"tiny mt6\">改完记得点最下面的「保存」。</div>\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"rcCardMoveAsk\" data-id=\"${esc(c.id)}\">↔️ 移到别的词本</button>\n      <button class=\"btn sm ghost grow\" data-act=\"rcCardCopyAsk\" data-id=\"${esc(c.id)}\">⧉ 复制到别的词本</button>\n    </div>\n    ${rcMistakePanel(c)}\n    <div class=\"row mt12\" style=\"gap:8px\">\n      <button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n      <button class=\"btn primary grow\" data-act=\"rcCardSave\" data-id=\"${esc(c.id)}\">保存</button></div>`);\n}\n/* ==========================================================\n   重复卡片检测\n   ----------------------------------------------------------\n   按「去标点后的小写题干」归一化分组，同组 ≥2 张就是重复。\n   答案不一样也算重复（题干一样就是同一道题，该合并）——\n   但会在弹窗里把各自的答案摆出来，方便你判断留哪一张。\n   ========================================================== */\n/* ---------- 题干相似度：0~1，1 = 完全一样 ----------\n   为什么不能只比「去标点后是否完全相同」：\n   以前就是这么做的 —— 所以「什么是边际效用？」和「什么是边际效用」\n   （只差一个标点也算不同）、「简述边际效用的含义」和「边际效用的含义」\n   全都被判成「不重复」，于是你明明有一堆重复卡片，检测却什么都没找到。\n   这里换成基于 LCS（最长公共子序列）的相似度：顺序不变、允许中间多字少字。 */\nfunction rcSimRate(a, b) {\n  const x = rcNormQ(a), y = rcNormQ(b);\n  if (!x || !y) return 0;\n  if (x === y) return 1;\n  const n = x.length, m = y.length;\n  if (!n || !m) return 0;\n  /* 长度差太大直接判不像，省掉一次 O(n*m) 的计算 */\n  if (Math.min(n, m) / Math.max(n, m) < 0.5) return 0;\n  if (n * m > 250000) {\n    /* 超长题干预算：按字符集合重合度的粗估 */\n    const set = {}; for (let i = 0; i < n; i++) set[x[i]] = 1;\n    let hit = 0; for (let i = 0; i < m; i++) if (set[y[i]]) hit++;\n    return hit / m * 0.9;\n  }\n  let prev = new Uint16Array(m + 1), cur = new Uint16Array(m + 1);\n  for (let i = 1; i <= n; i++) {\n    for (let j = 1; j <= m; j++) {\n      cur[j] = (x[i - 1] === y[j - 1]) ? (prev[j - 1] + 1) : (prev[j] > cur[j - 1] ? prev[j] : cur[j - 1]);\n    }\n    const t = prev; prev = cur; cur = t;\n    cur.fill(0);\n  }\n  const lcs = prev[m];\n  const lo = Math.min(n, m), hi = Math.max(n, m);\n  const byLong = lcs / hi;      // 长的这一头有多少字被对上（严格口径）\n  const byShort = lcs / lo;     // 短的那一头是不是被整句包住（同一题加了尾巴）\n  /* 双口径：短题被整句包住时按 byShort 加权 ——\n     以前只除以较长的那一侧，于是「四项基本原则」和「四项基本原则是什么？」\n     只有 0.67、「申请入党的基本条件」和「申请入党的基本条件是什么」只有 0.75，\n     明明是同一条题，却永远过不了 0.82 的线，扫半天什么都扫不出来。 */\n  const merged = (byShort >= 0.92) ? (byShort * 0.65 + byLong * 0.35) : byLong;\n  return Math.min(1, merged);\n}\n/* 判定阈值：默认 0.82 —— 比「完全相同」松得多，能抓出改标点、换说法、加几个字的重复，\n   又不会把只是同一个主题的题误判成重复。可在「背书设置」里调。 */\nfunction rcDupThres() { return clamp(Number(cfg('rcDupThres') != null ? cfg('rcDupThres') : 0.82) || 0.82, 0.5, 1); }\n/* 把相似度 ≥ 阈值的卡片聚成一组（每组内部两两都够像才算同一组，避免链式误并） */\nfunction rcDupGroups(bookId) {\n  const pool = (bookId ? rcCardsOf(bookId) : rcCards()).filter(c => rcNormQ(c.q).length >= 2);\n  const th = rcDupThres();\n  const used = {};\n  const groups = [];\n  for (let i = 0; i < pool.length; i++) {\n    const a = pool[i];\n    if (used[String(a.id)]) continue;\n    const group = [a];\n    for (let j = i + 1; j < pool.length; j++) {\n      const b = pool[j];\n      if (used[String(b.id)]) continue;\n      if (rcSimRate(a.q, b.q) >= th) { group.push(b); used[String(b.id)] = 1; }\n    }\n    if (group.length > 1) {\n      used[String(a.id)] = 1;\n      groups.push({\n        key: rcNormQ(a.q),\n        /* 组内按相似度贴到组长上：最像的排前面，方便你一眼看出哪几张几乎一样 */\n        cards: group.map(c => ({ c: c, sim: rcSimRate(a.q, c.q) }))\n          .sort((x, y) => y.sim - x.sim || (Number(y.c.level) || 0) - (Number(x.c.level) || 0))\n          .map(x => x.c),\n        sims: group.map(c => rcSimRate(a.q, c.q))\n      });\n    }\n  }\n  /* 组内先按「掌握最好」排，方便「每组只留最好的那张」 */\n  groups.forEach(g => g.cards.sort((a, b) => (Number(b.level) || 0) - (Number(a.level) || 0)));\n  return groups;\n}\nfunction rcDupSheet(groups, bookId) {\n  const total = groups.reduce((n, g) => n + g.cards.length, 0);\n  openSheet(`<h3>🧹 重复卡片（${groups.length} 组 / ${total} 张）</h3>\n    <div class=\"tiny\">同一题干的卡片重复进来了。下面每组都摆出全部内容，你决定留哪一张 —— 保留的那张会自动继承同组里最好的学习进度（等级、对错次数、易错词）。</div>\n    <button class=\"btn primary block mt10\" data-act=\"rcDupKeepBest\" data-id=\"${esc(bookId || '')}\">⚡ 每组只留掌握最好的那张（一次清完）</button>\n    <div class=\"mt10\">${groups.slice(0, 30).map((g, gi) => `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:9px\">\n      <div class=\"tiny\">第 ${gi + 1} 组 · ${g.cards.length} 张重复</div>\n      <div style=\"font-size:13px;line-height:1.6;margin-top:5px\">${esc(String(g.cards[0].q).slice(0, 90))}</div>\n      ${g.cards.map(c => `<div class=\"mt8\" style=\"border-top:1px solid rgba(255,255,255,.08);padding-top:8px\">\n        <div class=\"tiny\">${esc(rcLvName(c.level))} · 错 ${Number(c.wrongN || 0)} · 对 ${Number(c.rightN || 0)} · 优先级 ${esc(rcPriName(rcPriOf(c)))} · ${dkey(new Date(c.at))}</div>\n        <div class=\"tiny mt6\" style=\"line-height:1.65;color:var(--dim)\">答：${esc(String(c.a || '（无答案）').replace(/\\n/g, ' ').slice(0, 120))}</div>\n        <div class=\"row mt6\" style=\"gap:6px\">\n          <button class=\"btn sm ghost grow\" data-act=\"rcCardEdit\" data-id=\"${esc(c.id)}\">看这张</button>\n          <button class=\"btn sm primary\" data-act=\"rcDupKeep\" data-id=\"${esc(c.id)}\" data-ids=\"${esc(g.cards.map(x => x.id).join(','))}\">留这张，删其余 ${g.cards.length - 1} 张</button>\n        </div></div>`).join('')}\n    </div>`).join('')}</div>\n    <div class=\"hr\"></div>\n    <div class=\"tiny\">判定阈值：<b>${rcDupThres()}</b> —— 越高要求越像，越低抓得越松（当下这次扫描用的就是这个值）。</div>\n    <button class=\"btn block ghost sm mt6\" data-act=\"rcDupThresAsk\">⚙️ 调整阈值</button>\n    <button class=\"btn block ghost sm mt8\" data-act=\"closeSheet\">关闭</button>`);\n}\n/* 阈值就地调整：改完立刻用新值重扫，不用退出面板再点一遍 */\nasync function rcDupThresDo(v) {\n  const nv = clamp(Math.round(Number(v) * 100) / 100, 0.5, 1);\n  if (!nv) { toast('请填 0.5 ~ 1 之间的数'); return; }\n  S.settings.rcDupThres = nv;\n  await saveSettings(true);\n  closeAllSheets();\n  const bid = S.draft.rcBookId || '';\n  const groups = rcDupGroups(bid);\n  toast('阈值已设为 ' + nv + (groups.length ? '：扫出 ' + groups.length + ' 组重复' : '：暂时没扫出重复'));\n  if (groups.length) rcDupSheet(groups, bid); else render();\n}\n/* 挑选模式里当前勾中的卡片 id */\nfunction rcSelIds() {\n  const sel = S.draft.rcSelSel || {};\n  return Object.keys(sel).filter(k => sel[k]);\n}\n/* 挑一个目标词本（移动 / 复制都能用，支持一次处理多张） */\nfunction rcPickBooksThen(ids, copy) {\n  const list = (ids || []).map(rcCardById).filter(Boolean);\n  if (!list.length) { toast('卡片不在了'); return; }\n  const fromIds = {};\n  list.forEach(c => { fromIds[String(c.bookId)] = 1; });\n  const books = rcActiveBooks().concat(rcArchivedBooks());\n  if (!books.length) { toast('还没有词本'); return; }\n  closeAllSheets();\n  openSheet(`<h3>${copy ? '复制' : '移动'} ${list.length} 张卡片</h3>\n    <div class=\"tiny\" style=\"line-height:1.8\">${copy\n      ? '复制会在目标词本里新建同样的卡片（题干 / 答案 / 关键词 / 笔记 / 易错词 / 优先级都带过去），<b>学习等级和错误次数不跟着走</b> —— 到新词本是新的一张。原卡保留。'\n      : '移动会把原卡从它现在的词本挪到目标词本，<b>等级和错误次数都跟着走</b>。'}</div>\n    <div class=\"mt10\">${books.map(b => {\n      const isSame = list.every(c => String(c.bookId) === String(b.id));\n      return `<div class=\"item\" ${isSame ? '' : `data-act=\"rcPickBooksDo\" data-id=\"${esc(b.id)}\" data-copy=\"${copy ? '1' : '0'}\" data-ids=\"${esc(list.map(c => c.id).join(','))}\"`} style=\"${isSame ? 'opacity:.45' : 'cursor:pointer'}\">\n      <div class=\"ic\">📖</div>\n      <div class=\"grow\"><div style=\"font-size:13px\">${esc(b.name)}${b.archived ? ' <span class=\"tiny\">（已归档）</span>' : ''}</div>\n      <div class=\"tiny\">${rcCardN(b.id)} 张卡片${isSame ? ' · 已经在这些卡所在的词本' : ''}</div></div>\n      <div class=\"ic\">${isSame ? '' : '›'}</div></div>`;\n    }).join('')}</div>\n    <button class=\"btn block ghost sm mt10\" data-act=\"closeSheet\">取消</button>`);\n}\nObject.assign(ACTIONS, {\n  /* ---- 易错词：从默写记录里收进来 / 去掉 ---- */\n  /* 刷新表单前先把当前输入框里的字收进卡片 ——\n     不然你刚改了一半的题干/答案会被重建的表单冲掉。 */\n  rcCaptureEditFields: () => {\n    const cur = (S.recite && rcCurCard()) || null;\n    const id = S.draft.rcEditId || (S.draft.rcCardAi && S.draft.rcCardAi.id) || (cur && cur.id) || '';\n    const c = id ? rcCardById(id) : null;\n    if (!c) return null;\n    const q = document.getElementById('rcQ'), a = document.getElementById('rcA'), h = document.getElementById('rcH');\n    if (q) { const v = (q.value || '').trim(); if (v) c.q = v; }\n    if (a) c.a = (a.value || '').trim();\n    if (h) c.hint = (h.value || '').trim();\n    const nt = document.getElementById('rcNote');\n    if (nt) c.note = (nt.value || '').trim();\n    return c;\n  },\n  rcAddTricky: async el => {\n    const c = rcCardById(el.dataset.id) || ACTIONS.rcCaptureEditFields();\n    if (!c) return;\n    const k = String(el.dataset.k || '').trim();\n    if (!k) return;\n    const cur = (c.tricky || []).slice();\n    if (cur.indexOf(k) >= 0) { toast('已经在易错词里了'); return; }\n    cur.push(k);\n    c.tricky = cur;\n    await rcSaveCard(c);\n    toast('已收进易错词：' + k);\n    rcOpenCardEdit(c);\n  },\n  rcUnTricky: async el => {\n    const c = rcCardById(el.dataset.id) || ACTIONS.rcCaptureEditFields();\n    if (!c) return;\n    c.tricky = (c.tricky || []).filter(x => String(x) !== String(el.dataset.k));\n    await rcSaveCard(c);\n    rcOpenCardEdit(c);\n  },\n  /* ---- 优先级 ---- */\n  rcCardSetPri: async el => {\n    const c = rcCardById(el.dataset.id) || ACTIONS.rcCaptureEditFields();\n    if (!c) return;\n    c.pri = clamp(Number(el.dataset.k) || 0, 0, 2);\n    await rcSaveCard(c);\n    toast('已设为「' + rcPriName(c.pri) + '」');\n    rcOpenCardEdit(c);\n  },\n  /* ---- 移动 / 复制到别的词本 ---- */\n  rcCardMoveAsk: el => rcPickBooksThen([el.dataset.id], false),\n  rcCardCopyAsk: el => rcPickBooksThen([el.dataset.id], true),\n  rcPickBooksDo: async el => {\n    const ids = String(el.dataset.ids || '').split(',').filter(Boolean);\n    const tb = rcBookById(el.dataset.id);\n    if (!tb || !ids.length) { toast('卡片或词本不在了'); return; }\n    const copy = el.dataset.copy === '1';\n    let n = 0;\n    for (const id of ids) {\n      const c = rcCardById(id);\n      if (!c) continue;\n      if (copy) {\n        const nc = rcNewCard(tb.id, c.q, c.a, c.hint);\n        nc.note = c.note || '';\n        nc.pri = rcPriOf(c);\n        if ((c.tricky || []).length) nc.tricky = c.tricky.slice();\n        await rcSaveCard(nc);\n      } else {\n        c.bookId = String(tb.id);\n        c.order = rcCardsOf(tb.id).length;\n        await rcSaveCard(c);\n      }\n      n++;\n    }\n    closeAllSheets();\n    toast('已' + (copy ? '复制' : '移动') + ' ' + n + ' 张到「' + tb.name + '」');\n    /* 移走 / 复制完就把挑选状态收掉：原卡已经不在这个词本里了，\n       留着勾选只会让人以为「刚才那一下没执行」。 */\n    if (S.draft.rcSelMode) { S.draft.rcSelSel = {}; S.draft.rcSelMode = false; }\n    render();\n  },\n  /* ---- 词本 ---- */\n  rcNewBook: () => {\n    openSheet(`<h3>新建词本</h3>\n      <div class=\"tiny\">按科目或用途分，比如「专业课」「公考」「英语单词」。</div>\n      <label class=\"fl\">词本名称</label>\n      <input class=\"input\" id=\"rcBookName\" placeholder=\"例如：专业课名词解释\">\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"rcNewBookSave\">创建</button></div>`);\n  },\n  rcNewBookSave: async () => {\n    const n = ((document.getElementById('rcBookName') || {}).value || '').trim();\n    if (!n) { toast('请填一个词本名称'); return; }\n    const b = { name: n.slice(0, 24), at: Date.now(), archived: false };\n    const saved = await rcSaveBook(b);\n    closeAllSheets();\n    if (!saved || !saved.id) { toast('词本没存进本机数据库 —— 请把这句话发给小坊'); return; }\n    toast('已创建：' + b.name);\n    if (S.view === 'rcbook' || S.view === 'rcimport') go('rcbooks'); else render();\n  },\n  rcOpenBook: el => { S.draft.rcBookId = el.dataset.id; go('rcbook'); },\n  rcBookMenu: el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    const rc = rcCardN(b.id);\n    openSheet(`<h3>${esc(b.name)}</h3>\n      <div class=\"tiny\">${rc} 张卡片 · 熟练以上 ${rcMasteredN(b.id)} · 薄弱 ${rcWeakCards(b.id).length}</div>\n      <label class=\"fl\">改个名字</label>\n      <input class=\"input\" id=\"rcBookRename\" value=\"${esc(b.name)}\">\n      <button class=\"btn primary block mt10\" data-act=\"rcRenameSave\" data-id=\"${esc(b.id)}\">保存名称</button>\n      <div class=\"hr\"></div>\n      <button class=\"btn block ghost\" data-act=\"rcArchive\" data-id=\"${esc(b.id)}\">📦 归档（不删数据，只是不占首页）</button>\n      <button class=\"btn block ghost mt8\" data-act=\"rcExportOpen\" data-id=\"${esc(b.id)}\">📤 导出这个词本</button>\n      <button class=\"btn block mt8\" style=\"color:#ff9aa6\" data-act=\"rcDelBookAsk\" data-id=\"${esc(b.id)}\">删除词本</button>\n      <button class=\"btn block ghost sm mt10\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  rcRenameSave: async el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    const n = ((document.getElementById('rcBookRename') || {}).value || '').trim();\n    if (!n) { toast('名字不能空'); return; }\n    b.name = n.slice(0, 24);\n    await rcSaveBook(b);\n    closeAllSheets(); toast('已改名：' + b.name); render();\n  },\n  rcArchive: async el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    b.archived = true;\n    await rcSaveBook(b);\n    closeAllSheets(); toast('已归档：' + b.name + '（数据都还在）');\n    S.draft.rcBookId = '';\n    go('rcbooks');\n  },\n  rcUnarchive: async el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    b.archived = false;\n    await rcSaveBook(b);\n    toast('已取消归档：' + b.name); render();\n  },\n  rcDelBookAsk: async el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    const n = rcCardN(b.id);\n    const ok = await confirmBox('删除词本「' + b.name + '」？',\n      (n ? '它下面的 ' + n + ' 张卡片会一起删掉，' : '') + '删掉后不可恢复。\\n如果只是暂时不用，建议改成「归档」。', '确认删除');\n    if (!ok) return;\n    const cnt = await rcDelBook(b);\n    closeAllSheets();\n    toast('已删除「' + b.name + '」' + (cnt ? '（含 ' + cnt + ' 张卡片）' : ''));\n    S.draft.rcBookId = '';\n    go('rcbooks');\n  },\n  /* ---- 卡片 ---- */\n  rcCardNew: el => {\n    const bid = el.dataset.id || S.draft.rcBookId;\n    if (!bid) { toast('先选一个词本'); return; }\n    openSheet(`<h3>新建卡片</h3>\n      <div class=\"tiny\">名词解释、简答、单词都能放。答案是完整内容，提示关键词可留空（默写判分会用到）。</div>\n      <label class=\"fl\">题干</label>\n      <textarea id=\"rcQ\" style=\"min-height:70px\" placeholder=\"例如：什么是边际效用？\"></textarea>\n      <label class=\"fl\">完整答案</label>\n      <textarea id=\"rcA\" style=\"min-height:110px\" placeholder=\"完整写下来，不要只写关键词\"></textarea>\n      <label class=\"fl\">提示关键词（可留空，逗号分隔）</label>\n      <input class=\"input\" id=\"rcH\" placeholder=\"例如：边际、额外、满足感\">\n      <div class=\"row mt12\" style=\"gap:8px\">\n        <button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"rcCardSave\" data-book=\"${esc(bid)}\">保存</button></div>`);\n  },\n  rcCardEdit: el => { rcOpenCardEdit(rcCardById(el.dataset.id)); },\n  /* 背诵中就地改这张卡片：不用退出这一轮，改完接着背 */\n  rcEditCur: () => { const c = rcCurCard(); if (!c) { toast('当前没有卡片'); return; } rcOpenCardEdit(c); },\n  rcCardSave: async el => {\n    const q = ((document.getElementById('rcQ') || {}).value || '').trim();\n    const a = ((document.getElementById('rcA') || {}).value || '').trim();\n    const h = ((document.getElementById('rcH') || {}).value || '').trim();\n    const nt = ((document.getElementById('rcNote') || {}).value || '').trim();\n    const tgRaw = ((document.getElementById('rcTags') || {}).value || '').trim();\n    if (!q) { toast('题干不能空'); return; }\n    const tags = rcTagList(tgRaw);\n    let c = el.dataset.id ? rcCardById(el.dataset.id) : null;\n    if (c) { c.q = q; c.a = a; c.hint = h; c.note = nt; c.tags = tags; }\n    else { c = rcNewCard(el.dataset.book || S.draft.rcBookId, q, a, h); c.note = nt; c.tags = tags; }\n    await rcSaveCard(c);\n    closeAllSheets(); toast(el.dataset.id ? '已保存' : '已加进词本'); render();\n  },\n  rcCardDel: async el => {\n    const c = rcCardById(el.dataset.id);\n    if (!c) return;\n    const ok = await confirmBox('删掉这张卡片？', String(c.q).slice(0, 60), '删除');\n    if (!ok) return;\n    await rcDelCard(c);\n    toast('已删除'); render();\n  },\n  rcCardReset: async el => {\n    const c = rcCardById(el.dataset.id);\n    if (!c) return;\n    c.level = 0; c.wrongN = 0; c.rightN = 0; c.streak = 0; c.paused = false;\n    await rcSaveCard(c);\n    toast('已重置为「不会」'); render();\n  },\n  /* ==========================================================\n     卡片上的 AI：统一入口（生成 → 留存 → 再看 → 重生成 → 编辑）\n     ----------------------------------------------------------\n     ⚠️ 以前是「每点一次都重新问一遍 API」，结果只放在一个临时变量里，\n     关掉表单就没了；而且详解、口诀会直接往「答案」栏里塞 ——\n     弄脏了你要背的标准答案，也看不出哪份是 AI 写的。\n     现在全部改成：结果写进卡片自己的 ai 字段，生成过就留着。\n     ========================================================== */\n  rcCardAiGen: async el => {\n    const c = rcCardById(el.dataset.id); if (!c) return;\n    const k = String(el.dataset.k || '');\n    if (!k) return;\n    const already = rcCardAiGet(c, k);\n    if (already) {\n      const ok = await confirmBox('重新生成「' + ((RC_AI_KINDS[k] || {}).n || k) + '」？',\n        '上次生成于 ' + dkey(new Date(already.at)) + ' ' + hm(already.at) + '。\\n重新生成会覆盖它（会消耗一次 API）。', '重新生成');\n      if (!ok) { S.draft.rcAiOpenKind = k; rcOpenCardEdit(c); return; }\n    }\n    const q = ((document.getElementById('rcQ') || {}).value || c.q || '').trim();\n    const a = ((document.getElementById('rcA') || {}).value || c.a || '').trim();\n    const h = ((document.getElementById('rcH') || {}).value || c.hint || '').trim();\n    if (k === 'keys' && !a) { toast('先写下答案，再提关键词'); return; }\n    if (k !== 'keys' && !a) { toast('这张卡片还没有答案，AI 没有可依据的内容'); return; }\n    S.loading = (k === 'keys') ? 'rckey' : 'rcedit';\n    rcOpenCardEdit(c);\n    let out = '';\n    try {\n      if (k === 'keys') out = await rcAiKeywords({ q: q, a: a, hint: h });\n      else if (k === 'compress') out = await rcAiRewrite('compress', { q: q, a: a });\n      else if (k === 'expand') out = await rcAiRewrite('expand', { q: q, a: a });\n      else if (k === 'mnemonic') out = await rcAiRewrite('mnemonic', { q: q, a: a });\n    } finally { S.loading = ''; }\n    if (!out) { toast('AI 没给出内容 —— 可以再点一次，或直接用卡片里的提示关键词'); rcOpenCardEdit(c); return; }\n    await rcCardAiPut(c, k, out);\n    S.draft.rcAiOpenKind = k;\n    toast('已生成并留在卡片里（可随时编辑）');\n    rcOpenCardEdit(c);\n  },\n  /* 改动某条 AI 内容 —— 直接落库，不必再走「保存卡片」 */\n  rcCardAiSaveEdit: async el => {\n    const c = rcCardById(el.dataset.id); if (!c) return;\n    const k = String(el.dataset.k || '');\n    const box = document.querySelector('[data-in=\"rcAiEdit.' + k + '\"]');\n    const v = box ? (box.value || '').trim() : '';\n    if (!k) return;\n    if (!v) { toast('内容空了；要删就点旁边的「删」'); return; }\n    await rcCardAiPut(c, k, v);\n    toast('已保存「' + ((RC_AI_KINDS[k] || {}).n || k) + '」');\n    rcOpenCardEdit(c);\n  },\n  rcCardAiDrop: async el => {\n    const c = rcCardById(el.dataset.id); if (!c) return;\n    const k = String(el.dataset.k || '');\n    const ok = await confirmBox('删掉这条 AI 内容？', '「' + ((RC_AI_KINDS[k] || {}).n || k) + '」会从这张卡片上移除，删掉后可以再生成。', '删掉');\n    if (!ok) return;\n    await rcCardAiDel(c, k);\n    toast('已删掉');\n    rcOpenCardEdit(c);\n  },\n  /* 「填入」只给关键词和背诵版这两个真要替换的 —— 其余只读留存，避免弄脏答案 */\n  rcCardAiFill: el => {\n    const c = rcCardById(el.dataset.id); if (!c) return;\n    const k = String(el.dataset.k || '');\n    const it = rcCardAiGet(c, k);\n    if (!it || !it.text) { toast('这条还没生成'); return; }\n    const t = document.getElementById(k === 'keys' ? 'rcH' : 'rcA');\n    if (t) t.value = it.text;\n    toast(k === 'keys' ? '已填进关键词栏，记得点「保存」' : '已填进答案栏，记得点「保存」');\n  },\n  rcCardAiCopyText: async el => {\n    const c = rcCardById(el.dataset.id); if (!c) return;\n    const it = rcCardAiGet(c, String(el.dataset.k || ''));\n    if (!it) { toast('这条还没生成'); return; }\n    try { await navigator.clipboard.writeText(String(it.text || '')); toast('已复制'); }\n    catch (e) { toast('浏览器不给复制，可以长按选择文本'); }\n  },\n  /* 旧按钮名保留，防止旧面板残留调用落空 —— 一律转到新入口 */\n  rcCardAiKey: el => ACTIONS.rcCardAiGen({ dataset: { id: el.dataset.id, k: 'keys' } }),\n  rcCardAiCompress: el => ACTIONS.rcCardAiGen({ dataset: { id: el.dataset.id, k: 'compress' } }),\n  rcCardAiExpand: el => ACTIONS.rcCardAiGen({ dataset: { id: el.dataset.id, k: 'expand' } }),\n  rcCardAiMnemonic: el => ACTIONS.rcCardAiGen({ dataset: { id: el.dataset.id, k: 'mnemonic' } }),\n  rcCardAiClose: el => { const id = el && el.dataset && el.dataset.id; if (id) rcOpenCardEdit(rcCardById(id)); else render(); },\n  rcCardAiUse: () => { toast('AI 生成的内容现在直接留在卡片里了，不用再手动填'); },\n  rcCardAiCopy: () => { toast('请在对应的 AI 内容上点「复制」'); },\n  /* ---- 批量导入 ---- */\n  rcImportOpen: el => { S.draft.rcBookId = el.dataset.id || S.draft.rcBookId; S.draft.rcImportPreview = null; go('rcimport'); },\n  rcImportClear: () => { S.draft.rcImportText = ''; S.draft.rcImportPreview = null; S.draft.rcImportFromAI = false; render(); },\n  /* AI 拆题：把整段材料交给模型切成卡片，结果同样先落到预览里 ——\n     和手动解析走同一个预览、同一个入库按钮，绝不直接写库。 */\n  rcImportAi: async () => {\n    const box = document.getElementById('rcImportBox');\n    const v = box ? (box.value || '') : String(S.draft.rcImportText || '');\n    S.draft.rcImportText = v;\n    if (!v.trim()) { toast('先把材料粘进去'); return; }\n    const list = await rcAiGenCards(v, '知识点卡片');\n    if (!list || !list.length) return;\n    /* 去重、过滤空卡、限 200 —— 和手动解析同一套规矩，别因为来源不同就放宽 */\n    const exist = {};\n    rcCardsOf(S.draft.rcBookId).forEach(c => { exist[rcNormQ(c.q)] = 1; });\n    const clean = [], seen = {};\n    let dup = 0;\n    list.forEach(x => {\n      const q = rcStripNo(x.q);\n      if (!q) return;\n      const k = rcNormQ(q);\n      if (!k || seen[k] || exist[k]) { dup++; return; }\n      seen[k] = 1;\n      clean.push({ q: q, a: x.a || '', hint: x.hint || '' });\n    });\n    if (!clean.length) { toast('AI 拆出来的卡片都和现有的重复了，换个说法再试'); return; }\n    S.draft.rcImportPreview = { list: clean.slice(0, 200), dup: dup, total: clean.length, cut: Math.max(0, clean.length - 200) };\n    S.draft.rcImportFromAI = true;\n    render();\n    toast('AI 拆出 ' + clean.length + ' 张 —— 确认无误再入库');\n  },\n  rcImportParse: () => {\n    const v = ((document.getElementById('rcImportBox') || {}).value || '');\n    S.draft.rcImportText = v;\n    if (!v.trim()) { toast('先粘一段材料进来'); return; }\n    const r = rcParseImport(v);\n    if (!r.list.length) { toast('没能解析出卡片：检查一下格式，或用【题干】…【答案】…的写法'); return; }\n    S.draft.rcImportPreview = r;\n    S.draft.rcImportFromAI = false;\n    toast('解析出 ' + r.list.length + ' 条');\n    render();\n  },\n  /* 预览里删掉一条 */\n  rcPreviewDel: el => {\n    const pv = S.draft.rcImportPreview;\n    if (!pv) return;\n    pv.list.splice(Number(el.dataset.i), 1);\n    render();\n  },\n  rcImportSave: async () => {\n    const pv = S.draft.rcImportPreview;\n    const bid = S.draft.rcBookId;\n    if (!pv || !pv.list.length || !bid) { toast('没有可导入的内容'); return; }\n    /* 预览里被改空的题干直接跳过（改的时候可能把整条清掉了） */\n    pv.list = pv.list.filter(x => String(x.q || '').trim() !== '');\n    if (!pv.list.length) { toast('没有可导入的内容了'); render(); return; }\n    const exist = {};\n    rcCardsOf(bid).forEach(c => { exist[rcNormQ(c.q)] = 1; });\n    let added = 0, skip = 0, base = rcCardsOf(bid).length;\n    for (const it of pv.list) {\n      const k = rcNormQ(it.q);\n      if (exist[k]) { skip++; continue; }\n      exist[k] = 1;\n      const c = rcNewCard(bid, it.q, it.a, it.hint);\n      c.order = base + added;\n      await rcSaveCard(c);\n      added++;\n    }\n    /* 记一笔流水（新增卡片数），统计面板会用到 */\n    if (added) await rcLogAdd({ date: dkey(), at: Date.now(), bookId: bid, newN: added });\n    S.draft.rcImportPreview = null;\n    S.draft.rcImportText = '';\n    toast('已导入 ' + added + ' 张' + (skip ? '（跳过 ' + skip + ' 张题干重复）' : ''));\n    go('rcbook');\n  },\n  /* ---- 导出 ---- */\n  rcExportOpen: el => {\n    const b = rcBookById(el.dataset.id || S.draft.rcBookId);\n    if (!b) { toast('先选一个词本'); return; }\n    const n = rcCardN(b.id);\n    if (!n) { toast('这个词本还没有卡片'); return; }\n    openSheet(`<h3>导出「${esc(b.name)}」（${n} 张）</h3>\n      <div class=\"tiny\">三种格式，导出的文件会下载到本机。</div>\n      <button class=\"btn primary block mt10\" data-act=\"rcExportDo\" data-f=\"bak\" data-id=\"${esc(b.id)}\">🗄 内部备份（含全部学习数据，可完整还原）</button>\n      <button class=\"btn block mt8\" data-act=\"rcExportDo\" data-f=\"md\" data-id=\"${esc(b.id)}\">📝 Markdown（方便电脑笔记软件打开）</button>\n      <button class=\"btn block mt8\" data-act=\"rcExportDo\" data-f=\"txt\" data-id=\"${esc(b.id)}\">📄 TXT 纯文本（题干+答案，适合打印）</button>\n      <div class=\"tiny mt10\" style=\"line-height:1.75\">Markdown / TXT 只导出题干与答案；只有<b>内部备份</b>带记忆等级、错误次数等学习数据，之后可以完整还原。</div>\n      <button class=\"btn block ghost sm mt10\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  rcExportDo: async el => {\n    const b = rcBookById(el.dataset.id);\n    if (!b) return;\n    const cards = rcCardsOf(b.id);\n    const f = el.dataset.f;\n    const safe = String(b.name).replace(/[\\\\/:*?\"<>|]/g, '_').slice(0, 20);\n    let txt = '', name = '';\n    if (f === 'bak') {\n      txt = JSON.stringify({\n        kind: 'rc-book-backup', v: 1, at: Date.now(),\n        book: { name: b.name, at: b.at },\n        cards: cards.map(c => ({ q: c.q, a: c.a, hint: c.hint, level: c.level, wrongN: c.wrongN, rightN: c.rightN, streak: c.streak, paused: !!c.paused, lastAt: c.lastAt, order: c.order }))\n      });\n      name = safe + '.rcbak';\n    } else if (f === 'md') {\n      txt = '# ' + b.name + '\\n\\n导出 ' + dkey() + ' · 共 ' + cards.length + ' 张\\n\\n' +\n        cards.map((c, i) => '### ' + (i + 1) + '. ' + c.q + '\\n\\n' + (c.a || '（无答案）') + '\\n\\n---\\n').join('\\n');\n      name = safe + '.md';\n    } else {\n      txt = '【' + b.name + '】共 ' + cards.length + ' 张 · ' + dkey() + '\\n\\n' +\n        cards.map((c, i) => (i + 1) + '. ' + c.q + '\\n答：' + (c.a || '').replace(/\\n/g, ' ') + '\\n').join('\\n');\n      name = safe + '.txt';\n    }\n    const ok = blobDownload(name, txt, 'text/plain;charset=utf-8');\n    if (ok) { closeAllSheets(); toast('已导出：' + name); }\n    else openSheet(`<h3>导出被拦截</h3><div class=\"tiny\">把下面内容全选复制，自己存成文件也可以。</div>\n      <textarea style=\"min-height:170px;margin-top:10px\">${esc(txt)}</textarea>\n      <button class=\"btn primary block mt10\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  rcSearchClear: () => { S.draft.rcSearch = ''; render(); },\n  /* 按标签 / 优先级 / 等级 / 热力筛选（点同一个再点一次就取消） */\n  rcFilterSet: el => {\n    const v = String(el.dataset.v || '');\n    S.draft.rcFilter = (String(S.draft.rcFilter || '') === v) ? '' : v;\n    render();\n  },\n  /* 筛选改成弹出列表：一行一个条件，带各自的卡片数 —— 不再挤在页面上一长排 */\n  rcFilterOpen: () => {\n    const b = rcBookById(S.draft.rcBookId);\n    const allCards = b ? rcCardsOf(b.id) : rcCards();\n    const filter = String(S.draft.rcFilter || '');\n    const tagStat = {};\n    allCards.forEach(c => rcTagsOf(c).forEach(t => { tagStat[t] = (tagStat[t] || 0) + 1; }));\n    const tagNames = Object.keys(tagStat).sort((x, y) => tagStat[y] - tagStat[x]);\n    const hotN = allCards.filter(c => { const h = rcHeat(c); return h && h.k === 'hot'; }).length;\n    const row = (v, label, n) => `<div class=\"item\" data-act=\"rcFilterPick\" data-v=\"${esc(v)}\" style=\"cursor:pointer;padding:9px 0\">\n      <div class=\"ic\">${filter === v ? '✅' : '⬜'}</div>\n      <div class=\"grow\"><div style=\"font-size:13.2px\">${label}</div></div>\n      <span class=\"tiny\">${n} 张</span></div>`;\n    openSheet(`<h3>🔎 筛选卡片</h3>\n      <div class=\"tiny\">选一个条件，词本里就只剩这些卡片。再点一次取消。</div>\n      <div class=\"mt8\">${row('', '全部卡片', allCards.length)}</div>\n      <div class=\"tiny mt10\" style=\"color:var(--dim2)\">按优先级</div>\n      ${RC_PRI.map(p => row('pri:' + p.k, p.emoji + ' ' + p.n, allCards.filter(c => rcPriOf(c) === p.k).length)).join('')}\n      <div class=\"tiny mt10\" style=\"color:var(--dim2)\">按掌握等级</div>\n      ${RC_LV.slice().reverse().map(l => row('lv:' + l.k, '<span style=\"color:' + l.color + '\">' + l.n + '</span>', allCards.filter(c => Number(c.level || 0) === l.k).length)).join('')}\n      ${hotN ? `<div class=\"tiny mt10\" style=\"color:var(--dim2)\">薄弱</div>${row('heat:hot', '🔴 高频易错（错 ≥3 次）', hotN)}` : ''}\n      ${tagNames.length ? `<div class=\"tiny mt10\" style=\"color:var(--dim2)\">按标签</div>\n        ${tagNames.map(t => row('tag:' + t, '#' + esc(t), tagStat[t])).join('')}` : `<div class=\"tiny mt10\" style=\"color:var(--dim2)\">还没有标签 —— 点卡片「编辑」，在「标签」栏里写上，这里就会列出来。</div>`}\n      <button class=\"btn block ghost sm mt12\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  rcFilterPick: el => {\n    S.draft.rcFilter = String(el.dataset.v || '');\n    closeAllSheets();\n    render();\n  },\n  rcFilterClear: () => { S.draft.rcFilter = ''; S.draft.rcSearch = ''; render(); },\n  /* 只背当前筛出来的这批 —— 筛完了点开始却背整个词本，那就等于筛选白做 */\n  rcStartList: el => {\n    const ids = String(el.dataset.ids || '').split(',').filter(Boolean);\n    const cards = ids.map(rcCardById).filter(Boolean);\n    if (!cards.length) { toast('这些卡片已经不在了'); return; }\n    if (S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) {\n      toast('你还有一轮没背完 —— 先「继续」，或点「结束并记账」把它结掉');\n      return;\n    }\n    rcApplyDefaults();\n    S.recite = {\n      scope: 'pick', bookId: S.draft.rcBookId || '', queue: cards.map(c => c.id), idx: 0,\n      flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n      done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n      newN: 0, weakBefore: rcWeakCards(S.draft.rcBookId).length,\n      startedAt: Date.now(), touched: {}, log: []\n    };\n    toast('只背筛出的 ' + cards.length + ' 张');\n    go('rcsession');\n  },\n  /* ---- 重复卡片：同一题干的多张找出来，让你自己决定留哪一张 ---- */\n  rcDupThresAsk: () => {\n    openSheet(`<h3>⚙️ 重复判定阈值</h3>\n      <div class=\"tiny\" style=\"line-height:1.85\">题干相似度到这个值就算「重复」。<br>\n      · <b>0.95 以上</b>：只抓几乎一字不差的；<br>\n      · <b>0.82（默认）</b>：改标点、换几个字、多写少写一句都能抓到；<br>\n      · <b>0.7 左右</b>：抓得最狠，会多报一些，但基本不会漏。</div>\n      <label class=\"fl\">阈值（0.5 ~ 1）</label>\n      <input class=\"input\" type=\"number\" inputmode=\"decimal\" step=\"0.05\" min=\"0.5\" max=\"1\" id=\"rcDupThBox\" value=\"${rcDupThres()}\">\n      <div class=\"row mt10\" style=\"gap:6px\">\n        <button class=\"btn sm ghost grow\" data-act=\"rcDupThresPick\" data-v=\"0.95\">0.95</button>\n        <button class=\"btn sm ghost grow\" data-act=\"rcDupThresPick\" data-v=\"0.82\">0.82 默认</button>\n        <button class=\"btn sm ghost grow\" data-act=\"rcDupThresPick\" data-v=\"0.72\">0.72 抓狠一点</button>\n      </div>\n      <div class=\"row mt12\" style=\"gap:8px\">\n        <button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"rcDupThresSave\">保存并重扫</button></div>`);\n  },\n  rcDupThresPick: el => { const b = document.getElementById('rcDupThBox'); if (b) b.value = el.dataset.v; },\n  rcDupThresSave: async () => {\n    const v = (document.getElementById('rcDupThBox') || {}).value;\n    await rcDupThresDo(v);\n  },\n  rcDupThresSheet: () => { ACTIONS.rcDupThresAsk(); },\n  rcDupScan: el => {\n    const bid = el.dataset.id || S.draft.rcBookId;\n    const groups = rcDupGroups(bid);\n    if (!groups.length) {\n      /* 真的没扫出重复时，不再只丢一句「没有重复卡片」就完事 ——\n         把「扫了多少张、阈值是多少、下一步怎么调」摆在明面上，\n         免得你分不清到底是「没有重复」还是「算法没生效」。 */\n      const pool = (bid ? rcCardsOf(bid) : rcCards()).filter(c => rcNormQ(c.q).length >= 2);\n      const th = rcDupThres();\n      openSheet(`<h3>🧹 这次没扫出重复</h3>\n        <div class=\"tiny\" style=\"line-height:1.85\">\n        扫了 <b>${pool.length}</b> 张卡片（题干太短、去标点后不到 2 个字的会自动跳过）。<br>\n        当前判定阈值：<b>${th}</b> —— 越高要求越像，0.95 以上基本只抓「一字不差」，越低抓得越松。</div>\n        ${pool.length < 2 ? '<div class=\"tiny mt8\" style=\"color:var(--gold)\">这个范围里的卡片不到 2 张，没得比。</div>' : ''}\n        <div class=\"row mt12\" style=\"gap:8px\">\n          <button class=\"btn primary grow\" data-act=\"rcDupLower\" data-id=\"${esc(bid || '')}\">调松到 0.72 再扫一次</button>\n          <button class=\"btn ghost\" data-act=\"closeSheet\">关闭</button></div>\n        <div class=\"tiny mt10\" style=\"color:var(--dim2)\">如果调松之后还是空的、但你手上明明有重复的题：把那一对的题干发给小坊，我照着实际字面对一遍算法，不再靠猜。</div>`);\n      return;\n    }\n    rcDupSheet(groups, bid);\n  },\n  /* 调松阈值后当场重扫 —— 不用跑去设置页改完再回来点一遍 */\n  rcDupLower: async el => {\n    const bid = el && el.dataset ? (el.dataset.id || '') : '';\n    S.settings.rcDupThres = 0.72;\n    await saveSettings(true);\n    closeAllSheets();\n    const groups = rcDupGroups(bid || S.draft.rcBookId);\n    if (!groups.length) { toast('0.72 也没扫出重复 —— 这些卡片的字面确实不太像'); return; }\n    toast('调松后扫出 ' + groups.length + ' 组');\n    rcDupSheet(groups, bid || S.draft.rcBookId);\n  },\n  /* 保留这一张，把同组其余的删掉 */\n  rcDupKeep: async el => {\n    const keepId = String(el.dataset.id || '');\n    const ids = String(el.dataset.ids || '').split(',').filter(Boolean);\n    const c = rcCardById(keepId);\n    if (!c) { toast('这张卡片已经不在了'); return; }\n    const others = ids.map(rcCardById).filter(x => x && String(x.id) !== keepId);\n    if (!others.length) { toast('这一组没有别的卡片了'); return; }\n    const ok = await confirmBox('只留这一张？',\n      '保留：「' + String(c.q).slice(0, 60) + '」\\n\\n会删掉同组的另外 ' + others.length + ' 张（连它们的学习记录一起）。',\n      '保留这张，删掉其它 ' + others.length + ' 张');\n    if (!ok) return;\n    /* 保留的那张尽量继承同组里最好的学习状态，别把熟练度白丢了 */\n    let lv = Number(c.level) || 0, wn = Number(c.wrongN) || 0, rn = Number(c.rightN) || 0, st = Number(c.streak) || 0;\n    others.forEach(o => {\n      lv = Math.max(lv, Number(o.level) || 0);\n      wn = Math.max(wn, Number(o.wrongN) || 0);\n      rn = Math.max(rn, Number(o.rightN) || 0);\n      st = Math.max(st, Number(o.streak) || 0);\n    });\n    const tricky = {};\n    [c].concat(others).forEach(o => (o.tricky || []).forEach(k => { tricky[k] = 1; }));\n    c.level = lv; c.wrongN = wn; c.rightN = rn; c.streak = st;\n    c.tricky = Object.keys(tricky);\n    await rcSaveCard(c);\n    for (const o of others) await rcDelCard(o);\n    closeAllSheets();\n    toast('已保留 1 张、删掉 ' + others.length + ' 张');\n    render();\n  },\n  /* 整组只留「掌握得最好」的那张，一键清掉所有重复组 */\n  rcDupKeepBest: async el => {\n    const bid = el.dataset.id || S.draft.rcBookId;\n    const groups = rcDupGroups(bid);\n    if (!groups.length) { toast('没有重复的卡片'); return; }\n    let del = 0;\n    for (const g of groups) {\n      const best = g.cards.slice().sort((a, b) =>\n        (Number(b.level) || 0) - (Number(a.level) || 0) || (Number(b.rightN) || 0) - (Number(a.rightN) || 0))[0];\n      for (const o of g.cards) { if (String(o.id) === String(best.id)) continue; await rcDelCard(o); del++; }\n      await rcSaveCard(best);\n    }\n    closeAllSheets();\n    toast('清掉 ' + del + ' 张重复卡片，每组保留掌握最好的那张');\n    render();\n  },\n  rcWeakOpen: () => go('rcweak'),\n  rcStatsOpen: () => go('rcstats'),\n  /* ---- 挑选卡片：勾一批，批量设优先级 / 移走 / 复制 / 只背这几张 ----\n     ⚠️ 这一组动作以前整个漏写了：词本页画出了「☑️ 挑选卡片」按钮，\n     动作表里却没有对应的处理函数，点击事件委托拿不到函数就直接 return ——\n     表现就是「点了没反应」，一句提示都不会有。这里补齐。 */\n  rcSelModeOn: () => { S.draft.rcSelMode = true; S.draft.rcSelSel = {}; render(); },\n  rcSelModeOff: () => { S.draft.rcSelMode = false; S.draft.rcSelSel = {}; render(); },\n  rcSelToggle: el => {\n    const id = String(el.dataset.id || '');\n    if (!id) return;\n    S.draft.rcSelSel = S.draft.rcSelSel || {};\n    if (S.draft.rcSelSel[id]) delete S.draft.rcSelSel[id]; else S.draft.rcSelSel[id] = 1;\n    render();\n  },\n  rcSelAll: () => {\n    const m = {};\n    rcCardsOf(S.draft.rcBookId).forEach(c => { m[String(c.id)] = 1; });\n    S.draft.rcSelSel = m;\n    render();\n  },\n  rcSelNone: () => { S.draft.rcSelSel = {}; render(); },\n  rcSelPri: async el => {\n    const ids = rcSelIds();\n    if (!ids.length) { toast('先勾几张卡片'); return; }\n    const k = clamp(Number(el.dataset.k) || 0, 0, 2);\n    for (const id of ids) {\n      const c = rcCardById(id);\n      if (!c) continue;\n      c.pri = k;\n      await rcSaveCard(c);\n    }\n    toast('已把 ' + ids.length + ' 张设为「' + rcPriName(k) + '」');\n    render();\n  },\n  rcSelMove: () => { const ids = rcSelIds(); if (!ids.length) { toast('先勾几张卡片'); return; } rcPickBooksThen(ids, false); },\n  rcSelCopy: () => { const ids = rcSelIds(); if (!ids.length) { toast('先勾几张卡片'); return; } rcPickBooksThen(ids, true); },\n  rcSelStart: () => {\n    const ids = rcSelIds();\n    if (!ids.length) { toast('先勾几张卡片'); return; }\n    if (S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) {\n      toast('你还有一轮没背完 —— 先「继续」，或点「结束并记账」把它结掉');\n      return;\n    }\n    const list = ids.map(rcCardById).filter(Boolean);\n    if (!list.length) { toast('这些卡片已经不在了'); return; }\n    S.recite = {\n      scope: 'pick', bookId: S.draft.rcBookId || '', queue: list.map(c => c.id), idx: 0,\n      flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n      done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n      newN: 0, weakBefore: rcWeakCards(S.draft.rcBookId).length,\n      startedAt: Date.now(), touched: {}, log: []\n    };\n    S.draft.rcSelMode = false;\n    S.draft.rcSelSel = {};\n    toast('只背这 ' + list.length + ' 张');\n    go('rcsession');\n  }\n});\n/* ==========================================================\n   背诵会话 · 调度内核\n   ----------------------------------------------------------\n   调度规则（都在进入页面时一次算好，不后台定时，省电）：\n   · 不会(0)：本轮立刻插队再来 2 次；下一轮权重最高\n   · 模糊(1)：隔 6 条再出现一次，本轮多一次复习机会\n   · 熟练(2)：本轮基本不再出现，权重调低\n   · 精通(3)：本轮屏蔽，且 3 轮之内不再抽到\n   两种序列：顺序（按录入顺序）/ 权重随机（洗牌 + 按等级加权）\n   ========================================================== */\nfunction rcShuffle(arr) {\n  const a = (arr || []).slice();\n  for (let i = a.length - 1; i > 0; i--) {\n    const j = Math.floor(Math.random() * (i + 1));\n    const t = a[i]; a[i] = a[j]; a[j] = t;\n  }\n  return a;\n}\n/* 按等级权重抽：不是纯随机，薄弱的更容易被抽到；精通给极小权重兜底 */\n/* 抽到某张卡的权重：等级权重 × 优先级系数。\n   优先级系数按「焦点档」算 —— 焦点档 ×8、已过关的档 ×2（回来复习）、\n   还没到的档 ×0.6（只偶尔穿插）。这就是「分轮」的实质。 */\nfunction rcPriFactor(c, focus) {\n  const t = rcPriOf(c);\n  if (focus < 0) return 2;                       // 全掌握：一律按复习算\n  if (t === focus) return 8;\n  if (t < focus) return 2;                       // 已经过掉的档：跟着复习\n  return 0.6;                                    // 还没到的档：偶尔穿插\n}\nfunction rcWeightedShuffle(cards) {\n  const pool = (cards || []).slice();\n  const focus = rcFocusTier(pool);\n  const out = [];\n  while (pool.length) {\n    let total = 0;\n    const ws = pool.map(c => {\n      const base = rcLv(c.level).w * rcPriFactor(c, focus);\n      const w = c.paused ? base * 1.6 : base;      // 跳过 / 答错的先提权\n      total += w;\n      return w;\n    });\n    let r = Math.random() * total, pick = 0;\n    for (let i = 0; i < ws.length; i++) { r -= ws[i]; if (r <= 0) { pick = i; break; } pick = i; }\n    out.push(pool.splice(pick, 1)[0]);\n  }\n  return out;\n}\n/* 建队列：scope = 'weak' 只用薄弱卡片；否则用指定词本（或全部） */\nfunction rcBuildQueue(scope, bookId) {\n  let cards = scope === 'weak' ? rcWeakCards(bookId) : (bookId ? rcCardsOf(bookId) : rcCards());\n  /* 精通卡片本轮直接屏蔽（banUntilRound > 当前轮次才放行） */\n  const roundN = Number(S.draft.rcRound || 0);\n  cards = cards.filter(c => {\n    if (Number(c.level) !== 3) return true;\n    const ban = Number(c.banUntilRound || 0);\n    return ban > 0 && roundN < ban;\n  });\n  /* 「快忘的卡片」标记：不管用哪种序列，先让它们排到最前面过一遍 ——\n     标记只在当轮有效，用户随时可以在统计页清掉。 */\n  const fids = S.draft.rcForgetIds || [];\n  if (fids.length) {\n    const hit = [], rest = [];\n    const set = {};\n    fids.forEach(id => { set[String(id)] = 1; });\n    cards.forEach(c => { (set[String(c.id)] ? hit : rest).push(c); });\n    const ordered = hit.concat(rest);\n    if (S.draft.rcMode === 'weight') return rcWeightedShuffle(ordered).sort(function (a, b) {\n      return (set[String(b.id)] ? 1 : 0) - (set[String(a.id)] ? 1 : 0);\n    });\n    return ordered;\n  }\n  if (S.draft.rcMode === 'weight') return rcWeightedShuffle(cards);\n  if (S.draft.rcMode === 'pri') return rcPriQueue(cards);\n  return cards.slice();\n}\n/* 优先级分轮：焦点档整档排前面（打乱），每 4 条插 1 条其它档；\n   剩下的其它档接在后面。比纯随机更像「一轮一轮地过」。 */\nfunction rcPriQueue(cards) {\n  const list = (cards || []).slice();\n  const focus = rcFocusTier(list);\n  const groups = [[], [], []];\n  list.forEach(c => groups[rcPriOf(c)].push(c));\n  const out = [];\n  const focusList = focus < 0 ? [] : shuffle(groups[focus].slice());\n  const others = [];\n  [0, 1, 2].forEach(t => { if (t !== focus) shuffle(groups[t].slice()).forEach(c => others.push(c)); });\n  let oi = 0;\n  focusList.forEach((c, i) => {\n    out.push(c);\n    if (oi < others.length && (i + 1) % 4 === 0) out.push(others[oi++]);\n  });\n  while (oi < others.length) out.push(others[oi++]);\n  if (!out.length && list.length) return shuffle(list);   // 兜底：不该发生\n  return out;\n}\nasync function rcStartSession(scope, bookId) {\n  rcApplyDefaults();          // 先把设置里的默认值套上，再算队列\n  const cards = rcBuildQueue(scope, bookId);\n  if (!cards.length) {\n    toast(scope === 'weak' ? '现在没有薄弱卡片' : '这个词本还没有可抽的卡片');\n    return;\n  }\n  S.recite = {\n    scope: scope, bookId: bookId || '', queue: cards.map(c => c.id), idx: 0,\n    flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n    done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n    newN: 0, weakBefore: rcWeakCards(bookId).length,\n    startedAt: Date.now(), touched: {}, log: []\n  };\n  go('rcsession');\n}\nfunction rcCurCard() {\n  const R = S.recite;\n  if (!R) return null;\n  return rcCardById(R.queue[R.idx]) || null;\n}\nfunction rcProgress() {\n  const R = S.recite;\n  if (!R) return { i: 0, n: 0, pct: 0 };\n  const n = R.queue.length;\n  return { i: Math.min(R.idx + 1, n), n: n, pct: n ? Math.round(R.idx / n * 100) : 0 };\n}\n/* 角色气泡：关键节点才出，答错只安抚、绝不打击 */\nasync function rcBubble(kind) {\n  const cid = anyCharId();\n  const who = cid ? charName(cid) : '你的伴';\n  const TXT = {\n    like: ['给你点个赞，这段很稳。', '我看着呢，继续。', '这条数又往上走了，不错。'],\n    star: ['全对。帅。', '一模一样，你记住了。', '这一条我放心了。'],\n    hot: ['最难的那张，你把它啃下来了。', '红色的都被你清了，厉害。', '这张以前总错，现在稳了。'],\n    comfort: ['没关系，卡一下很正常，我们再来一遍。', '错了不要紧，先记住这个坑。', '别急，这一条我陪你多过几次。']\n  }[kind] || [];\n  if (!TXT.length) return;\n  toast(who + '：' + TXT[Math.floor(Math.random() * TXT.length)]);\n  /* 语音按原有开关走，且不阻塞、不锁按钮 */\n  try {\n    if (cid && shouldSpeak('cheer')) quietOn(), speak(cid, TXT[0]), quietOff();\n  } catch (e) { }\n}\n/* ---------- 评级：四档 + 防刷量 + 插队复习 ---------- */\nasync function rcRate(lv, fromDictation) {\n  const R = S.recite;\n  const c = rcCurCard();\n  if (!R || !c) return;\n  const now = Date.now();\n  /* 防刷量 ①：间隔太短连续翻卡 —— 这次不计入记忆等级（阈值可在背书设置里调） */\n  if (!fromDictation && now - (R.lastSwitchAt || 0) < rcFastFlipMs()) {\n    toast('翻得太快了，这次不计入记忆等级');\n    R.idx++; R.flipped = false; R.shownAt = now; R.lastSwitchAt = now;\n    if (R.idx >= R.queue.length) { await rcFinishSession(); return; }\n    render(); return;\n  }\n  /* 防刷量 ②：刚翻开就点「熟练 / 精通」—— 降权，不当成真记住 */\n  let eff = clamp(Number(lv) || 0, 0, 3);\n  let cheap = false;\n  if (!fromDictation && eff >= 2 && now - (R.shownAt || 0) < rcQuickMarkMs()) { eff = 1; cheap = true; }\n  /* 精通必须有「连续两次」的底子，否则先记熟练 */\n  let demoted = false;\n  if (eff === 3 && Number(c.streak || 0) < 2) { eff = 2; demoted = true; }\n  const before = Number(c.level) || 0;\n  if (eff >= 2) {\n    c.rightN = Number(c.rightN || 0) + 1;\n    c.streak = Number(c.streak || 0) + 1;\n    c.paused = false;\n  } else {\n    c.wrongN = Number(c.wrongN || 0) + 1;\n    c.streak = 0;\n    c.paused = true;\n  }\n  c.level = eff;\n  c.lastAt = now;\n  if (eff === 3) c.banUntilRound = Number(S.draft.rcRound || 0) + 3;\n  await rcSaveCard(c);\n  R.done++;\n  if (eff >= 2) R.right++; else R.wrong++;\n  if (fromDictation) { R.dictationN++; if (eff >= 2) R.dictationRight++; }\n  if (before < 2 && eff >= 2) R.newN++;\n  R.touched[c.id] = Math.max(Number(R.touched[c.id] || 0), eff);\n  R.log.push({ id: c.id, lv: eff, dict: !!fromDictation, at: now });\n  /* 过完一遍就把「快忘」标记撤掉 —— 刚复习过的卡片不该还挂着这个提示 */\n  if ((S.draft.rcForgetIds || []).length) {\n    S.draft.rcForgetIds = S.draft.rcForgetIds.filter(x => String(x) !== String(c.id));\n    if (S.draft.rcForgetList) S.draft.rcForgetList = S.draft.rcForgetList.filter(x => String(x.id) !== String(c.id));\n    if (!S.draft.rcForgetIds.length) S.draft.rcForgetNote = '';\n  }\n  /* 插队复习：不会 → 再来 2 次；模糊 → 隔 6 条再来 1 次 */\n  if (eff === 0) {\n    R.queue.splice(R.idx + 1, 0, c.id);\n    R.queue.splice(Math.min(R.queue.length, R.idx + 3), 0, c.id);\n  } else if (eff === 1) {\n    R.queue.splice(Math.min(R.queue.length, R.idx + 7), 0, c.id);\n  }\n  if (cheap) toast('点得太快了 —— 这张先按「模糊」记，认真过一遍再来');\n  else if (demoted) toast('连续两次都答对之后才算「精通」，这次先记熟练');\n  /* 里程碑气泡：每 10 条一次；答错给安抚；精通给星光 */\n  if (R.done > 0 && R.done % 10 === 0) rcBubble('like');\n  else if (eff === 0) rcBubble('comfort');\n  else if (eff === 3) rcBubble('star');\n  /* 攻克红色高频易错（错≥3 且这次答对）→ 专属庆祝 */\n  if (eff >= 2 && Number(c.wrongN || 0) >= 3 && before < 2) rcBubble('hot');\n  R.idx++; R.flipped = false; R.shownAt = now; R.lastSwitchAt = now;\n  S.draft.rcBlankShown = {};      // 换下一张：挖空全部盖回去\n  if (R.idx >= R.queue.length) { await rcFinishSession(); return; }\n  render();\n}\n/* 跳过：不算对也不算错，但会提权（下次更容易出现） */\nasync function rcSkipCard() {\n  const R = S.recite;\n  const c = rcCurCard();\n  if (!R || !c) return;\n  R.lastSwitchAt = Date.now();\n  c.paused = true;\n  await rcSaveCard(c);\n  R.idx++; R.flipped = false; R.shownAt = Date.now();\n  S.draft.rcBlankShown = {};\n  if (R.idx >= R.queue.length) { await rcFinishSession(); return; }\n  render();\n}\n/* 上一条 / 下一条：只在队列内移动，不改等级 */\nfunction rcMove(step) {\n  const R = S.recite;\n  if (!R) return;\n  R.idx = clamp(R.idx + step, 0, Math.max(0, R.queue.length - 1));\n  R.flipped = false; R.shownAt = Date.now(); R.lastSwitchAt = Date.now();\n  S.draft.rcBlankShown = {};\n  render();\n}\n/* 一轮结束：记流水（统计面板和专注报告都读它），并按条数发专注币 */\nasync function rcFinishSession() {\n  const R = S.recite;\n  if (!R) return;\n  const weakAfter = rcWeakCards(R.bookId).length;\n  const weakN = Math.max(0, R.weakBefore - weakAfter);\n  const rec = {\n    date: dkey(), at: Date.now(), bookId: R.bookId || '', scope: R.scope,\n    total: R.done, right: R.right, wrong: R.wrong,\n    dictationN: R.dictationN, dictationRight: R.dictationRight,\n    newN: R.newN, weakN: weakN,\n    ms: Date.now() - (R.startedAt || Date.now())\n  };\n  /* 先算币、写进 rec，再落流水。\n     ⚠️ 以前是先落流水、后算币：rcLogAdd 把 rec 快照存进数据库的那一刻，\n     coin 还没赋值 —— 所以统计里的「获得币」永远是 0。这就是那个 bug。 */\n  let earn = 0;\n  if (R.done > 0) {\n    const per = Math.max(0, Number(cfg('rcCoinPerCard') != null ? cfg('rcCoinPerCard') : 0.2));\n    earn = Math.round(R.done * per);\n    if (earn > 0) rec.coin = earn;\n  }\n  if (R.done > 0) await rcLogAdd(rec);\n  if (earn > 0) await coinAdd(earn, '背书 ' + R.done + ' 条');\n  /* 全部标记熟练以上 → 学霸称号弹窗 */\n  const allHigh = R.done > 0 && R.wrong === 0;\n  if (allHigh) { try { openSheet(`<h3 style=\"text-align:center\">🎓 一轮全过</h3>\n    <div class=\"center\" style=\"font-size:44px\">🏅</div>\n    <div class=\"center tiny mt6\">这一轮 ${R.done} 条全部熟练以上，没有一条掉队。</div>\n    <button class=\"btn primary block mt12\" data-act=\"closeSheet\">收下</button>`); } catch (e) { } }\n  S.recite = null;\n  const parts = [];\n  parts.push('背了 ' + R.done + ' 条');\n  if (R.dictationN) parts.push('默写 ' + R.dictationN + ' 条（对 ' + R.dictationRight + '）');\n  if (R.newN) parts.push('新掌握 ' + R.newN + ' 条');\n  if (weakN) parts.push('清掉薄弱 ' + weakN + ' 条');\n  if (earn) parts.push('+' + earn + ' 专注币');\n  toast('这一轮：' + parts.join(' · '));\n  go(R.scope === 'weak' ? 'rcweak' : 'rcbooks');\n}\n/* ==========================================================\n   视图 · 背诵会话（核心页）\n   ----------------------------------------------------------\n   顶部一排开关：顺序/权重随机 · 卡片/默写 · 遮罩 · 倒计时\n   中间是卡片主体，下面是操作按钮组。\n   ========================================================== */\nVIEWS.rcsession = function () {\n  const R = S.recite;\n  if (!R) return `<div class=\"card\"><h3>当前没有在背诵</h3>\n    <button class=\"btn primary block mt10\" data-act=\"gotoView\" data-view=\"rcbooks\">回背书首页</button></div>`;\n  const c = rcCurCard();\n  const pg = rcProgress();\n  if (!c) return `<div class=\"card\"><h3>这一轮结束了</h3>\n    <button class=\"btn primary block mt10\" data-act=\"rcFinish\">看本轮小结</button></div>`;\n  const mask = S.draft.rcMask || 'full';\n  const mode = S.draft.rcMode || 'order';\n  const study = S.draft.rcStudy || 'card';\n  const dict = S.draft.rcDict || '';\n  const timerOn = !!S.draft.rcTimer;\n  const secs = Number(S.draft.rcTimerSec || 5);\n  const strict = !!S.draft.rcStrict;\n  /* 遮罩：full 全遮 / hint 只留首尾线索 / line 逐行揭露 */\n  function answerHTML() {\n    const a = String(c.a || '');\n    if (!a) return '<div class=\"tiny\" style=\"color:var(--dim2)\">（这张卡片还没写答案）</div>';\n    if (mask === 'full') return `<di",
  "v style=\"font-size:14px;line-height:1.9;white-space:pre-wrap\">${esc(a)}</div>`;\n    /* 半遮：首、尾各留几个字由你定（背诵页和设置里都能调） */\n    if (mask === 'hint') {\n      const hN = rcMaskHead(), tN = rcMaskTail();\n      const lines = a.split('\\n').filter(x => x.trim());\n      return lines.map(l => {\n        const t = String(l).trim();\n        if (hN + tN >= t.length) return `<div style=\"font-size:14px;line-height:1.9\">${esc(t)}</div>`;\n        const head = t.slice(0, hN), tail = tN ? t.slice(-tN) : '';\n        const mid = t.length - hN - tN;\n        return `<div style=\"font-size:14px;line-height:1.9\">${esc(head)}<span style=\"color:var(--dim2)\">…（中间 ${mid} 字自己回忆）…</span>${esc(tail)}</div>`;\n      }).join('');\n    }\n    /* 挖空：把这张卡的易错词（没标过就用自动关键词）从答案里挖掉，\n       只留空位让你回忆；点单个空位可以单独揭开那一个。 */\n    if (mask === 'blank') {\n      const keys = ((c.tricky && c.tricky.length) ? c.tricky.slice() : rcKeywords(c)).filter(Boolean)\n        .slice().sort((x, y) => String(y).length - String(x).length);\n      if (!keys.length) return '<div class=\"tiny\" style=\"color:var(--dim2)\">（还没标过易错词 —— 去「✏️ 改这张卡片」里，把默写漏掉的词收成易错词）</div>';\n      const shownB = S.draft.rcBlankShown || {};\n      let out = esc(a);\n      keys.forEach(k => {\n        const ek = esc(k);\n        if (!ek) return;\n        const on = !!shownB[k];\n        out = out.split(ek).join('<span data-act=\"rcRevealBlank\" data-k=\"' + esc(k) + '\" style=\"background:var(--card2);border-bottom:1.5px dashed var(--gold);padding:0 6px;border-radius:4px;cursor:pointer;color:' + (on ? 'var(--gold)' : 'var(--dim2)') + '\">' + (on ? ek : '＿＿＿＿') + '</span>');\n      });\n      return out + '<div class=\"tiny mt8\" style=\"color:var(--dim2)\">点空位可以单独揭开那一个；其余内容照常显示，看完自己回想挖掉的是什么。</div>';\n    }\n    /* 逐行揭露：已揭开的行用实色，未揭开的盖住 */\n    const lines = a.split('\\n').filter(x => x.trim());\n    const shown = Number(S.draft.rcLineShown || 0);\n    return lines.map((l, i) => i < shown\n      ? `<div style=\"font-size:14px;line-height:1.9\">${esc(l)}</div>`\n      : `<div data-act=\"rcRevealLine\" data-i=\"${i}\" style=\"font-size:14px;line-height:1.9;background:var(--card2);border-radius:8px;padding:6px 9px;margin-bottom:5px;color:var(--dim2);cursor:pointer\">点这一行显示（第 ${i + 1} 行）</div>`).join('');\n  }\n  const lvBtns = RC_LV.slice().reverse().map(l =>\n    `<button class=\"btn ${l.k === 3 ? 'primary' : (l.k === 0 ? 'warn' : '')} grow\" style=\"min-height:46px\" data-act=\"rcRateBtn\" data-k=\"${l.k}\">${l.n}</button>`).join('');\n  return `\n  <div class=\"card tight\">\n    <div class=\"row between\">\n      <div class=\"grow\" style=\"min-width:0\">\n        <div class=\"row wrap\" style=\"gap:6px\">\n          <button class=\"chip ${mode === 'order' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMode\" data-v=\"order\">顺序</button>\n          <button class=\"chip ${mode === 'weight' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMode\" data-v=\"weight\">权重随机</button>\n          <button class=\"chip ${mode === 'pri' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMode\" data-v=\"pri\">🎯 优先级分轮</button>\n          <button class=\"chip ${study === 'card' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcStudy\" data-v=\"card\">卡片</button>\n          <button class=\"chip ${study === 'dict' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcStudy\" data-v=\"dict\">默写</button>\n          <button class=\"chip ${timerOn ? 'on' : ''}\" data-act=\"rcToggleTimer\">⏱ ${timerOn ? secs + 's' : '倒计时'}</button>\n        </div>\n      </div>\n      <button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"rcQuit\">结束</button>\n    </div>\n    ${study === 'card' ? `<div class=\"row wrap mt8\" style=\"gap:6px\">\n      <span class=\"tiny\" style=\"align-self:center\">遮罩：</span>\n      <button class=\"chip ${mask === 'full' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMask\" data-v=\"full\">全遮</button>\n      <button class=\"chip ${mask === 'hint' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMask\" data-v=\"hint\">半遮·首尾线索</button>\n      <button class=\"chip ${mask === 'line' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMask\" data-v=\"line\">逐行揭露</button>\n      <button class=\"chip ${mask === 'blank' ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcMask\" data-v=\"blank\">挖空 · 只考易错词</button>\n    </div>` : ''}\n    ${timerOn ? `<div class=\"row wrap mt8\" style=\"gap:6px\">\n      <span class=\"tiny\" style=\"align-self:center\">时限：</span>\n      ${[3, 5, 10].map(s => `<button class=\"chip ${secs === s ? 'on' : ''}\" data-act=\"rcSetOpt\" data-k=\"rcTimerSec\" data-v=\"${s}\" data-num=\"1\">${s}s</button>`).join('')}\n      <button class=\"chip ${strict ? 'on' : ''}\" data-act=\"rcToggleStrict\">严格考试（不许跳过·超时记模糊）</button>\n      <input class=\"input\" style=\"width:70px;padding:4px 8px;min-height:auto\" type=\"number\" inputmode=\"numeric\" data-in=\"rcTimerSec\" data-num=\"1\" value=\"${secs}\">\n    </div>` : ''}\n  </div>\n  <div class=\"card tight\"><div class=\"row between\">\n    <span class=\"tiny\">第 ${pg.i} / ${pg.n} 条${R.scope === 'weak' ? ' · 🔥 薄弱专项' : (R.scope === 'forget' ? ' · 🔮 快忘的' : (R.scope === 'plan' ? ' · 🤖 今日计划' : (R.scope === 'paper' ? ' · 🤖 组卷' : (R.scope === 'pick' ? ' · ☑️ 挑选的卡片' : (R.bookId ? ' · ' + esc(rcBookName(R.bookId)) : '')))))}</span>\n    <span class=\"tiny\">本轮 ${R.done} 条 · 对 ${R.right} · 错 ${R.wrong}</span></div>\n    <div class=\"bar mt6\"><i style=\"width:${pg.pct}%\"></i></div>\n    ${(mode === 'pri' || mode === 'weight') ? `<div class=\"tiny mt6\">🎯 本轮焦点：<b style=\"color:${rcFocusTier(R.queue.map(rcCardById).filter(Boolean)) < 0 ? 'var(--dim)' : rcPriColor(rcFocusTier(R.queue.map(rcCardById).filter(Boolean)))}\">${esc(rcFocusText(R.queue.map(rcCardById).filter(Boolean)))}</b> —— 焦点档主抽，已过关的档穿插复习，还没到的档只偶尔出现</div>` : ''}\n    ${c.pri != null ? `<div class=\"tiny mt6\">这张的优先级：<span style=\"color:${rcPriColor(rcPriOf(c))}\">${rcPri(c.pri).emoji} ${esc(rcPriName(rcPriOf(c)))}</span></div>` : ''}</div>\n  ${timerOn ? `<div class=\"card tight\" style=\"padding:8px 12px\"><div class=\"bar ${S.draft.rcTimeUp ? 'warn' : ''}\"><i id=\"rcTimeBar\" style=\"width:${S.draft.rcTimePct == null ? 100 : S.draft.rcTimePct}%\"></i></div>\n    <div class=\"tiny mt6\" id=\"rcTimeTip\">${S.draft.rcTimeUp ? (strict ? '时间到 —— 已按「模糊」记' : '时间到 —— 已自动翻面') : '思考时限 ' + secs + ' 秒'}</div></div>` : ''}\n  <div class=\"card\" data-act=\"rcFlip\" style=\"cursor:pointer;min-height:32vh;display:flex;flex-direction:column;justify-content:center\">\n    <div class=\"tiny\" style=\"color:var(--dim2)\">题干</div>\n    <div style=\"font-size:15.5px;line-height:1.85;margin-top:8px;white-space:pre-wrap\">${esc(c.q)}</div>\n    ${c.hint ? `<div class=\"tiny mt8\" style=\"color:var(--dim2)\">提示：${esc(c.hint)}</div>` : ''}\n    ${c.note ? `<div class=\"tiny mt8\" style=\"line-height:1.7;color:var(--gold)\">📝 我的笔记：${esc(c.note)}</div>` : ''}\n    ${R.flipped ? `<div class=\"hr\"></div>${answerHTML()}` : `<div class=\"tiny center mt14\" style=\"color:var(--dim2)\">点卡片翻开答案</div>`}\n  </div>\n  <div class=\"row\" style=\"gap:8px;margin:-4px 0 12px\">\n    <button class=\"btn sm ghost grow\" data-act=\"rcEditCur\">✏️ 改这张卡片（不用退出这一轮）</button>\n    ${/[a-zA-Z]{3,}/.test(String(c.q || '')) ? `<button class=\"btn sm ghost grow\" data-act=\"rcAiTranslateBtn\">🔤 例句词根</button>` : ''}\n  </div>\n  ${study === 'dict' ? `<div class=\"card\">\n    <div class=\"row between\"><span class=\"tiny\">✍️ 默写：写下你记得的内容，系统按关键词覆盖率判分</span></div>\n    <textarea id=\"rcDictBox\" data-in=\"rcdict.${esc(c.id)}\" style=\"min-height:110px;margin-top:8px\" placeholder=\"凭记忆写下来，写不全也没关系\">${esc((S.draft.rcDictBy || {})[c.id] || '')}</textarea>\n    <button class=\"btn primary block mt10\" data-act=\"rcDictSubmit\">提交核对</button>\n    <div class=\"tiny mt6\">覆盖率 ≥85% 记熟练 · 50%~85% 记模糊 · 低于 50% 或空白记不会。写完可以自己再改评级。</div></div>` : ''}\n  ${R.flipped ? `<div class=\"card\"><div class=\"tiny center\">这张你记得怎么样？</div>\n    <div class=\"row mt10\" style=\"gap:6px\">${lvBtns}</div></div>` : ''}\n  ${(rcAiCfg().on && rcAiOn('hint')) || rcAiOn('explain') || rcAiOn('compare') || rcAiOn('variant') ? `<div class=\"card tight\"><div class=\"tiny\">AI 辅助（不会直接给答案）</div>\n    <div class=\"row wrap mt6\" style=\"gap:6px\">\n      ${rcAiOn('hint') ? `<button class=\"chip\" data-act=\"rcAiHintBtn\" ${S.loading === 'rchint' ? 'disabled' : ''}>${S.loading === 'rchint' ? '…' : '💡 启发提示'}</button>` : ''}\n      ${rcAiOn('explain') ? `<button class=\"chip\" data-act=\"rcAiExplainBtn\">📖 AI 解释</button>` : ''}\n      ${rcAiOn('compare') ? `<button class=\"chip\" data-act=\"rcAiCompareBtn\">🔀 易混辨析</button>` : ''}\n      ${rcAiOn('variant') ? `<button class=\"chip\" data-act=\"rcAiVariantBtn\">🔁 变式题</button>` : ''}\n      ${(S.draft.rcAiShow && String(S.draft.rcAiShow.id) === String(c.id)) ? `<button class=\"chip on\" data-act=\"rcAiClose\">收起</button>` : ''}\n    </div>\n    ${(S.draft.rcAiShow && String(S.draft.rcAiShow.id) === String(c.id)) ? `<div class=\"mt8\" style=\"background:var(--card2);border-radius:10px;padding:10px\">\n      ${S.draft.rcAiShow.at ? `<div class=\"row between\" style=\"margin-bottom:5px\"><span class=\"tiny\" style=\"color:var(--dim2)\">留存在卡片上 · ${dkey(new Date(S.draft.rcAiShow.at))} ${hm(S.draft.rcAiShow.at)}</span>\n        <button class=\"btn sm ghost\" style=\"min-height:26px;padding:0 9px\" data-act=\"rcAiShowRegen\" data-k=\"${esc(S.draft.rcAiShow.kind || 'hint')}\">↺ 重新生成</button></div>` : ''}\n      <div style=\"font-size:13px;line-height:1.8;white-space:pre-wrap\">${esc(S.draft.rcAiShow.text)}</div></div>` : ''}\n    ${(S.draft.rcVariant && String(S.draft.rcVariant.id) === String(c.id)) ? `<div class=\"mt8\">\n      ${S.draft.rcVariant.at ? `<div class=\"row between\" style=\"margin-bottom:6px\"><span class=\"tiny\" style=\"color:var(--dim2)\">留存在卡片上 · ${dkey(new Date(S.draft.rcVariant.at))} ${hm(S.draft.rcVariant.at)}</span>\n        <button class=\"btn sm ghost\" style=\"min-height:26px;padding:0 9px\" data-act=\"rcVariantRegen\">↺ 重新出题</button></div>` : ''}\n      ${(S.draft.rcVariant.list || []).map((v, i) => `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:7px\">\n      <div style=\"font-size:12.8px;line-height:1.6\">变式 ${i + 1}：${esc(v.q)}</div>\n      <div class=\"tiny mt6\" data-act=\"rcVariantShow\" data-i=\"${i}\" style=\"cursor:pointer;color:var(--teal)\">${S.draft.rcVariantShown === i ? esc(v.a || '（无参考答案）') : '点这里看参考答案'}</div></div>`).join('')}</div>` : ''}\n  </div>` : ''}\n  ${(S.draft.rcDictResult && String(S.draft.rcDictResult.id) === String(c.id)) ? `<div class=\"card\" style=\"border-color:rgba(94,234,212,.45)\">\n    <div class=\"row between\"><span class=\"tiny\">✍️ 刚才那次默写</span><span class=\"pill ${S.draft.rcDictResult.lv >= 2 ? 'ok' : (S.draft.rcDictResult.lv === 1 ? 'warn' : 'bad')}\">${S.draft.rcDictResult.lv >= 2 ? '熟练' : (S.draft.rcDictResult.lv === 1 ? '模糊' : '不会')}${S.draft.rcDictResult.byAI ? ' · AI 判' : ' · 本地判'}</span></div>\n    <div class=\"tiny mt6\">覆盖率 ${S.draft.rcDictResult.pct}%${S.draft.rcDictResult.byAI && S.draft.rcDictResult.score ? ' · AI 给分 ' + S.draft.rcDictResult.score : ''}</div>\n    ${(S.draft.rcDictResult.hit || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">命中的关键词：<span style=\"color:var(--teal)\">${esc(S.draft.rcDictResult.hit.join('、'))}</span></div>` : ''}\n    ${(S.draft.rcDictResult.miss || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7;color:#ffb37a\">漏掉的：${esc(S.draft.rcDictResult.miss.join('、'))}</div>` : ''}\n    ${(S.draft.rcDictResult.wrong || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7;color:#ff9aa6\">写错的地方：${esc(S.draft.rcDictResult.wrong.join('；'))}</div>` : ''}\n    ${S.draft.rcDictResult.say ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">${esc(S.draft.rcDictResult.say)}</div>` : ''}\n    ${(S.draft.rcDictResult.text) ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">你写的：<span style=\"color:var(--dim)\">${esc(String(S.draft.rcDictResult.text).slice(0, 160))}</span></div>` : ''}\n    <div class=\"tiny mt8\">题目</div>\n    <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.q || ''))}</div>\n    <div class=\"tiny mt8\">标准答案</div>\n    <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.a || '（这张卡片没有答案）'))}</div>\n    ${(S.draft.rcDictResult.needCopy && !S.draft.rcDictResult.copied) ? `\n      <div class=\"card tight mt10\" style=\"border-color:rgba(255,201,120,.5);background:rgba(255,201,120,.08)\">\n        <div class=\"tiny\" style=\"color:var(--gold)\">这条没达标 —— 照着上面抄一遍，抄完才放你进下一题</div>\n        <textarea id=\"rcCopyBox\" data-in=\"rccopy\" style=\"min-height:96px;margin-top:8px\" placeholder=\"照着上面一行一行抄过来\">${esc(S.draft.rcCopyText || '')}</textarea>\n        <div class=\"tiny mt6\" style=\"color:var(--dim2)\">抄写框不接受粘贴。差不多就行，错几个字没关系。</div>\n        <button class=\"btn primary block mt8\" data-act=\"rcDictCopyDone\" data-id=\"${esc(c.id)}\">抄完了，检查一下</button>\n      </div>` : `\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"rcDictConfirm\">就按「${S.draft.rcDictResult.lv >= 2 ? '熟练' : (S.draft.rcDictResult.lv === 1 ? '模糊' : '不会')}」记，继续</button>\n      </div>\n      <div class=\"row mt8\" style=\"gap:8px\"><button class=\"btn sm ghost grow\" data-act=\"rcDictAdjust\" data-k=\"2\">其实记得，记熟练</button>\n        <button class=\"btn sm ghost grow\" data-act=\"rcDictAdjust\" data-k=\"1\">记模糊</button>\n        <button class=\"btn sm ghost grow\" data-act=\"rcDictAdjust\" data-k=\"0\">确实不会</button></div>`}\n    ${(S.draft.rcDictResult.miss || []).length ? `<button class=\"btn sm ghost block mt8\" data-act=\"rcDictTricky\" data-id=\"${esc(c.id)}\">把漏掉的 ${S.draft.rcDictResult.miss.length} 个词收成易错词（之后挖空考你）</button>` : ''}\n    <div class=\"tiny mt6\" style=\"color:var(--dim2)\">最终评级还是你说了算，AI 只是参考。</div>\n    ${(S.draft.rcDictResult.miss || []).length ? `<button class=\"btn sm ghost block mt8\" data-act=\"rcDictEditKeys\" data-id=\"${esc(c.id)}\">判得不准？改这张卡片的关键词</button>` : ''}\n    </div>` : ''}\n  <div class=\"row\" style=\"gap:8px;margin-bottom:12px\">\n    <button class=\"btn ghost grow\" data-act=\"rcMoveBtn\" data-s=\"-1\" ${R.idx <= 0 ? 'disabled' : ''}>‹ 上一条</button>\n    <button class=\"btn ghost grow\" data-act=\"rcSkip\" ${strict ? 'disabled' : ''}>跳过</button>\n    <button class=\"btn ghost grow\" data-act=\"rcMoveBtn\" data-s=\"1\">下一条 ›</button></div>`;\n};\n/* ==========================================================\n   视图 · 背书统计（今日 / 累计 / 记忆分析）\n   ========================================================== */\nVIEWS.rcstats = function () {\n  const all = rcCards();\n  const today = rcTodayLogs();\n  const tN = sum(today.map(x => Number(x.total) || 0));\n  const tDict = sum(today.map(x => Number(x.dictationN) || 0));\n  const tRight = sum(today.map(x => Number(x.dictationRight) || 0));\n  const tNew = sum(today.map(x => Number(x.newN) || 0));\n  const tWeak = sum(today.map(x => Number(x.weakN) || 0));\n  const tCoin = sum(today.map(x => Number(x.coin) || 0));\n  const lvN = k => all.filter(c => Number(c.level) === k).length;\n  const total = all.length || 1;\n  const hotTop = rcCards().filter(c => Number(c.wrongN || 0) > 0)\n    .sort((a, b) => Number(b.wrongN) - Number(a.wrongN)).slice(0, 10);\n  const weakN = rcWeakCards().length;\n  const dictRate = tDict ? Math.round(tRight / tDict * 100) : 0;\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03));border-color:rgba(94,234,212,.3)\">\n    <h3>📊 背书统计</h3>\n    <div class=\"tiny mt6\">今日与累计数据都从背诵流水里算，全部存在本机。</div>\n  </div>\n  <div class=\"card\"><h3>今日</h3>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${tN}</div><div class=\"tiny\">背诵条数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600\">${tDict}</div><div class=\"tiny\">默写条数</div></div>\n      <div class=\"grow center\"><div style=\"font-size:18px;font-weight:600;color:${dictRate >= 80 ? 'var(--teal)' : (tDict ? 'var(--gold)' : 'inherit')}\">${tDict ? dictRate + '%' : '—'}</div><div class=\"tiny\">默写正确率</div></div>\n    </div>\n    <div class=\"row mt8\">\n      <div class=\"grow center\"><div style=\"font-size:15px\">${tNew}</div><div class=\"tiny\">新掌握</div></div>\n      <div class=\"grow center\"><div style=\"font-size:15px;color:var(--gold)\">${tWeak}</div><div class=\"tiny\">攻克薄弱</div></div>\n      <div class=\"grow center\"><div style=\"font-size:15px\">${tCoin}</div><div class=\"tiny\">获得币</div></div>\n    </div></div>\n  <div class=\"card\"><h3>累计</h3>\n    <div class=\"row mt10\">\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${rcBooks().filter(b => !b.archived).length}</div><div class=\"tiny\">词本</div></div>\n      <div class=\"grow center\"><div style=\"font-size:17px;font-weight:600\">${all.length}</div><div class=\"tiny\">卡片</div></div>\n      <div class=\"grow center\" data-act=\"gotoView\" data-view=\"rcweak\" style=\"cursor:pointer\">\n        <div style=\"font-size:17px;font-weight:600;color:${weakN ? 'var(--gold)' : 'inherit'};${weakN ? 'text-decoration:underline;text-underline-offset:3px;' : ''}\">${weakN}</div>\n        <div class=\"tiny\">薄弱${weakN ? ' ›' : ''}</div></div>\n    </div>\n    <div class=\"mt12\">${RC_LV.slice().reverse().map(l => {\n      const n = lvN(l.k);\n      const pct = Math.round(n / total * 100);\n      return `<div style=\"margin-bottom:7px\"><div class=\"row between\"><span class=\"tiny\" style=\"color:${l.color}\">${l.n}</span><span class=\"tiny\">${n} 张 · ${pct}%</span></div>\n        <div class=\"bar mt6\"><i style=\"width:${pct}%;background:${l.color}\"></i></div></div>`;\n    }).join('')}</div></div>\n  ${(function () {\n      /* 历史复盘：以前只显示当天那一条，过了零点就再也找不回来 */\n      const box = cfg('rcReviews') || {};\n      const keys = Object.keys(box).sort().reverse().filter(k => k !== dkey());\n      if (!keys.length) return '';\n      const open = String(S.draft.rcReviewOpen || '');\n      return `<div class=\"card\"><div class=\"row between\"><h3>📅 往期复盘（${keys.length} 天）</h3>\n        <span class=\"tiny\">共留档 ${keys.length + 1} 天</span></div>\n        <div class=\"mt8\">${keys.slice(0, 30).map(k => {\n          const r = box[k] || {};\n          const isOpen = open === k;\n          return `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:8px\">\n            <div data-act=\"rcReviewOpenDay\" data-k=\"${esc(k)}\" style=\"cursor:pointer\">\n              <div class=\"row between\"><span class=\"tiny\">${esc(k)} ${r.at ? hm(r.at) : ''}${r.byAI === false ? ' · 本地版' : ''}</span>\n                <span class=\"tiny\">${isOpen ? '收起 ▲' : '展开 ▼'}</span></div>\n              <div class=\"tiny mt6\">背 ${Number((r.stat || {}).total) || 0} 条 · 对 ${Number((r.stat || {}).right) || 0}${Number((r.stat || {}).wrong) ? ' · 错 ' + (r.stat || {}).wrong : ''}</div>\n            </div>\n            ${isOpen ? `<div style=\"font-size:12.8px;line-height:1.8;margin-top:8px;white-space:pre-wrap\">${esc(r.text || '')}</div>\n              <button class=\"btn sm ghost block mt8\" data-act=\"rcReviewDelDay\" data-k=\"${esc(k)}\">删掉这天的复盘</button>` : ''}\n          </div>`;\n        }).join('')}</div></div>`;\n    })()}\n  ${(rcAiOn('forget') && all.length >= 3) ? `<div class=\"card\">\n    <div class=\"row between\"><h3>🔮 快忘的卡片</h3><span class=\"tiny\">按等级 / 错误次数 / 上次复习距今推算</span></div>\n    ${S.draft.rcForgetNote ? `<div class=\"tiny mt6\" style=\"color:var(--teal)\">${esc(S.draft.rcForgetNote)}</div>\n      ${(S.draft.rcForgetList || []).length ? `<div class=\"mt6\">${S.draft.rcForgetList.slice(0, 8).map(x => `<div class=\"tiny\" style=\"font-size:12.6px;line-height:1.65\">· ${esc(String(x.q).slice(0, 46))} <span style=\"color:#ffb37a\">（${esc(x.why || '')}）</span></div>`).join('')}</div>` : ''}\n      <div class=\"tiny mt6\">标记已生效：下一轮不管用哪种序列，这些都会排到最前面先过一遍。</div>\n      ${(S.draft.rcForgetIds || []).length ? `<button class=\"btn primary block mt10\" data-act=\"rcForgetStart\">▶️ 先刷这几张（${S.draft.rcForgetIds.length}）</button>` : ''}\n      <button class=\"btn sm ghost block mt6\" data-act=\"rcForgetClear\">清掉标记</button>`\n      : `<div class=\"tiny mt6\">背过的卡片里，有些再不看就要忘了。让 AI 挑出来，挑完可以一键先刷它们。</div>\n      <button class=\"btn primary block mt10\" data-act=\"rcAiForgetBtn\" ${S.loading === 'rcforget' ? 'disabled' : ''}>${S.loading === 'rcforget' ? '正在推算…' : '🤖 预测哪些快忘了'}</button>`}\n  </div>` : ''}\n  ${hotTop.length ? `<div class=\"card\"><div class=\"row between\"><h3>高频易错 TOP${hotTop.length}</h3>\n    <span class=\"tiny\">按错误次数排</span></div>\n    ${hotTop.map((c, i) => `<div class=\"item\" style=\"padding:8px 0\">\n      <div class=\"ic\">${i + 1}</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px;line-height:1.55\">${esc(String(c.q).slice(0, 56))}</div>\n      <div class=\"tiny\">错 ${Number(c.wrongN)} 次 · ${esc(rcBookName(c.bookId))} · ${rcLvName(c.level)}</div></div></div>`).join('')}\n    </div>`\n    : `<div class=\"card\"><div class=\"empty\" style=\"padding:12px\">还没有出错的卡片。<br>背过一轮之后，错的会记进这里。</div></div>`}`;\n};\n/* ==========================================================\n   动作 · 背诵会话（翻转 / 评级 / 遮罩 / 倒计时 / 默写）\n   ========================================================== */\nObject.assign(ACTIONS, {\n  /* 接着上一轮背 —— 别再新建一轮把旧的连同没记的账一起丢掉 */\n  rcResume: () => {\n    if (!S.recite) { toast('那一轮已经不在了'); render(); return; }\n    if (!S.recite.lastSwitchAt) S.recite.lastSwitchAt = Date.now();\n    go('rcsession');\n  },\n  /* 在首页就把上一轮结掉：该记的账当场记 */\n  rcQuitFromHome: async () => {\n    const R = S.recite;\n    if (!R) { render(); return; }\n    const ok = await confirmBox('结束这一轮？', '已经评过级的 ' + (R.done || 0) + ' 条会记进统计，没轮到的下次再来。', '结束并记账');\n    if (!ok) return;\n    await rcFinishSession();\n  },\n  rcStart: el => {\n    if (S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) {\n      toast('你还有一轮没背完 —— 先「继续」，或点「结束并记账」把它结掉');\n      return;\n    }\n    S.draft.rcBookId = el.dataset.id;\n    rcStartSession('book', el.dataset.id);\n  },\n  rcStartWeak: () => {\n    const first = rcWeakCards()[0];\n    rcStartSession('weak', first ? first.bookId : '');\n  },\n  rcFlip: () => {\n    const R = S.recite; if (!R) return;\n    if (R.flipped) return;              // 已翻开就不再翻回来，避免误触\n    R.flipped = true; R.shownAt = Date.now();\n    S.draft.rcLineShown = 0;\n    S.draft.rcBlankShown = {};      // 翻新一张：挖空全部盖回去\n    render();\n  },\n  rcRevealLine: el => {\n    S.draft.rcLineShown = Math.max(Number(S.draft.rcLineShown || 0), Number(el.dataset.i) + 1);\n    render();\n  },\n  /* 挖空模式：单独揭开/盖回某一个空位 */\n  rcRevealBlank: el => {\n    const k = String(el.dataset.k || '');\n    if (!k) return;\n    S.draft.rcBlankShown = S.draft.rcBlankShown || {};\n    S.draft.rcBlankShown[k] = !S.draft.rcBlankShown[k];\n    render();\n  },\n  /* 判得不准时：当场去改这张卡片的关键词（编辑表单里就有「🤖 自动提关键词」） */\n  rcDictEditKeys: el => {\n    const c = rcCardById(el.dataset.id) || rcCurCard();\n    if (!c) return;\n    rcOpenCardEdit(c);\n    toast('把「提示关键词」拆成几个核心词，默写判分就按它们算');\n  },\n  rcSetOpt: el => {\n    const k = el.dataset.k;\n    const v = el.dataset.num === '1' ? Number(el.dataset.v) : el.dataset.v;\n    S.draft[k] = v;\n    if (k === 'rcMode') {\n      S.draft.rcMode = v;\n      if (v === 'weight') toast('已切到权重随机（薄弱的更容易出现）');\n      else if (v === 'pri') toast('已切到优先级分轮：焦点档主抽，其它档穿插');\n      else toast('已切到顺序模式');\n    }\n    if (k === 'rcTimerSec') S.draft.rcTimeUp = false;\n    if (k === 'rcStudy') S.draft.rcStudy = v;\n    render();\n  },\n  rcToggleTimer: () => {\n    S.draft.rcTimer = !S.draft.rcTimer;\n    S.draft.rcTimeUp = false;\n    if (S.draft.rcTimer) { S.draft.rcTimerSec = Number(S.draft.rcTimerSec || 5); rcStartTimer(); }\n    else rcStopTimer();\n    render();\n  },\n  rcToggleStrict: () => {\n    S.draft.rcStrict = !S.draft.rcStrict;\n    toast(S.draft.rcStrict ? '严格考试模式：超时自动记「模糊」，且不许跳过' : '已关掉严格考试模式');\n    render();\n  },\n  rcMoveBtn: el => rcMove(Number(el.dataset.s) || 1),\n  rcSkip: async () => { await rcSkipCard(); },\n  rcRateBtn: async el => { await rcRate(Number(el.dataset.k), false); },\n  rcQuit: async () => {\n    const R = S.recite;\n    if (!R) { go('rcbooks'); return; }\n    const ok = await confirmBox('结束这一轮？', '已经评过级的 ' + R.done + ' 条会记进统计，没轮到的下次再来。', '结束并记账');\n    if (!ok) return;\n    await rcFinishSession();\n  },\n  rcFinish: async () => { await rcFinishSession(); },\n  /* ---- 默写判分：关键词覆盖率匹配（本地，后续可接 AI 增强） ---- */\n  /* ---- AI 设置与背诵页 AI 按钮 ---- */\n  rcAiSheet: () => rcAiSheet(),\n  rcAiToggle: async el => {\n    const k = el.dataset.k;\n    const c = rcAiCfg();\n    c[k] = (k === 'on') ? !c.on : (c[k] === false);\n    S.settings.rcAI = c;\n    await saveSettings(true);\n    closeAllSheets();\n    if (k === 'on') toast(c.on ? 'AI 已开启' : 'AI 已全部关闭，所有功能走本地逻辑');\n    rcAiSheet();\n    render();\n  },\n  /* 只收起 AI 面板本身 —— 不要把 rcDictResult 也清掉。\n     清掉的话，正在「必须抄一遍」的那张会被这条路径绕过：面板一收，抄写要求就没了。 */\n  rcAiClose: () => { S.draft.rcAiShow = null; S.draft.rcVariant = null; render(); },\n  /* 这一组按钮以前会「静默失效」：节流命中时空返回、按钮又只是 return，\n     连点两下什么都不会发生也不报错 —— 看上去就是坏的。\n     现在节流拦下会明说，AI 没给出内容也会说清楚，不留死按钮。 */\n  /* 这三件套统一走「先看留存的，没有才生成」——\n     以前每点一次都重新问一遍 API，关掉就没了，等于白烧额度。 */\n  rcAiHintBtn: async () => { await rcAiAssist('hint'); },\n  rcAiExplainBtn: async () => { await rcAiAssist('explain'); },\n  rcAiCompareBtn: async () => { await rcAiAssist('compare'); },\n  /* 不满意就重新生成，覆盖留存的那份 */\n  rcAiShowRegen: async el => {\n    const k = String((el && el.dataset && el.dataset.k) || '');\n    await rcAiAssist(k, true);\n  },\n  /* 变式题也接进留存体系 ——\n     以前结果只放在 S.draft.rcVariant 里：一刷新、一换卡片就没了，\n     也从来没进过卡片，所以「生成过等于没生成」。\n     现在生成一次就写进卡片的 ai.variant，点开先看上次那组。 */\n  rcAiVariantBtn: async () => {\n    const c = rcCurCard(); if (!c) return;\n    const have = rcCardAiGet(c, 'variant');\n    if (have) {\n      S.draft.rcVariant = { id: c.id, list: (have.list || []).slice(), at: have.at };\n      S.draft.rcVariantShown = -1;\n      render();\n      return;\n    }\n    if (rcAiThrottled('variant')) { toast('刚出过一组，缓几秒再来'); return; }\n    const list = await rcAiVariant(c);\n    if (!list || !list.length) { toast('AI 没给出变式题 —— 再点一次试试'); return; }\n    await rcCardAiPut(c, 'variant', list);\n    S.draft.rcVariant = { id: c.id, list: list, at: Date.now() };\n    S.draft.rcVariantShown = -1;\n    toast('已生成并留在卡片上');\n    render();\n  },\n  rcVariantRegen: async () => {\n    const c = rcCurCard(); if (!c) return;\n    const ok = await confirmBox('重新出一组变式题？', '会覆盖这张卡片上留存的变式题（消耗一次 API）。', '重新生成');\n    if (!ok) return;\n    if (rcAiThrottled('variant')) { toast('缓几秒再来'); return; }\n    const list = await rcAiVariant(c);\n    if (!list || !list.length) { toast('AI 没给出变式题 —— 再点一次试试'); return; }\n    await rcCardAiPut(c, 'variant', list);\n    S.draft.rcVariant = { id: c.id, list: list, at: Date.now() };\n    S.draft.rcVariantShown = -1;\n    toast('已重新生成并留存');\n    render();\n  },\n  rcVariantShow: el => { S.draft.rcVariantShown = Number(el.dataset.i); render(); },\n  rcAiTranslateBtn: async () => {\n    const c = rcCurCard(); if (!c) return;\n    const out = await rcAiRewrite('translate', c);\n    if (!out) { toast('AI 没给出结果'); return; }\n    S.draft.rcAiShow = { id: c.id, text: '🔤 ' + out };\n    render();\n  },\n  rcDictAdjust: async el => {\n    const k = Number(el.dataset.k) || 0;\n    S.draft.rcDictResult = null;\n    await rcRate(k, true);\n  },\n  /* 词本页 / 薄弱页 / 统计页的 AI 入口 */\n  rcAiPlanBtn: async () => { await rcAiPlan(); },\n  /* ---- 今日计划清单：可去掉、可再加、清空 ---- */\n  rcPlanDrop: el => {\n    const id = String(el.dataset.id || '');\n    S.draft.rcPlanPick = (S.draft.rcPlanPick || []).filter(x => String(x) !== id);\n    toast('已从计划里去掉一条');\n    render();\n  },\n  rcPlanClear: () => { S.draft.rcPlanPick = []; render(); },\n  rcPlanAddMore: el => {\n    const n = clamp(Number(el.dataset.n) || 5, 1, 50);\n    const have = {};\n    (S.draft.rcPlanPick || []).forEach(id => { have[String(id)] = 1; });\n    const bk = rcBookById(S.draft.rcPlanBookId);\n    const pool = (bk ? rcCardsOf(bk.id) : rcCards()).filter(c => !have[String(c.id)]);\n    if (!pool.length) { toast('这个词本里的卡片都已在计划里了'); return; }\n    /* 补的规则和首次挑的一致：焦点档 / 薄弱优先，其余按「等级低 → 错得多 → 久没碰」 */\n    const score = c => {\n      const lv = Number(c.level || 0);\n      const pr = 2 - rcPriOf(c);\n      const w = Math.min(9, Number(c.wrongN || 0));\n      const days = c.lastAt ? Math.min(60, (Date.now() - Number(c.lastAt)) / 86400000) : 20;\n      return (3 - lv) * 10 + pr * 6 + w * 4 + days * 0.6 + (c.paused ? 5 : 0);\n    };\n    const add = pool.slice().sort((a, b) => score(b) - score(a)).slice(0, n).map(c => c.id);\n    S.draft.rcPlanPick = (S.draft.rcPlanPick || []).concat(add);\n    toast('又添了 ' + add.length + ' 条');\n    render();\n  },\n  /* 「就按这个开始」：AI 建议不再是一句空话 —— 点了直接把这批卡片摆成一轮背诵 */\n  rcPlanStart: () => {\n    if (S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) {\n      toast('你还有一轮没背完 —— 先「继续」，或点「结束并记账」把它结掉');\n      return;\n    }\n    /* 用你眼前这份清单 —— 里面可能已经手动去掉了几条、又添了几条，\n       开始时就该按你改过的来，不能偷偷退回 AI 原版。清单空了才现挑。 */\n    let ids = (S.draft.rcPlanPick || []).slice();\n    let bookId = S.draft.rcPlanBookId || '';\n    if (!ids.length) {\n      const p = rcPlanPick(S.draft.rcPlanAI);\n      ids = p.list.map(c => c.id);\n      bookId = p.book ? p.book.id : '';\n    }\n    const list = ids.map(rcCardById).filter(Boolean);\n    if (!list.length) { toast('现在没有可背的卡片'); return; }\n    rcApplyDefaults();\n    S.recite = {\n      scope: 'plan', bookId: bookId, queue: list.map(c => c.id), idx: 0,\n      flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n      done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n      newN: 0, weakBefore: rcWeakCards(bookId).length,\n      startedAt: Date.now(), touched: {}, log: []\n    };\n    toast('就按这个：' + list.length + ' 条');\n    go('rcsession');\n  },\n  rcAiReviewBtn: async () => { await rcAiReview(); },\n  /* 收藏今天的复盘 —— 走统一的收藏面板，能选文件夹 */\n  rcReviewFav: () => {\n    const rec = (cfg('rcReviews') || {})[dkey()] || null;\n    const text = rec ? rec.text : (S.draft.rcReviewAI || '');\n    if (!text) { toast('今天还没有复盘'); return; }\n    openFavPicker({ kind: 'report', title: '背书复盘 · ' + dkey(), content: text, charId: anyCharId() || '', from: '背书复盘' });\n  },\n  rcAiWeakBtn: async () => { await rcAiWeakAnalyze(); },\n  rcAiForgetBtn: async () => { await rcAiForget(); },\n  /* 「AI 组卷」的入口已经撤掉 —— 它的挑题能力并进了「🎤 让 TA 抽背」：\n     抽背现在按「优先级 + 错得多 + 久没碰 + 最近抽过的不再抽」来挑，不再纯随机。\n     这两个旧名字留着接住可能残留的调用：点了就打开抽背，不会变成死按钮。 */\n  rcAiPaperBtn: () => { ACTIONS.rcAiPetOpen(); },\n  rcAiPaperDo: () => { toast('组卷已并入「让 TA 抽背」—— 抽背时按薄弱和优先级挑题'); ACTIONS.rcAiPetOpen(); },\n  rcAiPetBtn: async () => { await rcAiPetAsk(); },\n  /* 抽背这屏以前一抽到就把答案印在面板上 —— 等于没考。\n     现在：TA 问 → 你写 → 提交判分 → 再决定记什么等级。 */\n  rcAiPetOpen: () => {\n    closeAllSheets();\n    const c = rcPetCardById(S.draft.rcPetCardId);\n    const R = S.draft.rcPetResult;\n    const shown = !!S.draft.rcPetShown;\n    openSheet(`<h3>🎤 让 TA 抽你一道</h3>\n      ${(S.chars && S.chars.length > 1) ? `<div class=\"tiny\">谁来抽你：</div>\n        <div class=\"chips mt6\">${S.chars.map(ch => `<button class=\"chip ${String(petCharId()) === String(ch.id) ? 'on' : ''}\" data-act=\"rcPetPickChar\" data-id=\"${esc(ch.id)}\">${esc(ch.name)}</button>`).join('')}</div>` : ''}\n      ${S.draft.rcPetLine ? `<div class=\"row mt8\"><div class=\"avatar\" style=\"background:linear-gradient(135deg,#7c8cff,#5eead4)\">💬</div>\n        <div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.6px;line-height:1.75\">${esc(S.draft.rcPetLine)}</div></div>` : `<div class=\"tiny mt6\">点下面让 TA 抽一条问你 —— 挑的是「该背的」：优先级高、错得多、久没碰的先抽，不再是纯随机。</div>`}\n      ${!c ? '' : (R ? `\n        <div class=\"tiny mt10\" style=\"line-height:1.7\">你写的：<span style=\"color:var(--dim)\">${esc(String(R.text || '').slice(0, 200))}</span></div>\n        <div class=\"row mt8\" style=\"gap:6px\">\n          <span class=\"pill ${R.lv >= 2 ? 'ok' : (R.lv === 1 ? 'warn' : 'bad')}\">${rcLvName(R.lv)}${R.byAI ? ' · TA 判' : ' · 本地判'}</span>\n          <span class=\"tiny\" style=\"align-self:center\">覆盖率 ${R.pct}%</span></div>\n        ${(R.hit || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">答到的：<span style=\"color:var(--teal)\">${esc(R.hit.join('、'))}</span></div>` : ''}\n        ${(R.miss || []).length ? `<div class=\"tiny mt6\" style=\"line-height:1.7;color:#ffb37a\">漏掉的：${esc(R.miss.join('、'))}</div>` : ''}\n        ${R.say ? `<div class=\"tiny mt6\" style=\"line-height:1.7\">${esc(R.say)}</div>` : ''}\n        <div class=\"tiny mt8\">题目</div>\n        <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.q || ''))}</div>\n        <div class=\"tiny mt8\">标准答案</div>\n        <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.a || '（这条没有答案）'))}</div>\n        <div class=\"row mt10\" style=\"gap:6px\">\n          <button class=\"btn sm primary grow\" data-act=\"rcPetRate\" data-k=\"2\">记得，记熟练</button>\n          <button class=\"btn sm grow\" data-act=\"rcPetRate\" data-k=\"1\">记模糊</button>\n          <button class=\"btn sm ghost grow\" data-act=\"rcPetRate\" data-k=\"0\">不会</button></div>\n        ${(R.miss || []).length ? `<button class=\"btn sm ghost block mt8\" data-act=\"rcPetTricky\">把漏掉的 ${R.miss.length} 个词标成易错词</button>` : ''}\n      ` : `\n        <div class=\"tiny mt10\" style=\"color:var(--dim2)\">凭记忆写下来 —— 先别看答案，写完提交让 TA 看。</div>\n        <textarea id=\"rcPetBox\" style=\"min-height:96px;margin-top:8px\" placeholder=\"写下你记得的内容，写不全也没关系\">${esc(S.draft.rcPetText || '')}</textarea>\n        <button class=\"btn primary block mt10\" data-act=\"rcPetSubmit\" ${S.loading === 'rcpetgrade' ? 'disabled' : ''}>${S.loading === 'rcpetgrade' ? 'TA 正在看…' : '提交，让 TA 看看'}</button>\n        <button class=\"btn block ghost sm mt8\" data-act=\"rcPetReveal\">${shown ? '藏起答案' : '想不起来，看答案'}</button>\n        ${shown ? `<div class=\"tiny mt8\">题目</div>\n        <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.q || ''))}</div>\n        <div class=\"tiny mt8\">答案</div>\n        <div class=\"mt6\" style=\"background:var(--card2);border-radius:10px;padding:10px;font-size:13px;line-height:1.85;white-space:pre-wrap\">${esc(String(c.a || ''))}</div>` : ''}\n      `)}\n      <div class=\"row mt12\" style=\"gap:8px\">\n        <button class=\"btn grow\" data-act=\"rcAiPetBtn\" ${S.loading === 'rcpet' ? 'disabled' : ''}>${S.loading === 'rcpet' ? '正在抽…' : '🎲 再抽一条'}</button>\n        <button class=\"btn ghost grow\" data-act=\"closeSheet\">收起</button></div>`);\n  },\n  rcPetReveal: () => {\n    const c = rcPetCardById(S.draft.rcPetCardId);\n    if (!c) { toast('还没抽到卡片'); return; }\n    S.draft.rcPetShown = !S.draft.rcPetShown;\n    rcAiPetOpen();\n  },\n  rcPetPickChar: el => {\n    S.draft.rcPetCharId = el.dataset.id;\n    S.draft.rcPetLine = '';      // 换了人，上一句就不是他说的了\n    rcAiPetOpen();\n  },\n  rcPetSubmit: async () => {\n    const c = rcPetCardById(S.draft.rcPetCardId);\n    if (!c) { toast('还没抽到卡片'); return; }\n    const box = document.getElementById('rcPetBox');\n    const text = (box ? (box.value || '') : String(S.draft.rcPetText || '')).slice(0, 500);\n    S.draft.rcPetText = text;\n    if (!text.trim()) { toast('先写下你的答案'); return; }\n    const local = rcMatchAnswer(text, c);\n    let lv = local.rate, hit = local.hit || [], miss = (local.miss || []).slice(), say = '', byAI = false;\n    if (rcAiOn('grade') && text.trim().length >= 4) {\n      S.loading = 'rcpetgrade'; rcAiPetOpen();\n      try {\n        const g = await rcAiGrade(c, text);\n        if (g) { lv = g.lv; byAI = true; if (g.miss && g.miss.length) miss = miss.concat(g.miss).slice(0, 8); say = g.say || ''; }\n      } finally { S.loading = ''; }\n    }\n    S.draft.rcPetResult = { lv: lv, pct: local.pct, hit: hit, miss: miss, say: say, byAI: byAI, text: text };\n    rcAiPetOpen();\n    toast(byAI ? 'TA 判完：' + rcLvName(lv) : '覆盖率 ' + local.pct + '%');\n  },\n  rcPetRate: async el => {\n    const c = rcPetCardById(S.draft.rcPetCardId);\n    if (!c) return;\n    const lv = clamp(Number(el.dataset.k) || 0, 0, 3);\n    const before = Number(c.level) || 0;\n    if (lv >= 2) { c.rightN = Number(c.rightN || 0) + 1; c.streak = Number(c.streak || 0) + 1; c.paused = false; }\n    else { c.wrongN = Number(c.wrongN || 0) + 1; c.streak = 0; c.paused = true; }\n    c.level = lv; c.lastAt = Date.now();\n    await rcSaveCard(c);\n    toast('已记为「' + rcLvName(lv) + '」' + (before < 2 && lv >= 2 ? '（达成熟练以上）' : ''));\n    S.draft.rcPetResult = null; S.draft.rcPetText = ''; S.draft.rcPetShown = false;\n    render(); rcAiPetOpen();\n  },\n  rcPetTricky: async () => {\n    const c = rcPetCardById(S.draft.rcPetCardId);\n    const R = S.draft.rcPetResult;\n    if (!c || !R) return;\n    const list = (R.miss || []).map(x => String(x).replace(/（部分）$/, '').trim()).filter(Boolean);\n    if (!list.length) { toast('这次没有漏掉的词'); return; }\n    const cur = (c.tricky || []).slice();\n    list.forEach(k => { if (cur.indexOf(k) < 0) cur.push(k); });\n    c.tricky = cur;\n    await rcSaveCard(c);\n    toast('已标 ' + list.length + ' 个易错词 —— 背这张时会挖空考你');\n    rcAiPetOpen();\n  },\n  /* 默写提交：先本地按关键词覆盖率算一遍，再让 AI 补一次主观判分（关了 AI 就纯本地）。\n     判完不立刻翻卡 —— 先把结果摆出来（命中/漏掉/写错 + 标准答案），\n     由你点「就按这个记」或改一档再继续。这样也不会出现「结果一闪就被下一张顶掉」。 */\n  rcDictSubmit: async () => {\n    const R = S.recite, c = rcCurCard();\n    if (!R || !c) return;\n    const box = document.getElementById('rcDictBox');\n    const text = box ? (box.value || '').slice(0, 500) : String(S.draft.rcDictText || '').slice(0, 500);\n    S.draft.rcDictText = text;\n    if (!text.trim()) { toast('一个字都没写 —— 这次按「不会」记'); await rcRate(0, true); return; }\n    const local = rcMatchAnswer(text, c);\n    let res = local.rate, pct = local.pct, hit = local.hit || [], miss = (local.miss || []).slice();\n    let wrong = [], say = '', byAI = false, score = 0;\n    if (rcAiOn('grade') && text.trim().length >= 4) {\n      S.loading = 'rcgrade'; render();\n      try {\n        const g = await rcAiGrade(c, text);\n        if (g) {\n          res = g.lv; byAI = true; score = g.score || 0;\n          if (g.miss && g.miss.length) miss = miss.concat(g.miss).slice(0, 8);\n          wrong = g.wrong || [];\n          say = g.say || '';\n        }\n      } finally { S.loading = ''; }\n    }\n    /* 存一条默写记录：之后能在卡片里回看「我上次是怎么写的」，\n       并把这次漏掉的词收成易错词 —— 它们之后会被挖空考。\n       只留最近 5 条，别让卡片越来越重。 */\n    /* 要不要先抄一遍：三档开关，见背书设置 */\n    const needCopy = rcNeedCopyFor(res, c);\n    const missClean = miss.map(x => String(x).replace(/（部分）$/, '').trim()).filter(Boolean).slice(0, 8);\n    if (missClean.length || res < 2) {\n      c.mistakes = (c.mistakes || []).concat([{\n        at: Date.now(), text: text.slice(0, 400), miss: missClean, pct: pct, lv: res\n      }]).slice(-5);\n      await rcSaveCard(c);\n    }\n    S.draft.rcDictResult = {\n      id: c.id, lv: res, pct: pct, hit: hit, miss: miss, wrong: wrong,\n      say: say, byAI: byAI, score: score, text: text, needCopy: needCopy, copied: false\n    };\n    if (needCopy) S.draft.rcCopyText = '';\n    render();\n    toast(needCopy\n      ? '先抄一遍正确答案再继续'\n      : (byAI ? 'AI 判完：' + (res >= 2 ? '熟练' : res === 1 ? '模糊' : '不会') : '覆盖率 ' + pct + '%'));\n  },\n  /* 抄完校验：够像才放行 */\n  rcDictCopyDone: async el => {\n    const c = rcCardById(el.dataset.id) || rcCurCard();\n    const R = S.draft.rcDictResult;\n    if (!c || !R) return;\n    const box = document.getElementById('rcCopyBox');\n    const text = box ? (box.value || '') : String(S.draft.rcCopyText || '');\n    S.draft.rcCopyText = text;\n    if (!text.trim()) { toast('先照着上面抄一遍'); return; }\n    const r = rcCopyRate(text, c.a);\n    if (!r.ok) { toast('还差一点（相似 ' + r.pct + '%）—— 再对照着把漏掉的补上'); return; }\n    R.copied = true;\n    S.draft.rcCopyText = '';\n    render();\n    toast('抄完了，可以继续');\n  },\n  /* 把这次默写漏掉的词收成易错词 —— 从「错了」直接到「专门练它」 */\n  rcDictTricky: async () => {\n    const c = rcCurCard();\n    const R = S.draft.rcDictResult;\n    if (!c || !R) return;\n    const list = (R.miss || []).map(x => String(x).replace(/（部分）$/, '').trim()).filter(Boolean);\n    if (!list.length) { toast('这次没有漏掉的词'); return; }\n    const cur = (c.tricky || []).slice();\n    let add = 0;\n    list.forEach(k => { if (cur.indexOf(k) < 0) { cur.push(k); add++; } });\n    c.tricky = cur;\n    await rcSaveCard(c);\n    toast(add ? ('已收进 ' + add + ' 个易错词 —— 背这张时切「挖空」就能考它们') : '这些词已经在易错词里了');\n    render();\n  },\n  rcDictConfirm: async () => {\n    const r = S.draft.rcDictResult;\n    if (!r) return;\n    const lv = Number(r.lv) || 0;\n    S.draft.rcDictResult = null;\n    S.draft.rcDictText = '';\n    /* 这张已经判完并记档了，草稿就不必留着 */\n    if (S.draft.rcDictBy && r.id) delete S.draft.rcDictBy[r.id];\n    await rcRate(lv, true);\n  },\n});\n/* 关键词覆盖率：优先用卡片自定义关键词，没有就从答案里自动拆 */\n/* 不该拿来当关键词的碎块：纯数字 / 纯标点 / 整块都是虚字 */\nfunction rcBadKeyword(k) {\n  const s = String(k || '').trim();\n  if (s.length < 2) return true;\n  if (/^[\\d\\s\\W_]+$/.test(s)) return true;\n  if (/^[的是了在和与及或也就都还只被把给对向从到由因为所以这样那样一个我们他们它这个那个]+$/.test(s)) return true;\n  return false;\n}\nfunction rcKeywords(c) {\n  /* ① 卡片自己写了关键词 —— 永远优先，这是最准的一份 */\n  const raw = String((c && c.hint) || '').split(/[,，、;；\\s|／/]+/)\n    .map(x => x.trim().replace(/^[（(【\\[「『\"']+|[）)】\\]」』\"']+$/g, '').trim())\n    .filter(x => !rcBadKeyword(x));\n  if (raw.length) {\n    const seen = {}, out = [];\n    raw.forEach(x => { const k = norm(x); if (k && !seen[k]) { seen[k] = 1; out.push(x); } });\n    return out.slice(0, 12);\n  }\n  /* ② 没写关键词才从答案里拆。以前是机械取「前 4 字 + 后 4 字」——\n        会切出纯虚字、纯数字、跨词的碎片，这是「关键词不准」的头号原因。\n        现在：先掐掉句首虚字，短句整句当关键词，长句只取头尾并且过一遍过滤。 */\n  const a = String((c && c.a) || '');\n  const segs = a.split(/[，,。.、；;：:！!？?\\n（）()【】\\[\\]「」“”\"'—…]+/)\n    .map(x => x.trim()).filter(x => x.length >= 2);\n  const out = [];\n  segs.forEach(s => {\n    const t = s.replace(/^[的是了在和与及或就都还也又则并，。]+/, '').trim();\n    if (t.length < 2) return;\n    if (t.length <= 8) { if (!rcBadKeyword(t)) out.push(t); return; }\n    const head = t.slice(0, 4), tail = t.slice(-4);\n    if (!rcBadKeyword(head)) out.push(head);\n    if (!rcBadKeyword(tail) && tail !== head) out.push(tail);\n  });\n  const seen = {}, uniq = [];\n  out.forEach(x => { const k = norm(x); if (k && !seen[k]) { seen[k] = 1; uniq.push(x); } });\n  return uniq.slice(0, 10);\n}\nfunction rcMatchAnswer(input, c) {\n  const u = norm(String(input || ''));\n  const ks = rcKeywords(c).map(k => ({ raw: k, n: norm(k) })).filter(x => x.n);\n  if (!ks.length) {\n    /* 没有关键词可比：退回「答案包含多少」的粗判 */\n    const a = norm(String((c && c.a) || ''));\n    if (!a) return { pct: u ? 100 : 0, rate: u ? 2 : 0, hit: [], miss: [] };\n    const pct = u ? Math.round(Math.min(1, u.length / a.length) * 100) : 0;\n    return { pct: pct, rate: pct >= 85 ? 2 : (pct >= 50 ? 1 : 0), hit: [], miss: [] };\n  }\n  /* 判分两档：整词命中满分；只对上一大半（用户换了说法、少写中间几个字）给半分。\n     以前是「要么整词原样出现、要么算漏」—— 所以「意思写对了但用词不同」全被判不会，\n     这正是「识别关键词不准」的第二个原因。 */\n  const hit = [], miss = [];\n  let score = 0;\n  ks.forEach(k => {\n    if (!k.n) return;\n    if (u.indexOf(k.n) >= 0) { hit.push(k.raw); score += 1; return; }\n    if (k.n.length >= 4) {\n      const cut = Math.max(2, Math.ceil(k.n.length * 0.6));\n      const head = k.n.slice(0, cut), tail = k.n.slice(-cut);\n      if ((head.length >= 2 && u.indexOf(head) >= 0) || (tail.length >= 2 && tail !== head && u.indexOf(tail) >= 0)) {\n        hit.push(k.raw + '（部分）'); score += 0.5; return;\n      }\n    }\n    miss.push(k.raw);\n  });\n  const pct = Math.round(score / ks.length * 100);\n  return { pct: pct, rate: pct >= 85 ? 2 : (pct >= 50 ? 1 : 0), hit: hit, miss: miss };\n}\n/* 抄写校验：把用户抄的内容和标准答案比一比，够像才放行。\n   用最长公共子序列（LCS）算相似度 —— 比「逐字对齐」宽容，错一个字不会全崩；\n   再配一道长度下限，防止「只抄了开头一半」也混过去。 */\nfunction rcCopyRate(input, answer) {\n  const u = norm(String(input || ''));\n  const a = norm(String(answer || ''));\n  if (!a) return { ok: true, pct: 100 };          // 这张卡本来就没答案，没法抄\n  if (!u) return { ok: false, pct: 0 };\n  if (u === a) return { ok: true, pct: 100 };\n  const n = u.length, m = a.length;\n  let match = 0;\n  if (n * m <= 400000) {                          // 太长的就退化为「字符集合」粗算，别卡住页面\n    let prev = new Uint16Array(m + 1), cur = new Uint16Array(m + 1);\n    for (let i = 1; i <= n; i++) {\n      for (let j = 1; j <= m; j++) {\n        cur[j] = (u[i - 1] === a[j - 1]) ? (prev[j - 1] + 1) : (prev[j] > cur[j - 1] ? prev[j] : cur[j - 1]);\n      }\n      const t = prev; prev = cur; cur = t;\n      cur.fill(0);\n    }\n    match = prev[m];\n  } else {\n    const set = {};\n    for (let i = 0; i < n; i++) set[u[i]] = 1;\n    for (let i = 0; i < m; i++) if (set[a[i]]) match++;\n  }\n  const pct = Math.round(match / m * 100);\n  const ok = pct >= 90 && n >= m * 0.85;\n  return { ok: ok, pct: pct };\n}\n/* 这条判分要不要先抄一遍？三档开关统一在这里判，别在两处各写一遍 */\nfunction rcNeedCopyFor(res, card) {\n  const mode = String(cfg('rcCopyMode') || 'off');\n  if (mode === 'off') return false;\n  if (!card || !String(card.a || '').trim()) return false;   // 本来就没答案，没法抄\n  return mode === 'notMaster' ? Number(res) < 3 : Number(res) < 2;\n}\n/* ==========================================================\n   背诵倒计时｜考试压力模式\n   ----------------------------------------------------------\n   普通模式：超时自动翻开卡片，由你自己评级；\n   严格考试：超时直接记「模糊」，且不允许跳过。\n   ========================================================== */\nlet rcTimerId = null, rcTimerEndAt = 0;\nasync function rcOnTimeout() {\n  const R = S.recite;\n  rcStopTimer();\n  S.draft.rcTimeUp = true;\n  if (!R) { render(); return; }\n  if (S.draft.rcStrict) {\n    /* 默写 + 开了抄写规则时，超时不能靠「自动判模糊」躲过去 ——\n       照样要把正确答案抄一遍才放行。 */\n    const cc = (S.draft.rcStudy === 'dict') ? rcCurCard() : null;\n    if (cc && rcNeedCopyFor(1, cc)) {\n      S.draft.rcDictResult = {\n        id: cc.id, lv: 1, pct: 0, hit: [], miss: [], wrong: [],\n        say: '时间到，没写出来 —— 先照着标准答案抄一遍。', byAI: false, score: 0, text: '',\n        needCopy: true, copied: false\n      };\n      S.draft.rcCopyText = '';\n      render();\n      return;\n    }\n    await rcRate(1, true);\n    return;                              // 严格模式：自动记模糊\n  }\n  if (!R.flipped) { R.flipped = true; R.shownAt = Date.now(); }\n  S.draft.rcLineShown = 0;\n  render();\n}\nfunction rcStartTimer() {\n  rcStopTimer();\n  const R = S.recite;\n  if (!R || !S.draft.rcTimer) return;\n  const secs = Math.max(1, Number(S.draft.rcTimerSec || 5));\n  S.draft.rcTimeUp = false;\n  rcTimerEndAt = Date.now() + secs * 1000;\n  S.draft.rcTimePct = 100;\n  rcTimerId = setInterval(() => {\n    if (!S.recite || !S.draft.rcTimer) { rcStopTimer(); return; }\n    const left = rcTimerEndAt - Date.now();\n    const pct = clamp(left / (secs * 1000) * 100, 0, 100);\n    S.draft.rcTimePct = pct;\n    const bar = document.getElementById('rcTimeBar');\n    if (bar) bar.style.width = pct + '%';\n    if (left <= 0) { rcOnTimeout(); }\n  }, 200);\n}\nfunction rcStopTimer() {\n  if (rcTimerId) { clearInterval(rcTimerId); rcTimerId = null; }\n}\n/* 每次重画背诵页之后，重启这一条的计时 */\nfunction rcRestartTimerIfNeeded() {\n  if (S.view !== 'rcsession') { rcStopTimer(); return; }\n  if (S.draft.rcTimer) { rcStartTimer(); } else { rcStopTimer(); }\n}\n/* ==========================================================\n   背书模块 · AI 辅助内核\n   ----------------------------------------------------------\n   ① 总开关 + 分开关：总开关关掉后，任何 AI 按钮都不会发请求；\n   ② 全部只做「增强」，失败/超时就静默降级回本地逻辑，绝不阻断背诵；\n   ③ 输出永远先预览、由用户确认，不直接写库；\n   ④ 单次输入限长 + 同类操作节流，防止短时间刷爆 API 额度。\n   ========================================================== */\nfunction rcAiCfg() {\n  const d = {\n    on: true, gen: true, key: true, edit: true, hint: true, explain: true,\n    compare: true, grade: true, variant: true, weak: true, paper: true,\n    forget: true, plan: true, review: true, pet: true\n  };\n  const cur = cfg('rcAI');\n  return Object.assign({}, d, (cur && typeof cur === 'object') ? cur : {});\n}\n/* 某一项能不能用：总开关 + 分开关 + 有没有角色（角色用于解析模型配置） */\nfunction rcAiOn(k) {\n  const c = rcAiCfg();\n  if (!c.on) return false;\n  if (k && c[k] === false) return false;\n  return !!anyCharId();\n}\nasync function rcAiSet(k, v) {\n  const c = rcAiCfg();\n  c[k] = v;\n  S.settings.rcAI = c;\n  await saveSettings(true);\n}\n/* 节流：同一类操作 6 秒内最多一次（防止连点把额度刷光） */\nconst rcAiLast = {};\nfunction rcAiThrottled(k) {\n  const now = Date.now();\n  if (rcAiLast[k] && now - rcAiLast[k] < 6000) return true;\n  rcAiLast[k] = now;\n  return false;\n}\n/* 统一的 AI 调用：走普通助手通道（不扮演角色），失败返回空串并降级 */\nasync function rcAi(id, vars, opt) {\n  opt = opt || {};\n  if (!rcAiOn(opt.gate)) return '';\n  const cid = anyCharId();\n  if (!cid) return '';\n  try {\n    const t = await pGen(id, vars, [cid], undefined, true);   // plain=true：普通模型，不注入人设\n    return String(t || '').trim();\n  } catch (e) {\n    if (!opt.silent) toast('AI 没答应（已按本地逻辑继续）');\n    return '';\n  }\n}\nconst rcAiBusy = {};\nfunction rcAiLock(k) { if (rcAiBusy[k]) return false; rcAiBusy[k] = 1; return true; }\nfunction rcAiUnlock(k) { rcAiBusy[k] = 0; }\n/* ---------- 1. AI 拆题生成卡片（录入阶段） ---------- */\nasync function rcAiGenCards(text, kind) {\n  if (!rcAiOn('gen')) { toast('AI 生成卡片已在背书设置里关掉'); return null; }\n  text = String(text || '').slice(0, 3000);\n  if (!text.trim()) { toast('先粘一段材料进去'); return null; }\n  if (!rcAiLock('gen')) { toast('正在拆题，稍等一下'); return null; }\n  S.loading = 'rcgen'; render();\n  let out = '';\n  try {\n    out = await rcAi('rc.gen', { text: text, kind: kind || '名词解释', count: 30 }, { gate: 'gen' });\n  } finally { rcAiUnlock('gen'); S.loading = ''; }\n  const data = parseJSON(out);\n  const arr = Array.isArray(data) ? data : ((data && (data.questions || data.cards)) || []);\n  const list = (arr || []).map(x => ({\n    q: String((x && (x.question || x.q)) || '').trim(),\n    a: String((x && (x.answer || x.a)) || '').trim(),\n    hint: String((x && (x.hint || x.keywords)) || '').trim()\n  })).filter(x => x.q).slice(0, 200);\n  render();\n  if (!list.length) { toast('AI 没给出可用的卡片，可以换个说法再试，或手动录入'); return null; }\n  return list;\n}\n/* ---------- 2. AI 提取关键词 ---------- */\nasync function rcAiKeywords(c) {\n  if (!c) return '';\n  if (!rcAiOn('key')) { toast('AI 提取关键词已关掉'); return ''; }\n  if (rcAiThrottled('key')) { toast('刚提过一次，缓一下再来'); return ''; }\n  const out = await rcAi('rc.keywords', {\n    question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200)\n  }, { gate: 'key' });\n  return String(out || '').replace(/[\\n\\r]+/g, ' ').replace(/^[\\s,，、]+|[\\s,，、]+$/g, '').slice(0, 160);\n}\n/* ---------- 3. 精简 / 扩展 / 口诀 / 翻译（结果只回显，不动原内容） ---------- */\nasync function rcAiRewrite(kind, c) {\n  if (!c) return '';\n  if (!rcAiOn('edit')) { toast('AI 改写已关掉'); return ''; }\n  const map = {\n    compress: ['rc.compress', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1500) }],\n    expand: ['rc.expand', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200) }],\n    mnemonic: ['rc.mnemonic', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200) }],\n    translate: ['rc.translate', { question: String(c.q || '').slice(0, 200) }]\n  }[kind];\n  if (!map) return '';\n  if (!rcAiLock('edit')) { toast('正在生成，稍等一下'); return ''; }\n  S.loading = 'rcedit'; render();\n  let out = '';\n  try { out = await rcAi(map[0], map[1], { gate: 'edit' }); }\n  finally { rcAiUnlock('edit'); S.loading = ''; }\n  render();\n  return String(out || '').trim();\n}\n/* ==========================================================\n   卡片上的 AI 辅助（启发提示 / 通俗解释 / 易混辨析）\n   ----------------------------------------------------------\n   · 生成过一次就留在卡片里（c.ai.hint / explain / compare）；\n   · 点开先看上次生成的那份，不满意再点「重新生成」；\n   · 没生成过才去问 API —— 不再每点一次都烧一次额度。\n   变式题另有一套（列表结构，走 rcAiVariantBtn）。\n   ========================================================== */\nasync function rcAiAssist(kind, force) {\n  const c = rcCurCard();\n  if (!c) return '';\n  const gateMap = { hint: 'hint', explain: 'explain', compare: 'compare' };\n  const icoMap = { hint: '💡 ', explain: '📖 ', compare: '🔀 ' };\n  const tipMap = { hint: '启发提示', explain: '通俗解释', compare: '易混辨析' };\n  const gate = gateMap[kind] || 'hint';\n  /* ① 没让重新生成：先看留存的 */\n  if (!force) {\n    const have = rcCardAiGet(c, kind);\n    if (have) {\n      S.draft.rcAiShow = { id: c.id, kind: kind, text: icoMap[kind] + have.text, at: have.at, fromSaving: true };\n      render();\n      return have.text;\n    }\n  }\n  if (force) {\n    const ok = await confirmBox('重新生成「' + tipMap[kind] + '」？', '会覆盖这张卡片上留存的那份（消耗一次 API）。', '重新生成');\n    if (!ok) { S.draft.rcAiShow = null; render(); return ''; }\n  }\n  if (rcAiThrottled(kind)) { toast('刚问过一次，缓几秒再问（省 API 额度）'); return ''; }\n  let out = '';\n  try {\n    if (kind === 'hint') out = await rcAiHint(c);\n    else if (kind === 'explain') out = await rcAiExplain(c);\n    else if (kind === 'compare') out = await rcAiCompare(c);\n  } catch (e) { out = ''; }\n  if (!out) {\n    toast(kind === 'hint' ? '这次没拿到提示 —— 可以看卡片自带的提示关键词' : 'AI 这次没给出内容 —— 再点一次试试');\n    render();\n    return '';\n  }\n  await rcCardAiPut(c, kind, out);\n  S.draft.rcAiShow = { id: c.id, kind: kind, text: icoMap[kind] + out, at: Date.now() };\n  toast('已生成并留在卡片上');\n  render();\n  return out;\n}\n/* ---------- 4. AI 启发提示（绝不泄露答案） ---------- */\nasync function rcAiHint(c) {\n  if (!c) return '';\n  if (!rcAiOn('hint')) { toast('AI 提示已关掉，可以看卡片自带的提示关键词'); return ''; }\n  /* ⚠️ 这一行原来还有一次 rcAiThrottled('hint')。但调用方 rcAiAssist 在走进来之前\n     已经给 'hint' 打过一次节流标记（同一个 6 秒窗口），紧接着这里再查一次必然命中，\n     于是每次点「启发提示」都在这一行被拦下、返回空串 —— 表现就是\n     「点了没反应 / 总是提示这次没拿到」。节流统一交给 rcAiAssist 管，这里不再重复拦。 */\n  S.loading = 'rchint'; render();\n  let out = '';\n  try {\n    out = await rcAi('rc.hint', {\n      question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200),\n      keywords: rcKeywords(c).join('、').slice(0, 120)\n    }, { gate: 'hint' });\n  } finally { S.loading = ''; render(); }\n  /* 兜底：万一模型还是把答案吐出来了，这里再拦一道 */\n  const a = norm(String(c.a || ''));\n  if (out && a && a.length > 6) {\n    const body = norm(out);\n    if (body.length > 20 && a.indexOf(body.slice(0, 20)) >= 0) {\n      return '（这次提示不太合适，已经拦下了）想想它在哪一章、解决的是什么问题，先从那几个角度回忆。';\n    }\n  }\n  return out;\n}\n/* ---------- 5. AI 判分（可降级回本地关键词匹配） ---------- */\nasync function rcAiGrade(c, input) {\n  if (!c || !rcAiOn('grade')) return null;\n  if (rcAiThrottled('grade')) return null;\n  const out = await rcAi('rc.grade', {\n    question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1500),\n    input: String(input || '').slice(0, 500), keywords: rcKeywords(c).join('、').slice(0, 120)\n  }, { gate: 'grade', silent: true });\n  const d = parseJSON(out);\n  if (!d || !d.level) return null;\n  const lvTxt = String(d.level);\n  const lv = lvTxt.indexOf('熟练') >= 0 ? 2 : (lvTxt.indexOf('模糊') >= 0 ? 1 : 0);\n  return {\n    lv: lv, score: Number(d.score) || 0,\n    miss: Array.isArray(d.miss) ? d.miss.map(String).slice(0, 5) : [],\n    wrong: Array.isArray(d.wrong) ? d.wrong.map(String).slice(0, 5) : [],\n    say: String(d.say || '').slice(0, 80)\n  };\n}\n/* ---------- 6. 其余 AI 能力（解释 / 辨析 / 变式 / 薄弱 / 组卷 / 遗忘 / 计划 / 复盘 / 抽背） ---------- */\nasync function rcAiExplain(c) {\n  if (!c || !rcAiOn('explain')) { if (!rcAiOn('explain')) toast('AI 解释已关掉'); return ''; }\n  S.loading = 'rcexplain'; render();\n  let out = '';\n  try { out = await rcAi('rc.explain', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200) }, { gate: 'explain' }); }\n  finally { S.loading = ''; render(); }\n  return out;\n}\nasync function rcAiCompare(c) {\n  if (!c || !rcAiOn('compare')) { if (!rcAiOn('compare')) toast('AI 辨析已关掉'); return ''; }\n  S.loading = 'rccompare'; render();\n  let out = '';\n  try { out = await rcAi('rc.compare', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200) }, { gate: 'compare' }); }\n  finally { S.loading = ''; render(); }\n  return out;\n}\nasync function rcAiVariant(c) {\n  if (!c || !rcAiOn('variant')) { if (!rcAiOn('variant')) toast('AI 变式题已关掉'); return null; }\n  S.loading = 'rcvariant'; render();\n  let out = '';\n  try { out = await rcAi('rc.variant', { question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 1200), n: 2 }, { gate: 'variant' }); }\n  finally { S.loading = ''; render(); }\n  const d = parseJSON(out);\n  const arr = Array.isArray(d) ? d : ((d && d.questions) || []);\n  return (arr || []).map(x => ({ q: String((x && (x.q || x.question)) || ''), a: String((x && (x.a || x.answer)) || '') })).filter(x => x.q).slice(0, 5);\n}\n/* 薄弱分析：输出到统计面板 */\nasync function rcAiWeakAnalyze() {\n  if (!rcAiOn('weak')) { toast('AI 薄弱分析已关掉'); return ''; }\n  const hot = rcCards().filter(c => Number(c.wrongN || 0) > 0).sort((a, b) => Number(b.wrongN) - Number(a.wrongN)).slice(0, 30);\n  if (!hot.length) { toast('还没有出错记录，先背一轮'); return ''; }\n  if (!rcAiLock('weak')) return '';\n  S.loading = 'rcweak'; render();\n  let out = '';\n  try {\n    out = await rcAi('rc.weak', {\n      list: hot.map((c, i) => (i + 1) + '. [' + rcLvName(c.level) + ' 错' + Number(c.wrongN || 0) + '次] ' + String(c.q || '').slice(0, 60)).join('\\n'),\n      stats: '共 ' + rcCards().length + ' 张卡片，其中薄弱 ' + rcWeakCards().length + ' 张'\n    }, { gate: 'weak' });\n  } finally { rcAiUnlock('weak'); S.loading = ''; }\n  const d = parseJSON(out);\n  render();\n  if (!d || !d.summary) { toast('AI 没给出分析（已保留本地统计）'); return ''; }\n  S.draft.rcWeakAI = d;\n  S.draft.rcWeakAIAt = Date.now();\n  render();\n  return d.summary;\n}\n/* 组卷：AI 从候选里挑题，然后直接进背诵 */\nasync function rcAiPaper(mode) {\n  if (!rcAiOn('paper')) { toast('AI 组卷已关掉'); return; }\n  const pool = rcCards();\n  if (pool.length < 2) { toast('卡片太少，先多录几张'); return; }\n  if (!rcAiLock('paper')) return;\n  S.loading = 'rcpaper'; render();\n  const cand = pool.slice(0, 120);\n  let out = '';\n  try {\n    out = await rcAi('rc.paper', {\n      mode: mode || '查漏补缺卷', n: clamp(Math.round(pool.length * 0.15) + 5, 5, 30),\n      list: cand.map((c, i) => (i + 1) + '. [' + rcLvName(c.level) + '｜错' + Number(c.wrongN || 0) + '] ' + String(c.q || '').slice(0, 50)).join('\\n')\n    }, { gate: 'paper' });\n  } finally { rcAiUnlock('paper'); S.loading = ''; }\n  const d = parseJSON(out);\n  render();\n  const ids = (d && Array.isArray(d.ids)) ? d.ids : [];\n  const picked = ids.map(n => cand[Number(n) - 1]).filter(Boolean);\n  if (!picked.length) { toast('AI 没挑出可用的卡片，已退回按薄弱直接开背'); await rcStartSession('weak', ''); return; }\n  const uniq = {}, list = [];\n  picked.forEach(c => { if (!uniq[c.id]) { uniq[c.id] = 1; list.push(c); } });\n  S.recite = {\n    scope: 'paper', bookId: '', queue: list.map(c => c.id), idx: 0,\n    flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n    done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n    newN: 0, weakBefore: rcWeakCards('').length, startedAt: Date.now(), touched: {}, log: [],\n    paperWhy: (d && d.why) ? String(d.why).slice(0, 60) : ''\n  };\n  toast('已组卷 ' + list.length + ' 张' + (S.recite.paperWhy ? '：' + S.recite.paperWhy : ''));\n  go('rcsession');\n}\n/* 遗忘预测：结果作为临时提权叠加，不改动原始调度 */\nasync function rcAiForget() {\n  if (!rcAiOn('forget')) { toast('AI 遗忘预测已关掉'); return ''; }\n  const pool = rcCards().filter(c => Number(c.level) >= 1).slice(0, 150);\n  if (pool.length < 3) { toast('卡片太少，先多背几张'); return ''; }\n  if (!rcAiLock('forget')) return '';\n  S.loading = 'rcforget'; render();\n  let out = '';\n  try {\n    out = await rcAi('rc.forget', {\n      list: pool.map((c, i) => (i + 1) + '｜' + rcLvName(c.level) + '｜错' + Number(c.wrongN || 0) + '次｜' + (c.lastAt ? Math.round((Date.now() - c.lastAt) / 86400000) + '天前' : '没背过')).join('\\n')\n    }, { gate: 'forget' });\n  } finally { rcAiUnlock('forget'); S.loading = ''; }\n  const d = parseJSON(out);\n  render();\n  const risk = (d && Array.isArray(d.risk)) ? d.risk : [];\n  const ids = {}, list = [];\n  risk.forEach(r => {\n    const c = pool[Number(r.id) - 1];\n    if (!c) return;\n    const lv = String(r.lv || '');\n    if (lv !== '高' && lv !== '中') return;\n    if (!ids[c.id]) { ids[c.id] = 1; list.push({ id: c.id, q: c.q, lv: lv, why: String(r.why || '').slice(0, 20) }); }\n  });\n  list.sort((a, b) => (a.lv === '高' ? 0 : 1) - (b.lv === '高' ? 0 : 1));\n  S.draft.rcForgetIds = Object.keys(ids);\n  S.draft.rcForgetList = list.slice(0, 20);\n  S.draft.rcForgetAt = Date.now();\n  S.draft.rcForgetNote = 'AI 标出 ' + S.draft.rcForgetIds.length + ' 张快忘的卡片' + (list.filter(x => x.lv === '高').length ? '（其中 ' + list.filter(x => x.lv === '高').length + ' 张风险高）' : '') + '，已经给它们提权';\n  render();\n  toast(S.draft.rcForgetNote);\n  return S.draft.rcForgetNote;\n}\n/* 每日计划 / 复盘：嵌进首页与日志 */\nasync function rcAiPlan() {\n  if (!rcAiOn('plan')) { toast('AI 每日计划已关掉'); return ''; }\n  if (!rcAiLock('plan')) return '';\n  S.loading = 'rcplan'; render();\n  const todayMin = Math.round(sum((S.sessions || []).filter(s => s.date === dkey()).map(s => s.totalFocusSec || 0)) / 60);\n  const books = rcActiveBooks();\n  let out = '';\n  try {\n    out = await rcAi('rc.plan', {\n      focusMin: todayMin, coin: rcTodayLogs().length ? sum(rcTodayLogs().map(x => Number(x.total) || 0)) : 0,\n      total: rcCards().length, weak: rcWeakCards().length,\n      books: books.map(b => '· ' + b.name + '：' + rcCardN(b.id) + ' 张，薄弱 ' + rcWeakCards(b.id).length + '，熟练以上 ' + rcMasteredN(b.id)).join('\\n') || '（还没有词本）'\n    }, { gate: 'plan' });\n  } finally { rcAiUnlock('plan'); S.loading = ''; }\n  const d = parseJSON(out);\n  render();\n  if (!d || !d.count) { toast('AI 没给出计划（不影响你自己安排）'); return ''; }\n  S.draft.rcPlanAI = d; S.draft.rcPlanAIAt = Date.now();\n  /* 光给建议没用 —— 当场就把这一批挑出来，点「就按这个开始」直接进背诵。\n     挑法：先按建议里的那个词本，取「焦点档 + 薄弱」，不够再按\n     「等级低 → 错得多 → 久没碰」一路补，条数按 AI 建议（兜底 20）。 */\n  const pick = rcPlanPick(d);\n  S.draft.rcPlanPick = pick.list.map(c => c.id);\n  S.draft.rcPlanBookId = pick.book ? pick.book.id : '';\n  render();\n  return d.line || '';\n}\n/* ---------- 今日计划：把「该背的那一批」挑出来 ----------\n   · 优先建议里的那个词本（名字对不上就挑薄弱最多的那本）；\n   · 焦点档 + 薄弱先入选，不够再按「等级低 → 错得多 → 久没碰」补；\n   · 本词本凑不够就跨词本补 —— 总之点一下就能开始，不是一句空建议。 */\nfunction rcPlanPick(plan) {\n  const want = clamp(Number(plan && plan.count) || 20, 1, 100);\n  let book = null;\n  const wantName = String((plan && plan.book) || '').trim();\n  if (wantName) book = rcBooks().filter(b => String(b.name) === wantName)[0] || null;\n  if (!book) {\n    const act = rcActiveBooks().slice().sort((a, b) => rcWeakCards(b.id).length - rcWeakCards(a.id).length);\n    book = act[0] || rcBooks()[0] || null;\n  }\n  const score = c => {\n    const lv = Number(c.level || 0);\n    const pr = 2 - rcPriOf(c);\n    const w = Math.min(9, Number(c.wrongN || 0));\n    const days = c.lastAt ? Math.min(60, (Date.now() - Number(c.lastAt)) / 86400000) : 20;\n    return (3 - lv) * 10 + pr * 6 + w * 4 + days * 0.6 + (c.paused ? 5 : 0);\n  };\n  const pool = book ? rcCardsOf(book.id) : rcCards();\n  const notMaster = pool.filter(c => Number(c.level || 0) < 3);\n  const sorted = (notMaster.length ? notMaster : pool).slice().sort((a, b) => score(b) - score(a));\n  const focus = rcFocusTier(pool);\n  const picked = [], seen = {};\n  sorted.forEach(c => {\n    if (picked.length >= want) return;\n    const isFocus = focus >= 0 && rcPriOf(c) === focus;\n    const isWeak = Number(c.wrongN || 0) > 0 || Number(c.level || 0) < 2;\n    if (isFocus || isWeak) { picked.push(c); seen[String(c.id)] = 1; }\n  });\n  sorted.forEach(c => { if (picked.length < want && !seen[String(c.id)]) { picked.push(c); seen[String(c.id)] = 1; } });\n  if (picked.length < want && book) {\n    rcCards().filter(c => !seen[String(c.id)]).sort((a, b) => score(b) - score(a))\n      .forEach(c => { if (picked.length < want) { picked.push(c); seen[String(c.id)] = 1; } });\n  }\n  return { book: book, list: picked };\n}\n/* ---------- 复盘内核：本地版 + AI 版，两条路都会留档 ----------\n   为什么要留档：以前复盘只存在 S.draft.rcReviewAI 里，一换页、一重开就没了，\n   也没法回头看看「上周三是怎么背的」。现在按日期存进设置，历史可回看。 */\nfunction rcReviewStat() {\n  const logs = rcTodayLogs();\n  return {\n    total: sum(logs.map(x => Number(x.total) || 0)),\n    right: sum(logs.map(x => Number(x.right) || 0)),\n    wrong: sum(logs.map(x => Number(x.wrong) || 0)),\n    dictN: sum(logs.map(x => Number(x.dictationN) || 0)),\n    dictR: sum(logs.map(x => Number(x.dictationRight) || 0)),\n    newN: sum(logs.map(x => Number(x.newN) || 0)),\n    weakN: sum(logs.map(x => Number(x.weakN) || 0)),\n    coin: sum(logs.map(x => Number(x.coin) || 0)),\n    books: (function () {\n      const set = {};\n      logs.forEach(x => { if (x.bookId) set[String(x.bookId)] = 1; });\n      return Object.keys(set).map(id => rcBookName(id)).join('、');\n    })(),\n    n: logs.length\n  };\n}\n/* 本地兜底复盘：不调 AI 也能有一条真实的今日小结 */\nfunction rcReviewLocal() {\n  const s = rcReviewStat();\n  if (!s.total) return '今天还没有背书记录 —— 去词本点「开始背诵」，背完这里就有小结了。';\n  const rate = s.total ? Math.round(s.right / s.total * 100) : 0;\n  const parts = [];\n  parts.push('今天背了 ' + s.total + ' 条，过了 ' + s.right + ' 条（' + rate + '%）' + (s.wrong ? '，其中 ' + s.wrong + ' 条没接上' : '，一条没掉队') + '。');\n  if (s.dictN) parts.push('默写 ' + s.dictN + ' 条，对 ' + s.dictR + ' 条（' + Math.round(s.dictR / s.dictN * 100) + '%）。');\n  if (s.newN) parts.push('新掌握 ' + s.newN + ' 条。');\n  if (s.weakN) parts.push('清掉薄弱 ' + s.weakN + ' 张。');\n  parts.push(s.wrong ? ('明天先把这 ' + s.wrong + ' 条再过一遍，比新开一章更值。') : '明天可以往前推一章新的了。');\n  return parts.join('');\n}\n/* 写一份复盘并留档。byAI = true 表示这句是模型写的 */\nasync function rcReviewSave(text, byAI) {\n  if (!text) return null;\n  const box = Object.assign({}, cfg('rcReviews') || {});\n  const rec = { at: Date.now(), text: String(text), byAI: !!byAI, stat: rcReviewStat() };\n  box[dkey()] = rec;\n  /* 只留最近 30 天，别让设置行越滚越胖 */\n  const keys = Object.keys(box).sort().slice(-30);\n  const keep = {};\n  keys.forEach(k => { keep[k] = box[k]; });\n  S.settings.rcReviews = keep;\n  await saveSettings(true);\n  S.draft.rcReviewAI = rec.text;\n  S.draft.rcReviewAIAt = rec.at;\n  return rec;\n}\n/* 进背书首页时自动补一份：今天有记录、但还没复盘（或记录比复盘新）就更新。\n   隔 5 分钟以上才自动重跑一次，别把 API 额度刷爆；AI 关着就直接写本地版。 */\nlet rcReviewBusy = false;\nasync function rcReviewAuto() {\n  if (rcReviewBusy) return;\n  const s = rcReviewStat();\n  if (!s.total) return;\n  const cur = (cfg('rcReviews') || {})[dkey()] || null;\n  const latest = rcTodayLogs().reduce((m, x) => Math.max(m, Number(x.at) || 0), 0);\n  if (cur && cur.at >= latest && Number((cur.stat || {}).total || 0) === s.total) return;   // 已经是最新的\n  if (cur && Date.now() - cur.at < 5 * 60000) return;                                      // 刚更新过，别连着刷\n  rcReviewBusy = true;\n  try {\n    if (rcAiOn('review') && !rcAiLock('review')) return;\n    const logs = rcTodayLogs();\n    let out = '';\n    if (rcAiOn('review')) {\n      const tN = s.total, tR = s.right;\n      out = await rcAi('rc.review', {\n        date: dkey(), total: tN, right: tR,\n        dictN: s.dictN, dictRight: s.dictR, weak: s.weakN,\n        books: rcActiveBooks().map(b => b.name + '(' + rcCardN(b.id) + ')').join('、') || '（无）',\n        focusMin: Math.round(sum((S.sessions || []).filter(x => x.date === dkey()).map(x => x.totalFocusSec || 0)) / 60)\n      }, { gate: 'review', silent: true });\n    }\n    await rcReviewSave(out || rcReviewLocal(), !!out);\n    if (S.view === 'rcbooks' || S.view === 'recite') render();\n  } catch (e) { }\n  finally { if (rcAiOn('review')) rcAiUnlock('review'); rcReviewBusy = false; }\n}\nasync function rcAiReview() {\n  const logs = rcTodayLogs();\n  if (!logs.length) { toast('今天还没有背书记录 —— 先背一轮再来写复盘'); return ''; }\n  if (!rcAiOn('review')) {\n    /* AI 关着也照样能留一份复盘 —— 用本地统计版，功能不因为关 AI 就消失 */\n    const rec = await rcReviewSave(rcReviewLocal(), false);\n    toast('已写一份本地统计版复盘并留档');\n    render();\n    return rec ? rec.text : '';\n  }\n  if (!rcAiLock('review')) { toast('正在写，稍等一秒'); return ''; }\n  S.loading = 'rcreview'; render();\n  const tN = sum(logs.map(x => Number(x.total) || 0));\n  const tR = sum(logs.map(x => Number(x.right) || 0));\n  const dN = sum(logs.map(x => Number(x.dictationN) || 0));\n  const dR = sum(logs.map(x => Number(x.dictationRight) || 0));\n  const wN = sum(logs.map(x => Number(x.weakN) || 0));\n  let out = '';\n  try {\n    out = await rcAi('rc.review', {\n      date: dkey(), total: tN, right: tR, dictN: dN, dictRight: dR, weak: wN,\n      books: rcActiveBooks().map(b => b.name + '(' + rcCardN(b.id) + ')').join('、') || '（无）',\n      focusMin: Math.round(sum((S.sessions || []).filter(s => s.date === dkey()).map(s => s.totalFocusSec || 0)) / 60)\n    }, { gate: 'review' });\n  } finally { rcAiUnlock('review'); S.loading = ''; }\n  render();\n  /* AI 没给出结果就用本地版顶上 —— 复盘这件事不该因为一次调用失败就空着 */\n  const rec = await rcReviewSave(out || rcReviewLocal(), !!out);\n  if (!out) toast('AI 没给出内容，先用本地统计版记一份');\n  render();\n  return rec ? rec.text : '';\n}\n/* 模拟抽背：抽哪一条不再是纯随机 —— 优先该背的 */\nconst rcPetHistory = [];\nconst rcPetAsked = [];\nfunction rcPetPickCard() {\n  const all = rcCards();\n  if (!all.length) return null;\n  const skip = {};\n  rcPetAsked.slice(-6).forEach(id => { skip[String(id)] = 1; });\n  let pool = all.filter(c => !skip[String(c.id)]);\n  if (!pool.length) pool = all;\n  const score = c => {\n    const lv = Number(c.level || 0);\n    const pr = 2 - rcPriOf(c);                     // 必背 > 重要 > 一般\n    const w = Math.min(9, Number(c.wrongN || 0));\n    const days = c.lastAt ? Math.min(60, (Date.now() - Number(c.lastAt)) / 86400000) : 20;\n    return Math.max(0.5, (3 - lv) * 10 + pr * 6 + w * 4 + days * 0.6 + (c.paused ? 5 : 0));\n  };\n  const ws = pool.map(score);\n  let total = 0;\n  ws.forEach(w => { total += w; });\n  let r = Math.random() * total, pick = pool.length - 1;\n  for (let i = 0; i < pool.length; i++) { r -= ws[i]; if (r <= 0) { pick = i; break; } }\n  return pool[pick];\n}\n/* 让谁抽你 —— 没指定就用当前陪伴角色。这样「抽背」也是 TA 在做，不是系统。 */\nfunction petCharId() {\n  const want = S.draft.rcPetCharId;\n  if (want && charById(want)) return want;\n  return anyCharId();\n}\nasync function rcAiPetAsk() {\n  if (!rcAiOn('pet')) { toast('AI 抽背已关掉'); return; }\n  const pool = rcCards();\n  if (!pool.length) { toast('还没有卡片'); return; }\n  /* 挑题不再纯随机：优先「优先级高、错得多、久没碰、跳过过」的，\n     最近抽过的 6 张先排除，免得连着抽同一条。 */\n  const c = rcPetPickCard();\n  if (!c) { toast('还没有卡片'); return; }\n  rcPetAsked.push(String(c.id));\n  if (rcPetAsked.length > 40) rcPetAsked.splice(0, rcPetAsked.length - 40);\n  S.draft.rcPetCardId = c.id;\n  S.draft.rcPetAnswer = '';\n  S.draft.rcPetResult = null;\n  S.draft.rcPetText = '';\n  S.draft.rcPetShown = false;\n  if (!rcAiLock('pet')) return;\n  S.loading = 'rcpet'; render();\n  let out = '';\n  try {\n    out = await rcAi('rc.pet', {\n      question: String(c.q || '').slice(0, 300), answer: String(c.a || '').slice(0, 900),\n      history: rcPetHistory.slice(-3).join('；') || '（第一次抽）'\n    }, { gate: 'pet' });\n  } finally { rcAiUnlock('pet'); S.loading = ''; }\n  const cid = petCharId();\n  const line = out || ('来，' + String(c.q || '').slice(0, 50) + '——说说看？');\n  rcPetHistory.push(String(c.q || '').slice(0, 30));\n  S.draft.rcPetLine = line;\n  S.draft.rcPetChar = cid;\n  render();\n  if (cid && shouldSpeak('cheer')) { try { speak(cid, line); } catch (e) { } }\n  try { rcAiPetOpen(); } catch (e) { }\n}\n/* ---------- AI 设置面板 ---------- */\nconst RC_AI_ITEMS = [\n  ['gen', 'AI 生成卡片', '把材料拆成整套卡片（要人工确认才入库）'],\n  ['key', 'AI 提取关键词', '从答案里抽 3~8 个关键词，给默写判分用'],\n  ['edit', 'AI 改写卡片', '精简背诵版 / 扩展详解 / 记忆口诀 / 例句词根'],\n  ['hint', 'AI 启发提示', '给回忆角度，绝不直接说答案'],\n  ['explain', 'AI 通俗解释', '看不懂的知识点，用大白话讲一遍'],\n  ['compare', 'AI 易混辨析', '找出容易混淆的相近概念做对比'],\n  ['grade', 'AI 默写判分', '主观评判漏了哪些采分点（失败自动回退本地判分）'],\n  ['variant', 'AI 变式题', '换个问法检验是不是真懂'],\n  ['weak', 'AI 薄弱分析', '归纳你总在错哪一类知识点'],\n  ['forget', 'AI 遗忘预测', '标出快要忘的卡片并给它们提权'],\n  ['plan', 'AI 每日计划', '今天背多少、先背哪本（只是建议）'],\n  ['review', 'AI 每日复盘', '一天的背书小结，嵌进专注日志'],\n  ['pet', 'AI 模拟抽背', '角色按薄弱与优先级挑一条口头问你（原「组卷」已并到这里）']\n];\nfunction rcAiSheet() {\n  const c = rcAiCfg();\n  openSheet(`<h3>🤖 背书的 AI 能力</h3>\n    <div class=\"tiny\" style=\"line-height:1.8\">\n    · 关掉之后对应按钮会回退成<b>纯本地逻辑</b>，不请求任何 API；<br>\n    · AI 只做辅助：判分是建议、组卷可退回本地、生成卡片必须你确认才入库；<br>\n    · API 超时或失败会自动降级，<b>背诵、默写、复习本身不受影响</b>；<br>\n    · 卡片的题干与答案会发给大模型，敏感笔记请关掉 AI。</div>\n    <div class=\"chips mt10\">\n      <button class=\"chip ${c.on ? 'on' : ''}\" data-act=\"rcAiToggle\" data-k=\"on\">${c.on ? 'AI 总开关：开' : 'AI 总开关：关（全部走本地）'}</button>\n    </div>\n    <div class=\"mt10\">${RC_AI_ITEMS.map(([k, n, d]) => `<div class=\"item\" style=\"padding:8px 0\">\n      <div class=\"ic\">${c.on && c[k] !== false ? '✅' : '⬜'}</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px\">${esc(n)}</div><div class=\"tiny\">${esc(d)}</div></div>\n      <button class=\"btn sm ${c[k] !== false ? '' : 'ghost'}\" data-act=\"rcAiToggle\" data-k=\"${k}\" ${c.on ? '' : 'disabled'}>${c[k] !== false ? '开着' : '已关'}</button></div>`).join('')}</div>\n    <button class=\"btn primary block mt10\" data-act=\"closeSheet\">完成</button>`);\n}\n/* ==========================================================\n   背诵设置 / 备份还原\n   ----------------------------------------------------------\n   ① 刷卡片给多少币、默认背诵方式、默认倒计时、防刷阈值 —— 都收在这一页；\n   ② 「内部备份」导出的是一个 .rcbak（含记忆等级+错误次数），\n      这里能把它读回来合并成一个词本，等级和错误次数一起还原。\n   ========================================================== */\nfunction rcNum(key, dflt) {\n  const v = cfg(key);\n  return (v == null || v === '') ? dflt : Number(v);\n}\n/* 防刷量的两个阈值：从设置里读，读不到才用默认 ——\n   以前 rcRate 里写死 800/1200，设置项改了不生效，等于假开关。 */\nfunction rcFastFlipMs() { return clamp(Math.round(rcNum('rcFastFlipMs', 800)) || 800, 100, 5000); }\nfunction rcQuickMarkMs() { return clamp(Math.round(rcNum('rcQuickMarkMs', 1200)) || 1200, 100, 10000); }\nfunction rcDefaults() {\n  /* ⚠️ 这里以前读的是 S.draft（临时对象）——\n     S.draft 一进「专注设置」就被整个重建、重开 APP 更是空的，\n     所以「默认背诵方式 / 默认出题序列 / 默认遮罩」在设置页里永远弹回默认值，\n     看上去就是「改完没存住」。现在先读落库的设置，读不到才回落到 draft / 出厂值。 */\n  return {\n    rcCoinPerCard: rcNum('rcCoinPerCard', 0.2),\n    rcDailyGoal: rcNum('rcDailyGoal', 20),\n    rcRoundN: rcNum('rcRoundN', 1),\n    rcFastFlipMs: rcNum('rcFastFlipMs', 800),\n    rcQuickMarkMs: rcNum('rcQuickMarkMs', 1200),\n    rcCopyMode: String(cfg('rcCopyMode') || 'off'),\n    rcStudy: String(cfg('rcStudy') || S.draft.rcStudy || 'card'),\n    rcMode: String(cfg('rcMode') || S.draft.rcMode || 'order'),\n    rcMask: String(cfg('rcMask') || S.draft.rcMask || 'full'),\n    rcMaskHead: rcNum('rcMaskHead', 2),\n    rcMaskTail: rcNum('rcMaskTail', 1),\n    rcDupThres: rcDupThres()\n  };\n}\n/* 半遮时首、尾各留几个字 —— 以前写死「前 2 字 + 末 1 字」，\n   长句看不出来、短句又几乎等于没遮，现在可自己调。 */\nfunction rcMaskHead() { return clamp(Math.round(rcNum('rcMaskHead', 2)) || 0, 0, 20); }\nfunction rcMaskTail() { return clamp(Math.round(rcNum('rcMaskTail', 1)) || 0, 0, 20); }\n/* 进背诵页之前把设置里的默认值落到 draft ——\n   这样背诵页顶部的开关状态和设置页里选的一致，不会「设置选了默写、进去还是卡片」。 */\nfunction rcApplyDefaults() {\n  const d = rcDefaults();\n  S.draft.rcStudy = d.rcStudy;\n  S.draft.rcMode = d.rcMode;\n  S.draft.rcMask = d.rcMask;\n  if (S.draft.rcTimer == null) S.draft.rcTimer = false;\n  if (S.draft.rcTimerSec == null) S.draft.rcTimerSec = 5;\n}\nfunction rcSetsSheet() {\n  const d = rcDefaults();\n  openSheet(`<h3>⚙️ 背书设置</h3>\n    <div class=\"tiny\">这些只影响背书的节奏与奖励，不会动你已经记住的卡片。</div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">每背一条给多少专注币</label>\n        <input class=\"input\" type=\"number\" inputmode=\"decimal\" step=\"0.1\" data-in=\"setting.rcCoinPerCard\" data-num=\"1\" value=\"${d.rcCoinPerCard}\"></div>\n      <div class=\"grow\"><label class=\"fl\">每日目标条数</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rcDailyGoal\" data-num=\"1\" value=\"${d.rcDailyGoal}\"></div>\n    </div>\n    <div class=\"tiny mt6\">写成 0 就是背书不给币。按 0.2 算，背 50 条约等于 10 点。</div>\n    <label class=\"fl\">默认背诵方式</label>\n    <div class=\"chips\">\n      <button class=\"chip ${d.rcStudy === 'card' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcStudy\" data-v=\"card\">卡片翻看</button>\n      <button class=\"chip ${d.rcStudy === 'dict' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcStudy\" data-v=\"dict\">默写答题</button>\n    </div>\n    <label class=\"fl\">默认出题序列</label>\n    <div class=\"chips\">\n      <button class=\"chip ${d.rcMode === 'order' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMode\" data-v=\"order\">顺序</button>\n      <button class=\"chip ${d.rcMode === 'weight' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMode\" data-v=\"weight\">权重随机（薄弱优先）</button>\n      <button class=\"chip ${d.rcMode === 'pri' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMode\" data-v=\"pri\">🎯 优先级分轮</button>\n    </div>\n    <label class=\"fl\">默认遮罩</label>\n    <div class=\"chips\">\n      <button class=\"chip ${d.rcMask === 'full' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMask\" data-v=\"full\">全遮</button>\n      <button class=\"chip ${d.rcMask === 'hint' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMask\" data-v=\"hint\">半遮·首尾线索</button>\n      <button class=\"chip ${d.rcMask === 'line' ? 'on' : ''}\" data-act=\"rcSetDefault\" data-k=\"rcMask\" data-v=\"line\">逐行揭露</button>\n    </div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">半遮：首留几个字</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rcMaskHead\" data-num=\"1\" value=\"${d.rcMaskHead}\"></div>\n      <div class=\"grow\"><label class=\"fl\">半遮：尾留几个字</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rcMaskTail\" data-num=\"1\" value=\"${d.rcMaskTail}\"></div>\n    </div>\n    <div class=\"tiny mt6\">只影响「半遮·首尾线索」这一档：句首留几个字、句尾留几个字，中间部分自己回忆。设成 0 就是那一头不留。</div>\n    <label class=\"fl\">默写判完，要不要先抄一遍正确答案</label>\n    <div class=\"chips\">\n      <button class=\"chip ${d.rcCopyMode === 'off' ? 'on' : ''}\" data-act=\"rcSetCopyMode\" data-v=\"off\">不用抄</button>\n      <button class=\"chip ${d.rcCopyMode === 'notGood' ? 'on' : ''}\" data-act=\"rcSetCopyMode\" data-v=\"notGood\">没判「熟练」就抄</button>\n      <button class=\"chip ${d.rcCopyMode === 'notMaster' ? 'on' : ''}\" data-act=\"rcSetCopyMode\" data-v=\"notMaster\">没到「精通」就抄</button>\n    </div>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">开了之后，默写判分不达标就得先<b>照着标准答案手抄一遍</b>，抄完才放你进下一题。<br>\n    · 「没判熟练就抄」：只有答错、答得不够的才抄 —— 最实用的一档；<br>\n    · 「没到精通就抄」：<b>注意</b>，默写判分最高只给到「熟练」，「精通」要连续两次都答对才升得上去，所以选这一档等于<b>几乎每条都要抄</b>。<br>\n    · 抄写框不接受粘贴 —— 粘上去就失去「手过一遍」的意义了。</div>\n    <div class=\"hr\"></div>\n    <div class=\"tiny\" style=\"line-height:1.8\"><b>防偷懒参数</b>（默认就好，知道自己手快再调）<br>\n    间隔小于 ${d.rcFastFlipMs} 毫秒连续翻卡，这次不计等级；刚翻开 ${d.rcQuickMarkMs} 毫秒内点「熟练」，按「模糊」记。</div>\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">连续翻卡阈值（毫秒）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rcFastFlipMs\" data-num=\"1\" value=\"${d.rcFastFlipMs}\"></div>\n      <div class=\"grow\"><label class=\"fl\">快速点评阈值（毫秒）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"setting.rcQuickMarkMs\" data-num=\"1\" value=\"${d.rcQuickMarkMs}\"></div>\n    </div>\n    <div class=\"hr\"></div>\n    <div class=\"tiny\">出错时角色只安抚、不打击；答对才出星光。想彻底关掉 AI 辅助，去上面「AI」里关总开关。</div>\n    <div class=\"hr\"></div>\n    <label class=\"fl\">重复卡片判定阈值</label>\n    <input class=\"input\" type=\"number\" inputmode=\"decimal\" step=\"0.05\" min=\"0.5\" max=\"1\" data-in=\"setting.rcDupThres\" data-num=\"1\" value=\"${d.rcDupThres}\">\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">题干相似度到这个值就算重复。现在 ${d.rcDupThres}：改标点、换几个字、多写少写一句都能抓出来。<br>\n    · 想抓得更狠就调低（0.7 左右，会多报但不会漏）；<br>\n    · 想只看几乎一字不差的就调高（0.95 以上）。调完去词本点「🧹 查重复卡片」看效果。</div>\n    <div class=\"row mt12\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"rcSetsSave\">✅ 保存</button>\n      <button class=\"btn ghost grow\" data-act=\"rcExportAll\">📤 导出全部词本</button>\n    </div>\n    <div class=\"tiny mt6\" style=\"color:var(--dim2)\">改完点「保存」再关；直接点面板外面关掉也会一并存下，不会白改。</div>`);\n}\n/* 把面板里所有 setting.* 输入框当场收一遍再落库 ——\n   光靠 input 事件的防抖保存，用户看不出到底存没存，所以要有一个明确的「保存」。 */\nfunction setSettingByPath(path, val) {\n  const parts = String(path).split('.');\n  if (parts.length === 1) { S.settings[parts[0]] = val; return; }\n  let cur = S.settings;\n  for (let i = 0; i < parts.length - 1; i++) {\n    if (cur[parts[i]] == null || typeof cur[parts[i]] !== 'object' || Array.isArray(cur[parts[i]])) cur[parts[i]] = {};\n    cur = cur[parts[i]];\n  }\n  cur[parts[parts.length - 1]] = val;\n}\n/* 读一个本地文件（备份还原用）：优先宿主选择器，失败回落到 input[type=file] */\nasync function rcPickTextFile() {\n  return await new Promise(resolve => {\n    const inp = document.createElement('input');\n    inp.type = 'file'; inp.accept = '.rcbak,application/json,text/plain,.json,.txt';\n    inp.style.position = 'fixed'; inp.style.left = '-9999px'; inp.style.top = '0';\n    document.body.appendChild(inp);\n    let done = false;\n    const finish = v => { if (done) return; done = true; try { inp.remove(); } catch (e) { } resolve(v); };\n    inp.addEventListener('change', () => {\n      const f = inp.files && inp.files[0];\n      if (!f) { finish(''); return; }\n      const fr = new FileReader();\n      fr.onload = () => finish(String(fr.result || ''));\n      fr.onerror = () => finish('');\n      fr.readAsText(f, 'utf-8');\n    });\n    try { inp.click(); } catch (e) { finish(''); return; }\n    setTimeout(() => finish(''), 180000);\n  });\n}\n/* 把一份 .rcbak 还原成一个（新）词本 ——\n   同名卡片不覆盖，只补进去缺的那些；等级 / 错误次数 / 顺序一起还原。 */\nasync function rcRestoreFromBak(raw) {\n  let d = null;\n  try { d = JSON.parse(raw); } catch (e) { d = null; }\n  if (!d || (d.kind !== 'rc-book-backup' && !d.book && !Array.isArray(d.cards))) {\n    toast('这不是本 APP 导出的内部备份（.rcbak）');\n    return 0;\n  }\n  const name = String((d.book && d.book.name) || '还原的词本').slice(0, 24) + '（还原）';\n  const bk = { name: name, at: Date.now(), archived: false };\n  await rcSaveBook(bk);\n  const exist = {};\n  let added = 0, skip = 0;\n  const arr = Array.isArray(d.cards) ? d.cards.slice(0, 2000) : [];\n  for (const it of arr) {\n    const q = String((it && it.q) || '').trim();\n    if (!q) { skip++; continue; }\n    const k = rcNormQ(q);\n    if (exist[k]) { skip++; continue; }\n    exist[k] = 1;\n    const c = rcNewCard(bk.id, q, it.a, it.hint);\n    c.level = clamp(Number(it.level) || 0, 0, 3);\n    c.wrongN = Math.max(0, Number(it.wrongN) || 0);\n    c.rightN = Math.max(0, Number(it.rightN) || 0);\n    c.streak = Math.max(0, Number(it.streak) || 0);\n    c.paused = !!it.paused;\n    c.lastAt = Number(it.lastAt) || 0;\n    c.order = Number(it.order) || added;\n    await rcSaveCard(c);\n    added++;\n  }\n  if (added) await rcLogAdd({ date: dkey(), at: Date.now(), bookId: bk.id, newN: added });\n  toast('已还原 ' + added + ' 张' + (skip ? '（跳过 ' + skip + ' 张重复/空卡）' : '') + ' 到「' + name + '」');\n  S.draft.rcBookId = bk.id;\n  go('rcbook');\n  return added;\n}\nObject.assign(ACTIONS, {\n  rcSets: () => rcSetsSheet(),\n  rcSetCopyMode: async el => {\n    S.settings.rcCopyMode = el.dataset.v || 'off';\n    await saveSettings(true);\n    rcSetsSheet();\n  },\n  rcSetsSave: async () => {\n    document.querySelectorAll('[data-in^=\"setting.\"]').forEach(el => {\n      try { setSettingByPath(el.dataset.in.slice(8), readInput(el)); } catch (e) { }\n    });\n    await saveSettings(true);\n    closeAllSheets();\n    toast('背书设置已保存');\n    render();\n  },\n  rcSetDefault: async el => {\n    const k = el.dataset.k, v = el.dataset.v;\n    S.settings[k] = v;\n    S.draft[k] = v;\n    await saveSettings(true);     // 落库后再重画面板：下一次打开读的就是它\n    rcSetsSheet();\n  },\n  rcRestoreOpen: () => {\n    openSheet(`<h3>📥 还原内部备份</h3>\n      <div class=\"tiny\" style=\"line-height:1.8\">选择之前从本 APP 导出的 <b>.rcbak</b> 文件。<br>\n      还原规则：<b>合并</b>到一个新词本（名叫「原词本名（还原）」），同名题干自动跳过，不会覆盖你现在的内容；记忆等级、错误次数、掌握顺序都会一起恢复。</div>\n      <div class=\"tiny mt6\" style=\"color:var(--dim2)\">TXT / Markdown 备份只含文字，不含熟练度 —— 那种直接走「批量导入」即可。</div>\n      <button class=\"btn primary block mt12\" data-act=\"rcRestorePick\">选择备份文件</button>\n      <button class=\"btn block ghost mt8\" data-act=\"rcRestorePaste\">手动粘贴备份内容</button>\n      <button class=\"btn block ghost sm mt8\" data-act=\"closeSheet\">取消</button>`);\n  },\n  rcRestorePick: async () => {\n    closeAllSheets();\n    let raw = '';\n    try { raw = await rcPickTextFile(); } catch (e) { raw = ''; }\n    if (!raw || !String(raw).trim()) { toast('没有读到文件内容'); return; }\n    await rcRestoreFromBak(String(raw).trim());\n  },\n  rcRestorePaste: () => {\n    openSheet(`<h3>粘贴备份内容</h3>\n      <div class=\"tiny\">把 .rcbak 文件里的内容整段粘进来（以 { 开头的那一整段 JSON）。</div>\n      <textarea id=\"rcBakBox\" style=\"min-height:170px;margin-top:8px\" placeholder='{\"kind\":\"rc-book-backup\",...}'></textarea>\n      <div class=\"row mt12\" style=\"gap:8px\"><button class=\"btn ghost grow\" data-act=\"closeSheet\">取消</button>\n        <button class=\"btn primary grow\" data-act=\"rcRestorePasteDo\">开始还原</button></div>`);\n  },\n  rcRestorePasteDo: async () => {\n    const raw = ((document.getElementById('rcBakBox') || {}).value || '').trim();\n    if (!raw) { toast('先粘贴备份内容'); return; }\n    closeAllSheets();\n    await rcRestoreFromBak(raw);\n  },\n  /* 整库导出：一本书一个 .rcbak，逐一下载 */\n  rcExportAll: async () => {\n    const books = rcBooks().filter(b => rcCardN(b.id) > 0);\n    if (!books.length) { toast('还没有可导出的词本'); return; }\n    const ok = await confirmBox('导出全部 ' + books.length + ' 个词本？',\n      '会逐一下载 ' + books.length + ' 个 .rcbak 文件（每个带走该词本的全部学习数据）。\\n浏览器的下载确认可能需要你点几次「允许」。', '开始导出');\n    if (!ok) return;\n    closeAllSheets();\n    let n = 0;\n    for (const b of books) {\n      const cards = rcCardsOf(b.id);\n      const safe = String(b.name).replace(/[\\\\/:*?\"<>|]/g, '_').slice(0, 20);\n      const txt = JSON.stringify({\n        kind: 'rc-book-backup', v: 1, at: Date.now(),\n        book: { name: b.name, at: b.at },\n        cards: cards.map(c => ({ q: c.q, a: c.a, hint: c.hint, level: c.level, wrongN: c.wrongN, rightN: c.rightN, streak: c.streak, paused: !!c.paused, lastAt: c.lastAt, order: c.order }))\n      });\n      if (blobDownload(safe + '.rcbak', txt, 'application/json;charset=utf-8')) n++;\n      await new Promise(r => setTimeout(r, 320));   // 隔一下：连着触发下载容易被浏览器拦\n    }\n    toast(n ? ('已导出 ' + n + ' 个文件') : '导出被浏览器拦下了，可以一个个单独导出');\n  },\n  /* ---- 薄弱诊断 / 遗忘标记的清理 ---- */\n  rcWeakAiClear: () => { S.draft.rcWeakAI = null; S.draft.rcWeakAIAt = 0; render(); },\n  rcReviewOpenDay: el => {\n    const k = String(el.dataset.k || '');\n    S.draft.rcReviewOpen = (String(S.draft.rcReviewOpen || '') === k) ? '' : k;\n    render();\n  },\n  rcReviewDelDay: async el => {\n    const k = String(el.dataset.k || '');\n    const box = Object.assign({}, cfg('rcReviews') || {});\n    if (!box[k]) { toast('这条已经没了'); return; }\n    const ok = await confirmBox('删掉 ' + k + ' 的复盘？', '只删这一天的复盘文字，你的背诵记录和卡片进度都不受影响。', '删掉');\n    if (!ok) return;\n    delete box[k];\n    S.settings.rcReviews = box;\n    S.draft.rcReviewOpen = '';\n    await saveSettings(true);\n    toast('已删掉');\n    render();\n  },\n  rcForgetClear: () => {\n    S.draft.rcForgetIds = [];\n    S.draft.rcForgetList = [];\n    S.draft.rcForgetNote = '';\n    S.draft.rcForgetAt = 0;\n    toast('已清掉标记，恢复正常顺序');\n    render();\n  },\n  /* 先把标出来的「快忘的」过一遍：直接按这些卡片开一轮 */\n  rcForgetStart: () => {\n    const ids = (S.draft.rcForgetIds || []).slice();\n    if (!ids.length) { toast('没有标记的卡片'); return; }\n    const list = ids.map(rcCardById).filter(Boolean);\n    if (!list.length) { toast('这些卡片已经不在了'); return; }\n    S.recite = {\n      scope: 'forget', bookId: '', queue: list.map(c => c.id), idx: 0,\n      flipped: false, shownAt: Date.now(), lastSwitchAt: Date.now(),\n      done: 0, right: 0, wrong: 0, dictationN: 0, dictationRight: 0,\n      newN: 0, weakBefore: rcWeakCards('').length, startedAt: Date.now(), touched: {}, log: [],\n      forgetRound: true\n    };\n    toast('先把这 ' + list.length + ' 张过一遍');\n    go('rcsession');\n  }\n});\n/* ==========================================================\n   抽背 · 聊天室（重做 · 需求①）\n   ----------------------------------------------------------\n   · 不要语音          → 全程文字，不调 TTS\n   · 看见题目再回答    → 每题先把题干完整摆出来\n   · 随机默写 / 填空   → 每张卡开局随机挑形式；长答案出接力\n   · 聊天室形式        → TA 说一句、你答一句\n   · 不接 AI 的选项    → 默认纯本地出题，AI 开关默认关\n   落分不复用 rcRate（它绑在背诵会话的「当前卡」上），\n   这里直接写回卡片，等级口径和背诵页完全一致。\n   ========================================================== */\nconst RCQ_FORMS = [['mix', '混合（默写/填空/接力）'], ['dict', '只默写'], ['fill', '只填空'], ['relay', '只接力']];\nfunction rcQ() {\n  if (!S.rcChat) {\n    S.rcChat = { items: [], i: 0, form: 'mix', useAI: false, n: 5, run: false, right: 0, near: 0, wrong: 0, cur: null, waiting: false, log: [], bookId: '', hinted: false, needAsk: false };\n    /* 把上一轮接回来：S.rcChat 以前只活在内存里，退出 APP 整轮就清空\n       （题序、进度、聊过的话全丢）。现在每次推进都往设置里存一份精简快照，\n       重开时在这里还原。卡片本身的等级 / 错次早就写进数据库，不靠这份快照。 */\n    try { rcQRestore(cfg('rcChat')); } catch (e) { }\n  }\n  return S.rcChat;\n}\n/* 出题池：按「优先级 → 等级低 → 错得多 → 久没碰」排 */\nfunction rcQPool() {\n  const Q = rcQ();\n  let all = rcCards().filter(c => c && c.q);\n  if (Q.bookId) { const sub = all.filter(c => String(c.bookId) === String(Q.bookId)); if (sub.length) all = sub; }\n  return all.slice().sort((a, b) => {\n    const pa = rcPriOf(a), pb = rcPriOf(b);\n    if (pa !== pb) return pa - pb;\n    const la = Number(a.level || 0), lb = Number(b.level || 0);\n    if (la !== lb) return la - lb;\n    const wa = Number(a.wrongN || 0), wb = Number(b.wrongN || 0);\n    if (wa !== wb) return wb - wa;\n    return Number(a.lastAt || 0) - Number(b.lastAt || 0);\n  });\n}\n/* 挖空：优先挖掉一个关键词整块；没有关键词就挖半句。\n   ⚠️ 以前是随机遮 1~3 个单字，公式 k = min(3, floor(n/3))——\n   答案短一点就只剩 1 个字，还容易挖到「的、了」这种虚字，等于没考。\n   现在按「关键词（或半句）」整块挖，考的才是真内容。 */\nfunction rcQMask(a, card) {\n  a = String(a || '');\n  const n = a.length;\n  if (n <= 1) return { shown: a, blanks: a, kind: 'short' };\n  let keys = [];\n  try {\n    keys = (rcKeywords(card || { a: a }) || [])\n      .filter(k => k && k.length >= 2 && a.indexOf(k) >= 0 && k.length <= Math.max(4, Math.ceil(n * 0.7)));\n  } catch (e) { keys = []; }\n  let seg = '', kind = '';\n  if (keys.length) {\n    keys = keys.slice().sort((x, y) => y.length - x.length);\n    const top = keys.slice(0, Math.min(3, keys.length));\n    seg = top[Math.floor(Math.random() * top.length)];\n    kind = 'kw';\n  }\n  if (!seg) {\n    /* 没关键词：挖半句（前半或后半随机），比挖单字有意义 */\n    const half = Math.max(1, Math.floor(n / 2));\n    seg = (Math.random() < 0.5) ? a.slice(0, half) : a.slice(n - half);\n    kind = 'half';\n  }\n  const at = a.indexOf(seg);\n  if (at < 0 || !seg) return { shown: a, blanks: '', kind: 'none' };\n  const shown = a.slice(0, at) + '［' + '○'.repeat(seg.length) + '］' + a.slice(at + seg.length);\n  return { shown: shown, blanks: seg, kind: kind };\n}\nfunction rcQMake(n, form) {\n  const Q = rcQ();\n  const pool = rcQPool();\n  const want = Math.min(Math.max(1, Number(n) || 5), pool.length);\n  if (!pool.length) return [];\n  /* 「每次抽的题都一样」的原因：原来先整池排序，再只从最前面 want×2 张里选 ——\n     池子头固定不变，于是永远在同一小撮最薄弱的卡里转。\n     改法：① 先排除最近抽过的（最多排掉一半，免得没得抽）；\n           ② 剩下的按名次加权随机（第 1 名权重 1、第 2 名 1/2、第 3 名 1/3……），\n              薄弱的依然更容易被抽到，但名次靠后的也有了机会。 */\n  const recent = (Q.recentIds || []).slice();\n  const skipN = Math.min(recent.length, Math.floor(pool.length / 2));\n  const skip = {};\n  recent.slice(recent.length - skipN).forEach(id => { skip[String(id)] = 1; });\n  let base = pool.filter(c => !skip[String(c.id)]);\n  if (base.length < want) base = pool.slice();\n  const arr = base.slice();\n  const picked = [];\n  while (picked.length < want && arr.length) {\n    let total = 0;\n    const ws = arr.map((c, i) => { const w = 1 / (1 + i); total += w; return w; });\n    let r = Math.random() * total, pick = arr.length - 1;\n    for (let i = 0; i < arr.length; i++) { r -= ws[i]; if (r <= 0) { pick = i; break; } }\n    picked.push(arr.splice(pick, 1)[0]);\n  }\n  Q.recentIds = (Q.recentIds || []).concat(picked.map(c => String(c.id)));\n  if (Q.recentIds.length > 60) Q.recentIds = Q.recentIds.slice(-60);\n  return picked.map(c => {\n    let f = form, a = String(c.a || '');\n    if (f === 'mix') { const o = ['dict']; if (a.length >= 3) o.push('fill'); if (a.length >= 12) o.push('relay'); f = o[Math.floor(Math.random() * o.length)]; }\n    if (f === 'fill' && a.length < 3) f = 'dict';\n    if (f === 'relay') {\n      /* ⚠️ 这里本来还有一条 a.length < 12 —— 答案短于 12 字就被降级成「默写」，\n         所以你明选了「只接力」，系统却让你默写。rcQSplitSent 现在会把一句话\n         按中点补切成两句，所以只剩「短到没法接（<4 字）」才退回默写。 */\n      let sg = [];\n      try { sg = rcQSplitSent(a); } catch (e) { sg = []; }\n      if (!sg || sg.length < 2) f = 'dict';\n    }\n    return { card: c, form: f, q: String(c.q || ''), a: a };\n  });\n}\nfunction rcQPush(role, html, charId) {\n  const Q = rcQ();\n  Q.log.push({ role: role, text: html, at: Date.now(), charId: charId || '' });\n  if (Q.log.length > 120) Q.log = Q.log.slice(-120);\n}\nfunction rcQMsgHTML(m) {\n  if (m.role === 'sys') return `<div class=\"msg sys\"><div class=\"bd\">${esc(m.text)}</div></div>`;\n  if (m.role === 'me') return `<div class=\"msg me\"><div class=\"bd\">${esc(m.text)}</div></div>`;\n  const c = charById(m.charId);\n  return `<div class=\"msg\">${charAvatar(c)}<div class=\"bd\"><div class=\"who\">${esc(c ? c.name : 'TA')}${m.at ? ' · ' + hm(m.at) : ''}</div>${m.text}</div></div>`;\n}\n/* ---------- 抽背进度快照：退出 APP 也能接着上一轮 ---------- */\nfunction rcQSync() {\n  const Q = rcQ();\n  try {\n    S.settings.rcChat = {\n      form: Q.form, useAI: !!Q.useAI, n: Number(Q.n) || 5, bookId: String(Q.bookId || ''),\n      run: !!Q.run, i: Number(Q.i) || 0, logged: !!Q.logged,\n      right: Number(Q.right) || 0, near: Number(Q.near) || 0, wrong: Number(Q.wrong) || 0,\n      recentIds: (Q.recentIds || []).slice(-60),\n      items: (Q.items || []).map(function (x) {\n        return { id: String((x.card && x.card.id) || ''), form: x.form, q: Q.useAI ? String(x.q || '') : '', a: Q.useAI ? String(x.a || '') : '' };\n      }).filter(function (x) { return x.id; }),\n      log: (Q.log || []).slice(-40)\n    };\n    const p = saveSettings(true);\n    if (p && p.catch) p.catch(function () { });\n  } catch (e) { }\n}\nfunction rcQRestore(st) {\n  const Q = rcQ();\n  if (!st || typeof st !== 'object') return;\n  if (st.form && RCQ_FORMS.some(function (x) { return x[0] === st.form; })) Q.form = String(st.form);\n  Q.useAI = !!st.useAI;\n  if (Number(st.n) > 0) Q.n = clamp(Math.round(Number(st.n)), 1, 50);\n  Q.bookId = String(st.bookId || '');\n  const items = (Array.isArray(st.items) ? st.items : []).map(function (x) {\n    const c = rcCardById(x.id);\n    if (!c) return null;\n    return { card: c, form: String(x.form || 'dict'), q: String(x.q || c.q || ''), a: String(x.a || c.a || '') };\n  }).filter(Boolean);\n  if (!items.length) return;\n  Q.items = items;\n  Q.i = clamp(Number(st.i) || 0, 0, items.length);\n  Q.right = Math.max(0, Number(st.right) || 0);\n  Q.near = Math.max(0, Number(st.near) || 0);\n  Q.wrong = Math.max(0, Number(st.wrong) || 0);\n  Q.log = (Array.isArray(st.log) ? st.log : []).slice(-40);\n  Q.recentIds = Array.isArray(st.recentIds) ? st.recentIds.slice(-60) : [];\n  Q.logged = !!st.logged;\n  Q.hinted = false;\n  Q.run = !!st.run && Q.i < items.length;\n  Q.waiting = false;\n  Q.cur = null;\n  if (Q.run) {\n    const it = Q.items[Q.i];\n    Q.cur = it;\n    /* 重建这题的现场：不重建的话，恢复后填空/接力判分会失准 */\n    if (it.form === 'fill' && it.a) it.fill = rcQMask(it.a, it.card);\n    if (it.form === 'relay' && it.a) { const sg = rcQSplitSent(it.a); it.relaySegs = (sg && sg.length) ? sg : [String(it.a)]; it.relayAt = 1; }\n    Q.waiting = true;\n    rcQPush('sys', '接着上一轮 · 第 ' + (Q.i + 1) + '/' + Q.items.length + ' 题（已经答过的都记在卡片上了）');\n  }\n}\n/* ---------- 说话节奏：一次只讲一句，逐条发 ---------- */\nlet rcQStepTimers = [];\nfunction rcQClearSteps() { rcQStepTimers.forEach(function (t) { clearTimeout(t); }); rcQStepTimers = []; }\nfunction rcQSteps(list, cid, done) {\n  rcQClearSteps();\n  list = (list || []).filter(function (x) { return x != null && String(x) !== ''; });\n  if (!list.length) { if (done) done(); return; }\n  list.forEach(function (txt, i) {\n    if (i === 0) { rcQPush('ta', txt, cid); render(); rcQScroll(); return; }\n    rcQStepTimers.push(setTimeout(function () {\n      rcQPush('ta', txt, cid); render(); rcQScroll();\n      if (i === list.length - 1 && done) done();\n    }, i * 420));\n  });\n  if (list.length === 1 && done) done();\n}\n/* 把一段答案切成「句」：优先按句号/问号/叹号，太长的再按逗号切。\n   接力就按这个顺序一人一句往下走。 */\nfunction rcQSplitSent(a) {\n  a = String(a || '').trim();\n  if (!a) return [];\n  let segs = a.split(/(?<=[。！？!?；;])/).map(function (x) { return x.trim(); }).filter(Boolean);\n  if (segs.length <= 1) segs = a.split(/[，,、]/).map(function (x) { return x.trim(); }).filter(Boolean);\n  if (segs.length <= 1) {\n    /* 就一整句（比如「边际效用递减」）时，按中点补切一刀 ——\n       这样「接力」永远能一人一句地玩，不会因为答案是一句整话就退化成默写。 */\n    if (a.length >= 4) {\n      const half = Math.max(1, Math.round(a.length / 2));\n      return [a.slice(0, half), a.slice(half)];\n    }\n    return [a];\n  }\n  /* 太碎的短句合并一下，免得一句只有两三个字 */\n  const out = [];\n  let buf = '';\n  segs.forEach(function (s) {\n    buf += s;\n    if (buf.length >= 6) { out.push(buf); buf = ''; }\n  });\n  if (buf) { if (out.length) out[out.length - 1] += buf; else out.push(buf); }\n  return out;\n}\n/* 接力：一人一句地往下走。\n   用户接对一句 → TA 念下一句 → 再等用户接，直到整段说完；\n   哪一句没接上就当场收尾、把整段摆出来。\n   返回 true 表示这一句已经处理完（不用再走整段判分）。 */\nfunction rcQRelaySend(Q, it, txt) {\n  if (!Q || !it) return false;\n  if (it.form !== 'relay' || !it.relaySegs || it.relaySegs.length < 2) return false;\n  const at = Number(it.relayAt);\n  if (!(at >= 1) || at >= it.relaySegs.length) return false;\n  const want = it.relaySegs[at];\n  let good = false;\n  try {\n    const rr = rcMatchAnswer(txt, { q: it.q, a: want, hint: '', tricky: [] });\n    good = rr.rate >= 2;\n    if (!good && rcSimRate(txt, want) >= 0.85) good = true;\n  } catch (e) { }\n  if (!good) {\n    rcQSave(it, 0);\n    Q.wrong++;\n    rcQSteps([\n      '🟡 这一句差一点，先把整段看一遍。',\n      '<span class=\"tiny\">这句该是：' + esc(want) + '</span>',\n      '<span class=\"tiny\">完整答案：' + esc(it.a) + '</span>'\n    ], rcQChar());\n    Q.i++;\n    rcQSync(); render(); rcQScroll();\n    setTimeout(rcQAsk, 1300);\n    return true;\n  }\n  /* 接对了：看下一句轮到谁念（偶数索引 TA 念，奇数索引用户接） */\n  let k = at + 1, spoken = '';\n  if (k < it.relaySegs.length) { spoken = it.relaySegs[k]; k++; }\n  if (k < it.relaySegs.length) {\n    it.relayAt = k;\n    rcQSteps([\n      '✅ 对，就是这个。',\n      '我接着说 —— <span style=\"color:var(--gold)\">' + esc(spoken) + '</span>',\n      '<span class=\"tiny\">该你了，接下一句。</span>'\n    ], rcQChar(), function () {\n      Q.cur = it; Q.waiting = true;\n      rcQSync(); render(); rcQScroll();\n    });\n    rcQSync(); render(); rcQScroll();\n    return true;\n  }\n  rcQSave(it, 2);\n  Q.right++;\n  rcQSteps([\n    '✅ 整段接完了，漂亮。',\n    '<span class=\"tiny\">完整答案：' + esc(it.a) + '</span>'\n  ], rcQChar());\n  Q.i++;\n  rcQSync(); render(); rcQScroll();\n  setTimeout(rcQAsk, 1300);\n  return true;\n}\n/* 答完一条：进下一题 */\nfunction rcQNext() {\n  const Q = rcQ();\n  Q.i++;\n  render();\n  rcQScroll();\n  rcQSync();\n  setTimeout(function () { rcQAsk(); }, 380);\n}\nfunction rcQChar() { const p = (cfg('charIds') || []).filter(id => charById(id)); return p[0] || anyCharId() || ''; }\nfunction rcQAsk() {\n  const Q = rcQ();\n  if (!Q.items || !Q.items.length || Q.i >= Q.items.length) { rcQFinish(); return; }\n  const it = Q.items[Q.i];\n  const total = Q.items.length, no = Q.i + 1;\n  const cid = rcQChar();\n  Q.hinted = false;\n  /* ⚠️ 原来这里从头到尾没给 Q.cur 赋过值（只有 rcQFinish 把它清成 null），\n     而「发送 / 给点提示 / 不会看答案」三个动作开头都是\n     `if (!Q.run || !Q.waiting || !Q.cur) return;` —— 全被这一行静默拦掉，\n     表现就是三个按钮一点反应都没有。这里补上。 */\n  Q.cur = it;\n  Q.waiting = false;\n  const steps = [];\n  const opener = ['来，第 ' + no + ' 题（共 ' + total + ' 题）', '第 ' + no + ' 题', '接着来，第 ' + no + ' 题'];\n  steps.push('<span class=\"tiny\">' + esc(opener[Math.floor(Math.random() * opener.length)]) + '</span>');\n  if (it.form === 'dict') {\n    steps.push('<b>默写</b>：' + esc(it.q));\n    steps.push('<span class=\"tiny\">把这张卡的答案完整默写出来，写不全也没关系。</span>');\n  } else if (it.form === 'fill') {\n    it.fill = rcQMask(it.a, it.card);\n    steps.push('<b>填空</b>：' + esc(it.q));\n    steps.push('<span style=\"font-size:15px;letter-spacing:1px\">' + esc(it.fill.shown) + '</span>');\n    steps.push('<span class=\"tiny\">把［ ］里的 ' + it.fill.blanks.length + ' 个字按顺序打给我。' + (it.fill.kind === 'kw' ? '（挖掉的是一个关键词）' : '') + '</span>');\n  } else {\n    /* 接力：把答案切成句，一人一句接着念。\n       以前是按字数对半切，像机器断句；现在切在标点上，读起来才像聊天。 */\n    const segs = rcQSplitSent(it.a);\n    it.relaySegs = (segs && segs.length) ? segs : [String(it.a || '')];\n    it.relayAt = 1;                     // TA 念了第 0 句，轮到用户接第 1 句\n    steps.push('<b>接力</b>：' + esc(it.q));\n    steps.push('我先起个头 —— <span style=\"color:var(--gold)\">' + esc(it.relaySegs[0]) + '</span>');\n    if (it.relaySegs.length > 1) steps.push('<span class=\"tiny\">你接下一句，我再说下一句，咱们一句一句把它说完。</span>');\n    else steps.push('<span class=\"tiny\">就这一句，你把它重复一遍收尾。</span>');\n  }\n  rcQSync();\n  /* 一次一句、逐条发；最后一句落地后才解锁输入框 —— 题目没摆完不让你答 */\n  const go2 = function () {\n    rcQSteps(steps, cid, function () {\n      Q.waiting = true;\n      rcQSync();\n      render();\n      rcQScroll();\n    });\n  };\n  if (Q.useAI && !it.aiDone) {\n    /* 只给当前这题换问法：换完再发题，避免「边发边改」看着前后矛盾 */\n    Promise.resolve(rcQFillAI()).then(function () {\n      it.q = String(it.q || it.card.q || '');\n      it.a = String(it.a || it.card.a || '');\n      if (it.form === 'dict') { steps[1] = '<b>默写</b>：' + esc(it.q); }\n      go2();\n    }).catch(function () { go2(); });\n  } else go2();\n}\nfunction rcQScroll() {\n  try {\n    const b = document.getElementById('rcChatBox');\n    if (b) setTimeout(function () { try { b.scrollTop = b.scrollHeight; } catch (e) { } }, 60);\n  } catch (e) { }\n}\nfunction rcQJudge(it, got) {\n  got = String(got || '').trim();\n  let expect = it.a;\n  if (it.form === 'fill' && it.fill) expect = (got.length >= it.a.length - 2 && got.length <= it.a.length + 8) ? it.a : it.fill.blanks;\n  if (it.form === 'relay') expect = it.tail || it.a;\n  const r = rcMatchAnswer(got, { q: it.q, a: expect, hint: '', tricky: [] });\n  let rate = r.rate;\n  try { if (rcSimRate(got, expect) >= 0.9) rate = Math.max(rate, 2); } catch (e) { }\n  return { rate: rate, pct: r.pct, hit: r.hit || [], miss: r.miss || [] };\n}\nasync function rcQSave(it, lv) {\n  const c = it.card;\n  if (!c) return;\n  if (lv >= 2) { c.rightN = Number(c.rightN || 0) + 1; c.streak = Number(c.streak || 0) + 1; c.paused = false; }\n  else { c.wrongN = Number(c.wrongN || 0) + 1; c.streak = 0; c.paused = true; }\n  c.level = lv; c.lastAt = Date.now();\n  await rcSaveCard(c);\n}\nfunction rcQFinish() {\n  const Q = rcQ();\n  Q.run = false; Q.waiting = false; Q.cur = null;\n  rcQClearSteps();\n  const t = Q.right + Q.near + Q.wrong;\n  const earn = Math.round(t * Math.max(0, Number(cfg('rcCoinPerCard') != null ? cfg('rcCoinPerCard') : 0.2)));\n  rcQPush('ta', '<b>本轮抽背结束</b>：共 ' + t + ' 题 —— ✅ ' + Q.right + ' · 🟡 ' + Q.near + ' · ❌ ' + Q.wrong\n    + (earn > 0 ? '<br><span class=\"tiny\">+ ' + earn + ' 专注币（已记进统计）</span>' : '')\n    + '<br><span class=\"tiny\">每道题的结果都已经写回对应卡片（等级、对错次数）。</span>');\n  /* ⚠️ 这里以前没调记账：答完最后一题自动结束时，流水不写、币也不发 ——\n     只有点「结束本轮」才会记账，所以你看到「完成抽背没有币」。\n     现在无论从哪条路结束，都在这里统一记一笔（rcQLog 自身是幂等的）。 */\n  rcQLog();\n  rcQSync();\n  render();\n}\n/* 记进背诵流水：统计页和报告都读它 */\nasync function rcQLog() {\n  const Q = rcQ();\n  /* 幂等闸：「答完最后一题自动结束」「点结束本轮」「换一批重来」三条路都会走到记账，\n     加个标记，保证同一轮只记一笔、只发一次币。 */\n  if (Q.logged) return;\n  const t = Q.right + Q.near + Q.wrong;\n  if (!t) { Q.logged = true; return; }\n  Q.logged = true;\n  const per = Math.max(0, Number(cfg('rcCoinPerCard') != null ? cfg('rcCoinPerCard') : 0.2));\n  const earn = Math.round(t * per);\n  const rec = {\n    date: dkey(), at: Date.now(), bookId: Q.bookId || '', scope: 'chat',\n    total: t, right: Q.right + Q.near, wrong: Q.wrong,\n    dictationN: Q.items.filter(x => x.form === 'dict').length,\n    dictationRight: Q.right, newN: 0, weakN: 0,\n    ms: Date.now() - (Q.startedAt || Date.now()),\n    /* 把这一轮的一问一答一起留档 —— 以前只存了个条数，聊过什么全丢了，\n       想回头看看「上次哪几题错了」根本没处翻。 */\n    chat: (Q.log || []).slice(-60).map(m => ({\n      role: m.role, at: m.at || 0, charId: m.charId || '',\n      text: String(m.text || '').slice(0, 800)\n    }))\n  };\n  if (earn > 0) rec.coin = earn;\n  await rcLogAdd(rec);\n  if (earn > 0) await coinAdd(earn, '抽背 ' + t + ' 条');\n}\n/* ---------- 抽背历史：以前聊完就没了，现在每一轮都留着 ---------- */\nfunction rcChatHist() {\n  return (S.rlogs || [])\n    .filter(x => x && x.scope === 'chat')\n    .sort((a, b) => (b.at || 0) - (a.at || 0));\n}\nfunction rcChatHistHTML() {\n  const list = rcChatHist();\n  if (!list.length) return '';\n  const openId = String(S.draft.rcHistOpen || '');\n  return `<div class=\"card\">\n    <div class=\"row between\"><h3>📚 抽背历史（${list.length} 轮）</h3>\n      <span class=\"tiny\">点一轮展开看当时的一问一答</span></div>\n    <div class=\"tiny mt6\">每一轮抽背都完整留着：出过的题、你怎么答的、判定和参考答案。删掉某一轮，统计里的条数会跟着减少，但<b>卡片自己的等级和错次不受影响</b>。</div>\n    <div class=\"mt10\">${list.slice(0, 30).map(h => {\n      const open = openId === String(h.id);\n      return `<div class=\"card tight\" style=\"background:var(--card2);margin-bottom:8px;border-color:${open ? 'rgba(124,140,255,.5)' : 'var(--line)'}\">\n        <div data-act=\"rcHistOpen\" data-id=\"${esc(h.id || '')}\" style=\"cursor:pointer\">\n          <div class=\"row between\">\n            <span class=\"tiny\">${esc(h.date || '')} ${h.at ? hm(h.at) : ''} · ${h.bookId ? esc(rcBookName(h.bookId)) : '全部词本'}</span>\n            <span class=\"tiny\">${open ? '收起 ▲' : '展开 ▼'}</span></div>\n          <div class=\"tiny mt6\">共 ${Number(h.total) || 0} 题 · ✅ ${Number(h.right) || 0} · ❌ ${Number(h.wrong) || 0}${Number(h.coin) ? ' · +' + h.coin + ' 币' : ''}${h.ms ? ' · 用时 ' + fmtDur(h.ms / 1000) : ''}</div>\n        </div>\n        ${open ? `<div class=\"mt8\" style=\"max-height:46vh;overflow-y:auto\">\n          ${(h.chat || []).length ? (h.chat || []).map(m => rcQMsgHTML(m)).join('') : '<div class=\"tiny\">这一轮没留下对话明细（是改版前的旧记录）。</div>'}\n          <div class=\"row mt8\" style=\"gap:8px\">\n            <button class=\"btn sm ghost grow\" data-act=\"rcHistDel\" data-id=\"${esc(h.id || '')}\">删掉这一轮</button></div>\n        </div>` : ''}\n      </div>`;\n    }).join('')}</div>\n  </div>`;\n}\nVIEWS.rcchat = function () {\n  const Q = rcQ();\n  const books = rcActiveBooks();\n  const poolN = rcQPool().length;\n  return `\n  <div class=\"card tight\">\n    <div class=\"row between\"><h3 style=\"margin:0\">🎤 抽背 · 聊天室</h3>\n      <span class=\"pill ${Q.run ? 'run' : ''}\">${Q.run ? ('进行中 ' + Math.min(Q.i + 1, Q.items.length) + '/' + Q.items.length) : '未开始'}</span></div>\n    <div class=\"tiny mt6\">TA 出题、你作答，一问一答。每题都会把题目完整摆出来再等你答 —— 不语音、不藏题干。</div>\n    ${!Q.run ? `\n    <label class=\"fl\">抽哪个词本</label>\n    <div class=\"chips\">\n      <button class=\"chip ${!Q.bookId ? 'on' : ''}\" data-act=\"rcChatBook\" data-v=\"\">全部（${rcCards().length} 张）</button>\n      ${books.map(b => `<button class=\"chip ${String(Q.bookId) === String(b.id) ? 'on' : ''}\" data-act=\"rcChatBook\" data-v=\"${esc(b.id)}\">${esc(b.name)}（${rcCardN(b.id)}）</button>`).join('')}\n    </div>\n    <label class=\"fl\">考几题</label>\n    <input class=\"input\" type=\"number\" inputmode=\"numeric\" data-in=\"rcChatN\" value=\"${Number(Q.n) || 5}\">\n    <label class=\"fl\">考察形式</label>\n    <div class=\"chips\">${RCQ_FORMS.map(x => `<button class=\"chip ${Q.form === x[0] ? 'on' : ''}\" data-act=\"rcChatForm\" data-v=\"${x[0]}\">${x[1]}</button>`).join('')}</div>\n    <label class=\"fl\">出题方式</label>\n    <div class=\"chips\">\n      <button class=\"chip ${!Q.useAI ? 'on' : ''}\" data-act=\"rcChatAI\" data-v=\"0\">🧠 纯本地出题（不接 AI）</button>\n      <button class=\"chip ${Q.useAI ? 'on' : ''}\" data-act=\"rcChatAI\" data-v=\"1\">🤖 让 AI 换个问法</button>\n    </div>\n    <div class=\"tiny mt6\">纯本地出题完全不调用大模型，题目直接取自卡片的题干与答案${Q.useAI ? '；AI 模式每题多花一次你自己的 API，失败会自动回落到本地题。' : '。'}</div>\n    <button class=\"btn primary block mt12\" data-act=\"rcChatStart\" ${poolN ? '' : 'disabled'}>${poolN ? ('开始抽背（可抽 ' + poolN + ' 张）') : '还没有可抽的卡片'}</button>\n    ` : `\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn sm grow\" data-act=\"rcChatAgain\">↺ 换一批重来</button>\n      <button class=\"btn sm ghost grow\" data-act=\"rcChatStop\">结束本轮</button></div>\n    <div class=\"tiny mt10\">本轮：✅ ${Q.right} · 🟡 ${Q.near} · ❌ ${Q.wrong}${Q.useAI ? ' · AI 出题' : ' · 本地出题'}</div>\n    `}\n  </div>\n  ${(Q.log || []).length ? `<div class=\"card\" id=\"rcChatBox\" style=\"max-height:52vh;overflow-y:auto\">${Q.log.map(m => rcQMsgHTML(m)).join('')}</div>` : ''}\n  ${Q.run ? `<div class=\"card tight\">\n    <div class=\"row\" style=\"gap:8px\">\n      <input class=\"input grow\" data-in=\"rcChatInput\" value=\"${esc(S.draft.rcChatInput || '')}\" placeholder=\"${Q.waiting ? '把你的答案打在这里…' : '（正在出下一题…）'}\" ${Q.waiting ? '' : 'disabled'}>\n      <button class=\"btn primary\" data-act=\"rcChatSend\" ${Q.waiting ? '' : 'disabled'}>发送</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"rcChatHint\" ${Q.waiting ? '' : 'disabled'}>给点提示</button>\n      <button class=\"btn sm ghost grow\" data-act=\"rcChatSkip\" ${Q.waiting ? '' : 'disabled'}>不会，看答案</button></div>\n  </div>` : ''}\n  ${Q.run ? '' : rcChatHistHTML()}`;\n};\n/* AI 换问法：失败一律回落本地题，绝不因此卡住这一轮 */\n/* AI 换问法：原来是一口气把所有题都过一遍 API ——\n   题多的时候要等很久，中间还整屏空白、也看不到进度。\n   现在只给当前这一题换问法，进到哪题换哪题，失败就用本地题，绝不卡住。 */\nasync function rcQFillAI() {\n  const Q = rcQ();\n  if (!Q.useAI) return;\n  const it = Q.items[Q.i];\n  if (!it || it.aiDone) return;\n  try {\n    const ret = await Promise.resolve(rcAiVariant(it.card));\n    const one = (ret && ret.length) ? ret[0] : null;\n    if (one && one.q) { it.q = String(one.q); if (one.a) it.a = String(one.a); it.form = 'dict'; }\n  } catch (e) { }\n  it.aiDone = true;\n}\nObject.assign(ACTIONS, {\n  rcChatBook: el => { rcQ().bookId = el.dataset.v || ''; rcQSync(); render(); },\n  rcChatForm: el => { rcQ().form = el.dataset.v || 'mix'; rcQSync(); render(); },\n  rcChatAI: el => { rcQ().useAI = el.dataset.v === '1'; rcQSync(); render(); },\n  /* 退出视图 / 离开这一轮也要落一份，回来能接着答 */\n  rcChatSync: () => { rcQSync(); },\n  rcChatStart: async () => {\n    const Q = rcQ();\n    Q.n = Math.max(1, Math.min(50, Number(S.draft.rcChatN || Q.n) || 5));\n    const items = rcQMake(Q.n, Q.form);\n    if (!items.length) { toast('这个词本还没有卡片'); return; }\n    Q.items = items;\n    Q.i = 0; Q.right = 0; Q.near = 0; Q.wrong = 0; Q.run = true; Q.waiting = false; Q.log = [];\n    Q.startedAt = Date.now();\n    Q.cur = null; Q.hinted = false; Q.needAsk = false; Q.logged = false;\n    rcQClearSteps();\n    rcQPush('sys', '抽背开始 · 共 ' + items.length + ' 题' + (Q.useAI ? ' · AI 换问法' : ' · 本地出题'));\n    rcQSync();\n    render();\n    if (Q.useAI) { toast('正在让 AI 换问法…'); await rcQFillAI(); }\n    rcQAsk();\n  },\n  rcChatAgain: async () => { const Q = rcQ(); await rcQLog(); Q.run = false; rcQClearSteps(); rcQSync(); render(); ACTIONS.rcChatStart(); },\n  rcChatStop: async () => { const Q = rcQ(); if (Q.run) await rcQLog(); rcQFinish(); },\n  rcChatSend: async () => {\n    const Q = rcQ();\n    if (!Q.run || !Q.waiting || !Q.cur) return;\n    const box = document.querySelector('[data-in=\"rcChatInput\"]');\n    const txt = String((box ? box.value : S.draft.rcChatInput) || '').trim();\n    if (!txt) { toast('先写下你的答案'); return; }\n    S.draft.rcChatInput = '';\n    const it = Q.cur; Q.waiting = false;\n    rcQPush('me', txt);\n    /* 接力题：一句一句判、一句一句答，不走整段判分 */\n    if (rcQRelaySend(Q, it, txt)) return;\n    const r = rcQJudge(it, txt);\n    if (r.rate >= 2) Q.right++; else if (r.rate === 1) Q.near++; else Q.wrong++;\n    await rcQSave(it, r.rate);\n    /* 判定、参考答案、漏词拆成三条发 —— 一口气一大段既不像人，也看不清 */\n    const steps = [];\n    if (r.rate >= 2) steps.push('✅ 对了' + (r.pct < 100 ? '（覆盖 ' + r.pct + '%）' : '') + '。');\n    else if (r.rate === 1) steps.push('🟡 差一点，意思到了但不全。');\n    else steps.push('❌ 不对。');\n    steps.push('<span class=\"tiny\">参考答案：' + esc(it.a) + '</span>');\n    if (r.miss && r.miss.length) steps.push('<span class=\"tiny\">漏掉的关键词：' + esc(r.miss.join('、')) + '</span>');\n    rcQSteps(steps, rcQChar());\n    Q.i++;\n    rcQSync();\n    render();\n    rcQScroll();\n    setTimeout(rcQAsk, 900);\n  },\n  rcChatSkip: async () => {\n    const Q = rcQ();\n    if (!Q.run || !Q.waiting || !Q.cur) return;\n    Q.waiting = false;\n    const it = Q.cur;\n    Q.wrong++;\n    await rcQSave(it, 0);\n    rcQPush('me', '（不会）');\n    rcQSteps(['答案：' + esc(it.a), '<span class=\"tiny\">这张记「不会」，下次还会优先抽到它。</span>'], rcQChar());\n    Q.i++;\n    rcQSync();\n    render();\n    setTimeout(rcQAsk, 900);\n  },\n  rcChatHint: () => {\n    const Q = rcQ();\n    if (!Q.run || !Q.cur || Q.hinted) return;\n    const it = Q.cur;\n    Q.hinted = true;\n    let kw = [];\n    try { kw = rcKeywords(it.card).filter(Boolean); } catch (e) { kw = []; }\n    rcQSteps([\n      '提示：答案共 ' + it.a.length + ' 个字，开头是「' + esc(it.a.charAt(0)) + '」' + (kw.length ? '，关键词：' + esc(kw.slice(0, 4).join('、')) : '') + '。',\n      '<span class=\"tiny\">（提示不算答对，答案还是要你自己写出来）</span>'\n    ], rcQChar());\n    render();\n  },\n  /* 覆盖旧入口：词本页那个「🎤 让 TA 抽背」按钮（data-act=rcAiPetOpen）直接落到\n     聊天室这里，不用改视图 HTML，旧按钮也不会变成死键。 */\n  rcAiPetOpen: () => {\n    if (S.recite && S.recite.queue && S.recite.idx < S.recite.queue.length) {\n      toast('你还有一轮没背完 —— 先把它结束再开新的');\n      return;\n    }\n    closeAllSheets();\n    go('rcchat');\n  },\n  /* 词本页那个「🎤 让 TA 抽背」如果没落在聊天室里，用这个兜一下 */\n  rcChatOpen: () => { closeAllSheets(); go('rcchat'); },\n  /* 展开 / 收起某一轮抽背的问答明细 */\n  rcHistOpen: el => {\n    const id = String(el.dataset.id || '');\n    S.draft.rcHistOpen = (String(S.draft.rcHistOpen || '') === id) ? '' : id;\n    render();\n  },\n  rcHistDel: async el => {\n    const id = String(el.dataset.id || '');\n    const rec = (S.rlogs || []).find(x => String(x.id) === id);\n    if (!rec) { toast('这条记录找不到了'); return; }\n    const ok = await confirmBox('删掉这一轮抽背记录？',\n      '这一轮的答题明细会消失，统计里的条数也会跟着减少 ' + (Number(rec.total) || 0) + ' 条' + (Number(rec.coin) ? '、币 ' + rec.coin + ' 点' : '') + '。\\n\\n卡片自己的等级和错次不受影响 —— 那部分早就写进卡片了。', '删掉这一轮');\n    if (!ok) return;\n    await DB.remove(T.RLOG, id);\n    S.rlogs = (S.rlogs || []).filter(x => String(x.id) !== id);\n    S.draft.rcHistOpen = '';\n    toast('已删掉这一轮记录');\n    render();\n  }\n});\nTITLES.rcchat = ['抽背 · 聊天室', 'RECITE'];\n/* @@RC_NEXT@@ */\n/* ==========================================================\n   数据加载与启动\n   ========================================================== */\nasync function loadAll() {\n  /* 宿主 db.list 返回的是扁平记录；老版本有些表保存成了 { data: {...} }。\n     两种都兼容，否则通行证/会话重启后会变成空对象。 */\n  const dbRow = (r) => Object.assign({}, r && r.data && typeof r.data === 'object' ? r.data : (r || {}), { dbId: r && r.id });\n  const [sess, priv, pub, puns, gifts, ledger, sleeps, qbank, alarms, album, rewards, wlp] = await Promise.all([\n    DB.list(T.SESSION), DB.list(T.PRIV), DB.list(T.PUB), DB.list(T.PUN), DB.list(T.GIFT),\n    DB.list(T.LEDGER), DB.list(T.SLEEP), DB.list(T.QBANK), DB.list(T.ALARM), DB.list(T.ALBUM), DB.list(T.REWARD), DB.list(T.WLP)\n  ]);\n  const cutoff = Date.now() - 90 * 24 * 3600 * 1000;\n  S.sessions = (sess || []).map(dbRow).filter(x => x.startAt && x.startAt > cutoff);\n  S.priv = (priv || []).slice().sort((a, b) => b.at - a.at);\n  S.pub = (pub || []).slice().sort((a, b) => b.at - a.at);\n  S.puns = (puns || []).map(dbRow).sort((a, b) => b.at - a.at);\n  S.gifts = (gifts || []).slice().sort((a, b) => b.at - a.at);\n  S.ledger = (ledger || []).slice().sort((a, b) => b.at - a.at);\n  S.sleeps = (sleeps || []).slice().sort((a, b) => b.startAt - a.startAt);\n  S.gen = ((await DB.list(T.GEN)) || []).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.fav = ((await DB.list(T.FAV)) || []).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.appts = ((await DB.list(T.APPT)) || []).filter(x => x && x.startAt).sort((a, b) => (a.startAt || 0) - (b.startAt || 0));\n  S.todos = ((await DB.list(T.TODO)) || []).filter(x => x && x.text).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.invites = ((await DB.list(T.INVITE)) || []).filter(x => x && x.kind).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.qlogs = ((await DB.list(T.QA)) || []).filter(x => x && x.q).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.qa = ((await DB.list(T.QA)) || []).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.notes = ((await DB.list(T.NOTE)) || []).filter(x => x && x.text).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.qbank = (qbank || []).map(q => {\n    const c = Object.assign({}, q);\n    if (c.right == null) c.right = 0;\n    if (c.wrong == null) c.wrong = 0;\n    if (c.mastered == null) c.mastered = false;\n    if (!c.cat) c.cat = c.cat || '';\n    return c;\n  });\n  /* 老题库里的分类自动补进分类表，免得分类下拉是空的 */\n  {\n    const set = {};\n    (cfg('bankCats') || []).forEach(c => { if (c) set[c] = 1; });\n    S.qbank.forEach(q => { if (q.cat) set[q.cat] = 1; });\n    const merged = Object.keys(set);\n    if (merged.length !== (cfg('bankCats') || []).length) { S.settings.bankCats = merged; saveSettings(); }\n  }\n  /* 背书模块：词本 / 卡片 / 背诵流水 */\n  S.books = ((await DB.list(T.BOOK)) || []).filter(x => x && x.name).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.cards = ((await DB.list(T.CARD)) || []).filter(x => x && x.q).sort((a, b) => (a.order || 0) - (b.order || 0) || (a.at || 0) - (b.at || 0));\n  S.rlogs = ((await DB.list(T.RLOG)) || []).filter(x => x && x.date).sort((a, b) => (b.at || 0) - (a.at || 0));\n  S.alarms = (alarms || []).filter(x => x.enabled !== false);\n  S.wlPasses = (wlp || []).map(dbRow);\n  await repairWlPassPackages();\n  S.album = (album || []).slice().sort((a, b) => b.at - a.at);\n  S.rewards = (rewards || []).map(dbRow).sort((a, b) => b.at - a.at);\n  // 兼容旧版本：睡眠壁纸当年被默认上锁了，导致在壁纸库里存不下来 —— 这里统一解锁\n  for (const it of (S.album || []).filter(x => x.kind === 'sleep' && x.locked)) {\n    it.locked = false;\n    if (it.id) await DB.update(T.ALBUM, it.id, JSON.parse(JSON.stringify(Object.assign({}, it, { locked: false, dataUrl: '' }))));\n  }\n  await loadCustomWall();     // 你上传过的壁纸：启动时从媒体库取回来铺上\n  await loadStories();\n}\nasync function boot() {\n  setTimeout(() => { try { consumePendingApply(); } catch (e) { } }, 800);\n  try {\n    if (!API) {\n      $('#view').innerHTML = `<div class=\"card\"><h3>请在「小手机」里打开本 APP</h3>\n        <div class=\"sub\">这个应用依赖小手机提供的角色与 AI 能力，需要在应用内运行。</div></div>`;\n      return;\n    }\n    registerTools();          // 角色工具：APP 没打开时宿主也能把这段脚本拉起来执行\n    startInviteListener();    // 卡片指令监听：[陪睡:…] / [约专注:…]\n    await loadSettings();\n    await loadChars();\n    await loadAll();\n    clearBadge();\n    S.lastSleepWallRef = cfg('lastSleepWallRef') || '';\n    S.lastSleepInfo = cfg('lastSleepInfo') || null;\n    const liveSleep = await restoreSleepSession();   // 之前没结束的睡眠：接着计时\n    if (liveSleep && !liveSleep.wp && !liveSleep.wpRef) genSleepWallpaper();   // 之前那次没留下壁纸，补生成\n    const live = S.sessions.filter(s => s.status === 'running').sort((a, b) => b.startAt - a.startAt)[0];\n    if (live && Date.now() - live.startAt < 12 * 3600 * 1000) {\n      S.session = live; startTicking(); S.view = 'running';\n      restoreWallpaper(live);\n      /* 重开 APP 时补一次「离开」判定：页面被销毁期间收不到任何事件，用上次心跳算离开时长。\n         ⚠️ 旧版这里还多要求「倒计时没到点」（remainSec() > 0）—— 而倒计时按墙上时间走，\n         你离开的时间一超过剩余时长，整段离开就没人记账，表现就是「关掉应用检测不到」。\n         现在无论到没到点都会判；判定结果会当场告诉你，不用猜。 */\n      try {\n        const aliveAt = Number(live.lastAliveAt || 0);\n        if (aliveAt) {\n          const awaySec = Math.round((Date.now() - aliveAt) / 1000);\n          const grace = Number(cfg('graceSec') || 8);\n          if (awaySec > grace) await onAway(awaySec);\n          else if (awaySec > 1) toast('重开 APP：离开 ' + awaySec + ' 秒，在宽限 ' + grace + ' 秒内，不计违规');\n        }\n      } catch (e) { }\n    } else if (live) {\n      live.status = 'failed';\n      await DB.update(T.SESSION, live.dbId || live.id, { data: live });\n    }\n    const review = S.sessions.filter(s => s.status === 'review').sort((a, b) => b.startAt - a.startAt)[0];\n    if (!S.session && review) { S.session = review; S.view = 'review'; }\n    const pend = pendingPunish()[0];\n    if (pend) S.lock = { punish: pend };\n    const lastSleep = (S.sleeps || [])[0];\n    if (lastSleep && lastSleep.seconds > 60) {\n      S.report = Object.assign(\n        { rec: lastSleep, loading: false, quality: '', observe: '', advice: '', murmur: '', charId: anyCharId() },\n        lastSleep.report || {}\n      );\n      if (!S.report.quality) {   // 兼容旧记录：报告还没落库时，从对外记忆里补一句话\n        const pub = (S.pub || []).find(p => p.kind === 'sleep');\n        if (pub) S.report.quality = String(pub.text).replace(/^睡眠报告[^：]*：/, '');\n      }\n    }\n    startSleepTicker();\n    if (liveSleep) toast('已接着上次的睡眠记录：' + liveSleep.mode + ' · 已睡 ' + fmtDur((Date.now() - liveSleep.startAt) / 1000));\n    startAlarmLoop();\n    startApptLoop();\n    startMorningLoop();\n    if ((cfg('alarm') || {}).enabled) scheduleAlarm(cfg('alarm'), true);\n    if (morningCfg().enabled) scheduleMorning(morningCfg(), true);\n    /* 从聊天室 + 号面板进来：直接落到对应的邀请页，并带上当前对话的角色\n       （running / 锁定 / 待校验这些状态优先，不会被邀请页抢走） */\n    /* 从聊天室进来：按 launchContext 精确落到对应页面。\n       以前是靠 entry/actionId 里出现 'sleep' / 'focus' 猜的 —— 一旦宿主改了命名\n       或两个关键词同时出现就会跳错页。现在改成「显式映射表 + 兜底」，能对上就用映射，\n       对不上才退回关键词判断。 */\n    const lc = await sdk(() => API.app.getLaunchContext(), null);\n    if (lc && (lc.source === 'chat_plus_action' || lc.source === 'chat_directive' || lc.directiveId || lc.directiveArgs)) {\n      S.draft.inviteFromChat = !!(lc.source === 'chat_plus_action');\n      if (lc.characterId) S.draft.inviteChar = lc.characterId;\n      S.draft.launchSource = lc.source || '';\n      /* 一、+ 号面板 / 卡片叫得出名字的入口：直接映射到页面 */\n      const JUMP = {\n        'focus-invite': 'invite:focus', 'focus_invite': 'invite:focus',\n        'sleep-companion': 'invite:sleep', 'sleep_companion': 'invite:sleep',\n        'sleep-invite': 'invite:sleep', 'sleep_invite': 'invite:sleep',\n        'appointment': 'page:appt', 'appt': 'page:appt', 'focus-appt': 'page:appt',\n        'todos': 'page:todos', 'todo': 'page:todos',\n        'bottle': 'page:bottle', 'star-jar': 'page:bottle',\n        'album': 'page:album', 'gallery': 'page:album',\n        'coin': 'page:coin', 'goals': 'page:goals', 'bond': 'page:bond', 'wish': 'page:bond',\n        'qbank': 'page:qbank', 'quiz': 'page:qbank', 'mistakes': 'page:mistakes',\n        'invites': 'page:invites', 'sleep': 'page:sleep', 'stats': 'page:stats',\n        'checks': 'page:checks', 'rewards': 'page:rewards', 'genlog': 'page:genlog'\n      };\n      /* 先分清「卡片」和「+ 号面板」—— 这是两种完全不同的入口，必须分开对待：\n         · 卡片：TA 主动发来的邀请 → 该进「TA 的邀请」列表（能答应、能改时间、能看到完成情况）；\n         · + 号面板：你自己发起邀约 → 才进「专注邀约 / 睡眠陪伴」表单页。\n         ⚠️ 以前那张 JUMP ",
  "映射表排在卡片判断前面，而卡片的 directiveId 常写成\n         sleep-invite / focus-invite 这种，正好和 + 号面板入口名撞车 ——\n         于是点 TA 的卡总被送到「我自己发邀请」的表单上。这就是跳错页的根。 */\n      const fromPlus = (lc.source === 'chat_plus_action');\n      const isCard = !fromPlus && !!(lc.directiveId || lc.directiveLabel || lc.directiveRaw || lc.messageId || lc.source === 'chat_directive');\n      const cands = isCard ? [] : [lc.entry, lc.actionId, lc.entryId].filter(Boolean).map(v => String(v).trim());\n      let jump = isCard ? 'page:invites' : '';\n      for (const c of cands) {\n        const key = c.toLowerCase();\n        if (JUMP[key]) { jump = JUMP[key]; break; }\n        // 也容忍后缀写法，如 focus-app-plus-action-2 → 取到 focus\n        const seg = key.split(/[-_:.]/).filter(Boolean);\n        for (const sg of seg) { if (JUMP[sg]) { jump = JUMP[sg]; break; } }\n        if (jump) break;\n      }\n      /* 二、+ 号面板兜底：source 没写清楚时，靠入口名判断是不是面板入口 */\n      const dirKey = String(lc.directiveId || '').toLowerCase();\n      const cardIsSleep = dirKey.indexOf('sleep') >= 0 || dirKey.indexOf('陪睡') >= 0;\n      const cardIsFocus = dirKey.indexOf('focus') >= 0 || dirKey.indexOf('约专注') >= 0 || dirKey.indexOf('appt') >= 0;\n      /* 三、还是没有跳到任何地方：退回关键词兜底（老包兼容）——\n         卡片一律去「TA 的邀请」，面板才去表单页。 */\n      if (!jump) {\n        const key = String((lc.entry || lc.actionId || '') + ' ' + (lc.directiveId || '')).toLowerCase();\n        const hitSleep = (key.indexOf('sleep') >= 0 || key.indexOf('陪睡') >= 0);\n        const hitFocus = (key.indexOf('focus') >= 0 || key.indexOf('约专注') >= 0);\n        if (hitSleep) jump = fromPlus ? 'invite:sleep' : 'page:invites';\n        else if (hitFocus) jump = fromPlus ? 'invite:focus' : 'page:invites';\n      }\n      const busyNow = !!S.lock || !!(S.session && S.session.status === 'running') || S.sleep;\n      if (jump && !busyNow) {\n        const [kind, target] = jump.split(':');\n        S.navHistory = [];\n        if (kind === 'invite') {\n          S.draft.inviteKind = target === 'sleep' ? 'sleep' : 'focus';\n          S.draft.invitePlan = 'now';\n          /* 卡片上写的时长 / 事项直接预填，用户少填一遍 */\n          const a = lc.directiveArgs || {};\n          const aTask = a['事项'] || a.task || a['做的事'] || '';\n          const aMin = Number(a['分钟'] || a.minutes || a['时长'] || 0);\n          const aMode = a['模式'] || a.mode || '';\n          const aTime = a['时间'] || a.time || '';\n          if (aTask) S.draft.inviteTask = String(aTask);\n          if (aMin > 0) { if (target === 'sleep') S.draft.invMin = aMin; else S.draft.inviteMin = aMin; }\n          if (target === 'sleep' && aMode && ['小憩', '午睡', '长睡眠'].indexOf(String(aMode)) >= 0) S.draft.invMode = String(aMode);\n          if (target === 'focus') {\n            /* 卡里带了具体时间：直接按「预订」打开，省得用户再填 */\n            const mt = String(aTime).match(/^(\\d{1,2})[:：](\\d{2})$/);\n            if (mt) {\n              const d = new Date(); d.setHours(clamp(Number(mt[1]), 0, 23), clamp(Number(mt[2]), 0, 59), 0, 0);\n              if (d.getTime() <= Date.now()) d.setDate(d.getDate() + 1);\n              S.draft.invitePlan = 'book';\n              S.draft.inviteDate = dkey(d);\n              S.draft.inviteTime = pad2(d.getHours()) + ':' + pad2(d.getMinutes());\n            }\n          }\n          const d0 = inviteDefaultDate();\n          if (!S.draft.inviteDate) S.draft.inviteDate = d0.date;\n          if (!S.draft.inviteTime) S.draft.inviteTime = d0.time;\n          S.view = 'invite';\n        } else if (kind === 'page' && VIEWS[target]) {\n          S.view = target;\n          /* 从 TA 的邀请卡进来、但邀请记录里可能还没有对应那一条（宿主当时没把\n             监听拉起来，或卡片是更早发来的）—— 把卡片上写的参数带过去，\n             列表页用它兜底出一条「现在就能接受」的邀请，别让你扑空。 */\n          if (target === 'invites') {\n            /* 卡片参数有两个来源，必须都用上：\n               ① 宿主解析好的 directiveArgs；\n               ② 卡片原文（directiveRaw / directiveLabel / directiveText）。\n               以前只看 ① —— 很多环境里它是空的，于是「几点」「多久」「做什么」\n               全丢，时间也就永远填不进表单。这里用 parseInviteDirectives 从原文兜底。 */\n            const a = lc.directiveArgs || {};\n            const rawCard = String(lc.directiveRaw || lc.directiveLabel || lc.directiveText || '');\n            const dHit = parseInviteDirectives(rawCard)[0] || null;\n            const kindGuess = cardIsSleep ? 'sleep' : 'focus';\n            const fromArg = (k1, k2, dflt) => {\n              const v = (a[k1] != null && String(a[k1]) !== '') ? a[k1] : a[k2];\n              if (v != null && String(v) !== '') return v;\n              if (dHit && dHit.kind === kindGuess) {\n                if (k1 === '事项') return dHit.task || dflt;\n                if (k1 === '分钟') return dHit.minutes || dflt;\n                if (k1 === '模式') return dHit.mode || dflt;\n                if (k1 === '时间') return dHit.time || dflt;\n              }\n              return dflt;\n            };\n            S.draft.cardInvite = {\n              kind: kindGuess,\n              task: String(fromArg('事项', 'task', '') || '').slice(0, 60),\n              minutes: Number(fromArg('分钟', 'minutes', 0)) || 0,\n              mode: String(fromArg('模式', 'mode', '')),\n              time: String(fromArg('时间', 'time', '')),\n              cardMessageId: String(lc.messageId || ''),\n              at: Date.now()\n            };\n            /* 当场把它落成一条真邀请：列表里就有完整的\n               「答应他 / 改个时间 / 先不了」，不会再出现「只有答应一个按钮、\n               点下去直接开始、改时间的卡一闪而过」。 */\n            try { await ensureCardInvite(); } catch (e) { }\n          }\n        }\n      } else if (jump && busyNow) {\n        toast('你现在有正在进行的专注 / 睡眠，先把这一段走完');\n      }\n    }\n    /* 有约好的专注没开始、还没补写说明 —— 打开 APP 直接跳到那一页 */\n    const pendingMissed = (S.appts || []).filter(x => x.needEssay && x.status === 'missed').sort((x, y) => (y.missedAt || 0) - (x.missedAt || 0))[0];\n    if (pendingMissed && !S.lock) {\n      S.draft.missedId = pendingMissed.id;\n      S.draft.missWhy = S.draft.missWhy || '';\n      S.navHistory = [];\n      S.view = 'missed';\n    }\n    try { await loadCustomWall(); } catch (e) { }\n    S.ready = true;\n    render();\n    /* 打开 APP 先回扫一遍聊天：把「角色写过卡片、但当时没记下来」的邀请补进列表。\n       放在 render 之后 —— 先把界面给你，再悄悄补，不让你干等。 */\n    setTimeout(() => { try { backfillInvites(); } catch (e) { } }, 900);\n    setTimeout(() => { if (S.view === 'running') scrollMsgs(); }, 120);\n  } catch (e) {\n    console.warn('boot failed', e);\n    $('#view').innerHTML = `<div class=\"card\"><h3>初始化失败</h3><div class=\"sub\">${esc((e && e.message) || e)}</div>\n      <button class=\"btn primary block mt10\" data-act=\"reload\">重试</button></div>`;\n  }\n}\nACTIONS.reload = () => location.reload();\n/* ==========================================================\n   本版新增 · TA 主动来约你（工具 / 卡片指令 / 待办 / 邀请）\n   ----------------------------------------------------------\n   ① 6 个角色工具：查专注情况 / 看昨晚睡得怎么样 / 帮我记一条待办 /\n      跟我约一段专注 / 邀我一起睡 / 解除看守锁。角色在普通聊天里就能调用；\n      APP 没打开时宿主会临时拉起这段脚本执行 handler。\n   ② 两种卡片指令：[陪睡:模式:分钟:想说的话]、[约专注:时间:事项:分钟]\n      —— 后台监听聊天新消息，收到就写进「TA 的邀请」并发通知。\n   ③ 待办清单：TA 记的待办会出现在首页，可直接转成本次专注任务。\n   ========================================================== */\n/* ---------- 待办清单 ---------- */\nasync function saveTodo(t) {\n  if (!t) return null;\n  if (t.id) { await DB.update(T.TODO, t.id, JSON.parse(JSON.stringify(t))); return t; }\n  const r = await DB.create(T.TODO, t);\n  if (r) { t.id = r.id; S.todos = [t].concat(S.todos || []); }\n  return t;\n}\nasync function pushTodo(text, note, minutes, charId, from) {\n  const t = {\n    id: '', text: String(text || '').slice(0, 80), note: String(note || '').slice(0, 120),\n    minutes: Number(minutes) || 0, charId: charId || '', from: from || 'me',\n    done: false, at: Date.now(), date: dkey()\n  };\n  if (!t.text) return null;\n  return await saveTodo(t);\n}\nfunction todosHTML() {\n  const open = (S.todos || []).filter(t => !t.done);\n  if (!open.length) return '';\n  const t0 = open[0];\n  return `<div class=\"card tight\" style=\"border-color:rgba(94,234,212,.35)\">\n    <div class=\"row between\"><div class=\"grow\">\n      <div class=\"tiny\">📝 待办（${open.length} 条没做）</div>\n      <div style=\"font-size:14px\">${esc(t0.text)}${t0.charId ? ' <span class=\"tiny\">· ' + esc(charName(t0.charId)) + ' 记的</span>' : ''}</div>\n      ${t0.note ? `<div class=\"tiny mt6\" style=\"color:var(--dim2)\">${esc(t0.note)}</div>` : ''}</div>\n      <button class=\"btn sm\" data-act=\"todoToTask\" data-id=\"${esc(t0.id)}\">拿去专注</button></div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn sm ghost grow\" data-act=\"gotoView\" data-view=\"todos\">看全部（${open.length}）</button>\n      <button class=\"btn sm ghost grow\" data-act=\"todoDone\" data-id=\"${esc(t0.id)}\">这条做完了</button></div>\n  </div>`;\n}\nVIEWS.todos = function () {\n  const all = (S.todos || []).slice().sort((a, b) => (a.done ? 1 : 0) - (b.done ? 1 : 0) || (b.at || 0) - (a.at || 0));\n  const open = all.filter(t => !t.done), done = all.filter(t => t.done);\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(94,234,212,.14),rgba(255,255,255,.03));border-color:rgba(94,234,212,.3)\">\n    <h3>📝 待办清单</h3>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">这里既有你自己记的，也有 <b>TA 在聊天里帮你记的</b>（他调用「帮我记一条待办」工具，或者你说「帮我记一下…」）。<br>\n    点「拿去专注」能把一条待办直接填进本次专注的任务里。</div>\n  </div>\n  <div class=\"card\"><h3>记一条</h3>\n    <input class=\"input\" id=\"todoText\" placeholder=\"要做的事，例如：把第三章笔记补完\">\n    <input class=\"input mt8\" id=\"todoNote\" placeholder=\"备注（可留空）\">\n    <div class=\"row\" style=\"gap:10px\">\n      <div class=\"grow\"><label class=\"fl\">预估分钟（可留空）</label>\n        <input class=\"input\" type=\"number\" inputmode=\"numeric\" id=\"todoMin\" placeholder=\"25\"></div>\n    </div>\n    <button class=\"btn primary block mt10\" data-act=\"todoAdd\">记下来</button></div>\n  ${open.length ? `<div class=\"card\"><h3>还没做（${open.length}）</h3>\n    ${open.map(t => `<div class=\"todo\">\n      <button class=\"ck\" data-act=\"todoDone\" data-id=\"${esc(t.id)}\">✓</button>\n      <div class=\"tx\">${esc(t.text)}\n        <div class=\"meta\">${t.charId ? esc(charName(t.charId)) + ' 记的 · ' : ''}${t.minutes ? '预估 ' + t.minutes + ' 分钟 · ' : ''}${dkey(new Date(t.at))}${t.note ? ' · ' + esc(t.note) : ''}</div></div>\n      <button class=\"btn sm primary\" style=\"flex:0 0 auto\" data-act=\"todoToTask\" data-id=\"${esc(t.id)}\">拿去专注</button>\n      <button class=\"btn sm ghost\" style=\"flex:0 0 auto\" data-act=\"todoDel\" data-id=\"${esc(t.id)}\">删</button></div>`).join('')}</div>`\n      : '<div class=\"empty\">没有待办。你可以在聊天里跟 TA 说「帮我记一下…」，他会记到这里。</div>'}\n  ${done.length ? `<div class=\"card\"><div class=\"row between\"><h3>已完成（${done.length}）</h3>\n    <button class=\"btn sm ghost\" data-act=\"todosClearDone\">清空已完成</button></div>\n    ${done.slice(0, 30).map(t => `<div class=\"item\" style=\"padding:8px 0\"><div class=\"ic\">✅</div>\n      <div class=\"grow\"><div style=\"font-size:12.8px;color:var(--dim)\">${esc(t.text)}</div>\n      <div class=\"tiny\">${t.date || ''}${t.charId ? ' · ' + esc(charName(t.charId)) : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"todoDel\" data-id=\"${esc(t.id)}\">删</button></div>`).join('')}</div>` : ''}`;\n};\nObject.assign(ACTIONS, {\n  todoAdd: async () => {\n    const text = ((document.getElementById('todoText') || {}).value || '').trim();\n    const note = ((document.getElementById('todoNote') || {}).value || '').trim();\n    const min = Number((document.getElementById('todoMin') || {}).value) || 0;\n    if (!text) { toast('先写一件要做的事'); return; }\n    await pushTodo(text, note, min, '', 'me');\n    toast('已记下'); render();\n  },\n  todoDone: async el => {\n    const t = (S.todos || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!t) return;\n    t.done = !t.done; t.doneAt = t.done ? Date.now() : 0;\n    await saveTodo(t);\n    toast(t.done ? '完成：' + t.text : '已取消完成');\n    render();\n  },\n  todoDel: async el => {\n    const t = (S.todos || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!t) return;\n    await DB.remove(T.TODO, t.id);\n    S.todos = (S.todos || []).filter(x => String(x.id) !== String(t.id));\n    render();\n  },\n  todosClearDone: async () => {\n    const done = (S.todos || []).filter(t => t.done);\n    if (!done.length) { toast('没有已完成的待办'); return; }\n    const ok = await confirmBox('清空已完成？', '会删掉 ' + done.length + ' 条已完成的待办。', '清空');\n    if (!ok) return;\n    for (const t of done) await DB.remove(T.TODO, t.id);\n    S.todos = (S.todos || []).filter(t => !t.done);\n    toast('已清空'); render();\n  },\n  todoToTask: async el => {\n    const t = (S.todos || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!t) return;\n    if (!S.draft.plan) initDraft();\n    S.draft.plan = (S.draft.plan || []).filter(p => p.content && p.content.trim());\n    S.draft.plan.push({ content: t.text, est: Number(t.minutes) || 0 });\n    t.usedAt = Date.now();\n    await saveTodo(t);\n    toast('已填进任务：' + t.text + '（去「开始专注」里看）');\n    go('setup');\n  }\n});\n/* 从卡片进来时，把卡片上带的东西落成一条真正的邀请记录。\n   为什么必须落：不落的话列表里没有对应那一条，只能临时拼一张「兜底卡」，\n   而兜底卡上只有「答应他」一个按钮 —— 点下去先补记录、再重画、紧接着直接开专注，\n   所以你看到的「改时间的卡只闪了一下」就是这么来的。\n   落了之后：列表里就是一条正常的邀请，\n   「✅ 答应他，到点来催 / 🕐 改个时间 / ⚡ 现在就提前开始」三个按钮都在，\n   而且答应过一次它就变成「已答应」，不会再让你答应第二次、第三次。 */\nasync function ensureCardInvite() {\n  const ci = S.draft && S.draft.cardInvite;\n  if (!ci) return null;\n  /* 已经因为这个 messageId 落过记录了，直接用那条 —— 不重复建 */\n  if (ci.cardMessageId) {\n    const hit = (S.invites || []).find(x => x && x.cardMessageId\n      && String(x.cardMessageId) === String(ci.cardMessageId) && x.kind === ci.kind);\n    if (hit) { S.draft.cardInvite = null; return hit; }\n  }\n  const cid = (S.draft.inviteChar || '').trim() || inviteCharId() || anyCharId();\n  if (!cid) return null;\n  const rec = await pushInvite({\n    kind: ci.kind === 'sleep' ? 'sleep' : 'focus',\n    task: String(ci.task || '').slice(0, 60),\n    minutes: Number(ci.minutes) || 0,\n    mode: String(ci.mode || ''),\n    time: String(ci.time || ''),\n    note: '',\n    charId: cid,\n    apptId: '',\n    cardMessageId: String(ci.cardMessageId || ''),\n    at: ci.at || Date.now(),\n    status: 'new',\n    from: 'directive'\n  });\n  if (rec) S.draft.cardInvite = null;   // 已落成真邀请，兜底卡就不必再显示了\n  return rec;\n}\n/* ---------- TA 的邀请（陪睡 / 约专注） ---------- */\nasync function pushInvite(rec) {\n  if (!rec || !rec.kind) return null;\n  /* 同一张卡片只留一条记录 —— 靠 cardMessageId 认。\n     没有这道闸时，每次从卡片进来都会新建一条，于是\n     「明明答应过了，还能再答应一次、两次」。\n     已经处理过的那条也不覆盖它的状态，只刷新卡片上带来的字段。 */\n  if (rec.cardMessageId) {\n    const same = (S.invites || []).find(x => x && x.cardMessageId\n      && String(x.cardMessageId) === String(rec.cardMessageId) && x.kind === rec.kind);\n    if (same) {\n      if (same.status === 'new' || same.status === 'stale') {\n        ['task', 'minutes', 'time', 'mode', 'note'].forEach(k => {\n          if (rec[k] != null && String(rec[k]) !== '') same[k] = rec[k];\n        });\n        if (same.id) DB.update(T.INVITE, same.id, JSON.parse(JSON.stringify(same)));\n      }\n      return same;\n    }\n  }\n  // 同一角色 + 同一类型，10 分钟内只留最新一条未处理的\n  (S.invites || []).forEach(x => {\n    if (x.status === 'new' && x.kind === rec.kind && String(x.charId) === String(rec.charId)\n      && (rec.at - (x.at || 0)) < 10 * 60000) {\n      x.status = 'replaced';\n      if (x.id) DB.update(T.INVITE, x.id, JSON.parse(JSON.stringify(x)));\n    }\n  });\n  rec.status = rec.status || 'new';\n  const r = await DB.create(T.INVITE, rec);\n  if (r) rec.id = r.id;\n  S.invites = [rec].concat((S.invites || []).filter(x => String(x.id) !== String(rec.id)));\n  const nm = rec.charId ? charName(rec.charId) : 'TA';\n  const title = rec.kind === 'sleep' ? ('🌙 ' + nm + ' 邀你一起睡') : ('📨 ' + nm + ' 约你专注');\n  const body = rec.kind === 'sleep'\n    ? ((rec.mode || '午睡') + (rec.minutes ? ' · ' + rec.minutes + ' 分钟' : '') + (rec.note ? '：' + rec.note : ''))\n    : ((rec.task || '') + (rec.minutes ? ' · ' + rec.minutes + ' 分钟' : '') + (rec.time ? ' · ' + rec.time : ''));\n  await sdk(() => API.notifications.create({ title: title, body: body }));\n  if (S.ready && !S.lock) render();\n  return rec;\n}\n/* ---------- 回扫聊天历史：把「角色写过卡片、但记录表里没有」的邀请补录进来 ----------\n   为什么需要它：角色写卡是靠宿主后台监听（chat.message.created + background:true）写记录的。\n   监听没跑起来的那段时间，卡片就只是聊天室里的一张卡，记录表里空空如也 ——\n   这就是「翻遍历史都没有」的原因。这里在打开 APP 时回扫一遍最近聊天，\n   把漏掉的卡片补成记录（标为「补录」，不装成你当时答应过），\n   补录后同样会去对那次睡眠 / 那段专注，能不能看到完成情况取决于记录还在不在。 */\nfunction inviteSigOf(kind, charId, at) {\n  return String(kind) + '|' + String(charId || '') + '|' + Math.floor(Number(at || 0) / 60000);\n}\n/* 时间旁边给一句人话提示，避免「21:00」到底是今天还是明天要自己去猜 ——\n   过了那个点就按明天算，和真正排预约时的规则一致。 */\nfunction invTimeHint(t) {\n  const m = String(t || '').match(/(\\d{1,2})[:：](\\d{2})/);\n  if (!m) return '';\n  const d = new Date();\n  d.setHours(clamp(Number(m[1]) || 0, 0, 23), clamp(Number(m[2]) || 0, 0, 59), 0, 0);\n  if (d.getTime() <= Date.now()) return '（已过，算明天）';\n  return '（今天）';\n}\nasync function saveInviteOnly(rec) {\n  if (!rec || !rec.kind) return null;\n  const r = await DB.create(T.INVITE, rec);\n  if (r) rec.id = r.id;\n  S.invites = [rec].concat((S.invites || []).filter(x => String(x.id) !== String(rec.id)));\n  return rec;\n}\n/* 回扫的消息来源：把「当前会话」和「按角色读到的历史」两条路都收进来。\n   为什么必须两条路 —— 从桌面直接打开 APP 时拿不到当前会话；\n   而只按 characterId 读，有些环境一条也读不回来，回扫就等于白扫。\n   实测哪种可用由「邀请功能诊断」显示。 */\nasync function inviteScanSources(chars) {\n  const out = [];\n  const push = (cid, h) => {\n    const l = Array.isArray(h) ? h : ((h && h.messages) || []);\n    if (l.length) out.push({ cid: cid || '', list: l });\n  };\n  const cur = await sdk(() => API.chat.getCurrentSession(), null);\n  if (cur && cur.sessionId) {\n    push(cur.characterId || '', await sdk(() => API.chat.readHistory({ sessionId: cur.sessionId, limit: 80 }), null));\n  }\n  for (const c of (chars || [])) {\n    if (out.length >= 4) break;\n    push(c.id, await sdk(() => API.chat.readHistory({ characterId: c.id, limit: 60 }), null));\n  }\n  return out;\n}\n/* 统一的邀请卡识别：把「角色写的那段文本」理解成邀请参数。\n   为什么要换掉原来那两条死正则 —— 角色写卡的实际格式很活：\n   英文方括号 [ ]、中文方括号【】都可能用；分隔符可能是冒号、逗号、顿号、竖线、空格。\n   只要括号里以「陪睡」或「约专注」开头，就按分隔符拆开理解，尽量不放过。\n   时间里的冒号（21:00）先保护起来，否则会被当分隔符切碎。 */\nfunction parseInviteDirectives(text) {\n  const out = [];\n  const t = String(text || '');\n  if (!t || (t.indexOf('陪睡') < 0 && t.indexOf('约专注') < 0)) return out;\n  const re = /[\\[【]\\s*(陪睡|约专注)\\s*([^\\]】\\n]{0,150})[\\]】]/g;\n  let mm;\n  while ((mm = re.exec(t)) !== null) {\n    const kind = (mm[1] === '陪睡') ? 'sleep' : 'focus';\n    const body = String(mm[2] || '')\n      /* 先把时间里的冒号保护起来，否则会被当分隔符切碎。\n         一位分钟也算时间（9:5），所以用 \\d{1,2} 而不是 \\d{2}。 */\n      .replace(/(\\d{1,2})[:：](\\d{1,2})(?!\\d)/g, '$1@$2')\n      .replace(/^[\\s:：,，、|/／\\-—]+/, '');\n    const parts = body.split(/[\\s:：,，、|/／\\-—]+/)\n      .map(x => x.trim().split('@').join(':'))       // 全部还原（不只第一个）\n      .filter(x => x !== '');\n    if (!parts.length) {\n      /* [陪睡] 只写了两个字也要认 —— 没参数的睡眠邀请，按默认午睡 30 分钟。 */\n      if (kind === 'sleep') out.push({ kind: 'sleep', mode: '午睡', minutes: 30, note: '' });\n      continue;\n    }\n    if (kind === 'sleep') {\n      /* 睡觉卡的写法很活，逐个字段认，不靠位置硬套：\n         [陪睡:午睡:30:早点睡] / [陪睡:30] / [陪睡:早点睡] / [陪睡:小憩] 都要认对。\n         以前第一个字段若是纯数字（分钟数），会被当成「模式」，分钟数就丢了。 */\n      let mode = '午睡', minutes = 0;\n      const noteBits = [];\n      parts.forEach((p, i) => {\n        if (i === 0 && ['小憩', '午睡', '长睡眠'].indexOf(p) >= 0) { mode = p; return; }\n        if (/^\\d{1,4}$/.test(p) && !minutes) { minutes = clamp(Number(p), 0, 1440); return; }\n        noteBits.push(p);\n      });\n      out.push({ kind: 'sleep', mode: mode, minutes: minutes || 30, note: noteBits.join(' ').slice(0, 120) });\n    } else {\n      /* 时间：认 9:5 / 09:05 / 21：00 这些写法，并统一规范成 HH:MM */\n      let timePart = parts.find(p => /^\\d{1,2}[:：]\\d{1,2}$/.test(p)) || '';\n      if (timePart) {\n        const tp = timePart.split(/[:：]/);\n        timePart = pad2(clamp(Number(tp[0]) || 0, 0, 23)) + ':' + pad2(clamp(Number(tp[1]) || 0, 0, 59));\n      }\n      let minPart = '';\n      for (let i = parts.length - 1; i >= 0; i--) { if (/^\\d{1,4}$/.test(parts[i])) { minPart = parts[i]; break; } }\n      const task = parts.filter(p => p !== timePart && p !== timePart.replace(':', '：') && p !== minPart).join(' ').slice(0, 60);\n      out.push({\n        kind: 'focus',\n        time: timePart,\n        task: task || '一起专注一会儿',\n        minutes: clamp(Number(minPart) || Number(cfg('focusMin') || 25), 1, 600)\n      });\n    }\n  }\n  return out;\n}\nlet inviteBackfilled = false;\nasync function backfillInvites(force) {\n  if (inviteBackfilled && !force) return 0;\n  if (!API || !API.chat || !API.chat.readHistory) return 0;\n  if (!S.ready) return 0;\n  inviteBackfilled = true;\n  const chars = (S.chars || []).slice(0, 8);\n  if (!chars.length) return 0;\n  const seenMsg = {}, seenSig = {};\n  (S.invites || []).forEach(x => {\n    if (x.cardMessageId) seenMsg[String(x.cardMessageId)] = 1;\n    seenSig[inviteSigOf(x.kind, x.charId, x.at)] = 1;\n  });\n  let added = 0;\n  const srcs = await inviteScanSources(chars);\n  for (const src of srcs) {\n    if (added >= 40) break;\n    const c = { id: src.cid };\n    for (const m of src.list) {\n      if (added >= 40) break;\n      if (!m || m.role !== 'assistant') continue;\n      const text = String(m.content || m.text || '');\n      if (!text || (text.indexOf('陪睡') < 0 && text.indexOf('约专注') < 0)) continue;\n      const at = Number(m.at || m.createdAt || Date.now());\n      const mid = String(m.id || m.messageId || '');\n      if (mid && seenMsg[mid]) continue;\n      /* 卡片格式交给 parseInviteDirectives 统一识别 ——\n         原来那条死正则只认「英文方括号 + 冒号」，中文方括号、逗号分隔全会漏。 */\n      const difs = parseInviteDirectives(text);\n      for (const d of difs) {\n        const sig = inviteSigOf(d.kind, c.id, at);\n        if (seenSig[sig]) continue;\n        seenSig[sig] = 1; if (mid) seenMsg[mid] = 1;\n        await saveInviteOnly(Object.assign({}, d, {\n          charId: c.id, at: at, status: 'stale', from: 'backfill',\n          cardMessageId: mid, backfillAt: Date.now()\n        }));\n        added++;\n      }\n    }\n  }\n  if (added) { toast('补录了 ' + added + ' 张以前发过、没记下来的邀请卡'); render(); }\n  return added;\n}\n/* ---------- 一条邀请「后来怎么样了」 ----------\n   TA 发来的邀请一条都不会自己消失（存在本机，也会进备份）。\n   这里把每条邀请关联回它真正触发的东西：睡眠邀请 → 那天那次睡眠记录；\n   专注邀请 → 那段专注（预订过的就看那条预约的最终状态）。\n   于是历史列表里能直接看到完成情况，而不是只剩一个「已答应 / 先不了」。 */\nfunction inviteOutcome(inv) {\n  if (!inv) return null;\n  if (inv.status === 'new') return { text: '等你回应', tone: 'warn' };\n  if (inv.status === 'dismissed') return { text: '你说了「先不了」', tone: '' };\n  if (inv.status === 'replaced') return { text: '被后一条邀请替代，没等到回应', tone: '' };\n  /* 补录的旧卡片：当时没在这边回应过，但仍然去对那次睡眠 / 那段专注 ——\n     对上了就把结果照实写出来，对不上就直说没有对应记录。 */\n  const stale = (inv.status === 'stale');\n  const at = Number(inv.acceptedAt || inv.at || 0);\n  const gap = 8 * 60000;                 // 答应之后基本都是当场开始，前后 8 分钟足够对上\n  const near = t => t && Math.abs(Number(t) - at) < gap;\n  if (inv.kind === 'sleep') {\n    const live = S.sleep;\n    if (live && live.running && near(live.startAt)) {\n      return { text: '正在睡 · 已记录 ' + fmtDur(sleepElapsedSec()) + (live.mode ? '（' + live.mode + '）' : ''), tone: 'run' };\n    }\n    const rec = (S.sleeps || []).filter(x => near(x.startAt))\n      .sort((a, b) => Math.abs(a.startAt - at) - Math.abs(b.startAt - at))[0];\n    if (rec) {\n      const real = (rec.sleepSec != null ? rec.sleepSec : rec.seconds);\n      return {\n        text: '完成 · ' + (rec.mode || '睡眠') + ' ' + fmtDur(rec.seconds) + '（实际入睡 ' + fmtDur(real) + '）'\n          + ((rec.breaks || []).length ? ' · 中途醒来 ' + rec.breaks.length + ' 次' : ''),\n        tone: 'ok', act: 'sleepRec', id: rec.id\n      };\n    }\n    return stale\n      ? { text: '补录的旧卡片 · 那段时间没有睡眠记录', tone: '' }\n      : { text: '没找到对应的睡眠记录（当时可能只回了邀请、没开计时）', tone: '' };\n  }\n  /* 专注邀请：预订过的，看那条预约最后是什么结局 */\n  if (inv.apptId) {\n    const a = (S.appts || []).find(x => String(x.id) === String(inv.apptId));\n    if (a) {\n      const map = {\n        pending: '等到了约定时间 · ' + apptTimeText(a),\n        started: '已按时开始，专注进行中',\n        done: '按时完成了这次专注',\n        missed: '没去 · 催了 ' + (a.nudgeCount || 0) + ' 次，已开罚',\n        skipped: '到点你正在另一段专注里，这次放过',\n        canceled: '这条预约被取消了'\n      };\n      const tone = a.status === 'done' ? 'ok' : (a.status === 'missed' ? 'bad' : ((a.status === 'pending' || a.status === 'started') ? 'run' : ''));\n      return { text: map[a.status] || '已排进预约', tone: tone, act: 'gotoView' };\n    }\n    return { text: '已排进预约（那条预约已经不在了）', tone: '' };\n  }\n  const s = (S.sessions || []).filter(x => near(x.startAt))\n    .sort((a, b) => Math.abs(a.startAt - at) - Math.abs(b.startAt - at))[0];\n  if (s) {\n    const m = Math.round((s.totalFocusSec || 0) / 60);\n    if (s.status === 'running') return { text: '专注进行中 · 已 ' + m + ' 分钟', tone: 'run' };\n    if (s.status === 'review') return { text: '专注结束 ' + m + ' 分钟 · 还没走校验', tone: 'warn' };\n    if (s.status === 'passed') return { text: '考核通过 · 专注 ' + m + ' 分钟' + (s.quizTotal ? '（答对 ' + (s.quizScore || 0) + '/' + s.quizTotal + '）' : ''), tone: 'ok' };\n    if (s.status === 'failed') return { text: '考核没过 · 专注 ' + m + ' 分钟', tone: 'bad' };\n    return { text: '专注记录：' + m + ' 分钟', tone: '' };\n  }\n  return stale\n    ? { text: '补录的旧卡片 · 那段时间没有专注记录', tone: '' }\n    : { text: '没找到对应的专注记录（当时可能只回了邀请、没开计时）', tone: '' };\n}\nfunction invitesHTML() {\n  const list = (S.invites || []).filter(i => i.status === 'new');\n  if (!list.length) return '';\n  return list.slice(0, 2).map(inv => {\n    const c = charById(inv.charId);\n    const isSleep = inv.kind === 'sleep';\n    return `<div class=\"card\" style=\"border-color:${isSleep ? 'rgba(165,139,255,.5)' : 'rgba(124,140,255,.5)'};background:linear-gradient(160deg,${isSleep ? 'rgba(165,139,255,.16)' : 'rgba(124,140,255,.14)'},rgba(255,255,255,.03))\">\n    <div class=\"row between\"><span class=\"tiny\">${isSleep ? '🌙 他邀你一起睡' : '📨 他约你专注'} · ${inv.at ? hm(inv.at) : ''}</span>\n      <span class=\"pill warn\">TA 在等你</span></div>\n    <div class=\"row mt6\">${charAvatar(c)}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">\n      <div class=\"who\">${esc(charName(inv.charId))}</div>${esc(inv.note || (isSleep ? '一起去睡会儿吧。' : '陪我学一会儿吧。'))}</div></div>\n    <div class=\"kv mt6\"><span class=\"k\">${isSleep ? '一起' : '做什么'}</span><span>${esc(isSleep ? ((inv.mode || '午睡') + (inv.minutes ? ' · ' + inv.minutes + ' 分钟' : '')) : (inv.task || ''))}</span></div>\n    ${!isSleep && inv.time ? `<div class=\"kv\"><span class=\"k\">时间</span><span>${esc(inv.time)}${invTimeHint(inv.time)}</span></div>` : ''}\n    <div class=\"row mt10\" style=\"gap:8px\">\n      <button class=\"btn primary grow\" data-act=\"inviteAccept\" data-id=\"${esc(inv.id)}\" data-mode=\"${(!isSleep && (inv.time || inv.apptId)) ? 'book' : 'now'}\">${isSleep ? '🌙 躺下，开始记录' : ((inv.time || inv.apptId) ? '✅ 答应他，到点来催' : '▶️ 答应他，现在开始')}</button>\n      <button class=\"btn ghost\" data-act=\"inviteDismiss\" data-id=\"${esc(inv.id)}\">先不了</button></div>\n    ${!isSleep ? `<div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn ghost sm grow\" data-act=\"inviteReschedule\" data-id=\"${esc(inv.id)}\">🕐 改个时间</button>\n      ${(inv.time || inv.apptId) ? `<button class=\"btn ghost sm grow\" data-act=\"inviteAccept\" data-id=\"${esc(inv.id)}\" data-mode=\"now\">⚡ 现在就提前开始</button>` : ''}\n    </div>` : ''}\n  </div>`;\n  }).join('');\n}\nVIEWS.invites = function () {\n  const all = (S.invites || []).slice().sort((a, b) => (b.at || 0) - (a.at || 0));\n  const news = all.filter(i => i.status === 'new');\n  const past = all.filter(i => i.status !== 'new' && i.status !== 'replaced');\n  const gone = all.filter(i => i.status === 'replaced');\n  const label = { accepted: '已答应并开始', dismissed: '先不了', replaced: '已被新的邀请替代', stale: '补录的旧卡片 · 当时没在这里回应' };\n  return `\n  <div class=\"card\" style=\"background:linear-gradient(160deg,rgba(124,140,255,.16),rgba(255,255,255,.03));border-color:rgba(124,140,255,.3)\">\n    <h3>💌 TA 的邀请</h3>\n    <div class=\"tiny mt6\" style=\"line-height:1.8\">角色可以主动约你：<br>\n    · 直接写卡 <b>[陪睡:午睡:30:早点睡]</b> / <b>[约专注:21:00:背单词:25]</b>；<br>\n    · 或在聊天里调用工具「邀我一起睡」「跟我约一段专注」。<br>\n    他发出的邀请会进这里，同时给你发一条通知 —— <b>APP 没打开也能收到</b>（宿主会临时拉起本 APP 的脚本执行）。<br>\n    <b>每一条邀请都留着</b>：下面的历史里会写清它后来怎么样了 —— 那晚一起睡了多久、那段专注过没过考核、预订的那条有没有按时去。</div>\n    <div class=\"row mt8\" style=\"gap:8px\">\n      <button class=\"btn ghost sm grow\" data-act=\"inviteBackfill\">🔄 回扫聊天记录</button>\n      <button class=\"btn ghost sm grow\" data-act=\"inviteDiag\">🔍 诊断</button>\n    </div>\n  </div>\n  ${S.draft.cardInvite ? (function () {\n    /* 从 TA 的卡片点进来、但邀请记录里没有那一条时（宿主当时没把监听拉起来，\n       或卡片是更早发来的）—— 按卡片上写的参数在这里兜底出一条，\n       让你当场就能接受，而不是被丢到一个「自己发邀请」的表单上。 */\n    const ci = S.draft.cardInvite;\n    const isSleep = ci.kind === 'sleep';\n    const cid = inviteCharId() || anyCharId();\n    return `<div class=\"card\" style=\"border-color:rgba(255,201,120,.55);background:linear-gradient(160deg,rgba(255,201,120,.15),rgba(255,255,255,.03))\">\n      <div class=\"row between\"><span class=\"tiny\">${isSleep ? '🌙 邀你一起睡' : '📨 约你专注'} · 从卡片点进来的</span>\n        <span class=\"pill warn\">等你点头</span></div>\n      <div class=\"row mt6\">${charAvatar(charById(cid))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">\n        <div class=\"who\">${esc(charName(cid))}</div>${isSleep ? '一起去睡会儿吧。' : '陪我学一会儿吧。'}</div></div>\n      <div class=\"kv mt6\"><span class=\"k\">${isSleep ? '一起' : '做什么'}</span><span>${esc(isSleep ? (ci.mode || '午睡') : (ci.task || '一起专注一会儿'))}</span></div>\n      <div class=\"kv\"><span class=\"k\">多久</span><span>${Number(ci.minutes) || (isSleep ? 30 : Number(cfg('focusMin') || 25))} 分钟</span></div>\n      ${ci.time ? `<div class=\"kv\"><span class=\"k\">时间</span><span>${esc(ci.time)}${invTimeHint(ci.time)}</span></div>` : ''}\n      <div class=\"tiny mt6\">这条是卡片带过来的。点了「答应他」会先记成一条邀请（历史里能回看），再开始；和他写的时间一致的会按「到点来催」处理。</div>\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"inviteAcceptCard\" data-mode=\"${(!isSleep && ci.time) ? 'book' : 'now'}\">${isSleep ? '🌙 躺下，开始记录' : (ci.time ? '✅ 答应他，到点来催' : '▶️ 答应他，现在开始')}</button>\n        <button class=\"btn ghost\" data-act=\"inviteDismissCard\">先不了</button></div>\n      ${!isSleep ? `<div class=\"row mt8\" style=\"gap:8px\">\n        <button class=\"btn ghost sm grow\" data-act=\"inviteAcceptCard\" data-mode=\"now\">⚡ 现在就提前开始</button>\n      </div>` : ''}\n    </div>`;\n  })() : ''}\n  ${news.length ? news.map(inv => {\n    const isSleep = inv.kind === 'sleep';\n    return `<div class=\"card\" style=\"border-color:${isSleep ? 'rgba(165,139,255,.45)' : 'rgba(124,140,255,.45)'}\">\n      <div class=\"row between\"><span class=\"tiny\">${isSleep ? '🌙 邀你一起睡' : '📨 约你专注'} · ${dkey(new Date(inv.at))} ${hm(inv.at)}</span>\n        <span class=\"pill warn\">待回应</span></div>\n      <div class=\"row mt6\">${charAvatar(charById(inv.charId))}<div class=\"bd\" style=\"background:transparent;padding:0;font-size:13.5px\">\n        <div class=\"who\">${esc(charName(inv.charId))}</div>${esc(inv.note || (isSleep ? '一起去睡会儿吧。' : '陪我学一会儿吧。'))}</div></div>\n      <div class=\"kv mt6\"><span class=\"k\">${isSleep ? '一起' : '做什么'}</span><span>${esc(isSleep ? ((inv.mode || '午睡') + (inv.minutes ? ' · ' + inv.minutes + ' 分钟' : '')) : (inv.task || ''))}</span></div>\n      ${!isSleep && inv.minutes ? `<div class=\"kv\"><span class=\"k\">多久</span><span>${inv.minutes} 分钟</span></div>` : ''}\n      ${!isSleep && inv.time ? `<div class=\"kv\"><span class=\"k\">时间</span><span>${esc(inv.time)}${invTimeHint(inv.time)}${inv.apptId ? ' · 已排进预约专注' : ''}</span></div>` : ''}\n      <div class=\"row mt10\" style=\"gap:8px\">\n        <button class=\"btn primary grow\" data-act=\"inviteAccept\" data-id=\"${esc(inv.id)}\" data-mode=\"${(!isSleep && (inv.time || inv.apptId)) ? 'book' : 'now'}\">${isSleep ? '🌙 躺下，开始记录' : ((inv.time || inv.apptId) ? '✅ 答应他，到点来催' : '▶️ 答应他，现在开始')}</button>\n        <button class=\"btn ghost\" data-act=\"inviteDismiss\" data-id=\"${esc(inv.id)}\">先不了</button></div>\n      ${!isSleep ? `<div class=\"row mt8\" style=\"gap:8px\">\n        <button class=\"btn ghost sm grow\" data-act=\"inviteReschedule\" data-id=\"${esc(inv.id)}\">🕐 改个时间</button>\n        ${(inv.time || inv.apptId) ? `<button class=\"btn ghost sm grow\" data-act=\"inviteAccept\" data-id=\"${esc(inv.id)}\" data-mode=\"now\">⚡ 现在就提前开始</button>` : ''}\n      </div>` : ''}\n      ${!isSleep && inv.apptId ? `<button class=\"btn block ghost sm mt8\" data-act=\"gotoView\" data-view=\"appt\">看他给你排的预约 ›</button>` : ''}\n    </div>`;\n  }).join('') : `<div class=\"empty\">现在没有待回应的邀请。<br>TA 主动约你时，这里会出现一张卡，你也能收到通知。</div>`}\n  ${past.length ? `<div class=\"card\"><div class=\"row between\"><h3>之前的邀请（${past.length}）</h3>\n    <span class=\"tiny\">都留着 · 下面写着后来怎么样了</span></div>\n    ${past.map(inv => {\n      const isSleep = inv.kind === 'sleep';\n      const oc = inviteOutcome(inv);\n      const head = isSleep\n        ? ('陪你一起睡' + (inv.mode ? '（' + esc(inv.mode) + (Number(inv.minutes) ? ' · ' + inv.minutes + ' 分钟' : '') + '）' : ''))\n        : ('约你专注：' + esc(inv.task || '') + (Number(inv.minutes) ? '（' + inv.minutes + ' 分钟）' : ''));\n      const icon = inv.status === 'accepted' ? ((oc && oc.tone === 'ok') ? '✅' : ((oc && oc.tone === 'bad') ? '⚠️' : '📌')) : (inv.status === 'stale' ? '🕐' : '➖');\n      return `<div class=\"item\"><div class=\"ic\">${icon}</div>\n      <div class=\"grow\">\n        <div style=\"font-size:13px\">${head}</div>\n        <div class=\"tiny\">${dkey(new Date(inv.at))} ${hm(inv.at)} · ${esc(label[inv.status] || inv.status)}${inv.acceptedAt ? ' · 回应于 ' + hm(inv.acceptedAt) : ''}${inv.from === 'directive' ? ' · 写卡约的' : inv.from === 'tool' ? ' · 工具约的' : ''}</div>\n        ${oc ? `<div class=\"mt6\"><span class=\"pill ${oc.tone || ''}\">${esc(oc.text)}</span></div>` : ''}\n      </div>\n      ${(oc && oc.act === 'sleepRec') ? `<button class=\"btn sm ghost\" data-act=\"sleepRec\" data-id=\"${esc(oc.id)}\">看报告</button>` : ''}\n      ${(oc && oc.act === 'gotoView') ? `<button class=\"btn sm ghost\" data-act=\"gotoView\" data-view=\"appt\">看预约</button>` : ''}\n      <button class=\"btn sm ghost\" data-act=\"inviteDel\" data-id=\"${esc(inv.id)}\">删</button></div>`;\n    }).join('')}</div>` : ''}\n  ${gone.length ? `<div class=\"card\"><div class=\"row between\"><h3>被新邀请替代的（${gone.length}）</h3>\n    <button class=\"btn sm ghost\" data-act=\"invitesClearGone\">清掉</button></div>\n    <div class=\"tiny mt6\">同一角色、同一类型的邀请 10 分钟内只留最新那条，被顶替的留在这里（不算你回应过）。</div>\n    ${gone.map(inv => `<div class=\"item\"><div class=\"ic\">🕐</div>\n      <div class=\"grow\"><div class=\"tiny\">${dkey(new Date(inv.at))} ${hm(inv.at)} · ${inv.kind === 'sleep' ? '邀你一起睡' : '约你专注'}${Number(inv.minutes) ? ' · ' + inv.minutes + ' 分钟' : ''}</div></div>\n      <button class=\"btn sm ghost\" data-act=\"inviteDel\" data-id=\"${esc(inv.id)}\">删</button></div>`).join('')}</div>` : ''}`;\n};\nObject.assign(ACTIONS, {\n  inviteAccept: async el => {\n    const inv = (S.invites || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!inv) return;\n    /* 已经处理过的邀请不再响应第二次 —— 这是「答应了还能答应第二次、第三次」\n       的最后一道闸。列表里处理过的邀请本来就不再显示按钮，\n       但兜底卡 / 历史记录 / 重复点按都可能再调进来，所以这里硬拦。 */\n    if (inv.status && inv.status !== 'new' && inv.status !== 'stale') {\n      const map = {\n        accepted: inv.acceptedAt ? ('你已经在 ' + hm(inv.acceptedAt) + ' 答应过这条了') : '你已经答应过这条了',\n        dismissed: '这条你已经说过「先不了」',\n        replaced: '这条已经被新的邀请替代了',\n        canceled: '这条已经取消了'\n      };\n      toast(map[inv.status] || '这条邀请已经处理过了');\n      render();\n      return;\n    }\n    /* 正在跑这条邀请对应的专注 / 睡眠时，也别重复开一段 */\n    if (S.session && S.session.status === 'running') { toast('你现在已经在专注里了'); go('running'); return; }\n    if (S.sleep && S.sleep.running) { toast('已经在记录睡眠了'); go('sleep'); return; }\n    if (pendingPunish().length) { toast('先把没完成的惩罚做完'); S.lock = { punish: pendingPunish()[0] }; render(); return; }\n    if (S.session && S.session.status === 'running') { toast('你现在已经在专注里了'); go('running'); return; }\n    if (inv.kind === 'sleep') {\n      if (S.sleep && S.sleep.running) { toast('已经在记录睡眠了'); go('sleep'); return; }\n      inv.status = 'accepted'; inv.acceptedAt = Date.now();\n      if (inv.id) await DB.update(T.INVITE, inv.id, JSON.parse(JSON.stringify(inv)));\n      S.settings.sleepCharIds = inv.charId ? [inv.charId] : (cfg('sleepCharIds') || []);\n      await saveSettings(true);\n      const ok = await startSleep(inv.mode || '午睡', Number(inv.minutes) || 30);\n      if (ok !== false) {\n        const st = S.sleep;\n        if (st) {\n          const line = inv.note || '来，躺下吧，我在。';\n          st.inviteLine = line; st.inviteChar = inv.charId || '';\n          st.chat = (st.chat || []).concat([{ role: 'char', charId: inv.charId || '', text: line, at: Date.now(), kind: 'invite' }]);\n          if (st.chat.length > 60) st.chat = st.chat.slice(-60);\n          await saveSleepSession();\n          if (inv.charId && shouldSpeak('invite')) speak(inv.charId, line);\n          if (S.view === 'sleep') render();\n        }\n        toast('已开始：' + charName(inv.charId) + '陪你' + (inv.mode || '午睡'));\n      }\n      render();\n      return;\n    }\n    /* 带时间的邀请（TA 写的是「几点一起专注」）：\n       默认走「答应下来、到点由 TA 来催」，不占掉你现在的状态；\n       想立刻就练，点的是「⚡ 现在就提前开始」（mode=now）。 */\n    const acceptMode = (el && el.dataset && el.dataset.mode) || '';\n    if (acceptMode === 'book') {\n      inv.status = 'accepted'; inv.acceptedAt = Date.now();\n      let aRec = inv.apptId ? (S.appts || []).find(x => String(x.id) === String(inv.apptId)) : null;\n      if (!aRec) {\n        const tm = String(inv.time || '').match(/(\\d{1,2})[:：](\\d{2})/);\n        const dt = new Date();\n        if (tm) {\n          dt.setHours(clamp(Number(tm[1]), 0, 23), clamp(Number(tm[2]), 0, 59), 0, 0);\n          if (dt.getTime() <= Date.now()) dt.setDate(dt.getDate() + 1);\n        } else dt.setTime(Date.now() + 30 * 60000);\n        const rec0 = {\n          id: '', date: dkey(dt), time: pad2(dt.getHours()) + ':' + pad2(dt.getMinutes()), startAt: dt.getTime(),\n          minutes: clamp(Number(inv.minutes) || Number(cfg('focusMin') || 25), 1, 600),\n          task: String(inv.task || '一起专注一会儿').slice(0, 60),\n          charIds: [inv.charId].filter(Boolean), status: 'pending', nudgeCount: 0,\n          createdAt: Date.now(), note: '由角色在聊天里约的'\n        };\n        await createAppt(rec0);\n        await scheduleAppt(rec0);\n        inv.apptId = rec0.id;\n        aRec = rec0;\n      }\n      if (inv.id) await DB.update(T.INVITE, inv.id, JSON.parse(JSON.stringify(inv)));\n      toast('答应了：' + apptTimeText(aRec) + ' · TA 到点来催你');\n      go('appt');\n      return;\n    }\n    // 约专注：现在就开始\n    inv.status = 'accepted'; inv.acceptedAt = Date.now();\n    if (inv.id) await DB.update(T.INVITE, inv.id, JSON.parse(JSON.stringify(inv)));\n    const ids = [inv.charId || anyCharId()].filter(Boolean);\n    if (!ids.length) { toast('还没有角色'); return; }\n    const mins = clamp(Number(inv.minutes) || Number(cfg('focusMin') || 25), 1, 600);\n    const task = inv.task || '和他一起安静地待一会儿';\n    const line = inv.note || '';\n    const apptRec = inv.apptId ? (S.appts || []).find(x => String(x.id) === String(inv.apptId)) : null;\n    const opt = sessionOptsFromAppt(apptRec, task, mins);\n    await startSession({\n      charIds: ids, focusMin: opt.focusMin, breakMin: opt.breakMin, cycles: opt.cycles,\n      plan: opt.plan, reviewEvery: opt.reviewEvery, voiceOn: cfg('voiceMode') !== 'off'\n    });\n    const s = S.session;\n    if (s) {\n      pushMsg(s, 'sys', '你答应了 ' + charName(inv.charId) + ' 的约：' + task);\n      if (line) pushMsg(s, 'char', line, { charId: inv.charId, kind: 'invite' });\n      await saveSession(true); render();\n    }\n  },\n  inviteDismiss: async el => {\n    const inv = (S.invites || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!inv) return;\n    inv.status = 'dismissed'; inv.dismissedAt = Date.now();\n    if (inv.id) await DB.update(T.INVITE, inv.id, JSON.parse(JSON.stringify(inv)));\n    toast('先不了，TA 还等着你下次点头');\n    render();\n  },\n  inviteDel: async el => {\n    await DB.remove(T.INVITE, el.dataset.id);\n    S.invites = (S.invites || []).filter(x => String(x.id) !== String(el.dataset.id));\n    render();\n  },\n  /* 卡片带过来、当场接受：先落一条真实的邀请记录（这样历史里也会留下它），\n     再走和普通邀请完全一样的接受流程 —— 真的会开始专注 / 睡眠。 */\n  /* 兜底卡上的「答应他」：先确保有一条真记录，再走和普通邀请完全一样的接受流程。\n     注意带上正确的 mode —— 卡片里写了时间的，答应该按「到点来催」处理，\n     不能一律当成「现在就开始」（以前就是这么丢掉了时间）。 */\n  inviteAcceptCard: async el => {\n    const ci = S.draft.cardInvite;\n    if (!ci) { toast('没有待处理的卡片邀请'); return; }\n    const rec = await ensureCardInvite();\n    if (!rec || !rec.id) {\n      /* 极少数情况连记录都落不下来（比如还没有角色）：如实说，不装作开始了 */\n      const cid = inviteCharId() || anyCharId();\n      if (!cid) { toast('还没有角色'); return; }\n      S.draft.cardInvite = null;\n      toast('这条卡片没能记下来，请重新打开 APP 再试一次');\n      render();\n      return;\n    }\n    const mode = (el && el.dataset && el.dataset.mode)\n      || ((ci.kind !== 'sleep' && (ci.time || rec.time)) ? 'book' : 'now');\n    await ACTIONS.inviteAccept({ dataset: { id: String(rec.id), mode: mode } });\n  },\n  inviteDismissCard: () => {\n    S.draft.cardInvite = null;\n    toast('先不了，TA 还等着你下次点头');\n    render();\n  },\n  /* 给 TA 的专注邀请改时间：带着卡上的事项 / 时长 / 角色打开预约表单，\n     改完保存 —— 这条邀请记为已答应，并按你定的新时间排催促。\n     如果 TA 本来就排过预约，这次改的是那一条（不重复建）。 */\n  inviteReschedule: el => {\n    const inv = (S.invites || []).find(x => String(x.id) === String(el.dataset.id));\n    if (!inv) { toast('找不到这条邀请'); return; }\n    const mins = clamp(Number(inv.minutes) || Number(cfg('focusMin') || 25), 1, 600);\n    S.draft.apptTask = inv.task || '';\n    S.draft.apptMinutes = mins;\n    S.draft.apptSegs = [{ content: inv.task || '', min: mins }];\n    S.draft.apptBreakMin = Number(cfg('breakMin') || 5);\n    S.draft.apptReview = 'focus';\n    S.draft.apptCharIds = [inv.charId].filter(Boolean);\n    const tm = String(inv.time || '').match(/(\\d{1,2})[:：](\\d{2})/);\n    const dt = new Date();\n    if (tm) {\n      dt.setHours(clamp(Number(tm[1]), 0, 23), clamp(Number(tm[2]), 0, 59), 0, 0);\n      if (dt.getTime() <= Date.now()) dt.setDate(dt.getDate() + 1);\n    } else dt.setTime(Date.now() + 30 * 60000);\n    S.draft.apptDate = dkey(dt);\n    S.draft.apptTime = pad2(dt.getHours()) + ':' + pad2(dt.getMinutes());\n    S.draft.apptEditId = inv.apptId || '';      // 他排过就改那一条，没排就新建\n    S.draft.inviteReschedId = inv.id;\n    ACTIONS.apptNew();\n  },\n  inviteBackfill: async () => {\n    toast('正在翻聊天记录…');\n    let n = 0;\n    try { n = await backfillInvites(true); } catch (e) { n = 0; }\n    if (!n) toast('没扫到邀请卡 —— 点下面的「 🔍 诊断」看看是读不到聊天，还是聊天里本来就没有');\n    render();\n  },\n  /* 诊断：一次性说清「能不能读到聊天」「里面到底有没有 TA 写过的邀请卡」。\n     没有它，我们只能一直猜。 */\n  inviteDiag: async () => {\n    const chars = (S.chars || []).slice(0, 3);\n    const lines = [];\n    lines.push('角色数：' + (S.chars || []).length + ' · 已有邀请记录：' + (S.invites || []).length + ' 条');\n    const cur = await sdk(() => API.chat.getCurrentSession(), null);\n    lines.push('当前会话：' + (cur && cur.sessionId ? ('拿得到 sessionId = ' + String(cur.sessionId).slice(0, 20) + '…') : '拿不到（从桌面直接打开就是这个结果）'));\n    let total = 0, hit = 0, parsed = 0;\n    const samples = [];\n    for (const c of chars) {\n      const h = await sdk(() => API.chat.readHistory({ characterId: c.id, limit: 30 }), null);\n      const l = Array.isArray(h) ? h : ((h && h.messages) || []);\n      const card = l.filter(m => m && m.role === 'assistant' && /陪睡|约专注/.test(String(m.content || m.text || '')));\n      let okN = 0;\n      card.forEach(m => {\n        const ds = parseInviteDirectives(String(m.content || m.text || ''));\n        if (ds.length) okN++;\n        if (samples.length < 4) samples.push((ds.length ? '✅ 能识别' : '⚠️ 认不出') + '：' + String(m.content || m.text || '').slice(0, 90).replace(/\\n/g, ' '));\n      });\n      lines.push('· ' + charName(c.id) + '：读到 ' + l.length + ' 条，含「陪睡/约专注」字样 ' + card.length + ' 条，其中能识别的指令 ' + okN + ' 条');\n      total += l.length; hit += card.length; parsed += okN;\n    }\n    if (samples.length) { lines.push('—— 命中的原文 ——'); samples.forEach(x => lines.push(x)); }\n    if (cur && cur.sessionId) {\n      const h2 = await sdk(() => API.chat.readHistory({ sessionId: cur.sessionId, limit: 30 }), null);\n      const l2 = Array.isArray(h2) ? h2 : ((h2 && h2.messages) || []);\n      lines.push('· 当前会话：读到 ' + l2.length + ' 条');\n      total += l2.length;\n    }\n    lines.push('合计：读到 ' + total + ' 条 · 含字样 ' + hit + ' 条 · 能识别 ' + parsed + ' 条。');\n    const lc2 = await sdk(() => API.app.getLaunchContext(), null);\n    lines.push('本次打开方式：' + (lc2\n      ? [lc2.source, lc2.directiveId, lc2.entry || lc2.actionId].filter(Boolean).join(' · ')\n      : '桌面直接打开（卡片进来时这里会显示 chat_directive）'));\n    openSheet(`<h3>🔍 邀请功能诊断</h3>\n      <div class=\"tiny mt6\" style=\"line-height:1.8\">这一屏直接说清两件事：<b>能不能读到聊天</b>，以及<b>聊天里到底有没有 TA 写过的邀请卡</b>。</div>\n      <div class=\"tiny mt10\" style=\"white-space:pre-wrap;line-height:1.8;background:var(--card2);border-radius:10px;padding:10px;max-height:50vh;overflow:auto\">${esc(lines.join('\\n'))}</div>\n      <div class=\"tiny mt8\" style=\"color:var(--dim2)\">读到 0 条 → 是读取通道的问题，我改读法；读到很多条但没有邀请卡 → TA 从来没写过卡，那「邀请」就一直是你自己发起的那条路。</div>\n      <button class=\"btn primary block mt10\" data-act=\"closeSheet\">关闭</button>`);\n  },\n  invitesClearGone: async () => {\n    const gone = (S.invites || []).filter(i => i.status === 'replaced');\n    for (const x of gone) if (x.id) await DB.remove(T.INVITE, x.id);\n    S.invites = (S.invites || []).filter(i => i.status !== 'replaced');\n    render();\n  }\n});\n/* ---------- 角色工具（APP 没打开时由宿主的隐藏运行环境拉起执行） ---------- */\nasync function ensureBasics() {\n  if (!S.settings) await loadSettings();\n  if (!S.chars || !S.chars.length) { try { await loadChars(); } catch (e) { } }\n}\nfunction statBriefOf(sess, range) {\n  const now = Date.now(), today = midnight();\n  let from = 0, name = '全部';\n  if (range === 'today') { from = today; name = '今天'; }\n  else if (range !== 'all') { const wd = (new Date(today).getDay() + 6) % 7; from = today - wd * 86400000; name = '本周'; }\n  const list = (sess || []).filter(s => s.startAt >= from && s.startAt < now);\n  const min = Math.round(sum(list.map(s => s.totalFocusSec || 0)) / 60);\n  const graded = list.filter(s => s.status === 'passed' || s.status === 'failed');\n  const passed = list.filter(s => s.status === 'passed').length;\n  const vio = sum(list.map(s => (s.violations || []).filter(v => !v.excused).length));\n  const byDay = {};\n  (sess || []).filter(s => s.status === 'passed').forEach(s => { if (s.date) byDay[s.date] = (byDay[s.date] || 0) + Math.round((s.totalFocusSec || 0) / 60); });\n  const slot = [0, 0, 0, 0, 0, 0, 0, 0];\n  list.forEach(s => { slot[Math.floor(new Date(s.startAt).getHours() / 3)] += (s.totalFocusSec || 0) / 60; });\n  const best = slot.some(x => x > 0) ? SLOT_LABEL[slot.indexOf(Math.max.apply(null, slot))] : '（还没有明显的高效时段）';\n  // 连续打卡（按有通过考核的天数）\n  let streak = 0; const d = new Date();\n  if (!byDay[dkey(d)]) d.setDate(d.getDate() - 1);\n  while (byDay[dkey(d)]) { streak++; d.setDate(d.getDate() - 1); }\n  return {\n    range: name, focusMinutes: min, sessions: list.length,\n    avgMinutes: list.length ? Math.round(min / list.length) : 0,\n    passRate: graded.length ? Math.round(passed / graded.length * 100) : 0,\n    violations: vio, bestSlot: best, streakDays: streak,\n    todayMinutes: Math.round(sum((sess || []).filter(s => dkey(new Date(s.startAt)) === dkey()).map(s => s.totalFocusSec || 0)) / 60),\n    coin: coinBal()\n  };\n}\nfunction registerTools() {\n  if (!API || !API.tools || !API.tools.handle) return;\n  /* 1) 查我的专注情况 */\n  API.tools.handle('focusStats', async (args) => {\n    await ensureBasics();\n    const sess = (await DB.list(T.SESSION)).map(r => r.data || r).filter(x => x && x.startAt);\n    const st = statBriefOf(sess, String((args && args.range) || 'week'));\n    return {\n      success: true,\n      data: st,\n      userNotice: `${st.range}专注 ${st.focusMinutes} 分钟 · ${st.sessions} 次 · 通过率 ${st.passRate}%`\n    };\n  });\n  /* 2) 看昨晚睡得怎么样 */\n  API.tools.handle('sleepLast', async (args) => {\n    await ensureBasics();\n    const n = clamp(Number((args && args.count) || 1), 1, 7);\n    const rows = (await DB.list(T.SLEEP)).slice().sort((a, b) => (b.startAt || 0) - (a.startAt || 0)).slice(0, n);\n    if (!rows.length) return { success: true, data: { hasRecord: false }, userNotice: '他还没有睡眠记录' };\n    const fmt = r => {\n      const real = (r.sleepSec != null ? r.sleepSec : r.seconds);\n      const drow = r.drowsySec || 0;\n      const brk = (r.breaks || []).length;\n      return {\n        date: r.date, mode: r.mode || '睡眠',\n        from: hm(r.startAt), to: hm(r.endAt),\n        totalMinutes: Math.round(r.seconds / 60),\n        drowsyMinutes: Math.round(drow / 60),\n        sleepMinutes: Math.round(real / 60),\n        breaks: brk,\n        selfReport: r.asleep ? asleepLabel(r.asleep) : '未填写',\n        quality: (r.report && r.report.quality) ? String(r.report.quality).slice(0, 200) : ''\n      };\n    };\n    const list = rows.map(fmt);\n    return {\n      success: true,\n      data: { hasRecord: true, count: list.length, records: list },\n      userNotice: '最近一次 ' + list[0].mode + '：总 ' + list[0].totalMinutes + ' 分钟（实际入睡 ' + list[0].sleepMinutes + ' 分钟）'\n    };\n  });\n  /* 3) 帮我记一条待办 */\n  API.tools.handle('addTodo', async (args, ctx) => {\n    await ensureBasics();\n    const text = String((args && args.text) || '').trim();\n    if (!text) return { success: false, error: '待办内容为空' };\n    const cid = (ctx && ctx.characterId) || (args && args.characterId) || '';\n    const t = await pushTodo(text, (args && args.note) || '', (args && args.minutes) || 0, cid, 'char');\n    await sdk(() => API.notifications.create({ title: '📝 TA 给你记了一条待办', body: text }));\n    if (cid) await syncTimeline(cid, `${charName(cid)}帮用户记了一条待办：${text}${(args && args.note) ? '（' + args.note + '）' : ''}`, 'todo_add', {});\n    return { success: true, data: { todoId: t ? t.id : '', text: text }, userNotice: '待办已记进专注 APP 首页' };\n  });\n  /* 4) 跟我约一段专注 */\n  API.tools.handle('makeAppt', async (args, ctx) => {\n    await ensureBasics();\n    const timeStr = String((args && args.time) || '').trim();\n    const m = timeStr.match(/^(\\d{1,2})[:：](\\d{2})$/);\n    if (!m) return { success: false, error: '时间格式不对，需要 HH:MM' };\n    const task = String((args && args.task) || '').trim() || '一起专注一会儿';\n    const minutes = clamp(Number((args && args.minutes) || cfg('focusMin') || 25), 1, 600);\n    const cid = (ctx && ctx.characterId) || (args && args.characterId) || anyCharId();\n    const hh = clamp(Number(m[1]), 0, 23), mi = clamp(Number(m[2]), 0, 59);\n    let dateStr = String((args && args.date) || '').trim();\n    let target = null;\n    if (/^\\d{4}-\\d{2}-\\d{2}$/.test(dateStr)) {\n      const dp = dateStr.split('-').map(Number);\n      target = new Date(dp[0], dp[1] - 1, dp[2], hh, mi, 0, 0);\n      if (target.getTime() <= Date.now()) target = null;\n    }\n    if (!target) {\n      const d = new Date(); d.setHours(hh, mi, 0, 0);\n      if (d.getTime() <= Date.now()) d.setDate(d.getDate() + 1);\n      target = d;\n    }\n    const startAt = target.getTime();\n    dateStr = dkey(target);\n    const nowMs = Date.now();\n    if (startAt - nowMs < 60000) {\n      // 太近了：直接当成「现在就约他现在专注」，写成一条邀请\n      const inv = {\n        kind: 'focus', task: task, minutes: minutes, time: timeStr, note: '',\n        charId: cid, apptId: '', at: Date.now(), status: 'new', from: 'tool'\n      };\n      const saved = await pushInvite(inv);\n      if (cid) await syncTimeline(cid, `你约用户现在就一起专注 ${minutes} 分钟：${task}。`, 'appt_invite', {});\n      return { success: true, data: { mode: 'now', inviteId: saved ? saved.id : '' }, userNotice: '已把「现在就一起专注」的邀请发给用户了' };\n    }\n    const rec = {\n      id: '', date: dateStr, time: pad2(hh) + ':' + pad2(mi), startAt: startAt,\n      minutes: minutes, task: task.slice(0, 60), charIds: cid ? [cid] : [],\n      status: 'pending', nudgeCount: 0, createdAt: Date.now(), note: '由角色在聊天里约的'\n    };\n    await createAppt(rec);\n    const n = await scheduleAppt(rec);\n    const inv = {\n      kind: 'focus', task: task, minutes: minutes, time: rec.date + ' ' + rec.time, note: '',\n      charId: cid, apptId: rec.id, at: Date.now(), status: 'new', from: 'tool'\n    };\n    await pushInvite(inv);\n    if (cid) await syncTimeline(cid, `你和用户约好 ${rec.date} ${rec.time} 一起专注 ${minutes} 分钟：${task}。到点前你要来催他开始。`, 'appt_make', {});\n    return {\n      success: true,\n      data: { mode: 'scheduled', date: rec.date, time: rec.time, minutes: minutes, task: task, nudges: n },\n      userNotice: '已排好：' + rec.date + ' ' + rec.time + '（会提前 ' + apptAdvance() + ' 分钟开始催）'\n    };\n  });\n  /* 5) 邀我一起睡 */\n  API.tools.handle('inviteSleep', async (args, ctx) => {\n    await ensureBasics();\n    const mode = ['小憩', '午睡', '长睡眠'].indexOf(String((args && args.mode) || '')) >= 0 ? String(args.mode) : '午睡';\n    const minutes = clamp(Number((args && args.minutes) || 30), 0, 1440);\n    const cid = (ctx && ctx.characterId) || (args && args.characterId) || anyCharId();\n    const rec = await pushInvite({\n      kind: 'sleep', mode: mode, minutes: minutes, note: String((args && args.note) || '').slice(0, 120),\n      charId: cid, at: Date.now(), status: 'new', from: 'tool'\n    });\n    if (cid) await syncTimeline(cid, `你主动邀用户一起${mode}（${minutes || '不定时'} 分钟）：${(args && args.note) || '（没留言）'}`, 'sleep_invite', {});\n    return {\n      success: true,\n      data: { inviteId: rec ? rec.id : '', mode: mode, minutes: minutes },\n      userNotice: '邀请已发给他：他打开专注 APP 就能一键躺下'\n    };\n  });\n  /* 6) 角色主动解除看守锁 */\n  API.tools.handle('focusUnlock', async (args, ctx) => {\n    await ensureBasics();\n    const cid = (ctx && ctx.characterId) || (args && args.characterId) || anyCharId();\n    const reason = String((args && args.reason) || '角色判断继续锁下去不合适').slice(0, 160);\n    const running = !!(S.session && S.session.status === 'running');\n    await forceUnlock(reason, { silent: true });\n    if (cid) await syncTimeline(cid, `角色解除了看守锁：${reason}`, 'focus_unlock', {});\n    return {\n      success: true,\n      data: { unlocked: true, wasRunning: running },\n      userNotice: running ? '专注已结束，看守锁和勿扰都解除了' : '看守锁已解除',\n    };\n  });\n  /* 7) 角色判定通行证查岗结果：pass +2；violation 收回通行证并 -10 */\n  API.tools.handle('passVerdict', async (args, ctx) => {\n    await ensureBasics();\n    const cid = (ctx && ctx.characterId) || (args && args.characterId) || anyCharId();\n    const verdict = String((args && args.verdict) || '').toLowerCase() === 'violation' ? 'violation' : 'pass';\n    const appName = String((args && args.app) || '').trim().toLowerCase();\n    const active = (S.wlPasses || []).filter(p => p.status === 'active');\n    const pass = (appName\n      ? active.find(p => {\n          const name = String(p.app || '').toLowerCase();\n          return name === appName || name.indexOf(appName) >= 0 || appName.indexOf(name) >= 0;\n        })\n      : null)\n      || active.slice().sort((a, b) => (Number(b.issuedAt) || 0) - (Number(a.issuedAt) || 0))[0];\n    if (!pass) {\n      return { success: false, error: '现在没有生效中的通行证，无法判定。', userNotice: '没有可判定的通行证' };\n    }\n    if (pass.verdict) {\n      return { success: true, data: { passId: pass.id, app: pass.app, verdict: pass.verdict, skipped: true }, userNotice: '这次查岗已经判定过了' };\n    }\n    const reason = String((args && args.reason) || '').slice(0, 200);\n    if (verdict === 'pass') {\n      pass.checkedAt = Date.now();\n      pass.verdict = 'pass';\n      pass.verdictAt = Date.now();\n      if (pass.dbId) await DB.update(T.WLP, pass.dbId, JSON.parse(JSON.stringify(pass)));\n      await wlTrustAdd(2, '查岗通过（' + pass.app + '）' + (reason ? '：' + reason : ''));\n      if (cid) await syncTimeline(cid, `通行证（${pass.app}）查岗通过：${reason || '画面合规'}`, 'wl_checkin_pass', {});\n      render();\n      return { success: true, data: { passId: pass.id, app: pass.app, verdict: 'pass' }, userNotice: '查岗通过，信任分 +2' };\n    }\n    pass.status = 'revoked';\n    pass.violatedAt = Date.now();\n    pass.verdict = 'violation';\n    pass.verdictAt = Date.now();\n    if (pass.dbId) await DB.update(T.WLP, pass.dbId, JSON.parse(JSON.stringify(pass)));\n    cancelWlCheckinNative(pass.id);\n    await wlTrustAdd(-10, '查岗违规（' + pass.app + '）' + (reason ? '：' + reason : ''));\n    if (cid) await syncTimeline(cid, `通行证（${pass.app}）查岗违规，已收回：${reason || '画面不合规'}`, 'wl_checkin_violation', {});\n    syncLockNow();\n    render();\n    return { success: true, data: { passId: pass.id, app: pass.app, verdict: 'violation' }, userNotice: '查岗违规：通行证已收回，信任分 -10' };\n  });\n}\nfunction startInviteListener() {\n  if (!API || !API.on || S.inviteListenerOn) return;\n  S.inviteListenerOn = true;\n  try {\n    API.on('chat.message.created', async (payload) => {\n      try {\n        const msg = (payload && payload.message) || null;\n        if (!msg || msg.role !== 'assistant') return;\n        const text = String(msg.content || msg.text || '');\n        if (!text || (text.indexOf('陪睡') < 0 && text.indexOf('约专注') < 0)) return;\n        await ensureBasics();\n        const cid = payload.characterId || msg.characterId || '';\n        /* 角色写卡：格式很活（英文/中文方括号、冒号/逗号/顿号分隔），\n           统一交给 parseInviteDirectives 理解，不再靠一条死正则硬匹配。 */\n        const dirs = parseInviteDirectives(text);\n        for (const d of dirs) {\n          if (d.kind === 'sleep') {\n            /* 同一角色、同一睡法/时长在 24 小时内已有邀请就不再重复建；\n               宿主会在生成聊天卡时先拦一次，这里是对旧卡/补录的兜底。 */\n            const sameSleep = (S.invites || []).find(x => x && x.kind === 'sleep'\n              && x.status !== 'replaced' && x.status !== 'dismissed'\n              && String(x.charId) === String(cid)\n              && String(x.mode || '') === String(d.mode || '')\n              && Number(x.minutes || 0) === Number(d.minutes || 0)\n              && Date.now() - Number(x.at || 0) < 24 * 60 * 60000);\n            if (sameSleep) continue;\n            await pushInvite({ kind: 'sleep', mode: d.mode, minutes: d.minutes, note: d.note, charId: cid, at: Date.now(), status: 'new', from: 'directive' });\n            if (cid) await syncTimeline(cid, `你写卡邀用户一起${d.mode}（${d.minutes || '不定时'} 分钟）：${d.note || '（没留言）'}`, 'sleep_invite', {});\n            continue;\n          }\n          const hmStr = String(d.time || '').replace('：', ':');\n          const ps = hmStr.split(':').map(Number);\n          if (!ps.length || isNaN(ps[0])) continue;\n          const hh2 = clamp(ps[0] || 0, 0, 23), mi2 = clamp(ps[1] || 0, 0, 59);\n          const dt2 = new Date(); dt2.setHours(hh2, mi2, 0, 0);\n          if (dt2.getTime() - Date.now() < 60000) {\n            const sameNow = (S.invites || []).find(x => x && x.kind === 'focus'\n              && x.status !== 'replaced' && x.status !== 'dismissed'\n              && String(x.charId) === String(cid)\n              && String(x.time || '') === hmStr\n              && Date.now() - Number(x.at || 0) < 24 * 60 * 60000);\n            if (sameNow) continue;\n            await pushInvite({ kind: 'focus', task: d.task, minutes: d.minutes, time: hmStr, note: '', charId: cid, apptId: '', at: Date.now(), status: 'new', from: 'directive' });\n            if (cid) await syncTimeline(cid, `你写卡约用户现在就一起专注 ${d.minutes} 分钟：${d.task}。`, 'appt_invite', {});\n          } else {\n            /* 同一角色、同一开始时间已经有待开始的预约时，不再建第二条；\n               否则后面每次聊到这件事都会多一条同时间预约和一张同时间卡。 */\n            const sameAppt = (S.appts || []).find(a => a && a.status === 'pending'\n              && Number(a.startAt) === dt2.getTime()\n              && (!cid || (Array.isArray(a.charIds) ? a.charIds : []).indexOf(cid) >= 0));\n            if (sameAppt) continue;\n            const rec = {\n              id: '', date: dkey(dt2), time: pad2(hh2) + ':' + pad2(mi2), startAt: dt2.getTime(),\n              minutes: d.minutes, task: String(d.task || '').slice(0, 60), charIds: cid ? [cid] : [],\n              status: 'pending', nudgeCount: 0, createdAt: Date.now(), note: '由角色在聊天里约的'\n            };\n            await createAppt(rec);\n            await scheduleAppt(rec);\n            await pushInvite({ kind: 'focus', task: d.task, minutes: d.minutes, time: rec.date + ' ' + rec.time, note: '', charId: cid, apptId: rec.id, at: Date.now(), status: 'new', from: 'directive' });\n            if (cid) await syncTimeline(cid, `你和用户约好 ${rec.date} ${rec.time} 一起专注 ${d.minutes} 分钟：${d.task}。到点前你要来催他开始。`, 'appt_make', {});\n          }\n        }\n      } catch (e) { console.warn('directive listener', e); }\n    });\n  } catch (e) { console.warn('startInviteListener', e); }\n}\n/* ---------- 启动自检：万一哪一段漏搬了，直接在首页写出来（不白屏、不硬猜） ---------- */\nfunction selfCheckMissing() {\n  const miss = [];\n  const needViews = ['home', 'sleep', 'stats', 'me', 'setup', 'running', 'review', 'reward', 'weak', 'story',\n    'alarm', 'roles', 'qbank', 'mistakes', 'gifts', 'ledger', 'calendar', 'help', 'album', 'unlockquiz',\n    'rewards', 'sleepreport', 'prompts', 'genlog', 'fav', 'appt', 'bond', 'coin', 'goals', 'periodrep',\n    'trend', 'invite', 'todos', 'invites', 'bottle', 'rcchat'];\n  needViews.forEach(k => { if (typeof VIEWS[k] !== 'function') miss.push('VIEWS.' + k); });\n  const needActs = ['openInvite', 'inviteSend', 'inviteBook', 'inviteAcceptCard', 'inviteDismissCard', 'inviteBackfill', 'inviteDiag', 'inviteReschedule', 'apptNew', 'apptStart', 'wishGen', 'coinBuy',\n    'genPeriod', 'trendExplain', 'morningSave', 'exportData', 'importData', 'permCheck', 'todoAdd',\n    'inviteAccept', 'planFromTodos', 'startFocus', 'gradeNow', 'openLock', 'useFreePass',\n    'noteOpen', 'noteSend', 'noteDel', 'noteReplay', 'noteToChat', 'genReplay', 'genLoopOne',\n    'noteOpenItem', 'noteToggleAll',\n    'genLoopRecent', 'voiceLoopStop', 'bankAddToggle', 'msgReplay', 'msgLoop', 'msgLoopAll', 'msgLoopAllStop',\n    'rcChatStart', 'rcChatSend', 'rcChatSkip', 'rcChatHint', 'rcChatStop', 'rcChatAgain', 'rcAiPetOpen'];\n  needActs.forEach(k => { if (typeof ACTIONS[k] !== 'function') miss.push('ACTIONS.' + k); });\n  ['noteFly', 'startSleep', 'startSession', 'genSleepReport', 'registerTools', 'startInviteListener', 'pushInvite',\n    'ensureCardInvite', 'parseInviteDirectives', 'inviteOutcome',\n    'rcStartSession', 'rcBuildQueue', 'rcWeightedShuffle', 'rcMatchAnswer', 'rcKeywords',\n    'rcBubble', 'rcOnTimeout', 'rcStartTimer', 'rcFinishSession', 'rcParseImport',\n    'pushTodo', 'todosHTML', 'invitesHTML', 'statBriefOf', 'saveAlbum', 'saveImageAnywhere', 'playVoiceRefOnce',\n    'promptText', 'pGen', 'loadAll', 'render', 'go', 'toast', 'confirmBox', 'openSheet',\n    'voiceGap', 'voiceLogs', 'msgVoiceRef', 'msgVoiceBarHTML', 'msgHTML', 'msgLoopAllRefs',\n    'msgLoopSrc', 'msgLoopAllRun', 'attachRefToMsg', 'refreshMsgVoice', 'renderKeepChat'].forEach(k => {\n      if (typeof window[k] !== 'function' && typeof (window[k]) !== 'function') {\n        try { if (typeof eval(k) !== 'function') miss.push(k); } catch (e) { miss.push(k); }\n      }\n    });\n  return miss;\n}\nboot();   /* v1.9.2：唯一入口，只会执行一次 */\nif (typeof window !== 'undefined') {\n  window.__focusSelfCheck = selfCheckMissing;\n  setTimeout(() => {\n    try {\n      const miss = selfCheckMissing();\n      const v = document.getElementById('view');\n      if (!miss.length || !v) return;\n      v.insertAdjacentHTML('afterbegin', '<div class=\"card\" style=\"border-color:rgba(255,123,138,.6);background:rgba(255,123,138,.1)\">'\n        + '<h3 style=\"color:#ff9aa6\">⚠️ 有 ' + miss.length + ' 个组件没装进来</h3>'\n        + '<div class=\"tiny\" style=\"line-height:1.7\">把这一屏截图发给小坊，我能立刻定位是哪一段漏了。你的记录都还在，不会因此丢失。</div>'\n        + '<div class=\"tiny\" style=\"margin-top:8px;white-space:pre-wrap;word-break:break-all\">' + miss.join('、') + '</div></div>');\n    } catch (e) { }\n  }, 2600);\n}\n</script>\n</body>\n</html>",
].join("");
